INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('一', 'yī', '1', '一', NULL, NULL, '一 (指事。一”是汉字部首之一。本义数词。大写作壹”。最小的正整数。常用以表示人或事、物的最少数量)', '小学', '1'),
    ('丁', 'dīng', '2', '一', '独体', NULL, '丁 (象形。金文象俯视所见的钉头之形,小篆象侧视的钉形。本义钉子) 同本义。丁为钉”的古字 丁,钻也。象形。今俗以钉为之,其质用金或竹,若木。；组词：丁屐(底有钉齿的木鞋)；丁子(蝌蚪', '小学', '1'),
    ('七', 'qī', '2', '一', NULL, NULL, '七〈数〉 (指事。从一ㄣ。画以纪数。本义六加一的和) 同本义 七,阳之正也。从一,微阴从中斜出也。；组词：七宝(佛经上指金、银、琉璃、砗磲、玛璃、珍珠、玫瑰)；七出(旧指休妻的七种理由无子,淫泆报会,不事舅姑,口舌,盗窃,妒忌', '小学', '1'),
    ('万', 'wàn', '3', '一', NULL, NULL, '万 (形声。萬”,甲骨文呈蝎子形。本义蝎) 虫名。蝎。 万,虫也。--《说文》 今日俸钱过十万,与君营奠复营斋。--唐·元稹《遣悲怀》；组词：万寿(称皇帝、皇后的生日)；万劫(即万世', '小学', '1'),
    ('丈', 'zhàng', '3', '一', NULL, NULL, '丈 (会意。小篆字形。从又(手)持十”。十,十尺。本义长度单位,十尺) 同本义 丈,十尺也。；组词：丈尺(以丈、尺为单位来计量)；丈六(一丈六尺)；丈二(一丈二尺)；丈数(一丈多；丈把) 丈 古时对长辈男子的尊称 丈zh', '小学', '1'),
    ('三', 'sān', '3', '一', '上下', NULL, '三〈数〉 (指事。本义数目。二加一的和) 同本义 三,天地人之道也。从三数。--《说文》 三,数名。--《广韵》 二与一为三。--《庄子·齐物论》 一生二,二生三,三生万物；组词：三叉(三歧的道路)；三木(古时套在犯人颈、手、足上的刑具)；三节(农历二月一日中和节、三月三上巳节、九 三sān 1.数', '小学', '1'),
    ('上', 'shàng', '3', '一', '上下', NULL, '上〈名〉 (指事。小篆字形。下面的一”表示位置的界线,线上一短横表示在上面的意思。本义高处;上面)；组词：上荣(飞檐', '小学', '1'),
    ('下', 'xià', '3', '一', '上下', NULL, '下 (指事。据甲骨文,上面部分表示位置的界限,下面部分表示在下的意思。本义下面,位置在下)；组词：下元(道教指水中或水府)；下溜头(下流头', '小学', '1'),
    ('不', 'bù', '4', '一', NULL, NULL, '不 (象形。甲骨文字形,上面象花蒂的子房,下面象花蕊下垂形。1本义萼足。《诗·小雅·常棣》常棣之花,鄂不韡。”郑笺承华者曰鄂。”2副词。不。《荀子》锲 而不舍,金石可镂；组词：不会；不大；不一定；不古(不古朴', '小学', '1'),
    ('与', 'yǔ', '3', '一', NULL, NULL, '与 (会意。小篆字形,一、勺”合起来,表示赐予别人东西。與”,从与,从舁(鉹??),共同抬起,与,给予∠起来表偕同、朋友。本义赐予,施予,给予)；组词：赠与(赠给)；交与(交给)；与人方便；与受同科(行贿和受贿的人 与(與)yǔ 1.跟,同,和~众不同', '小学', '1'),
    ('丐', 'gài', '4', '一', NULL, NULL, '丐 乞求,乞讨 求愿曰匃。--《通俗文》 匃,求也。--《广雅》 不强丐。--《左传·昭公六年》 毋或匄夺。--《左传·昭公十六年》 丐沐沐我。--《史记·外戚世家》 丐,乞也；组词：丐饭；丐物；丐食；丐计(乞求计策)；丐施(乞求布施)；丐贷(乞贷)；丐养(给人收养为义子) 求,请求 邹君海滨,以所辑黄', '小学', '1'),
    ('丑', 'chǒu', '4', '一', NULL, NULL, '丑 (形声。从鬼,酉声。古人以为鬼的面貌最丑,故从鬼。本义貌丑。按在古代,醜”和丑”是两个字,意义各不相同,除作地支和时辰用丑”以外,都不能写作丑”；组词：丑名(恶名)；丑言(恶劣的话)；丑攀谈(说粗俗话)；丑徒(恶徒)；丑语(恶劣的话', '小学', '1'),
    ('专', 'zhuān', '4', '一', NULL, NULL, '专 (会意兼形声。甲骨文字形,右边象纺塼形,即叀;左边是手(寸),合起来为用手纺织。叀”兼作声符。本义纺锤) 纺专,收丝器 专,纺专。', '小学', '1'),
    ('且', 'qiě', '5', '一', '上下', NULL, '且 此,这;今 匪且有且,匪今斯今。--《诗·周颂·载芟》。毛传且,此也。” 且 将近;几乎 年且九十。--《列子·汤问》 上晚年多内宠,小王且二十人', '小学', '1'),
    ('世', 'shì', '5', '一', NULL, NULL, '世 (指事。金文字形。古人以三十年为一世。止”上加三个圆点,表三十年;止,到此为止。本义三十年)', '小学', '1'),
    ('丘', 'qiū', '5', '丿', '上下', NULL, '丘 (会意兼指事。甲骨文字形,象地面上并立两个小土峰。本义自然形成的小土山) 同本义 丘,土之高也。非人所为也。从北,从一。一,地也。人居在丘南,故从北。', '小学', '1'),
    ('丙', 'bǐng', '5', '一', '上下', NULL, '丙 (象形。本义鱼尾。《尔雅·释鱼》曰‘鱼枕谓之丁,鱼肠谓之乙,鱼尾谓之丙’。乙之象鱼肠,丙之象鱼尾,可无庸说。”) 鱼尾 鱼尾谓之丙。；组词：丙向(南向,即朝南) 五行 丙 bǐng天干的第三位', '小学', '1'),
    ('业', 'yè', '5', '业', NULL, NULL, '业 (象形。从乹,从巾丛生草。巾象版。本义古时乐器架子横木上的大版,刻如锯齿状,用来悬挂钟磬) 版,大版 古代覆在悬挂钟、鼓等乐器架横木上的装饰物,刻如锯齿形,涂以白色 榠', '小学', '1'),
    ('丛', 'cóng', '5', '一', '上下', NULL, '丛 (会意。从乹,取声。乹”,意思是丛生草”。本义聚集) 同本义 丛,聚也。--《说文》 其植物宜丛物。--《周礼·大司徒》 树木丛生,百草丰茂。--曹操《观沧海》；组词：丛物(聚生于一处的植物)；丛灌(丛生的灌木)；丛丛(聚集的样子)；丛育(聚集生长)；丛毛(丛生的草)；丛森(树木繁茂幽深', '小学', '1'),
    ('东', 'dōng', '5', '一', NULL, NULL, '东 (会意。从木,官溥说,从日在木中。本义东方,日出的方向) 同本义 东,动也。--《说文》 东方者,动方也,万物始动生也。--《白虎通·五行》 东方木也。--《淮南子·天文训》；组词：关东；旭日东升；东夏(指中国东部)；东朝(东宫)；东极(东方边远之处)；东君(神话中与西王母相对的东王公)；东坦(女婿)', '小学', '1'),
    ('丝', 'sī', '5', '一', NULL, NULL, '丝 (会意。从二糸。糸,细丝。本义蚕丝) 同本义 丝,蚕所吐也。--《说文》。段注凡蚕者为丝、麻者为缕。” 素丝五总。--《诗·召南·羔羊》 金石丝竹,乐之器也。谓弦也；组词：丝棉；丝网；丝缰(丝制的马缰绳)；丝人(治理蚕丝 丝(絲)sī 1.蚕吐出的纤维', '小学', '1'),
    ('丢', 'diu', '6', '一', '上下', NULL, '丢 丢失;遗失 抛弃;撇开 用眼色暗示 搁置 遗留 我一生是个无用的人,一块土也不曾丢给你们。', '小学', '1'),
    ('两', 'liǎng', '7', '一', '上下', NULL, '两 (会意。从一,兩平分。兩亦声。本义二十四铢为一两) 同本义 两,二十四铢为一两。--《说文》 衡权...本起于黄钟之重。一龠容千二百黍,重十二铢,两之为两,二十四铢为两', '小学', '1'),
    ('严', 'yán', '7', '一', NULL, NULL, '严 同本义 事严,虞不敢请。--《孟子·公孙丑下》 又如严急(犹危急;紧急);严行(急行);严鼓(急鼓,急促的鼓声) 严厉;严肃 诛严不为戾。--《韩非子·五蠹》 严限追比；组词：严急(犹危急；紧急)；严行(急行)；严鼓(急鼓,急促的鼓声) 严厉；严肃 诛严不为戾', '小学', '1'),
    ('丧', 'sàng', '8', '一', NULL, NULL, '丧 (会意。小篆字形,上面是哭’,下面是亡”。表示哭已死去的人。本义丧失) 同本义 喪,亡也。；组词：丧明(眼睛失明)；丧检(丧失德行,失去检点)；丧履(失去庇护)；丧精(失神)；丧心(心理反常；丧失理智)；丧志(丧失心志', '小学', '1'),
    ('个', 'gè', '3', '丨', '上下', NULL, '个 通用个体量词,表示单独的人或物 个,枚也。--《集韵》 俎释三个。--《仪礼·士虞礼》 竹竿万个。--《史记·货殖列传》。正义竹曰个,木曰枚。” 字亦作箇” 箇,箇数,又枚也', '小学', '1'),
    ('中', 'zhōng', '4', '丨', NULL, NULL, '中 (指事。甲骨文字形,中象旗杆,上下有旌旗和飘带,旗杆正中竖立。本义中心;当中,指一定范围内部适中的位置)；组词：人中(人 中zhòng 1.符合,适合,正着,正对上~意', '小学', '1'),
    ('丰', 'fēng', '4', '丨', NULL, NULL, '丰 (象形。甲骨文字形,上面象一器物盛有玉形,下面是豆”(古代盛器)。故豷”本是盛有贵重物品的礼器。这由豱”字可以得到证明。古文豷与豱”是同一个字,《说文 》豱,行礼之器也', '小学', '1'),
    ('串', 'chuàn', '7', '丨', NULL, NULL, '串 chuan 将物品连贯在一起。亦指连贯而成的物品 勾结 交错连接 走;到别人家走动 担任戏曲角色 串 穿在绳上的一组东西,尤指穿满的一串 串 chuàn 1连贯~讲。 2量词', '小学', '1'),
    ('临', 'lín', '9', '丨', NULL, NULL, '临 (会意。金文字形,右边是人,左上角象人的眼睛,左下角象众多的器物。整个字形象人俯视器物的样子。本义从高处往低处察看)；组词：居高临下；如临深渊；临轩(在殿前平台上接见臣属)；临下(从高望下)；临见(居上视下看见) 引申为从上监视着 临长晋国者', '小学', '1'),
    ('丸', 'wán', '3', '丿', NULL, NULL, '丸 (形声。反体指事。小篆是仄的反写。本义小而圆的物体) 同本义 丸,圜也。--《说文》 五六月累丸二不坠。--《庄子·达生》 市南宜僚弄丸。--《庄子·徐无鬼》 首衔铜丸；组词：鱼丸；肉丸；丸熊(形容母善教子', '小学', '1'),
    ('丹', 'dān', '4', '丶', NULL, NULL, '丹 (象形。甲骨文字形,外面框框象矿井形,里边的一横是加上的符号,表示那里有丹砂。本义辰砂,朱砂)；组词：丹矸(丹砂)；丹砂(一种红色矿物,也叫朱砂”)；丹砾(矿物之丹砂,可为药用)；丹铅(丹砂和铅粉,是古人校勘文字的用具)', '小学', '1'),
    ('为', 'wéi', '4', '丶', NULL, NULL, '为 (爲的本义是母猴。象形。按字,从爪,古文下象两母猴相对形) 假借为伪”。做,作,干,搞 我生之初,尚无为。', '小学', '1'),
    ('主', 'zhǔ', '5', '丶', '上下', NULL, '主 (象形。甲骨文字形,象点燃的火把。下面是木材。主”是炷”的本字。小篆字形从上往下依次为火焰、油盏、灯台、灯座。本义灯心)；组词：主驾(君主的车驾)；主道(君主治国之 主zhǔ 1.最重要的,最基本的,事物的根本~力', '小学', '1'),
    ('丽', 'lì', '7', '丶', '上下', NULL, '丽 通罹”。遭遇;落入 鱼丽于羢。--《诗·小雅·鱼丽》 丽水 丽 (形声。从鹿,丽声。其字本作丽”,后加鹿”,成为形声字。鹿形丽声,鹿成对,并驾。本义成群;结伴', '小学', '1'),
    ('举', 'jǔ', '9', '丶', '上下', NULL, '举 (形声。小篆字形,从手,舉声。本义双手托物) 同本义 举,对举也。--《说文》 举,擎也。--《广韵》 其坚不能自举也。--《庄子·逍遥游》 举所佩玉玦；组词：举桉(桉同案”', '小学', '1'),
    ('乃', 'nǎi', '2', '丿', NULL, NULL, '乃 你,你的 余嘉乃勋。--《左传·僖公十二年》 几败乃公事。--《汉书·高帝纪上》 谁谓乃公勇者?--《史记·淮南衡山传》 王师北定中原日,家祭无忘告乃翁(父亲)；组词：乃父(乃翁', '小学', '1'),
    ('久', 'jiǔ', '3', '丿', NULL, NULL, '久 灸灼。灸”的古字 其腹有久故瘢二所。--《睡虎地秦墓竹简》 久,以后灸之,象人两胫后有距也。--《说文》 皆木桁,久之。--《仪礼·既夕礼》。注当为灸', '小学', '1'),
    ('么', 'me', '3', '丿', '上下', NULL, '么 me 用作某些词的后缀。如什么;怎么;多么 么 用作歌词中的衬字。如五月的花儿,红呀么红似火 么 ma 用在句末,表示疑问或反诘的语气 先生,你会看喉咙吗?；组词：幺微(微小)；幺店(幺店子', '小学', '1'),
    ('义', 'yì', '3', '丶', NULL, NULL, '义 (会意。从我,从羊。我”是兵器,又表仪仗;羊”表祭牲。本义正义;合宜的道德、行为或道理)；组词：丈义(主持正义)；义断恩绝(恩情道义断绝)；义不容辞(道义上不容推辞) 情谊 义(義)yì 1.公正合宜的道德、道理或行', '小学', '1'),
    ('之', 'zhī', '3', '丿', NULL, NULL, '之 (会意。象苃过屮。枝茎益大。本义出,生出,滋长) 同本义 之,出也。象苃过屮,枝茎益大有所之,一者,地也。；组词：之如(前往)；之往(去；之zhī 1.到,往由京~川', '小学', '1'),
    ('乌', 'wū', '4', '丿', NULL, NULL, '乌 (象形。本义鸟名,乌鸦) 同本义 燕雀乌鹊。--《楚辞·屈原·涉江》 又如乌鸟(乌鸦之属);乌鸢(乌鸦和老鹰);乌鹊(乌鸦和喜鹊);乌师(在妓院教唱或伴奏的乐师)；组词：乌鸟(乌鸦之属)；乌鸢(乌鸦和老鹰)；乌鹊(乌鸦和喜鹊)；乌师(在妓院教唱或伴奏的乐师)；乌鸦嘴(比喻说话讨厌的人) 古', '小学', '1'),
    ('乍', 'zhà', '5', '丿', NULL, NULL, '乍 (会意。小篆字形,从亡从一。本义忽然) 同本义 乍,暂也。--《广雅》 今人乍见孺子。--《孟子》 银瓶乍破。--唐·白居易《琵琶行(并序)》 雷霆乍惊；组词：离乍(分离很骤然)；乍乍(忽然)；江上渔火乍明乍灭；乍冷乍热,天气很不正常 刚；才 波色乍明', '小学', '1'),
    ('乎', 'hū', '5', '丿', NULL, NULL, '乎〈动〉 (会意。甲骨文字形,上面的符号表示声音上扬,下面的符号表示舒气。乎”是呼”的本字。当乎”借作语气词、介词用之后,就另造了一个从口”的形声字呼”。本义 吐气)', '小学', '1'),
    ('乏', 'fá', '4', '丿', '上下', NULL, '乏〈名〉 古代射礼唱靶者用以避箭的器具,其形略似屏风 乏,春秋传曰,反正为乏。--《说文》。按,容也。从反正,推事。受矢者为正,避矢者为乏。 故文反正为乏', '小学', '1'),
    ('乐', 'lè', '5', '丿', NULL, NULL, '乐 喜悦;愉快 有朋自远方来,不亦乐乎。--《论语·学而》 并怡然自乐。--晋·陶渊明《桃花源记》 游人去而禽鸟乐也。--欧阳修《醉翁亭记》 君游海而乐之；组词：快乐(感到幸福或满意)；乐嬉嬉(喜悦貌)；乐悦(欢喜)；乐笑(欢笑)；乐胥(喜乐)；乐哈哈(形容喜笑的样子)；乐好(爱好', '小学', '1'),
    ('乒', 'pīng', '6', '丿', '上下', NULL, '乒〈象〉 好像枪弹击中金属障碍物时的尖锐声 乒 〈名〉 乒乓球的简称 乒pīng 1.像声词~~~乱响。 2."乒乓球"的简称~坛。~队。', '小学', '1'),
    ('乓', 'pāng', '6', '丿', '上下', NULL, '乓〈象〉 突然的强烈的响声。形容枪声、关门声、东西砸破声等 乓pāng像声词~ ~两声。', '小学', '1'),
    ('乔', 'qiáo', '6', '丿', NULL, NULL, '乔 (会意。从夭,从高省,高亦声。夭,象人(大)行走的样子。本义高) 高耸。多用以形容树木 乔,高而曲也。；组词：乔木世家(指贵族世家', '小学', '1'),
    ('乖', 'guāi', '8', '丿', NULL, NULL, '乖 (会意。小篆字形,象羊角形,从北”。从北”,取其分背的意思。本义背离,违背,不和谐)；组词：乖礼(违背成礼、定制)；乖角(违背抵触)；乖 乖guāi 1.孤僻,违背,不协调~僻', '小学', '1'),
    ('乘', 'chéng', '10', '丿', NULL, NULL, '乘 cheng (会意。甲骨文字形,从大(人)从木,表示人爬在树上。大”象人”正面。本义登,升)；组词：乘槎(神话中指乘木排上天)；乘城(登城；守城)；乘屋(登上屋顶) 骑；坐 昔人已乘黄鹤去,此地空余黄鹤楼', '小学', '1'),
    ('乙', 'yǐ', '1', '乙', NULL, NULL, '乙 (象形。甲骨文字形。本义象植物屈曲生长的样子) 同本义 乙,草木冤曲而出也。象形。--《说文》 乙者,物蕃屈有节欲出。--《白虎通》 思乙乙其若抽。--陆机《文赋》。注抽也；组词：乙乙(难出之貌) 第二,次一等 乙 天干的第二位,与地支相配,用以纪年、月、日 其日甲乙', '小学', '1'),
    ('九', 'jiǔ', '2', '丿', NULL, NULL, '九 (指事。本义数词。比八大一的基数) 同本义 古人造字以纪数,起于一,极于九,皆指事也。二三四为积画,余皆变化其体。--朱骏声《说文通训定声》 乾玄用九,乃见天则。；组词：九伯(宋时把痴傻人叫九伯', '小学', '1'),
    ('乞', 'qǐ', '3', '乙', NULL, NULL, '乞〈动〉 (象形。《说文》本作气”,借云气字表示乞求义。本义向人求讨) 同本义 乞,谓行匄也。；组词：乞化(乞讨；化缘)；乞言(求取可行的善言)；乞邻(向邻人求取)；乞粮(求人济助粮食)；乞活(到有粮之地就食求生)；乞募(', '小学', '1'),
    ('也', 'yě', '3', '乙', NULL, NULL, '也 亦表示同样 叠用,强调两事并列或对等 表示转折或让步 表示委婉。如我也只好如此 表示强调 表示选择,还是 你见我府里那个门子,却是多少年纪?或是黑瘦也白净肥胖?；组词：也是(还是) 也 语气 用在句末表示判断或肯定语气', '小学', '1'),
    ('习', 'xí', '3', '乙', NULL, NULL, '习 (会意。从羽 。从羽,与鸟飞有关。本义小鸟反复地试飞) 同本义 習,数飞也。--《说文》 鹰乃学习。--《礼记·月令》 习习笼中鸟,举翮触四隅。--晋·左思《咏史》 反覆练习；组词：习容(练习举止,整饬仪表)；习肄(犹练习)；习战(练习作战)；习非胜是(对错 习(習)xí 1.鸟屡次拍着翅膀飞鹰乃学~', '小学', '1'),
    ('乡', 'xiāng', '3', '乙', '独体', NULL, '乡 (会意。据甲骨文,像二人对食形。‘鄉’和‘饗’原本是一字...整个字像两个人相向对坐,共食一簋的情状。本义是用酒食款待别人,是饗”的古字) 乡”假借为行政区域名 乡', '小学', '1'),
    ('书', 'shū', '4', '乛', NULL, NULL, '书 (形声。从聿,者声。聿,即笔。隶书省者”成曰”。《说文》书,箸也。”箸(著)即显明∠起来表示用笔使文字显明,者、箸”音近,故者”有表意作用。本义书 写,记录,记载)', '小学', '1'),
    ('买', 'mǎi', '6', '乙', '上下', NULL, '买 (会意。小篆字形,从网贝。网”是收进,贝”是财货∠起来表示把财货购进来。本义买进,购进)；组词：买嘴吃(买零食吃)；买市(旧市官方或豪绅定期召集商贩开市,以买卖财物为名,犒赏百姓)；买山(购置山地,作为隐居之处)；买', '小学', '1'),
    ('乱', 'luàn', '7', '乙', '左右', NULL, '乱 (会意。金文字形,象上下两手在整理架子上散乱的丝。是乱”的本字。本义理丝) 同本义 人以一手持丝,又一手持互以收之,丝易乱,以互收之,则有条不紊,故字训治训理也；组词：乱政(治理政务；干扰、败坏政治) 扰乱；打乱；使乱 行拂乱其所为', '小学', '1'),
    ('乳', 'rǔ', '8', '乙', '左右', NULL, '乳 (会意。从孚)。甲骨文中象手抱婴儿哺乳形。孚”是以爪抱子哺乳。本义生子,生产 同本义 人及鸟生子曰乳,兽曰产。；组词：乳子(产子；分娩)；乳舍(产房)；乳妇(产妇)；乳卵(产(下)蛋)；乳抱(繁殖) 喂奶 妪,先大母婢也,乳二世', '小学', '1'),
    ('乾', 'qián', '11', '乙', '左右', NULL, '乾〈动〉 (俗作乹。形声。从乙,倝声。乙,象植物屈曲生长的样子。本义上出) 同本义 乾,上出也。', '小学', '1'),
    ('了', 'le', '2', '乙', '上下', NULL, '了〈助〉 le 用在动词或形容词后,表示完成 了 〈语气〉 表示肯定语气 表示促进或劝止 表示感叹语气 了 〈动〉 (象形。从子,无臂。小篆字象婴儿束其两臂形。初生的婴儿', '小学', '1'),
    ('予', 'yǔ', '4', '亅', NULL, NULL, '予〈代〉 予”假借为余”,我 予独爱莲之出淤泥而不染。--宋·周敦颐《爱莲说》 然而累汝至此者,未尝非予之过也。--清·袁枚《祭妹文》；组词：予知(自认为聪明)；予美(自己所爱的人)；予圣(自以为圣人)；予一人(古代帝王的自称)；予小子(古代帝王对先王或长辈的自', '小学', '1'),
    ('争', 'zhēng', '6', '刀', '上下', NULL, '争 (会意。金文字形,上为爪”(手),下为又”(手),中间表示某一物体,象两人争一样东西。从又,义同。本义争夺)', '小学', '1'),
    ('事', 'shì', '8', '亅', NULL, NULL, '事 (形声。从史,之省声。史,掌管文书记录。甲骨文中与吏”同字。本义官职) 同本义 事,职也。；组词：事宦(仕宦', '小学', '1'),
    ('二', 'èr', '2', '二', '上下', NULL, '二 (会意。古文字二用两横画表示,是原始记数符号) 一加一的和 二,地之数也。从耦一,会意。古文又从弋。；组词：二加四得六；总数为二；二府(大肠和小肠；二太爷)；二形(男女两性)；二难(指难兄难弟,即蔡、宋两御史)；二仪(两仪', '小学', '1'),
    ('于', 'yú', '3', '二', NULL, NULL, '于〈动〉 (象形。甲骨文字形,表示气出受阻而仍越过。本义超过) 往;去 之子于归,宜其室家。；组词：于何(如何) 于 引进动作、行为的时间、处所,意义相当于在”、到”或在...方面(上、中)” 捐金于野', '小学', '1'),
    ('亏', 'kuī', '3', '二', NULL, NULL, '亏 (形声。从亏。本义气损) 同本义 亏,气损也。--《说文》。段注引申凡损皆曰亏。” 又如亏柔(犹虚弱);亏退(衰退止息) 欠缺,短少(应该有的而缺少)。与盈”；组词：亏柔(犹虚弱)；亏退(衰退止息) 欠缺,短少(应该有的而缺少)', '小学', '1'),
    ('云', 'yún', '4', '二', '上下', NULL, '云 (象形。《说文》古文字形。象云回转形。雲”为会意字,从雨,从云。本义云彩。这个意义后作雲”)；组词：云瞑(古乐器名)；云根(山石', '小学', '1'),
    ('互', 'hù', '4', '二', NULL, NULL, '互 (象形。是一种绞绳用的工具。本义绞绳用的工具) 同本义 段玉裁注今绞绳者尚有此器。从竹,象形,谓其物象工字;中象人手推握也。” 差错 各有乘互', '小学', '1'),
    ('五', 'wǔ', '4', '二', NULL, NULL, '五 (五,会意。从二,从乿。二”代表天地,乿”表示互相交错。本义交午,纵横交错) 同本义 五,阴阳在天地之间交午也。；组词：五路总口(通往东、西、南、北、中五路的交叉口)；五车腹笥(腹中 五wǔ 1.数目字~人', '小学', '1'),
    ('井', 'jǐng', '4', '二', NULL, NULL, '井 (象形。金文字形,外象井口,中间一点表示井里有水。本义水井) 同本义 改邑不改井。--《易·井》 井道。--《易·杂卦》传 宿息井树。--《周礼·野庐氏》。注井,共饮食；组词：井池(井口旁储水的小池)；井鱼(井中的鱼', '小学', '1'),
    ('亚', 'yà', '6', '二', '上下', NULL, '亚 (象形。小篆作亞”。许慎认为像人驼背形。甲骨文一说像花边形。本义丑) 同本义 夫地有山有泽,有黑有白,有美有亚。--马王堆汉墓帛书《十六经》 亚,丑也。；组词：亚献(古代 亚(亞)yà 1.次,第二的~热带', '小学', '1'),
    ('些', 'xiē', '8', '二', '上下', NULL, '些 (会意。从此,从二。未详) 细小 雀微贱,身体些小,肌肉瘠瘦,所得盖少。--三国魏·曹植《鹞雀赋》；组词：些子事(指极细小的违背礼法的事情)；些娘(方言', '小学', '1'),
    ('亡', 'wáng', '3', '亠', NULL, NULL, '亡 (会意。小篆字从入,从乚。入”是人字。乚隐蔽∠起来表示人到隐蔽处。本义逃离,出走) 同本义 亡,逃也。；组词：亡归(逃回)；逃亡(逃走在外)；亡虏(逃亡的犯人)；亡民(逃亡 亡wú 1.〈古〉同"无"用之~度,则物力必屈(屈jué', '小学', '1'),
    ('交', 'jiāo', '6', '亠', '上下', NULL, '交 (象形。小篆字形,象人两腿交叉形。本义交叉) 脚胫相交 交,交胫也。--《说文》 交足而待。--《战国策·秦策》 雕题交趾。--《礼记·王制》；组词：交趾(古郡名『置,地处五岭以南一带', '小学', '1'),
    ('亥', 'hài', '6', '亠', NULL, NULL, '亥〈名〉 (象形。甲骨文字形,与豕”的写法相似,象猪形。古代亥”与豕”很容易写混,成语鲁鱼亥豕”讲的就是这种误写现象。本义猪)', '小学', '1'),
    ('亦', 'yì', '6', '亠', NULL, NULL, '亦 (指事。甲骨文字形,在大”(人)旁加两点,指示两腋所在。腋”的本字。本义人腋窝) 同本义 亦,人之臂亦也。', '小学', '1'),
    ('产', 'chǎn', '6', '亠', '上中下', NULL, '产 (形声。从生,彦省声。本义出生,生育) 同本义 産,生也。--《说文》 百物之产。--《周礼·大宗伯》。注生其种曰产。以天产作阴德,以地产作阳德。”注天产者动物,地产者植物；组词：产子(生孩子)；产育(养育；生育)；产母(产妇) 出产 永州之野产异蛇', '小学', '1'),
    ('亩', 'mǔ', '7', '亠', '上下', NULL, '亩 (形声。小篆字形。从十,从田,久声。十,四方。本义中国土地面积市亩的通称) 同本义,一亩约等于667平方米 畮,六尺为步,百步为畮。秦田二百四十步为畮。畮或从十久。；组词：亩丘(有垄界的丘地)；亩道(古代以国都为中心的大道) 亩(畝)mǔ我国的土地面积单位,一亩为六十平方丈∠6.6667公亩', '小学', '1'),
    ('享', 'xiǎng', '8', '亠', '上中下', NULL, '享 (会意。本作亯”。从高”省,曰”象进献熟物形。本义祭献,上供。用物品进献人,供奉鬼神使其享受)；组词：享厅(供奉祖宗木主或神佛偶像的地方)；享牛(供 享xiǎng 1.受用,满足~受', '小学', '1'),
    ('京', 'jīng', '8', '亠', '上中下', NULL, '京 (象形。甲骨文字形,象筑起的高丘形,上为耸起的尖端。本义人工筑起的高土堆) 同本义 京,人所为绝京丘也。；组词：筑京(堆土为小山)；京丘(为战死的人所筑的坟墓', '小学', '1'),
    ('亭', 'tíng', '9', '亠', '上下', NULL, '亭〈名〉 (象形。战国文字字形,其中t”象矗立的亭柱。小篆以为从高省,丁声。本义古代设在路旁的公房,供旅客停宿)', '小学', '1'),
    ('亮', 'liàng', '9', '亠', '上中下', NULL, '亮〈形〉 (《说文》一说本作倞”,后移人”于京”下,又变作儿”,并省去京”中一竖。本义明亮)；组词：亮钟(更楼上报天亮的钟声)；亮隔(亮槅', '小学', '1'),
    ('亲', 'qīn', '9', '亠', '上下', NULL, '亲 (形声。从见,亲声。见”与至”义相通。本义亲爱) 同本义 亲,至也。从見,亲声,字亦作儭。；组词：亲父(生父)；亲爹(亲父)；姑表亲；亲如一家；亲心(亲爱之心；父母爱护子女之心)；亲厚(亲爱并加以厚待) 亲密', '小学', '1'),
    ('人', 'rén', '2', '人', NULL, NULL, '人 (象形。甲骨文字形,象侧面站立的人形。人”是汉字部首之一。本义能制造工具改造自然并使用语言的高等动物)；组词：人王(人中之王)；人满(人多)；人寰(人世)；人欲(人的嗜欲)；人 人rén 1.能制造工具且能使用工具从事劳动的动物~', '小学', '1'),
    ('亿', 'yì', '3', '亻', '左右', NULL, '亿 (形声。左形,右声。本义安宁) 安宁;安定 亿,安也。--《说文》 不能供亿。--《左传·隐公十年》 心亿则乐。--《左传·昭公二十一年》 我盍姑亿吾鬼神；组词：共亿(相安)；亿康(安康)；亿福(安宁幸福) 极多；极大 据亿丈之城', '小学', '1'),
    ('什', 'shí', '4', '亻', '左右', NULL, '什么 shen 表示询问某人、某物或某事的本身或性质 你从那里得到了什么消息 表示询问某物或某事的情况 告诉我你在找什么 虚指', '小学', '1'),
    ('仁', 'rén', '4', '亻', '左右', NULL, '仁 (会意。从人,从二。右边的二是重文。本义博爱,人与人相互亲爱) 中国古代一种含义极广的道德观念。其核心指人与人相互亲爱。孔子以之作为最高的道德标准 仁,亲也。；组词：仁人(有仁德的人)；仁术(施行仁道、仁政 仁rén 1.果核或种子里最内的部分,也指某些硬壳中可吃的部分杏~∷桃~', '小学', '1'),
    ('仅', 'jǐn', '4', '亻', '左右', NULL, '仅〈副〉 (形声。从人,堇声。本义仅能,只能) 同本义 仅,才能也。--《说文》 仅逮是月也。--《公羊传·僖公十六年》 仅然后得兔。 余一人仅亦守府；组词：绝无仅有；仅有二元；仅见他三次；不仅听见它,也看见了它；他仅十岁 仅(僪、廑)jǐn 1.只,不过~供参考', '小学', '1'),
    ('仆', 'pú', '4', '亻', '左右', NULL, '仆〈动〉 向前跌倒 仆,顿也。--《说文》。朱骏声曰前覆曰仆,后仰曰偃。” 仆表决漏。--《史记·司马穰苴传》。索隐卧其表也。” 度水跌仆。--《素问·经脉别论》 卒仆济北；组词：前仆后继；仆然(扑通倒下的样子)；仆顿(精疲力竭而倒仆)；仆僵(跌倒；翻倒) 下坠；倾倒 距洞百余步,有碑仆道,其文漫灭', '小学', '1'),
    ('仇', 'chóu', '4', '亻', '左右', NULL, '仇 (形声。从人,九声。本义匹偶,同伴) 怨恨 仇者,讐也。--《史记·晋世家》 葛伯仇饷。--《孟子》 多仇少与。--《汉书·盖宽饶传》 以先国家之急而后私仇也；组词：仇忌(怨恨憎恶)；仇嫌(怨仇；怨恨) 仇恨 悉以家财求客刺秦王,为韩报仇', '小学', '1'),
    ('今', 'jīn', '4', '人', NULL, NULL, '今 (会意。从佶亼。本义现在) 同本义 今,是时也。--《说文》 今,时辞也。--《苍颉篇》 迨其今兮。--《诗·召南·摽有梅》 于今三年。--《诗·豳风·东山》 吾今召君矣；组词：今 今jīn现在,现代,跟"古"相对~时', '小学', '1'),
    ('介', 'jiè', '4', '人', NULL, NULL, '介 (象形。甲骨文字形,象人身上穿着铠甲形。中间是人,两边的四点象联在一起的铠甲片。本义铠甲。一种用来防身的武器)；组词：介士(穿着甲胄的兵士)；介卒(甲兵)；介胄(铠甲与头盔、披甲戴盔)；介人(武士,甲士)；介马(披甲的战马) 疆界；界限◇', '小学', '1'),
    ('仍', 'réng', '4', '亻', '左右', NULL, '仍 (形声。从人,乃声。本义因袭,依旧) 同本义 仍,因也。--《说文》 彫玉仍几。--《书·顾命》 仍旧贯。--《论语·先进》 据行事,仍人道。--《汉书·艺文志》 天灾仍重；组词：仍复(仍然；依旧)；仍前(仍按先前；照旧)；仍了旧贯(做了过去的事)；一仍其旧；仍几(保留原样的几案) 接续；连续 夫吉', '小学', '1'),
    ('从', 'cóng', '4', '人', '左右', NULL, '从 (会意。甲骨文字形,象二人相从形。本义随行,跟随) 同本义 従,随行也。--《说文》 客从拜辱于朝。--《周礼·司仪》 或从王事。--《易·坤》 啬人不从；组词：从龙(随从帝王创业开国)；从学(跟随受学)；从骑(骑马随从的人)；从嫁(陪嫁的侍婢)；从井救人(跟着跳下井去营救落井者)', '小学', '1'),
    ('仑', 'lún', '4', '人', '上下', NULL, '仑 思 仑,思也。--《说文》 自我反省检讨 浙江令人自反省者,曰肚里仑一仑。--《新方言·释言》 仑 见昆仑” 仑(侖、 2.崙)lún 1.条理,次序。 2. 5.。', '小学', '1'),
    ('仓', 'cāng', '4', '人', '上下', NULL, '仓 (象形。甲骨文字形,上象盖儿,中间象一扇门,下面是进出的口儿,合起来表示仓库这个概念。本义粮仓)；组词：谷仓(粮仓)；仓廒(粮库)；仓敖(储藏米谷的地方) 泛指储藏物资的建筑物 姓 仓 cāng 1收藏谷物的建筑物粮~', '小学', '1'),
    ('仔', 'zǎi', '5', '亻', '左右', NULL, '仔 zai (会意兼形声。从人,从子,子亦声。甲骨文字形,是小孩的意思。本义儿子) 指有某些特征或从事某种职业的年轻人 幼小的动物 仔 zi 任 仔,克也。从人,子声。；组词：仔肩(所肩负的任务；责任) 仔 zi 幼小(多指牲畜、家禽) 仔zī 1. 仔zǐ 1.幼小的(多指家畜家禽)~猪', '小学', '1'),
    ('他', 'tā', '5', '亻', '左右', NULL, '他〈代〉 (本作佗”。形声。从人,它”省声。本义负担) 古代、近代泛指男女及一切事物,现代则用于称代自己和对方以外的男性第三者 某以非他故。；组词：他家(他或她)；他每(他们,他懑)；他爹(他大', '小学', '1'),
    ('仗', 'zhàng', '5', '亻', '左右', NULL, '仗 (形声。从人,丈声。本义执,拿着) 同本义 韩信仗剑从之。--《史记·淮阴侯列传》 独行仗剑至韩。--《史记·刺客列传》；组词：仗斧(手持斧铖钺', '小学', '1'),
    ('付', 'fù', '5', '亻', '左右', NULL, '付〈动〉 (会意。从人,从寸。从寸”,表示与手的动作有关。意思是以手持物交付给别人。本义给予)；组词：付法(传授佛法)；付任(把事情交给别人去做)；付治(交有司治罪)；付推(交付有审问)；付度(移交,交代)；付命(授以天命', '小学', '1'),
    ('仙', 'xiān', '5', '亻', '左右', NULL, '仙 (会意。本作僲”。右边的意思是人爬到高处取鸟巢,加上人”旁,表示人升高成仙。隶书作仙”,表示仙人多住在高处。本义仙人)', '小学', '1'),
    ('代', 'dài', '5', '亻', '左右', NULL, '代 (形声。小篆字形,从人,弋声。本义更迭,代替) 同本义 代,更也。凡以此易彼,以后续前,皆曰代。', '小学', '1'),
    ('令', 'lìng', '5', '人', NULL, NULL, '令〈动〉 听从◇作聆” 故古之圣王,审顺其天而以行欲,则民无不令矣。--《吕氏春秋》 名词。通鸰” 脊令在源,兄弟急难。--《诗·小雅·常棣》。按脊令即鷚鸰 假设语气词 令', '小学', '1'),
    ('以', 'yǐ', '4', '人', NULL, NULL, '以 (象形。甲骨文字形象。金文字形,象人。本义用) 同本义。有一部分现已弱化成了介词 以,用也。；组词：以手代足(爬行', '小学', '1'),
    ('仪', 'yí', '5', '亻', '左右', NULL, '仪 (形声。从人,义声。本义容止仪表) 同本义 令仪令色,小心翼翼。--《诗·大雅》。郑玄笺善威仪,善颜色。” 心质平理,其仪安闲。--《人物志》；组词：仪状(容貌形状)；仪观(容貌威仪)；仪宇(仪容；器量)；仪缀(威仪,外观)；仪止(仪表举止)；仪采(仪表风采)；仪相(仪', '小学', '1'),
    ('们', 'mén', '5', '亻', '左右', NULL, '们 用在代词或指人的名词后面,表示复数。如孩子们 么”的变音字 李逵道这们睡,闷死我也。”', '小学', '1'),
    ('仰', 'yǎng', '6', '亻', '左右', NULL, '仰 (会意兼形声。从人,从卬,卬亦声。卬,小篆字形。一个人站着,一个人跪着,跪者抬头看站者,为抬头仰望的仰”的本字◇借为我”,遂加人”作仰”。卬”仰” 古今字。本义抬头', '小学', '1'),
    ('仲', 'zhòng', '6', '亻', '左右', NULL, '仲 (会意兼形声。从人,从中。中亦声。甲骨文、金文作中”。本义排行第二) 同本义 仲,中也。', '小学', '1'),
    ('件', 'jiàn', '6', '亻', '左右', NULL, '件 (会意。从人,从牛。《说文》分也。从人,从牛。牛大物故可分。”本义分解,分开) 同本义 件错理微。--晋·郭璞《山海经·图赞》；组词：件别(分别,一一分开)；件举(枚举,一一分开列举) 件 计量某些个体事物、衣服等 不要因一事而惹出两件三件', '小学', '1'),
    ('价', 'jià', '6', '亻', '左右', NULL, '价 (形声。从人,贾声。本义价格,价值) 同本义 经千载以待价兮。--《文选·嵇康·琴赋》 国贫而用不足,请以平价取之。--《管子·轻重》 以求重价；组词：价贯(价关', '小学', '1'),
    ('任', 'rèn', '6', '亻', '左右', NULL, '任 汉王莽时女子爵位名。用以称公主 其女皆为任。--《汉书·王莽传》 古代中国南方少数民族的一种乐曲 任,南蛮之乐也。--《礼记·明堂位》 姓 任 通壬”。壬人,狡猾骗人的；组词：任人(佞人', '小学', '1'),
    ('份', 'fèn', '6', '亻', '左右', NULL, '份〈名〉 (形声。从人,分声。同彬”。1本义文质兼备的样子 2量词。用于计数或搭配成组的东西) 整体里的一部分 限度;程度 情分;情面 本分;名分 用在省、县、年、月”后面', '小学', '1'),
    ('仿', 'fǎng', '6', '亻', '左右', NULL, '仿 (形声。从人,方声。本义相似。或作彷”) 同本义 仿,相似也。--《说文》。俗亦作倣。；组词：仿像(仿佛相像)；他俩长得相仿 仿效；模仿', '小学', '1'),
    ('企', 'qǐ', '6', '人', '上下', NULL, '企〈动〉 (会意。从人,从止。甲骨文字形,上面是一个人,下面是止”(脚),表示这个人在踮起后脚跟,有企立、企足的意思。本义踮起脚跟)；组词：企望(举起脚跟而望)；企仰(踮起脚来仰望)；企足(踮起脚) 立,站立 鸟企山峙', '小学', '1'),
    ('伊', 'yī', '6', '亻', '左右', NULL, '伊 (会意。从人,从尹。尹,治理∠起来指伊尹,殷治理天下者◇假借为那) 表示远指,相当于那” 所谓伊人,在水一方。；组词：伊行(她那里；他们)；伊曹(彼辈,他们)；伊俦(彼辈,其类)；伊拉(方言', '小学', '1'),
    ('伍', 'wǔ', '6', '亻', '左右', NULL, '伍 (会意。从人,从五。五人为伍。本义五人构成一个集体) 同本义 伍,行伍。--《广韵》 五人为伍。--《管子·小筐》 会其什伍而教之道义。--《周礼·天官·宫正》 先偏后伍；组词：伍伯(即伍长', '小学', '1'),
    ('伏', 'fú', '6', '亻', '左右', NULL, '伏〈动〉 (会意。从人,从犬。意思是人如狗那样地匍伏着。本义俯伏;趴下) 同本义 伏,司也。；组词：伏尸(倒在地上的尸体,多 伏 fú 1.趴,脸面向下,身体前屈~地', '小学', '1'),
    ('伐', 'fá', '6', '亻', '左右', NULL, '伐〈动〉 (会意。从人,从戈。甲骨文字形,像用戈砍人的头。本义砍杀) 同本义 伐,击也。--《说文》 伐,杀也。--《广雅》 为酒醴,伐豚羔,舞长袖；组词：伐祭(砍头祭天)；伐杀(杀戮) 砍伐 伐竹取道', '小学', '1'),
    ('休', 'xiū', '6', '亻', '左右', NULL, '休 (会意。从人,从木。人依傍大树休息。本义休息) 同本义 休,息止也。--《说文》 休,息也。--《尔雅》 南有乔木,不可休思。--《诗·周南·汉广》 休,象人息木阴', '小学', '1'),
    ('众', 'zhòng', '6', '人', '上下', NULL, '众 (会意。众”从三人。三”表示众多。众”表示众人站立。衆”,甲骨文字形。象许多人在烈日下劳动。本义众人、大家)', '小学', '1'),
    ('优', 'yōu', '6', '亻', '左右', NULL, '优 (形声。从人,尤声。本义古代表演乐舞、杂戏的艺人。宋元以后,亦泛称戏曲艺人、演员) 同本义 优,饶也。一曰倡也。；组词：优人杂剧(乐舞戏曲)；优孤(专演老年男子的优人 优(優)yōu 1.美好', '小学', '1'),
    ('伙', 'huǒ', '6', '亻', '左右', NULL, '伙 同火”。古兵制十人为火,同火的人互称火伴。俗作伙伴,同伴 合伙;由若干人结成的一群 伙 群聚;结伴;联合一起干 伙 一群的人 伙〈名〉 伙食。饭食 伙huǒ 1.同伴,伴侣', '小学', '1'),
    ('会', 'huì', '6', '人', '上下', NULL, '会 (会意。古文从合,从彡。按彡亦众多意。本义会合) 同本义 会,合也。--《说文》 会,聚也。--《广雅·释诂三》 会同有绛。--《诗·小雅·车攻》 会言近止；组词：会茶(一起喝茶)；会酒(一起吃酒)；会猎(原指会合打猎,又比喻会同作战)；会衔(联名签署公文)；会次(朝会停留的时刻)', '小学', '1'),
    ('伞', 'sǎn', '6', '人', NULL, NULL, '伞 (繖为傘的古字) 特指伞盖。长柄,圆顶,伞面边缘有流苏下垂,也称马伞。古代仪仗的一种,用不同颜色区别品级的高下。知府以上用黄色,知州以下用蓝色 服素衣,持白勺幡。；组词：伞子(古代仪仗队里的执伞者)；伞扇(古代的两种仪仗物', '小学', '1'),
    ('伟', 'wěi', '6', '亻', '左右', NULL, '伟 (形声。从人,韦声。本义高大;壮美) 同本义 伟,大也。--《华严经音义》引珠丛 猗欤伟欤!--《文选·汉武帝·贤良诏》 身长八尺,容貌甚伟；组词：伟干长躯(身材高大、魁梧)；伟木(高大的树)；伟干(魁梧的身躯)；伟美,伟秀(魁梧英俊)；伟悍(魁梧勇猛)；伟貌(体貌魁', '小学', '1'),
    ('传', 'chuán', '6', '亻', '左右', NULL, '传〈动〉 chuan 传递;传送 速于置郵而传命。--《孟子·公孙丑上》 传以示美人及左右。--《史记·廉颇蔺相如列传》；组词：传家(传于后代子弟)；传衣(继承衣钵)；传首(传送首级)；传运(传递运输)；传演(传递演变) 传授 师者,所以传道授业解', '小学', '1'),
    ('伤', 'shāng', '6', '亻', NULL, NULL, '伤 (形声。从人。本义皮肉破损处;创伤) 同本义 伤,创也。--《说文》 命理瞻伤。--《礼记·月令》。注创之浅者曰伤。” 以杙抉其伤。--《左传·襄公十七年》 无面伤；组词：枪伤；两虎相斗,必有一伤；负 伤(傷)shāng 1.受到损害、损坏受~', '小学', '1'),
    ('伦', 'lún', '6', '亻', '左右', NULL, '伦 (形声。从人,仑声。本义辈,类) 同本义 伦,辈也。--《说文》 人伦并处。--《荀子·富国》 儗人必于其伦。--《礼记·曲礼下》 毛犹有伦；组词：伦辈(伦匹,伦党,伦伍)；伦序(流辈；等类)；伦表(流辈之上)；伦品(等类品第)；伦侯(秦爵名', '小学', '1'),
    ('伪', 'wěi', '6', '亻', '左右', NULL, '伪 (会意兼形声。从人,从为,为亦声。本义欺诈) 同本义 伪,诈也。--《说文》。徐锴曰伪者,人为之,非天真也。” 无或诈伪淫巧。--《礼记·月令》 不可学,不可事而在人者；组词：伪诈(欺诈)；伪怠(欺诈懈怠)；伪服(骗居尊位)；伪人(伪夫', '小学', '1'),
    ('伯', 'bó', '7', '亻', '左右', NULL, '伯 通霸”。原指春秋时诸侯的首领 穆公任之,强配五伯、六卿施。(五伯,即五个盟主,五霸齐桓公、晋文公、宋襄公、秦穆公、楚庄王。)；组词：伯气(霸气) 伯 称霸 一朝而伯', '小学', '1'),
    ('估', 'gū', '7', '亻', '左右', NULL, '估 (形声。从人,古声。本义物价) 同本义 乃高盐直,贱帛估。--《新唐书·陆长源传》 通贾”。商人 莫复临时不寄人,漫道江中无估客。--《玉台新咏·梁元帝·别诗》；组词：估人(商人) 市场税 估税悉除,市无二价', '小学', '1'),
    ('伴', 'bàn', '7', '亻', '左右', NULL, '伴 陪同;依随 伴张驰之信期。--《楚辞·悲回风》。注俱也。” 二贵酋名曰馆伴。(名义上是招待使者的官员。)--宋·文天祥《指南录·后序》；组词：伴宿(出殡前一天夜里,亲属等人通宵守灵)；伴游(陪同游玩) 配合 相比 他都是前生修的,咱拿甚么伴他?--《醒世姻缘传》', '小学', '1'),
    ('伶', 'líng', '7', '亻', '左右', NULL, '伶〈名〉 (形声。从人,令声。本义古乐官名、相传黄帝时有伶伦,世掌乐官) 同本义 伶,弄臣也。；组词：伶官(古代的乐官)；伶工(旧指乐师或演员)；伶伦(传说中黄帝时的乐官)；伶界(旧称戏曲界) 引申为表演歌舞的艺人 伶,乐', '小学', '1'),
    ('伸', 'shēn', '7', '亻', '左右', NULL, '伸〈动〉 (本作申”。形声。从人,申声。本义伸直,伸展) 同本义 伸,不屈也。--《说文》 伸,展也。--《广雅》 引而伸之。--《易·系辞上》 君子欠伸。--《仪礼·士相见礼》；组词：伸吭(伸长脖子)；伸舒(伸展；舒展)；伸不得手(插不上手；施展不开手段)；伸长倘脚(方言', '小学', '1'),
    ('伺', 'sì', '7', '亻', '左右', NULL, '伺候 伺候柴进回庄,林冲便说道...--《水浒传》 si 伺 (形声。从人,司声。本义候望,探察)；组词：伺察(观察；侦察)；伺望(守望；察看)；伺漏( 伺 cì又见sì', '小学', '1'),
    ('似', 'sì', '6', '亻', '左右', NULL, '似 (形声。从人,以声。本义像;相像) 同本义 似,象也。--《说文》 似,有以相攖,有不相櫻也。--《墨子经上》 见似目瞿。--《礼记·杂记》。注谓容貌似其父母', '小学', '1'),
    ('佃', 'diàn', '7', '亻', '左右', NULL, '佃 (形声。从人,田声。田”又兼表字义。1本义耕种土地 2引申义租种田地) 同引申义,也指向地主或在古代向官府租种土地 通畋”。畋猎,猎取禽兽 作结绳而为罔罟,以佃以渔,盖取诸离', '小学', '1'),
    ('但', 'dàn', '7', '亻', '左右', NULL, '但 (形声。从人,旦声。1本义脱去上衣,露出身体的一部分。经传皆以袒为之。2只,仅,不过) 表示范围,相当于只”,仅” 但闻黄河流水鸣溅溅。；组词：但已(仅此而已)；但凭(任凭；随便)；但可(只须) 只管,尽管 此系私室,但坐不妨', '小学', '1'),
    ('位', 'wèi', '7', '亻', '左右', NULL, '位 (会意。从人立。人站在朝廷上。本义官吏在朝廷上站立的位置) 同本义 列中廷之左右谓之位。；组词：位著(也作位宁', '小学', '1'),
    ('低', 'dī', '7', '亻', '左右', NULL, '低 (形声。从人,氐声。本义下,与高”相对) 同本义 向上伸展的长度相对较小的 风吹草低见牛羊。；组词：低水位；低仰(忽高忽低)；低小(低矮窄小)；低狭(低矮狭小) 程度或强度处于正常情况以下的', '小学', '1'),
    ('住', 'zhù', '7', '亻', '左右', NULL, '住 (形声。从人,主声。本义停留) 同本义(站住) 见者呼之曰蓟先生小住。”--《后汉书·蓟子训传》 春光已向梅梢住。--《后汉书》 融为中书郎,未有居止,权牵小船于岸上住；组词：住歇(停止,停歇)；住滞(停留)；住后(留后；殿后)；住锡(僧人在某地居留', '小学', '1'),
    ('佑', 'yòu', '7', '亻', '左右', NULL, '佑〈动〉 (形声。从人,右声。字本作右”。表右助。因右”用为左右之右”,又造佑”字表示本义。本义保护;右助)；组词：保佑(迷信的人称神力保护和帮助)；佑助(保佑扶助；庇护) 辅助；帮助 佑,助也', '小学', '1'),
    ('体', 'tǐ', '7', '亻', '左右', NULL, '体〈名〉 (体,会意。从人,从本。古代体、軆”是两个字,体”是劣”,又指粗笨。身体本字是軆”,形声。从骨,豱声。今简化为体”。本义身体)；组词：体态轻盈(形容女子 体(體)tǐ 1.人或动物的全身人~', '小学', '1'),
    ('何', 'hé', '7', '亻', '左右', NULL, '何〈代〉 什么 何节奄忽,蹄足洒血?--《文选·宋玉·高唐赋》。注何,问辞也。” 何调翰之乔桀?--《文选·潘岳·射雉赋》。注何,疑问之辞也。” 何以自绘；组词：何人；何物；有何困难；何干(有什么相干) 怎么样 如太行王屋何', '小学', '1'),
    ('余', 'yú', '7', '人', NULL, NULL, '余 (形声。从食,余声。本义饱足) 饱足。足食得饱 余,饶也。--《说文》 剩下;剩余 昔人已乘黄鹤去,此地空余黄鹤楼。--崔颢《黄鹤楼》 余 剩下的,多余的 行有余力,则以学文；组词：余夫(指一家五口或八口为率以外多余的人口)；余润(利润)；余资(剩余的钱)；余师(很多余地；残留的；余yú 1.我,', '小学', '1'),
    ('佛', 'fó', '7', '亻', '左右', NULL, '佛〈名〉 梵文 buddha音译佛陀”的简称 缺此三项,声闻、缘觉缺后二项,菩萨缺最后一项,只有佛才三项俱全。小乘讲的佛”,一般是用作对释迦牟尼的尊称。大乘除指释迦牟尼外；组词：佛天(佛；西天；美好的地方)；佛化(佛的教化)；佛光(佛所带来的光明)；佛会(佛菩萨众圣会聚的地方)；佛图(佛塔)；佛位', '小学', '1'),
    ('作', 'zuò', '7', '亻', '左右', NULL, '作 作坊,手工业工场 明帝方修宫室而节气不合,...而礼径至所作,不复重奏,称诏罢民。--《三国志·魏志》；组词：作房(作坊)；作分(作坊)；木工作；油漆作；洗衣作 作坊 作 (会意', '小学', '1'),
    ('你', 'nǐ', '7', '亻', '左右', NULL, '你 (形声。从人,尔声。本义称说话的对方) 同本义 武平元年童谣曰狐截尾,你欲除我我除你。”；组词：你咱(你)；你懑(你们)；你娘(骂人的话,相当于你娘的”)；你老(对尊长的敬称)；你那(你老人家)；你伫(您)；你等(你', '小学', '1'),
    ('佣', 'yòng', '7', '亻', '左右', NULL, '佣 (形声。从人,庸声。本义受雇佣,出卖劳动力) 同本义 佣,均直也。卖力受直曰佣。隋其力均其直也。；组词：(1)∶雇佣', '小学', '1'),
    ('佩', 'pèi', '8', '亻', '左右', NULL, '佩 (会意。从人凡巾。本义系在衣带上的装饰品) 同本义 佩,大带佩也。--《说文》 青青子佩。--《诗·郑风·子衿》 共王之服玉佩玉。--《周礼·王府》。注王之所带者；组词：佩玖(作佩饰用的浅黑色美石)；佩玦(有缺口的环形佩玉)；佩珂(用黄黑色玉石制成的佩饰)；佩衽(佩玉和衣襟) 姓 佩 〈动', '小学', '1'),
    ('佳', 'jiā', '8', '亻', '左右', NULL, '佳 (形声。从人,圭声。本义美,美好) 同本义 佳,善也。--《说文》 佳,大也,又,好也。--《广雅》 佳兵者不祥。--《老子》 佳丽人之所出也', '小学', '1'),
    ('使', 'shǐ', '8', '亻', '左右', NULL, '使 (形声。从人,吏声。从人表示人的动作行为。本义命令) 同本义 使,伶也。--《说文》。按,伶者,令也。 故君使其臣。--《礼记·表记》。注谓使之聘问师役之属也；组词：支使(命令人去做事) 派遣 乃使蒙恬北筑长城而守藩篱', '小学', '1'),
    ('侄', 'zhí', '8', '亻', '左右', NULL, '侄 (侄为姪的俗字)弟兄或其他同辈男性亲属的子女 姪,兄之女也。从女,至声。--《说文》 女子谓兄弟之子为姪。--《尔雅》 谓吾姑者,吾谓之姪；组词：侄少爷(旧时 侄(姪)zhí兄、弟或同辈亲戚的儿子(也指女儿)~子', '小学', '1'),
    ('侈', 'chǐ', '8', '亻', '左右', NULL, '侈 (形声。从人,多声。本义自高自大,盛气凌人) 同本义 侈,掩胁也。--《说文》。段注掩者,掩盖其上;胁者,胁制其旁。凡自多以陵人曰侈。此侈之本义也。” 侈兮哆兮；组词：侈慢(自大傲慢)；侈满(骄纵)；侈然(骄纵貌；自大貌)；侈傲(骄纵)；侈邪(言行放肆) 奢侈,追求过分的享受 侈,一曰奢', '小学', '1'),
    ('例', 'lì', '8', '亻', '左右', NULL, '例〈动〉 (形声。从人,列声。本义比照) 同本义 例,比也。--《说文》。按,礼记服问上附下附,列也。公别比例之义。古只作列,此字后出。 举此以例其余；组词：溯古例今；以此例比 例 〈名〉 类；列 扬州城下进退不由,殆例送死', '小学', '1'),
    ('侍', 'shì', '8', '亻', '左右', NULL, '侍 (形声。从人,寺声。本义在尊长旁边陪着) 同本义 侍,承也。--《说文》 曾子侍。--《孝经》。郑注卑在尊者之侧为侍也。” 侍中。--《后汉书·邳彤传》。注有左右曹,入侍天子', '小学', '1'),
    ('供', 'gòng', '8', '亻', '左右', NULL, '供 (形声。从人,共声。本义供给,供应) 同本义 供,供给。--《说文》 凡与之所以大用者,外供甲兵而内给淫奢也。--《韩非子·解老》 王之诸臣皆足以供之；组词：供亿(供应所需,也指供应的东西)；供膳(供给膳食)；供饷(供给差粮)；供祀(供给祭祀) 提供某种条件 供gòng 1.奉', '小学', '1'),
    ('依', 'yī', '8', '亻', '左右', NULL, '依 (形声。从人,衣声。甲骨文字形。人在衣中。本义靠着) 同本义 依,倚也。--《说文》 依,恃也。--《广雅》 白日依山尽,黄河入海流。--王之涣《登鹳雀楼》 依柱而笑；组词：依山之榭(靠山建造的房屋)；依栖(依傍栖息)；依山傍水；依着电线杆；偎依(亲密地靠着)；依倚(倚靠；依傍)；依门卖笑(以', '小学', '1'),
    ('侠', 'xiá', '8', '亻', '左右', NULL, '侠 (形声。从人,夹声。本义侠义) 同本义。指见义勇为、肯舍己助人的性格、气质或行为 俠,俜也。；组词：侠奴(侠义的奴仆)；侠情(见义勇为、舍己助人的感情) 侠客 材力绝人,少重然许,喜侠节', '小学', '1'),
    ('侣', 'lǚ', '8', '亻', '左右', NULL, '侣〈名〉 (形声。从人,吕声。本义伴侣,同伴) 同本义 命俦啸侣,或戏清流,或翔神渚。--曹植《洛神赋》 我来无伴侣,把酒对南山。--唐·韩愈《把酒》 故人念我寡徒侣；组词：仙侣；僧侣(出家修行的佛教徒)；侣俦(朋友) 侣 〈动〉 结为伴侣；陪伴 侣鱼虾而友麋鹿', '小学', '1'),
    ('侥', 'yáo', '8', '亻', '左右', NULL, '侥〈形〉 (形声。从人,尧声。本义 僬侥 古代传说中的矮人) 贪求不止 不敢复有侥冀。--《资治通鉴》；组词：侥速(贪求速度)；侥滥(贪得无厌不守法度)；侥望(对财利的非分奢望) 引申指希求意外成功或幸免 此以人之国侥倖也', '小学', '1'),
    ('侦', 'zhēn', '8', '亻', '左右', NULL, '侦 (形声。从人,贞声。本义探伺,暗中察看) 同本义 外令兄弟求其纤过,内使御者侦伺得失。；组词：侦知(探知；暗中查明)；侦伺(窥探,伺望)；侦者(侦探敌情的人) 问,卜问', '小学', '1'),
    ('侧', 'cè', '8', '亻', '左右', NULL, '侧 (形声。从人,则声。本义旁边) 同本义。亦用作谦词 侧,旁也。--《说文》 居侧室。--《礼记·内则》。注谓夹之室次燕寝也。” 立于侧阶。--《书·顾命》 倾容幸而待侧；组词：左侧；右侧；侧闻(谦词', '小学', '1'),
    ('侨', 'qiáo', '8', '亻', '左右', NULL, '侨 (形声。从人,乔声。本义高) 同本义 侨,高也。--《说文》 败长狄侨如。--《左传·文公十一年》；组词：侨人(踩高跷的人) 侨 客居异地 客居国外 侨 寄居国外的人 侨(僺)qiáo 1.寄居在国外或外乡~居', '小学', '1'),
    ('侮', 'wǔ', '9', '亻', '左右', NULL, '侮 (形声。从人,每声。本义轻慢,不敬重) 同本义 不侵侮。--《礼记·曲礼》 又如侮易(轻慢。);侮慢(轻侮傲慢,不敬重他人);侮忽(轻视,轻慢);侮法(藐视和歪曲法令)；组词：侮易(轻慢', '小学', '1'),
    ('侯', 'hòu', '9', '亻', '左右', NULL, '侯 (象形。从人,从厂,象张布,矢在其下。甲骨文字形,象射侯张布著矢之形。本义箭靶) 同本义。以兽皮或画上兽形的为之 矦,春饷所射矦也。；组词：侯弓(古代较射时用以射侯之弓☆,箭靶)；侯道(箭靶与射者间的距离) 诸侯 内诸侯禄也,外诸侯嗣也', '小学', '1'),
    ('侵', 'qīn', '9', '亻', '左右', NULL, '侵〈动〉 (会意。小篆字形从人,手(又)拿扫帚,一步一步地扫地。本义渐进) 同本义 侵,渐进也。；组词：侵润(逐渐发展)；侵寻(渐进)；侵淫(渐进的样子)；侵寻(范围逐渐扩大) 侵犯进攻 凡师有钟鼓曰伐,无曰侵,轻曰袭', '小学', '1'),
    ('便', 'biàn', '9', '亻', '左右', NULL, '便 便利,方便 便,安也。人有不便更之。从人,从更,会意。--《说文》 故自谓便人。--《礼记·表记》。释文谓便习也。” 或谓救之便。--《战国策·秦策》。注利也。” 恣所便只；组词：简便(简单方便)；便郵(顺便替人传送书信的人)；便中(方便的时候)；便宜施行(不及请示,自行斟酌情势以处理', '小学', '1'),
    ('促', 'cù', '9', '亻', '左右', NULL, '促 (形声。从人,足声。本义紧迫。又指急促,赶快) 同本义 促,速也。--《广韵》 促,速也。--《汉书·高帝纪》注 长来觉日月益促。--唐·柳宗元《与萧俛书》；组词：促柱(急切的絣音)；促装(急忙整治行装)；促速(急速)；促病(急病) 小,狭窄 短', '小学', '1'),
    ('俄', 'é', '9', '亻', '左右', NULL, '俄 (形声。从人,我声。本义倾斜) 同本义 俄,行顷也。--《说文》 侧弁之俄。--《诗·小雅·宾之初筵》 俄轩冕。--扬雄《羽猎赋》。注卬也。” 于时曜灵俄景；组词：俄景(偏西的阳光) 通峨”', '小学', '1'),
    ('俊', 'jùn', '9', '亻', '左右', NULL, '俊 (形声。从人,雋声。本义才智超群的人) 同本义 俊,材千人也。--《说文》 十人者曰豪,百人者曰杰,千人者曰俊,万人者曰英。--《春秋繁露·爵国》 德万人者谓之俊；组词：俊选(俊士和选士)；俊良(贤能优良之士)；俊物(杰出人物)；俊群(才能卓越一类人) 光彩 那就算你在世街路上留了朋友,俊', '小学', '1'),
    ('俏', 'qiào', '9', '亻', '左右', NULL, '俏〈形〉 (形声。从人,肖声。本义相貌美好) 同本义 俏 灵巧 有利可图 没点胆子哪能找到这么俏的事!--老舍《骆驼祥子》 货物销路好 这一批货', '小学', '1'),
    ('俐', 'lì', '9', '亻', '左右', NULL, '伶俐”聪慧;机灵 俐亮 话也说不俐亮 俐落,俐索 说起话来干脆俐索 俐lì', '小学', '1'),
    ('俗', 'sú', '9', '亻', '左右', NULL, '俗 (形声。从人,谷声。习俗是人的行为,所以从人。本义风俗) 同本义(长期形成的礼节、习惯) 俗,习也。；组词：风俗(风,指一时普遍流行的风气；俗,指长期形成的礼节、习惯)；习 俗sú 1.风俗土~', '小学', '1'),
    ('俘', 'fú', '9', '亻', '左右', NULL, NULL, '小学', '1'),
    ('保', 'bǎo', '9', '亻', '左右', NULL, '保 (会意。甲骨文字形,象用手抱孩子形。金文写作从人”从子”◇来为了结构的对称,小篆变成保”,使人不能因形见义了。本义背子于背)', '小学', '1'),
    ('信', 'xìn', '9', '亻', '左右', NULL, '信 (会意。从人,从言。人的言论应当是诚实的。本义真心诚意) 同本义 信,诚也。--《说文》 有诸已之谓信。--《孟子》 信,言合于意也。--《墨子经》 信者,诚也。专一不移也', '小学', '1'),
    ('俩', 'liǎng', '9', '亻', '左右', NULL, '俩 (形声。从人,两声。本义两个) 同本义 几个(泛指少数) 注意俩”后面不再接个”字或其他量词 俩(倆)liǎ 1.两个,少数几个("俩"字后不能再用"个"或别的量词)咱~', '小学', '1'),
    ('俭', 'jiǎn', '9', '亻', '左右', NULL, '俭 (形声。从人,佥声。本义自我约束,不放纵) 同本义 俭,约也。--《说文》 君子以俭德避难。--《易·否象传》 俭德之共也。--《左传·庄公二十四年》 严公子广而俭,文而有礼；组词：俭貌(态度谦逊)；俭退(俭约谦让)；俭然(自谦的样子) 节俭,节省 俭于财用,节于衣食', '小学', '1'),
    ('修', 'xiū', '9', '亻', '上下', NULL, '修 (形声。从彡,攸声。彡”有装饰义。本义修饰,装饰) 同本义 修,饰也。--《说文》 义之修而礼之藏也。--《礼记·礼运》。注犹饰也。” 美要眇兮宜修。--《楚辞》 以修敬也；组词：修容(整饰容貌)；修词(修饰词句', '小学', '1'),
    ('俯', 'fǔ', '10', '亻', '左右', NULL, '俯 (会意。从页,表示与头有关,从逃省。取低头逃跑意。现在简化为从人府声”的形声字。本义低头)；组词：俯擗(低头捶胸,悲伤之极的样子)；俯偻(低头曲背)；俯听(俯首而听)；俯鉴(低头照视) 弯腰屈身 余立侍左右,援疑质理,', '小学', '1'),
    ('俱', 'jù', '10', '亻', '左右', NULL, '俱 (形声。从人,具声。本义走在一起,在一起) 同本义 俱,皆也。--《说文》 而仪与之俱。--《战国策·齐策》。注偕也。” 道可载而与之俱也', '小学', '1'),
    ('俺', 'ǎn', '10', '亻', '左右', NULL, '俺〈代〉 都道是金玉良缘,俺只念木石前盟。--《红楼梦》 又如俺那儿(我家里那个。指丈夫);俺不去', '小学', '1'),
    ('倍', 'bèi', '10', '亻', '左右', NULL, '倍 (形声。从人,(轴??))声。本义通背”。反;背向) 同本义 倍,反也。--《说文》 倍正南方。--《周髀算经下》 兵法右倍山陵,前左水泽。--《史记·淮阴侯传》 背弃；组词：倍畔(同背叛)；倍上(背叛尊上) 通背”', '小学', '1'),
    ('倒', 'dǎo', '10', '亻', '左右', NULL, '倒 (形声。从人,到声。本义倒下) 同本义 对此欲倒东南倾。--唐·李白《梦游天姥吟留别》；组词：倒头(躺下睡觉；死亡)；倒路(亦路倒', '小学', '1'),
    ('倔', 'juè', '10', '亻', '左右', NULL, '倔 (形声。从人,屈声。本义顽强,固执) 同本义 倔强倨傲。--《盐铁论》 倔强,谓强梁也。亦双声连语。--《后汉书·张李彭卢传》注；组词：倔僵(亦作倔彊”、倔犟”', '小学', '1'),
    ('倘', 'tǎng', '10', '亻', '左右', NULL, '倘佯 tang 倘〈连〉 表示假设。同黨”、儻” 倘三年犹不得。--清·候方域《壮悔堂文集》 倘复请之。--清·方苞《狱中杂记》 汝倘有灵；组词：倘若；倘或；倘或间；倘使；倘如；倘然(假如) 相当于或许”、大概” 倘 cháng又见tǎng', '小学', '1'),
    ('候', 'hòu', '10', '亻', '左右', NULL, '候〈动〉 (形声。古文作矦”。从人,侯声。本义守望;侦察) 同本义 矦,伺望也。--《说文》 矦,覗也。--《广雅·释诂三》 市有候馆。--《周礼·遗人》。注楼可以观望者也；组词：候馆(用以瞭望的高楼)；候楼(用以瞭望的楼)；侯遮(侦探敌情)；候徼(在国境线上巡察警戒)；候车(侦察敌情的战车) 观测', '小学', '1'),
    ('倚', 'yǐ', '10', '亻', '左右', NULL, '倚 (形声。从人,奇声。本义斜靠着) 同本义 倚,依也。--《说文》 参天两地而倚数。--《易·说卦》 倚柱而笑。--《史记·刺客列传》 倚于郎门；组词：倚望(父母倚门望子)；倚身(把身体靠在某一物体上)；倚门(靠着门) 依靠；依赖 祸兮福之所倚', '小学', '1'),
    ('借', 'jiè', '10', '亻', '左右', NULL, '借 (形声。从人,昔声。本义借,借进,借出) 借进 借,假也。--《说文》。朱骏声曰即藉字之转注。古只作藉。” 借,假借也。--《广韵》 借无不给；组词：求借(请求别人借给)；挪借(暂时借用别人的钱)；借当(借人东西去当铺当钱)；借当头(借将要拿去典当的东西)；借典(借,借', '小学', '1'),
    ('倡', 'chàng', '10', '亻', '左右', NULL, '倡 (形声。从人,昌声。本义唱歌的艺人) 同本义 倡,乐也。--《说文》 倡,俳也。--《声类》 倡,优乐也。--《字林》 令倡俳赢戏坐中。--《汉书·广川惠王越传》。注乐人也；组词：倡家(歌楼酒馆', '小学', '1'),
    ('倦', 'juàn', '10', '亻', '左右', NULL, '倦 (形声。从人,卷声。本义疲倦,劳累) 同本义 倦,疲也。--《汉书·司马相如传》集注 倦狭路之迫隘。--潘岳《西征赋》 不继之以倦。--《礼记·表记》 居之无倦；组词：困倦(疲乏想睡)；倦程(倦于旅程)；倦飞(疲于飞行', '小学', '1'),
    ('债', 'zhai', '10', '亻', '左右', NULL, '债 (形声。从人,责声。本作责”,债”为后起字。本义欠别人的钱财) 同本义 债,债负也。--《说文新附》 于是有买田宅,鬻子孙,以偿债者矣。--《汉书·论贵粟疏》；组词：债壳子(负了一身债的穷官)；债赖(债权人否认借债给他人)；债累(负债；债务)；债桩(比喻被债务包围的人)；内债(国家向本', '小学', '1'),
    ('值', 'zhí', '10', '亻', '左右', NULL, '值 (形声。从人,直声。字本作直”。本义措置,放置) 同本义 值,措也。--《说文》 值,本作直。...值与置同,故《说文》训值为措,训措为置,互相转注,其音义并同；组词：值遇；正值国庆,老友相逢,真是高兴 值班 家父前日退值回来', '小学', '1'),
    ('倾', 'qīng', '10', '亻', '左右', NULL, '倾 (会意兼形声。从人,从顷,顷亦声。顷”有偏侧的意思。从人,多表示人的动作行为。本义偏侧)；组词：倾葵(向日葵', '小学', '1'),
    ('假', 'jiǎ', '11', '亻', '左右', NULL, '假 (形声。从人。叚”亦兼表字义。本义不是真的) 同本义(跟真”相反) 假,非真也。--《说文》 假,今不然也。--《墨子·经上》 假寐永叹。--《诗·小雅·小弁》；组词：假姨姨(假亲戚,冒充的亲戚)；假言(虚假不实的言语)；假女(鸨儿称自己认作养女的妓女)；假局(假局子', '小学', '1'),
    ('偎', 'wēi', '11', '亻', '左右', NULL, '偎 (形声。从人,畏声。本义亲近) 同本义 不偎不爱。--《列子·黄帝》 天毒偎人爱人。--《山海经·海内经》；组词：偎爱(相亲爱)；偎妻靠妇(依恋妻子)；偎红倚翠(亲狎女色；狎妓)；偎干就湿(形容母育儿之苦) 依傍,紧靠着 灞岸晴来送别', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('偏', 'piān', '11', '亻', '左右', NULL, '偏〈形〉 (形声。从人,扁声。本义不正,倾斜) 同本义 偏,颇也。--《说文》 无偏无颇。--《书·洪范》 势有偏侧。--南朝宋·谢灵运《山居赋》；组词：偏岸(斜岸)；偏偏倒倒(东倒西歪', '小学', '1'),
    ('做', 'zuò', '11', '亻', '左右', NULL, '做 (做”是作”后起的分别字,作”近代写作做”) 作。从事某种工作或活动 我且不做买卖,和你一同家去。；组词：做道路(做生意；从事拦路抢劫、偷盗活动)；做夫(服劳役；作劳动力)；大事做不来,小事又不做；做不得；做不了；做嗄(干什么', '小学', '1'),
    ('停', 'tíng', '11', '亻', '左右', NULL, '停〈动〉 (形声。从人,亭声。本义停止,止息) 同本义 停,定也,定于所在也。--《释名·释言语》 潢汙行潦之水。--《左传·隐公三年》。注潢汙,停水。” 停杯投箸不能食；组词：停床(指亡故)；停市(停止交易)；停刑(停止执行刑罚)；停步(停止前进) 停留,暂时居住 停数日', '小学', '1'),
    ('健', 'jiàn', '10', '亻', '左右', NULL, '健 (形声。从人,建声。本义强有力) 同本义 健,伉也。--《说文》 震其究为健。--《易·说卦传》 四健骄也。--《韩诗外传》 天行健,君子以自强不息。--《易·乾》 天下健者；组词：健举(刚劲有力)；健舞(刚健风格的舞蹈) 健康；健壮 纵有健妇把锄犁,禾生垄亩无东西', '小学', '1'),
    ('偶', 'ǒu', '11', '亻', '左右', NULL, '偶〈名〉 (形声。从人,禺声。本义仿人形制成的木偶) 同本义 偶,相人也。--《说文》。按,相人者,像人也。一名俑。 鲁以偶人,而孔子叹。--《淮南子·缪称》 见偶人与偶人相与语；组词：头偶；偶戏(木偶戏) 伙伴；同伴；与人共处 乃率其曹偶,亡之江中', '小学', '1'),
    ('偷', 'tōu', '11', '亻', '左右', NULL, '偷 (形声。从人,俞声。本义苟且;马虎) 同本义 偷,苟且也。--《说文》 其下偷以幸。--《国语·晋语一》 安肆曰偷。--《礼记·表记》 存者且偷生；组词：偷的锣儿敲不得(喻不能声张)；偷存(偷生；苟活)；偷合(苟且迎合)；偷弛(苟且松弛)；偷免(苟免)；偷快(苟求快乐)；偷', '小学', '1'),
    ('偿', 'cháng', '11', '亻', '左右', NULL, '偿 (形声。从人,赏声。本义归还,赔偿) 同本义 偿,还也。--《说文》 偿,复也。--《广雅》 西邻责言不可偿也。--《左传·僖公十五年》 使吏召诸民当偿者悉来合券；组词：偿债(偿还欠债)；偿付(归还所欠的债) 报答；酬报 补偿,抵偿 相如视秦王无意偿赵城', '小学', '1'),
    ('傀', 'guī', '11', '亻', '左右', NULL, '傀〈形〉 (形声。从人,鬼声。本义伟;大) 同本义 傀,伟也。--《说文》 达生之情者傀。--《庄子·列御寇》；组词：傀然(魁梧貌)；傀俄(魁伟貌)；傀卓(卓异) 奇异 大傀异灾', '小学', '1'),
    ('傅', 'fù', '12', '亻', '左右', NULL, '傅〈动〉 (形声。从人,尃声。本义辅佐) 同本义 傅,相也。--《说文》。按,与倅略同。 傅,傅之德义。--《汉书·贾谊传》。师古曰傅,辅也。” 郑伯傅王；组词：傅父(古代辅育王室子女的年长男性保育人员)；傅御(古代辅佐君王或诸侯办事的官员)；傅弼(辅弼；辅佐) 辅导 有楚大夫于此', '小学', '1'),
    ('傍', 'bàng', '12', '亻', '左右', NULL, '傍 (形声。从人,旁声。本义靠近,临近)同本义 傍,近也。--《说文》 双兔傍地走。--《乐府诗集·木兰诗》；组词：傍边(靠近边沿)；傍通(靠近四方通达之地)；傍境(边境)；傍户而立 傍 依附,依靠 辅佐 四贤傍之', '小学', '1'),
    ('储', 'chǔ', '12', '亻', '左右', NULL, '储〈动〉 (形声。从人,诸声。本义积蓄备用) 同本义 储,偫也。--《说文》 储,贮也。储亦备也,谓蓄物以为备曰储也。--《一切经音义》 小人德无储。--曹子建诗犊 盈衍储邸；组词：储粮备荒；冬储白菜；储邸(储存物品的府库)；储峙(蓄备)；储款(将钱存入银行)；储书(藏书)；储敛(聚集资财)；储才(积', '小学', '1'),
    ('催', 'cuī', '13', '亻', '左右', NULL, '催 (形声。从人,崔声。本义催促,促使) 同本义 交徧催我。--《诗·邶风·室人》 鸿仪催零金。--《侯成碑》 都门帐饮无绪,留恋处兰舟催发。--柳永《雨霖铃》 葡萄美酒夜光杯；组词：催比(催征)；催并(催促；催逼)；催迸(同催并”)；催科(催租；亦指催缴钱粮的小吏)；催命鬼(催人早死的鬼使)；催索(催', '小学', '1'),
    ('傲', 'ào', '12', '亻', '左右', NULL, '傲〈形〉 (形声。从人,敖声。本义骄傲;傲慢无理) 同本义 傲,倨也。--《说文》 经传以敖为之 凡视上于面则敖。--《礼记·曲礼》 彼交匪敖。--《诗·小雅·桑柔》 不吴不敖；组词：傲兀( 傲ào 1.自高自大~慢', '小学', '1'),
    ('傻', 'shǎ', '13', '亻', '左右', NULL, '傻 头脑蠢笨,不谙事理,缺乏想象力 贾母喜欢,便起名为傻大姐。--《红楼梦》 又如傻厮(傻角。傻瓜,呆子);傻大头(傻子);傻儿凹(呆子);傻相(愚蠢可笑的样子)；组词：傻厮(傻角', '小学', '1'),
    ('像', 'xiàng', '13', '亻', '左右', NULL, '像 (形声。从人,从象,象亦声。本义相貌相似) 同本义 像,似也。--《说文》。段注然韩非之前只有象字,无像字~非以后小篆即作像。许断不以象释似,复以象释像矣。系辞曰,爻也者', '小学', '1'),
    ('僚', 'liáo', '14', '亻', '左右', NULL, '僚〈名〉 (形声。从人,尞声。本义官,官职) 同本义 百僚师师。--《书·皋陶谟》 百僚是试。--《诗·小雅·大东》 世胄蹑高位,英俊沉下僚。--左思《咏史》；组词：僚吏(僚属', '小学', '1'),
    ('僧', 'sēng', '14', '亻', '左右', NULL, '僧〈名〉 (形声。从人,曾声。本义和尚) 同本义 僧言古壁佛画好,以火来照所见稀。--韩愈《山石》；组词：僧行(僧众)；僧众(僧人和尚；佛教徒)；僧录司(明清时期管理佛门事务的机构)；僧雏(年龄小的僧人)；僧寮(僧人居住的房屋', '小学', '1'),
    ('僵', 'jiāng', '15', '亻', '左右', NULL, '僵 (形声。从人,畺声。本义仰面向后倒下) 同本义 僵,偾也。--《说文》 鲍叔御公子凶僵。--《吕氏春秋·贵卒》。注偃也。” 佯僵而弃酒。--《史记·苏秦传》。注仆也；组词：僵死(倒地死去；倒地死去的人)；僵伏(倒地而死 死去 伶悝僵', '小学', '1'),
    ('僻', 'pì', '15', '亻', '左右', NULL, '僻〈动〉 (形声。从人,辟声。本义退避;回避) 同本义 僻,辟也。...《诗》曰宛如左僻。”；组词：僻路(偏僻的小路)；僻壤(偏僻的地方)；僻小(偏僻狭小)；僻穴(偏僻的洞穴)；僻陋(偏僻简陋)；僻巷(偏僻小巷)；僻净(', '小学', '1'),
    ('儒', 'rú', '16', '亻', '左右', NULL, '儒 (形声。从人, 需声。本义 术士) 同本义。春秋时从巫、史、祝、卜中分化出来的、熟悉诗书礼乐而为贵族服务的人 儒,术士之称。；组词：儒师；儒仙 孔子学说(孔教)；孔子的和他的弟子一家的学说,其特点是强调对孝、仁、义、礼、智、信等基本道德的实践和修养,', '小学', '1'),
    ('儡', 'lěi', '17', '亻', '左右', NULL, '儡〈形〉 败坏 儡,相败也。--《说文》 然而不免于儡身。--《淮南子·俶真》 又如儡亡(颓丧的样子);儡然(破败的样子) 疲倦 寮位儡其隆替；组词：儡亡(颓丧的样子)；儡然(破败的样子) 疲倦 寮位儡其隆替', '小学', '1'),
    ('儿', 'ér', '2', '儿', '左右', NULL, '儿 (象形。甲骨文字形,下面是人”字,上面象小儿张口哭笑。儿”是汉字部首之一,从儿”的字大都与人”有关。本义幼儿。古时男称儿,女称婴,后来孩童都称儿)；组词：儿女子(孩童)；儿剧(犹儿戏)；儿话(孩子话)；儿撬(拐棍儿)；儿拜(孩童对大人所行的礼拜)；儿啼(小孩哭)；儿孩(孩童', '小学', '1'),
    ('允', 'yǔn', '4', '儿', '上下', NULL, '允 (会意。甲骨文字形,上为以”(呂)字,下为儿”(人)字。以是任用,用人不贰就是允”。本义诚信)；组词：允元(信任仁厚之人)；允直(诚实正真)；允忠(忠信) 公平 祖父经,为郡县狱吏,案法平允,务存宽恕', '小学', '1'),
    ('元', 'yuán', '4', '儿', '上下', NULL, '元 (会意。从一,从兀。甲骨文字形。象人形。上面一横指明头的部位。上一短横是后加上去的,依汉字造字规律,顶端是一横的,其上可加一短横。本义头)；组词：元首(头) 天 元yuán 1.头归(送还)其~', '小学', '1'),
    ('兄', 'xiōng', '5', '儿', '上下', NULL, '兄 (会意。据甲骨文,上为口”,下为匍伏的人。小篆从口,从儿(人)。象一人在对天祈祷,是祝”的本字。本义兄长)；组词：乃兄(你的哥哥)；令兄(尊兄,尊称对方的哥哥)；愚兄(哥哥自己谦称)；家兄(谦称自己的哥哥) 亲戚中同辈男性中年龄比自己', '小学', '1'),
    ('充', 'chōng', '6', '儿', '上下', NULL, '充 (会意。从儿,育省声。育子长大成人。本义长,高) 同本义 充,长也,高也。--《说文》 宗人视牲告充。--《仪礼·特牲礼》 满 充,塞也。--《小尔雅》 充,满也；组词：充多(众多)；充车(满车；喻数量众多)；充房(满屋)；充堂(满堂) 足；实；富厚 肥胖 充 装满；塞满 充 chōng', '小学', '1'),
    ('兆', 'zhào', '6', '儿', NULL, NULL, '兆 (象形。大篆字形像龟甲受灼所生的裂痕。本义卜兆,龟甲烧后的裂纹) 同本义 兆卜,灼龟拆也。--兆,古文兆卜省。；组词：兆象(占卜时龟板上显示的征象)；兆文(据以卜占吉凶的龟甲裂纹)；兆卦(显示于卦象上的征兆)；兆梦(占梦,圆梦) 征兆,预', '小学', '1'),
    ('先', 'xiān', '6', '儿', NULL, NULL, '先 (会意。据甲骨文,上面是止”(脚),下面是人”。意思是脚已走在人的前面。本义前进,走在前面)；组词：身先士卒；争先恐后；争先(争着赶到别人前头) 尊崇；重视 安宁则长庠序,先本绌末,以礼义防于利', '小学', '1'),
    ('光', 'guāng', '6', '儿', '上下', NULL, '光guāng 1.光线,照亮物体因而可用眼睛看到物体的那种东西~亮。~芒。日~。电灯~。~的传播速度,每秒约30万公里。〈喻〉心怀坦白,公正无私~明磊落。正大~明。 2.荣耀', '小学', '1'),
    ('克', 'kè', '7', '十', '上下', NULL, '克 (象形。甲骨文字形,下面象肩形。整个字形,象人肩物之形。本义胜任) 同本义 克,肩也。；组词：克当(担当,承受)；克堪(胜利)；克家(能承担家事)；克祚(能继承祖辈的福禄)；克家子(克家儿', '小学', '1'),
    ('免', 'miǎn', '7', '刀', '上下', NULL, '免 (会意。金文字形,下面是人”,上面象人头上戴帽形,是冠冕的冕”本字。由于假借为免除”义,另造冕”字。假借义免除,避免) 脱掉;脱落 免,脱也。；组词：免胄(脱下头盔)；免丧(脱去丧服)；免绖(脱去麻带而仅着丧服) 赦免,释放 免miǎn 1.去除,去掉~去', '小学', '1'),
    ('兑', 'duì', '7', '儿', '上下', NULL, '兑 (会意。从人,从囗,八象气之舒散,兄者与祝同意。从八,与曾同意,今字作悦。本义喜悦)；组词：兑悦(喜悦) 通锐(畲??))”', '小学', '1'),
    ('兔', 'tù', '8', '儿', NULL, NULL, '兔 (象形。象踞后其尾形。本义哺乳类动物,通称兔子) 同本义 兔,兽名。象踞后其尾形。--《说文》。其兽前足短后足长,俗字作菟。 兔舐毫而孕,及其生子,从口而出也', '小学', '1'),
    ('党', 'dǎng', '10', '儿', NULL, NULL, '党 (形声。从黑,尚声。党”、黨”在古代是两个字,现在党”是黨”的简化字。简化字党”,从儿(人,尚声)本义晦暗不明。党”指集团时,在古代一般只用于贬义', '小学', '1'),
    ('兜', 'dōu', '11', '儿', NULL, NULL, '兜 兜鍪,即胄,古代头盔名 又如兜韐(头盔和皮革制的弓箭袋,也泛指武器装备);兜鍪铠(战士戴的头盔和铠甲);兜巾(有后兜的帽子) 缝在衣服里面的或旁边开口的小袋 装盛东西之物；组词：兜韐(头盔和皮革制的弓箭袋,也泛指武器装备)；兜鍪铠(战士戴的头盔和铠甲)；兜巾(有后兜的帽子) 缝在衣服里面的或旁边开', '小学', '1'),
    ('兢', 'jīng', '14', '儿', '左右', NULL, '兢 (象形。金文字形,象二人头顶重物形。头上戴着重物,故常戒惕小心。本义小心谨慎的样子)；组词：兢惕(小心谨慎)；兢持(矜持,拘束)；兢兢切切(兢兢业业,小心翼翼)；兢危(戒慎忧惧) 强劲 尔羊来思,矜矜兢兢,不骞不', '小学', '1'),
    ('入', 'rù', '2', '入', NULL, NULL, '入 (象形。甲骨文字形,象个尖头器具,尖头器具容易进入。本义进来,进去) 同本义 入,内也。；组词：入门问讳(到别人家里,先需了解人家先祖名讳,以便谈话)；入对(进宫回答皇帝的问题)；入览(看到)；入迁(从外地迁到京城做', '小学', '1'),
    ('全', 'quán', '6', '入', '上下', NULL, '全〈名〉 (一作仝。会意。篆文从入,从王(玉)。盖谓交纳的玉完整无缺。本义纯色玉) 同本义 全,完也。；组词：全装贯带(全副武装)；全副(全套)；全家；全甲(全部披 全quán 1.完整,完备,不缺少齐~', '小学', '1'),
    ('八', 'bā', '2', '八', NULL, NULL, '八 (象形。甲骨文象分开相背的样子『字部首之一。从八”的字多与分解、分散、相背有关。本义相背分开)', '小学', '1'),
    ('公', 'gōng', '4', '八', '上下', NULL, '公〈形〉 (会意。小篆字形,上面是八”,表示相背,下面是厶”(私”的本字)∠起来表示与私相背”,即公正无私”的意思。本义公正,无私)；组词：公气(正大,公正)；公素(公正质朴)；公洁(公正廉洁)；公慎(公正谨慎)；公诚( 公gōng 1.国家的或集体的,跟"私', '小学', '1'),
    ('六', 'liù', '4', '八', '上下', NULL, '六〈数〉 五加一的和 人道以六制。--《管子·五行》 六日不詹。--《诗·小雅·采绿》 六主律。--《易·本命》 夫六中色也。--《国语·周语》 六王毕,四海一；组词：六礼(中国古代婚姻需备的六种礼节纳采、问名、纳吉、纳征、请期、亲迎)；六味(指苦、酸、甘、辛、咸、淡等六种滋味)；六料(', '小学', '1'),
    ('兰', 'lán', '5', '乺', '上下', NULL, '兰 (形声。从苃,阑声。本义兰草,即泽兰) 同本义 蘭,香草也。--《说文》 衡兰芷若。--《汉书·司马相如传》 兰槐之根是为芷。--《荀子·劝学》 泽兰属植物的泛称,属菊科', '小学', '1'),
    ('共', 'gòng', '6', '八', '上中下', NULL, '共 供奉 不共神祗。--《国语》 尔贡包茅不入,王祭不共,无以缩酒。--《左传》 恭敬。通恭” 共武之服。--《诗·小雅·六月》 虔共尔位。--《诗·大雅·韩奕》 公卑杞；组词：共命(敬从命令)；共勤(恭谨勤劳)；共承(恭敬地承奉)；共奉(敬奉,供奉) 供给；供应', '小学', '1'),
    ('关', 'guān', '6', '乺', '上下', NULL, '关 (形声。从门,乷声。金文作閠”,象门里有门闩形,本象形字。小篆繁化,变成了形声字。本义门闩) 门闩。闩门的横木 关,以木横持门户也。；组词：关牡(门闩', '小学', '1'),
    ('兴', 'xīng', '6', '八', '上中下', NULL, '兴 (会意。从舁,从同。舁,共举;同,同力。本义兴起;起来) 同本义 兴,起也。--《说文》 夙兴夜寐。--《诗·卫风·氓》 乃寝乃兴。--《诗·小雅·斯干》 三岁不兴；组词：兴居(起居)；兴辞(起立致辞)；兴寝(起卧 兴(興)xīng 1.起,起来~起', '小学', '1'),
    ('兵', 'bīng', '7', '八', '上下', NULL, '兵 (会意。从廾,从斤。甲骨文字形,上面是斤”,是短斧之类;下面是廾”双手),象双手持斤。本义兵器,武器)', '小学', '1'),
    ('其', 'qí', '8', '八', '上下', NULL, '其〈名〉 通期”。期限 既辱且危,死其将至。--《易·系辞下》 其 〈代〉 (形声。甲骨文字形象簸箕形,即箕”本字。金文又加声符丌”,变成其”。本义簸箕。今字作箕”；组词：独善其身 她 它 或者不如说希望希望其有,又希望其无', '小学', '1'),
    ('具', 'jù', '8', '八', '上下', NULL, '具 (会意。甲骨文字形,上面是鼎”,下面是双手。表示双手捧着盛有食物的鼎器(餐具)。本义准备饭食或酒席)；组词：具食(准 具jù 1.器物器~', '小学', '1'),
    ('典', 'diǎn', '8', '八', '上下', NULL, '典 (会意。甲骨文字形,上面是册”字,下面是大。本义重要的文献、典籍) 同本义 典,五帝之书也...庄都说,典,大册也。；组词：药典；字典；释典(佛经)；法典；佛典；引经据典；典志(记载政 典 diǎn 1标准；法则~范、~型', '小学', '1'),
    ('养', 'yǎng', '9', '乺', '上下', NULL, '养 (形声。从食,羊声。本义饲养) 供养,奉养;抚育 养,供养也。--《说文》。古文从攴,未详。疑厮养作此字。 凡食养阴气也,凡饮养阳气也。--《礼记·郊特牲》 殳能生之不能养之；组词：养娇囡(因父母溺爱而性格骄纵的姑娘)；养家人(担负赡养全家生计的人)；养济院(孤老院 养(餬)yǎng 1.抚育,供给~', '小学', '1'),
    ('兼', 'jiān', '10', '乺', '上下', NULL, '兼 (会意。小篆字形,从又(手),从秝。字形象一手持两棵庄稼。本义一手执两禾。引申为同时进行几桩事情或占有几样东西) 同时具有或涉及几种事务或若干方面 兼,并也。', '小学', '1'),
    ('兽', 'shòu', '11', '乺', '上下', NULL, '兽 (象形。小篆字形。上象耳,中象头,下象足踩地。兽本是禽兽的总称。古另有玣”字,指捕捉禽兽的活动。二字通用。本义禽兽的总称) 四足的哺乳动物,多指野兽 兽,守备者。', '小学', '1'),
    ('冀', 'jì', '16', '八', '上下', NULL, '冀 (形声。从北,异声。本义冀州。古九州之一) 同本义 冀,北方州也。--《说文》 两河间曰冀州。--《尔雅·释地》 河内曰冀州。--《周礼·职方氏》。朱骏声曰地亘今盛京直隶山西', '小学', '1'),
    ('内', 'nèi', '4', '冂', NULL, NULL, '内〈名〉 里面。与外”相对 一室之内。--明·袁宏道《满井游记》 郗犹在帐内。--《世说新语·雅量》 东海家内则郝夫人之法,亲陵家内范钟夫人之礼；组词：海内；关内；内牵(内中传递消息者) 指某一群体或某一物体的中间', '小学', '1'),
    ('冈', 'gāng', '4', '冂', '半包围', NULL, '冈 (形声。从山,网声。本义山脊,山岭) 同本义 岡,山脊也。--《说文》。俗亦误作崗。 览高冈兮峣峣。--《楚辞·守志》。注山岭曰冈。” 山脊曰冈。冈,亢也,在上之言也；组词：山冈；冈陀(山冈)；冈子(低矮而坡度较小的山丘)；冈岑(小山峦)；冈崖(山岩)；冈岭(山岭) 冈(岡)gāng山脊景阳~', '小学', '1'),
    ('册', 'cè', '5', '丿', NULL, NULL, '册 (象形。金文、小篆字形与甲骨文相似,象简册形。本义书简。古代文书用竹简。编简名为册,后凡簿籍均可称册”)；组词：名册；画册；纪念册；册书(史籍,史书) 古时称编串好的许多竹简,现在指装订好的纸本子 特指皇帝的诏书 册 cè 1装订好', '小学', '1'),
    ('再', 'zài', '6', '冂', '上下', NULL, '再 (会意。小篆从一,冓省。冓”是构”的初文,甲骨文字形,象两部分材木架起的样子。本义第二次)', '小学', '1'),
    ('冒', 'mào', '9', '冂', '上下', NULL, '冒 (会意。小篆字形。上为帽子,下边是眼睛。本义帽子) 帽”的古字。帽子 著黄冒。--《汉书·儁不疑传》 白纱冒者,视朝、听讼、宴见宾客之服也。--《新唐书》；组词：冒絮(头巾) 古代殓尸的布囊,由上下两截合成 冒缁质,长与手齐', '小学', '1'),
    ('冕', 'miǎn', '11', '冂', '上下', NULL, '冕 (形声。从月,免声。月是蛮 夷及小儿的头衣”,免”是冕”的本字。本义古代帝王、诸侯及卿大夫所戴的礼帽)；组词：冠冕(古代帝王、官员戴的帽子)；冕弁(冕和弁', '小学', '1'),
    ('冗', 'rǒng', '4', '冖', '上下', NULL, '冗 ( 《说文》散也。从宀儿(人),人在屋下,无田事也。”儿,人”的古文形体。本义闲散)；组词：冗从(官名', '小学', '1'),
    ('写', 'xiě', '5', '冖', '上下', NULL, '写 (形声。从宀,舃声。本义移置;放置) 同本义 写,置物也。--《说文》。俗字亦作泻。 以浍写水。--《周礼·稻人》 牛弗进,则置虚命彻。--《左传·昭公四年》。注写器令空', '小学', '1'),
    ('军', 'jūn', '6', '冖', '上下', NULL, '军 (会意。金文字形,从车,从勹。表示用车子打包围圈的意思。古代打仗主要靠车战,驻扎时,用战车围起来形成营垒,以防敌人袭击。本义围成营垒)', '小学', '1'),
    ('农', 'nóng', '6', '冖', NULL, NULL, '农 (会意。甲骨文字形,从林,从辰。古代森林遍野,如要进行农耕,必先伐木开荒,故从林”;古代以蜃蛤的壳为农具进行耕耨,故从辰”。小篆认为从晨,囟声。从晨”,取日 出而作；组词：农家子(村野耕作之人)；农舆(耕作用的车)；农战(从事农耕,以为攻战之本)；农月(立夏以后 农(農、辳)nóng 1.种', '小学', '1'),
    ('冠', 'guàn', '9', '冖', '上下', NULL, '冠〈名〉 (会意。从冖”(用布帛蒙覆。从元”(人头),从寸”(手)。意思是手拿布帛之类的制品加在人的头上,即冠”。本义帽子)', '小学', '1'),
    ('冤', 'yuān', '10', '冖', '上下', NULL, '冤 (会意。从兔,从冖。冖”表示覆盖。兔子被覆盖住了,卷曲不能伸。或从冖,表示在房屋内。本义屈缩;不舒展)', '小学', '1'),
    ('冬', 'dōng', '5', '冫', '上下', NULL, '冬 (会意。表示时序终了,已进入寒冷季节。四季中的第四季,即农历十月至十二月) 一年四季中秋春之间的季节,天文学上认为是从12月至3月,农历十月到十二月 冬,四时尽也。；组词：冬暖夏凉；冬酿(冬季酿酒)；冬温(冬天所害的一种热病)；冬计(寒冬的生计) 冬月,阴历十一月的俗称 适冬(阴历十一月)之', '小学', '1'),
    ('冯', 'féng', '5', '冫', '左右', NULL, '冯 古地名 郑于是乎伐冯、滑、胥靡,负黍、狐人、阙外。--《左传·定公六年》 姓 冯 (形声。从马,冫声。冫,古冰字的楷书写法。本义马跑得快)；组词：冯冯(马行疾速的样子) 大,盛 今君奋焉震电冯怒', '小学', '1'),
    ('冰', 'bīng', '6', '冫', '左右', NULL, '冰 (会意。从仌,从水。金文作仌”。金文字形表示水凝成冰后,体积增大,表面上涨(上拱)形。《说文》冻也,象水凝之形”。小篆繁化,增加水”变成。从仌”从水” 的会意字；组词：冰扳(冰镇)；冰麝(冰片与', '小学', '1'),
    ('冲', 'chōng', '6', '冫', '左右', NULL, '冲 (形声。从水,中声。本义向上涌流) 同本义 冲溶沅瀥。--木华《海赋》 直上 又如冲天(直上天空);冲汉(直上霄汉) 以水、酒等浇注调制 幸而后手里渐渐翻过来了,除了冲账的；组词：冲天(直上天空)；冲汉(直上霄汉) 以水、酒等浇注调制 幸而后手里渐渐翻过来了,除了冲账的,反赢了好些--《红楼梦》 又', '小学', '1'),
    ('决', 'jué', '6', '冫', '左右', NULL, '决 (形声。从水,夬声。本义疏通水道,使水流出去) 同本义 自河决瓠子后,二十余岁,岁因以数不登。', '小学', '1'),
    ('况', 'kuàng', '7', '冫', '左右', NULL, '况 (形声。从水,兄声。本义寒冷的水) 同本义 況,寒水也。--《说文》。段玉裁注未得其证。...古矧兄、比兄,皆用兄字;后乃用況字,后又改作况。” 情形；组词：况味(境况情味', '小学', '1'),
    ('冶', 'yě', '7', '冫', '左右', NULL, '冶 (形声。从冫(古冰”字),台声。以冰融化解释金属销熔。段玉裁冰之融如铄金然,故炉铸亦曰冶。”本义销熔)；组词：冶铸(冶炼铜铁,铸造器物)；冶锻(冶炼)；冶人(犹冶工)；冶工(铸造金属器物的工人)；冶士(古代从事冶炼铸造的刑徒) 陶', '小学', '1'),
    ('冷', 'lěng', '7', '冫', '左右', NULL, '冷〈形〉 (形声。从仌,冰,令声。本义凉) 同本义 冷,寒也。--《说文》 画堂鹦鹉鸟,冷暖不相知。--白居易《乌夜啼》；组词：冷香(清雅的香气)；冷泉(清凉的泉水)；冷翠(给人以清凉感的翠绿色) 寒冷 布衾多年冷似铁', '小学', '1'),
    ('冻', 'dòng', '7', '冫', '左右', NULL, '冻 (形声。从仌,东声。本义结冰) 同本义 冻,仌也。--《说文》 壮冰曰冻。--《风俗通》 水始冰,地始冻。--《礼记·月令》 风掣红旗冻不翻；组词：冻柱(冻住)；冻浦(结了冰的河川) 受冻；感到寒冷 夜冻寒', '小学', '1'),
    ('净', 'jìng', '8', '冫', '左右', NULL, '净 (形声。从水,争声。本义春秋时鲁国北城门争门”的护城河) 同本义 净,鲁北城门池也。--《说文》。按,北城之门曰净门,当因池水名净而命也。公羊传所谓鹿门、争门、吏门；组词：窗明几净；白净(白而洁净)；净本(唐 净(凈、渜)jìng 1.清洁干~', '小学', '1'),
    ('凄', 'qī', '10', '冫', '左右', NULL, '凄 (渄俗作凄”。形声。从水,妻声。本义云雨兴起的样子) 同本义 渄,雨云起也。--《说文》 有渰渄渄。--《诗·小雅·大田》；组词：凄凄(云兴起的样子) 寒冷 渄其以风', '小学', '1'),
    ('准', 'zhǔn', '10', '冫', '左右', NULL, '准 (准本为凖的俗字,现为凖的简化字。但在未简化前,准习用的意义,与凖字有别) 公文用语 乃于战所,准当时兵士,人种树一株,以旌武功。；组词：批准；照准；准如所请 (2) 引申为比照,作某类事物看待', '小学', '1'),
    ('凉', 'liáng', '10', '冫', '左右', NULL, '凉 (形声。从水,京声。本义寒) 同本义 北风其凉。--《诗·邶风·北风》 北风谓之凉风。--《尔雅·释天》 凉风至。--《礼记·月令》 凉雨时降。--《素问·五常政大论》 凉州；组词：冬暖夏凉；凉生生(微凉貌 凉(涼)liáng 1.稍冷,微寒,温度低~粉', '小学', '1'),
    ('凌', 'líng', '10', '冫', '左右', NULL, '聆〈动〉 (形声。从耳,令声。本义细听) 同本义 聆广乐之九奏兮。--张衡《思玄赋》 宝玉接过来,一面目视其文,耳聆其歌。；组词：聆偈(听经)；聆受(倾听并接受)；聆训(听受训教)；聆教(聆听教晦)；聆音察理(听到声音就能明察事理) 明了,清楚 观读', '小学', '1'),
    ('减', 'jiǎn', '11', '冫', '左右', NULL, '减 (形声。从水,咸声。本义减少,由全体中去掉一部分) 同本义 减,渻也。--《说文》 减,少也。--《广雅》 减,尽也。--《管子·宙合》 谮始既减。--《韩诗·巧言》。传少也；组词：减算(减少税收；减少年寿)；减膳(吃素或减少菜肴)；减了口里的(减少饮食) 不足；不到；少于 减(減)jiǎn 1.减少', '小学', '1'),
    ('凑', 'còu', '11', '冫', '左右', NULL, '凑 (形声。从水,奏声。本义水流会合) 同本义 凑,水会也,聚也。--《广韵》 凑,水上人所会也。--《 说文》。 顺波凑而下降。--《楚辞·九叹·逢纷》。注聚也；组词：凑队(集合在一起)；凑聚(集合,聚集)；凑泊(凝聚,结合)；凑会(聚集,会合) 奔向；趋 衰世凑学', '小学', '1'),
    ('凛', 'lǐn', '15', '冫', '左右', NULL, '凛凛 (形声。从仌冰。禀声。本义剌骨的寒冷) 同本义 皉,寒也。从欠,? 其性为凛。--《素问·五运行大论》。注寒也。肾之性也。” 寒则凛冻。--《风俗通·究通》 凛凛寒风升；组词：凛冽(非钞冷)；凛栗(因寒冷而颤抖)；凛秋(寒冷的秋天)；凛气(寒气)；凛寒(寒冷) 严肃而可敬畏 凛者,颜色惧貌', '小学', '1'),
    ('凝', 'níng', '16', '冫', '左右', NULL, '耵聍”耳垢 凝níng 1.物体由气体变为液体或液体变为固体~结。~固。~气结为霜。 2.聚集,集中~聚。~集。~神。~视。 3.厚,盛~重。~妆。 4.稳定,巩固坚~。', '小学', '1'),
    ('几', 'jǐ', '2', '几', '左右', NULL, '几 (象形。本义古人席地而坐时有靠背的坐具) 同本义 几,坐所以凭也。--《说文》 掌五几五席之名物。--《周礼·司几筵》。注五几左右玉雕彤漆素。” 室中度以几,堂上度以筵；组词：几杖(供老人依靠的小桌子和支撑用的手杖', '小学', '1'),
    ('凡', 'fán', '3', '几', '半包围', NULL, '凡 (象形。金文字形,象造器之模范形。1本义铸造器物的模子。2引申义凡是,表示概括) 凡是,一切 凡,皆也。；组词：凡有(一切；所有)；凡此(所有这些) 总共 凡(刦) fán 1.所有的,总共,总计~是', '小学', '1'),
    ('凤', 'fèng', '4', '几', '半包围', NULL, '凤 (形声。从鸟,凡声。本义凤凰。中国古代传说中的百鸟之王。常用来象征祥瑞。雄的叫凤,雌的叫凰)；组词：凤求凰；凤子(绣有凤凰的轿子)；凤舸(雕有凤凰的大游船)；凤毛(凤凰的羽毛', '小学', '1'),
    ('凫', 'fú', '6', '几', '上下', NULL, '凫 动物名。俗名野鸭 凫,水鸭也。--《广韵》 另一说凫是家鸭” 又如凫雏(幼凫);凫雁(野鸭与大雁);凫胫(野鸭的小腿) 凫 浮游;泅水 凫(鴇) fú 1.俗称"野鸭"；组词：凫雏(幼凫)；凫雁(野鸭与大雁)；凫胫(野鸭的小腿) 凫 浮游；泅水 凫(鴇) fú 1.俗称"野鸭"', '小学', '1'),
    ('凭', 'píng', '8', '几', '上下', NULL, '凭 (会意。从几,从任。几,矮而小的桌子。任,凭借。本义倚靠) 同本义 恁,依也。--《小尔雅》 某自幼与周郎同窗交契,愿凭三寸不烂之舌,往江东说此人来降；组词：凭几(凭靠几案)；凭肩(以手靠在别人肩上)；凭脉(搭脉) 依托；仰仗 不凭其子,灵公夺而里之', '小学', '1'),
    ('凯', 'kǎi', '8', '几', '左右', NULL, '凯 (会意,从豰,从几。几”象架子。字本作豰”,也作愷”。从豆,省声。本义军队得胜所奏的乐曲)；组词：凯入(奏着胜利的乐曲归来)；凯(刾)kǎi 1.军队打胜仗后所奏的乐曲~歌', '小学', '1'),
    ('凰', 'huáng', '11', '几', '半包围', NULL, '凰 中国古代传说中的鸟名,雄的叫凤”,雌的叫凰” 凰(〈古〉写作"皇")huáng', '小学', '1'),
    ('凳', 'dèng', '14', '几', '上下', NULL, '凳 凳子 床前踏具 床凳之凳,晋已有此器。--宋·吴曾《能改斋漫录》 供坐的无背家具。如方凳 具有水平顶面的长工作台 凳 dèng没有靠背的坐具。', '小学', '1'),
    ('凶', 'xiōng', '4', '凵', '半包围', NULL, '凶 (指事。小篆字形,凵”象地陷形。乿”表示这里可陷人。兇”是会意字,从儿(人),在凶下。本义不吉利)；组词：凶兆(不祥的预兆)；凶宿(凶星)；吉凶未卜；凶星(不吉祥的星) 凶恶可怕 作凶事,为凶人', '小学', '1'),
    ('凸', 'tū', '5', '凵', NULL, NULL, '凸〈形〉 高出 凸凹(高低不平);凸杯(满杯);凸岸;凸镜;凸透镜 凸〈动〉 使突出于周围表面或范围之外 伸出;突出 凸tū周围低,中间高。跟"凹"相对~形。这是~透镜。', '小学', '1'),
    ('凹', 'āo', '5', '凵', NULL, NULL, '凹〈形〉 周围高,中间低 ,跟"凸"相反~面。 其湖无凹凸,平湖无高下。--《神异经·北方荒经》 又如凹岸;凹面;凹洼(凹陷);凹地;凹处 凹wā 1.亦用于地名。山西省有核桃凹。', '小学', '1'),
    ('出', 'chū', '5', '凵', '上下', NULL, '出 (象形。象草木益滋上出达之形。本义长出) 同本义 出,进也。象草木益滋,上出达也。--《说文》。按,《说文》讲的出”,其实是茁。 句者毕出,萌者尽达', '小学', '1'),
    ('击', 'jī', '5', '凵', NULL, NULL, '击 (形声。从手,毄声。本义敲击,敲打) 同本义 欲以击柱。--《史记·廉颇蔺相如列传》 不肯击缻。 留击柝者。--《资治通鉴·唐纪》 使击柝如故。 援玉 枹兮击鸣鼓；组词：击壤(相传尧时有老人击壤而歌曰日出而作,日入而息,凿井而饮,耕田而食,率力于我何有哉?后因以比喻太平盛世)；击节(打拍子', '小学', '1'),
    ('函', 'hán', '8', '凵', NULL, NULL, '函 (象形。今隶误作函。本义舌) 同本义 圅,舌也。--《说文》 若合而函吾中。--《国语·楚语》。注入也。”按,如舌之在口中也。 口上曰臄,口下曰圅。--《通俗文》 噱,圅舌也；组词：蒋；镜函 传达消息或指示的信件(古代寄信用木函) 邮政 信封 发函伸纸,...', '小学', '1'),
    ('凿', 'záo', '12', '凵', '半包围', NULL, '凿 (形声。从金,鑿省声。从金,表示与金属制品有关。本义凡穿物使通都称凿) 同本义 凿,穿木也。；组词：凿巾(在覆盖死者脸部的巾上,正对口部的位置,剪开一通孔)；凿穴(开造洞穴) 挖掘；开凿 凿地为坎', '小学', '1'),
    ('刀', 'dāo', '2', '刀', NULL, NULL, '刀 (象形。小篆字形,象刀形『字部首之一。本义古代兵器名) 同本义 刀,兵也。象形。--《说文》 刀,到也,以斩伐到其所乃击之也。--《释名》 刀光照塞月,阵色明如昼；组词：刀枪；刀兵；刀瘢(刀伤的褊)', '小学', '1'),
    ('刁', 'diāo', '2', '刀', NULL, NULL, '刁 古代行军用具。一种有柄的小斗,白天可供一人烧饭,夜间敲击以巡更 刁 狡猾,奸诈 乖巧,机灵 这话实在刁的,说到我心里了。', '小学', '1'),
    ('刃', 'rèn', '3', '刀', '半包围', NULL, '刃 (指事。小篆字形,在刀上加一点,表示刀锋所在。本义刀口,刀锋) 同本义 刃,刀坚也。象刀有刃之形。；组词：刀刃；迎刃而解 刀剑一类利器 铸金而为刃', '小学', '1'),
    ('分', 'fēn', '4', '刀', '上下', NULL, '分〈动〉 (会意。从八,从刀。八”就是分;从刀”,是以刀剖物,使之分开的意思。本义一分为二)；组词：分合(分开与合并)；分地(分割土地；分封土地)；分间(分开,间隔)；分灶(分家度日) 辨 分 fēn 1.划,划开,跟"', '小学', '1'),
    ('切', 'qiē', '4', '刀', '左右', NULL, '切 通砌”。台阶 切皆铜沓黄金涂。--《汉书·外戚·孝成赵皇后传》 切 (形声。从刀,七声。本义用刀把物品分成若干部分)', '小学', '1'),
    ('刊', 'kān', '5', '刂', '左右', NULL, '刊 (形声。从刀,干声。本义砍,砍削) 同本义 刊,剟也。--《说文》 刊,削也。--《广雅》 刊阳木而火之。--《周礼·柞氏夏日至令》。注谓斫去次地之皮。” 刊其柄与末；组词：刊山(砍伐山上树木)；刊木(砍伐树木)；刊藄(砍伐割除草木) 删除 诚不刊之典', '小学', '1'),
    ('刑', 'xíng', '6', '刂', '左右', NULL, '刑 同本义 利用刑人。--《易·蒙》。注兑折为刑。” 刑人之父子也。--《吕氏春秋·顺说》。注杀也。” 杀戮之谓刑。--《韩非子·二柄》 阴为刑。--《易·本命》 阴将始刑；组词：刑牛(古代盟誓时作牺牲用的牛)；刑牲(古时为了祭祀或盟约而杀牲畜)；刑马(古代结盟要杀马歃血,立誓为信,称刑马”) 惩罚', '小学', '1'),
    ('划', 'huá', '6', '刂', '左右', NULL, '划〈动〉 以桨拨水使船前进 合算 指二人伸指猜拳行酒。也作豁拳” 划 〈名〉 划子,小船 划 用尖利物把东西割开 摩擦', '小学', '1'),
    ('列', 'liè', '6', '刂', '左右', NULL, '列〈动〉 (形声。从刀,本义割,分) 裂”的古字。分割;分解 列,分解也。--《说文》 古者列地建国。--《荀子》 大袂列。--《管子·五辅》。注决之也。” 两骖列两服入厩；组词：列断(裂断)；列地(列土', '小学', '1'),
    ('刘', 'liú', '6', '刂', '左右', NULL, '刘 (形声。从金,从刀,乯声。本义杀,戮) 同本义(含有大规模杀戮的意思) 胜殷遏刘,耆代尔功。', '小学', '1'),
    ('则', 'zé', '6', '刂', '左右', NULL, '则 (会意。金文从鼎,从刀。古代的法律条文曾刻铸在鼎上,以便让人遵守。本义准则,法则) 同本义 则,等画物也。；组词：则天(以天为 则zé 1.规则,规律,制度准~', '小学', '1'),
    ('刚', 'gāng', '6', '刂', '左右', NULL, '刚 (形声。从刀,冈声。本义坚硬) 同本义 刚,坚也。--《增韵》 刚,彊断也。--《说文》 挢然刚折。--《荀子·臣道》 断之以刚。--《左传·昭公六年》 柔则茹之,刚则吐之；组词：刚巨(坚硬锐利的爪)；刚条(坚硬的树枝)；刚木(木质坚硬的树木)；刚土(硬土) 坚强 刚,强也', '小学', '1'),
    ('创', 'chuàng', '6', '刂', '左右', NULL, '创 (指事。从刀,仓声。金文,象一个躺着的人,手上脚上都有小竖,表示受了创伤,是个指事字。本义创伤,伤口)；组词：身受重创；创痕(伤痕)；创病(伤病)；创残(伤残)；创瘢(伤疤) 疮疖', '小学', '1'),
    ('初', 'chū', '7', '刀', '左右', NULL, '初〈名〉 (会意。从刀,从衣∠起来表示用刀剪裁衣服是制衣服的起始。本义起始,开端) 同本义 初,始也。裁者衣之始也。；组词：初岁(年初)；初枯(秋季里植物开始枯萎)；初头(起初；开头)；初化(变化之始)；初末(始末) 本原 欲知', '小学', '1'),
    ('删', 'shān', '7', '刂', '左右', NULL, '删 (会意。从刀从册。册是简册,把若干竹简编穿在一起叫册”。简册的内容有问题,就用刀除掉,所以从刀”。本义削除) 削除;勾划掉 删,剟也。；组词：增删(增加和删去)；删存(经过删除保留下来)；删裁(删除)；删弃(删除,删去)；删割(删去)；删繁(删除繁冗之言)；删抹', '小学', '1'),
    ('判', 'pàn', '7', '刂', '左右', NULL, '判〈动〉 (形声兼会意。从刀,半声。从刀,表明其意义与刀有联系。半”是把牛分开。本义分,分开)；组词：判割(分割)；判妻(丈夫去世或与丈夫离异后再嫁的妇女)；判散(分散)；判礼(分离；分开)；判迹(分道而行)；判裂(割裂', '小学', '1'),
    ('刨', 'páo', '7', '刂', '左右', NULL, '刨 刨子 刨床”的简称 刨 用刨子或刨床刮平木材或钢材等 刨床 用于金属材料的平面加工和各种直线的成型面的加工的一种机床 刨子上的木制部分 刨刀 刨光 刨花 刨花板 刨 bào 1', '小学', '1'),
    ('利', 'lì', '7', '刂', '左右', NULL, '利〈形〉 (会意。从刀,从禾。表示以刀断禾的意思。本义刀剑锋利,刀口快) 同本义 利铦也。；组词：利爪；利喙(尖利的嘴)；利矢(锋 利lì 1.好处,益处,跟"害"、"弊"相对~益', '小学', '1'),
    ('别', 'bié', '7', '刂', '左右', NULL, '别 (会意。从冎,从刀。冎”,《说文》剔人肉置其骨也。”别”的小篆形体,是一个表示用刀剔骨头的会意字。本义分解)；组词：别割(分割)；别产(分割家产；分家)；别国(从一国分化而成的国家；现常指别的国家) 分离；分开；分出 岷山导江,东别为沱', '小学', '1'),
    ('刮', 'guā', '8', '刂', '左右', NULL, '刮〈动〉 (形声。小篆作字形,从刀。本义削,用刃平削物体,或把物体表面的某些东西去掉) 同本义 刮,掊杷也。；组词：刮毒(刻毒,狠毒)；刮子(耳光)；刮刷(刮除干净)；刮垢磨光；刮楹(刮削摩擦过的柱子)；刮锅子；刮磨(磨练)；刮摩(琢磨', '小学', '1'),
    ('到', 'dào', '8', '刂', '左右', NULL, '到 (形声。从至,刀声。本义到达,达来,去到) 同本义 到,至也。--《说文》 靡国不到。--《诗·大雅·韩奕》 虽隆薛之城到于天。--《战国策·齐策》 朝发白帝,暮到江陵；组词：到时(到达之时)；飞机半夜到北京；官员到后,会就开始了；到头来(结果；后来) 颠倒', '小学', '1'),
    ('制', 'zhì', '8', '刂', NULL, NULL, '制 制、製本同一词,后来分化,製”用于具体的制 造,制”且于抽象的制作。(会意。小篆字形,左边是未”,右为刀。未”即有滋味,乐于裁制。本义裁断;制作)；组词：制割(裁剪切割)；制义(制宜,裁断适宜)；轧制；机制；仿制；自制；试制；研制(研究制造)；配制；提制(提炼制造)；精制', '小学', '1'),
    ('刷', 'shuā', '8', '刂', '左右', NULL, '刷 (形声。本义清扫;揩拭;冲洗) 同本义 刷,刮也。礼有刷巾。--《说文》 刷羽汎清源。--《文选·沈约和谢宣城诗》 旦刷幽燕,昼秼荆越。--颜延之《赫白马赋》 秋刷；组词：刷刮(擦拭)；刷涤(洗刷；洗除)；刷刨(刮擦；刷拭)；刷剃(擦眼泪) 清除；洗雪 王虽东取地于越,不足以刷耻', '小学', '1'),
    ('券', 'quàn', '8', '刀', '上下', NULL, '券〈名〉quan (形声。 券要分成两半,故从刀”。本义契据) 同本义。古代用于买卖或债务的契据。书于简牍,常分为两半,双方各执其一,以为凭证◇用纸帛书写 券,契也；组词：券契(契据)；券要(契约)；券约(契据)；券书(契约,文书)；券剂(契据；凭证)；券证(契据) 可作凭证的物件；票证 比', '小学', '1'),
    ('刹', 'shā', '8', '刂', '左右', NULL, '刹 cha (形声,从刀,杀声。梵语刹多罗的省称。本义土或土田,国土) 同本义 指佛寺 梵语 ksana 的音译。表示极短促的瞬间 刹〈动〉sha 止住,使停止(机器', '小学', '1'),
    ('刺', 'cì', '8', '刂', '左右', NULL, '刺 激烈的撞击或爆炸声 刺 (形声。从刀,朿声。本义扎入,用尖利的东西刺) 同本义 君杀大夫曰刺。刺,直伤也。；组词：刺焚(刺股、焚膏之略词,比喻刻苦攻读)；刺子(暗剑)；刺心(以刀等刺进心脏', '小学', '1'),
    ('刻', 'kè', '8', '刂', '左右', NULL, '刻〈动〉 (形声。从刀,亥声。本义雕刻,在木头上雕刻) 同本义 刻,镂也。--《说文》 金谓之镂,木谓之刻。--《尔雅·释器》 器不刻镂。--《礼记·哀公问》 二十四年春,刻其桷；组词：刻图章；刻刀(雕刻所用的刀具)；刻木(在木质器物上雕刻)；刻饰(雕刻装 刻kè 1.雕,刀子挖,铁笔划雕~', '小学', '1'),
    ('刽', 'guì', '8', '刂', '左右', NULL, '刽 割断,砍断 刽,断也。从刀,会声。今大辟刑人之隶。俗语谓之刽子手。--《说文》 刽刖困于赤绂。--京房本《易·困》 刽子磨旗提刀,押正旦带枷上。--《窦娥冤》；组词：刽子(执行死刑的人)；刽伍(刽子手之辈) 刽(劊)guì 1.砍断', '小学', '1'),
    ('剂', 'jì', '8', '刂', '左右', NULL, '剂 (会意。从刀,齐声。齐”亦兼表字义。本义剪齐) 同本义 剂,齐也。--《说文》 剂,剪齐也。--《后汉书·刘梁传》注 其命剂也。--《太玄·永》。注剪绝也。” 永不轨；组词：调剂；剂和(调药；调和)；剂救(调和弥补)；剂调(调节) 剂 古代买卖时用的契券 以两剂禁民狱', '小学', '1'),
    ('剃', 'tì', '9', '刂', '左右', NULL, '剃〈动〉 用刀刮去毛发 鬀,剃发也。大人曰髡,小儿曰鬀,尽及身毛曰鬄。--《说文》 后来写作剃” 剃,同鬀。--《广韵》；组词：剃胡子；剃汗毛；剃得干净；剃光头；剃削(剃去毛发)；剃面；剃工；剃平头；剃刀 剃度出家 如剃落(剃发', '小学', '1'),
    ('削', 'xuē', '9', '刂', '左右', NULL, '削 曲刀,书刀,削刀 削书刀也。--《曲礼·金工》注 东周和秦汉时用来除去书写在木牍或竹简上的错字。；组词：削刀(书刀) 简札 削 斜着刀略平地切去物体的表层 削则削', '小学', '1'),
    ('前', 'qián', '9', '刂', '上下', NULL, '前〈动〉 (本义前进) 同本义 前,进也。--《广雅》 然而驱之不前,却之不止。--《韩非子·外储说右上》 相如视秦王无意偿赵城,乃前曰。--《史记·廉颇蔺相如列传》 罗敷前致词；组词：前却(进退)；前迈(前行,前进)；前旌(仪仗中前行的旗帜) 引导 尸谡祝前', '小学', '1'),
    ('剑', 'jiàn', '9', '刂', '左右', NULL, '剑 (形声。从刀,佥声。本义古代兵器。长刃两面,中间有脊,短柄) 同本义 劒,人所带兵也。；组词：剑锷(剑的锋刃)；剑首(剑环', '小学', '1'),
    ('剔', 'tī', '10', '刂', '左右', NULL, '剔〈动〉 (形声。从刀,易声。本义分解骨肉,把肉刮下) 同本义 剔,解骨也。--《说文》。按,即为鬄之或体。 去骨曰剔。--《通俗文》；组词：剔股；剔肉；剔骨头 挑；拔 斜拔玉钗灯影畔,剔开红焰救飞蛾', '小学', '1'),
    ('剖', 'pōu', '10', '刂', '左右', NULL, '剖〈动〉 (形声。从刀,咅声。本义破开,中分) 同本义 剖,判也。--《说文》 剖,分也。--《广雅》 剖伛之背。--《战国策·宋策》。注劈也。” 比干剖。--《庄子·胠箧》；组词：剖心(破开胸腹以割心；开布诚心,竭诚相见)；剖判(分割,破开；辨析)；剖列(分列)；剖割(分割)；剖肝沥胆( 剖pōu', '小学', '1'),
    ('剥', 'bāo', '10', '刂', '左右', NULL, '剥 或剥或烹。--《诗·楚茨》 又如剥花生;剥碗豆;剥牛皮;剥葱皮 剥 bāo 去掉外面的皮壳~豆子。又见bō。 剥 bō义同''剥''(bāo)专用于合成词或成语~落。又见bāo；组词：剥花生；剥碗豆；剥牛皮；剥葱皮 剥 bāo 去掉外面的皮壳~豆子', '小学', '1'),
    ('剧', 'jù', '10', '刂', '左右', NULL, '剧 (形声。本义甚;厉害,严重) 同本义 剧,甚也。--《文选》注引《说文》。朱骏声曰即勮字之误文。” 何其剧欤。--《剧秦美新》 口吃不能剧谈。--《汉书·扬雄传》 即疾剧；组词：剧论(激烈的论辩)；剧难(激切地质问论难)；剧疵(严重的过失)；剧暑(酷暑)；剧寒(严寒)；剧艰(激烈诘难)；剧药(毒性', '小学', '1'),
    ('剩', 'shèng', '12', '刂', '左右', NULL, '剩 (形声。从刀,乘声。本义剩余;余下) 同本义 一屠晚归,担中肉尽,止有剩骨。--《聊斋志异·狼三则》 使野无闲田,民无剩力。--清·洪亮吉《治平篇》；组词：剩员(多余的人员)；剩语(多余的话)；剩货 多 且容侬,多种竹,剩栽梅', '小学', '1'),
    ('剪', 'jiǎn', '11', '刀', '上下', NULL, '剪 (形声。从刀,前声。本义用剪刀铰断) 同本义。本作前”,通作翦”,俗作剪” 剪,齐断也。；组词：剪截铺(衣料店)；剪筒(存放剪掉的蜡花的用具)；剪直(直截了当,径直)；剪断(亦作简断”', '小学', '1'),
    ('副', 'fù', '11', '刂', '左右', NULL, '副〈动〉 (形声。从刀,畐声。本义用刀剖开。《说文》判也。”《诗·大雅》不坼不副。”) 相称,符合 盛名之下,其实难副。--李固《遗黄琼书》；组词：名副其实；副顺(顺应,随顺) 交付,付与 只恐重重世缘在,事须三度副苍生', '小学', '1'),
    ('割', 'gē', '12', '刂', '左右', NULL, '割〈动〉 (形声。从刀,害声。本义用刀分解牲畜的骨肉) 同本义。泛指用刀截断 割,断也。--《广雅·释诂一》 割鸡焉用牛刀。--《论语·阳货》 犹未能操刀而使割也；组词：割鲜(割杀畜兽)；割烹(割切烹调)；割刀(切割之刀) 放弃 分割；割取 东割膏腴之地', '小学', '1'),
    ('剿', 'jiǎo', '13', '刂', '左右', NULL, '勦 剿 抄袭 毋剿说,毋雷同。--《礼记·曲礼上》 又如剿拾(袭取);剿袭(剽窃人言以为己说) jiao 剿〈动〉 (形声。从刀,巢声。本义劳累,使辛勤劳累)；组词：剿拾(袭取)；剿袭(剽窃人言以为己说) jiao 剿〈动〉 (形声', '小学', '1'),
    ('劈', 'pī', '15', '刀', '上下', NULL, '劈〈动〉 (形声。从刀,辟声。本义破开;分割) 同本义 劈,破也。--《说文》 劈,分也。--《广雅》 劈,剖也。--《埤苍》 以刀劈狼首。--《聊斋志异·狼三则》；组词：劈心(剖心)；劈半儿(分做两半)；劈拉(成八字分开)；劈笺(裁纸)；劈空(划破长空) 俗称雷击为劈” 正对着；冲着 便', '小学', '1'),
    ('力', 'lì', '2', '力', NULL, NULL, '力〈名〉 (象形。甲骨文字形,象耒形,有柄有尖,用以翻地。用耒表示执耒耕作需要花费力气。力”是汉字部首之一。本义体力,力气)', '小学', '1'),
    ('劝', 'quàn', '4', '力', '左右', NULL, '劝 (形声。从力,雚声。简化字中又”仅是一个符号。本义勉励) 同本义 劝,勉也。--《说文》 劝防之事。--《周礼·丧祝》。司农注劝防引柩也。” 则楚之应之也,必劝；组词：劝进(劝勉,策进)；劝蚕(勉励种桑养蚕)；劝戒(劝勉警戒 劝(勸)quàn 1.讲明事理,使人听从~说', '小学', '1'),
    ('办', 'bàn', '4', '力', NULL, NULL, '办 (形声。从力,辡声。力取致力之意。本义办理;治理) 同本义 办,致力也。--《说文新附》 卿能办之者诚决。--《资治通鉴》；组词：办案；办事；办理 做,干 吾已无事可办,惟待死期耳', '小学', '1'),
    ('功', 'gōng', '5', '力', '左右', NULL, '功 (会意。从力,工声。工”亦兼表字义,表示用力从事工作。本义功绩,功业;功劳) 同本义 功,以劳定国也。；组词：功誉(功绩与声誉)；功行(功绩与德行)；功化(功业与教化)；功成名就(建立了功业,才有名声◇指功绩、名声皆得) 事情；工', '小学', '1'),
    ('加', 'jiā', '5', '力', '左右', NULL, '加〈动〉 (会意。从力,从口。本义添枝加叶说假话、虚报) 同本义 加,语相增加也。--《说文》 君子称其功以加小人。--《左传·襄公十三年》 我不欲人之加诸我也；组词：加叶添枝(加油添醋,加油加醋,加油添酱', '小学', '1'),
    ('务', 'wù', '5', '力', '上下', NULL, '务 (形声。从力,務声。从力,表示要致力于某事。本义致力,从事) 同本义 非务相反也。--《吕氏春秋·察今》 欲富国者,务广其地。--《战国策·秦策一》 务耕织；组词：务能(竭力)；务精(极力求精；精益求精)；务穑(务农)；务法(致力于法治)；务本(专心致力于根本)；务外(谓研究学问,只', '小学', '1'),
    ('劣', 'liè', '6', '力', '上下', NULL, '劣〈形〉 (会意。从力,从少。这是合并两个字的意思而构成的会意字。本义弱;小) 同本义 劣,弱也。；组词：劣马(瘦弱的马；又指烈性马)；劣弱(衰弱；懦弱) 少,不足 夫德劣故用兵,犯法故施刑', '小学', '1'),
    ('动', 'dòng', '6', '力', '左右', NULL, '动 (形声。从力,重声。《说文》古文从辵”。本义行动;发作) 同本义 动,作也。--《说文》 动而健。--《易·彖传》。虞注震也。” 效天下之动者也。--《易·系辞》。虞注发也；组词：按兵不动；动着(开始下棋)；动止(行动和静止；训练调度)；动烦(爆发战乱)；动转(行动,活动) 摇动,震动,移动', '小学', '1'),
    ('助', 'zhù', '7', '力', '左右', NULL, '助 (形声。从力,且声。助人要用力,故从力。本义帮助) 同本义(在物质上或精神上给予协助) 助,左也。；组词：助胆(帮助壮胆)；互助(互相帮助)；扶助(帮助)；资助(用财物帮助)；助力(帮助；援助) 助zhù 1.辅助；帮助', '小学', '1'),
    ('努', 'nǔ', '7', '力', '上下', NULL, '努〈动〉 (形声。从力,奴声。本义勉力,出力) 同本义 少壮不努力,老大徒伤悲。--《乐府诗集·长歌行》；组词：努筋拔力(竭尽全力；费了很大的力) 向外突出 却才见押司努嘴过来', '小学', '1'),
    ('劫', 'jié', '7', '力', '左右', NULL, '劫 (会意。从力,去声。本义以强力使对方欲去而不得) 威胁;威逼 劫,人欲去,以力胁止,曰劫。；组词：劫杀(劫持并加以杀害)；劫略(以威力胁迫于人)；劫盟(以暴力逼人缔结盟约)；劫质(挟持人质,借此勒索) 抢夺；强取 乃欲', '小学', '1'),
    ('励', 'lì', '7', '力', '左右', NULL, '励 (形声。从力,厉声。本义勉力,努力) 同本义 勵,勉力也。--《说文》。 用勵相我邦家。--《书·立政》 庶明励翼。--《书·皋谟》 励于一言。--《鬼谷子·决篇》；组词：砺翼(勉力辅佐君主,精勤以行君命)；励志(勉励其心志；集中心思于某种事业)；励节(勉力志行,崇尚气节) 振作 处遂改励', '小学', '1'),
    ('劲', 'jìn', '7', '力', NULL, NULL, '劲 (形声。从力,坙声。1本义强劲有力。2力气) 力量,力气 精神;情绪 神情;态度 趣味;兴趣 指某种程度,限度 劲(勁)jìng 1.正直,挺拔,坚强有力~士。~松。~草', '小学', '1'),
    ('劳', 'láo', '7', '力', '上下', NULL, '劳 (会意。小篆字形,上面是焱,即焰”的本字,表示灯火通明;中间是冖”字,表示房屋;下面是力”,表示用力。夜间劳作。本义努力劳动;使受辛苦)；组词：劳心焦思(苦思苦想)；劳民(劳役人民)；劳民动众(动用众多民力去做某件事)；劳师(使军队劳累；劳军) 烦劳；麻烦 劳各位', '小学', '1'),
    ('势', 'shì', '8', '力', '上下', NULL, '势 (形声。从力,埶声。本义权力;权势) 同本义 富者得势益彰,失势则客无所之。--《史记·货殖列传序》 有势家朱丹其门,闻瑞至,黝之。--《明史·海瑞传》；组词：势家(有权势的豪家大族)；失势(失去权势)；权势(权柄和势力)；势子(趋炎附势的人)；势利(权势和利益)；势任(掌握权势', '小学', '1'),
    ('勃', 'bó', '9', '力', '左右', NULL, '勃 (形声。从力,孛声。本义排,推动) 同本义 勃,排也。--《说文》 勃,展也。--《广雅》。今苏俗语以力旋转物曰勃。；组词：勃郁(风回旋的样子；郁结)；勃屑(即勃窣) 勃 兴起；旺盛 气喷勃以布覆兮', '小学', '1'),
    ('勇', 'yǒng', '9', '力', '上下', NULL, '勇 (本作勈,或作恿。形声。从力,甬声。从力,与力气有关。本义果敢,胆大) 同本义 勇,气也。；组词：忠勇(忠诚而勇敢)；英勇(勇敢出众)；勇悍(勇敢强悍)；勇烈(勇敢猛烈)；勇夫(勇敢的人) 勇yǒng 1.敢干,有胆量', '小学', '1'),
    ('勉', 'miǎn', '9', '力', '半包围', NULL, '勉 (形声。从力,免声。本义力所不及而强作) 同本义 勉,彊也。--《说文》 丧事不敢不勉。--《论语·子罕》 曰勉升降以上下兮。--《楚辞·离骚》 勉力不时；组词：勉意(勉强；勉为其难) 尽力,用尽所有力量 尔其勉之', '小学', '1'),
    ('勋', 'xūn', '9', '力', '左右', NULL, '勋 (形声。小篆字作勲”,从力,熏声。古文从力,员声。本义特别大的功劳) 同本义 勲,能成王功也。从力,熏声,古文唗声。；组词：勋胤(功勋的后代)；勋垂 勋(勳)xūn劳绩,特殊的功劳~劳', '小学', '1'),
    ('勒', 'lè', '11', '力', '左右', NULL, '勒〈名〉 (形声。从革,力声。从革”,表示与皮革有关。本义套在马头上带嚼子的笼头) 同本义 勒,马头络衔也。；组词：马勒；勒面(古代马面饰) 对数能量损失,中子能量损失的一种量度,等于中子初始能量与在慢化过程中任一点上能量之比的自然对数', '小学', '1'),
    ('勘', 'kān', '11', '力', '左右', NULL, '勘〈动〉 (形声。从力,甚声。本义校订,核对) 同本义(考订核实异同) 勘,校也。--《说文新附》 每获一书,即共同勘校。--李清照《金石录后序》；组词：勘合(验证,核对', '小学', '1'),
    ('募', 'mù', '12', '力', '上下', NULL, '募 (形声。从力,莫声。本义招募;征召) 同本义 募,广求也。--《说文》 招延募选。--《荀子·议兵》 谨募选阅材货之上。--《荀子·王制》。注招也。” 安集吏民,顺俗而教；组词：募选(从应募的人中选择合适的人)；募缘(化缘)；募召(招募)；募民(征募民众)；募格(募人从军,杀敌的赏格) 募 假借为', '小学', '1'),
    ('勤', 'qín', '13', '力', '左右', NULL, '勤〈动〉 (形声。右形,左声。本义劳累,劳苦) 尽力多做,不断地做 勤,劳也。--《说文》 文王既勤止。--《诗·周颂·赍》 勤者,有事则收之。--《礼记·玉藻》。注执劳辱之事也', '小学', '1'),
    ('勺', 'sháo', '3', '勹', '半包围', NULL, '勺〈名〉 (象形。本义古代舀酒器) 同本义。泛指舀东西的器具,有柄 勺,挹取也。象形。中有实,与包同意。', '小学', '1'),
    ('勾', 'gōu', '4', '勹', '半包围', NULL, '勾 本作句”。弯曲 删除或截取 谢安已令吏部郎袁彦伯撰策文,文成,安辄勾点,令更治改。--《魏书·司马叡传》 把报上的新词勾出来；组词：勾除(勾销,除掉)；勾抹(勾除；抹掉)；勾却(勾销,取消) 勾勒(用笔先勾一个轮廓) 勾结 都是这些和尚勾合光棍,在外诈', '小学', '1'),
    ('勿', 'wù', '4', '勹', '半包围', NULL, '兀 (指事。从一,在人上。人头上一横,表示高平。本义高耸特出的样子) 同本义 兀,高而上平也。；组词：兀岸(直耸挺拔)；兀嵝(险峻) 光秃(如毛发)的 蜀山兀', '小学', '1'),
    ('匀', 'yún', '4', '勹', NULL, NULL, '匀 (会意。从勹二。勹,象人曲形有所包裹,二”表示所裹不多。本义少) 假借为均”。分,分出 匀,调匀也。；组词：匀滚(拉平；平均)；饭匀着吃；叫东村匀出一匹马来；匀摊(平均分摊) 涂抹均匀 向镜轻匀衬脸霞', '小学', '1'),
    ('包', 'bāo', '5', '勹', '半包围', NULL, '包 (会意。小篆字形,外边是勹”。中间是个巳”字,象子未成形”。勹”就是包”的本字。本义裹) 用纸、布等裹东西 野有死麕,白茅包之。；组词：纸包不住火；包缠(包裹缠绕) 包含,包容', '小学', '1'),
    ('匆', 'cōng', '5', '勹', NULL, NULL, '匆 急促地 匆 cōng急;忙~忙、~~。', '小学', '1'),
    ('匈', 'xiōng', '6', '勹', '半包围', NULL, '匈 (形声。从勹,凶声。勹,裹。本义胸膛) 胸”的古字 匈,膺也。--《说文》。字亦作胷、作胸 胸满。--《素问·腹中论》 贯匈国。其为人胸有窍。--《海内南经》 心胸；组词：匈臆(胸怀) 匈xiōng 1.〈古〉同"胸"', '小学', '1'),
    ('匕', 'bǐ', '2', '匕', '半包围', NULL, '匕 (象形。从二匕,匕亦声。甲骨文字形,象汤匙形『字部首之一。本义勺子。按一说匕”象反人形,妣”之初文) 古代的一种取食器具,长柄浅斗,形状像汤勺 先主方食,失匕箸；组词：比筋(羹匙与筷子) 匕 bǐ 1取食的器具先生方食,失~箸', '小学', '1'),
    ('化', 'huà', '4', '匕', '左右', NULL, '化〈动〉 (古字为匕”。会意。甲骨文,从二人,象二人相倒背之形,一正一反,以示变化。本义变化,改变)', '小学', '1'),
    ('北', 'běi', '5', '匕', NULL, NULL, '北 方位名。与南”相对 人坐立皆面明背暗,故以背为南北之北。--朱骏声《说文通训定声》 万物负阴而抱阳。；组词：正北；西北；东北；北邙(即氓山', '小学', '1'),
    ('匙', 'shi', '11', '匕', '半包围', NULL, '匙 (形声。从匕,是声。匕”食器。本义古时盛食物的器具◇来的茶匙、汤匙,即由它演变而来)', '小学', '1'),
    ('匠', 'jiàng', '6', '匚', '半包围', NULL, '匠 (会意。从匚,盛放工具的筐器,从斤(斧)。工具筐里放着斧头等工具,表示从事木工。本义木工)；组词：匠氏(木匠)；匠者(木工)；匠营(土木工) 亦泛指工匠 能剒削柱梁谓之木匠；能穴凿穴埳谓之土匠,能雕琢文书谓之史匠', '小学', '1'),
    ('匣', 'xiá', '7', '匚', '半包围', NULL, '匣 (形声。从匚,甲声。匚,盛物器。本义匣子) 同本义,一般呈方形,大的叫箱,小的叫匣 匣,匮也。；组词：匣子炮(匣子枪', '小学', '1'),
    ('匪', 'fěi', '10', '匚', '半包围', NULL, '匪〈名〉 (形声。从匚,盛物之器。非声。本义篚”的古字。竹器,形似竹箧) 同本义 匪,器似竹筐。', '小学', '1'),
    ('匹', 'pǐ', '4', '匚', '半包围', NULL, '匹 (会意。据金文,象以山崖的凹凸不平来比喻布的摺皱。本义中国古代计算布帛的单位,四丈为匹) 量词。用于纺织品或缧马等 匹,四丈也。；组词：匹练(一匹白绢)；匹帛(泛指纺织品)；匹段(泛指丝织品) 志同道合的人；伴侣；配偶 常以鳏旷多感,或谋新匹', '小学', '1'),
    ('区', 'qū', '4', '匚', '半包围', NULL, '区 ou 一种中国古代容器。又用为容量单位 齐旧四量豆、区、釜、钟。--《左传·昭公三年》 古代农民播种时所开的穴或沟称为区” 姓氏 我区氏儿也', '小学', '1'),
    ('医', 'yī', '7', '匚', '半包围', NULL, '医 (会意兼形声。从匚,从矢,矢亦声。《说文》盛弓弩矢器也。”醫”,会意,从殹”,从酉。殹”,治病时的扣击声。酉”,用以医疗的酒。二字各有本义,今用医” 为简体字；组词：医国(指良医)；医家有割股之心(喻医生有治病救人的虔诚愿望)；缺医少药；医(醫、毉)yī 1.治病~疗', '小学', '1'),
    ('匾', 'biǎn', '11', '匚', '半包围', NULL, '匾 同扁”。形体的厚度比长度、宽度小;不圆 匾 匾额 上面绣字的丝制横幅 用竹蔑编成的器具,圆形平底框很浅,用来养蚕或盛粮食 匾biǎn 1同"扁"。形体的厚度比长度与宽度小', '小学', '1'),
    ('匿', 'nì', '10', '匚', '半包围', NULL, '匿〈动〉 (形声。从匚,若声(上古读音与匿声相近)。匚”表示有所藏。本义隐藏,躲藏) 同本义 匿,亡也。；组词：隐匿(隐藏；躲起来)；藏匿(藏起来不让人发现)；匿光(隐藏其光华', '小学', '1'),
    ('十', 'shí', '2', '十', NULL, NULL, '十 (指事。甲骨文象用一根树枝代表十,金文象是结绳记数,用一个结表示十◇来一点变成了一横。本义九加一的和)；组词：十里长亭(古时设在路旁的亭子,常用作送别饯行之处)；十番(合奏乐以十种乐器演奏的名称)；十牌(十户人家 十shí 1.数', '小学', '1'),
    ('千', 'qiān', '3', '十', '上下', NULL, '千〈数〉 (形声。从十,人声。本义数目。十百为千) 同本义 千,十百也。--《说文》 又如千夫(一千个成年男子);千门(千家);千社(25家为社,千社为25000家);千祀(千年；组词：千夫(一千个成年男子)；千门(千家)；千社(25家为社,千社为25000家)；千祀(千年,千代)；总数为一千；千乘(兵车', '小学', '1'),
    ('升', 'shēng', '4', '十', NULL, NULL, '升 (象形。本义容器名。一斗的十分之一) 容量单位 升,十龠也。从斗,亦象形。--《说文》。按,十合也。 两匊谓之升。--《小尔雅》 蕃衍盈升。--《诗·唐风·椒聊》 十合为一升', '小学', '1'),
    ('午', 'wǔ', '4', '十', NULL, NULL, '午 (象形。本义御马索) 同本义 地支的第七位 与天干相配,用以纪年 太岁在午曰敦羊。--《尔雅》 用以纪月。即农历五月 午,五月阴气午逆阳,冒地而出', '小学', '1'),
    ('半', 'bàn', '5', '十', NULL, NULL, '半 (会意。从八,从牛。八”是分解的意思;牛大,易于分割,所以取牛”会意。本义一半,二分之一)；组词：太半(三分之二)；半日；半工；半升 中 部分的,不完全的 犹抱琵琶半遮面', '小学', '1'),
    ('华', 'huá', '6', '十', '上下', NULL, '华 华丽;光彩美丽 金银华美之服。--宋·司马光《训俭示康》 华堂之上。--明·刘基《诚意伯刘文成公文集》 华衣乘马。--明·高启《书博鸡者事》；组词：华扁(华丽的匾额)；华彩(华美；光彩)；华服(华丽的服装)；华舆(华美的车辆或轿子)；华筵(华美的筵席)；华观(华丽的观', '小学', '1'),
    ('协', 'xié', '6', '十', '左右', NULL, '协 (会意。从办,从十。办亦声。办表示同力。十,表示众多∠起来表示众人同力。本义和睦;融洽)；组词：协允(合理公平)；协气(和气)；协恭(友好而同心协力)；协睦；协畅；协调；协泰(协和安泰) 合；共同 纪农协功', '小学', '1'),
    ('卑', 'bēi', '8', '十', '上下', NULL, '卑 (椑之古字,本义是圆搕,一种酒器) 地位低微 卑,庳也。--《广雅》 文王卑服。--《书·无逸》 人皆赴高,己独赴下卑也。--《管子·水地》 天尊地卑；组词：卑弁(下级武职对上级的自称)；卑寒(谦词', '小学', '1'),
    ('卒', 'zú', '8', '十', '上下', NULL, '卒 cu 同猝”。仓促,急速 行西逾陇卒。--《汉书·食货志》。注仓卒也。” 兴卒暴之作。--《汉书·成帝纪》 而卒惶急无以击轲,而乃以手共搏之。--《战国策·燕策》；组词：卒拔(仓猝攻取)；卒迫(仓促紧迫) 突然 则亡以应卒', '小学', '1'),
    ('卓', 'zhuó', '8', '十', '上下', NULL, '卓 (卓的古字。形声。匕形早声。匕”表示人”。本义超然独立;高明;高超) 同本义 卓,高也。；组词：卓荦不羁(卓越超群,不甘受拘束)；卓尔独行(超越众人)；卓夺(作出高明的决断)；卓殊(卓越,特异)；卓逸(卓越超绝) 高', '小学', '1'),
    ('单', 'dān', '8', '十', NULL, NULL, '单于 chan 月黑雁飞高,单于夜遁逃。--唐·卢纶《塞下曲》 单于使卫律治其事。--《汉书·李广苏建传》 单 dan (本义大)', '小学', '1'),
    ('卖', 'mài', '8', '十', '上下', NULL, '卖 (会意。小篆字形。从出,从买。将收进的财物卖出。本义以货物换钱。与买”相对) 同本义 卖,出物货也。；组词：卖炭得钱；出卖(拿东西换钱)；卖动(卖出去)；卖 卖(賣)mài 1.用东西换货币,跟"买"相反~粮', '小学', '1'),
    ('南', 'nán', '9', '十', '上下', NULL, '南无 na 南 〈名〉 (象形,甲骨文字形,是钟閐之类的乐器。1本义乐器。《诗·小雅·鼓钟》以雅以南。”2方位词) 方位名⊥北”相对 南,草木至南方有枝任也。；组词：南薰(借指从南面刮来的风)；南离(南方) 南方；南面 阮仲容步兵居道 南nán方向,跟"北"相对', '小学', '1'),
    ('博', 'bó', '12', '十', '左右', NULL, '博 (形声。从十,尃声。十”意思是四方中央齐备。尃”有分布之义。本义大) 同本义。与小”相对 博,大通也。；组词：宽衣博带；博硕(粗大；宽大)；博硕肥腯(古时献牲祭神的祝祷辞,是说六畜肥大) 宽广；广搏 博闻强志,明于治乱,娴于辞令', '小学', '1'),
    ('卜', 'bo', '2', '卜', NULL, NULL, '卜--见萝卜” 卜 bǔ 1占卜~卦。 2预料生死未~。 3选择(处所)~宅。 4姓。又见·bo。 【卜筮】古时占卜, 用龟甲称卜,用蓍草称筮,合称卜筮', '小学', '1'),
    ('占', 'zhàn', '5', '卜', '上下', NULL, '占 (会意。从卜,从口。以口问卜。本义推测吉凶,即察看甲骨的裂纹或蓍草排列的情况取兆推测吉凶)；组词：占旺相(占卜时运)；占人(掌占卜的官员)；占工(占者', '小学', '1'),
    ('卡', 'kǎ', '5', '卜', '上下', NULL, '卡〈名〉 卡路里的简称 卡车的省称 译音用字。如卡宾枪;卡介苗;卡车;卡片;卡通 卡 〈象〉 象声词 卡kǎ 1.卡车,又简称"卡"大~车。十轮~', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('卢', 'lú', '5', '卜', '上下', NULL, '卢 (形声。甲骨文字形,从皿,虎声。本义饭器) 同本义 卢,饭器也。--《说文》 通庐”。房屋 君卢屋妾。--《荀子·富国》 瞳人 玉女无所眺其清卢兮', '小学', '1'),
    ('卤', 'lǔ', '7', '卜', '上下', NULL, '卤 (象形。金文字形,象盐罐(或盐池)中有盐形。本义盐碱地) 同本义 晋荀吴帅师败狄于大鹵。；组词：卤田(盐田)；卤莽(荒地上的野草)；卤泻(含盐碱的土壤)；卤地(盐碱地) 天然生成的盐称为卤”', '小学', '1'),
    ('卦', 'guà', '8', '卜', '左右', NULL, '卦 (形声。从卜,圭声。本义象征自然现象和人事变化的一套符号,供占卜用) 同本义 卦,筮也。', '小学', '1'),
    ('卧', 'wò', '8', '卜', '左右', NULL, '卧 (会意。从人臣。臣”是竖立的眼睛。本义人伏在几案上休息,眼睛呈竖立形) 同本义 坐而言,不应,隐几而卧。；组词：卧冰(卧于冰上', '小学', '1'),
    ('卫', 'wèi', '3', '卩', '上下', NULL, '卫 (会意。从韋币从行。甲骨文中卫、韦”同字。意思是在大道(行)站岗保卫(韦)。本义保卫;防护)；组词：卫籍(军籍)；守卫(防守保卫)；自卫(保卫自己)；捍卫(保卫)；卫守(保卫防守)；卫助(保卫协助)；卫足(比喻自全或自卫', '小学', '1'),
    ('印', 'yìn', '5', '卩', NULL, NULL, '印 (会意。甲骨文字形。左是手爪,右象跪着的人,合起来表示用手按人使之跪拜。本义官印) 同本义 印,执政所持信也。；组词：印务(有关印章管理和收发文书的工作；也指官印和职务)；印券(盖有官印的凭证)；印佩(官印)；印牌(将印或令 印yìn 1', '小学', '1'),
    ('危', 'wēi', '6', '厄', '上下', NULL, '危 (会意。小篆字形上面是人,中间是山崖,下面腿骨节形。人站在山崖上,表示很高。本义在高处而畏惧)；组词：人人自危；危心(心存戒惧)；危怖(恐惧不安)；危栗(恐惧战栗)；危气(气馁；危惧)；危悚(危悰,危惧)；危视(惊视)；危', '小学', '1'),
    ('即', 'jí', '7', '卩', NULL, NULL, '即 (会意。甲骨文作坐人形(后讹为卩)面对食器(皀)会意。本义走近去吃东西) 同本义 即,就食也。；组词：若即若离 登上；走上 即jí 1.便,立刻,马上立~办', '小学', '1'),
    ('却', 'què', '7', '卩', '左右', NULL, '却 (形声。本作却”,俗字作却”。从卩,谷声。卩,象人下跪的样子,即腿骨节屈曲的样子。从卩”与脚的活动有关。本义退)；组词：退 却(卻)què 1.退退~', '小学', '1'),
    ('卵', 'luǎn', '7', '卩', NULL, NULL, '卵〈名〉 (象形。小篆字形像卵。本义卵子,特指蛋) 蛋 卵,凡物无乳者卵生。--《说文》 鸟翼鷇卵。--《国语·鲁语》。注未孚曰卵。” 梁卵焍黄。--《史记·龟策传》。索隐鸡子也；组词：卵袋(指长圆形口上有绳可结扎的钱袋)；卵清(蛋白)；卵用鸡(以产蛋为主要目的而饲养的鸡种) 成熟的雌性生殖细胞,一般呈球', '小学', '1'),
    ('卷', 'juàn', '8', '厄', '上下', NULL, '卷 (形声。从卩(甲骨文象人曲膝而跪的样子),劵声。本义膝曲) 把物弯转成圆筒形 有卷者阿。；组词：卷舒(裹卷和舒展)；卷帐(新郎在女家结婚,三日之后新婚夫妇带妆奁回到男家)；卷坐(轿舆不调头,向后退称卷坐)；卷戏(过去', '小学', '1'),
    ('卸', 'xiè', '9', '卩', '左右', NULL, '卸 (会意。从卩,从止,从午。卩,像人形;止,息止;午,指马∠起来表示停车解马。本义解马卸车)；组词：卸车；卸鞍 解除；解下', '小学', '1'),
    ('卿', 'qīng', '10', '卩', NULL, NULL, '卿〈名〉 (会意。甲骨文字形,像二人向食之形。《说文》从卯,皂声。”卯,事之制也。”本义飨食) 古时高级长官或爵位的称谓『以前有六卿,汉设九卿,北魏在正卿下还有少卿。以后历代相沿', '小学', '1'),
    ('厂', 'chǎng', '2', '厂', NULL, NULL, '厂 (形声。从广,敞声。从广”,表示与房屋有关。本义棚舍) 没有墙壁的简易房屋 又如厂屋(棚舍;无隔墙的房屋) 马屋;牲口棚子 架北墙为厂。；组词：厂屋(棚舍；无隔墙的房屋) 马屋；牲口棚子 架北墙为厂', '小学', '1'),
    ('厅', 'tīng', '4', '厂', NULL, NULL, '厅 (形声。从广,聽声。厅是后起字,大约产生于唐代。古作聽”。魏晋以来加广”。本义堂屋)；组词：官厅(旧时称政府机关)；厅宇(厅堂,厅房)；厅屋(包括厅堂在内的房舍)；厅头(守厅军士的头目) 住宅中通往各房间的大或小', '小学', '1'),
    ('历', 'lì', '4', '厂', NULL, NULL, '历 (形声。从謪,厤声。从止”,表示与脚、行走有关。本义经过) 同本义 历,过也。--《说文》 深践戎马之地, 足历王庭,垂饵虎口。--汉·司马迁《报任少卿书》 历齐河；组词：身历(亲身经历)；历时(所经过的时间)；历劫(佛教用语', '小学', '1'),
    ('厉', 'lì', '5', '厂', NULL, NULL, '厉 (是砺”的本字。从厂,象山崖形,表示与山石有关。本义磨刀石) 同本义 段注旱石者,刚于柔石者也。字亦作厲、作祕。”朱骏声曰精者曰厎,粗者曰厉『书地理志,述禹贡砥厉砮丹;诗公刘；组词：厉阶(祸端) 恶鬼 晋侯梦大厉', '小学', '1'),
    ('压', 'yā', '6', '厂', NULL, NULL, '压 (形声。从土,厌声。本义崩坏) 同本义 压,坏也。--《说文》 侨将压焉。--《左传·襄公三十一年》 吾惧压焉。--《国语·鲁语》。注笮也。” 壤压之变；组词：压溺(土崩和水淹) 从上往下增加重力,加压 千朵万朵压枝低', '小学', '1'),
    ('厌', 'yàn', '6', '厂', NULL, NULL, '厌 ya 一物压在另一物上 厌,笮也。--《说文》。段注此义今人字作压,乃古今字之殊。” 地震陇西,厌四百余家。--《汉书·五行志下之上》 如墙厌之；组词：厌覆(车翻人压) 泛指压制；抑制 东厌诸侯之权,西远羌胡之难', '小学', '1'),
    ('厕', 'cè', '8', '厂', NULL, NULL, '厠 (形声。从厂),则声。厂”,小篆字形象山崖,可以住人。厂”作为汉字部首之一,常与广”(?；组词：男厕；女厕；厕屋(厕溷', '小学', '1'),
    ('厘', 'lí', '9', '厂', NULL, NULL, '厘 (形声。从里,从里”,表示与居住家居有关。本义家福;幸福) 同本义 祠官祝釐。--《汉书·文帝纪》。如淳注福也。” 上方受釐坐宣室。--《汉书·贾谊传》 逆釐三神者；组词：恭祝新厘 极小,极少量 厘 治理；处理 允厘百工,庶绩咸熙', '小学', '1'),
    ('厚', 'hòu', '9', '厂', NULL, NULL, '厚 (会意。从厂,表示与山石有关。本义地壳厚。与薄”相对) 同本义 谓地盖厚。--《诗·小雅·正月》 穷高极远而测深厚。--《礼记·乐记》。注深厚,山川也。” 厚将崩；组词：厚土(覆土厚)；厚地(大地)；厚坤(大坤)；厚厚(大地) 扁平物体上下两面之间距离大的', '小学', '1'),
    ('原', 'yuán', '10', '厂', NULL, NULL, '原 (会意。小篆字形。象泉水从山崖里涌出来。从厂,象山崖石穴形。从泉。本义水源,源泉) 源”的古字。水源,水流起头的地方 原,水泉本也。；组词：原泉(源泉)；原流(源流) 起源；根本；根由 必达于礼乐之原', '小学', '1'),
    ('厢', 'xiāng', '11', '厂', NULL, NULL, '厢 (形声。从厂相声。从厂,与房屋有关。本义东西廊) 同本义 厢,廊也。--《说文新附》 室有东西厢曰庙。--《尔雅·释宫》。孙注厢,夹室前堂。”李注厢,谓宗庙殿有东西小堂也；组词：东厢；西 厢(廂)xiāng 1.正房前面两侧的房屋~房', '小学', '1'),
    ('厦', 'shà', '12', '厂', NULL, NULL, '厦 sha (厦俗作厦。古通作夏。形声。从广,夏声。广表示房屋。夏”古有大”的意思。见《尔雅·释诂》。本义大屋子)；组词：厦子(小厢房；小屋)；厦处(住所) 门庑；廊屋；披屋 厦 大 厦屋一揆,华屏齐荣', '小学', '1'),
    ('厨', 'chú', '12', '厂', NULL, NULL, '厨〈名〉 (形声。从广,尌声。本义厨房) 同本义 厨,庖屋也。--《说文》 《孟子》始有厨字,是周初名庖,周末名厨也。--《说文句读》 厨主食者也；组词：厨下(厨房)；厨头(厨房)；厨仓(厨房与粮仓)；厨帐(账幕式厨房) 主持烹饪的人 厨 chú做饭菜的(事情、人、地方)帮', '小学', '1'),
    ('去', 'qù', '5', '厶', '上下', NULL, '去〈动〉 (会意兼形声。甲骨文字形。上面是人(大),下面是口(或作凵”),表示人离开洞口或坑坎而去。《说文》从大,凵声。”凵。本义离开)', '小学', '1'),
    ('县', 'xiàn', '7', '厶', '上下', NULL, '县 (会意。从系持倒首。象悬挂的样子。本义悬挂) 县假借为寰”,为州县的县 遂缚诣县。--三国魏·邯郸淳《笑林》 南番二县。；组词：县尹(一县的长官)；县学(旧制设在县里的学校,以培养人才,教育百姓,称县学)；县委(中国共产党县一级委员会的简称) 官府', '小学', '1'),
    ('叁', 'sān', '8', '厶', '上下', NULL, '叁〈数〉 參,三也。--《广雅》◇作叁”。 參天两地而倚数。--《易·说卦》。虞注參,三也。” 大都不过參国之一。--《左传·隐公元年》。注三分国城之一。” 參伍以变', '小学', '1'),
    ('参', 'cān', '8', '厶', '上下', NULL, '参 can 加入 参水浸于盂内。--宋应星《天工开物》 又如参选(参加盐);参纂(参加编纂) 参与(亦作参予”参豫”。预闻而参议其事) 与之参国政。；组词：参选(参加盐)；参纂(参加编纂) 参与(亦作参予”参豫”', '小学', '1'),
    ('又', 'yòu', '2', '又', NULL, NULL, '又 (象形。甲骨文字形,象右手形,本左右的右”。从又”的字多与手的动作有关。本义右手) 同本义 又,手也,象形。；组词：读了又读；又是他；又问；又起个窖儿(比喻多费了一道手续)；又称；又说 表示几种情况或性质同时存在 东出于陶邱北,又东至于', '小学', '1'),
    ('叉', 'chā', '3', '又', '全包围', NULL, '叉 (指事。小篆为又”(即手)上加一点,指出叉手的动向。本义交错,交叉) 手指相交错。也泛指一般的交错、交叉 叉,手指相错也。；组词：叉手 刺；扎取 叉 古代的一种兵器,头有分杈 红漆了叉', '小学', '1'),
    ('及', 'jí', '3', '又', NULL, NULL, '及 (会意。甲骨文字形,从人,从手。表示后面的人赶上來用手抓住前面的人。本义追赶上,抓住)；组词：赶不及(来不及)；企及(希望赶上)；來得及(能够赶上)；及面(见面)；及时应令(与季节令令相适应) 至,达到 及,至也', '小学', '1'),
    ('友', 'yǒu', '4', '又', NULL, NULL, '友〈名〉 (会意。甲骨文字形,象顺着一个方向的两只手,表示以手相助。本义朋友) 同本义 友,同志为友。；组词：挚友(亲密的朋友)；友生(朋友) 职官名', '小学', '1'),
    ('双', 'shuāng', '4', '又', '左右', NULL, '双 (会意。从雔,从又,持之。雔,两只鸟。又,手。本义一对) 禽鸟二只 雙,隹二枚也。--《说文》 飞鸟曰双。--《方言六》 其诸为其双双而俱至者与。--《公羊传·宣公五年》', '小学', '1'),
    ('反', 'fǎn', '4', '又', NULL, NULL, '反〈动〉 (象形。甲骨文字形,从又从厂。厂”音。本义手心翻转) 同本义。通翻”。覆,倾倒 反,覆也。；组词：辗转反侧；反易(颠倒)；反风(风向倒转) 通返”', '小学', '1'),
    ('发', 'fā', '5', '又', NULL, NULL, '发 (形声。本义 放箭) 同本义 發,射发也。--《说文》 壹发五豝。--《诗·召南·驺虞》 发彼有的。--《诗·小雅·宾之初筵》 循声而发。--《礼记·射义》 矢四发；组词：百发百中；发矢(射箭)；发箭(射箭)；发功(指射技) 出发；上路 发(發) fā 1.长出,产生~新枝', '小学', '1'),
    ('叔', 'shū', '8', '又', '左右', NULL, '叔 会意兼形声。同本义 叔,拾也。--《说文》。汝南名收芋为叔。 九月叔苴,采荼薪樗。--《诗·豳风·七月》 叔 假借为少”。年幼的 叔者,少也', '小学', '1'),
    ('取', 'qǔ', '8', '又', '左右', NULL, '取〈动〉 (会意。从又,从耳。甲骨文字形。左边是耳朵,右边是手(又),合起来表示用手割耳朵。古代作战,以割取敌人尸体首级或左耳以计数献功。本义 耳)', '小学', '1'),
    ('受', 'shòu', '8', '又', '上中下', NULL, '受 (会意。甲骨文字形,象两手中间有一只舟,表示传递东西。本义接受;承受) 同本义 受,相付也。', '小学', '1'),
    ('变', 'biàn', '8', '又', '上下', NULL, '变 (形声。从攴(酰??),宒(畬溂?? )声。本义变化,改变) 同本义 变,更也。--《说文》 变,易也。--《小尔雅》 变者,非常也。--《白虎通》 一阖一辟谓之变；组词：变文协韵(古文修辞术语', '小学', '1'),
    ('叙', 'xù', '9', '又', '左右', NULL, '叙 (形声。从攴,余声。本义秩序,次序) 同本义(强调一个挨一个的序列) 敘,次弟也。--《说文》。经传亦以序为之。 百揆时敘。--《虞书》 行其秩敘；组词：叙齿(序齿)；叙齿而坐(按年齿大小的顺序入座) 同序”', '小学', '1'),
    ('叛', 'pàn', '9', '又', '左右', NULL, '叛〈动〉 (形声。从反,半声。本义背叛) 同本义 叛,乱也。--《广雅》 信中涂而叛之。--《楚辞·逢纷》 叛者,反背之辞也。--《左传释例》 侯不朝,兹谓叛；组词：众叛亲离；反叛(叛变)；叛道(背叛正道)；叛败(谋叛而败亡)；叛镇(背叛朝廷的藩镇)；叛附(叛变后另有依附)；叛服(叛变', '小学', '1'),
    ('叠', 'dié', '13', '又', '上下', NULL, '叠 (会意。金文字形,象物体叠放在俎”上。本义重叠) 同本义 曡,重也,积也。--《苍颉篇》 阳始出奥舒、曡。--《书·太元乐》。注积也。” 虽累叶百叠,而富强相继；组词：叠石为山；叠暴(显露；指人激动时青筋鼓出来)；叠字(单字的重叠)；叠雪(重叠飞扬的雪花) 折,折叠,交叠,指用对折或交叠', '小学', '1'),
    ('口', 'kǒu', '3', '口', '上下', NULL, '口〈名〉 (象形。甲骨文字形,象人的口形。本义口腔器官,嘴) 同本义。人类用来发声和进食的器官 口,人所以言食也。；组词：口腹(指饮食)；口分(口福)；口滑(指吃东西失去控制；说话不谨慎)；口辅(面颊', '小学', '1'),
    ('古', 'gǔ', '5', '口', '上下', NULL, '古 (会意。从十,从口。本义古代。一般分为太古、上古、中古、近古) 同本义 古,故也。--《说文》 大古冠布。--《仪礼·士冠礼》。注大古,唐虞以上。” 以是为近古也；组词：远古(遥远的古代)；古字(指隶书以前的古代文字)；古gǔ 1.很久以前的,过去的,跟"今"相对~代', '小学', '1'),
    ('句', 'jù', '5', '口', '半包围', NULL, '句 gou (形声。从口。正当读今言钩,俗作勾。本义弯曲) 同本义 句,曲也。--《说文》。段注凡曲折之物,侈为倨,敛为句。考工记多言倨句。” 越子为左右句卒；组词：句爪(钩形的尖爪)；句枉(曲枝)；句曲(弯 句jù 1.句子,能表达一个完整意思的语言单位造~', '小学', '1'),
    ('另', 'lìng', '5', '口', '上下', NULL, '另〈动〉 分居,分开居住而各自谋生 另,分居也。--《五音集韵》 割开,分开 另,割开也。--《五音集韵》 另〈形〉 单,独 别异,别为一事 另lìng别的,以外,其它~有。~外', '小学', '1'),
    ('叨', 'dāo', '5', '口', '左右', NULL, '叨 话多 叨 等他爬起来一看呀,小兔子正在叨气儿呢,胸脯里的心跳得一撞一撞的。--杨朔《春子姑娘》 叨叨 别一个人叨叨了,听听大家的意见吧! 叨咕 叨念 叨〈动〉 tao 贪婪', '小学', '1'),
    ('只', 'zhī', '5', '口', '上下', NULL, '只 (形声。从又,持隹。持一隹曰隻,持二隹曰雙。本义鸟一只) 同本义 隻,鸟一枚也。--《说文》 如彼翰林鸟,双栖一朝只。--《悼亡诗三首》；组词：只翼(一只鸟', '小学', '1'),
    ('叫', 'jiào', '5', '口', '左右', NULL, '叫〈动〉 (形声。本义呼,喊) 同本义 叫,噁也。--《说文》 或不知叫号。--《诗·小雅·北山》 叫我友兮配耦。--《楚辞·疾世》。注急呼也。” 叫帝阍使辟扉兮；组词：叫命(骂人话', '小学', '1'),
    ('召', 'zhào', '5', '口', '上下', NULL, '召 (形声。从口,刀声。本义呼唤) 召唤。用言语叫人来 召,呼也。从口,刀声。以言曰召,以手曰招。；组词：召呼(呼唤；通知；交代)；召致(使之至；唤来) 招致 故言有召祸也,行有招辱也', '小学', '1'),
    ('叭', 'bā', '5', '口', '左右', NULL, '叭 将食物扒入口中 只三叭两咽,就是一碗。--《金瓶梅词话》 叼;含在口中 移开叭在口里的旱烟袋。--周立波《牛》 叭 形容开合声 1.将食物扒入口中', '小学', '1'),
    ('叮', 'dīng', '5', '口', '左右', NULL, '叮 (形声。从口,丁声。本义切嘱。如叮咛) 同本义 虫类用针形口器刺人 力叮不释', '小学', '1'),
    ('可', 'kě', '5', '口', NULL, NULL, '可〈动〉 (会意。从口,从丂(供神之架),表示在神前歌唱。可”似为歌”字的古文。1本义唱 2引申义许可) 许可;同意;准许 可,许可也。；组词：不可；可许(准许)；可传(可以传后；可以传授；可以流传)；可则(可作准则)；可风(可为风范) 能够；可以 可使以其技鸣', '小学', '1'),
    ('台', 'tái', '5', '口', '上下', NULL, '台〈名〉 地名。台州”的简称 南发交广东温台。--王安石《和王微之登高斋二首》 台〈名〉 (形声。小篆字形。从口,(以)声。从口,与表示喜悦有一定的联系。本义喜悦。 三台。星名', '小学', '1'),
    ('史', 'shǐ', '5', '口', NULL, NULL, '史 (会意。甲骨文字形,上面是放简策的容器,下面是手∠起来表示掌管文书记录。本义史官) 古官名。职别各异 史,记事者也。', '小学', '1'),
    ('右', 'yòu', '5', '口', NULL, NULL, '右 (会意。从口,从又(手)。口手并用帮助别人。本义右助。见《说文》。这个意义后来写作佑”) 助;帮助◇多作佑” 右,手口相助也。；组词：右援(援助；引荐)；右序(辅助；佑助)；右饷(谓享受祭献,佑助降福)；右与(佑助,帮助) 尊崇；崇尚 兼爱,尚贤,右鬼,', '小学', '1'),
    ('叶', 'yè', '5', '口', '左右', NULL, '叶 (形声。从苃,枽声。植物的叶子。叶”,同协”,会意字,从十从口。本是两个字。本义草木之叶)；组词：叶尖(植物学名词', '小学', '1'),
    ('号', 'hào', '5', '口', '上下', NULL, '号 (会意。从虎,从号。号”亦兼表读音。号”是號”的古字,上面是口”,下面代表声音,即号呼的意思◇繁化,变成號”,现在简化为号”。本义大声喊叫)；组词：号噪(呼叫,喧嚷)；号踯(号叫跳顿)；号佛(高声念佛) 哭而有言 号,痛声也', '小学', '1'),
    ('司', 'sī', '5', '口', NULL, NULL, '司 (指事。甲骨文字形,表示一个人用口发布命令,有统治、管理义。从反后,意思说,与帝王后”相对为司”,即有司。本义职掌,主管)', '小学', '1'),
    ('叹', 'tàn', '5', '口', '左右', NULL, '叹 (形声。从欠(另一繁体从口”),難”省声。欠,打呵欠,与出气有关。本义叹息) 同本义 叹,吞叹也。一曰太息也。；组词：叹气嗐声(唉声叹气)；叹恨(叹息抱恨)；叹憾(叹息遗憾)；叹笑(叹息讥笑)；叹悔(叹息后悔)；叹喟(叹息)；叹嗟(叹息)', '小学', '1'),
    ('叼', 'diāo', '5', '口', '左右', NULL, '叼 用嘴衔住 在嘴上吊着 叼 diāo用嘴衔着某种东西,被衔的东西相当部分露在嘴外~着香烟。', '小学', '1'),
    ('叽', 'jī', '5', '口', '左右', NULL, '叽 稍微吃一点 嘰,小食也。从口,幾声。--《说文》 叽琼华。--《大人赋》 进秙(叽)进羞。--《礼记·玉藻》 呼吸沆瀣兮餐朝霞,噍咀芝英 茹,叽,食也', '小学', '1'),
    ('吁', 'yù', '6', '口', '左右', NULL, '吁 xu (形声。从口,于声。本义表示惊怪、不然、感慨等) 同本义 王曰吁!来!有邦有土,告尔祥刑。”；组词：吁咈(表示不以为然之意)；吁咈都俞(吁咈,吁俞', '小学', '1'),
    ('吃', 'chī', '6', '口', '左右', NULL, '吃 (形声。从口,乞声。本义口吃,结巴) 同本义 吃,言蹇难也。--《说文》 昌为人吃。--《汉书·周昌传》；组词：吃子(口吃的人)；吃吃(形容口吃或有话说不出口) 吃 (形声', '小学', '1'),
    ('各', 'gè', '6', '口', '上下', NULL, '各 每个,各自 各守尔典。--《书·汤浩》 行人弓箭各在腰--唐·杜甫《兵车行》 乡民复鸣锣会集各乡约数千人。--《三元里人民抗英》；组词：各有所长；各个；各自；各众(梵语', '小学', '1'),
    ('吆', 'yāo', '6', '口', '左右', NULL, '吆 大声喊。通常指大声斥责人,大声驱赶牲口,高声叫卖,喊劳动号子等 现在皇帝还着人吆跑了。；组词：吆号子(大声唱吆号子”)；吆卖(大声叫卖)；吆天喝地(大声喊叫)；吆吆喝喝(大声喊叫) 吆yāo', '小学', '1'),
    ('合', 'hé', '6', '口', '上下', NULL, '合〈动〉 (会意。从亼,三面合闭,从口。本义闭合,合拢) 同本义 合,合口也。--《说文》 公孙龙口呿而不合。--《庄子·秋水》 引申为开合之称 合则成体；组词：蚌合；合上书；合祛(开闭)；合喙(闭口)；合盘(犹合掌)；合瞑(闭目；闭目入睡) 会聚,聚合 于是乎合其州乡朋友婚姻', '小学', '1'),
    ('吉', 'jí', '6', '口', '上下', NULL, '吉 (会意。甲骨文字形,上象兵器,下象盛放兵器的器具∠起来表示把兵器盛放在器中不用,以减少战争,使人民没有危难。本义吉祥;吉利)', '小学', '1'),
    ('吊', 'diào', '6', '口', '上下', NULL, '吊 (吊为弔的俗字。会意。甲骨文字形,象人持弋射砫缴之形。古人死而不葬,只是放在荒野里用柴薪盖着,但怕禽兽要来吃,连送丧的亲友都带着弓箭前来帮助驱除。本义悼念死者 )；组词：吊纸(在死者灵前烧纸吊祭)；吊问(吊念死者,慰问生者)；吊死(吊慰死者；自缢而死)；吊祠(吊唁祭祀) 引申为慰问 人皆吊', '小学', '1'),
    ('同', 'tóng', '6', '口', '半包围', NULL, '同〈动〉 (会意。从冃,从口。冃,重复。本义聚集) 同本义 同,合会也。--《说文》 同重体合类。--《墨子·经上》 同人亲也。--《易·杂卦》 六曰同衣服；组词：云同(云彩聚集)；同天(共存于人世间)；同合(使相一致；融会)；同流(诸水合流) 相同,一样,共同(侧重于同样,齐一)', '小学', '1'),
    ('名', 'míng', '6', '口', NULL, NULL, '名 (会意。甲骨文字形。从口夕。本义自己报出姓名;起名字) 同本义 名,自命也。--《说文》 黄帝正名百物。--《礼记·祭法》 名之曰幽厉。--《孟子》 名公器也；组词：名品(辨明品级) 称说；说出 不能名其一处', '小学', '1'),
    ('后', 'hòu', '6', '口', NULL, NULL, '后 (会意。象人之形,施令以告四方,古之,从一口,发号者君后也。按从坐人,从口,与君同意。本义君主,帝王)；组词：后王(君王；天子)；后帝(天帝；上帝)；后夷(上古有穷国的国君)；后辟(君主；帝王) 帝王的妻子 天子之妃曰后', '小学', '1'),
    ('吏', 'lì', '6', '口', NULL, NULL, '吏〈名〉 (会意。甲骨文。从手(又),从中。以手持中。有人认为中为笔。吏”、事”、使”古同字。本义官吏) 官员的通称『以后,指低级官员或吏卒 吏,治人者也。', '小学', '1'),
    ('吐', 'tǔ', '6', '口', '左右', NULL, '吐〈动〉 (形声。从口,土声。本义东西从口腔中涌出) 同本义 吐,写也。--《说文》 柔则茹之,刚则吐之。--《诗·大雅·焌民》 然我一沫三捉发,一饭三吐哺；组词：吐气纳元(道家的一种练功修身之法', '小学', '1'),
    ('向', 'xiàng', '6', '口', NULL, NULL, '向 (象形。从宀,从口。宀”表示房屋,甲骨文中像屋墙,有窗户之形。本义朝北开的窗户) 同本义 向,北出牖也。；组词：向(嚮)xiàng 1.朝着,对着~着', '小学', '1'),
    ('吓', 'xià', '6', '口', '左右', NULL, '吓 he (形声。从口,赫声。本义恐吓,恫吓) 同本义 先生造此等言语,意欲吓编吾马。--《二刻拍案惊奇》；组词：吓骗(恐吓诈骗)；吓诈(恐吓讹诈) 吓 用以表示不满 用来表示惊奇或赞叹 吓 xia 使害怕 吓,以口拒人谓之吓', '小学', '1'),
    ('吕', 'lǚ', '6', '口', '上下', NULL, '吕〈名〉 (象形。甲骨文字形,象脊骨形,是膂”的本字。本义脊梁骨) 同本义。膂”的古字 吕,脊骨也。象形。', '小学', '1'),
    ('吗', 'ma', '6', '口', '左右', NULL, '吗 译音字 嗎、么、麽吗 用在句末,表示疑问或反诘的语气 先生,你会看喉咙吗?--《老残游记》 吗má〈方〉什么干~?他笑~? 吗mǎ 儿等禁用。吗啡及其毒品,严禁私造、贩卖', '小学', '1'),
    ('君', 'jūn', '7', '口', NULL, NULL, '君 (会意。从尹,从口。尹”,表示治事;从口”,表示发布命令∠起来的意思是发号施令,治理国家。本义君主,国家的最高统治者) 古代大夫以上据有土地的各级统治者的通称 君,尊也。', '小学', '1'),
    ('吝', 'lìn', '7', '口', '上下', NULL, '吝 (形声。从口,文声。本义顾惜,舍不得) 同本义(爱惜过分,当耗费的舍不得耗费,该使用的舍不得使用) 吝,恨惜也。', '小学', '1'),
    ('吞', 'tūn', '7', '口', '上下', NULL, '吞〈动〉 (形声。从口,天声。本义咽下) 同本义 吞,咽也。--《说文》 吞舟大鱼也。--《后汉书·杜笃传》注 吞长江。--宋·范仲淹《岳阳楼记》 与风水相吞吐；组词：吞炭(吞咽火炭毁嗓子)；吞舌(闭口结舌不言)；吞舟(吞航', '小学', '1'),
    ('吟', 'yín', '7', '口', '左右', NULL, '吟 (形声。从口,今声。唫为吟的本字。本义呻吟、叹息) 同本义 吟,呻也。--《说文》 吟,叹也。--《苍颉篇》 呿吟至微。--《素问·宝命全形论》。注谓吟叹也。” 昼吟宵哭；组词：吟呻(呻吟', '小学', '1'),
    ('吠', 'fèi', '7', '口', '左右', NULL, '吠〈动〉 (会意。从犬,从口。本义狗叫) 同本义 吠,犬鸣也。--《说文》 邑犬君吠兮所怪也。--《楚辞·九章》 谚云一犬吠形,百犬吠声。”--王符《潜夫论·贤难》；组词：吠声(狗叫声)；吠日(很少见到太阳的狗,偶尔见到太阳出来就狂叫,喻少见多怪) 泛指动物鸣叫 恶言攻击 吠形吠声 吠 fè', '小学', '1'),
    ('否', 'fǒu', '7', '口', '上下', NULL, '否〈副〉fou (会意。从口,从不。不”亦兼表字音。本义不然,不是这样) 否,不也。--《说文》 否臧凶。--《易·师》 否德黍帝位。--《书·尧典》。注皆训不。” 唐雎对曰否；组词：这是妥当的办法吗?否 非,不是 大人否亨', '小学', '1'),
    ('吧', 'bā', '7', '口', '左右', NULL, '吧 像东西爆烈或撞击的声音 吧 三老爷只顾吧着他的杂拌烟。--《死水微澜》 又如他吧了一口烟,才开始说明 吧 英语 bar 的译音,小酒馆；组词：他吧了一口烟,才开始说明 吧 英语 bar 的译音,小酒馆,又称酒吧 吧 bā 象声词小木棍~的一声断了', '小学', '1'),
    ('吨', 'dūn', '7', '口', '左右', NULL, '吨 (形声。从口,屯声。本义重量单位。公制1吨为 1000 公斤) 同本义 质量和重量的单位 等于 20 长担或 2240磅的单位', '小学', '1'),
    ('吩', 'fēn', '7', '口', '左右', NULL, '吩咐 (方言又叫吩示) 张大爷吩咐我好生照看小马驹 吩 fēn 【吩咐】(也写作"分付")叮嘱,嘱咐,多用于口头分派或命令这件事,~咐他去办理。~咐她早点回来。', '小学', '1'),
    ('含', 'hán', '7', '口', '上下', NULL, '含〈动〉 (形声。从口,今声。本义含在嘴里) 同本义 含,嗛也。--《说文》 含,口也,合口亭之也。衔亦然也。--《释名·释饮食》 含哺而熙,鼓腹而游；组词：含哺(口衔食物)；含殓(含口；含口垫背', '小学', '1'),
    ('听', 'tīng', '7', '口', '左右', NULL, '听 (形声。本字从耳德,壬声。从耳德,即耳有所得,今简化为听”。听”本义笑貌”。从口,斤声。本义用耳朵感受声音)；组词：听知(听到)；听受(聆听,用耳感受声音 听(聽)tīng 1.用耳朵接受声音~录音', '小学', '1'),
    ('吭', 'kēng', '7', '口', '左右', NULL, '吭〈动〉 出声 吭〈名〉haang 鸟的喉咙,泛指喉咙;咽喉 吭háng 1.喉咙,嗓子引~(放开喉咙,拉长嗓子)高歌。 2.见kēng、hàng。 吭kēng 1.出声', '小学', '1'),
    ('吮', 'shǔn', '7', '口', '左右', NULL, '吮 (形声。从口,允声。本义用口含吸,缓饮) 同本义 医善吮人之伤,含人之血。--《韩非子·备内》 磨牙吮血,杀人如麻。--李白《蜀道难》 母曰非然也。往年吴公吮其父；组词：吮痈(用嘴吸痈疽的脓血以祛毒)；吮疮(以口嘬吸疮疽之毒)；吮卒(为士兵嘬吸疮口的脓血)；吮嘬(用嘴吸) 舐 吮shǔn嘬', '小学', '1'),
    ('启', 'qǐ', '7', '口', NULL, NULL, '启 (会意。从户,从口。甲骨文字形,左边是手(又),右边是户(单扇门);用手开门,即开启的意思◇繁化加口”,或省去手(又)而成启”。金文又加攴”成啓”。现简化为 启”。本义开；组词：启(啟、啓)qǐ 1.开,打开,开发,开拓~开', '小学', '1'),
    ('吱', 'zī', '7', '口', '左右', NULL, '吱 zhi 细小的声音 人语闹吱嗻。--《牡丹亭》 吱 发出 老孙头看看四周,却不吱声。--《暴风骤雨》 吱 zi 多形容小动物的叫声 形容物体发出短促的尖叫声 做声', '小学', '1'),
    ('吴', 'wú', '7', '口', '上下', NULL, '吴 (会意。从口,从矢。矢,象头的动作∠起来表示晃着头大声说话。本义大声说话,喧哗) 同本义 不吴不敖,胡考之休。', '小学', '1'),
    ('吵', 'chǎo', '7', '口', '左右', NULL, '吵--古人名用字。 吵吵 一个一个说,别吵吵 吵 (形声。从口,少声。本义叫嚷) 同本义 吵嘴', '小学', '1'),
    ('吸', 'xī', '6', '口', '左右', NULL, '吸 (形声。从口,及声。本义吸气入体内) 同本义 吹呴呼吸,吐故纳新。--《庄子·刻意》 不食五谷,吸风引露。--《庄子·逍遥游》；组词：吸呼(呼吸)；吸留(變滓喘吸的样子)；吸风(吸气', '小学', '1'),
    ('吹', 'chuī', '7', '口', '左右', NULL, '吹 (会意。从口,从欠。欠”是出气的意思。本义合拢嘴唇用力呼气) 同本义 吹,嘘也。--《说文》 生物之以息相吹也。--《庄子·逍遥游》；组词：吹火筒；吹火(吹气使火旺盛', '小学', '1'),
    ('吻', 'wěn', '7', '口', '左右', NULL, '吻 (形声。从口,勿声。本义嘴唇) 同本义 吻,唇两角头边也。--《华严经音义》 黄吻澜漫赤。--左思《娇女诗》 遂鼓吻奋爪以向先生。--马中锡《中山狼传》；组词：接吻；亲吻 嘴；口 使人之吻助己言谈', '小学', '1'),
    ('吼', 'hǒu', '7', '口', '左右', NULL, '喉〈名〉 喉头 喉,咽也。--《说文》 喉咽者,量肠之府也。--《后汉书·马融传》 断其喉。--唐·柳宗元《三戒》；组词：喉吻(喉头与嘴唇)；喉头气 (因生气发怒而感到喉头憋闷)；喉韵(饮茶后喉头产生的甘爽的回味) 喻要害之地；交通要道 吼h', '小学', '1'),
    ('呀', 'ya', '7', '口', '左右', NULL, '呀 (形声。从口,牙声。本义张口的样子)表示惊异 呀 吱吱嘎嘎的声音 呀 表示语气。啊”受前一字韵母的影响而发生变音。如他从小就没有了家呀!群众的力量真大呀!老张', '小学', '1'),
    ('呆', 'dāi', '7', '口', '上下', NULL, '呆 痴;傻 呆霸王调情遭苦打。--《红楼梦》 又如呆霸王(《红楼梦》中薛蟠的浑号);呆里撒奸(装痴卖呆以售其奸);呆串了友(呆得不可收拾);呆想(痴想);呆人(呆子,傻瓜)；组词：呆霸王(《红楼梦》中薛蟠的浑号)；呆里撒奸(装痴卖呆以售其奸)；呆串了友(呆得不可收拾)；呆想(痴想)；呆人(呆子,傻瓜', '小学', '1'),
    ('呈', 'chéng', '7', '口', '上下', NULL, '呈 (形声。从口,壬声。本义平) 同本义 呈,平也。--《说文》 呈现,显现,显露 呈,显也。--《广韵》 延颈秀项,皓质呈露,芳泽无加,铅华弗御。--曹植《洛神赋》。注见也；组词：呈华(显示才华)；呈瑞(呈现祥瑞)；呈质(呈现本体) 送交,呈报--送东西给人的敬词 献 汝曹呈艺已遍,吾当呈艺', '小学', '1'),
    ('告', 'gào', '7', '口', '上下', NULL, '告〈动〉 (会意。甲骨文字形,上面的牛”,牛触人,角着横木,所以告人也。从口,从牛。本义报告,上报)', '小学', '1'),
    ('呐', 'nà', '7', '口', '左右', NULL, '呐〈动〉na 呐喊,大叫 且说史进就中堂又放起火来,大开了庄门,呐声喊,杀将出来。--《水浒传》 呐 〈叹〉 表示提醒注意 呐,我们可以开始了', '小学', '1'),
    ('呕', 'ǒu', '7', '口', '左右', NULL, '呕 (形声。从口,区声。本义东西在胃喉中上涌,从口中出来) 同本义 欧,吐也。--《说文》。字亦作呕。 吾伏噄呕血。--《左传·哀公二年》 其音如呕；组词：呕逆(恶心想吐)；呕泄(吐泻)；呕家(平素患有恶心、呕吐的病人) 古通讴”', '小学', '1'),
    ('员', 'yuán', '7', '口', '上下', NULL, '员 (会意。甲骨文字形,表示俯视鼎,看到鼎口是圆形的。小篆从贝,口声。本义物的数量;人员的数额。亦指人员)；组词：员位(人员定额；职位)；员次(员额等次) 官员的定额', '小学', '1'),
    ('呛', 'qiàng', '7', '口', '左右', NULL, '呛 鸟啄食物 呛,鸟食。--《玉篇》 呛 愚笨 呛 有刺激性的气体进入嗅觉器官、呼吸器官或视觉器官,使人感觉难受 受;又比喻说话有火气,生硬而尖刻);烟呛人;尘土呛人 吃', '小学', '1'),
    ('呜', 'wū', '7', '口', '左右', NULL, '呜 口中舒发而出的声音,叹息声。悲叹 及与公卿言国家事,未尝不噫呜流涕。--《后汉书·袁安传》；组词：呜呃(悲叹)；呜乎(呜呼)；呜唈(因悲哀、愤懑而抑郁气塞)；呜恻(悲泣)；呜噎(呜咽', '小学', '1'),
    ('呢', 'ne', '8', '口', '左右', NULL, '呢〈助〉ne 用在疑问句末,表示疑问 用在反问句末,加强反问 用在陈述句末,表示对事实的确认或强调 用在陈述句末', '小学', '1'),
    ('周', 'zhōu', '8', '口', '半包围', NULL, '周 (象形。甲骨文字形,在田”里加四点,郭沫若认为周象田中有种植之形。”有稠密和周遍的意思。小篆析为会意,从用口。段玉裁认为,善用口则周密。本义周密;周到而没 有疏漏)；组词：周悉(周密)；计划不周；周谋( 周zhōu 1.环绕,循环绕场一~', '小学', '1'),
    ('味', 'wèi', '8', '口', '左右', NULL, '味 (形声。从口,未声。本义滋味) 同本义 味,滋味也。--《说文》 以五味五谷五药养其病。--《周礼·疾医》 味者,气之父母也。--《鹖冠子·泰录》 五味六和十二食；组词：味如嚼蜡(比喻诗文枯燥,读后令人心情不舒)；入味(有滋味)；味口(犹胃口', '小学', '1'),
    ('呵', 'hē', '8', '口', '左右', NULL, '呵〈叹〉 表示惊异或赞叹。同啊” 呵,青春,愿你光芒四射。--郭小川《致青年公民》 呵ɑ助词。 1在句尾,〈表〉惊奇、赞叹等语气,常因前面字音的不同,而有各种变音', '小学', '1'),
    ('呻', 'shēn', '8', '口', '左右', NULL, '呻〈动〉 (形声。从口,申声。本义吟诵) 同本义 学业荒呻毕。--范成大《藻侄比课》 又如呻毕(诵读书籍。毕,书简);呻唤(因劳苦病痛而呻吟或叫唤) 病痛时低声哼 疾者思愈；组词：呻毕(诵读书籍', '小学', '1'),
    ('呼', 'hū', '8', '口', '左右', NULL, '呼 (形声。从口,乎声。本义吐气,与吸”相对) 同本义 呼,外息也。--《说文》(外息,指呼气) 阴盛则呼吸万物而藏之内也。--《书·大传》 候呼引针；组词：呼哈(呼吸吞吐)；呼噏(吐云纳气)；呼息(呼吸,喘气)；呼翕(呼气和吸气) 大声叫喊 呼,唤也', '小学', '1'),
    ('命', 'mìng', '8', '口', '半包围', NULL, '命 (会意。从口从令。表示用口发布命令。本义指派;发号) 同本义 命,使也。--《说文》。朱骏声按在事为令,在言为命,散文则通,对文则别。令当训使也,命当训发号也', '小学', '1'),
    ('咆', 'páo', '8', '口', '左右', NULL, '咆〈动〉 (形声。从口,包声。本义野兽吼叫) 同本义 咆,嗥也。--《说文》 袭穴而不敢咆。--《淮南子·览冥》 虎豹斗兮熊罴咆。--《文选·刘安招隐士》。注吼也；组词：咆号(吼叫)；咆跃(吼叫跳跃) 咆páo 1.猛兽怒吼', '小学', '1'),
    ('和', 'hé', '8', '口', '左右', NULL, '和 和谐;协调。 和,相应也。--《说文》 和,谐也。--《广雅》 音声相和。--《老子》 乐从和。--《国语·周语下》 倡予和女。--《诗·郑风·? 鸣鹤在阴,其子和之；组词：和合日(和谐、合好的吉日)；和合会(合好；和谐)；和令(和谐畅适)；和比(和谐) 和顺；平和 和(龢)hé 1.音乐和谐', '小学', '1'),
    ('咏', 'yǒng', '8', '口', '左右', NULL, '咏 (形声。从口,永声。又作詠”。本义曼声长吟;歌唱) 同本义 詠,歌也。或从口。--《说文》。段注尧典曰‘歌永言。’乐记曰‘歌为之言也,长言之也。说之,故言之;言之不足；组词：咏士(诗人)；咏雪(咏絮', '小学', '1'),
    ('咐', 'fù', '8', '口', '左右', NULL, '吩咐”嘱托;安排 咐 fù 【吩咐】见fēn吩。 咐fú 1.嘘气。参见"呕咐"。', '小学', '1'),
    ('咒', 'zhòu', '8', '口', '上下', NULL, '咒 (呪俗作咒。会意。从口从兄。兄”,祝”的本字。祝、呪本同一词。祝愿和诅呪是一件事的两面。本义祝告)；组词：咒延(祝祷延年益寿)；咒祝(祝祷祈福)；咒愿(向天或神佛祷祝,希望顺遂或表示心愿) 诅咒,乞求神灵降祸 忳咒曰有何枉状,', '小学', '1'),
    ('咕', 'gū', '8', '口', '左右', NULL, '咕〈象〉 形容刹车、低声说话等的声音 咕gū像声词。 1鸽子~ ~地叫。 2 3 4 5', '小学', '1'),
    ('咖', 'kā', '8', '口', '左右', NULL, '咖喱 ga 咖 ka (形声。从口,加声。咖啡木名。种子制成粉末可作饮料。也指这种饮料) --译音用字 咖啡 灌木或小乔木,花白色。种子炒熟制成粉可做饮料', '小学', '1'),
    ('咙', 'lóng', '8', '口', '左右', NULL, '咙 喉咙,咽部和喉部的统称 咙,喉也。--《说文》 又如咙胡(咽喉) 咙(嚨)lóng', '小学', '1'),
    ('咧', 'liě', '9', '口', '左右', NULL, '咧咧 瞎咧咧什么? 老是咧咧,让人笑话 咧 〈动〉 口微张,嘴角向两边伸展 咧lie助词。义同"了"、"啦"好~。她早到~。 咧lié 咧liě张开嘴或嘴斜着张开~着嘴笑', '小学', '1'),
    ('咨', 'zī', '9', '口', '上下', NULL, '咨 (形声。从口,次声。本义商议;征询) 同本义 咨,谋事曰咨。--《说文》。字亦作谘。 咨,谋也。--《尔雅》 周爰咨诹。--《诗·皇皇者华》 咨于故实；组词：咨叩(咨询求教)；咨考(询问查考)；咨度(咨询；商酌)；咨问(咨询；请教)；咨禀(请教；禀告) 叹息；赞叹 文王 咨zī', '小学', '1'),
    ('咪', 'mī', '9', '口', '左右', NULL, '咪 形容猫叫声或唤猫声 咪 微笑的样子 咪姥 咪咪 咪 法国长度单位米突”的省称 咪唑 咪mī 1.像声词。猫叫声。 2. 1呼猫声。 2微笑的样子笑~ ~。', '小学', '1'),
    ('咬', 'yǎo', '9', '口', '左右', NULL, '咬 (形声。从口,交声。《说文》本从齿”。本义用牙齿把东西夹住或切断弄碎) 同本义 易子而咬。；组词：咬姜呷醋(节约饮食用度)；咬牙关(形容痛恨、愤怒或发狠心)；咬瓦(比喻乏味)；咬定牙根(亦作咬定牙关”', '小学', '1'),
    ('咱', 'zán', '9', '口', '左右', NULL, '咱 zan (形声。从口,自声。本义我) 同本义 你若无意向咱行,为甚梦中频相见。--柳永《玉楼春》；组词：咱可(咱们；我们)；咱家(我)；咱每(咱们', '小学', '1'),
    ('咳', 'ké', '9', '口', '左右', NULL, '咳〈叹〉hai 啊 哎呀,唉,呜呼 该死!糟了! 表示感叹 嗨 咳 〈动〉 叹息 黛玉只咳”了一声,眼中泪直流下来,回身便走。', '小学', '1'),
    ('咸', 'xián', '9', '口', '半包围', NULL, '咸 (会意。据甲骨文。从戌,从口。戌是长柄大斧,口”指人头∠起来表示大斧砍人头。本义杀)；组词：咸腓(妄动)；咸感(阴阳相感,夫妇相和) 咸 普遍都,全部 咸,皆也,悉也', '小学', '1'),
    ('咽', 'yān', '9', '口', '左右', NULL, '咽 yan (形声。从口,因声。本义咽头) 同本义 咽,嗌也。--《说文》。段注咽者,因也,言食因于是以上下也。” 咽,又谓之嗌,气所流通,厄要之处也。--《释名》 咽已绝；组词：咽吭(咽喉', '小学', '1'),
    ('哀', 'āi', '9', '口', NULL, NULL, '哀〈形〉 (形声。从口,衣声。本义悲痛;悲伤) 同本义 哀,闵也。--《说文》 哀,痛也。--《广雅》 以凶礼哀邦国之忧。--《周礼·大宗伯》。注救患分灾。” 舍正路而不由哀哉；组词：哀咜(悲哀叹息)；哀诏(皇上驾崩后,新君通告全国的文书)；哀哉(表示悲伤或痛惜) 哎〈叹〉 表示满意或赞叹', '小学', '1'),
    ('品', 'pǐn', '9', '口', '上下', NULL, NULL, '小学', '1'),
    ('哄', 'hǒng', '9', '口', '左右', NULL, '哄〈动〉 (形声。从口,共声。本义许多人同时发声) 同本义 游人哄笑观俳优。--宋·孔平仲《上元作》；组词：哄笑；哄饮(聚众饮酒)；哄伙(形容热闹,盛大)；哄然；哄哄翕翕(潦潦草草；匆匆忙忙) 呵叱 叿,呵也', '小学', '1'),
    ('哆', 'duō', '9', '口', '左右', NULL, '哆 形容敲击声 张姑娘含着笑,皱着眉,把两只小脚儿点的脚踏儿哆哆的乱响。--《儿女英雄传》 哆 战栗 哆哆(喋喋。说话没完没了) 哆嗦 冷得打哆嗦 哆chǐ 1张口貌。 2哗然', '小学', '1'),
    ('哈', 'hā', '9', '口', '左右', NULL, '哈〈动〉 (形声。从口,合声。本义以唇啜饮。同歃”) 张口呼气 哈 身子略弯,以此表示礼貌(不及鞠躬郑重) 哈 口 臾儿、易牙,淄 渑之水合者,尝一哈水而甘苦知矣;故圣人之论贤也', '小学', '1'),
    ('响', 'xiǎng', '9', '口', '左右', NULL, '响 (形声。从口,鄉声。本义回声) 同本义 響,声也。--《说文》 炎光飞响。--《剧秦美新》 黄玉响应。--《史晨奏铭》 其受命也如响。--《易·系辞》 空谷传响,哀转久绝；组词：响臻(响应纷至)；响彻；响效(同响应) 声音 泠泠作响', '小学', '1'),
    ('哎', 'āi', '8', '口', '左右', NULL, '哎〈叹〉 表示满意或赞叹 。如哎,这就对了! 表示惊讶或不满意 。如哎,你怎么不早说! 表示提醒。如哎,小声点 表示醒悟 。如哎!原来是这样 表示招。如哎,大婶', '小学', '1'),
    ('哑', 'yǎ', '9', '口', '左右', NULL, '哑 (形声。从口,亚声。本义笑声) 同本义 哑,笑也。--《说文》 笑言哑哑。--《易·震》 乌鸦之类的叫声 乌之哑哑,鹊之唶唶。--《淮南子》 婴儿学说话的声音 哑,哑呕；组词：聋哑(又聋又哑)；哑子做梦(比 哑(啞)yǎ 1.不能说话~巴', '小学', '1'),
    ('哗', 'huá', '9', '口', '左右', NULL, '哗 (形声。从口,华声。本义喧哗,声大而杂乱) 同本义 哗 人声嘈杂,喧闹 哗然而骇者。--唐·柳宗元《捕蛇者说》 有辄哗笑之。--唐·柳宗元《答韦中立论师道书》 无敢哗者。', '小学', '1'),
    ('哟', 'yō', '9', '口', '左右', NULL, '哟 表示轻微的惊异(有时带玩笑的语气) 哟 用在句尾表示祈使语气。如用力拉哟! 用在歌词中做衬字。如呼儿海哟! 哟yo助词。 1用于句末或句中停顿处加把劲~。鲜菜~,鲜肉~', '小学', '1'),
    ('哥', 'gē', '10', '口', '上下', NULL, '哥 (会意。从二可。可”,有快乐”、欢乐”的意思。《诗·小雅·正月》哿矣富人。”毛传哿,可。”王引之《经义述闻》卷六哿与哀对文,哀者忧悲,哿者欢乐 也；组词：哥钟(即歌钟,古代打击乐器)；哥咏(歌咏) 哥哥 哥,声也', '小学', '1'),
    ('哨', 'shào', '10', '口', '左右', NULL, '哨〈形〉 (形声。从口,肖声。本义口小不能容的,一说口歪不正的) 同本义 哨,不容也。--《说文》 哨,口不容也。--《韵会》引《说文》 某有枉矢哨壶。--礼记·投壶》；组词：哨壶(口不正的壶) 细狭尖锐 哨,小也', '小学', '1'),
    ('哩', 'lǐ', '10', '口', '左右', NULL, '哩哩啦啦 开会时间已到,但厅内哩哩啦啦才来了几个人 哩哩罗罗 哩溜歪斜 他的字写得哩溜歪斜的 这个醉汉哩溜歪斜的走过来 哩〈助〉 用在陈述句末,表示肯定、猜测、夸张、强调等语气', '小学', '1'),
    ('哪', 'nǎ', '9', '口', '左右', NULL, '哪 na (形声。从口,那声。本义表疑问的词) 表示疑问,要求在同类事物中加以确指 表示任何一个 用于虚指,表示不确定的一个 哪 〈副〉 用于反问,表示肯定；组词：又不是你的东西,哪能随便拿 哪儿 这是哪儿对哪儿啊 哪个 哪nǎ疑问词', '小学', '1'),
    ('哭', 'kū', '10', '口', '上下', NULL, '哭〈动〉 (会意。甲骨文字形,从,表示号呼;中间象一人擗踊的样子。本义悲痛出声,声泪俱下)；组词：哭哭嘶嘶(边哭边喊)；哭唠叨(方言', '小学', '1'),
    ('哮', 'xiāo', '10', '口', '左右', NULL, '哮 (形声。从口,孝声。本义野兽的吼声) 同本义 哮,豕惊声也。--《说文》 虎声谓之哮唬。--《通俗文》 哮阚之兽。--曹植《七启》。注虎怒也。” 熊罴哮我东,虎豹号我西；组词：哮吼(野兽吼叫)；咆哮(吼叫)；哮唬(虎啸声)；哮阚(猛兽咆哮', '小学', '1'),
    ('哲', 'zhé', '10', '口', '上下', NULL, '哲 (形声。从口,折声。本义聪明,有智慧) 同本义 哲,知也。--《说文》。古文从三吉(嚞),字亦作喆。作悊 哲,智也。--《尔雅》 世有哲王。--《诗·大雅·下武》 哲夫成城；组词：哲士(聪明智慧、见识超常的人)；哲子(贤明的人)；哲艾(指明达的老人)；哲母(贤明的母亲)；哲匠(指明达而富有才能的大臣', '小学', '1'),
    ('哺', 'bǔ', '10', '口', '左右', NULL, '哺 (形声。从口,甫声。本义口中含嚼的食物) 同本义 辍饭吐哺。--《汉书·高帝纪》 稚子咽哺。--《汉书·匈奴传赞》 周公吐哺,天下归心。--曹操《短歌行》；组词：一饭三吐哺 哺 吃食 众人皆醉,何不餵其糟而啜其醨?--《楚辞·渔父》 子之从于子敖来,徒餵啜也', '小学', '1'),
    ('哼', 'hēng', '10', '口', '左右', NULL, '哼〈动〉 (形声。从口,亨声。本义痛苦作声) 同本义。訇的俗字 且睡在床上推病,口里哼哼囋囋的不绝。；组词：哼贲(呻吟', '小学', '1'),
    ('唁', 'yàn', '10', '口', '左右', NULL, '唁 (形声。从口,言声。本义对遭遇非常变故者的慰问◇多指对遭遇丧事的人的慰问) 公孙于齐,齐侯唁公于野井。；组词：唁奠(吊唁祭奠)；唁劳(对遭丧事者进行慰问)；唁慰(对死者家属表示安慰) 唁yàn吊丧,对遭遇丧事者表示慰问~言', '小学', '1'),
    ('唆', 'suō', '10', '口', '左右', NULL, '唆 (形声。本义怂恿人做坏事) 同本义 怎禁猪八戒气不忿,在旁漏八分儿唆嘴道师父,说起这个女子,他是此间农妇,...却怎么栽他是个妖怪?；组词：唆讼(教唆诉讼的简称)；唆教(挑拨；唆弄)；唆掇(撺掇；怂恿)；唆犯(调唆；撺掇)；唆哄(教唆哄骗)；唆激(教唆挑动)', '小学', '1'),
    ('唇', 'chún', '10', '口', NULL, NULL, '唇 (形声。从口,辰声。本义嘴唇) 同本义 脣,缘也,口之缘也。--《释名·释形体》 谚所谓辅车相依,脣亡齿寒者。--《左传·僖公五年》 唇焦口燥呼不得；组词：唇吻(言语)；唇红齿白(形容面貌俊美)；唇不离腮(比喻亲密无间,形影不离)；唇齿之邦(非常亲密、利害攸关的邻邦) 边缘', '小学', '1'),
    ('唉', 'āi', '10', '口', '左右', NULL, '唉〈叹〉 (形声。从口,矣声。本义表示答应) 同本义 唉,应也。--《说文》 唉,予知之。--《庄子·知北游》。释文应声。” 勤唉厥生。--《韦贤讽谏诗》；组词：你一定要去呀!”唉,我是要去的', '小学', '1'),
    ('唐', 'táng', '10', '口', NULL, NULL, '唐〈形〉 (形声。小篆作字形。从口,庚声。本义大话) 唐,大言也。--《说文》 荒唐之言。--《庄子·天下》 唐之为言荡荡也。--王充《论衡》 广大 平原唐其坛曼兮；组词：唐唐(广大；浩荡)；唐皇(气势宏伟盛大) 在温室中生长的,人工培育的 空；徒然 唐 〈名〉 朝代名', '小学', '1'),
    ('唠', 'lào', '10', '口', '左右', NULL, '唠 (形声。从口,劳声。本义唠叨) 同本义 不休);这段时间她一直唠叨,讲一些鸡毛蒜皮的话 唠(噝)láo 唠(噝)lào〈方〉说话,闲谈随便~。我们来~一~。', '小学', '1'),
    ('唤', 'huàn', '10', '口', '左右', NULL, '唤 (形声。从口,奂声。本义呼,叫,) 同本义 唤,呼也。--《说文新附》 不闻爷娘唤女声。--《乐府诗集·木兰诗》 千呼万唤始出来。--唐·白居易《琵琶行(并序)》；组词：唤门(在门外叫内边的人开门)；唤应(呼应,照应)；唤字叫背(掷钱猜正反面赌博) 呼唤使来 虑诸公不奉诏,于是先唤周侯、丞', '小学', '1'),
    ('唧', 'jī', '10', '口', '左右', NULL, '唧 (形声。从口,即声。本义象声词。唧唧杂乱细碎的声音;秋虫鸣声) 同本义 唧 突然有力的喷射出 吸水上喷 唧咕 唧唧 虫声唧唧 唧唧嘎嘎 唧唧喳喳 女孩子们一直在唧唧喳喳地说 唧', '小学', '1'),
    ('唬', 'hǔ', '11', '口', '左右', NULL, '唬 虚张声势、夸大事实来吓人 唬,虎声也。从口虎。--《说文》 又如你别唬人;唬吓(吓唬);唬弄(糊弄。欺骗;蒙混) 唬hǔ 1.虚张声势,威吓("吓"读hè)或欺蒙莫~人；组词：你别唬人；唬吓(吓唬)；唬弄(糊弄', '小学', '1'),
    ('售', 'shòu', '11', '口', '上下', NULL, '售 (形声。从口,雔省声。本义卖出去) 同本义 售,卖出手也。--《说文新附》 卖之,不可偻售也。--《荀子·儒效》 吾售之,人取之,未尝有言；组词：售卖(卖出；出售) 买 欲居之以为利,而高其值,亦无售者', '小学', '1'),
    ('唯', 'wéi', '11', '口', '左右', NULL, '唯 (形声。从口,隹声。本义急声回答声) 同本义 唯者,应之速而无疑也。--《助字辨略》朱注 子曰参乎!吾道一以贯之。”曾子曰唯；组词：唯阿(唯、阿同为应对 语词', '小学', '1'),
    ('唱', 'chàng', '11', '口', '左右', NULL, '唱〈动〉 (形声。从口,昌声。唱”字经传以倡”为之。本义领唱) 同本义 唱,导也。--《说文》 取其唱予和女。--《左传·昭公十六年》注 唱和有应。--《荀子·乐论》 晷漏肃唱；组词：唱和(唱歌时此唱彼和) 倡导；发起◇作倡” 为天下唱,宜多应者', '小学', '1'),
    ('唾', 'tuò', '11', '口', '左右', NULL, '唾〈名〉 (形声。从口,垂声。本义口液,唾沫) 同本义 唾,口液也。--《说文》 脾为涎,肾为唾。--《素问》 汝身已见唾成珠,汝伯何由发如漆!--唐·杜甫《醉歌行》；组词：唾腺(唾液腺)；唾沫星(口液的细小点子)；唾盂(痰盂)；唾壶(一种大肚痰盂) 唾 〈动〉 吐唾沫 必唾其面', '小学', '1'),
    ('啃', 'kěn', '11', '口', '左右', NULL, '啃 (形声。从口,肯声。本义用牙齿剥食坚硬的东西) 同本义 比喻刻苦钻研 同坑”。坑,害 我的大太爷?那真啃死小人了!', '小学', '1'),
    ('啄', 'zhuó', '11', '口', '左右', NULL, '啄 (形声。从口,豿声。本义鸟用嘴取食) 同本义 啄,鸟食也。--《说文》 啄啮也。--《广雅》 谁家燕子啄春泥。--唐·白居易《钱塘湖春行》 檐牙高啄；组词：啄抱(禽鸟幼雏破壳而出)；啄啄(禽鸟取食的样子)；啄饮(啄食饮水)；啄噪(啄食鸣叫)；啄木 用嘴理 敲击 归来残月窥窗角', '小学', '1'),
    ('商', 'shāng', '11', '口', '上下', NULL, '商〈动〉 (会意。从阩,章省声。本义计算,估量) 同本义 商,从外知内也。--《说文》。段注汉律志云商之言章也。物成熟可章度也。” 商,度也。--《广雅》 虏必商军进退,稍引去；组词：商略(估计)；商算(计算)；商度(测量)；商羊(传说中一种能预知雨的鸟)；商谜(猜谜)；商功(古代九章算术之一,即测量体', '小学', '1'),
    ('啊', 'ā', '10', '口', '左右', NULL, '啊 (形声。从口,阿声。本义叹词) 表示惊叹或赞颂。如啊!多么美丽的夜色;啊!祖国,我为您歌唱 啊á叹词。在句首,〈表〉疑问或反问~,这是什么?~,你想干什么? 啊ǎ叹词。在句首', '小学', '1'),
    ('啡', 'fēi', '11', '口', '左右', NULL, '见咖啡”、吗啡” 啡 fēi 1. 【吗啡】见吗。 2. 【咖啡】见咖。', '小学', '1'),
    ('啤', 'pí', '11', '口', '左右', NULL, '啤酒(德语 beer 的音译) 啤酒厂 啤pí', '小学', '1'),
    ('啥', 'shá', '11', '口', '左右', NULL, '啥〈代〉 甚么 );干啥 啥shá〈方〉什么你要干~?有~说~。 啥shà 1.方言。什么。', '小学', '1'),
    ('啦', 'lā', '11', '口', '左右', NULL, '啦〈动〉 同拉”。闲扯,闲谈 啦la助词,"了"和"啊"的合音。在句末,作用与"了"相似天晴~。别走~!春天来~。 啦lā像声词嗨~ ~。叽哩哇~。', '小学', '1'),
    ('啸', 'xiào', '11', '口', '左右', NULL, '啸 (形声。从口,肃声。本义撮口作声,打口哨) 同本义 啸,吹声也。--《说文》 其噕也歌。--《诗·召南·江有汜》 不噕不指。--《礼记·内则》 激于舌端而清谓之啸；组词：啸傲林泉(在幽静的山林泉水环抱中隐居)；啸吟(长啸哀叹)；啸指(以指夹唇吹之作声) 呼召,号召 噕者,谓若有所召命,若齐', '小学', '1'),
    ('啼', 'tí', '12', '口', '左右', NULL, '啼〈动〉 (形声。从口,帝声。本义放声痛心地哭) 同本义 嗁,号也。--《说文》。段注号,痛声也。” 见人方引婴儿欲投之江中,婴儿啼。--《吕氏春秋·察今》 妇啼一何苦；组词：啼呼(哭叫,叫唤)；啼饥(因饥饿而号哭)；啼天哭地(非常悲惨)；啼咽(悲哽) 叫鸣 自在娇莺恰恰啼', '小学', '1'),
    ('喂', 'wèi', '12', '口', '左右', NULL, '喂 (餵、喂是近代的餧”字) 喂食 餧,饲也。--《玉篇》 季春之月,餧兽之药,毋出九门。--《礼记·月令》 如以肉餧虎。--《汉书·张耳陈馀传》 骥不骤进而求服兮', '小学', '1'),
    ('善', 'shàn', '12', '口', '上下', NULL, '善〈形〉 (会意,从言,从羊。言是讲话。羊是吉祥的象征。本义吉祥) 同本义 善,吉也。--《说文》 来者以善日邪时,孰与邪日善时?--《汉书·翼奉传》；组词：善时(吉时)；善祥(吉祥；吉兆)；善征(吉兆)；善日(吉日) 好；美好 母氏圣善', '小学', '1'),
    ('喇', 'lǎ', '12', '口', '左右', NULL, '喇〈象〉 形容忽然发出的声音。如忽喇喇;刀枪喇喇;哗喇(象声词);呼喇 喇叭 汽车喇叭 喇叭裤 喇伙 这喇伙的事,而今行不得! 喇嘛 喇嘛教 喇子 喇lǎ 1. 1中管乐器之一', '小学', '1'),
    ('喉', 'hóu', '12', '口', '左右', NULL, '喉〈名〉 喉头 喉,咽也。--《说文》 喉咽者,量肠之府也。--《后汉书·马融传》 断其喉。--唐·柳宗元《三戒》；组词：喉吻(喉头与嘴唇)；喉头气 (因生气发怒而感到喉头憋闷)；喉韵(饮茶后喉头产生的甘爽的回味) 喻要害之地；交通要道 喉急', '小学', '1'),
    ('喊', 'hǎn', '12', '口', '左右', NULL, '喊 (形声。从口,咸声。本义尝味) 同本义 狄牙能喊,狄牙不能齐不齐之口。--《法言·问神》 大声呼叫 唤醒 召请;呼唤 喊hǎn大声叫,呼唤~口号。~叫几声。快~她来。', '小学', '1'),
    ('喘', 'chuǎn', '12', '口', '左右', NULL, '喘 (形声。从口,聑声。本义喘息,急速地呼吸) 同本义 喘,疾息也。--《说文》 其发咳喘。--《素问·五常正大论》 牛喘吐舌。--《汉书·丙吉传》 喘喘然将死；组词：心跳气喘；累得直喘；喘喝(中气不顺,口鼻有声的样子)；喘乏(气喘困乏) 轻声说话 礼义以为文,伦类以为理,喘而言', '小学', '1'),
    ('喜', 'xǐ', '12', '口', '上下', NULL, '喜 (会意。甲骨文上面是鼓”本字,下面是口”。鼓”表示欢乐,口”是发出欢声。本义快乐;高兴)', '小学', '1'),
    ('喝', 'hē', '12', '口', '左右', NULL, '喝〈动〉 (形声。从口,曷声。本义声音幽咽。如嘶喝。又指饮。特指饮酒) 饮。北方称饮为喝 喝 〈叹〉 用以表示惊讶。同嗬” 喝〈动〉 大声喊叫 喝声之幽也。；组词：呼幺喝六；喝神弄鬼(形容大喊大叫)；喝号(大声吆喝)；喝拳(高声划拳)；喝报(大声报告)；喝喊(呼喊) 恐吓威胁 喊移', '小学', '1'),
    ('喧', 'xuān', '12', '口', '左右', NULL, '喧 (形声。从口,宣声。宣”有宣扬”义,也有表义作用。本义声音大而嘈杂) 同本义 喧,大语也。；组词：喧议(喧闹议论)；喧埃(尘世的喧嚷)；喧吓(喧哗恐吓)；喧卑(喧闹低下)；喧哄(喧闹) 喧(諠)xuān声音大,声音杂乱', '小学', '1'),
    ('喳', 'zhā', '12', '口', '左右', NULL, '喳喳 半夜总听见哪里喳喳 喳喳 你们别喳喳了 zha (形声。从口,查声。本义啁啾;震颤声)；组词：喳喳(鸟鸣声；高叫声)；唧唧喳喳 下级(或仆人)对上级(或主人)的应诺声 只见那家人连声应道喳!喳!”回头就去了', '小学', '1'),
    ('喷', 'pēn', '12', '口', '左右', NULL, '喷 (形声。从口,贲声。本义怒叱) 同本义 喷,咤也。--《说文》。徐灏注笺今俗语犹谓咤人曰喷。” 泉水自地下涌出;喷出,喷射 子不见夫唾者乎?喷则大者如珠,小者如雾；组词：喷噀(喷出)；喷沫(喷涌泡沫)；喷沸(喷涌沸腾)；喷筒(旧时装火药以喷射的火器)；喷激(喷涌激荡)；喷蛆(詈词', '小学', '1'),
    ('喻', 'yù', '12', '口', '左右', NULL, '喻〈动〉 (形声。从口,俞声。本义告知,把情况通知某人。同谕”) 同本义 喻,告也。--《广雅》 教之以利,而喻诸德者也。--《礼记·文王世子》 晓喻;开导 前后告喻,曾无悛改；组词：喻勉(开导勉励)；喻教(开导教育) 知晓；明白 君子喻于义', '小学', '1'),
    ('嗅', 'xiù', '13', '口', '左右', NULL, '嗅 (形声。从口,臭声。字本作臭”,由犬、自(鼻)”会意,狗的鼻子灵敏,善于闻嗅。本义用鼻子辨别气味)；组词：嗅石(神兽名)；嗅闻(用鼻子辨别气味) 嗅xiù用鼻子闻,以辨别气味~到臭味', '小学', '1'),
    ('嗓', 'sǎng', '13', '口', '左右', NULL, '嗓〈名〉 喉咙 嗓音 嗓 爱打击、揭发别人的短处或隐私 播开门闩钻进来,抹抹索索找饭嗓。--清·蒲松龄《聊斋俚曲集》 嗓sǎng 1.喉咙。~子。 2.声带与发出的声音低~音', '小学', '1'),
    ('嗜', 'shì', '13', '口', '左右', NULL, '嗜shì喜欢,特别爱好,爱好而成习惯~学。~酒。~好。', '小学', '1'),
    ('嗡', 'wēng', '13', '口', '左右', NULL, '嗡 飞虫特有的持续刺耳声或很快的不规则的震动产生的声音 嗡wēng像声词~ ~ ~飞机声。蚊子太多~ ~音不停。 嗡wěng 1.声音通过鼻腔发出,含糊不清。', '小学', '1'),
    ('嗤', 'chī', '13', '口', '左右', NULL, '嗤 (形声。从口,蚩声。本义讥笑,嘲笑) 同本义 岂多嗤呼。--《后汉书·隗嚣传论》。注笑也。” 人皆嗤吾固陋,吾不以为病。--宋·司马光《训俭示康》；组词：嗤靳(讥笑、羞愧他人)；嗤嗤(讥笑)；嗤鄙(讥笑轻视)；嗤玩(嘲笑玩弄)；嗤戏(讥笑戏弄) 嗤 形容布等扯裂之声 嗤 表', '小学', '1'),
    ('嗦', 'suō', '13', '口', '左右', NULL, '哆嗦”发抖,战栗 嗦suo 1. 2. 嗦suō 1.见"哆嗦"。 2.见"啰嗦"。 3.见"嗦嗦"。', '小学', '1'),
    ('嗽', 'sòu', '14', '口', '左右', NULL, '嗽 (形声。从口,歠声。本义咳嗽) 同本义 嗽,咳嗽。--《玉篇》 冬季有嗽,上气疾。--《周礼》 他干嗽了几声 嗽sòu 嗽shuò 1.吮吸。 嗽shù 1.漱口。', '小学', '1'),
    ('嘀', 'dī', '14', '口', '左右', NULL, '嘀嗒 嘀咕 你一个人在这里嘀咕什么? 他又犯嘀咕了 嘀 dī又见dí。 【嘀里嘟噜】形容说话很快,使人听不清楚。 嘀 dí。又见dī。 【嘀咕】 1小声说;私下说。 2猜疑', '小学', '1'),
    ('嘁', 'qī', '14', '口', '左右', NULL, '嘁〈象〉 形容低语声或轻细的声音。多叠用 嘁哩喀喳 嘁嘁喳喳 传来单调的嘁嘁喳喳的声音 嘁qī', '小学', '1'),
    ('嘉', 'jiā', '14', '口', '上下', NULL, '嘉 (形声。从壴,加声。本义善,美) 同本义 嘉,美也。--《说文》 嘉,善也。--《尔雅》 孚于嘉。--《易·随》 嘉靖殷邦。--《书·无逸》 以嘉视亲万民；组词：嘉羞(美味的食品)；嘉况(丰厚的赏赐)；嘉言(善美的言辞)；嘉祉(美善幸福) 幸福；吉祥 蒙获嘉瑞,赐兹祉福', '小学', '1'),
    ('嘱', 'zhǔ', '15', '口', '左右', NULL, '嘱 (形声。从口,属声。本义嘱托,叮嘱) 同本义 去时嘱我。--晋·干宝《搜神记》 嘱学使俾入邑庠。(嘱咐考试官让成名进县学学习。学使,提督学政即学台,是专管教育和考试的官。俾；组词：嘱板(嘱其牵扳) 嘱(囑)zhǔ托付,吩咐,叮咛,告诫遗~', '小学', '1'),
    ('嘲', 'cháo', '15', '口', '左右', NULL, '嘲 chao (形声。从口,朝声。本义嘲笑) 同本义 以至于杂以嘲戏。--曹丕《典论·论文》；组词：冷嘲热讽；嘲问(带讽刺地问)；嘲戏(嘲弄嬉戏) 唱,按音律发声 因使元翌等嘲,以酒为韵', '小学', '1'),
    ('嘴', 'zuǐ', '16', '口', '左右', NULL, '嘴 (嘴,本作觜。嘴是后起的累增字。形声。从口,觜声。本义同觜”。猫头鹰之类头上的毛角)；组词：嘴片子(嘴皮子', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('嘶', 'sī', '15', '口', '左右', NULL, '嘶 (形声。从口,斯声。本义声音沙哑) 同本义 莽为人,...露眼赤睛,大声而嘶。--《汉书·王莽传》；组词：嘶嚷(吵闹)；嘶嗄(沙哑)；嘶喝(声音沙哑无力)；嘶竭(沙哑得发不出声)；嘶丑(沙哑粗浊)；嘶涩(沙哑干涩)；声嘶力竭', '小学', '1'),
    ('嘹', 'liáo', '15', '口', '左右', NULL, '嘹〈形〉 声音清脆悠扬 嘹亮 歌声嘹亮 军号吹出的头几个音符格外嘹亮 嘹liáo 嘹liào 1.犹闯。闯荡,奔走。', '小学', '1'),
    ('嘿', 'hēi', '15', '口', '左右', NULL, '嘿〈叹〉 (形声。从口,黑声。本义叹词,表示招呼、赞叹或惊异) 同本义 表示招呼或提起注意。如嘿,老钟,到这儿来! 表示惊讶。如嘿,这种事少见! 表示得意或赞叹。如嘿', '小学', '1'),
    ('器', 'qì', '16', '口', '上中下', NULL, '器 (会意。从犬。《说文》象器之口,犬所以守之。”器物很多,用狗看守。本义器具) 同本义 器,皿也。', '小学', '1'),
    ('噩', 'è', '16', '口', NULL, NULL, '噩 通愕”。惊愕 凶恶 严肃;严正 淳朴 肥腴貌 噩 è惊人的;可怕的。 【噩耗】惊人的坏消息特指亲近或敬爱的人去世的消息。 【噩梦】可怕的梦。', '小学', '1'),
    ('噪', 'zào', '16', '口', '左右', NULL, '噪 (形声) 同本义 又如噪呤(鸣叫);噪天(鸟名。即云雀) 大声喧嚷 以毁谤言之,贞良见妒,高奇见噪。--汉·王充《论衡》 又如噪逐(叫骂驱逐);噪儿巴喝(方言。哇啦哇啦乱嚷)；组词：噪呤(鸣叫)；噪天(鸟名', '小学', '1'),
    ('嚎', 'háo', '17', '口', '左右', NULL, '嚎〈动〉 (形声。从口,豪声。本义吼叫;鸣叫) 同本义 昼夜风不止,寒树嚎未休。--梅尧臣《宁陵阻风雨寄都下亲旧》；组词：嚎啸(呼啸)；鸡嚎天欲白 大声哭喊', '小学', '1'),
    ('嚣', 'xiāo', '18', '口', '上中下', NULL, '嚣 (会意。从棘,从页。棘,众口。页,人头。表示众口喧嚣。本义喧哗,声音响而闹哄) 同本义 嚣,嚣声也。气出头上。；组词：嚣争(吵闹；争夺)；嚣湫(尘嚣渊隘)；嚣鄙(喧闹鄙俗)；嚣号(喧嚷) 害臊；害羞 嚣xiāo 1.喧哗,吵闹喧~', '小学', '1'),
    ('嚷', 'rǎng', '20', '口', '左右', NULL, '嚷嚷 谁在那儿嚷嚷 屋里一片乱嚷嚷 这件事,你可别嚷嚷 嚷 吵闹 叫喊 责备;训斥 嚷 叫喊声 只觉得耳朵边满是嘈杂的嚷。--鲁迅《故事新编》 嚷叫 嚷rāng 1吵闹,喧哗~闹', '小学', '1'),
    ('嚼', 'jiáo', '20', '口', '左右', NULL, '嚼〈动〉 jiao (形声。从口,爵声。本义以牙磨碎食物) 同本义 嚼,削也。--《释名》 嚼,噬嚼也。--《玉篇》；组词：嚼蜡(多指文章或讲话没有滋味,没有意思)；嚼吞(咀嚼吞食)；嚼咽(咀嚼吞咽)；嚼头(经得起咀嚼的厚味(多用比喻义)) 吃', '小学', '1'),
    ('囊', 'náng', '22', '口', NULL, NULL, '囊揣 同囊膪” 囊膪 囊〈名〉 (形声。大篆字形象两头扎起的口袋。本义有底的口袋) 同本义 囊,橐也。', '小学', '1'),
    ('囚', 'qiú', '5', '囗', '全包围', NULL, '囚〈动〉 (会意。从人在囗(围)中。本义拘禁、囚禁) 同本义 囚,系也。--《说文》 囚,拘也。--《尔雅》 在泮献囚。--《诗·鲁颂·泮水》 斯率囚；组词：囚阱(押进地牢)；囚解(拘禁押送)；被囚；囚奴(囚禁奴役)；囚拘(囚禁)；囚桎(囚禁) 俘获,在战争中抓获 限制,围困', '小学', '1'),
    ('四', 'sì', '5', '囗', '全包围', NULL, '四 (指事。甲骨文字形,象鼻子喘息呼气之形。本义数目。三加一所得) 同本义 四,阴数也。四分之。；组词：四垂(四边)；四梢(城镇四方边缘地方)；四隅头(四方街口,四处)；四柱(指人出生的年、月、日、时)；四不拗六(少数拗不过', '小学', '1'),
    ('回', 'huí', '6', '囗', '全包围', NULL, '回 (囘为回的古字; 廻为迴的俗字。囬、迴同回。象形。甲骨文象渊水回旋之形。本义回旋;旋转)；组词：回湍(回旋的急流)；回倒(回旋倾倒)；回纡(迂 回(囬)huí 1.返,还,归~家乡', '小学', '1'),
    ('因', 'yīn', '6', '囗', '全包围', NULL, '因 (会意。从囗大。大,人。甲骨文字形,象人在车席子上。本义茵”的本字,坐垫,车垫) 同本义 因,就也。；组词：因果报应(佛教指物有起因必有结果,善因得善果,恶因得恶果)；前因后果 机会 于今无会因', '小学', '1'),
    ('团', 'tuán', '6', '囗', '全包围', NULL, '团 (形声。从囗,专声。本义圆) 同本义 团,圆也。--《说文》 裁为合欢扇,团团似明月。--《文选·班婕妤·怨歌行》；组词：团扇(圆形的扇子', '小学', '1'),
    ('囤', 'dùn', '7', '囗', '全包围', NULL, '囤 dun 用竹篾垫子或荆条编织物或用席子等围成的盛粮食的围栏 用木栅围成,填以土石,作堤防或防御工事之用 缘河堤埽,止用蒲绳泥草,不能持久。宜编木为囤,填石其中,则水可杀；组词：囤塌(积存；囤积)；囤货；囤粮；囤户(囤货以牟利的人家) 囤积 囤tún 1.积存粮食或货物等~积', '小学', '1'),
    ('园', 'yuán', '7', '囗', '全包围', NULL, '园 (形声。从囗,袁声。形符为囗”,表示范围。本义种蔬菜、花果、树木的地方) 同本义 园,所以树果也。；组词：园头(禅寺内管菜园的人)；果园；植物园；园公(即东园公', '小学', '1'),
    ('困', 'kùn', '7', '囗', '全包围', NULL, '困 (会意。甲骨文字形,从囗,象房的四壁;里边是生长的树木。本义废弃的房屋) 同本义 困,故庐也。', '小学', '1'),
    ('围', 'wéi', '7', '囗', '全包围', NULL, '围 (形声。从囗,韦声。囗”是围”的古字。本义环绕) 同本义 囗,回也,象回币之形。--《说文》。段注按,围绕, 周围字当用此。” 围,裹也。--《广雅·释诂四》 范围天地之化；组词：围堑(围绕营垒的壕沟)；围圆(圆形围墙)；围地(四周山川环绕,形势险峻的地方)；围屏(屏风)；围落(篱笆,栅栏) 包围', '小学', '1'),
    ('固', 'gù', '8', '囗', '全包围', NULL, '固 (形声。从囗,围”的古体字,象四周围起来的样子,古声。本义坚,坚固) 同本义 固,四塞也。；组词：固项(牛皮制的护领)；固阴(隆冬时阴气固结)；固植(根基巩固', '小学', '1'),
    ('国', 'guó', '8', '囗', '全包围', NULL, '国 (会意。从囗”,表示疆域。从或(即国”)。或”亦兼表字音。本义邦国) 周代,天子统治的是天下”,略等于现在说的全国” 国,邦也。', '小学', '1'),
    ('图', 'tú', '8', '囗', '全包围', NULL, '图 (会意。从囗,从啚。囗,表示范围。啚,鄙”的本字,表示艰难∠起来表示规划一件事,需慎重考虑,相当不容易。本义谋划,反复考虑)；组词：试图(打算)；图计(谋划) 图谋；谋取 阙秦以利晋,唯君图之', '小学', '1'),
    ('圃', 'pǔ', '10', '囗', '全包围', NULL, '圃〈名〉 (形声。从囗,甫声。囗,围的古体字。从囗的字往往表示某一个范围或区域。本义种植果木瓜菜的园地。周围常无垣篱)；组词：花圃(种花草的园地)；园圃(种蔬菜花果、树木的场所)；苗圃；圃畦(种蔬菜花果的园畦)；圃田 圃pǔ种植蔬菜、花草、苗木等', '小学', '1'),
    ('圆', 'yuán', '10', '囗', '全包围', NULL, '圆 (形声。从囗,员声。本义圆形) 同本义 圆,圜全也。--《说文》 圆而神。--《易·系辞》 天道曰圆,地道曰方。--《大戴礼记·曾子天圆》 中吾规者谓之圆；组词：圆丢丢(圆溜溜)；圆浑(浑圆)；圆领(明朝官员的常礼服', '小学', '1'),
    ('圈', 'quān', '11', '囗', '全包围', NULL, '圈 juan 把禽畜关在栅栏里 鼻赤象,圈巨猵。--《文选·张衡·西京赋》 又如把羊群圈起来 把犯人拘禁起来 闷在;关闭 我只恨天天圈在家里,一点儿做不得主,行动就有人知道；组词：把羊群圈起来 把犯人拘禁起来 闷在；关闭 我只恨天天圈在家里,一点儿做不得主,行动就有人知道', '小学', '1'),
    ('土', 'tǔ', '3', '土', '上下', NULL, '土〈名〉 (象形。甲骨文字形,上象土块,下象地面。金文中空廓变填实,小篆又变为线条。本义泥土,土壤)；组词：土粉(粉刷墙壁用的白垩 土tǔ 1.沙泥等的混合物~壤', '小学', '1'),
    ('圣', 'shèng', '5', '土', '上下', NULL, '圣 (形声。从耳,呈声。甲骨文字形。左边是耳朵,右边是口字。即善用耳,又会用口。本义通达事理)；组词：圣功(神灵的功力)；圣子(超凡入圣的儿子)；圣意(神灵的旨意)；圣明(英明) 聪明；才智胜人 圣人莫之', '小学', '1'),
    ('在', 'zài', '6', '土', NULL, NULL, '在 (形声。小篆字形。从土,才声。表示草木初生在土上。本义存活着,生存,存在) 同本义 在,存也。；组词：在生日(在世时)；祖父已经不在了；在日(在世之日)；在堂(母亲健在)；父母健在 居于,处于 朕在位七十载', '小学', '1'),
    ('地', 'dì', '6', '土', '左右', NULL, '地 用在状语和中心词之间 表示动态,相当于着”。常附在立、卧、坐等不及物动词的后头 后妻向床上卧地不起。', '小学', '1'),
    ('场', 'chǎng', '6', '土', '左右', NULL, '场 (形声。从土? 祭坛旁的平地 牺牲壇场。--《汉书·郊祀志》。注平地为场。” 灵场之威。--《法言·问明》。注鬼神之壇也。” 谷场,场子 一曰治谷田也；组词：打场(在场上脱粒)；禾场；摊场；晒场 场 cháng 1平坦的空地', '小学', '1'),
    ('圾', 'jī', '6', '土', '左右', NULL, NULL, '小学', '1'),
    ('址', 'zhǐ', '7', '土', '左右', NULL, '址 (形声。从土,止声。字本从阜,止声。本义地基,基部) 同本义 阯,基也。从阜,止声,或从土。；组词：芙蓉镇故址；厂址；住址 址(阯)zhǐ地基,地点基~', '小学', '1'),
    ('均', 'jūn', '7', '土', '左右', NULL, '均 (形声。从土,匀声。匀”亦兼表字义∠起来指土地分配均平。本义均匀;公平) 同本义 均,平也。；组词：均壹(公平专一)；均浃(平均而普遍)；均人(官名', '小学', '1'),
    ('坊', 'fāng', '7', '土', '左右', NULL, '坊〈名〉 (形声。从土,方声。本义城市中街市里巷的通称) 古代把一个城邑划分为若干区,通称为坊 两京及州县之郭内为坊,郊外为村。；组词：坊隅(街巷,街坊)；坊厢(古代城市区划,城中曰坊,近城曰厢)；坊市(街市)；坊郭(城郭市街) 官署名 明年春,大疫,为病', '小学', '1'),
    ('坎', 'kǎn', '7', '土', '左右', NULL, '坎 (形声。从土,欠声。本义坑,穴) 同本义 坎,陷也。--《说文》 坎者,陷也。--《易·序卦》 其坎深不至于泉。--《礼记·檀弓下》 钁其城为坎以先登；组词：坎儿(道路不平', '小学', '1'),
    ('坏', 'huài', '7', '土', '左右', NULL, '坏 (形声。从土,褱声。古代建筑物主要以土建造,故从土”。本义倒塌(指建筑物遭到破坏)。按古代坏”与壞”是音义都不相同的两个字。坏”,,是个从土、不声的形 声字,指未烧过的砖瓦', '小学', '1'),
    ('坐', 'zuò', '7', '土', NULL, NULL, '坐 (会意。《说文》古文作象形字,象两人坐在土上。本义人的止息方式之一。古人席地而坐,坐时两膝着地,臀部压在脚跟上)', '小学', '1'),
    ('坑', 'kēng', '7', '土', '左右', NULL, '坑〈名〉 (形声。从土,亢声。本义地面上凹下去的地方) 同本义 坑,堑也,壑也。--《玉篇》 或被坑水冲淹。--《广东军务记》；组词：刨个坑；挖坑；坑阱(泛指深坑)；坑坎(指地面高低不平；洼地；坑穴) 矿穴,矿场 其天下自五岭以北,见捋银坑,并宜禁断', '小学', '1'),
    ('块', 'kuài', '7', '土', '左右', NULL, '块 (形声。从土,鬼声。字本作剆”,是个会意字,表示土块装在筐器之中◇来写作塳”,变成了形声字,现在简化为块”。本义土块)；组词：块阜(小土丘)；块苏(土块和草堆', '小学', '1'),
    ('坚', 'jiān', '7', '土', NULL, NULL, '坚 (会意。从舘,从土。舘”,金文象以手拉臣”(屈服的奴隶)。从土”,表示土质坚硬。本义泥土坚硬)；组词：坚瓠(坚厚而实心的葫芦', '小学', '1'),
    ('坛', 'tán', '7', '土', '左右', NULL, '坛〈名〉 (形声。从土,亶声。本义土筑的高台,用于祭祀、会盟等) 同本义 坛,祭坛场也。--《说文》。除地曰场,曰墠,于墠筑土曰坛。坛无不墠,而墠有不坛。 为三坛同墠', '小学', '1'),
    ('坝', 'bà', '7', '土', '左右', NULL, '坝 (形声。从土,霸声。本义堤坝) 截河拦水的堤堰。堤坝 其河自西坝至东坝十六里有余。--单锷《吴中水利书》；组词：队；坝埽；顺坝 堤岸 平地 君家水茄白银色,殊胜坝里紫彭亨', '小学', '1'),
    ('坞', 'wù', '7', '土', '左右', NULL, '坞 防守用的小堡 又筑坞于瞫。--《后汉书·董卓传》 又如筑坞(构筑防守城堡);坞壁(防御用的土堡,土障。也称坞候) 泛指四面高中央低的处所 方离柳坞,乍出花房；组词：筑坞(构筑防守城堡)；坞壁(防御用的土堡,土障', '小学', '1'),
    ('坟', 'fén', '7', '土', '左右', NULL, '坟 (形声。从土,贲声。本义大防) 同本义 坟,大防。--《尔雅·释丘》 坟莫大于河坟。--《尔雅释地》 遵彼汝坟。--《诗·周南·汝坟》。传大防也。” 注或曰河坟,汝坟、淮坟也；组词：坟家(用土堆成的坟包) 通濆”', '小学', '1'),
    ('坠', 'zhuì', '7', '土', '上下', NULL, '坠 (形声。从土,队声。坠落到地上,故从土。本义落下,掉下) 同本义 隊,从高陨也。--《说文》。俗字作墜。 墜,落也。--《尔雅》 墜,堕也。--《广雅》 死而坠也；组词：坠睫(落泪)；坠楼(从楼上掉 坠(墜)zhuì 1.落,掉下,下沉~落', '小学', '1'),
    ('坡', 'pō', '8', '土', '左右', NULL, '坡〈名〉 (形声。从土,皮声。本义山地倾斜的地方) 同本义 坡,陂也。--《说文》 隰则有泮。--《诗·卫风·氓》。传泮,坡也。”；组词：山坡；上下坡；坡土(山坡地)；坡陀(山势起伏的样子；不平坦；山；山坡)；坡坂(倾斜的山坡)；坡梁(方言', '小学', '1'),
    ('坤', 'kūn', '8', '土', '左右', NULL, '坤 (形声。从土,申声。本义八卦之一,象征地) 地,大地 坤,地也,易之卦也。--《说文》 坤,土也。--《左传·庄公二十二年》 坤也者,地也。--《易·说卦》 山岳河渎；组词：坤元(坤的元始之德,指大地资生万物之德)；坤母(地；火)；坤后(地)；坤珍(象征大地的符瑞)；坤轴(想像中的地轴)；坤维', '小学', '1'),
    ('坦', 'tǎn', '8', '土', '左右', NULL, '坦〈形〉 (形声。从土,旦声。本义平而宽广) 同本义 坦,安也。--《说文》 道坦坦。--《易·履》 坦坦,平也。--《广雅》 坦气修通。--《管子·板法》。注平也。”；组词：平坦(没有高低凹凸)；坦夷(土地开阔平坦)；坦坦(平宽的样子)；坦迤(地势平缓而连绵不断)；坦途(平坦的路) 心安,宽舒', '小学', '1'),
    ('坪', 'píng', '8', '土', '左右', NULL, '坪〈名〉 (形声。从土,平声。本义平坦之地) 同本义,泛指山区和丘陵地区局部的平地 坪,地平也。；组词：草坪；停机坪 中国西北黄土地区的黄土阶地或台地', '小学', '1'),
    ('坯', 'pī', '8', '土', '左右', NULL, '坯 没有烧过的砖瓦、陶器 坏,瓦未烧也。--《说文》 又如砖坯;瓦坯 特指土坯 山丘一重。通坏” 山三袭,陟;再成,英;一成,坯。--《尔雅·释山》。义疏坯者,当作坏；组词：砖坯；瓦坯 特指土坯 山丘一重', '小学', '1'),
    ('坷', 'kě', '8', '土', '左右', NULL, '坷垃,坷拉 见坎坷” 坷kě 1道路或土地高低不平。 2不得志,不顺利。 坷kē', '小学', '1'),
    ('垂', 'chuí', '8', '土', NULL, NULL, '垂 (形声。从土,声。本义边疆) 通陲”。边疆;边境 垂,远边也。--《说文》。按,下垂的垂,说文作垂。 垂,疆也。--《广韵》 寡人无良边垂之臣；组词：垂堂(堂边近阶处屋檐下) 垂 垂挂 垂带悸兮', '小学', '1'),
    ('垃', 'lā', '8', '土', '左右', NULL, '垃圾 垃圾处理 垃圾箱 垃lā[垃圾]脏土或抛扔的破烂东西科学处理~圾。〈喻〉旧时遗留下来的反动腐朽的事物腐朽的~圾。', '小学', '1'),
    ('垄', 'lǒng', '8', '土', '上下', NULL, '垄 (形声。从土,龙声。本义坟) 同本义 生王之头,曾不若死士之垄也。--《战国策·齐策》；组词：垄墓(坟墓) 土埂 田埂 辍耕之垄上', '小学', '1'),
    ('型', 'xíng', '9', '土', '上下', NULL, '型 (形声。从土,刑声。本义铸造器物的模子。用木做的叫模,用竹做的叫范,用泥做的叫型) 同本义 型,铸器之法也。；组词：纸型；剂型；砂型；造型；铸型；模型 楷模 虽无老成人,尚有典型', '小学', '1'),
    ('垒', 'lěi', '9', '土', '上下', NULL, '垒 (形声。从土,畾(雷)声。本义军壁,防护军营的墙壁或建筑物) 同本义 垒,军壁也。--《说文》 四郊多垒。--《礼记·曲礼上》 营军之垒舍。--《周礼·夏官·量人》 因垒而降；组词：垒培(军营中的围墙等防御工事)；垒尉(官名', '小学', '1'),
    ('垛', 'duǒ', '9', '土', '左右', NULL, '垛 垛子;墙两侧或上头伸出的部分 垜,堂塾也。从土,朶声。门堂之塾有左右。左右各有南向北向两塾,今俗谓门两边伸出小墙曰垛头。；组词：垛口；垛迭(建筑物突出的部分,指门两旁伸出的墙)；垛楼(军官住的高楼) 设置箭靶的小土墙 罗灰修药灶,筑垛阅弓垜', '小学', '1'),
    ('垢', 'gòu', '9', '土', '左右', NULL, '垢〈名〉 (形声。从土,后声。本义污秽,尘土一类的脏东西) 同本义 垢,浊也。--《说文》 茫然彷徨乎尘垢之外。--《庄子·大宗师》 不吹毛而求小疵,不洗垢而察难知；组词：积垢；尘垢；泥垢；牙垢；污垢；耳垢 耻辱,因不名誉而产生的羞耻感 受天下之垢', '小学', '1'),
    ('垦', 'kěn', '9', '土', '上下', NULL, '垦 (形声。从土,声。本义翻土,开垦) 同本义 垦,耕也。--《说文新附》 垦,耕也。--《广雅·释地》 土不备垦。--《国语·周语上》 叩石垦壤。--《列子·汤问》；组词：垦化(谓开垦荒地使变为良田)；垦田(开垦耕地；已开垦的田地)；垦民(开荒种地的人)；垦草(垦荒', '小学', '1'),
    ('垫', 'diàn', '9', '土', '上下', NULL, '垫 (形声。从土,执声。本义下陷,淹没) 同本义 垫,下也。--《说文》 垫,下也。凡屋而下曰垫。--《方言六》 洪水滔天,浩浩怀山襄陵,下民昏垫。--《书·益稷》。郑注垫,陷也；组词：垫没(下沉)；垫溺(陷溺)；垫裂(塌陷破裂)；垫陷(下陷', '小学', '1'),
    ('垮', 'kuǎ', '9', '土', '左右', NULL, '垮〈动〉 (形声。从土,夸声。本义倒塌,崩溃瓦解) 同本义 溃败;遭到彻底失败 困顿不堪 垮 〈形〉 垮kuǎ 1.倒塌墙~了。〈引〉坏不要搞~了身体。 2.败敌军~了。', '小学', '1'),
    ('埂', 'gěng', '10', '土', '左右', NULL, '埂 (形声。从土,更声。本义小坑) 同本义 埂,秦谓坑为埂。--《说文》 埂,小坑也。--《玉篇》 假借为防”。堤封,用泥土筑起来的堤防 长条形的突出地面的地方 田埂', '小学', '1'),
    ('埃', 'āi', '10', '土', '左右', NULL, '埃〈名〉 (形声。从土,矣声。本义尘土;灰尘) 同本义 埃,尘也。--《说文》 埃,谓风扬尘也。--《苍颉篇》 灰尘曰埃。--《通俗文》 野马也,尘埃也,生物之以息相吹也；组词：埃尘(飞扬的尘土)；埃垢(灰尘污垢)；埃土(泥土,尘土) 埃〈名〉 埃及的略称 两种波长单位的任一种 一百亿分之一米,即', '小学', '1'),
    ('埋', 'mái', '10', '土', '左右', NULL, '埋 (形声.从土,里声.字本作薶”,甲骨文字形,象在坑中埋狗的形象,是向地神祭献的活动。本义藏入土中)；组词：埋地雷；埋玉(比喻英才或美女之死)；埋书(把盟书埋在地下', '小学', '1'),
    ('城', 'chéng', '9', '土', '左右', NULL, '城 (会意。从土,从成,成亦声。本义城墙) 同本义 城,所以盛民也。--《说文》 城郭沟池以为固。--《礼记·礼运》 使老弱女子乘城。--《史记·田单列传》 百雉而城；组词：城内；城外；万里长城；城守(据城守御)；城 城 chéng 1城市', '小学', '1'),
    ('域', 'yù', '11', '土', '左右', NULL, '域〈名〉 (形声。从土,或声。土,表示疆土。域”本作或”,与国”同义。从口,从戈,以守一。一,地也。”为会意字。本义疆界,疆域)；组词：域野(境内乡野)；域内(域中)；域外(境外；国外) 地区,区域 出百死,入绝域', '小学', '1'),
    ('埠', 'bù', '11', '土', '左右', NULL, '埠 (形声。从土,阜声。本义停船的码头。如船已抵埠) 同本义 埠,见《大明律》,官牙埠头,船埠头。谓主舶客商买卖货物也。', '小学', '1'),
    ('培', 'péi', '11', '土', '左右', NULL, '培〈动〉 (形声。从土,咅声。本义给植物或墙堤等的根基垒土) 同本义 培,培敦土田山川也。；组词：培户(昆虫把土堆在洞穴周围) 增益；增添 培养,教育 把东西埋在灰、沙中保存 培péi 1.在植物、墙堤等的根基部分加土', '小学', '1'),
    ('基', 'jī', '11', '土', '上下', NULL, '基 (形声。从土,其声。本义墙基) 同本义 基,墙始也。--《说文》 度幽宅兆基。--《仪礼·士丧礼》 止基迺理?--《诗·大雅·公刘》 于墙基之所,方整深耕；组词：基扃(城阙)；基趾(凡墙脚、城脚居下承上的,都叫基趾', '小学', '1'),
    ('堂', 'táng', '11', '土', '上下', NULL, '堂〈名〉 (形声。从土,尚声。尚”有高”义。本义殿堂。高于一般房屋,用于祭献神灵、祈求丰年)', '小学', '1'),
    ('堆', 'duī', '11', '土', '左右', NULL, '堆 (象形。从土,隹声。本义土堆) 土墩,沙墩或水中聚集的礁石 逾陇堆兮渡漠。--《楚辞·疾世》 激堆埼。--司马相如《上林赋》 呼水中沙堆为墠。--《尔雅·释水》注；组词：堆阜(小丘)；堆埼(曲折的岸边)--多用于地名', '小学', '1'),
    ('堕', 'duò', '11', '土', '上下', NULL, '堕 (形声。从土,隋声。甲骨文字形,右边是阜”(象陡坡),左边是倒过来的人”。会意。表示人从陡坡上掉下。本义毁坏)；组词：堕废(毁坏；衰落)；堕罪(降罪)；堕地(落地', '小学', '1'),
    ('堡', 'bǎo', '12', '土', '上下', NULL, '堡 (形声。从土,保声。堡是后起字。本义土筑的小城) 同本义 据险筑堡以自固。--《晋书·符登载记》 又 关中堡壁三千余所。；组词：碉堡；堡障(用于防守的小土城) 指堡垒 送将军登空堡上', '小学', '1'),
    ('堤', 'dī', '12', '土', '左右', NULL, '堤 (形声。从土,是声。本义河堤,堤坝) 同本义 隄,唐也。--《说文》 完堤防。--《礼记·月令》 脩堤梁。--《荀子·王制》 河堤绕绿水。--唐·李白《赠清漳明府侄聿》；组词：河堤；海堤；堤埽(堤和埽', '小学', '1'),
    ('堪', 'kān', '12', '土', '左右', NULL, '堪〈名〉 (形声。从土,甚声。本义地面高起) 同本义 堪,地突也。谓土之坟起者。--《说文》 堪坏得之,以袭昆仑。--《庄子·大宗师》；组词：堪岩(山形幽深) 指天道 堪舆徐行', '小学', '1'),
    ('堰', 'yàn', '12', '土', '左右', NULL, '堰 (形声。从土,匽声。本义拦河坝) 同本义 东出千金堰。--《文选·沈约·三月三日率尔成篇诗》 堰,潜堰也,潜筑土以壅水也。--《广雅》 长分桥西有千金堰；组词：都江堰；堰塘(筑有堤堰的蓄水池)；堰埭(截水的土堰)；堰埭(壅水的土坝) 田边用以分界或防止水土流失的土埂 池塘 桌椅板', '小学', '1'),
    ('堵', 'dǔ', '11', '土', '左右', NULL, '堵 (形声。从土,者声。本义墙壁) 同本义 堵,垣也。五版为一堵。--《说文》 环堵之室。--《淮南子·原道》 止如堵墙。--《尉缭子·战威》；组词：堵墙(墙垣,土墙', '小学', '1'),
    ('塌', 'tā', '13', '土', '左右', NULL, '塌〈动〉 因凹陷而倒塌 塌,堕也。--《广雅》 天崩地塌壮士死。--吴士玉《玉带生歌奉和漫堂先生》 忽忆雨时秋井塌。--杜甫《苏端薛复筵简薛华醉歌》；组词：塌岸(朽坏、坍塌的埽岸或堤岸)；房子塌了；倒塌(建筑物倒下来)；塌翼 减掉；垮 贴紧 安定；镇定 塌 〈形〉 平 精神委', '小学', '1'),
    ('塑', 'sù', '13', '土', '上下', NULL, '塑 (形声。从土,朔声。本义用泥土抟成人物形象) 同本义 明道先生(程颢)坐如泥塑人。--《二程全书·传闻杂记》 --宋·苏轼《凤翔八观维摩像唐杨惠之塑在天柱寺》；组词：塑人；塑像；泥塑；面塑 呆愣 把个公子如同泥塑一般,塑在那里', '小学', '1'),
    ('塔', 'tǎ', '12', '土', '左右', NULL, '塔〈名〉 (形声。从土,莈声。本义佛塔,亦作浮屠”) 同本义。晋、宋译经时始造塔”字。塔为形高而顶尖的佛教建筑物,多为五层七级,也有高至十三级的,初为藏佛骨(舍利子)的地方；组词：塔庙(寺庙)；塔院(建有佛塔的院子)；塔铃(佛塔上的风铃)；塔头(佛塔顶部)；宝塔；佛塔 形状像塔的建筑物 分馏柱或塔', '小学', '1'),
    ('塘', 'táng', '13', '土', '左右', NULL, '塘〈名〉 (形声。从土,唐声。本义堤岸) 同本义 池塘生春草。--谢灵运《登池上楼》 又如塘岸(堤岸);塘埝,塘埭(塘坝);塘堰(小型蓄水工程。现指塘坝);塘坟(近海盐区无山地；组词：塘岸(堤岸)；塘埝,塘埭(塘坝)；塘堰(小型蓄水工程', '小学', '1'),
    ('塞', 'sāi', '13', '土', NULL, NULL, '塞 (会意兼形声。从土,塞声。塞同罅,空隙之义。本义阻隔;堵住) 同本义 塞,隔也。--《说文》 四塞世告至。--《礼记·名堂位》。注四塞,谓夷服、镇服、蕃服在四方为蔽塞者；组词：塞耳(堵住耳朵)；塞绝(堵塞断绝)；塞噎(阻塞,哽噎)；塞话(使人生气的话)；塞狗洞(把银钱花在无用的地方)；塞除(堵塞', '小学', '1'),
    ('填', 'tián', '13', '土', '左右', NULL, '填〈动〉 (形声。从土,真声。本义充塞) 同本义 填,塞也。--《说文》 填坑满谷。--《史记·司马相如传》 填如也。--《荀子·大略》 宾客亦填门；组词：填馅(填空；代替)；填引(加引)；填坑满谷(塞满坑谷)；填街(充塞街道)；填咽(充满空间)；填盈(充满)；填宫(古代犯官', '小学', '1'),
    ('境', 'jìng', '14', '土', '左右', NULL, '境 (形声。从土,竟声。本义边境,国境) 同本义 境,疆也。--《说文新附》 至齐境。--《吕氏春秋·赞能》 字本作竟” 亡不越竟。--《左传·宣公二年》 边竟有人焉；组词：出境(离开国境)；入境(进入国境)；境宇(国境,疆土)；境人(境内之人；本地人)；境头(结果；亦作景头”', '小学', '1'),
    ('墅', 'shù', '14', '土', '上下', NULL, '墅 田庐;村舍。田间土舍 剧哉边海民,寄身于草墅。--曹植《泰山梁甫行》 别馆;在本宅之外营建的田庄园林 又于土山营墅,楼馆竹林甚盛。；组词：别墅(在郊区或风景区供游玩休养的园林房屋) 墅shù 1.住宅以外的供游玩休养的园林式房屋别~', '小学', '1'),
    ('墓', 'mù', '13', '土', '上下', NULL, '墓 (形声。从土,莫声。本义上古时期凡掘塘穴葬棺木,盖土与堆平,不植树者称墓。泛指坟墓)；组词：墓庐(墓旁的房屋)；墓隧(墓前或墓室 墓mù埋葬死人的地方~地', '小学', '1'),
    ('墙', 'qiáng', '14', '土', '左右', NULL, '墻 (会意。从啬,从土。啬”有节俭收藏的意思。垒土为墙,意在收藏。本义房屋或园场周围的障壁)；组词：墙阙(院落；门庭)；墙宇(房舍,住宅；喻指人的气度)；墙篱(藩篱,篱笆)；墙东(比喻隐居不仕,以避乱世)；墙茨(墙上生长', '小学', '1'),
    ('增', 'zēng', '15', '土', '左右', NULL, '增 (形声。从土,曾声。字本作曾”。本义增多) 同本义 增,益也。--《说文》 增,加也。--《广雅·释诂一》 鹰鸢犹以山为卑而增巢其上。--《荀子·法行》 残高增下；组词：增年(加寿；年龄增加)；增增(众多的样子)；增奉(增加俸禄 增zēng加,添~加', '小学', '1'),
    ('墨', 'mò', '15', '土', '上下', NULL, '墨 (会意兼形声。从土,从黑,黑亦声。本义书画所用的黑色颜料,用松烟等原料制成) 同本义 墨,书墨也。；组词：墨丸(古墨的一种)；墨本(碑帖的拓本)；墨工(制墨的工匠)；墨妆(脸部以墨化妆)；墨路(墨线) 指诗文或书画 墨客降席,', '小学', '1'),
    ('墩', 'dūn', '15', '土', '左右', NULL, '墩 (形声。从土,敦声。本义土堆) 同本义 墩,平地有堆。--《说文》 冶城访古迹,犹有谢安墩。--李白《登金陵冶城西北谢安墩诗》；组词：挖塘取土,垒土为墩；土墩；墩台(高一些的土堆台；报警台) 厚而粗大的整块木头、石头或用砖砌成的基础 墩 用于丛生的或几棵', '小学', '1'),
    ('壁', 'bì', '16', '土', '上下', NULL, '壁 (形声。从土,辟声。本义墙壁) 同本义 壁,垣也。--《说文》 壁亦土也。--《风俗通》 观壁垒于北落兮。--张衡《思玄赋》 家徒四壁立。--《汉书·司马相如传》 徘徊四顾；组词：壁有耳(指机密容易泄露,说话不可不慎', '小学', '1'),
    ('壕', 'háo', '17', '土', '左右', NULL, '壕〈名〉 (形声。从土,豪声。本义护城河) 同本义 雁迷寒雨下空壕。--唐·许浑《登洛阳故城》；组词：壕闸(壕堑的闸门)；壕池(城壕', '小学', '1'),
    ('壤', 'rǎng', '20', '土', '左右', NULL, '壤 (形声。从土,襄声)声。本义柔土,即经耕作的土地) 土壤 壤,柔土也。--《说文》 凡穿地四尺,为壤五尺,为坚三尺。--《九章算法》。按,息土曰壤,筑土曰坚。 厥土惟白壤；组词：壤坟(柔细肥沃,适于耕种的土地)；壤芥(泥土和小草)；沃壤 泛指泥土 夫太山不辞壤石', '小学', '1'),
    ('士', 'shì', '3', '士', NULL, NULL, '士〈名〉 (会意。从一,从十。善于做事情,从一开始,到十结束。本义古代男子的美称) 同本义 士,事也。', '小学', '1'),
    ('壮', 'zhuàng', '6', '士', '左右', NULL, '壮 (形声。从士,爿声。本义人体高大,肌肉壮实) 同本义 壮,大也。--《说文》 壮,健也。--《广雅》 秦晋之间凡人之大谓之奘,或谓之壮。--《方言》 三十曰壮；组词：壮浪(健壮)；壮盛(强壮旺盛)；壮勇(强壮而勇敢)；壮(壯)zhuàng 1.强健,有力强~', '小学', '1'),
    ('声', 'shēng', '7', '士', NULL, NULL, '声 (形声。从耳,殸声。殸”是古乐器磬”的本字,耳”表示听。本义声音;声响) 同本义 声,音也。；组词：声叉(声音不正常)；声嘶(声音破哑)；声如洪钟 声(聲)shēng 1.物体振动时所产生的能引起听觉的波~波', '小学', '1'),
    ('壳', 'ké', '7', '士', '上下', NULL, '壳 ke 壳 qiao 蠃蚌脱壳。-- 又如躯壳;甲壳;地壳;金蝉脱壳;介壳;外壳;躯壳;枳壳 壳(殻)ké 1.坚硬的外皮螺蛳~。鸭蛋~儿。荔枝~儿。 2.见qiào；组词：躯壳；甲壳；地壳；金蝉脱壳；介壳；外壳；躯壳；枳壳 壳(殻)ké 1.坚硬的外皮螺蛳~', '小学', '1'),
    ('壶', 'hú', '10', '士', '上下', NULL, '壶 (象形。甲骨文字形,象壶形。本义古代盛器) 同本义 壶,昆吾圆器也。--《说文》 国子执壶浆。--《公羊传·昭公二十五年》。注礼器,腹方口圆曰壶,反之曰方壶,有爵饰；组词：壶瓶(盛酒器)；壶滥(又名壶鉴', '小学', '1'),
    ('壹', 'yī', '12', '士', '上下', NULL, '壹 (形声。小篆字形。从壶,吉声。一”的大写。本义专一) 同本义 壹,专一也。--《说文》 君子壹教,凝子壹学,亟成。--《荀子·大略》 与人之壹也。--《左传·文公三年》。注壹；组词：壹心(同心；专心)；壹德(谓一心一意)；壹意(专心致志)；壹定(一贯不变,固定不变) 统一；一致 圣人之为国也,壹赏,壹', '小学', '1'),
    ('处', 'chǔ', '5', '夂', '半包围', NULL, '处〈动〉 (会意。从口,从文,或从处,虍声。处”即處”的古字,于六书为会意。金文加声旁虍”变成了形声字。本义中止;停止)', '小学', '1'),
    ('备', 'bèi', '8', '夂', '上下', NULL, '备 (形声。从人,備(衢??))声。本义谨慎、警惕) 同本义 事戒不虞曰知备。--《大戴礼记·小辨》 备者,国之重也。--《墨子·七患》 且夫备有未至而设之；组词：傥荡不备(行为无拘无束,不谨慎) 完备；齐备 备,具也', '小学', '1'),
    ('复', 'fù', '9', '夂', '上下', NULL, '复 (形声。小篆字形,下面的意符攵”,是甲骨文止”字的变形,表示与脚或行走有关。上面是声符畐”的省形,有腹满”义,在字中亦兼有表义作用◇来繁化,加义符彳 ”,表示行走', '小学', '1'),
    ('夏', 'xià', '10', '夂', '上中下', NULL, '夏 (会意。据小篆字形,从页,从臼,从攵。页,人头。臼,两手,攵,两足∠起来象人形。本义古代汉民族自称)', '小学', '1'),
    ('夕', 'xī', '3', '夕', NULL, NULL, '夕 (指事。从月半见。本义黄昏,傍晚) 同本义 夕,莫也。--《说文》 日之夕矣。--《诗·王风·君子于役》 日东则景夕多风。--《周礼·大司徒》。司农注谓日跌景乃中立表之处；组词：夕晖(夕阳的余晖)；朝发夕至；夕霭(黄昏的云气)；夕市(傍晚进行的集市贸易) 夜 今夕何夕', '小学', '1'),
    ('外', 'wài', '5', '夕', '左右', NULL, '外 (会意。从夕,从卜。通常在白天占卜,如在夜里占卜,表明边疆(外)有事。又有人说,因为要在外过夜,故要卜问吉凶。本义外面;外部)；组词：外户(从外面关闭的大门)；外祟(指外来的桅)；外槨(棺材外的套 外wài 1.跟"内"、"里"相对~面', '小学', '1'),
    ('多', 'duō', '6', '夕', '上下', NULL, '多 (会意。甲骨文字形,从二夕”。表示数量大。本义多,数量大,与少”、寡”相对) 同本义 多,重也。从重夕,会意。重夕为多,重日为叠。；组词：多次；多分(多半)；多士(众多士子)；多感(多谢,非常感激)；多口(多嘴)；多般(许多事端；多半；大概)；多口可(许多)', '小学', '1'),
    ('夜', 'yè', '8', '夕', '上下', NULL, '夜 (形声。金文字形。从月,亦声。本义从天黑到天亮的时间) 同本义 夜,舍也。天下休舍也。；组词：夜游子(爱在晚上游荡的人)；夜里个(昨天)；夜合钱(妓女接客所收的报酬)；夜行人(夜间秘密行事的人,如盗贼 夜(亱)yè', '小学', '1'),
    ('够', 'gòu', '11', '夕', '左右', NULL, '够 (形声。从多,句声。本义聚,多) 同本义 繁富夥够,非可单究。--晋·左思《魏都赋》；组词：够使(够多) 够 〈动〉 数量上满足；足够 钱不够 材料够了 达到某一点或某种程度 手等达到,触及 又如够不着 表示超过', '小学', '1'),
    ('大', 'dà', '3', '大', NULL, NULL, '大 (象形。甲骨文字形,象人的正面形,有手有脚。大”是汉字部首之一,从大”的字往往与人类或人事有关。本义大小的大”) 形容体积、面积、数量、力量、规模', '小学', '1'),
    ('天', 'tiān', '4', '大', '上下', NULL, '天〈名〉 (会意。甲骨文字形。下面是个正面的人形(大),上面指出是人头,小篆变成一横。本义人的头顶)；组词：天灵(人或其他动物的头顶骨)；天灵盖(头顶骨) 古代的墨刑', '小学', '1'),
    ('太', 'tài', '4', '大', '半包围', NULL, '太〈形〉 (指事。古作大”,后语音分化,在大”字下添加符号,成指事字。本义过于) 极大。古作大”,也作泰”。凡言大而以为形容未尽,则作太 太,大也。；组词：太虚幻境(天上虚幻的境界)；太 太tài 1.过于,过分~冷', '小学', '1'),
    ('夫', 'fū', '4', '大', NULL, NULL, '夫〈名〉 (象形。甲骨文字形,像站着的人形(大),上面的一”,表示头发上插一根簪(腺??)),意思是成年男子,是个丈夫了。古时男子成年束发加冠才算丈夫,故加一”做标志；组词：夫公( 夫 fū 1.旧时对成年男子的通称农~务农', '小学', '1'),
    ('夭', 'yāo', '4', '大', '上下', NULL, '夭〈名〉 刚出生的兽或禽 毋覆巢,毋胎夭。--《淮南子》 畋不掩群,不取麛夭;不涸泽而渔,不焚林而猎。--吴伯箫《猎户》 初生的草木 泽不伐夭。--《国语》 夭 yao (象形；组词：夭英(折断幼苗) 夭 短命,早死', '小学', '1'),
    ('央', 'yāng', '5', '大', NULL, NULL, '央 (会意。小篆字形。从大,在冂之内。上像物体(冂),一个人(大)站在它的当中。本义中心)；组词：央渎(出水沟) 通殃”', '小学', '1'),
    ('夯', 'hāng', '5', '大', '上下', NULL, '夯 同笨”。笨拙 小儿蠢夯,自幼失学。--《儒林外史》 又如夯汉(干粗笨体力活的人);夯货(笨货;蠢人) 另见膟杮夁 夯〈名〉 (会意。从大,从力。表示劳动时需要出大气力；组词：夯汉(干粗笨体力活的人)；夯货(笨货；蠢人) 另见膟杮夁 夯〈名〉 (会意', '小学', '1'),
    ('失', 'shī', '5', '大', NULL, NULL, '失 (形声。从手,乙声。表示从手中丢失。小篆字形。本义失掉;丢失) 同本义 失,纵也。--《说文》。段注在手而逸去为失。” 失得勿恤。--《易·晋》 故人情不失；组词：失状(丢失财物的清单)；失 失shī 1.丢,掉丢~', '小学', '1'),
    ('头', 'tóu', '5', '大', NULL, NULL, '头〈名〉 (形声。从页,豆声。页,人头。头在战国时期才出现,首出现较早。本义首) 同本义 頭,首也。；组词：头直上(头顶上)；光头(剃光的头；头上没有戴帽子)；头大(形容遇到困难头昏脑胀的样子 头(頭)tóu 1.脑袋,人体的最', '小学', '1'),
    ('夷', 'yí', '6', '大', NULL, NULL, '夷 (会意。从大从弓。本义东方之人。即我囯古代对对东部各民族的统称) 同本义 夷,东方之人也。从大,从弓,会意,弓所持也。字亦作巳。', '小学', '1'),
    ('夸', 'kuā', '6', '大', '上下', NULL, '夸 (形声。从大,于声。本义奢侈) 同本义 夸,奢也。--《说文》 贵而不为夸。--《荀子·仲尼》。注奢侈也。”；组词：夸丽(虚美浮华)；夸侈(奢侈,浮华)；夸恣(奢侈放纵) 通說”', '小学', '1'),
    ('夹', 'jiā', '6', '大', NULL, NULL, '夹 (会意。甲骨文字形,象左右二人从两边辅助中间一个人。本义从左右两方相持,从两旁限制)；组词：夹拥(左右围抱) 栽插在物体的两边 墙下当官道,依前夹竹篱', '小学', '1'),
    ('夺', 'duó', '6', '大', '上下', NULL, '夺 (会意。金文字形,上面象振翅欲飞的鸟,下面是手(又、寸),其意思是这只振翅欲飞的鸟,眼看着就要从手中失脱掉。本义丧失)；组词：夺宗(始封的国君被尊为诸侯以后,除去原来宗子的名分)；夺气(丧失了胆量和勇气)；夺魄(精神丧失而无生气)；夺胆(丧胆)', '小学', '1'),
    ('奄', 'yǎn', '8', '大', '上下', NULL, '奄 突然地 奄忽灭没。--马融《长笛赋》。注奄遽也。” 又如奄然(突然;悄然);奄至(急速来到) 奄 气息微弱的样子 奄,息也。；组词：奄然(突然；悄然)；奄至(急速来到) 奄 气息微弱的样子 奄,息也', '小学', '1'),
    ('奇', 'qí', '8', '大', '上下', NULL, '奇 ji (字源见奇。本义奇特,奇异) 单数,偶之对 奇,一曰不耦。--《说文》 阳数奇。--《白虎通·嫁娶》 一算为奇。--《仪礼·乡射礼》 奇肱之国,其人一臂三目,有阴有阳；组词：奇日(奇数之日', '小学', '1'),
    ('奈', 'nai', '8', '大', '上下', NULL, '奈〈代〉 如,如何 奈何去社稷也?--《礼记·曲礼下》 诸侯不从,奈何?--《史记·高祖本纪》 无奈何也。--《韩非子·喻老》 无可奈何。--《史记·屈原贾生列传》 亡奈何矣；组词：奈何天(言对付天公) 通耐”', '小学', '1'),
    ('奉', 'fèng', '8', '大', NULL, NULL, '奉〈动〉 (会意。小篆字形,从手,从収(双手),最上面像一串玉或树盖子。是用手捧物的意思。本义两手恭敬地捧着◇作捧”)；组词：奉书；奉地图；奉手(捧握长者之手) 恭敬地接受 奉 fèng 1.两手捧着臣愿~璧往使', '小学', '1'),
    ('奋', 'fèn', '8', '大', '上下', NULL, '奋 (会意。金文字形,中间是隹”(鸟);外面象鸟振翅欲飞之势;下面是田”,表示空旷的田野。本义鸟类振羽展翅)；组词：奋翅(振翼起飞)；奋翼(振翼高飞)；奋翔(振翼高飞)；奋鳞(龙腾飞)；奋翮(展翅,振羽 奋(奮) fèn 1.鸟类展翅~', '小学', '1'),
    ('奏', 'zòu', '9', '大', NULL, NULL, '奏 (会意。小篆字形。上为屮”,初生的草,有上进义;中为双手形;下为本”,行趋之义。本义奉献,送上)', '小学', '1'),
    ('契', 'qì', '9', '大', '上下', NULL, '契〈名〉 后时圣人易之以书契。--《易·系辞》 掌稽布之书契。--《周礼·质人》。注取予市物之券也,其券之象书两札,刻其侧。” 献粟者执右契。--《礼记·曲礼》 翟璜操右契而乘轩；组词：契卷(互相约束的证据)；契印(骑缝印', '小学', '1'),
    ('奔', 'bēn', '8', '大', '上下', NULL, '奔 (会意。金文字形,上面从大”(人),象人挥动双手,下面从止”(趾),而且是三个止”,表示快跑。本义快跑)；组词：东奔西跑；奔冲(奔驰,猛冲)；奔走呼号(一面奔跑,一面叫喊)；奔马；奔驹；奔丧(父母丧,儿女由外地赶回安葬守丧) 逃跑,', '小学', '1'),
    ('奕', 'yì', '9', '大', '上下', NULL, '奕 (形声。从大,亦声。本义大) 同本义 奕,大也。--《说文》 往小来奕。--《太玄·格》 四壮奕奕。--《诗·小雅·车攻》 奕奕梁山。--《诗·大雅·韩奕》 伯夷相唐；组词：奕世簪缨(子孙世代都为显宦贵族)；奕世(累世,代代)；奕代(奕世,累世)；奕叶(累世,代代) 光明 故其华表则镐 奕yì', '小学', '1'),
    ('奖', 'jiǎng', '9', '大', '上下', NULL, '奖 (形声。字本作妜”,从犬,将省声。本义驱使狗猛进) 同本义 奖,嗾犬厉之也。--《说文》。段玉裁注《口部》‘嗾,使犬声也。’厉之,犹勉之也。” 劝勉;鼓励 奖,劝也；组词：奖导(劝勉诱导)；奖激(劝勉激励)；奖慰(劝勉安慰)；奖鉴(勉励劝戒)；奖蹙威柄(勉励促成其成为权威者)；奖拔(勉励提拔', '小学', '1'),
    ('套', 'tào', '10', '大', '上下', NULL, '套〈名〉 (会意。从大,从长。套在外面的东西比被套者要大、长。本义罩在外面的东西) 同本义 指已成固定格式的办法或语言 衡量、要求事物的固定模式 地势弯曲的地方', '小学', '1'),
    ('奠', 'diàn', '12', '大', '上下', NULL, '奠 (象形。金文字形,上面是酋”(即酒”),下面象放东西的基物。本义设酒食以祭) 同本义。特指初死时的备供品敬礼 奠,置祭也。；组词：祭奠(为死者举行仪式,表示追念)；奠馔(置食物以祭 奠 diàn 1对死者陈设祭品表示悼念', '小学', '1'),
    ('奢', 'shē', '11', '大', '上下', NULL, '奢〈形〉 (形声。从大,者声。本义 奢侈,不节俭) 同本义 奢,张也。--《说文》。徐灏曰奢者侈靡放纵之义。故曰‘张’,言其张大也。” 奢言淫乐而显侈靡；组词：奢尚(奢侈的风尚)；奢欲(奢侈的欲望)；奢绮(奢侈华丽)；奢薄(风俗奢侈,人情,浇薄)；奢阔 奢shē 1.浪费,挥霍财', '小学', '1'),
    ('奥', 'ào', '12', '大', '上下', NULL, '奥〈名〉 (形声。本义古时指房屋的西南角。古时祭祀设神主或尊者居坐之处) 同本义 奥,宛也。室之西南隅。；组词：奥阼(室之西南隅,为尊者、主人之位) 泛指室内深处 室无奥阼', '小学', '1'),
    ('女', 'nǚ', '3', '女', NULL, NULL, '女〈名〉 (象形。甲骨文字形,象一个敛手跪着的人形。本义女性, 女人,与男”相对) 同本义 女,妇人也。；组词：女陪堂(女帮闲)；女先儿(女先生)；女红(泛指妇女干的纺织 女nǚ 1.女性,女人妇~', '小学', '1'),
    ('奴', 'nú', '5', '女', '左右', NULL, '奴〈名〉 (会意。从女,从又。女指女奴,又(手)指用手掠夺之。一说又(手)指女奴从事劳动。本义奴隶;奴仆)；组词：奴胎(对乐户子女或奴婢的贱称 奴nú 1.阶级社会中,丧失自由,遭受压迫、剥削、役使的人~仆', '小学', '1'),
    ('奶', 'nǎi', '5', '女', '左右', NULL, '奶 (古作嬭) (形声。从女,乃声。本义乳房) 同本义 今人谓乳房为奶,乳汁亦为奶。奶”是乳”的音转。--王力《同源字典》；组词：奶胖(乳子) 母 乳汁 我的血变了奶,吃的长这么大', '小学', '1'),
    ('奸', 'jiān', '6', '女', '左右', NULL, '奸 (会意。从三女。本义奸邪,虚伪狡诈) 同本义 姦,私也。--《说文》 姦,盗也。--《广雅》 在内曰姦,在外曰宄。--《三苍》 用轨之财者为姦。--《国语·鲁语》 寇贼姦宄', '小学', '1'),
    ('她', 'tā', '6', '女', '左右', NULL, '她〈代〉 (形声。从女,它”省声。本义女性第三人称) 同本义 称代美好的事物或者自己所敬重、热爱和喜欢的事物,往往用她”字 她们 她tā称第三人,特指女性~是巾帼英雄。出于敬慕', '小学', '1'),
    ('好', 'hǎo', '6', '女', '左右', NULL, '好〈形〉 (会意。从女,从子。本义美,貌美) 指女子貌美 好,美也。--《说文》 凡美色或谓之好。--《方言二》 不可谓好。--《国语·晋语》。注美也。” 是女子不好；组词：好皮囊(好看的外貌)；好鸟(美丽的鸟)；好不丑(反语', '小学', '1'),
    ('如', 'rú', '6', '女', '左右', NULL, '如 (会意。从女,从口。本义遵从,依照) 同本义 如,从随也。--《说文》。按,此字疑从女,若省声。女子从人者也。 有律以如己也。--《左传·宣公十二年》。杜预注如,从也；组词：如命(遵从命令)；如志(随顺意愿；实现志愿)；如令(从令,遵令) 好像, 如同 日初出大如车盖', '小学', '1'),
    ('妄', 'wàng', '6', '女', '上下', NULL, '妄 (形声。从女,亡声。本义胡乱) 同本义 妄,乱也。--《说文》 不通于轻重谓之妄言。--《管子·山至数》 以人自观谓之度,反度为妄。--《贾子道术》 施妄者,乱之始也；组词：妄口(胡说)；妄系(无故抓人入罪)；妄扳平人(胡乱牵连无辜之人)；妄施(随便地施恩)；妄折(无原则地屈从)；妄行(随便行', '小学', '1'),
    ('妆', 'zhuāng', '6', '女', '左右', NULL, '妆 (形声。从女,爿声。本义梳妆打扮) 同本义 妝,饰也。--《说文》。字亦作娤。 不待饰装(妆)。--宋玉《登徒子好色赋》 靓莊(妆)刻饰；组词：妆束(打扮的样式)；妆台(妇女梳妆用的镜台', '小学', '1'),
    ('妇', 'fù', '6', '女', '左右', NULL, '妇 (会意。甲骨文字形,左边是帚”,右边是女”。从女持帚,表示洒扫。本义已婚的女子) 同本义 媎,服也。从女,持帚,洒埽也。会意。谓服事人者。；组词：少妇；孕妇；媳妇；妇驵(交易时的女介绍人)；妇政(妇人参与政事)；妇人家(已婚妇女) 泛指妇女,常指成年女子 纵有健妇把', '小学', '1'),
    ('妈', 'mā', '6', '女', '左右', NULL, '妈 (形声。从女,马声。本义称呼母亲) 同本义 妈,母也。--《广雅·释亲》 又如有妈的孩子像个宝,没妈的孩子像根草;孩子的妈;谢谢妈 尊称长一辈或年长的妇女 称中老年女仆 妻子；组词：有妈的孩子像个宝,没妈的孩子像根草；孩子的妈；谢谢妈 尊称长一辈或年长的妇女 称中老年女仆 妻子,老伴 鸨母 妈mā 1', '小学', '1'),
    ('妒', 'dù', '7', '女', '左右', NULL, '妒 (形声。从女,户声。本义妇女忌妒丈夫。也指忌妒别的女子的姿色) ) 泛指忌妒别人 妆成每被秋娘妒。--唐·白居易《琵琶行(并序)》；组词：妒害(妒忌陷害)；妒纷(因互相妒忌而引起的争执、纠纷)；妒痴(过度的妒忌而引发的痴病)；妒刻(嫉妒刻薄)；妒富愧贫(忌妒', '小学', '1'),
    ('妓', 'jì', '7', '女', '左右', NULL, '妓 (形声。从女,支声。本义古代歌舞的女子) 同本义 妓,女乐也。--《广韵》 字本作伎 军装宫妓扫蛾浅,摇摇锦旗夹城暖。--李贺《三月》；组词：妓人(妓妇', '小学', '1'),
    ('妖', 'yāo', '7', '女', '左右', NULL, '妖 (形声。从女,夭声。) 同本义 妖,妍也。--《三苍》 妖夫曳衔。--《楚辞·天问》 妖冶闲都。--《汉书·司马相如传》。注妖冶,美好也。” 妖姬静女；组词：妖妍(艳丽)；妖姿(艳丽的姿容)；妖异(美艳奇异)；妖丽(艳丽)；妖靡(艳丽华美)；妖蛊(艳丽)；妖姬(美女)；妖玩(美', '小学', '1'),
    ('妙', 'miào', '7', '女', '左右', NULL, '妙 (会意兼形声。从女,从少,少亦声。美妙少女。本义美,好) 同本义 尽所历妙。--宋·陆游《过小孤山大孤山》；组词：天镜之句为妙；妙巧(美妙奇巧)；妙香(特好的香气)；妙丽(容貌美好)；妙观(美妙的观察)；妙引(佳美的文辞)；妙色(庄严', '小学', '1'),
    ('妥', 'tuǒ', '7', '女', '上下', NULL, '妥〈形〉 (会意。从爪女。爪指手。意思是得到了女子,就安稳、安定了。本义安稳,安定) 同本义 妥,安也。；组词：妥密(稳妥机密)；妥安(稳定)；妥妥(安定貌)；妥帖(安定；平静；稳当)；妥洽(稳妥合适)；妥干(稳妥干练)；妥绥(安定', '小学', '1'),
    ('妨', 'fáng', '7', '女', '左右', NULL, '妨〈动〉 (形声。从女,方声。本义损害;有害于) 同本义 妨,害也。--《说文》 将妨于国家。--《国语·越语》 敬而无妨些。--《楚辞·招魂》 令人行妨。--《老子》。注伤也；组词：妨要(妨害要务)；妨紊(伤害扰乱) 阻碍 无发令而干时,以妨神农之事', '小学', '1'),
    ('妹', 'mèi', '8', '女', '左右', NULL, '妹 (形声。从女,未声。本义妹妹) 称同父母或同父异母或同母异父比自己年纪小的女子 妹,女弟也。；组词：妹妹；妹丈(妹妹的丈夫)；妹婿(妹夫) 称亲戚中同辈(或为表示亲善对非亲戚中同辈)年纪比自己小的女子 古邑 妹 通昧”', '小学', '1'),
    ('妻', 'qī', '8', '女', '上下', NULL, '妻〈名〉 (会意。小篆字形从女,从屮,从又。屮”象家具形,又是手∠起来象女子手拿家具从事劳动的形象。本义男子的正式配偶)；组词：妻妾(嫡妻与侧室)；妻房(妻室,妻子)；妻儿(妻和儿女；妻)；妻姊妹婚(再与亡妻之姊、妹缔结婚姻)；妻谒(透过得宠的女子', '小学', '1'),
    ('姆', 'mǔ', '8', '女', '左右', NULL, '娒 (形声。从女,母声。本义中国古代教育未出嫁女子的妇人) 同本义 娒,女师也。--《说文》 姆纚笄宵衣在其右。--《仪礼·士昏礼》。注姆,妇人年五十,无子,出而不复嫁；组词：保姆(保母', '小学', '1'),
    ('姊', 'zǐ', '7', '女', NULL, NULL, '姊 (形声。本义姐姐) 同本义 姊,女兄也。--《说文》 男子谓女子先生为姊。--《尔雅》 遂及伯姊。--《诗·邶风·泉水》 阿姊闻妹来。--《乐府诗集·木兰诗》 又 小弟闻姊来；组词：姊丈(姐姐的丈夫)；姊夫(姐姐的丈夫)；姊弟(姐姐和妹妹或姐姐和弟弟)；姊儿(对妓女的称呼) 指母亲 如今之所谓者,若中', '小学', '1'),
    ('始', 'shǐ', '8', '女', '左右', NULL, '始 (形声。从女,台声。本义开头,开始) 同本义。与终”相对 始,女之初也。--《说文》。朱曰裁衣之始为初,草木之始为才,人身之始为首为元,筑墙之始为基,开户之始为戽', '小学', '1'),
    ('姐', 'jiě', '8', '女', '左右', NULL, '姐 (形声。从女,且声。本义母亲的别称) 蜀谓母曰姐。--《说文》。段玉裁注方言也,其字当蜀人所制。” 女兄。同父母或只同父或同母;年龄比自己大的女子 近世多以女兄为姐,盖尊之也；组词：大姐；二姐；姐妹；姐弟 称本族或亲戚同辈而年龄比自己大的(不包括称为嫂的)女子 尊称年纪和自己差不多的女子 对一般同辈女', '小学', '1'),
    ('姑', 'gū', '8', '女', '左右', NULL, '姑〈名〉 (形声。从女,古声。本义丈夫的母亲) 同本义 姑,夫母也。--《说文》 姑在则曰君姑,姑殁则曰先姑。又,妇谓夫之庶母为少姑。--《尔雅》 如母而非母也,姑也；组词：翁姑；姑嫜(古时妻子对丈夫父母的称呼,即公婆) 父亲的姐妹 父之姊妹为姑', '小学', '1'),
    ('姓', 'xìng', '8', '女', '左右', NULL, '姓 (会意兼形声。从女,从生,生亦声。本义标志家族系统的字) 同本义 姓,人所生也。--《说文》 左氏传曰天子建德,因生以赐姓。--《春秋·隐公八年》。按,神农母居姜水；组词：姓族(大族,望族)；姓字(姓氏和名字)；姓系(姓氏家族的源流系统)；姓第(姓氏行第) 命,性命 救民之姓而不夸,行补三君', '小学', '1'),
    ('委', 'wěi', '8', '女', '上下', NULL, '委 曲,委曲 委两馆于咸唐。--《楚辞·九叹·远游》 委貌,冠形有委曲之貌,上大下小也。--《释名·释首饰》 委委佗佗。--《诗·鄘风·君子偕老》 委 (会意。从女,从禾；组词：委折(曲折)；委注(曲折流往)；委宛(委曲婉转)；委纡(曲折)；委延(曲折蜿蜒)；委坠(曲折,遥远) 牛不知其死也,如土', '小学', '1'),
    ('姚', 'yáo', '9', '女', '左右', NULL, '姚 (形声。从女,兆声。本义姓) 同本义。相传为虞舜之后 姚,虞舜居姚虚,因以为姓。--《说文》。按,母名握登。大荒南经,帝俊妻娥皇,生此三身之国,姚姓。 姚 或为姚,娆也', '小学', '1'),
    ('姜', 'jiāng', '9', '女', '上下', NULL, '姜 (形声。从女,羊声。本义水名。姜水) 同本义 岐水经姜氏城为姜水。--《水经注·渭水》注 黄帝以姬水成,炎帝以姜水成。--《国语》 姓 姜,神农居姜水,以为姓；组词：姜太公钓鱼(姜子牙世称姜太公,即吕尚', '小学', '1'),
    ('姥', 'lǎo', '9', '女', '左右', NULL, '姥〈形〉lao 用同老” 姥姥 姥娘 姥〈名〉mu (形声。从女,老声。本义老年妇女的俗称)；组词：姥姥(称年老女仆) 通母”', '小学', '1'),
    ('姨', 'yí', '9', '女', '左右', NULL, '姨 (形声。从女,夷声。本义妻子的姐妹) 同本义 姨,妻之女弟同出为姨。--《说文》 妻之姊妹同出为姨。--《尔雅》 蔡哀侯曰吾姨也。--《左传·庄公十年》 东宫之妹,邢侯之姨；组词：姨夫(妻的姊妹夫；又两男共狎一妓,彼此互称姨夫) 母之姊妹 继室以其侄,穆姜之姨子也', '小学', '1'),
    ('姻', 'yīn', '9', '女', '左右', NULL, '姻 (会意兼形声。从女,从因,因亦声。本义女婿家) 同本义 姻,婿家也,女之所因,故曰姻。从女,从因,因亦声。；组词：姻母(对兄弟妻之母、姐妹夫之母以及疏亲前辈之妻的称呼) 妻或妻之父 姻(媋)yīn 1.〈古〉指女婿的父亲', '小学', '1'),
    ('姿', 'zī', '9', '女', '上下', NULL, '姿 (形声。从女,次声。本义姿态) 同本义(姿”侧重于呈现的姿势、风度) 姿,态也。--《说文》。按,态者,材艺巧善也。即才能、贤能本字。 嵇康身长七尺八寸,风姿特秀', '小学', '1'),
    ('威', 'wēi', '9', '女', NULL, NULL, '威 威力;威风 威,畏也。--《说文》 威也者,力也。--《吕氏春秋·荡兵》 有而可畏谓之威《史记·平原君虞卿列传》 严大国之威。--《史记·廉颇蔺相如列传》 秦王之威；组词：威风杀气(威风恶煞；盛气凌人)；威弧(很有威力的弧矢)；威折(以威力使之折服)；威服(以威力慑服)；威柄(威权,权力)', '小学', '1'),
    ('娃', 'wá', '9', '女', '左右', NULL, '娃 (形声。从女,圭声。本义美女) 同本义 娃,美也。吴楚衡淮之间曰娃。吴有馆娃之宫。--《方言》二；组词：娃姣(美女)；娃馆(宫女的馆舍)；娃儿(美貌女郎) 小孩子；尤指仍在怀抱中的年幼孩子 少女；姑娘 邻娃尽著绣裆襦,独自提', '小学', '1'),
    ('娄', 'lóu', '9', '女', '上下', NULL, '娄 物体中空的 娄,空也。--《说文》。段玉裁注凡中空曰娄,今俗语尚如是。” 娄 收敛 莫肯下遣,式居娄骄。--《诗·小雅·角弓》 娄 二十八宿之一,西方白虎七宿的第二宿', '小学', '1'),
    ('娇', 'jiāo', '9', '女', '左右', NULL, '娇〈形〉 (形声。从女,乔声。本义妩媚可爱) 同本义(柔嫩美态) 娇,姿也。--《说文新附》 娇,女字,亦态。--《广韵》 娇,娇姿也。--《玉篇》 娇逸未有婚；组词：娇影(娇美动人的影子)；娇娇痴痴(故作娇痴之态)；娇婢侈童(娇贵奢侈的婢女童仆)；娇羞(妩媚含羞的样子)；娇娥(美丽的妇', '小学', '1'),
    ('娘', 'niáng', '10', '女', '左右', NULL, '娘 (形声。从女,良声。本义对妇女的泛称,多指少女) 同本义 见娘喜容媚,愿得结金兰。--古乐府《子夜歌》；组词：渔娘；厨娘；婆娘；老板娘；娘行(女性通称)；娘们(女人)；娘娘庙(俗谓送子女神之庙)；娘子关(一称苇泽关', '小学', '1'),
    ('娜', 'nà', '9', '女', '左右', NULL, '娜〈名〉 (形声。从女,那声。本义婀娜,美貌) --女子人名用字 娜,女字。--《集韵》 娜nà 1.见于人名。 娜nuó 1. 2."。', '小学', '1'),
    ('娩', 'miǎn', '10', '女', '左右', NULL, '娩 (形声。从女,免声。本义生孩子) 同本义。 娩以连卷兮。--《文选·张衡·思玄赋》。旧注引纂要齐人谓生子曰娩。”；组词：娩身(分娩,生小孩)；娩息(产育,蕃殖)；娩乳(妇人产子)；娩娠(分娩)；娩难(分娩', '小学', '1'),
    ('娱', 'yú', '10', '女', '左右', NULL, '娱 (形声。从女,吴声。本义快乐,欢娱) 同本义 娱,乐也。--《说文》。经传多以虞为之。 夏康娱以自纵。--《楚辞·离骚》 穷身极娱。--张衡《西京赋》 诸侯不娱；组词：娱娱(喜乐的样子)；娱快(欢快,愉快)；娱玩(玩乐)；娱放(娱恣,纵情欢乐)；娱笑(欢笑和悦)；娱嬉(戏乐)；娱戏(娱乐', '小学', '1'),
    ('娶', 'qǔ', '11', '女', '上下', NULL, '娶〈动〉 (会意兼形声。从女,从取,取亦声。本义男子结婚。把女子接过来成亲) 同本义 娶,取妇也。；组词：迎娶(娶妻) 带进,接收 娶qǔ指男子结婚~妻', '小学', '1'),
    ('婆', 'pó', '11', '女', '上下', NULL, '婆娑 (形声。从女,波声。本义舞貌) 舞 婆娑,舞也。--《尔雅》 盘旋;停留 婆娑虖术艺之场,休息虖篇籍之囿。--《汉书》 分散;扶疏 风鸿洞而不绝兮,优娆娆以婆娑', '小学', '1'),
    ('婉', 'wǎn', '11', '女', '左右', NULL, '婉 (形声。从女,宛声。本义柔顺) 同本义 婉,顺也。--《说文》 妇听而婉。--《左传·昭公二十六年》 恶而婉。--《左传·襄公二十六年》。服注婉,顺也。”；组词：婉软(柔和的样子)；婉艳(柔顺华美)；婉嫕(婉静', '小学', '1'),
    ('婚', 'hūn', '11', '女', '左右', NULL, '婚 (形声。从女,昏声。因为古时黄昏迎亲,故昏”亦兼表字义。本义妇家) 妻之家 婚,妇家也。礼,娶妇以昏时。妇人阴也,故曰婚。婚,妇家也。；组词：婚友(有婚姻关系的亲戚和朋友)；婚媾 婚hūn 1.男女结成夫妻结~', '小学', '1'),
    ('婴', 'yīng', '11', '女', '上下', NULL, '婴 (会意。从女,賏。賏”是颈项链。本义妇女颈饰,似现代的项链) 同本义 婴,颈饰也。--《说文》 喉下称婴。--《释名》 初生的女孩 见人方引婴儿欲投之江中；组词：男婴；女婴；妇婴；婴子(婴儿', '小学', '1'),
    ('婶', 'shěn', '11', '女', '左右', NULL, '婶 叔母。父亲弟弟的妻子 及抱入姆、婶房中。--吴自牧《育子》 又如婶母(婶娘;婶婶。都指叔父之妻);婶太太(对别人叔母的尊称) 称呼与父母同辈而年龄较小的已婚妇女 兄；组词：婶母(婶娘；婶婶', '小学', '1'),
    ('婿', 'xù', '12', '女', '左右', NULL, '婿 (形声。从女,胥声。或作壻”。本义古时女子称夫为婿) 同本义 壻,夫也。--《说文》 女子之夫为壻。--《尔雅》 壻执雁入。--《礼记·昏义》 壻御轮三周；组词：夫婿(丈夫) 成年男子的美称 桓温有 婿(壻)xù 1.女儿的丈夫女~', '小学', '1'),
    ('媒', 'méi', '12', '女', '左右', NULL, '媒 (形声。从女,某声。本义婚姻介绍人,媒人) 同本义 媒,谋也。谋合二姓。--《说文》 匪我愆期,子无良媒。--《诗·卫风·氓》 不待父母之命,媒妁之言,钻穴隙相窥,逾墙相从；组词：媒人婆迷了路儿,没的说了(做媒的迷了路,没有说合对象了)；媒人婆拾马粪,越发越晒(说媒人不怕碰钉子,面皮就像马粪那样,越', '小学', '1'),
    ('媚', 'mèi', '12', '女', '左右', NULL, '媚 (形声。从女,眉声。眉”也有示意作用,表示以目媚人。本义爱;喜爱) 同本义 媚,说也。；组词：媚子(所爱之人；爱子)；媚好(爱悦)；媚靥(女子两颊讨人喜欢的酒窝) 逢迎取悦 人服媚之如是', '小学', '1'),
    ('媳', 'xí', '13', '女', '左右', NULL, '媳 儿子的配偶 弟弟及晚辈亲属之妻 媳xí 1.子、弟的妻子,也称其它晚辈亲属的妻子儿~。表弟~。堂侄~。外孙~。 2. 1北方〈方〉称妻子猪八戒背~妇。 2通称已婚的年轻妇女', '小学', '1'),
    ('嫁', 'jià', '13', '女', '左右', NULL, '嫁 (形声。从女,家声。本义女子出嫁) 同本义(跟娶”相对) 嫁,女适人也。--《说文》 归妹。--《易·序卦》。虞注嫁,归也。” 子嫁反。--《仪礼·丧服》；组词：嫁杏(比喻婚期)；嫁子(嫁出的女儿；孪生的女儿)；嫁娶(嫁女与娶妇)；嫁殇(男子未满十九岁而死,死后女子才嫁之为妻) 往', '小学', '1'),
    ('嫂', 'sǎo', '12', '女', '左右', NULL, '嫂〈名〉 (形声。从女,叟声。本义兄之妻) 同本义 嫂,兄妻也。--《说文》 女子谓兄之妻为嫂。--《尔雅》 是嫂亦可谓之母乎?--《礼记太传》 兄弟嫂妹妻妾皆窃笑之；组词：表嫂；大嫂；嫂溺叔援(变通；权变', '小学', '1'),
    ('嫉', 'jí', '13', '女', '左右', NULL, '嫉 (形声。从女,疾声。本义忌妒才德地位等美好的人) 同本义。泛指忌妒 嫉,妒也。--《广雅》 各兴心而嫉妒。--《楚辞·离骚》 世溷浊而嫉贤兮,好蔽美而称恶。 众女嫉予之娥眉兮；组词：嫉诬(因嫉妒而诬告)；嫉病(忌妒指责)；嫉心(嫉妒之心)；嫉毁(嫉妒毁谤) 憎恨 荀卿嫉浊世之政', '小学', '1'),
    ('嫌', 'xián', '13', '女', '左右', NULL, '嫌 (形声。从女,兼声。本义疑惑,怀疑而有可能性) 同本义 嫌,一曰疑也。--《说文》 礼者,所以定亲疏,决嫌疑也。--《礼记·曲礼上》 使民无嫌；组词：嫌间(因彼此猜疑而产生恶感)；嫌微(犹嫌疑) 避忌 贵贱不嫌同号,美恶不嫌同辞', '小学', '1'),
    ('嫡', 'dí', '14', '女', '左右', NULL, '嫡 (形声。从女,啇(詤??)声。本义奴隶社会、封建社会中的正妻) 同本义 齐公族多宠,嫡庶并行。；组词：嫡庶不分(妻妾亲疏不分)；嫡出(正妻所生)；嫡室(正妻)；嫡礼相待(像正妻一般对待) 正妻生的长子称嫡子,省称嫡” 君家', '小学', '1'),
    ('嫩', 'nèn', '14', '女', '左右', NULL, '嫰 (形声。从女,敕声。本义物初生时的柔弱娇嫩状) 同本义 萝短未中揽,葛嫩不任牵。--萧衍《游钟山大爱敬寺》；组词：嫩萼；嫩蕊(含苞欲放的花)；嫩箭(兰花新抽的花茎)；嫩叶 指某些食物烹调时间短、容易咀嚼 柔弱,娇气 指事物尚处在开始或', '小学', '1'),
    ('嬉', 'xī', '15', '女', '左右', NULL, '嬉 (形声。从女,喜声。本义无拘束地游戏) 同本义 追渔父以同嬉。--《文选·张衡·归田赋》 业精于勤荒于嬉。--韩愈《进学解》；组词：嬉娱(嬉戏娱乐)；嬉弄(游戏；玩耍；戏弄；玩弄)；嬉宕(嬉戏游乐)；嬉春(游乐于春光之中) 开玩笑,作弄嘲笑 虽嬉笑怒骂', '小学', '1'),
    ('子', 'zǐ', '3', '子', NULL, NULL, '子 (象形。甲骨文字形,象小儿在襁褓中,有头、身、臂膀,两足象并起来的样子。子”是汉字的一个部首。本义婴儿)；组词：子衣(小儿的胎衣 子zǐ 1.儿,儿或女~女', '小学', '1'),
    ('孔', 'kǒng', '4', '子', '左右', NULL, '孔〈副〉 (象形。金文字形,象小儿食乳之形。婴儿吃奶容易过量,因以表示过甚之意。本义甚,很)；组词：孔亟(甚急)；孔多(很多)；孔明(很完备；很洁净；很鲜明)；孔疚(很痛苦)；孔虔(非常虔诚)；孔圣(很圣明) 孔 〈名〉', '小学', '1'),
    ('孕', 'yùn', '5', '子', '上下', NULL, '孕 (会意。甲骨文字形,外象妇女大腹之形,内象腹中怀子之形。本义怀胎) 同本义 孕裹子也。；组词：孕重(怀胎)；孕吐(妊娠初期呕吐)；孕乳(怀胎哺育) 孕育 拙辞或孕于巧义,庸事或萌于新意', '小学', '1'),
    ('字', 'zì', '6', '子', '上下', NULL, '字 (会意兼形声。从宀从子,子亦声。在屋内生孩子。本义生孩子) 同本义 字,乳也。--《说文》。 字,生也。--《广雅》 妇人疏字者子活,数乳者子死。--《论衡·气寿》 六畜遂字；组词：字乳(生育)；字育(生育、蕃育) 怀孕,体内怀着胎儿 女子贞不字,十年乃字', '小学', '1'),
    ('存', 'cún', '6', '子', NULL, NULL, '存 (形声。本义生存;存在) 同本义 存,存在也。--《尔雅》。注存即在。” 有天子存。--《公羊传·隐公三年》 虽存乎人者。--《孟子·告子上》 以其存心也；组词：存济(存活；活命)；存殁(活着的和死去的) 恤问,劳问 存,恤问也', '小学', '1'),
    ('孙', 'sūn', '6', '子', '左右', NULL, '孙 (会意。从子,从系,续也。金文,象用绳索捆绑小孩子,意为少年俘虏。本义儿子的儿子) 同本义 宱,子之子曰孙。；组词：祖孙；重孙(孙子的儿子)；孙少爷(旧时尊称别人的孙子)；孙囡(方言', '小学', '1'),
    ('孝', 'xiào', '7', '子', NULL, NULL, '孝 (形声。从老省,从子。本义尽心奉养和服从父母) 同本义 孝,善事父母者。--《说文》 孝利亲也。--《墨子经》 子爱利亲谓之孝。--《贾子道术》 慈惠爱亲为孝。协时肇享为孝', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('孟', 'mèng', '8', '子', '上下', NULL, '孟 (形声。从子,皿声。本义妾媵生的长子称孟”,正妻生的长子称伯”,后来统称长子) 同本义 孟,长也。；组词：孟兄；孟孙；孟仲叔季(兄弟姊妹的长幼顺序,顺次排行为大、二、三、四) 始,四季中每季的第一个月 孟mèng 1.旧时,兄', '小学', '1'),
    ('季', 'jì', '8', '子', '上下', NULL, '季 (会意。从子,从稚省。稚”亦兼表读音。本义即排行最后的) 同本义(与老”相对) 季,少称。；组词：季女(最小的女儿)；季父(父亲的幼弟)；季指(小指头)；季弟(最小的弟弟) 一年四季中,每季的最后一个月 季春之月', '小学', '1'),
    ('孤', 'gū', '8', '子', '左右', NULL, '孤〈名〉 (形声。从子,瓜声。本义幼年丧父,即孤儿) 同本义 孤,无父也。--《说文》 如孤子。--《礼记·深衣》。注三十以下无父称孤。” 司民协孤终；组词：孤驹(无母的小马)；孤遗(无父母的子女)；孤雏(失去母鸟的幼鸟)', '小学', '1'),
    ('学', 'xué', '8', '子', '上下', NULL, '学 (形声。本作壆”,象双手构木为屋形◇作声符,加子”为义符。子,孩子。小孩子是学习的主体。本义学习)；组词：学书(认真读书)；学学乖(经世面,学聪明)；学理论；学技术；好学；苦学；教学相长；学文(学习人文学科或社会 学(寃、斈)', '小学', '1'),
    ('孩', 'hái', '9', '子', '左右', NULL, '孩〈动〉 (形声。从子,亥声。本义小儿笑) 同本义。同咳” 咳,小儿笑也。--《说文》。古文咳从子。内则,孟子则作此字。 孤女藐焉始孩。--潘岳《寡妇赋》；组词：未孩(还不会笑) 当作婴儿看待 圣人在天下,歙歙为天下浑其心,百姓皆注其耳目,圣人皆孩之', '小学', '1'),
    ('孵', 'fū', '14', '子', '左右', NULL, '孵〈动〉 (形声。从卵,孚声。本义鸟类伏在卵上,使卵内的胚胎发育成雏鸟) 同本义 孵化 孵卵 孵育 并非每只蛋都能孵育出小鸡 孵 fū 1.鸟类伏在卵上', '小学', '1'),
    ('孽', 'niè', '19', '子', '上下', NULL, '孽 (形声。从子,薛声。从子,与子孙有关。本义庶出的,宗法制度下指家庭的旁支) 同本义 孽,庶子也。；组词：孽长子,孽子(庶子,非正妻所生之子)；孽出(庶出)；孽孙(庶出之孙)；孽庶(即孽子) 地位低贱的 恶；邪恶 孽(寊)n', '小学', '1'),
    ('宁', 'níng', '5', '宀', '上下', NULL, '宁 (本作寍”。从宀,从心,从皿。表示住在屋里有饭吃就安心了◇世假寧”为寍”,寧”行而寍”废。今用宁”字作寧”简化字。宁”,是贮”的本字。本义 安宁,平安)；组词：心神不宁；宁吉(安宁吉祥)；宁息(安宁平 宁(寧、甯)níng 1.安定,平安~静', '小学', '1'),
    ('它', 'tā', '5', '宀', '上下', NULL, '它〈名〉 (象形。小篆字形。象虫形。本义虫) 同本义◇作蛇” 它,虫也。从虫而长,象冤曲垂尾形,上古草居患它,故相问无它乎?”；组词：它(牠)tā 1.他,专指事物或牲口晒的衣服~已干了', '小学', '1'),
    ('宅', 'zhái', '6', '宀', '上下', NULL, '宅 (形声。从宀,乇声。本义住所;住处) 同本义 宅,所托居也。--小徐本《说文》 上以厚,下安宅。；组词：卜宅(卜择住处建都地或葬地)；宅司(宅子；宅院)；宅券(房契)；宅相(住宅风水之相)；宅神(住宅里的神鬼)；宅屋(住房)', '小学', '1'),
    ('宇', 'yǔ', '6', '宀', '上下', NULL, '宇〈名〉 (形声。从宀,于声。宀”表示房屋。本义屋檐) 同本义 宇,屋边也。--《说文》 宇,屋檐也。--《一切经音义》引《说文》 上栋下宇。--《易·系辞》 八月在宇；组词：宇堂(屋檐下的正房前)；宇达(屋檐和窗户)；宇溜(屋檐) 房屋 聿来胥宇', '小学', '1'),
    ('守', 'shǒu', '6', '宀', '上下', NULL, '守 (会意。从宀,从寸。宀表示房屋;寸是法度∠起来表示掌管法度。本义官吏的职责,职守) 同本义 守,官守也。从门,寺府之事也。', '小学', '1'),
    ('安', 'ān', '6', '宀', '上下', NULL, '安〈形〉 (会意。从女”在宀”下,表示无危险。本义安定;安全;安稳) 同本义 安,定也。--《尔雅》 共给之为安。--《庄子·天地》 好和不争曰安；组词：安睡；安寝；安抵(平安地抵达)；心神不安；坐立不安；安枕(安安稳稳) 1.平静,稳定平~', '小学', '1'),
    ('宋', 'sòng', '7', '宀', '上下', NULL, '宋 (会意。从宀,从木。表示房屋周围有树木。本义定居) 同本义 宋,居也。--《说文》。段玉裁注此义未见经传,名子者不以国,而鲁定公名宋,则必取其本义也。” 郑公子宋字子公', '小学', '1'),
    ('完', 'wán', '7', '宀', '上下', NULL, '完 (形声。从宀,元声。宀”与房屋有关。本义完备,完整) 同本义 完,全也。--《说文》 巢非不完也。--《荀子·劝学》 完全富足而趋赵。--《荀子·议兵》 完璧归赵；组词：完计(周密完善的计策)；完完(完整无缺的样子)；完充(完备充裕)；完锐(完备精良)；完块(完整的 完wán 1.齐全~整', '小学', '1'),
    ('宏', 'hóng', '7', '宀', '上下', NULL, '宏〈形〉 (形声。从宀,表示与家室房屋有关,厷声。本义屋子宽大而深) 同本义 宏,屋深响也。；组词：宏才(大才)；宏硕(大儒硕学', '小学', '1'),
    ('宗', 'zōng', '8', '宀', '上下', NULL, '宗 (会意。从宀示。示,神祇,宀,房屋。在室内对祖先进行祭祀。本义宗庙,祖庙) 同本义 宗,尊祖庙也。；组词：宗守(宗庙所在)；宗邑(宗庙所在的城邑)；宗稷(宗庙社稷)；宗仪(有关宗庙的典章礼仪)；宗彝(宗庙祭祀所用的酒器)；宗器', '小学', '1'),
    ('官', 'guān', '8', '宀', '上下', NULL, '官〈名〉 (会意。甲骨文字形,从宀”, 以冖覆众,则有治众的意思。本义官吏,官员) 同本义 官,吏事君也。', '小学', '1'),
    ('宙', 'zhòu', '8', '宀', '上下', NULL, '宙 (形声。从宀,由声。宀”,表示房屋。本义栋梁) 同本义 宙,舟舆所极覆也。--《说文》。按,舟舆上覆如屋极者,或曰覆也,舟舆所极也。 而燕雀佼之,以为不能与之争于宇宙之间；组词：宙始(远古)；宙合(囊括上下古今之道) 天空 功烛上宙, 宙zhòu古往今来,无限的时间有长而无本剽者~也(本剽本末', '小学', '1'),
    ('定', 'dìng', '8', '宀', '上下', NULL, '定 (会意。从宀,从正。正”亦兼表字音。本义安定;安稳) 同本义,与乱”或动”相对 定,安也。；组词：定迭(定叠', '小学', '1'),
    ('宛', 'wǎn', '8', '宀', '上下', NULL, '宛 (形声。从宀,夗声。象屋里的草弯曲自相覆盖。本义弯曲) 同本义 宛,屈草自覆也。--《说文》 宛宛黄龙。--《史记·司马相如传》 是以欲谈者宛舌而固声；组词：宛妙(事物屈曲美妙)；宛虹(弯曲的虹)；宛曲(辗转；曲折)；宛委(弯曲；曲折)；宛宛(盘旋屈曲的样子；山川道路蜿蜒曲折)', '小学', '1'),
    ('宜', 'yí', '8', '宀', '上下', NULL, '宜 (会意。从门之下一之上。甲骨文字形。象屋里俎上有肉的形状。本义合适;适宜) 同本义 宜,所安也。；组词：宜子(女子富有生育能力)；宜民(使民众安辑)；宜时(适时)；宜春(适宜于春天) 宜 煮熟可吃的肉 弋言加之,与子宜之', '小学', '1'),
    ('宝', 'bǎo', '8', '宀', '上下', NULL, '宝 (形声。甲骨文字形,象房子里有贝和玉,表示家里藏有珍宝,会意。在西周金文里,又加上一个声符缶”(古音与宝”同)。本义珍宝)；组词：珠宝；宝函(宝匣)；珍宝(珠玉宝石等)；宝肆(出售珍宝的店 宝 bǎo 1珍贵的东西粮食是个~,谁都离不了', '小学', '1'),
    ('实', 'shí', '8', '宀', '上下', NULL, '实 (会意。从宀,从贯。宀,房屋。贯,货物,以货物充于屋下。本义财物粮食充足,富有) 同本义 實,富也。；组词：殷实；实核(种子)；实谷(子粒饱满的谷类作物) 真实；诚实 实,诚也', '小学', '1'),
    ('宠', 'chǒng', '8', '宀', '上下', NULL, '宠 (形声。从宀,龙声。本义尊崇) 同本义 宠神其祖。--《国语·楚语》。注尊也。” 宠,尊居也。--《说文》 宠名皆弃。--《左传·襄公三十年》。谓族也。；组词：宠存(尊崇慰问)；宠重(尊崇重视)；崇厉(尊崇勉励) 宠爱 君以为忠,而甚宠之', '小学', '1'),
    ('审', 'shěn', '8', '宀', '上下', NULL, '审 (会意。从宀番。宀房屋。番,兽足。屋里有兽足印,能仔细分辨。简体字从宀申声。本义详究;考察)；组词：审时(详察时令)；审物(详察物情)；审形(详察实情)；审决(审察决定)；审机而行(详细、周密地进行分析研究,把握好时机再', '小学', '1'),
    ('客', 'kè', '9', '宀', '上下', NULL, '客〈动〉 (形声。从宀,表示与家室房屋有关,各声。本义寄居;旅居,住在异国他乡) 同本义 客,寄也。；组词：客边(暂寓别人家里)；客纲客纪(经常出门在外者的法度经验)；客寄(寄居客地人家) 以客礼相待 孟尝君客我', '小学', '1'),
    ('宣', 'xuān', '9', '宀', '上下', NULL, '宣 (形声。从宀,亘声。宀”与房屋有关。一说据甲骨文为云气舒卷自如之象。本义帝王的宫殿) 古代帝王的大室,古宫室名 宣,天子宣室也。', '小学', '1'),
    ('室', 'shì', '9', '宀', '上下', NULL, '室 (会意。从宀从至。人到屋中就停止了。本义内室) 同本义 室,实也。--《说文》。段注古者前堂后室。释名曰室,实也,人物实满其中也。” 上古穴居而野处,后世圣人易之以宫室', '小学', '1'),
    ('宦', 'huàn', '9', '宀', '上下', NULL, '宦 (会意。从宀,表示与家庭房屋有关。从臣。臣”本奴隶∠起来的意思是家室奴仆。本义做奴隶主或帝王的奴仆)；组词：宦女(服务于宫中的女奴) 学习官吏的事务 宦,仕也', '小学', '1'),
    ('宪', 'xiàn', '9', '宀', '上下', NULL, '宪 (会意。从心,从目,害省声。心、目并用。本义敏捷) 同本义 宪,敏也。--《说文》 博闻多能曰宪。--《周书·谥法》 喜乐的样子 天之方难,无然宪宪。--《诗·大雅》；组词：宪宪(欣欣', '小学', '1'),
    ('宫', 'gōng', '9', '宀', '上下', NULL, '宫 (象形。甲骨文字形,象房屋形。在穴居野处时代也就是洞窟。外围象洞门,里面的小框框象彼此连通的小窟,即人们居住的地方。本义古代对房屋、居室的通称(秦', '小学', '1'),
    ('宰', 'zǎi', '10', '宀', '上下', NULL, '宰 (会意。从宀,从辛。宀”表屋子。辛,奴隶,罪人。本义充当家奴的罪人) 同本义 宰,罪人在屋下执事者。', '小学', '1'),
    ('害', 'hài', '10', '宀', '上下', NULL, '害〈动〉 (会意。从宀,从口,丰声。从宀”、从口”,意思是言从家起,而言”又往往是桅的根源。本义伤害,损害)；组词：害心(害人害物的心思', '小学', '1'),
    ('宴', 'yàn', '10', '宀', '上下', NULL, '宴 (形声。从宀声。宀”表示房屋,妟”是安”意思,也有表意作用。本义请人吃饭喝酒,聚会在一起喝酒吃饭 )；组词：宴犒(设宴犒赏)；宴赏(设宴犒赏)；宴饯(设宴招待)；宴好(泛指宴饮聚会)；宴衍 宴yàn 1.用酒饭招待客人~客', '小学', '1'),
    ('宵', 'xiāo', '10', '宀', '上下', NULL, '宵 (形声。从宀,肖声。从门”表夜间昏暗。本义夜晚) 同本义 宵,夜也。--《说文》 宵中星。--《书·尧典》 禁宵行者。--《周礼·司寤氏》 甘暝太宵之长。--《淮南子·精神》；组词：宵烟(指夜晚的烟雾)；宵宿(住宿；住宿的地方)；宵夕(晚上)；宵中(夜里,晚上)；宵分(半夜,深夜)；宵行(夜间出行)', '小学', '1'),
    ('家', 'jiā', '10', '宀', '上下', NULL, '家 (会意。甲骨文字形,上面是宀”,表示与室家有关,下面是豕”,即猪。古代生产力低下,人们多在屋子里养猪,所以房子里有猪就成了人家的标志。本义屋内,住所)', '小学', '1'),
    ('容', 'róng', '10', '宀', '上下', NULL, '容 (会意兼形声。小徐本从宀,谷。”大徐本看作会意。宀”是房屋,谷”是空虚的山洼,都有盛受的意思。本义容纳)；组词：容隐(包庇,隐瞒)；容足(仅容立足)；容接(容纳接待)；容盛(覆载,容纳)；容民(容纳民众)；容民畜众(容纳畜养民众)', '小学', '1'),
    ('宽', 'kuān', '10', '宀', '上下', NULL, '宽 (形声。从宀,表示与房屋有关,苋声。本义房屋宽敞) 同本义 宽,屋宽大也。--《说文》 府寺宽敞。--《后汉书·刘般传》；组词：宽厂(宽敞)；宽空(宽畅,不阻塞)；宽转(宽敞有余地) 广阔；面积大', '小学', '1'),
    ('宾', 'bīn', '10', '宀', '上下', NULL, '宾 (形声。从贝,冥(榠溂?? )声。甲骨文字形,会意。上面象屋形,下面是人”和止”。表示客人来到屋下,即宾客到门。金文将止”改为贝”,小篆从之', '小学', '1'),
    ('宿', 'xiǔ', '11', '宀', '上下', NULL, '宿 (形声。据甲骨文,象人睡在室内席子上。本义住宿;过夜) 同本义 宿,止也。--《说文》 出宿于干。--《诗·邶风·泉水》 言就尔宿。--《诗·小雅·我行其野》 戒及宿之日；组词：宿歇(住宿,睡觉)；宿坛(住宿)；宿泊(住宿；安歇)；宿夜然诺(存留过夜的诺言)；宿sù 1.住,过夜,夜晚睡觉住~', '小学', '1'),
    ('寂', 'jì', '11', '宀', '上下', NULL, '寂 (形声。从宀,叔声。本义静悄悄,没有声音) 同本义 寂,无人声。--《说文》 寂寥宇宙。--《四子讲德论》 寂兮寥兮,独立不改。--《老子》 寂然不动；组词：寂寂悄悄(悄悄地,不弄出声音地)；寂密(隐密)；寂天寞地(悄无声息) 安详闲静,心志淡泊 旷然无忧患,寂然无思虑', '小学', '1'),
    ('寄', 'jì', '11', '宀', '上下', NULL, '寄 (形声。从宀,表示与家室房屋有关,奇声。本义寄居) 同本义 寄,托也。--《说文》 寄公者,何失地之君也。--《仪礼·丧服》传 可以寄百里之命。--《论语》；组词：寄籍(寄居外地而附以户籍的叫寄籍)；寄庄(在外地买地设庄,收租) 委托,托付 令可以寄政', '小学', '1'),
    ('密', 'mì', '11', '宀', '上下', NULL, '密 (形声。从山,宓声。本义形状象堂屋的山) 同本义(意思是山多) 密,山如堂者。--《说文》 松柏之鼠,不知堂密之有美枞。--《尸子》 隐蔽的地方 不窥密。--《礼记·少仪》', '小学', '1'),
    ('寇', 'kòu', '11', '宀', '上下', NULL, '寇 (会意。从宀,表示与室家房屋有关,从元(人),从攴,表示持械击打。意思是手持器械的人,侵犯到房子里来打人。本义入侵;侵犯)；组词：寇戎(来犯的敌军)；寇虐(侵掠残害之行)寇钞(攻劫掠夺)；寇剽(抢劫)；寇钞(亦 寇kòu 1.盗匪,侵略者防~', '小学', '1'),
    ('富', 'fù', '12', '宀', '上下', NULL, '富〈形〉 (形声。从宀,表示与房屋宫室有关。畐声。声符亦兼表字义。畐”本像人腹满之形(参福”字条),合宀”为之,以示富人安居宫室,丰于饮馔之义。本义财产多,富裕)', '小学', '1'),
    ('寒', 'hán', '12', '宀', NULL, NULL, '寒〈形〉 (会意。金文外面是宀”,即房屋;中间是人”;人的左右两边是四个草”,表示很多;下面两横表示冰”‘冷是一种感觉,人们虽能感觉到,但是却看不见', '小学', '1'),
    ('寓', 'yù', '12', '宀', '上下', NULL, '寓 (形声。从宀,禺声。宀,表示房屋。本义寄居,寄住) 同本义 寓,寄也。--《说文》 国无寄寓。--《国琼·周语》 诸侯不臣寓公。--《礼记·郊特牲》 无寓人于我室；组词：寄寓(寄居)；寓士(寄居之人)；寓泊(寄住)；寓食(寄食', '小学', '1'),
    ('寝', 'qǐn', '13', '宀', '上下', NULL, '寝 (形声。从宀,侵声。本义睡觉) 同本义 寢,卧也。--《说文》 寝毋伏。--《礼记·曲礼上》 宰于昼寝。--《论语·公冶长》 寡人夜者寝而不寐；组词：寝不成寐(睡不着', '小学', '1'),
    ('寞', 'mò', '13', '宀', '上下', NULL, '寞 寂静;无声响 巡陆夷之曲衍兮,幽空虚以寂寞。--《楚辞》 冷落,孤单 寞mò寂静,冷静寂~。', '小学', '1'),
    ('察', 'chá', '14', '宀', '上下', NULL, '察 (形声。从宀,祭声。本义观察;仔细看) 同本义 察,复审也。--《说文》 览察草木。--《楚辞·离骚》 纤微皆审谓之察。--贾谊《道术》 察其所以然；组词：观察(仔细察看客观事物或现象)；觉察(发觉,看出来) 明察,知晓 小大之狱,虽不能察,必以情', '小学', '1'),
    ('寡', 'guǎ', '14', '宀', '上下', NULL, '寡〈形〉 少;缺少 寡,少也。--《说文》 曹操比于袁绍,则名微而众寡。--《三国志·诸葛亮传》 不患寡而患不均。--《论语·季氏》；组词：寡尤(少犯错误)；寡功(功效少)；寡见(见识少)；寡交(与人交往少) 孤独；孤单 寡,独也', '小学', '1'),
    ('寥', 'liáo', '14', '宀', '上下', NULL, '寥〈动〉 假借为赖”。凭依;聊赖 上下不相宁,吏民不相寥。--《淮南子·兵略》。按,与国策民无所聊。 寥 〈形〉 (本作廫。形声。从宀,本义空虚;寂静)；组词：寥朗(空虚明朗)；寥天(道教的所谓虚无之境', '小学', '1'),
    ('寨', 'zhai', '14', '宀', NULL, NULL, '寨 (形声。从木,赛省声。本义防卫所用的木栅) 同本义 敌军已近寨。--清·徐珂《清稗类钞·战事类》 寨中人踡伏。 借寨墙为蔽。 多指四面环围的驻军处,营垒 时巴山陈定亦拥兵立寨；组词：寨落(有栅栏或围墙的村落)；寨垛(寨墙上的垛口)；寨屋(营房) 寨子,村庄 寨(砦)zhài 1.防卫用的栅栏鹿~(军用', '小学', '1'),
    ('寸', 'cùn', '3', '寸', NULL, NULL, '寸 (指事。小篆字形,从又,从一。又”象手形,一”指下手腕一寸之处。寸”是汉字部首之一,从寸”的字往往与手”有关。本义中医切脉,称距离手腕一寸长的部位为 寸口”,简称寸”) 寸；组词：寸田(三丹田)；寸关尺(中医指寸口、关上、尺中的简称) 长度单位, 1/10尺为一寸,古代计量长度单位的标准不同,寸的具', '小学', '1'),
    ('对', 'duì', '5', '寸', '左右', NULL, '对 (会意。从口,从乹”,即,古丛”字,象草木丛生。),从寸。寸,法度也『文帝以为责对而伪,言多非诚,故去其口,以从土。本义应答)；组词：无言以对；对当(', '小学', '1'),
    ('寺', 'sì', '6', '寸', '上下', NULL, '寺 (形声。小篆字形,从寸,之声。寸,与法度有关。本义古代官署的名称。秦以官员任职之所,通称为寺。如大理寺(职掌审核刑狱案件))；组词：寺正(大理寺正卿的略称)；寺舍(官舍', '小学', '1'),
    ('寻', 'xún', '6', '寸', '上下', NULL, '寻 (会意。从工口,从又(彐)寸。本义八尺为寻) 中国古代的一种长度单位,八尺为寻 尋,绎理也。', '小学', '1'),
    ('导', 'dǎo', '6', '寸', '上下', NULL, '导 (形声。从寸,道声。寸”与手”意思相近。本义以手牵引,引导) 同本义 导,引也。--《说文》 其治宜导引按辤。--《素问》。注谓摇筋骨动支节。” 导官令本；组词：导子(官员出行时在前面开路的仪仗队)；导从(古代官员出行时,担任前导和后从的人)；导仗(前导的仪仗) 教导', '小学', '1'),
    ('寿', 'shòu', '7', '寸', NULL, NULL, '寿 (形声。从老省,畴声(依《说文》),从老省,即上面象老”的上半部。本义长寿) 同本义 寿,久也。', '小学', '1'),
    ('封', 'fēng', '9', '寸', '左右', NULL, '封〈名〉 (会意。金文字形,左边象土上长着丰茂的树木形,右边是一只手(又,后来写作寸”),表示聚土培植。《说文》封,爵诸侯之土也。从之从土从寸。”郭沫若曰古之畿封 实以树为之也', '小学', '1'),
    ('射', 'shè', '10', '寸', '左右', NULL, '射 (本作射”。会意。金文字形,象箭在弦上,手(寸)在发放。小篆把弓矢形讹变成身”字,误。本义用弓发箭使中远处目标)；组词：射鹄(射箭的靶子)；射日(古代神话', '小学', '1'),
    ('将', 'jiāng', '9', '寸', '左右', NULL, '将 (形声。从寸,酱省声。从寸”,表示与手有关。本义将领,带兵的人) 扶持,扶助 将,扶也。；组词：将美(助成好事)；将引(扶助收纳)；将扶(扶持；搀扶)；将助(扶助；支持) 奉行,秉承 使臣将王命,岂不如贼焉?--元结', '小学', '1'),
    ('尉', 'wèi', '11', '寸', '左右', NULL, '尉 wei (会意。尉”是熨”的古字。表示用火熨烫缯布使之平展。本义烫平衣服的火斗,熨斗)；组词：尉斗(藉热力烫平衣服的火斗) 中国古代官名 八月官尉', '小学', '1'),
    ('尊', 'zūn', '12', '寸', '上下', NULL, '尊 (会意。甲骨文字形,象双手捧着尊,从酉,从収。小篆从酋,从収。或作寸。本义酒器) 同本义 尊,酒器也。；组词：携尊(端起酒器)；尊觯(尊谭', '小学', '1'),
    ('小', 'xiǎo', '3', '小', NULL, NULL, '小 (象形。据甲骨文,象沙粒形。小篆析为会意。从八,从|。本义细;微。与大”相对) 同本义 小,物之微也。；组词：小鹿儿(喻指因紧张而剧烈跳动的心脏)；小录(新科进士的题名录)；小 小xiǎo 1.跟"大"相对 1面积、范围小的~山', '小学', '1'),
    ('少', 'shǎo', '4', '小', '上下', NULL, '少〈形〉 (会意。小篆从小。本义不多) 同本义 少,不多也。--《说文》 少,微也。--《太玄·玄衡》 夫少者,多之所贵也。--《易·略例》 宾少进。--《仪礼·乡射礼》 险以远；组词：少一时(少时,过一会儿)；少可(少,至少；稍好,稍愈)；少冗(较忙)；少甚么(少甚末,少是末,少甚', '小学', '1'),
    ('尔', 'ěr', '5', '小', '上下', NULL, '尔 (形声。本义窗格花纹) 同本义 后引作薾。华盛的样子 彼尔维何?维常之华。--《诗·小雅》。毛传尔,华盛貌。”；组词：丽尔(华丽的样子) 近', '小学', '1'),
    ('尖', 'jiān', '6', '小', '上下', NULL, '尖 (会意。从小,从大。一头小一头大为尖。本义物体的末端细削而锐利) 同本义 尖,锐也。--《广韵》 按,尖”是后起的会意字。；组词：尖山(尖而高的山)；尖屁股(借指坐不安稳)；尖担担柴两头脱(比喻两头落空,什么也没捞着)；尖顶木驴(尖头木驴', '小学', '1'),
    ('尘', 'chén', '6', '小', '上下', NULL, '尘 (会意。《说文》从三鹿”,从土”,表示鹿群行扬起尘土的意思。楷书简去重迭的部分,只保留一个鹿”。现行简化字尘”,也是一个从小”从土”的会意字。本义 尘土)；组词：浮尘；降尘；灰尘(尘土)；一尘不染；尘封(盖满灰尘)；尘涓(尘埃与一滴水', '小学', '1'),
    ('尚', 'shàng', '8', '小', '半包围', NULL, '尚〈副〉 (会意。从八,向声。本义尚且) 同本义 尚,曾也。--《说文》 尚无为。--《诗·王风·免爰》 又 尚无造。 尚求其雌。--《诗·小雅·小弁》 亦尚一人之庆；组词：尚有不少；尚来得及；尚未娶亲；尚待研究；尚兀自(还；尚且)；尚尔(尚且这样)；尚自(尚且)；尚然(尚且)；尚犹(犹,还)', '小学', '1'),
    ('尝', 'cháng', '9', '小', '上下', NULL, '尝 (形声。从旨,尚声。旨”,滋味美。本义辨别滋味,品尝) 同本义 天子乃以雏尝黍。--《礼记·月令》 臣先尝之。--《礼记·曲礼》 不敢尝。--《论语》 百鬼迪尝；组词：尝酒；尝食(试辨食物的味道)；尝酎(祭祀的时候,尝一尝新酒的滋味) 尝试 尝,试也', '小学', '1'),
    ('尤', 'yóu', '4', '尢', NULL, NULL, '尤 (形声,小篆字形,从乙,又声。乙象植物屈曲生长的样子,受到阻碍,则显示出它的优异。本义最优异)；组词：尤功(功绩最卓著', '小学', '1'),
    ('就', 'jiù', '12', '尢', '左右', NULL, '就 (会意。京尤会意。京”意为高,尤”意为特别。本义到高处去住) 同本义 就,就高也。从京从尤。尤,异于凡也。', '小学', '1'),
    ('尸', 'shī', '3', '尸', NULL, NULL, '尸〈名〉 (象形。小篆字形,屍像卧着的人形。本义祭祀时代表死者受祭的人) 同本义 尸,神像也。象卧之形。', '小学', '1'),
    ('尺', 'chǐ', '4', '尸', NULL, NULL, '尺 chi (指事。小篆,从尸,从乙。尸”象人卧的形象。乙”是个标识,周制寸、咫、尺、仞、寻、常诸度,皆以人之体为法。本义十寸)', '小学', '1'),
    ('尼', 'ní', '5', '尸', NULL, NULL, '尼〈形〉 (会意。从尸,匕声。甲骨文字形象两个人亲昵的样子。本义亲近,亲昵) 同本义◇作昵” 尼,从后近之也。；组词：僧尼(和尚和尼姑)；尼寺(尼姑所住的寺院)；尼房(尼姑所居处)；尼坛(尼姑 尼ní梵语"比丘尼"的简称', '小学', '1'),
    ('尽', 'jìn', '6', '尸', '半包围', NULL, '尽〈副〉 (尽为儘”和眒”的简化字) 尽量,尽可能 意思同最”,用在方位词的前面 老是;总 尽 〈动〉 表示以某个范围为界限,不得超过 让先 任凭,纵使 惟有落红不禁', '小学', '1'),
    ('尾', 'wěi', '7', '尸', NULL, NULL, '尾 (会意。从倒毛在尸后。尸,指人。象人长有尾巴。本义人或动物的尾巴) 同本义 尾,微也。；组词：虎尾；牛尾；尾大(比喻臣下势力强大)；尾君子(指猴子) 末端,末尾 渤海之尾', '小学', '1'),
    ('尿', 'niào', '7', '尸', NULL, NULL, '尿〈名〉 (会意。从尸,从水。尸代表人体。本义小便) 同本义 尿,人小便也。--《说文》。古书多假溺为之。；组词：糠尿病；尿鳖(尿壶', '小学', '1'),
    ('局', 'jú', '7', '尸', '半包围', NULL, '局 (会意。从口,从尺。尺”示规矩法度。口易出错,故以尺相拘束。本义局促) 同本义 局,促也。；组词：局守(谨守)；局定(限制,固定)；局囿(局限,限制)；局滞(局限停滞)；局蹐(局限,局束)；局脊(拘泥,拘束)；局数(局', '小学', '1'),
    ('屁', 'pì', '7', '尸', NULL, NULL, '屁〈名〉 肠道产生但从肛门突然排出的臭气 屁股,臀部 常用来骂人或指斥诗文、言语的荒谬 比喻没用的、微不足道的事物 屁pì从肛门排出来的臭气。', '小学', '1'),
    ('层', 'céng', '7', '尸', NULL, NULL, '层 (形声。从尸,尸者象屋形,从屋省。本义楼房) 同本义 层,重屋也。--《说文》 珠殿连云,金层辉景。--刘孝绰《栖隐寺碑》；组词：层楹(高楼大厦) 构成整个事物的一个层次 层 重叠 高堂邃宇,槛层轩些', '小学', '1'),
    ('居', 'jū', '8', '尸', NULL, NULL, '居 (象形。金文字形,是踞”的本字,象人曲胫蹲踞形。本义蹲着) 同本义◇作踞” 居,蹲也。从尸,古者居从古,俗居从足。', '小学', '1'),
    ('屈', 'qū', '8', '尸', NULL, NULL, '屈〈动〉 (形声。从尸,出声。尸,古文字中是假卧着的人形。本义弯曲) 同本义 屈,拗曲。--《广韵》 凡曲而不伸者皆曰屈。--《正字通》 尺蠖之屈,以求信也；组词：屈指询算(迷信指用手指占算)；屈律(弯曲的样子)；屈卮(有弯曲把手的酒杯)；屈申(屈伸', '小学', '1'),
    ('屉', 'tì', '8', '尸', NULL, NULL, '屉〈名〉 鞍屉,马鞍垫子 屉,鞍屉也。--《字汇》 抽屉 暂设装奁,还抽镜屉。--北周·庾信《镜赋》 笼屉 如刚出屉的包子好吃 窗棂;窗格子 那窗上的纸,隔着屉子', '小学', '1'),
    ('届', 'jiè', '8', '尸', NULL, NULL, '届 (形声。从尸,剆声。本义人行路不便) 同本义 届,行不便也。--《说文》 届 极限;穷极 至天之届,于河之沂。--晋·陆云诗 靡有夷届。--《诗·大雅·瞻卬》 君子如届；组词：届候(届时)；届止(停留,止息)；届路(登程,上路) 届满,结束 (如一段时间) 距悔罪乞降之始末届十年', '小学', '1'),
    ('屋', 'wū', '9', '尸', NULL, NULL, '屋 (屋的本义是幄,后来屋”指房屋,另造幄”字。会意。从尸,从至。尸,与房屋有关,至”表示来到。人来到这里居住之意。本义帐幕。幄”的本字)；组词：屋幕(帐幕)；屋漏(古代室内西北隅施设小帐,安插神主,为人所不见的地方) 古代半地穴式住室建筑的顶部覆盖 屋wū 1.房', '小学', '1'),
    ('屏', 'píng', '9', '尸', NULL, NULL, '屏 退避;隐退 侯生乃屏人间语。--《史记·魏公子列传》 又如屏居(辞官隐居,不问世事);屏语(避开他人,私下交谈);屏伏(隐退,避匿);屏移(退隐) 隐藏 尔不许我；组词：屏居(辞官隐居,不问世事)；屏语(避开他人,私下交谈)；屏伏(隐退,避匿)；屏移(退隐) 隐藏 尔不许我,我乃屏璧与圭', '小学', '1'),
    ('屑', 'xiè', '10', '尸', NULL, NULL, '屑 (形声。从尸,肖声。本义碎末) 同本义。 时造船,木屑及竹头悉令举掌之。--《晋书·陶侃传》；组词：米屑；屑涕(屑泣', '小学', '1'),
    ('展', 'zhǎn', '10', '尸', NULL, NULL, '展 (形声。小篆字形假卧的人形。从尸,与人体动作有关。本义转动) 同本义 展,转也。--《说文》 展,转,反侧也。--《广雅》 展转伏枕。--《韩诗泽陂》 忧心展转；组词：展动(翻动)；展轮(转轮', '小学', '1'),
    ('属', 'shǔ', '12', '尸', NULL, NULL, '属 shu (形声。从尾,蜀声。尾”与身体相连。1本义连接。2类,族) 种类。亦特指牲类 忠之属也,可以一战。；组词：金属；属禽(分别飞禽的种类) 亲属 是疾易传染,遘者虽戚属,不敢同卧起', '小学', '1'),
    ('屠', 'tú', '11', '尸', NULL, NULL, '屠〈动〉 (形声。从尸,者声。尸”,祭祀时代表死者受祭的活人,与人有关。本义宰杀牲畜) 同本义 屠,刳也。；组词：屠沽(杀猪卖酒)；屠狗(杀狗；称操贱业的人)；屠杀(屠宰杀戮)；屠肆(肉铺,宰杀牲畜的地方)；屠工(屠子,屠夫', '小学', '1'),
    ('屡', 'lǚ', '12', '尸', NULL, NULL, '屡(屢)lǚ多次~次。~见不鲜。~战~胜。~禁不止。', '小学', '1'),
    ('履', 'lǚ', '15', '尸', NULL, NULL, '履〈动〉 (会意。小篆字,从尸,即人;从彳,表示与行走有关。履在战国以前一般只作动词用。一般用屦”称鞋子。用鞋”是唐以后的事了。本义践踏)；组词：履危(蹈践高危之处)；履亩(勘查田亩)；履虎尾(踩踏虎尾)；履迹(踏着前人的足迹)；履霜(踩踏霜地', '小学', '1'),
    ('屯', 'tún', '4', '屮', NULL, NULL, '屯〈动〉 (会意。从屮贯一。屮,草。一,土地。象草木初生的艰难。1艰难。2引申义聚集) 聚集 屯,聚也。；组词：屯聚(会合,聚集)；屯屯(聚集)；屯合(聚集)；屯行(集中行进)；屯萃(聚集)；屯结(聚集；集结)；屯塞(聚拢堵塞)；屯', '小学', '1'),
    ('山', 'shān', '3', '山', '半包围', NULL, '山〈名〉 (象形。甲骨文和金文字形,象山峰并立的形状。山”是汉字的一个部首。本义地面上由土石构成的隆起部分)；组词：山霭(山上的云气)；山灵( 山shān 1.地面上高度大、坡度陡的隆起地貌高~', '小学', '1'),
    ('屹', 'yì', '6', '山', '左右', NULL, '屹 (形声。从山,乞声。本义山势直立高耸的样子) 同本义◇泛指耸立的 屹山峙以迂郁。(迂郁盘曲的样子。)--王延寿《鲁灵光殿赋》；组词：屹仡(挺拔雄劲的样子)；屹峙(耸立) 坚定不移的 屹yì山峰高耸', '小学', '1'),
    ('屿', 'yǔ', '6', '山', '左右', NULL, '屿 (形声。从山,与声。本义小岛) 同本义 为屿,为嵁,为岩。--唐·柳宗元《至小丘西小石潭记》 平地小山 屿,平地小山也。', '小学', '1'),
    ('岁', 'suì', '6', '山', '上下', NULL, '岁 (形声。小篆字形。从步,戌声。步”有经历的意思。古音岁、戌”迭韵。本义岁星。即木星)；组词：岁君(太岁', '小学', '1'),
    ('岂', 'qǐ', '6', '山', '上下', NULL, '岂 同恺”。安乐 王在在镐,岂乐饮酒。--《诗·小雅·鱼藻》 既见君子,孔燕岂弟。--《诗·小雅·蓼萧》 岂 (形声。从壴省,微省声。壴,陈列乐器；组词：岂奈(何奈,无奈)；岂不尔思(怎能不思念你)；岂有他哉(表示没有其他原因) 相当 岂(豰)qǐ 1.助词', '小学', '1'),
    ('岔', 'chà', '7', '山', '上下', NULL, '岔 (会意。从山,从分。本义山脉分岐的地方) 山脉或道路分岐的地方 在活动过程出的麻烦事 乱子,事故 岔 错开 转移主题 在他人谈话中插话 岔 chà 1山或道路等分岐的地方~流', '小学', '1'),
    ('岖', 'qū', '7', '山', '左右', NULL, '岖 (形声。从山,区声。崎岖,地面高低不平的样子) 道路险阻不平 形容山势峻险 岖(嶇)qū', '小学', '1'),
    ('岗', 'gǎng', '7', '山', '上下', NULL, '岗 同岡”。山脊,山岭 振衣千仞岗,濯足万里流。--晋·左思《咏史》之五 岗 (形声。从山,冈声。本义岗位,哨位) 同 本 义 土石坡儿 岗(崗)gǎng 1.守卫的位置站~', '小学', '1'),
    ('岛', 'dǎo', '7', '山', '半包围', NULL, '岛 (形声。从山,鸟声。本义江、湖、海洋中被水所包围而比大陆要小的一片陆地) 同本义 字省作岛” 入海居岛中。；组词：岛峙(似海岛般耸峙)；岛夷(古指中国东部近海一带及海岛上的居民；南北朝时南北双方封建统治者各以正统自居,互相诋毁,北朝称', '小学', '1'),
    ('岩', 'yán', '8', '山', '上下', NULL, '岩 (形声。从山,严声。岩”为会意字。从山,从石。本义高峻的山崖) 同本义 嵌岩窦穴。--宋·陆游《过小孤山大孤山》 高岩峭壁。--宋·沈括《梦溪笔谈》 植土龛岩。；组词：岩电(山崖间的闪电)；岩阿(山崖旁边凹下的地方)；岩徼(山崖边远的地方)；岩下(山崖之下)；岩饰(岩壁上的雕饰) 山峰', '小学', '1'),
    ('岭', 'lǐng', '8', '山', '左右', NULL, '岭 (形声。从山,领声。本义山道;山坡) 同本义 岭,山道也。--《说文新附》 日末涧增波,云生岭逾叠。--南朝 宋·谢灵运《登上戍石鼓山》 顶上有路可通行的山；组词：翻山越岭；岭隘(山岭上险要的隘口)；岭北(山峰北面；五岭之北) 相连的山,山脉 横看成岭侧成峰,远近高低各不同', '小学', '1'),
    ('岳', 'yuè', '8', '山', '上下', NULL, '岳 (会意。从山,从丘。古文字形,象两座高大的山峰形,表示高山大岭。? 特指名山五岳”或四岳” ? 崧高维岳,骏极于天。；组词：岳宗(五岳之中的嵩山)；岳帝(东岳泰山之神、东岳大帝的简称)；岳华(西岳华山)；岳庙(五岳之神的庙宇', '小学', '1'),
    ('岸', 'àn', '8', '山', '上下', NULL, '岸〈名〉 (形声。从山,从厂,干声。厂(山崖),意思为水边高起之地。本义河岸) 同本义 淇则有岸。；组词：沿岸；起岸(把货物从船上搬运到岸上) 比喻高位 诞先登于岸', '小学', '1'),
    ('峡', 'xiá', '9', '山', '左右', NULL, '峡 (形声。从山,夹声。本义两山夹水处) 同本义 仿洋于山峡之旁。--《淮南子·原道》。注两山之间为峡。” 峡里谁知有人事,世中遥望空云山。--王维《桃源行》 仍下峡路；组词：峡口(峡谷之口)；峡路(峡谷中的道路或航道)', '小学', '1'),
    ('峦', 'luán', '9', '山', '上下', NULL, '峦 (形声。从山,羉声。本义小而尖的山) 同本义 峦,山小而锐者。--《说文》 登峦而远望兮。--《楚辞·自悲》。注小山也。” 陟玉峦兮逍遥。--《楚辞·守志》。注山脊曰峦。玉峦；组词：山峦(连绵的山)；峦壑(峰峦和山谷)；峦峤(峭拔的山峰) 泛指山 谕以封峦', '小学', '1'),
    ('峭', 'qiào', '10', '山', '左右', NULL, '峭 (形声。从山,肖声。《说文》从阜。本义陡直) 同本义 峭,陵也。从阜,肖声。斗直曰峭。；组词：峭拔(特立高耸)；峭岸(陡岸)；峭谷(险峻的山谷)；峭坂(高陡的山坡)；峭卓(高峻陡直)；峭岫(陡峭的峰峦)；峭削(陡峭', '小学', '1'),
    ('峰', 'fēng', '10', '山', '左右', NULL, '峰 (形声。从山,峯声。本义山顶) 同本义 峯,山聑也。--《说文新附》 夹岸高山...争高直指,千百成峰。--吴均《与朱元思书》；组词：山峰(山的突出的尖顶)；高峰；孤峰；峰岫,峰朵,峰头；峰腹(山峰中部) 最高点；顶点 拔地而起的高山 突起 峰(峯) f', '小学', '1'),
    ('峻', 'jùn', '10', '山', '左右', NULL, '峻 (形声。从山,雋声。本义高而陡峭) 同本义 山峻高而蔽日兮。--《楚辞·屈原·涉江》 山道峻隘。--《北齐书·高昂传》 是犹上高陵之颠堕峻溪之下而求生；组词：峻危(高耸险峻)；峻朵(高峻的山峰)；峻岭(崇高的山岭)；峻绝(极为陡峭) 严酷,严厉 乃峻责租调', '小学', '1'),
    ('崇', 'chóng', '11', '山', '上下', NULL, '崇 (形声。从山,宗声。本义山大而高) 同本义 崇,嵬高也。--《说文》。按,字亦作嵩、作崧。 融降于崇山。--《国语·周语》。注崇,崇高山也。夏居阳城,崇高所近。”；组词：崇亘(高峻绵延)；崇崖(高峻的山崖)；崇阿(高大的山丘)；崇山(高山)；崇崇(高耸的样子) 高；高大 崇,高也', '小学', '1'),
    ('崎', 'qí', '11', '山', '左右', NULL, '崎〈形〉 (形声。从山,奇声。本义崎岖,地面高低不平的样子) 同本义 崎岖,倾侧也。--《广雅》；组词：崎崟(山峰高低不平的地方)；崎岭(形容山路险阻不平) 险峻 崎岖 崎岖而经丘', '小学', '1'),
    ('崔', 'cuī', '11', '山', '上下', NULL, '崔 (形声。从山,隹声。本义高大) 同本义 崔,大高也。--《说文》 南山崔崔。--《诗·齐风·南山》 大山崔,百卉殖。--《乐府诗集》；组词：崔巍(高峻雄伟)；崔崔(高大的样子) 蹉跎 崔 春秋时齐国邑名,在今山东省章丘县西北 成请老于崔,崔子许之', '小学', '1'),
    ('崖', 'yá', '11', '山', '上下', NULL, '崖 (形声。从山,厓声。本义岸;水边) 同本义 崖,高边也。--《说文》 崖,岸。高边也。...此云高边,崖则水之边而峭高者也。--《说文句读》 渊生珠而崖不枯', '小学', '1'),
    ('崩', 'bēng', '11', '山', '上下', NULL, '崩 (形声。从山,朋声。本义山倒塌) 同本义 梁山崩。--《左传·成公五年》 又如山崩地裂 崩裂;倒塌 中间力拉崩倒之声,火爆声,呼呼风声,百千齐作；组词：山崩地裂 崩裂；倒塌 中间力拉崩倒之声,火爆声,呼呼风声,百千齐作', '小学', '1'),
    ('崭', 'zhǎn', '11', '山', '上下', NULL, '崭 (形声。从山,斩声。双音词崭岩”。本义山高而险峻的样子) 同本义 崭岩嵾嵯。--《史记·司马相如传》 豨谷崭岩兮水曾波。--《楚辞·招隐士》 仰视所登之处,崭然在云汉；组词：崭岩(险峻)；崭崒(陡峭高峻)；崭绝(险峻陡峭的样子；事物超群不寻常)；崭阢(高峻)；崭崖(陡峻的山崖)；崭露头角(比喻', '小学', '1'),
    ('嵌', 'qiàn', '12', '山', '上下', NULL, '嵌〈形〉 (形声。本义山谷深的样子) 同本义 张开的样子 金人仡仡其承钟虚兮,嵌岩岩其龙鳞。', '小学', '1'),
    ('巍', 'wēi', '20', '山', '上下', NULL, '巍〈形〉 (形声。从山,魏声。本义高大) 同本义 巍,高也。--《说文》 巍巍乎尧舜之有天下也。--《论语·泰伯》。集解巍巍者,高大也。” 崛巍巍而特秀；组词：巍科(高级的科举高试)；巍廓(高大开阔)；巍耸(高耸)；巍蟠(高大而盘曲)；巍崇(高大)；巍张(高大宽阔)；巍峻(高峻)', '小学', '1'),
    ('川', 'chuān', '3', '川', '左中右', NULL, '川〈名〉 (象形。甲骨文字形,左右是岸,中间是流水,正像河流形。本义河流) 同本义 川,贯川通流水也。；组词：川源(河川的源头)；顺尊(取自河川的祭品)；川游(游泳渡河)；川口(河口)；川水(江河之水)；川防(河堤 川 chuān', '小学', '1'),
    ('州', 'zhōu', '6', '川', NULL, NULL, '州 (会意。甲骨文字形,两边的曲折线象河流,中间象水中的陆地。州”是洲”的本字。小篆字形象两个川”字相重合。本义水中的陆地)', '小学', '1'),
    ('巡', 'xún', '6', '巛', '半包围', NULL, '巡 (形声。从辵,川声。本义到各地视察;巡行) 同本义 巡,视行也。--《说文》 五载一巡守。--《虞书》。郑注行视所守也。殷制六年一巡守,周制十二年一巡守。” 巡守者,巡所守也；组词：巡风料哨(巡 巡(廵)xún 1.往来查看~视', '小学', '1'),
    ('巢', 'cháo', '11', '巛', '上下', NULL, '巢 (象形。小篆字形,下边是树木,木上是三只鸟和鸟窝∠起来表示鸟栖于树窝上。本义鸟窝) 同本义 巢,鸟在木上曰巢,在穴曰窠。', '小学', '1'),
    ('工', 'gōng', '3', '工', '上下', NULL, '工 (象形。甲骨文字形,象工具形。工”、巨”(矩)古同字,有规矩”,即持有工具。本义工匠的曲尺)', '小学', '1'),
    ('左', 'zuǒ', '5', '工', NULL, NULL, '左 (会意。甲骨文字形,象手的象形。本义辅佐,从旁帮助◇作佐”) 同本义 左,手相左助也。', '小学', '1'),
    ('巧', 'qiǎo', '5', '工', '左右', NULL, '巧〈形〉 (形声。从工,丂声。工”有精密、灵巧义。本义技艺高明、精巧) 同本义 巧,技也。；组词：巧思(精巧的构思、设计)；巧工(技艺高超的工匠)；巧任(技巧,技能)；精巧；工巧(能很快发明的创造力量和品质)；巧夺天孙', '小学', '1'),
    ('巨', 'jù', '4', '工', NULL, NULL, '巨 (象形。金文字形,是矩”的本字,象人持矩形。本义画直角方形用的工具) 同本义◇作矩” 巨,规巨也。；组词：巨砮(法度', '小学', '1'),
    ('巩', 'gǒng', '6', '工', '左右', NULL, '巩 (形声。从革,巩声。从革”,表示与皮革有关。本义用皮革捆东西) 同本义 巩,以韦束也。；组词：巩巩(恐惧的样子) 巩 中国河南省县名 姓 巩(鞏)gǒng用皮革捆绑东西~用黄牛之革', '小学', '1'),
    ('巫', 'wū', '7', '工', NULL, NULL, '巫 (象形。据甲骨文,象古代女巫所用的道具。小篆象女巫两袖舞形。本义古代称能以舞降神的人)；组词：巫 巫wū装神弄鬼,装模作样,专搞迷信活动,骗取钱财的人~婆', '小学', '1'),
    ('差', 'chà', '9', '工', NULL, NULL, '差 cha (会意。小篆,从左(手)。本义失当;错;相差) 同本义 差,贰也,差不相值也。；组词：说差啦；认差了 差 区别 何必更以多寡为差', '小学', '1'),
    ('己', 'jǐ', '3', '己', NULL, NULL, '己 (象形。甲骨文字形,象绳曲之形。己”是古纪”字,假借作自己”用。1本义丝的头绪,用以缠束丝。2自己) 自己,本人 知己知彼,百战不殆。；组词：舍己为公；异己；克己；知己；己身(自己)；己私(自己的欲望)；己里钱(血汗钱,私房钱) 己 天干的第六位 己与三相近 己', '小学', '1'),
    ('已', 'yǐ', '3', '己', NULL, NULL, '已 (象形。象蛇形。一说原与子”同字。本义停止) 同本义 鸡鸣不已。--《诗·郑风·风雨》。传已,止也。” 德音不已。--《诗·小雅·南山有台》。传已,止也。” 以故事得已；组词：不已 完成,完毕 已,成也', '小学', '1'),
    ('巴', 'bā', '4', '巳', NULL, NULL, '巴 (象形。小篆象蛇形。本义大蛇) 古代传说中的一种大蛇 巴,巴虫也,或曰食象蛇。--《说文》 巴蛇食象,三岁而出其骨。--《山海经·海内南经》。注说者云,长千寻。” 朱卷之国', '小学', '1'),
    ('巷', 'xiàng', '9', '巳', '上下', NULL, '巷〈名〉hang 矿坑里的通道 巷 xiang 同本义。直为街,曲为巷;大者为街,小者为巷 斜阳草树,寻常巷陌,人道寄奴曾往。--辛弃疾《永遇乐》 深巷中犬吠。；组词：巷口(里弄的出入口)；巷言,巷议(于里巷中议论是非) 住宅 在陋巷,人不堪其忧,回也不改其乐', '小学', '1'),
    ('巾', 'jīn', '3', '巾', NULL, NULL, '巾 (象形。甲骨文字形,象布巾下垂之形。本义佩巾,拭布,相当于现在的手巾) 同本义 巾,佩巾也。；组词：花巾；小丝巾；巾栉(梳洗用品,即手巾和梳子；梳洗打扮)；巾帚(拭巾和扫帚)；巾帨(毛巾) 缠束或覆盖用的织物 巾袖无光', '小学', '1'),
    ('币', 'bì', '4', '巾', NULL, NULL, '币 (形声。从巾,敝声。从巾表示与布帛有关。本义古人用作礼物的丝织品) 同本义 幣,帛也。；组词：皮币(兽皮和缯布)；币玉(帛和玉,祭祀用品)；币号(祭祀用的物品名称)；币献(进献的礼品) 泛指车马皮帛玉器等礼物 凡执', '小学', '1'),
    ('市', 'shì', '5', '巾', '上下', NULL, '市 (会意。金文字形,上面是之”(往),下面是兮”,表市场嘈杂声。本义市场) 同本义 市,买卖之所也。；组词：市征(市场的 市shì 1.做买卖的场所~场', '小学', '1'),
    ('布', 'bù', '5', '巾', NULL, NULL, '布〈名〉 (形声。从巾,父声。本义麻布) 同本义(古时无棉布) 坤为布。--《易·说卦》 抱布贸丝。--《诗·卫风·氓》 女有余布。--《孟子》 果布辐凑而常然；组词：布衣(平民,老百姓', '小学', '1'),
    ('帅', 'shuài', '5', '巾', '左右', NULL, '帅 (形声) 同本义 无感我帨兮。--《诗·野有死麕》 毋施衿结帨。--《仪礼·士昏礼》 左佩纷帨。又,女子设帨于门右。--《礼记·内则》 军队中的主将、统帅 帅刘良佐拥骑至城下；组词：挂帅；帅甸(甸地的统帅 帅(帥)shuài 1.军队中最高级的指挥者元~', '小学', '1'),
    ('帆', 'fān', '6', '巾', '左右', NULL, '帆 张帆行驶 不枉故人书,无因帆江水。--韩愈《除官赴阙》 帆 〈名〉 挂在船桅上利用风力使船前进的布篷 孤帆远影碧空尽,唯见长江天际流。--李白《黄鹤楼送孟浩然之广陵》；组词：扬帆；帆力(帆受风时的推动力)；帆势(帆篷张挂之势)；帆楫(船帆和桨) 靠帆推进的船舶 两岸青山相对出,孤帆一片日边来', '小学', '1'),
    ('师', 'shī', '6', '巾', '左右', NULL, '师 (会意。从币,从垖。垖是小土山,帀是包围。四下里都是小土山,表示众多。本义古代军队编制的一级。二千五百人为一师)', '小学', '1'),
    ('希', 'xī', '7', '巾', '上下', NULL, '希 (会意。从巾,从爻,象做针线。巾”,丝织品,爻”,象针线交错。本义刺绣) 假借为稀”。稀少;罕见 希,罕也。；组词：希姓(罕见的姓)；希言(少言)；希疏(稀少)；希诧(媳惊奇)；希媳儿(媳少见的 希xī 1.盼望,期望~望', '小学', '1'),
    ('帐', 'zhàng', '7', '巾', '左右', NULL, '帐 (形声。从巾,长声。巾,麻丝织品。本义篷帐,有顶的篷帐) 同本义 帐,帱也。--《说文》 帱谓之帐。--《尔雅》 在上曰帐,在旁曰帷,禅帐曰帱；组词：帷帐(帷是四周相围而无顶的篷帐；帐是有顶的篷帐)；帐具(陈列帷帐入筵', '小学', '1'),
    ('帕', 'pà', '8', '巾', '左右', NULL, '帕〈名〉 束额巾 佩巾。通帊” 帷帐 绿树垂垂护宝栏,床头翠帕幂双环。--陈旅《题春宫倦绣图诗》 俗称小方巾为帕 压强单位。帕斯卡的简称 帕 〈动〉 缠绕,包裹 以锦缠股', '小学', '1'),
    ('帖', 'tiē', '8', '巾', '左右', NULL, '帖〈形〉 帖服。对约束、控制或权威命令顺从的 塞外蛮人方帖服,水边鬼卒又猖狂。--《三侠五义》；组词：伏伏帖帖；俯首帖耳；帖帖(形容帖伏收敛的样子；温顺,服帖)；帖伏(折服,顺从不反抗)；帖胁(拘束不展) 安定 事不妥帖', '小学', '1'),
    ('帘', 'lián', '8', '巾', '上下', NULL, '帘〈名〉 旧时酒家、茶馆作店招的旗帜,用布做成 白鸟窥鱼网,青帘认酒家。--唐·郑谷《旅寓洛南村舍》 帘 (形声。从竹,廉声。本义门帘) 帘子,遮蔽门窗的用具 簾,堂簾也。；组词：簾帷(遮蔽閠窗的簾子、布幕)；簾籠(窗簾和窗牖)；簾旌(簾端所緔之布帛)；簾政(皇太後垂簾聽政,故名)；簾庑(指堂前廊檐', '小学', '1'),
    ('帚', 'zhǒu', '8', '巾', '上下', NULL, '帚 (象形。甲骨文字形,象扫帚形。本义扫帚) 同本义 又如笤帚(扫帚);帚卜(吴中旧俗,妇女于正月灯节用裙束破帚以占事) 帚(箒)zhǒu扫除尘土、垃圾等的用具扫~。', '小学', '1'),
    ('帜', 'zhì', '8', '巾', '左右', NULL, '帜 (形声。从巾,只声。本义旗帜的通称) 同本义 帜,旌旗之属。--《说文新附》 长丈五尺、广半幅曰帜。--《墨子》 私记曰帜。--《通俗文》 拔赵帜,立汉赤帜；组词：帜羽(羽饰之旌旗)；帜志(旗帜) 标记 缝其裾为帜', '小学', '1'),
    ('帝', 'dì', '9', '巾', '上下', NULL, '帝 (象形。甲骨文字形,象花蒂的全形。上面象花的子房,中间象花萼(花瓣外面的绿片)。下面下垂的象雌雄花蕊。本义花蒂) 天帝,上帝。宗教或神话中称主宰万物的神。最高的天神；组词：帝乡(传说中天帝居住的仙乡)；帝君(古人对神的尊称)；帝江(传说中的神名', '小学', '1'),
    ('带', 'dài', '9', '巾', '上下', NULL, '带 (象形。小篆字形,上面表示束在腰间的一根带子和用带的两端打成的结。下面象垂下的须子,有装饰作用。本义大带,束衣的腰带)；组词：带冕(大带和冠冕)；带围(腰围,腰带)；带钩(皮革腰带上的金属钩', '小学', '1'),
    ('席', 'xí', '10', '巾', NULL, NULL, '席 (蓆”的古字。会意。从巾,庶省声。天子诸侯的席有刺绣镶边,故从巾。席用来待广大宾客,故从庶”省。本义供坐卧铺垫的用具◇又曾写作蓆”)', '小学', '1'),
    ('帮', 'bāng', '9', '巾', '上下', NULL, '帮 (形声。从巾,邦声。巾”。从巾”字多与布帛有关。本义鞋的边缘部分) 同本义 用纤指将绣帮儿弹。--元·乔吉《赏花时·睡鞋儿》；组词：帮子,帮儿(鞋帮) 泛指物体两侧或周围的部分 伙,群 东壁店里,午后走了一帮客', '小学', '1'),
    ('常', 'cháng', '11', '巾', '上下', NULL, '常 (形声。从巾,尚声。本义旗) 同本义 纪于太常。--《书·君牙》。传王之旌旗画日月曰太常。 载是常服。--《诗·小雅·六月》 裙子 叔旦泣涕于常,悲不能对。--《逸周书》 常；组词：常古(旧法,常法)；常故(旧例；常例)；常式(法式) 封建社会宣扬的所谓恒久不变的人与人之间的关系准则,即伦常；纲常 常', '小学', '1'),
    ('帽', 'mào', '12', '巾', '左右', NULL, '帽 (形声。从巾,冒声。巾是丝织品,表示材料。字本作月”,象帽形,又作冒”。本义帽子) 同本义 少年见罗敷,脱帽著帩头。；组词：帽凭(盈满的样子)；帽正(帽子前缘正中的装饰,一般为珠或玉)；帽襻儿(帽子上布制的扣纽带)；礼帽(跟礼服相配的帽子)；帽', '小学', '1'),
    ('幅', 'fú', '12', '巾', '左右', NULL, '幅〈名〉 (形声。从巾,畐声。从巾”表示与布帛有关。声符畐”训满”(参福”字条),在字中亦兼有表义作用。布帛的宽度(广)与满”有相通之处,故可以引申。本义 布帛 的宽度)；组词：单幅,双幅；宽幅的白布；幅裂(像 幅 fú 1.幅面,布、绸、呢绒等的宽度单~', '小学', '1'),
    ('幌', 'huǎng', '13', '巾', '左右', NULL, '幌 窗帘、帷幔 幌,帷也。--《集韵》 何时倚虚幌,双照泪痕干。--唐·杜甫《月夜》 酒店的招子 幌 挥动;摇晃 随意走动 须是再多幌个时辰,才好去回话', '小学', '1'),
    ('幔', 'màn', '14', '巾', '左右', NULL, '幔 (形声。从巾,曼声。巾,丝麻织品。本义帐幕,帐幔) 同本义 幔,幕也...蔽在上曰幔,在旁曰帷。；组词：幔亭(张挂帐幕围成的亭子)；幔屋(帐篷)；幔幕,幔帷,幔城(张帷幔围绕如城,故称幔城”)；幔室(用帷幕围成的房间) 以布', '小学', '1'),
    ('幕', 'mù', '13', '巾', '上下', NULL, '幕 (形声。从巾,莫声。本义覆布,帐篷的顶布) 同本义 幕,帷在上曰幕。--《说文》 舞于鲁君之幕下。--《谷梁传·定公十年》 楚幕有乌。--《左传·庄公二十八年》 夫子之在此也；组词：幕幕(覆布周密的样子)；幕燕(筑巢于幕上的燕子)；幕下(帐幕之下；幕府中) 帐幕；篷帐 风动将军幕', '小学', '1'),
    ('幢', 'zhuàng', '15', '巾', '左右', NULL, '幢 chuang (形声。从巾,童声。本义古时作为仪仗用的一种旗帜) 垂筒形、饰有羽毛、锦绣的旗帜。古代常在军事指挥、仪仗行列、舞蹈表演中使用 般旌旗);幢队(行军时', '小学', '1'),
    ('干', 'gàn', '3', '干', '上下', NULL, '干〈名〉 (象形。甲骨文字形,象叉子一类的猎具、武器,本是用于进攻的,后来用于防御。本义盾牌)；组词：∶干羽(盾牌和雉羽,供乐舞之用)；干革(干即盾；革即甲胄类', '小学', '1'),
    ('平', 'píng', '5', '干', NULL, NULL, '平〈形〉 (指事。小篆字形, 从于, 从八。于”是气受阻碍而能越过的意思, 八”是分的意思, 气越过而能分散, 语气自然平和舒顺。本义 语气平和舒顺)；组词：平典(和平典雅)；平度(平和的法度)；平气(平和之气)；平远(谓性情平和,胸襟远大)；平愉(平和愉悦)；平睦(犹平和)', '小学', '1'),
    ('年', 'nián', '6', '干', NULL, NULL, '年 (形声。甲骨文字形,上面是禾”,下面是人”,禾谷成熟,人在负禾。小篆字形,从禾,千声。本义年成,五谷成熟)；组词：年登(谷物丰收)；年荒(谷物歉收)；年丰(年成丰收)；年饥(年成荒 年(秊)nián 1.时间单位', '小学', '1'),
    ('并', 'bìng', '6', '干', '上下', NULL, '并 (会意。《说文》从二立。”金文字形,为二人并立之形。本义并行,并列) 同本义 乲,併也。从二立,会意。今隶作乲。；组词：并列；并肩作战；并介(不论穷富,都能耿介于守', '小学', '1'),
    ('幸', 'xìng', '8', '干', '上下', NULL, '幸 幸,吉而免凶也。--《说文》 幸而至于旦。--《礼记·檀弓》 不幸短命死矣。--《论语》。皇疏凡应死而生曰幸。应生而死曰不幸。” 幸甚。--曹操《步出夏门行》 生固幸而遇予；组词：三生有幸；荣幸(光荣而幸运)；万幸(非常幸运)；得此幸,不幸中的大幸；庆幸；天幸；不幸；万幸 幸 通倖”', '小学', '1'),
    ('幻', 'huàn', '4', '幺', NULL, NULL, '幻 惑乱 幻,相诈惑也。--《说文》 民无或胥,诪张为幻。--《书·无逸》 又如幻惑(迷惑) 奇异地变化 幻 假象;虚幻,虚无 皆幻也；组词：幻惑(迷惑) 奇异地变化 幻 假象；虚幻,虚无 皆幻也', '小学', '1'),
    ('幼', 'yòu', '5', '幺', '左右', NULL, '幼 (会意。从幺,从力。幺,小。年幼力小。本义幼小) 同本义 幼,小也。--《说文》 幼,稀也。--《尔雅》 人生十年曰幼。--《礼记·曲礼》 子幼。--《仪礼·丧服》；组词：幼主(年幼的君主)；幼少(幼小)；幼志(幼年时的志向)；幼君(年幼的君主)；幼孤(年幼的孤儿)；幼累(指年幼的儿女)；幼', '小学', '1'),
    ('幽', 'yōu', '9', '幺', NULL, NULL, '幽〈动〉 同本义 幽,隐也。--《说文》。段注幽,从山,犹隐从阜,取遮蔽之意。” 昆仑旁薄幽。--《太玄·中》。注隐也。” 雍遏不通曰幽。--《周书·谥法》 以致其幽；组词：幽隐(隐居的贤才)；幽士(幽子,幽人', '小学', '1'),
    ('广', 'guǎng', '3', '广', '上下', NULL, '广 (形声。从广,黄声。从广”,表示与房屋有关。按广”和弙”本不同义是两个字。广”,甲骨文和金文的写法象屋墙屋顶,其含义是依山崖建造的房屋。现在广”是 弙”的简化字', '小学', '1'),
    ('庄', 'zhuāng', '6', '广', NULL, NULL, '庄 (会意兼形声。从苃,从壮,壮亦声。本义草大) 同本义 莊,草芽之壮也。--《六书正伪》 莊,草盛貌。--《唐韵》 汉明帝名莊,汉世多以严字为之。《左传》、《楚莊王国》；组词：庄论(庄重严肃的议论或说教)；庄语(庄重正直的言论)；庄士(端正 庄(莊)zhuāng 1.严肃,端重~严', '小学', '1'),
    ('庆', 'qìng', '6', '广', NULL, NULL, '庆 (会意。甲骨文字形,左边是个文”字,中间有个心,表示心情诚恳;右边是一张鹿皮∠起来表示带着鹿皮,真诚地对人庆贺。小篆字形上面是鹿字省略一部分;中间是心”字 ,表心意', '小学', '1'),
    ('庇', 'bì', '7', '广', NULL, NULL, '庇 (形声。从广,比声。广”(? 同本义 庇,荫也。--《说文》。按,字亦作庀 弓长六尺,谓之庇轵。--《考工记·轮人》 安得广厦千万间,大庇天下寒士俱欢颜；组词：庇庥(荫庇；庇护)；庇覆(掩盖,覆盖)', '小学', '1'),
    ('床', 'chuáng', '7', '广', NULL, NULL, '床 (形声。从木,爿声。本义坐卧的器具) 同本义 牀,安身之坐也。从木,片声。字亦作床。古闲居坐于牀,隐于几,不垂足,夜则寝,晨兴则敛枕簟。；组词：单人床；双人床；帆布床；折叠床；卧病在床；床裙(床围,围在床四周的绸、布等)；床地平(床面)；床背阁(置于床背的长方形', '小学', '1'),
    ('序', 'xù', '7', '广', NULL, NULL, '序 (形声。从广,予声。从广,与房屋有关。本义东西墙) 堂屋的东西墙 序,东西墙也。--《说文》 西序东向。--《书·顾命》 奠爵于序端。--《仪礼·乡饮酒礼》 直东序', '小学', '1'),
    ('庐', 'lú', '7', '广', NULL, NULL, '庐 (形声。从广,廬声。从广”,表示与房屋有关。本义特指田中看守庄稼的小屋) 同本义 庐,寄也。秋冬去,春夏居。', '小学', '1'),
    ('库', 'kù', '7', '广', NULL, NULL, '库 (会意。从广,表示与房屋有关,从车。兵车藏在房屋一类的建筑内,表示是储藏武器战车的地方。本义军械库,收藏兵器和兵车的处所)；组词：库兵(库藏的兵器) 后泛指贮物的屋舍 库,舍也', '小学', '1'),
    ('应', 'yīng', '7', '广', NULL, NULL, '应 应当,应该 应,当也。--《说文》 应,当也。--《尔雅》 文王既勤止,我应受之。--《诗·周颂·赉》 故国神游,多情应笑我；组词：应然(应该如此)；应伯爵(白吃白喝', '小学', '1'),
    ('底', 'dǐ', '8', '广', NULL, NULL, '底 (形声。从广,氐声。本义止住;停滞) 同本义 底,止居也。--《说文》 勿使有壅蔽湫底。--《左传·昭公元年》 又 底禄以德。 有所底止。--《左传·宣公三年》 盟以底信；组词：底止(结局)；底着(停滞；滞留)；底遏(遏止)；底滞(滞留) 隐藏 达到 引致 磨砺 底 dǐ 1物体的最下部分~层、鞋', '小学', '1'),
    ('店', 'diàn', '8', '广', NULL, NULL, '店 (形声。从广,占声。从广”,表示与房屋有关。本义栈房) 同本义 肆,所以陈货鬻之物也;店,所以置货鬻之物也。--晋·崔豹《古今注》 旅舍;客店 付的费用) 商店', '小学', '1'),
    ('庙', 'miào', '8', '广', NULL, NULL, '庙 (形声。从广,朝声。广”与建筑物有关。本义宗庙,供奉祭祀祖先的处所) 同本义 弐,尊先祖貌也。', '小学', '1'),
    ('府', 'fǔ', '8', '广', NULL, NULL, '府〈名〉 (形声。从广,表示与房屋有关,付声。本义府库,府藏。古时国家收藏文书或财物的地方)；组词：府室(国家书库)；府库(官府储存财物、兵甲的仓库)；府实(府库中的财物)；府帑(国库；国库所藏的金帛)；府钱(府库的钱财', '小学', '1'),
    ('庞', 'páng', '8', '广', NULL, NULL, '庞 (形声。从广,龙声。广,象高屋形。本义高屋) 同本义 庞,高屋也。--《说文》。段玉裁注谓屋之高者也,故字从广。” 脸盘 姓。如庞德(三国魏南安人。字令明。初从马腾；组词：庞杂；庞鸿(天地元气浑成未分,宇宙浑然一体的样子)；庞眉(眉毛又粗又黑) 高大 湛恩庞洪', '小学', '1'),
    ('废', 'fèi', '8', '广', NULL, NULL, '废 (形声。从广,发声。从广”,表示与房屋有关。本义房子倾倒) 同本义 废,屋顿也。--《说文》。段玉裁注顿之言钝,谓屋钝置无居之者也。” 泛指倾圮,倒塌 往古之时,四极废；组词：作废(因失效而废弃)；废业(丢弃正业,不务正业；荒废衰败的事业)；废贩(荒废；败坏)；废损(荒废损害)；废旷(荒废,不利', '小学', '1'),
    ('度', 'dù', '9', '广', NULL, NULL, '度 (形声。从又,庶省声。又”即手,古代多用手、臂等来测量长度。本义计量长短的标准,尺码)；组词：尺度 法制；法度 公室无度', '小学', '1'),
    ('座', 'zuò', '10', '广', NULL, NULL, '座 (形声。从广,坐声。坐”的后起字。本义座位) 同本义。供人坐的地方,也指位置,座次 隔座送钩春酒暖。--唐·李商隐《无题》 座上有健啖客。--明·魏禧《大铁椎传》；组词：宝座(指帝王或神佛的座位)；上座(坐位分尊卑时,最尊的坐位叫上座)；落座(坐到位置上)；满座；空座；首座；末座；楼座；茶', '小学', '1'),
    ('庭', 'tíng', '9', '广', NULL, NULL, '庭〈名〉 (形声。从广,廷声。广,就山岩架成的屋。本义厅堂) 同本义 庭,宫中也。--《说文》 是君子之所以骋志意于坛宇宫庭也。--《荀子·儒效》 藜棘树于中庭；组词：庭落(厅堂)；庭庑(堂下四周的廊屋)；庭炬(古代庭中照明的火炬)；庭阶(厅砌', '小学', '1'),
    ('庵', 'ān', '11', '广', NULL, NULL, '庵 (闇的俗字作庵或萩) 圆顶草屋 草圆屋谓之庵。--《释名·释宫室》 庵,舍也。--《广雅》 亲人萩庐。--《后汉书·皇甫规传》 居河之湄,结划为庵。--《神仙传·焦先传》；组词：庵舍(设在墓旁的草屋)；庵庐(草舍) 尼姑的住所 一定另外或村庄或尼庵寻个下处', '小学', '1'),
    ('庶', 'shù', '11', '广', NULL, NULL, '庶 众多 庶,屋下众也。--《说文》 既庶且多。--《诗·大雅·卷阿》 明庶风至。--《春秋考异郵》 庶众也。--《尔雅》 庶明厉翼。--《书·皋谟》 制义庶乎以行之；组词：庶常(众多有养德的官员)；庶类(众多物类)；庶官(百官,众官)；庶士(众士,多士；军士)；庶事(诸事,众事)；庶草(百草', '小学', '1'),
    ('康', 'kāng', '11', '广', NULL, NULL, '康 (会意。康为穅的本字。从禾,康声。本义谷皮;米糠) 同本义 康,谷皮也。--《说文》。字亦作穅。 尘垢粃穅。--《庄子·逍遥游》 亦食穅何覈耳。--《汉书·陈平传》 播康迷目', '小学', '1'),
    ('庸', 'yōng', '11', '广', NULL, NULL, '庸 (会意。小篆字形。从用,从庚。庚更”同音,表更换。先做某事,然后更换做别的事。本义用;需要)；组词：无庸讳言；庸yōng 1.常,平常的~行之谨', '小学', '1'),
    ('廉', 'lián', '13', '广', NULL, NULL, '廉 (形声。从广,兼声。从广”,表示与房屋有关。本义厅堂的侧边) 同本义 廉,仄也。--《说文》。按,堂之侧边曰廉,故从广。天子之堂九尺,诸侯七尺,大户五尺,士三尺。堂边皆如其高', '小学', '1'),
    ('廊', 'láng', '11', '广', NULL, NULL, '廊〈名〉 (形声。从广,郎声。从广”,表示与房屋有关。本义厅堂周围的屋) 同本义 平公恐惧,优于廊室之间。；组词：廊房(廊室', '小学', '1'),
    ('廓', 'kuò', '13', '广', NULL, NULL, '廓〈名〉 (形声。从广,郭声。广”甲骨文、金文象屋墙屋顶形,这里表示与建筑物有关。本义通郭”。外城)；组词：城廓(内外城的城墙,指城池) 物体的外缘 白描,以细笔钩勒形廓者也', '小学', '1'),
    ('延', 'yán', '6', '廴', '上下', NULL, '延 同本义 延,长行也。--《说文》。按,字亦作蜒”。 蝮蛇蜒只。--《楚辞·大招》 延颈而鸣,舒翼而舞。--《韩非子》 我不敢知曰不其延。惟不敬厥德,乃早坠厥命；组词：延瞩(引颈瞩目)；延望(引颈远望)；延算三纪(延长寿命三十六年)；延年(延长寿命)；延息(延长寿命)；延期(延长或推迟日', '小学', '1'),
    ('廷', 'tíng', '6', '廴', '半包围', NULL, '廷〈名〉 (形声。从廴,壬声。廴,建之旁。有引长之义。本义朝廷) 同本义 廷,朝中也。--《说文》 虎兕争兮于廷中。--《楚辞·王逸·九思逢尤》 游汉廷公卿间；组词：廷臣(朝臣)；廷吏(朝廷的官吏)；廷推(明代用高级官吏,由大臣推荐,经皇帝批准后任用)；廷魁(科举时廷试头名', '小学', '1'),
    ('建', 'jiàn', '8', '廴', '半包围', NULL, '建 (会意。从廴,有引长的意思,从聿(意为律)。本义立朝律) 同本义 立朝律也。--《说文》 建,立也。--《广雅》；组词：建法(制定法律)；建中(定立标准)；建极(制定至中至正的建国大法) 引申为建立、创设 官惟王建国', '小学', '1'),
    ('开', 'kāi', '4', '廾', '上下', NULL, '开 (会意。小篆字形,两边是两扇门,中间一横是门闩,下面是一双手,表示两手打开门闩之意。本义开门)；组词：开城(打开城门)；开门钱(男家迎亲的轿子到女家,女家开门前索取的钱财) 打开,开启 微子开封于宋', '小学', '1'),
    ('异', 'yì', '6', '廾', '上下', NULL, '异 (会意。異”,甲骨文字形,象个有手、脚、头的人形。从廾从畀。畀,予也。本义奇特;奇异;奇怪)；组词：异疾(奇怪的病症)；异形(怪异或奇特的形状) 不同 礼者为异', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('弃', 'qì', '7', '廾', '上中下', NULL, '弃 (会意。甲骨文字形,上面是个头向上的婴孩,三点表示羊水,头向上表示逆产。中间是只簸箕 ,下面是两只手∠起来表示将不吉利的逆产儿倒掉之意。小篆写法大同小异。本义 扔掉', '小学', '1'),
    ('弄', 'nòng', '7', '廾', '上下', NULL, '弄 long 宫中别道 弄 (会意。上为玉”,下为廾”。指双手玩赏玉器。本义用手把玩;玩弄)；组词：弄丸(古技巧名称', '小学', '1'),
    ('弊', 'bì', '14', '廾', '上下', NULL, '弊 (形声。字本作獘”,从犬,敝声。从犬,表示被狗扑倒或遭狗咬而倒下。讹变为弊”。本义仆,向前倒下) 同毙”。仆;向前倒下 獘,茧顿仆也。；组词：弊仆(倒毙) 通蔽”', '小学', '1'),
    ('式', 'shì', '6', '弋', '半包围', NULL, '式 (形声。从工,弋声。工有矩”的意思。本义法度;规矩) 同本义 式,法也。--《说文》 式,法也。--《周书·谥法》 下士之式。--《诗·大雅·下武》。传法也。” 三曰筮式；组词：式度(规制,法式)；式则(法则；规范) 榜样；楷模 世世享德,百邦作式', '小学', '1'),
    ('弓', 'gōng', '3', '弓', NULL, NULL, '弓 (象形。甲骨文字形,象弓形,有弓背和弓弦,后省去弓弦,只剩下弓背,隶变后变成现在的弓”字。弓”是汉字部首之一,从弓”的字多与弓箭”有关系。本义射箭或打 弹的器械)', '小学', '1'),
    ('引', 'yǐn', '4', '弓', '左右', NULL, '引 (会意。从弓丨。丨表示箭。箭在弦上,即将射发。本义拉开弓) 同本义 引,开弓也。--《说文》 君子引而不发,跃如也。--《孟子》 引弓而射。--《淮南子·说林训》 臣为王引弓；组词：引手(引箭手)；引弓(拉弓)；引满(拉弓至满) 拉,牵挽 人方引婴儿而欲投之江中', '小学', '1'),
    ('弛', 'chí', '6', '弓', '左右', NULL, '弛 (形声。从弓,也声。本义放松弓弦) 同本义 弛,弓解也。--《说文》 弛弓尚角。--《礼记·曲礼》 一张一弛。--《礼记·杂记》 乃弛弓而自后缚之；组词：弛张(一松一紧', '小学', '1'),
    ('弟', 'dì', '7', '弓', NULL, NULL, '弟 (象形。甲骨文字形,象有绳索围绕于弋”,象竖立有杈的短木桩。绳索捆束木桩,就出现了一圈一圈的次第”。本义次第)；组词：弟老的(排行最小的)；弟郎(兄弟)；弟兄相狱(兄弟相互诉讼)；弟昆(弟兄)；弟息(弟弟与 弟 dì 1同父母的比自己年纪', '小学', '1'),
    ('张', 'zhāng', '7', '弓', '左右', NULL, '张 (形声。从弓,长声。本义把弦安在弓上) 同本义 张,施弓弦也。--《说文》 一张一弛。--《礼记·杂记》 鲁琴张字子开。--《左传·昭公二十年》 良弓难张,然可以及高入深；组词：张满(张弓使满)', '小学', '1'),
    ('弥', 'mí', '8', '弓', '左右', NULL, '弥 (形声。从弓,尔声。本义放松弓弦) 同本义 彌,驰弓也。--《说文》 弥,《说文》弛弓也。--《集韵》 充满;填满 弥缝其阙,而匡救其灾。--《左传》；组词：弥封；弥补；弥缝 通弭”', '小学', '1'),
    ('弦', 'xián', '8', '弓', '左右', NULL, '弦 (会意。左为弓”,右为丝”。弓弦是用丝做成的。本义弓弦) 同本义 弦,弓弦也。从弓,象丝轸之形。；组词：弦箭(弦上之箭)；弦栝(弓弦和箭末扣弦处) 弓弩 乐器上的肠线或金属丝 弦而鼓之', '小学', '1'),
    ('弧', 'hú', '8', '弓', '左右', NULL, '弧〈名〉 (形声。从弓,瓜声。本义木弓) 同本义;泛指弓 弧,木弓也。--《说文》 弦木为弧。--《易·系传》 檿弧箕服。--《国语·郑语》 弧弓夭猎。--《汉书·韩安国传》；组词：弧弓(古代六弓之一', '小学', '1'),
    ('弯', 'wān', '9', '弓', '上下', NULL, '弯 (形声。本义拉弓) 同本义 弯,持弓关矢也。--《说文》 弯,引也。--《广雅·释诂一》 弯綦卫之箭。--《淮南子·原道》 弯威弧之拔刺兮。--《文选·张衡·思玄赋》；组词：弯弹(拉弓射弹)；弯弓(弯弧', '小学', '1'),
    ('弱', 'ruò', '10', '弓', '左右', NULL, '弱 (会意。小篆字形,两把弯曲的弓,彡”象毛羽之形,合起来表示柔弱。本义气力小;势力差)', '小学', '1'),
    ('弹', 'dàn', '11', '弓', '左右', NULL, '弹 (形声。从弓,单声。本义弹丸) 同本义 弹,行丸也。--《说文》 长安大道边,挟弹谁家儿?--唐·苏涣《变律》其三；组词：枪弹；弹子涡(卵石)；枪林弹雨(形容战斗激烈)；弹丸黑子(形容地域狭小) 形状像弹丸的东西,如圆形的果实；禽鸟的卵等 其', '小学', '1'),
    ('强', 'qiáng', '12', '弓', '左右', NULL, '强 (形声。从虫,弘声。本义米中小虫) 同本义 通襁”。襁褓 成王少在强葆之中。--《史记·鲁周公世家》 强 (通彊。弱的反义词) 弓有力 彊,弓有力也。--《说文》 强,健也；组词：强弩(用机括发射的强弓) 强盛；势力大 不可谓强', '小学', '1'),
    ('归', 'guī', '5', '彐', NULL, NULL, '归 (会意。从止,从媎省。本义女子出嫁) 同本义 归,女嫁也。--《说文》 帝乙归妹。--《易·泰》 桃之夭夭,灼灼其华。之子于归,宜其室家；组词：归适(出嫁)；归女(嫁女)；归妹(嫁妹)', '小学', '1'),
    ('当', 'dāng', '6', '彐', '上下', NULL, '当 (形声。从田,尚声。本义两块田相当、相等) 对等;相当于 当,田相值也。--《说文》 必当其位。--《吕氏春秋·孟夏纪》 蔽贤者当之。--《孟子·离娄下》 朱也当御；组词：旗鼓相当；门当户对；当才(才能与所任之事相当)；当匹(匹敌；对等)；实力相当 面对着 木兰当户织', '小学', '1'),
    ('录', 'lù', '8', '王', '上下', NULL, '录 (形声。从金,录声。本义绿色金属) 同本义 録,金色也。--《说文》 记载言行事物的册籍 录,记之具也。--《广雅·释诂三》 皆辨其物而奠其录。--《周礼·职币》；组词：言行录；名人录 次第,次序 今大国越录', '小学', '1'),
    ('形', 'xíng', '7', '彡', '左右', NULL, '形 同本义 形,象形也。--《说文》 物成生理谓之形。--《庄子·天地》 雷雨之动满形。--《易·屯》 在天成象,在地成形。--《礼记·乐记》 形色天性也。--《孟子》 形者；组词：形物(有形之物)；条形；线形；方形；圆形；球形；梯形；三角形；正方形；多角形；多边形；口形；体形 形体,实体 可以隐形', '小学', '1'),
    ('彤', 'tóng', '7', '彡', '左右', NULL, '彤〈动〉 (会意。从丹,从彡。丹,丹砂。彡,毛饰。本义彩色装饰) 同本义 彤,丹饰也。--《说文》 彤弓一。--《书·文侯之命》 诸侯彤弓。--《荀子·大略》。按丹漆也。”；组词：彤几(朱漆几)；彤镂(涂丹漆和雕刻花纹)；彤辇(朱漆宫车)；彤壶(朱漆漏壶)；彤庭(彤宫,彤殿,彤廷『代宫廷', '小学', '1'),
    ('彩', 'cǎi', '11', '彡', '左右', NULL, '彩 (形声。从彡),采声。从彡”表示与图画、文饰相关。本义文采,文章才华) 同本义 延之与陈郡谢灵运俱以词彩齐名。；组词：彩仗(彩饰的仪仗)；剪彩；张灯结彩 指某些赌博、竞赛等赢得的财物 大博争雄好彩来,全盘一掷万人开', '小学', '1'),
    ('彪', 'biāo', '11', '彡', '半包围', NULL, '彪 (会意。从虎,从彡)。彡”,《说文》象其文也。”本义虎身的斑纹) 同本义 彪,虎文也。；组词：彪文(文采丰盛的样子)；彪章(文采美盛的样子) 虎,幼虎 熊彪顾盼,鱼龙起伏', '小学', '1'),
    ('彬', 'bīn', '11', '彡', '左右', NULL, '彬 (形声。从彡),焚省声(省去火”)。本义文质兼备的样子) 同本义 份,文质备也。《论语》曰文质份份。”彬,古文份。；组词：文质彬彬(既文雅又朴实) 富有文采的 颂优游以彬蔚,论精微而朗畅', '小学', '1'),
    ('彭', 'péng', '12', '彡', '左右', NULL, '彭〈象〉 (会意。从壴,从彡。壴”在古文字中象鼓形。彡,毛饰形。本义鼓声) 同本义 彭,鼓声也。', '小学', '1'),
    ('彰', 'zhāng', '14', '彡', '左右', NULL, '彰 (会意兼形声。从彡从章,章亦声。章,显著;彡,加上修饰。本义明显,显著) 同本义 彰,文彰也。；组词：彰弥(更加显著；越发暴露)；彰明昭著(彰明较著', '小学', '1'),
    ('影', 'yǐng', '15', '彡', '左右', NULL, '影 (形声。从彡,景声。彡,毛饰花边形。本义影子;因挡住光线而投射的暗影) 同本义 影,形影。；组词：影灯(点火取影的彩灯)；影不离灯(紧密地连在一起)；影形不离(形影不离', '小学', '1'),
    ('役', 'yì', '7', '彳', '左右', NULL, '役 (古文作伇。会意。甲骨文字形,象人持殳击人。本义服兵役,戍守边疆) 同本义 役,戍边也。执殳巡行也。；组词：役夫(服役的人)；役民(服役的人)；役卒(服役的人) 役使,驱使 予造天役,遗大投艰于朕身', '小学', '1'),
    ('彻', 'chè', '7', '彳', '左右', NULL, '彻 (形声。从彳,甲骨文,从鬲”(炊具)从丑”(举手),表示吃罢饭用手撤去炊具的意思。《说文》给古文增加了音符彳”,变成了形声字。本义撤除,撤去)；组词：彻案(撤去食案)；彻坐(撤去座位)；彻兵(撤军) 拆毁；拆下 彻 彻 chè通；透响~云霄、~夜不眠', '小学', '1'),
    ('彼', 'bǐ', '8', '彳', '左右', NULL, '彼 (形声。从彳,皮声。彳”)。本义流行、传播,施加) 那,与此”相对 彼,对此称彼也。--《玉篇》 逝将去女,适彼乐土。--《诗·魏风·硕鼠》 彼君子兮,不素食兮；组词：彼此腾倒着做(彼此交换', '小学', '1'),
    ('往', 'wǎng', '8', '彳', NULL, NULL, '往 (会意。甲骨文字形,从止,从土。意为从这个地方走向目的地。本义去,到...去) 同本义 往,之也。；组词：前往(前去；去)；往造(前去拜访)；往教(老师前往学生处施教)；往旋(往复回 往wǎng 1.去,到有来有~', '小学', '1'),
    ('征', 'zhēng', '8', '彳', '左右', NULL, '征 (形声。从彳,正声。从彳,表示与行走有关。甲骨文从彳,从足。本义到很远的地方去,远行)；组词：征鼙(征战的军鼓)；征衣(行旅在在外的御寒衣服)；征客(游子', '小学', '1'),
    ('径', 'jìng', '8', '彳', '左右', NULL, '径 经过,行经 径,过也。--《广雅》 夜径泽中。--《汉书·高帝纪》。按,行也。 又如径历(经过);径复(往返,迂回曲折) 径 南北为径 径 (形声。从彳,表示与道路有关,巠声；组词：径历(经过)；径复(往返,迂回曲折) 径 南北为径 径 (形声', '小学', '1'),
    ('待', 'dài', '9', '彳', '左右', NULL, '待 (形声。从彳,寺声。本义等待,等候) 同本义 待,逗也。--《广雅》 有待而行也。--《易·归妹》 窃待于下风。--《庄子·渔父》 多行不义,必自毙,子姑待之；组词：待年(等待长大', '小学', '1'),
    ('很', 'hěn', '9', '彳', '左右', NULL, '很 (形声。从彳,艮声。本义违逆,不听从) 同本义 很,不听从也。--《说文》 美而很。--《左传·襄公二十六年》。服注戾不从教。” 今王将很天而伐齐--《国语·吴语》；组词：很子(忤逆的儿子)；很忤；很触(违犯 争斗；争讼 很毋求胜,分毋求多', '小学', '1'),
    ('徊', 'huái', '9', '彳', '左右', NULL, '徊 (形声。表示与行走有关)回环。也作回”、迴” 佪 徊huái 徊huí 1.回环。参见"徊肠伤气"。', '小学', '1'),
    ('律', 'lǜ', '9', '彳', '左右', NULL, '律〈名〉 (形声。从彳,聿声。本义法律;法令) 同本义 (多指具体的规则、条文) 律,均布也。；组词：律则(律条)；律贯(法律系统)；律科(法令条文)；律度(规矩,法度)；律纪(纪律)；律贯(指法律系统)；律斩(依法斩决)', '小学', '1'),
    ('徐', 'xú', '10', '彳', '左右', NULL, '徐 (形声。从彳,余声。双人旁与行走有关。本义慢步走) 同本义 徐,安行也。--《说文》 乃徐有说。--《易·困》。虞注坤为徐。” 徐其攻而留其日', '小学', '1'),
    ('徒', 'tú', '10', '彳', '左右', NULL, '徒〈动〉 (形声。从辵,土声。本义步行) 同本义 徒,步行也。--《说文》 我徒我御。--《诗·小雅·黍苗》 君子耆老不徒行。--《礼记·王制》 徒递来告；组词：徒徙(无舟船乘载而徒步过水)；徒跣(赤足步行)；徒践(赤足步行)；徒杠(供徒步行走的小桥)；徒负(徒步负荷)；徒行(步行', '小学', '1'),
    ('得', 'dé', '11', '彳', '左右', NULL, '得 (会意。金文字形,右边是贝”(财货)加手”,左边是彳”,表示行有所得。手里拿着财货,自然是有所得。本义得到,获得)；组词：得人心；各得其所；得肆(得志,肆意)；得闲儿(有空闲时间；得空)；得胜回头 得 dé 1〈古〉同''德''所识穷乏者~我与(', '小学', '1'),
    ('徘', 'pái', '11', '彳', '左右', NULL, '徘 (形声。从彳,非声。表示小步行走) 徘徊 他在街上徘徊 三纳之而未克,徘徊容与,追者益近', '小学', '1'),
    ('徙', 'xǐ', '11', '彳', '左右', NULL, '徙 (形声。从辵,止声。本义迁移) 同本义 (平行或由上而下的移动) 徙,迻也。--《说文》 徙,移也。--《广雅》 若徙于他。--《周礼·比长》。注谓出居异乡也。” 死徙无出乡；组词：徙倚(徘徊；留连)；徙贯(迁地居住,更换籍贯)；迁徙(迁移)；徙居(徙次,即迁居, 徙xǐ 1.迁移~居', '小学', '1'),
    ('御', 'yù', '12', '彳', '左右', NULL, '御〈动〉 (会意。甲骨文字形。左为行”的省写,中为绳索形,右是人”形。意为人握辔行于道中,即驾驶车马。本义驾驶车马)；组词：御轮(赶车)；御策(驾驭马匹的鞭子)；御正(驾驶使不偏斜)；御夫(驾驭车马的人) 后亦泛指驾驭一切运行或飞行之物 御轻舟', '小学', '1'),
    ('循', 'xún', '12', '彳', '左右', NULL, '循 (形声。从彳,盾声。彳,双人旁,与行走有关。本义顺着,沿着) 同本义 循,行顺也。--《说文》 循道而趋。--《庄子·天道》 循墙而走。--《庄子·列御寇》 率循大下；组词：循轨(依轨道而行)；循箫(沿街叫卖的人) 按照；依序 因任而授官,循名 循xún 1.顺着,遵照,沿袭~着', '小学', '1'),
    ('微', 'wēi', '13', '彳', '左中右', NULL, '微〈动〉 (会意。从彳。本义隐秘地行走) 同本义 微,隐行也。--《说文》 崔杼微逆光。--《左传·襄公十九年》；组词：微行(便装出行,不想让人知其尊贵的身分) 藏匿,隐蔽 其徒微之', '小学', '1'),
    ('德', 'dé', '15', '彳', '左右', NULL, '德 (形声。从彳,惪声。从彳”,表示与行走有关。本义登高,攀登) 同本义 德,升也。--《说文》 君子德车。--《易·剥》虞本。按,与剥庐对文。登也,升。君子以顺德,亦本字', '小学', '1'),
    ('徽', 'huī', '17', '彳', '左中右', NULL, '徽 (形声。从糸,表示与线丝有关,微省声。本义三纠绳) 同本义 徽,三股绳也。--《说文》 系用徽纆。--《易·坎》。刘注三股为徽。” 绳索 免于徽索。--《汉书·扬雄传》；组词：徽索(徽绳', '小学', '1'),
    ('心', 'xīn', '4', '心', NULL, NULL, '心 (象形。据甲骨文和小篆,中间像心;外面像心的包络。本义心脏) 同本义 心,人心也。在身之中,象形。；组词：心腹之病(致命之祸；隐患)；心上刃(忍”字的拆写)；心肝胕蒂(心肝宝贝)；心气(中医指心脏的功能)；心系(系悬心脏于胸腔', '小学', '1'),
    ('必', 'bì', '5', '心', NULL, NULL, '必 (会意。从八,从弋。弋亦兼表字音。八”表示分”,弋”即杙”,小木桩,合起来指用木杆做标记。本义区分的标准) 标杆;标准 必,分极也。；组词：必防其渐(防微杜渐之意', '小学', '1'),
    ('忆', 'yì', '4', '忄', '左右', NULL, '忆 (形声。从心,意声。本义思念,回想) 同本义 问女何所忆。--《乐府诗集·木兰诗》 还思建邺水,终忆武昌鱼。--庾信《奉和永丰殿下言志》；组词：忆想(回想) 留在记忆中；记住 读书数行并下,过目皆忆', '小学', '1'),
    ('忌', 'jì', '7', '心', '上下', NULL, '忌 (形声。从心,己声。本义憎恨) 同本义 忌,憎恶也。--《说文》 而忌处者。--《国语·晋语》 不克不忌。--《大戴礼记·卫将军文子》 子将助天为虐；组词：忌恶(憎恶坏人坏事)；忌愤(怨愤,嫉恨) 嫉妒 操虽称美,心甚忌之', '小学', '1'),
    ('忍', 'rěn', '7', '心', '上下', NULL, '忍 (形声。从心, 刃声。本义 忍耐、 容忍) 同本义 忍,能也。--《说文》 忍,耐也。--《广雅》 是可忍也。--《论语·八脩》。皇疏忍,犹容耐也。” 强力忍垢,吾不知其他也；组词：忍事(以忍耐态度面对各种事情)；忍容(容忍)；忍顺(忍耐顺受；忍耐顺从)；忍从(忍受顺从)；忍羞(忍受羞辱)；忍气(忍受', '小学', '1'),
    ('志', 'zhì', '7', '心', '上下', NULL, '志 (形声。从心,士声。战国文字,从心之,之亦声。意为心愿所往。本义志气,意愿心之所向,未表露出来的长远而大的打算)', '小学', '1'),
    ('忘', 'wàng', '7', '心', '上下', NULL, '忘 (会意兼形声。从心,从亡,亡亦声。本义忘记,不记得) 同本义 忘,不识也。--《说文》 德音不忘。--《诗·郑风·有女同车》 中年病忘。--《列子·周穆王》。释文不记事也；组词：忘魂(忘怀)；忘昏(忘怀)；忘反(流连忘归)；忘年(忘记年岁)；忘味(忘记美食的滋味)；忘食(忘了吃饭)；忘却(不记得)', '小学', '1'),
    ('忙', 'máng', '6', '忄', '左右', NULL, '忙 (形声。从心,亡声。本义急迫,慌忙) 同本义 出门看火伴,火伴皆惊忙。--《木兰诗》；组词：急忙(心里着急,行动加快)；忙丢丢(急急忙忙)；忙不择价(匆忙出卖东西,就卖不到好价钱)；忙迫(仓皇迫促；忙碌紧张)；忙', '小学', '1'),
    ('忠', 'zhōng', '8', '心', '上下', NULL, '忠 (形声。从心,中声。本义忠诚无私,尽心竭力) 同本义 不可谓忠。--《墨子·公输》 忠之属也。(忠,尽力做好本分的事。)--《左传·庄公十年》 为忠善者；组词：忠贞廉士(忠诚坚贞廉洁的人)；忠孝带(清代官员系的一种短而阔的带子,用于保驾或皇帝赐死时自尽)；忠敬(忠诚恭敬) 忠厚', '小学', '1'),
    ('忧', 'yōu', '7', '忄', '左右', NULL, '忧 (被嵋狻P闹杏辛擞浅黼必然在脸上(用页”即人头代表)反映出来◇加攵”(表示行走),形成憂”字。忧”是形声字。本义担忧;发愁)；组词：忧忿滞中(中医 忧(憂)yōu 1.发愁,担心~愁', '小学', '1'),
    ('快', 'kuài', '7', '忄', '左右', NULL, '快〈形〉 (形声。从心,声。本义高兴,痛快) 同本义 快,喜也。--《说文》 文信侯去而不快。--《战国策·秦策》 心不快。--《史记·魏公子列传》 快意留之,非忠臣也；组词：快观(让人看了高兴)；快吾意(使吾意快,符合我的意思) 舒适；舒畅 有一士大夫不快', '小学', '1'),
    ('忱', 'chén', '7', '忄', '左右', NULL, '忱 (形声。从心,冘声。本义诚;诚信;真诚而有信用) 同本义 忱 信任 忱 真诚的心意 忱 chén情意;真诚而有信心热~。 【忱挚】热情而真挚。 忱chén 1.诚信', '小学', '1'),
    ('念', 'niàn', '8', '心', '上下', NULL, '念〈动〉 (形声。从心,今声。本义常思;思念,惦念) 同本义 念,常思也。--《说文》 天念尔祖。--《诗·大雅·文王》 不念昔者。--《诗·邶风·谷风》 不念旧恶；组词：念诵(念叨)；念恤(挂念忧虑)；念旧(不忘故旧)；念思(怀念)；念想(想念)；念一(思念大道)；念恋(思念爱恋) 思考,', '小学', '1'),
    ('忽', 'hū', '8', '心', '上下', NULL, '忽 (形声。从心,勿声。本义不重视;忽略) 同本义 忽,忘也。--《说文》 忽,轻也。--《广雅·释诂三》 奈何而忽。--《汉书·食货志》 忽于小过；组词：疏忽；忽忘(忘记)；忽易(忽略,忽视)；忽睨(傲视)；忽怠(轻慢)；忽慢(轻慢)；忽薄(轻视) 好像 忽 〈副〉 忽然', '小学', '1'),
    ('忿', 'fèn', '8', '心', '上下', NULL, '忿〈动〉 (形声。从心,分声。从心”,表示与心情有关。本义愤怒,怨恨) 同本义 忿,悁也。；组词：忿恨(愤怒怨恨)；忿气(气愤；生气)；忿怒(愤怒)；忿疾(愤怒厌恶) 忿 fèn怒,怨恨,生气~怒', '小学', '1'),
    ('怀', 'huái', '7', '忄', '左右', NULL, '怀 (形声。从心,褱声。本义想念,怀念) 同本义 怀,思念也。--《说文》 嗟我怀人。--《诗·周南·卷耳》 维以不永怀。 有女怀人。--《诗·召南·野有死麕》 惟佳人之独怀兮；组词：怀土(怀恋故乡；安于所处)；怀香(怀念女色；风流)；怀慕(怀念仰慕)；怀乡(思念故乡) 心里存有；怀藏 怀(懷)huái', '小学', '1'),
    ('态', 'tài', '8', '心', '上下', NULL, '态〈名〉 (会意。从心,从能。简体字为形声。从心,太声。本义姿态,姿势与状态) 同本义 慴,意态也。', '小学', '1'),
    ('怎', 'zěn', '9', '心', '上下', NULL, '怎 (形声。从心,乍声。本义怎么,如何) 同本义 怎禁人临去也回头望!--马致远《汉宫秋》；组词：怎生奈何(怎么办)；怎的起(怎么搞的；为什么)；怎禁(怎么受得)；怎个(怎么)；怎说(怎么回事)；怎价(方言', '小学', '1'),
    ('怒', 'nù', '9', '心', '上下', NULL, '怒〈动〉 (形声。从心,奴声。本义发怒,明显地表形于外的生气) 同本义 怒,恚也。--《说文》 怨而不怒。--《国语·周语》 薄言往愬,逢彼之怒。--《诗·邶风·柏舟》 驴不胜怒；组词：怒烘烘(怒哄哄,怒叿叿,怒吽吽', '小学', '1'),
    ('怔', 'zhēng', '8', '忄', '左右', NULL, '怔 (形声。从心,正声。本义惶恐不安的样子) 同本义 军书交驰,羽檄狎至,乃复怔忪如前。--《潜夫论》；组词：怔忡之症(心脏跳动加速、节律不整的病症)；怔忡(惊恐不安；又指患者心脏跳动剧烈的一种症状) 发愣,发呆 那丫鬟倒发了个怔', '小学', '1'),
    ('怕', 'pà', '8', '忄', '左右', NULL, '怕〈动〉 (形声。从心,白声。怕就是怖,怕”是中古的新字。本义畏惧)同本义 怕,怕惧。--《广韵》 鬼神怕嘲咏。--韩愈《双鸟诗》 粉骨碎身浑不怕。--明·于谦《石灰吟》；组词：惧怕(害怕)；害怕(遇到困难、危险等而心中不安或发慌)；怕怯(害怕) 怕 〈语气〉 用在谓语前面或句首,对某一情况进行估', '小学', '1'),
    ('怖', 'bù', '8', '忄', '左右', NULL, '怖 (形声。从心,布声。《说文》作‘悑’”。本义惶恐,惊惧) 同本义 昔者纣为象箸而箕子怖。；组词：恐怖(由于生命受到威胁而引起的恐惧)；怖畏(恐惧)；怖怯(胆小害怕；恐惧)；怖覆(恐怖而反复)；怖肝(戒惧)；怖沮(恐惧', '小学', '1'),
    ('怜', 'lián', '8', '忄', '左右', NULL, '怜 (形声。从心,粦声。本义哀怜,怜悯) 同本义 憐,哀也。从心。粦声。字亦作怜。--《说文》 矜憐抚掩之也。--《尔雅》 独不怜公子姊邪?--《史记·魏公子列传》 若俯首贴耳；组词：可怜(值得怜悯)；怜见(哀矜,怜悯)；怜拯(怜悯拯救)；怜鉴(哀怜审察)；怜闵(哀怜,同情) 爱,惜 憐,爱也', '小学', '1'),
    ('思', 'sī', '9', '心', '上下', NULL, '思 (会意兼形声。从心,从囟,囟亦声。囟脑子。古人认为心脑合作产生思想。本义思考,想;考虑)；组词：多思；前思后想；自思；深思熟虑；思疑(疑惑；疑心)；思郁(思虑薀结)；思鲈(比喻抽身归隐)；思劳(思虑劳累)；思察(思虑', '小学', '1'),
    ('怠', 'dài', '9', '心', '上下', NULL, '怠 (形声。从心,台声。本义懒惰) 同本义 怠,慢也。--《说文》 懈,怠也。--《尔雅》 怠,赖也。--《广雅》 可先而不备,谓之怠。--《国语·周语》 吉事虽止不怠；组词：怠荒(松弛荒废)；怠戏(怠情职责,纵情嬉戏) 疲倦；倦怠 怠 dài 1〈古〉怠慢；不恭敬守卒皆~炎', '小学', '1'),
    ('急', 'jí', '9', '心', '上下', NULL, '急 (形声。小篆字形,从心,及声。本义狭窄) 紧,紧缩 遂生缚布,布曰缚太急,小缓之。--《三国志·吕布传》；组词：急亲戚(最接近的亲戚)；急持(紧紧抱持)；急窄(犹紧缩)；急装(扎缚紧凑的装束)；急绷绷形容把东西拉得很紧 急躁,着急', '小学', '1'),
    ('性', 'xìng', '8', '忄', '左右', NULL, '性 (形声。从心,生声。本义人的本性) 同本义 性,人之阳气性善者也。--《说文》 性,质也。--《广雅》 天命之谓性。--《礼记·中庸》 自诚明谓之性。 不可学,不可事；组词：性根(根性；本性)；性行(人的禀性和行为)；性气(人的个性和脾气)；个性(人的本性；人所具有的正常的感情或理性)；禀性(', '小学', '1'),
    ('怨', 'yuàn', '9', '心', '上下', NULL, '怨 (形声。从心,夗声。本义怨恨;仇恨) 同本义 怨,恚也。--《说文》 曰怨乎。--《论语》。皇疏恨也。” 施行得理,谓之德。反德为怨。--《贾子道术》 不怨人取之；组词：怨怅(怨畅', '小学', '1'),
    ('怪', 'guài', '8', '忄', '左右', NULL, '怪 (形声。从心,圣声。恠曾为怪的俗字。本义奇异;奇怪) 同本义 怪,异也。--《说文》 诡于众而突出曰怪。--《论衡·自纪》 铅松怪石。--《书·禹贡》 苟床之山多怪石', '小学', '1'),
    ('怯', 'qiè', '8', '忄', '左右', NULL, '怯 (形声。从心,去声。《说文》本从犬。本义胆小,畏缩) 同本义 持节不恐谓之勇,反勇为怯。；组词：怯怯乔乔(战战兢兢)；怯壳儿(怯坎儿,怯条子', '小学', '1'),
    ('总', 'zǒng', '9', '心', '上中下', NULL, '总 (形声。从糸,悤声。糸是细丝,细丝常聚合成一束,故从糸。本义聚束;系扎) 同本义 总,聚束也。；组词：总发(指童年,幼年', '小学', '1'),
    ('恃', 'shì', '9', '忄', '左右', NULL, '恃shì依靠,依赖,倚仗有~无恐。~才傲物。', '小学', '1'),
    ('恋', 'liàn', '10', '心', '上下', NULL, '恋 (形声。本义留恋,依依不舍) 同本义 宒,慕也。字亦作戀。--《说文》 有孚恋如思也。--《易·小畜·子夏传》 羁鸟恋旧林,池鱼思故渊。--晋·陶潜《归田园居五首》；组词：贪恋(十分留恋)；眷恋(深切地留念)；依恋(留恋)；恋土(依恋乡土,慕恋故里)；恋主(依恋主人,不忍离去) 思念,怀念', '小学', '1'),
    ('恍', 'huǎng', '9', '忄', '左右', NULL, '恍 (形声。从心,況省声。字本作恥,亦作慌.本义狂的样子) 同本义 恥,狂之貌。--《说文》 恥,狂也。--《广雅·释诂四》 临风恥兮浩歌。--《楚辞·少司命》；组词：恍恍(狂的样子) 昏瞶不明的样子 追恥忽于地底兮', '小学', '1'),
    ('恐', 'kǒng', '10', '心', '上下', NULL, '恐〈动〉 (形声。从心,巩声。本义严重害怕,惊恐) 同本义 恐,惧也。--《说文》 室如县罄,野无青草,何恃而不恐?--《左传·僖公二十六年》 星队木鸣,国人皆恐；组词：恐防(担心,提防)；恐虑(担心)；恐灼(惊恐)；恐怯(畏怯、害怕)；恐畏(畏惧)；恐急(惊慌) 恐吓,使之害怕 恐kǒn', '小学', '1'),
    ('恒', 'héng', '9', '忄', '左右', NULL, '恒 (会意。金文,从心,从月,从二。二”,表示天地。本义永久,永恒) 同本义 恒,常也。--《说文》 恒者,久也。--《易·序卦传》 恒,德之固也。--《易·系辞下传》 无恒安处；组词：恒牙(恒齿', '小学', '1'),
    ('恕', 'shù', '10', '心', '上下', NULL, '恕 (形声。从心,如声。本义恕道,体谅) 同本义 恕,仁也。--《说文》 彊恕而行,求仁莫近焉。--《孟子》 以心度物曰恕。--《声类》 以己量人谓之恕。--《贾子道术》 恕；组词：恕直(宽仁正直)；恕心(仁爱之心)；恕实(忠实,老实)；恕道(宽仁之道) 恕 饶恕,宽恕 老臣病足,曾不能疾走,不得 恕', '小学', '1'),
    ('恢', 'huī', '9', '忄', '左右', NULL, '恢 (形声。从心,灰声。本义志气大;大;广大) 同本义 恢,大也。--《说文》 不恢于夏家。--《左传·襄公四年》 恢郭也。--《公羊传·文公十五年》 配稷契兮恢唐功；组词：恢伟(壮伟,魁伟)；恢奇(雄伟杰出的样子)；恢台(广大的样子)；恢卓(宽大,高明)；恢恢(宽大广阔的样子)；恢郭(宽大的', '小学', '1'),
    ('恤', 'xù', '9', '忄', '左右', NULL, '恤 (形声。从心,血声。本义忧虑) 同本义 恤,忧也。--《说文》 勿恤其孚。--《易·泰》 不印自恤。--《书·大诰》 告而忧恤。--《诗·大雅·桑柔》 不恤国事；组词：恤功(担忧民众的事务)；恤恤(忧虑的样子)；恤民(忧虑人民的疾苦) 体恤 朝廷竟无恤赠之典', '小学', '1'),
    ('恨', 'hèn', '9', '忄', '左右', NULL, '恨〈动〉 (形声。从心,艮声。本义怀恨在心,怨恨) 同本义 恨,怨也。--《说文》 今财亡民罢,莫不怨恨。--《国语·周语下》 役夫敢申恨。--唐·杜甫《兵车行》 恨贯肌骨；组词：恨命(恨恨地；拼命)；恨恨(气 忿的样子)；恨穷发极(愤恨到极点而发怒)；恨五骂六(投骰子时的叫骂声)；恨如头醋(比喻非', '小学', '1'),
    ('恩', 'ēn', '10', '心', '上下', NULL, '恩 (形声。从心,因声。本义恩惠) 同本义 恩,惠也。--《说文》 恩者,仁也。--《礼记·丧服四制》 如此,则上下之恩结矣。--《韩非子·用人》 夫人有恩而背之,不祥莫大焉；组词：忘恩；报恩；恩润(恩惠德泽)；恩义(恩情与道义)；恩分(恩惠情分)；恩惠教化', '小学', '1'),
    ('恬', 'tián', '9', '忄', '左右', NULL, '恬〈形〉 (形声。从心,甜省声。本义安静) 同本义 (表示心境的安静,平静) 恬,安也。--《说文系传》 恬,静也。--《广雅》 恬淡寡欲。--曹丕《与吴质书》 恬然自安；组词：恬波(水面平静无波', '小学', '1'),
    ('恭', 'gōng', '10', '小', '上下', NULL, '恭 (形声。从心,共声。本义恭敬,谦逊有礼) 同本义 密人不恭,敢距大邦。--《诗·大雅·皇矣》 恭,敬也。--《尔雅》 何胤云,在貌为恭,在心为敬,何之所说,从多举也；组词：恭默(谦恭沈静不语)；恭倨(恭敬和傲慢)；恭恪(心存恭敬而态度谨慎)；恭敬(犹尊敬)；恭和(谦恭温和)；恭逢其盛(亲身经', '小学', '1'),
    ('息', 'xī', '10', '心', '上下', NULL, '息 (会意兼形声。从心,从自,自亦声。自,鼻子。古人以为气是从心里通过鼻子呼吸的。本义喘气;呼吸)；组词：喘息(急促呼吸)；息息(呼吸；气息出入)；息窒(窒息,呼吸困难)；息响(呼吸的声音)；息贲(中医病名', '小学', '1'),
    ('恰', 'qià', '9', '忄', '左右', NULL, '恰〈副〉 (形声。从心,合声。本义用心) 同本义 恰,用心也。--《说文新附》 又如恰恰(用心的样子) 才,刚刚 岂;难道 恰 〈形〉 适当;正好 恰是湘妃泪尽时；组词：恰恰(用心的样子) 才,刚刚 岂；难道 恰 〈形〉 适当；正好 恰是湘妃泪尽时', '小学', '1'),
    ('恳', 'kěn', '10', '心', '上下', NULL, '恳 (形声。从心,声。本义诚恳,真诚)同本义 恳,信也。--《广雅·释诂一》 至诚曰恳。--《一切经音义》四引《通俗文》 意气勤勤恳恳。--《汉书·司马迁传》。师古曰恳恳,至诚也；组词：恳悃(真心诚意)；恳款(殷切诚恳)；恳曲(诚恳委婉)；恳言(诚挚之言)；恳直(诚挚切直) 恳 请求,表露愿望和要求 恳恩', '小学', '1'),
    ('恶', 'è', '10', '心', '上下', NULL, '恶 (形声。从心,亚声。本义过失) 同本义 恶,过也。--《说文》 恶上安西。--《颜氏家训》 吾以志前恶。--《左传·定公五年》 君子之遏恶扬善。--《易·象传》；组词：恶恶从短(对于人的过失,不十分苛责,适可而止) 泛指一般罪恶 恶积祸盈', '小学', '1'),
    ('恼', 'nǎo', '9', '忄', '左右', NULL, '恼 (形声。从心,惱声。本义恼恨;生气;发怒) 同本义 任汝恼弟示,任汝恼姨舅。--唐·卢仝《寄男抱孙》 他呆子着了恼的人,张开嘴...被行者轻轻的提将出来。；组词：恼聒(烦恼,恼恨)；恼懆(烦恼忧愁)；恼燥,恼躁(烦恼不安)；恼悔(悔恨)；恼闷(懊恼烦闷)；恼烦(烦恼)；恼懊(懊恼)', '小学', '1'),
    ('悄', 'qiāo', '10', '忄', '左右', NULL, '悄悄 悄悄离开 他悄悄地全跟我说了 悄悄话 开会不准说悄悄话 悄〈形〉 (形声。从心,肖声。本义忧愁的样子)；组词：悄切(形容声音忧愁凄切)；悄怆(哀伤,忧伤)；悄悄(忧愁的样子)；悄悒(因思念而忧郁)；悄戚(悲痛忧伤) 寂静无声 悄q', '小学', '1'),
    ('悉', 'xī', '11', '心', '上下', NULL, '悉 (会意。从心,从采。采,辨别。心中加以辨别,很详细。本义详尽) 同本义 悉,详尽也。--《说文》 悉,尽也。--《尔雅》 占不悉。--《史记·平准书》。索隐尽也；组词：纤悉(详细；详尽)；详悉(详细而全面)；悉数(一一列举) 悉 悉如外人', '小学', '1'),
    ('悍', 'hàn', '10', '忄', '左右', NULL, '悍 (形声。从手,旱声。本义勇猛) 同本义 悍,勇也。--《说文》 悍戇好斗。--《荀子·大略》 虽有悍如冯敬者。--《汉书·贾谊传》 且其人剽悍；组词：悍酋(勇猛的首领)；悍夫(勇士)；悍志(勇猛之气)；悍壮(勇武强壮) 凶狠,蛮横 悍吏之来吾乡', '小学', '1'),
    ('悔', 'huǐ', '10', '忄', '左右', NULL, '悔 (形声。从心,每声。本义悔恨,懊悔) 同本义 悔,恨也。--《说文》 宜无悔怒。--《诗·大雅·云汉》 此讲之悔也。--《战国策·秦策》 悔不杀汤于夏台；组词：悔亲(因反悔而废弃婚约)；悔谢(悔过请罪)；悔心革命(痛改前非)；悔悟心行(反省 悔huǐ 1.做错事后埋怨、懊恼或怨恨', '小学', '1'),
    ('悟', 'wù', '10', '忄', '左右', NULL, '悟 (形声,从心,吾声。本义理解,明白) 同本义 悟,觉也。--《说文》 悟彼蟋蟀唱。--《文选·谢混游西池诗》 慧然独悟。--《素问·八正神明论》 未悟见出,意不自得；组词：觉悟(由迷惑而明白；由凝而认清)；悟心(悟性', '小学', '1'),
    ('悠', 'yōu', '11', '心', '上下', NULL, '悠 (形声。从心,攸声。本义忧思) 同本义 悠,忧也。--《说文》 悠,思也。--《尔雅》 悠悠我里。--《诗·小雅·十月之交》。注忧也。” 悠悠苍天兮；组词：悠然(忧伤的样子)；悠忧(忧伤) 亿 做事从容不迫 听安老爷这等说,便道喂! 悠yōu 1.长远,长久~远', '小学', '1'),
    ('患', 'huàn', '11', '心', '上下', NULL, '患 (形声。从心,串”即毌”(贯)字。本义担忧,忧虑 同本义 患,忧也。--《说文》 不患人之不已知,患其不能也。--《论语·宪问》 书文止于一者谓之忠,持二中者谓之患,患人之忠；组词：患累(忧患)；患御(害怕服兵役)；患忧(忧患)；患失(生怕失去) 憎恶；讨厌；厌烦 患,恶也', '小学', '1'),
    ('悦', 'yuè', '10', '忄', '左右', NULL, '悦 (形声。从心,说省声。本作说”。本义高兴,愉快) 同本义 悦,犹说也,拭也,解脱也。若人心有郁结能解释之也。；组词：悦心(愉悦心情)；悦情(欢乐之情)；悦笑(欢乐笑谑)；悦喜(喜悦)；悦畅(和畅,欢畅)；悦乐(快乐)；悦泽(光润悦目)', '小学', '1'),
    ('您', 'ní', '11', '心', '上下', NULL, '您〈代〉 (会意。从你,从心。表示尊重。本义你”的尊称) 同本义 注意用于多数时不加词尾们”,两个人称您俩”或您二位”,三个人称您仨”或您三位”,三个人以上称您诸位”', '小学', '1'),
    ('悬', 'xuán', '11', '心', '上下', NULL, '悬 (形声。从心,县声。本作县”,象断首倒挂,后加系”。假借为行政区域的县”后,另加心”字表示悬挂。本义吊挂)；组词：悬丝诊脉(传说古代中医诊脉法之一', '小学', '1'),
    ('悯', 'mǐn', '10', '忄', '左右', NULL, '悯 (形声。从心,闵声。本义怜恤) 同本义 隋堤柳,悯亡国也。--白居易《新乐府序》 人远悲天悯人之怀,岂为一己之不遇乎?--清·黄宗羲《朱人远墓志铭》；组词：悯人之凶(原谅、可怜凶恶之人', '小学', '1'),
    ('悲', 'bēi', '12', '忄', '上下', NULL, '悲 (形声。从心,非声。本义哀伤;痛心) 同本义 悲,痛也。--《说文》 悲,伤也。--《广雅》 忧心且悲。--《诗·小雅·鼓钟》 我心伤悲。--《诗·召南·草虫》 并于肺则悲；组词：悲怆(悲伤)；悲怨(悲痛怨恨)；悲惋(悲伤惋惜)；悲吟(悲伤哀叹)；悲忧(悲 悲 bēi 1哀伤~哀、~喜交集', '小学', '1'),
    ('悴', 'cuì', '11', '忄', '左右', NULL, '悴 (形声。从心,卒声。本义忧愁,悲伤) 同本义 人力雕残,百姓愁悴。--《晋书·凉武昭王李玄盛传》；组词：悴民(指忧时而不得志的人)；悴沮(忧伤沮丧) 憔悴；枯萎 屈原...颜色憔悴,形容枯槁', '小学', '1'),
    ('悼', 'dào', '11', '忄', '左右', NULL, '悼 (形声。从心,卓声。本义恐惧) 同本义 悼,惧也。陈楚谓惧曰悼。--《说文》 隐悼播越。--《国语·晋语》 恐惧从处曰悼。--《周书·谥法》 怵悼栗而耸兢；组词：悼栗(因惊恐而战栗)；悼慑(害怕) 悲痛；哀伤 悼,哀也', '小学', '1'),
    ('情', 'qíng', '11', '忄', '左右', NULL, '情〈名〉 (形声。从心,青声。本义感情) 同本义 情,人之阴气有欲者也。--《说文》 何谓人情?喜怒哀惧爱恶欲七者,弗学击能。--《礼记·礼运》又 人情者,圣王之田也。 情伪相感；组词：情熟(亲密)；情款(情意诚挚融洽)；情悃(情意；感情真挚,诚心诚意)；情 情qíng 1.喜、怒、哀、乐等心理状况~绪', '小学', '1'),
    ('惊', 'jīng', '11', '忄', '左右', NULL, '惊 (形声。从马,敬声。本义马受惊) 同本义 驚,马骇也。--《说文》 襄子至桥而马惊。--《战国策·赵策一》；组词：惊嘶(马受惊而嘶叫)；惊尘(车马疾驶所扬起的尘土)；惊镳(惊马) 惊动；震惊 宫庭震惊', '小学', '1'),
    ('惋', 'wǎn', '11', '忄', '左右', NULL, '惋 (形声。从心,宛声。本义怨恨,叹惜) 同本义 守穷者贫贱,惋叹泪如雨。--曹操《善哉行》 皆叹惋。--晋·陶渊明《桃花源记》 惋 中医学术语。内热 夫志悲者惋,惋则冲阴。', '小学', '1'),
    ('惑', 'huò', '12', '心', '上下', NULL, '惑 (形声。从心,惑声。本义疑惑,分辨不清) 同本义 内惑于郑袖。--《史记·屈原贾生列传》 为奴婢所惑。--唐·李朝威《柳毅传》；组词：惑眩(迷乱；混乱)；惑疾(迷乱之病)；惑变(迷乱变化)；惑易(精神失常)；惑志(疑心)；惑误 (使人疑而误之) 迷惑,使', '小学', '1'),
    ('惕', 'tì', '11', '忄', '左右', NULL, '惕〈动〉 (形声。从心,易声。本义害怕,放心不下) 同本义 惕,惧也。--《玉篇》 惕,敬也。--《说文》 夕惕若厉。--《易·乾》。郑注惧也。” 岂不使诸侯之心惕惕焉；组词：惕息(忧心戒惧,不敢喘息', '小学', '1'),
    ('惜', 'xī', '11', '忄', '左右', NULL, '惜 (形声。从心,昔声。本义哀痛,哀伤) 同本义 惜,痛也。--《说文》 惜者,哀也。--《楚辞·惜誓序》 为陛下惜之。-- 汉·贾谊《论积贮疏》 惜其用武不终；组词：可惜(值得惋惜)；痛惜(沉痛地惋惜)；惜伤(哀伤) 珍惜,爱惜,重视而不糟棠费 为天下惜死', '小学', '1'),
    ('惠', 'huì', '12', '心', NULL, NULL, '惠 (会意。从心,从叀。本义仁爱) 同本义 惠,仁也。--《说文》 爱民好与曰惠。柔质慈民曰惠。--《周书·谥法》 分人以财谓之惠。--《孟子》 心省恤人谓之惠；组词：惠声(仁爱而有德泽的美名)；惠育(用仁心爱德加以养育)；惠化(仁爱的教化)；惠心(仁慈的心) 柔顺；顺从 义征不惠', '小学', '1'),
    ('惦', 'diàn', '11', '忄', '左右', NULL, '惦 (形声。从心,店声。本义惦记,挂念) 同本义 惦 diàn记挂;挂念。 【惦记】心里记挂着。', '小学', '1'),
    ('惧', 'jù', '11', '忄', '左右', NULL, '惧 (形声。从心,瞿声。本义害怕,恐惧) 同本义 惧,恐也。--《说文》 是以举天下之人,皆恐惧振动惕栗,不敢为淫暴。--《墨子·尚同中》 楚兵惧,自秦归；组词：惧思(因恐惧而慎重考虑)；惧选(害怕获罪)；惧高症(心理学名词', '小学', '1'),
    ('惨', 'cǎn', '11', '忄', '左右', NULL, '惨 (形声。从心,参声。本义残酷,狠毒) 同本义 惨,毒也。--《说文》 惨毒行于民。--《汉书·陈汤传》 苛惨失中。--《后汉书·周纺传》。注虐也。” 惨如蜂虿；组词：惨虐(残酷暴虐)；惨无人理(惨无人道) 悲痛；伤心 惨于腹', '小学', '1'),
    ('惩', 'chéng', '12', '心', '上下', NULL, '惩 (形声。从心,征声。本义警戒;鉴戒) 同本义 惩,戒也。--《玉篇》 惩,恐也。--《广雅》 则民有所惩。--《礼记·表记》 不惩其心。--《诗·小雅·节南山》；组词：惩毖(受创于前,当戒慎于后)；惩纠(告戒督察)；惩示(警告) 处罚 惩恶而劝善', '小学', '1'),
    ('惫', 'bèi', '12', '心', '上下', NULL, '惫 (形声。从心,備声。本义疲乏,困顿) 同本义 疲极曰惫。--《通俗文》 单惫于戏笑。--《列子·黄帝》 往来惛惫,通于大神；组词：疲惫(非常疲乏)；惫喘(疲惫而喘息)；惫劳(疲劳) 衰竭；危殆 惫懒 这个贾宝玉,不知是怎生个惫懒人物', '小学', '1'),
    ('惭', 'cán', '11', '忄', '左右', NULL, '惭 (形声。从心,斩声。本义羞愧)同本义 憀,媿也。--《说文》 不直失节谓之憀。--《小尔雅》 富者有惭色。--清·彭端淑《为学一首示子侄》 羊子大惭；组词：大言不惭；惭叹(惭愧感叹) 惭 cán 亦作"憀"', '小学', '1'),
    ('惯', 'guàn', '11', '忄', '左右', NULL, '惯 (形声。从心,贯声。本义习惯,惯常) 同本义 惯,习也。--《尔雅》 譬如田猎,射御惯,则能获禽。--《左传·襄公三十一年》 谓客曰宗军人,惯啖粗食；组词：惯熟(因经常做某事而动作熟练；因经常见面而熟悉习惯)；惯历(惯常经过,不止一次经过)；惯经(习惯,惯常所经历的)；惯有(', '小学', '1'),
    ('惰', 'duò', '12', '忄', '左右', NULL, '惰 (形声。从心,隋省声。本义不恭敬) 同本义 惰,不敬也。--《说文》 滕成公来会葬,惰而多涕。--《左传·襄公三十一年》 今者治平日久,天下之人骄惰脆弱；组词：惰傲(怠慢)；惰慢(懈怠不敬；懈怠涣散)；惰肆(怠慢放肆)；惰骄(骄傲懈怠)；惰偷(懈怠苟且,懒惰) 懈怠；懒惰 惰,懒', '小学', '1'),
    ('想', 'xiǎng', '13', '心', '上下', NULL, '想 (形声。心形相声。本义想念;怀念;羡慕) 同本义 想,冀思也。--《说文》 览物想故国。--杜甫《客居》 遥想公瑾当年,小乔初嫁了,雄姿英发。--苏轼《念奴娇》；组词：想似(深切的怀念)；想思(想念) 思考,思索 入景响之无应兮,闻省想而不可得', '小学', '1'),
    ('惶', 'huáng', '12', '忄', '左右', NULL, '惶 (形声。从心,皇声。本义恐惧,惊慌) 同本义 惶,惶恐也。--《说文》 惶,惧也。--《广雅》 秦王方环柱走,卒惶急,不知所为。--《史记·刺客列传》 孟贲狎猛虎而不惶；组词：惶惶(惊恐不安)；遑迫(惊慌)；惶汗(惊惧而汗流)；惶沮(恐惧沮丧)；惶怖(恐惧害怕) 惶huáng恐惧,惊慌~惑', '小学', '1'),
    ('惹', 'rě', '12', '心', '上下', NULL, '惹 (形声。从心,若声。本义招引) 同本义 春风不为吹愁去,春日偏能惹恨长。--何逊《九日侍宴乐游苑》；组词：惹口面(惹麻烦)；惹邪(魅人)；惹起(引起)；惹口舌(引起口角是非) 触犯；触动 引起 到处顽耍,惹的乡下孩子们三五成群', '小学', '1'),
    ('愁', 'chóu', '13', '心', '上下', NULL, '愁 (形声。从心,秋声。字亦作愀”。本义忧虑,发愁) 同本义 愁,忧也。--《说文》 孔子愀然作色而对。--《礼记·哀公问》 见善愀然。--《荀子·脩身》 哀而不愁,乐而不荒；组词：不愁吃,不愁穿；愁坐(含忧默坐)；愁思(忧愁的心绪)；愁绝(忧愁到极点)；愁怀勃勃(心中有万端愁绪；非常忧戚 愁 chó', '小学', '1'),
    ('愈', 'yù', '13', '心', '上下', NULL, '愈 (形声。从心,俞声。本义病好了。这个意义后来又写作瘉”、発”) 同本义 瘉,病瘳也。--《说文》 幸上病瘉。--《汉书·卢绾传》 至日中间差瘉。--《汉书·李寻传》 周王病瘉；组词：愈合(伤口长好) 愈 胜过 一暴之功,犹愈于十日之寒也', '小学', '1'),
    ('愉', 'yú', '12', '忄', '左右', NULL, '愉〈形〉 (形声。从心,俞声。本义和悦,快乐) 同本义 愉,乐也。--《说文》 愉,喜也;说也。--《广雅》 他人是愉。--《诗·唐风·山有枢》 其进之也,敬之愉；组词：愉怡(快乐和悦)；愉心(愉悦心情)；愉目(悦目)；愉色(和悦的神色) 愉yú喜悦,快乐~快', '小学', '1'),
    ('意', 'yì', '13', '心', '上下', NULL, '意 (会意。从心从音。本义心志。心意) 同本义 意,志也。--《说文》 心之所谓意。--《春秋繁露·循天之道》 今者项庄拔剑舞,其意常在沛公也。--《史记·项羽本纪》 通其意；组词：文章大意；词不达意', '小学', '1'),
    ('愕', 'è', '12', '忄', '左右', NULL, '愕 (形声。从心,咢声。本义惊讶) 同本义 愕,然欲殴之。--《汉书·张良传》 犹愕眙而不能阶。--班固《西都赋》 成骇立愕呼。--《聊斋志异·促织》 又 成益愕,急逐趁之；组词：愕怪(惊奇)；愕窒(惊惶得不敢出气)；愕梦(惊愕而梦) 直言 愕愕者不以天下为忧', '小学', '1'),
    ('愚', 'yú', '13', '心', '上下', NULL, '愚 (会意。从心,从禺。从心,与性情有关。禺,猴属,兽之愚者。本义愚蠢,愚昧) 同本义 愚,戆也。；组词：愚若胶柱(胶住调节乐弦的柱再去弹奏,只能弹出单一无变化的音调', '小学', '1'),
    ('感', 'gǎn', '13', '心', '上下', NULL, '感〈动〉 (形声。从心,咸声。本义感动) 同本义。思想感情受外界事物的影响而激动 感,动人心也。；组词：感格(感动,感化)；感咽(受感动而悲伤,泣不成声)；感涕(感动而涕泪俱下)；感慕(感动而思慕)；感悦(感动悦服)；感人肺', '小学', '1'),
    ('愤', 'fèn', '12', '忄', '左右', NULL, '愤 (形声。从心,贲声。从心”,表示与心情等有关。本义郁结于心;憋闷) 同本义 愤,懑也。；组词：愤切(内心极度愤懑)；愤悁(愤懑郁积)；愤薄(郁结,充塞)；愤厥(由于愤气郁结造成的痉挛昏厥) 充盈,旺盛 愤,盈也', '小学', '1'),
    ('愧', 'kuì', '12', '忄', '左右', NULL, '愧〈动〉 (形声。从心,鬼声。本义惭愧) 同本义。同媿” 小则如愧。--《礼记·儒行》 尚不愧于屋漏。--《诗·大雅·抑》 不愧于人。--《诗·小雅·何人斯》 虽颜惭未知心愧；组词：愧心( 愧(媿)kuì羞惭,心里觉得对不起~对', '小学', '1'),
    ('愿', 'yuàn', '14', '心', NULL, NULL, '愿〈形〉 (形声。从页,原声。古时愿、願”各有本义。愿”义为谨慎,願”义为大头”) 谨慎;老实,质朴 愿,谨也。；组词：愿恭(恭谨)；愿款(诚挚)；愿法(执法恭谨)；愿敏(朴实敏悟)；愿婉(朴实恭顺)；愿懿(朴实诚实)；愿民(朴实善良之民)', '小学', '1'),
    ('慈', 'cí', '13', '心', '上下', NULL, '慈 (形声。从心,兹声。本义慈爱) 同本义 慈,爱也。--《说文》 尧不慈舜不孝。--《庄子·盗跖》 夫慈者不忍,而惠者好与也。--《韩非子·内储说上》 一曰慈幼', '小学', '1'),
    ('慌', 'huāng', '12', '忄', '左右', NULL, '慌〈形〉 (形声。从心,荒声。本义急忙,忙乱) 同本义 怎这样慌?五日内我还便罢了!--明·梦觉道人《三刻拍案惊奇》 偏偏我们走的慌,未带银子。；组词：走得太慌；慌不择路(慌里慌张,顾不上选择道路)；慌慌速速(匆忙,慌张)；慌速(慌张急促) 慌 散亡 仆夫慌悴,散若流兮', '小学', '1'),
    ('慎', 'shèn', '13', '忄', '左右', NULL, '慎 (形声。从心,真声。本义谨慎;慎重) 同本义 慎,谨也。--《说文》 慎,诚也。--《尔雅》 慎,德之守也。--《国语·周语》 僶勉就善谓之慎。--《贾子道术》 慎尔优游；组词：审慎(周密而谨慎)；失慎(疏忽)；慎独(个人闲居独处时,也要小心谨慎,不可有越礼非分的念头)；慎shèn持重,小心谨~', '小学', '1'),
    ('慕', 'mù', '14', '小', '上下', NULL, '慕 (形声。从心,莫声。本义依恋;向往) 同本义 慕,习也。--《说文》。按,思也。 其往也如慕。--《礼记·檀弓》 巨室之所慕。--《孟子·万章》 人少,则慕父母。；组词：慕义(向往正义)；慕向(思慕向往)；慕企(企慕,仰慕)；慕位(思慕权位)；慕尚(向往推崇)；慕思(向往；仰慕思念) 仰慕', '小学', '1'),
    ('慢', 'màn', '14', '忄', '左右', NULL, '慢 (形声。从心,曼声。本义轻慢;对人无礼貌) 同本义 慢,一曰不畏也。--《说文》 慢,惰也。--《广雅》 我远而慢之。--《左传·襄公三十一年》 可敬不可慢；组词：慢骂(信口乱骂)；慢亵(慢待；招待不周)；慢狎(轻侮)；慢视( 慢màn 1.迟缓,跟"快"相对缓~', '小学', '1'),
    ('慧', 'huì', '15', '心', '上下', NULL, '慧 (形声。从心,彗声。本义聪明,有才智) 同本义 慧,儇也。--《说文》 知或谓之慧。--《方言》三 注慧,儇,皆意精明。” 亟见窕察谓之慧。--《贾子道术》 柔质受谏曰慧；组词：慧侠(有才华,有胆略)；慧给(聪敏而有口才)；慧种(优良的天赋秉性)；慧黠(聪敏机智)；慧美(聪明美丽) 狡黠 身冷若冰', '小学', '1'),
    ('慨', 'kǎi', '12', '忄', '左右', NULL, '慨〈形〉 (形声。从心,既声。本义不得志而愤激) 同本义 慨,忼慨壮士不得志也。--《说文》 副将军史德威慨然任之。--清·全祖望《梅花岭记》；组词：愤慨；慨切(愤激而恳切)；慨爽(慷慨爽朗)；慨慷(情绪激昂) 疲惫的样子 慨焉如不及,其反而息', '小学', '1'),
    ('慰', 'wèi', '15', '心', '上下', NULL, '慰 (形声。从心,尉声。本义安慰) 同本义 慰,安也。--《说文》 有子七人,莫慰母心。--《诗·邶风·凯风》 以慰长想。--宋·沈括《梦溪笔谈·活板》 慰留不允；组词：慰眼(观赏,饱眼福)；劝慰(劝解安慰)；自慰(自己安慰自己)；抚慰(安慰)；慰存(安抚慰问)；慰唁(安慰勉励)；慰喭(对', '小学', '1'),
    ('慷', 'kāng', '14', '忄', '左右', NULL, '慷 (形声。从心,康声。本义情绪激昂) 同本义 慨当以慷,忧思难忘。--曹操《短歌行》 又如慷惋(愤激怨恨);慷忾(慷慨。意气高昂);慷慨赴死(意气激昂,不畏死难)；组词：慷惋(愤激怨恨)；慷忾(慷慨', '小学', '1'),
    ('憋', 'biē', '15', '心', '上下', NULL, '憋 (形声。从心,敝声。本义性急) 同本义 憋,曰性急。--《集韵》 又如憋懯(亦作憋恘”。急性);憋肠(急性子);憋古(性格暴烈、古怪、不合时宜) 凶恶 执拗 憋 憋闷；组词：憋懯(亦作憋恘”', '小学', '1'),
    ('憎', 'zēng', '15', '忄', '左右', NULL, '憎 (形声。从心,曾声。本义憎恨厌恶) 同本义 憎,恶也。--《说文》 憎而知其善。--《礼记·曲礼》 盗憎主人。--《国语·晋语》 秦甚憎齐。--《史记·屈原贾生列传》；组词：憎人(可憎恶的人)；憎妒(憎恨妒忌)；憎命(憎恶命运)；憎毒(憎恨痛恨)；憎恨(厌恶怨恨)；憎毁(憎恶诋毁)；憎爱(憎恨', '小学', '1'),
    ('憔', 'qiáo', '15', '忄', '左右', NULL, '憔 (会意。从心,焦声。本义憔悴,瘦弱萎靡的样子。也泛指折磨困苦) 同本义 顦,面焦枯小也。从面焦,焦亦声。；组词：憔瘁(黄瘦,瘦损) 憔(顦)qiáo 1脸色黄瘦面容~悴', '小学', '1'),
    ('憨', 'hān', '15', '心', '上下', NULL, '戆〈形〉 (形声。从心,敢声。《说文》作戆”。本义痴呆,傻气) 同本义 狂惑戆陋之人。--《荀子·儒效》。按,字亦作憨”。；组词：憨虫(傻瓜)；憨子(傻子)；憨砖(笨蛋；傻瓜)；憨哥(傻小子)；憨头狼(傻小子) 娇痴 顽皮 朴实 憨厚 憨乎乎 憨hā', '小学', '1'),
    ('憾', 'hàn', '16', '忄', '左右', NULL, '憾 (形声。从心,感声。本义遗憾,不快,不满) 同本义(先秦古书一般用憾”,汉代以后多用恨”) 憾,恨也。；组词：憾悔(悔恨)；憾惜(遗憾惋惜)；憾轲 憾hàn悔恨,惋惜,失望~事一桩', '小学', '1'),
    ('懂', 'dǒng', '15', '忄', '左右', NULL, '懂 (形声。从心,董声。本义明白,了解) 同本义 懂 dǒng了解;明白。', '小学', '1'),
    ('懈', 'xiè', '16', '忄', '左右', NULL, '懈 (形声。从心,解声。本义松懈) 同本义 懈,怠也。--《说文》 夙夜匪懈。--《孝经》 为民兴利除害而不懈。--《淮南子》 然侍卫之臣不懈于内；组词：懈懈(怠惰；懒散)；懈厥操觚(怠慢从事)；懈忒(懈怠失误)；懈沮(懈怠沮丧)；懈意(懈怠之心) 疲困；松散 懈xiè松弛', '小学', '1'),
    ('懊', 'ào', '15', '忄', '左右', NULL, '懊〈形〉 (形声。从心,奥声。本义失悔,认识到错了而烦恼) 同本义 门生惊懊者累日。--《晋书·王羲之传》 垂头视之,如有懊丧竟。--《世说新语·言语》 懊yù 1.通"噢"', '小学', '1'),
    ('懒', 'lǎn', '16', '忄', '左右', NULL, '懒 (形声。从心,赖声。本义懒惰) 同本义 懒,懈也。怠也。一曰卧也。--《说文》。字亦作懒。 吾少懒学问,晚成人。--《宋书·范晔传》；组词：懒待(没有精神和兴致)；懒怠(懒于做某种事)；懒得(不想,不情愿)；懒残和尚煨芋(唐衡狱寺和尚明瓒禅师,性子懒惰,常吃别', '小学', '1'),
    ('懦', 'nuò', '17', '忄', '左右', NULL, '懦〈形〉 (形声。从心,需声。本义胆小,含有软弱之意;弱) 同本义 懦,驽弱者也。--《说文》 少懦于诸侯。--《国语·晋语》 而性懦愚,沉于国家大事,开罪于先生；组词：懦小(懦弱胆小)；懦弛(软弱懈怠)；懦退(软弱畏缩)；懦恧(软弱)；懦软(软弱)；懦庸(软弱庸陋)；懦谨(胆小谨慎)；懦', '小学', '1'),
    ('戈', 'gē', '4', '戈', NULL, NULL, '戈〈名〉 (象形。甲骨文字形,象一种长柄兵器形。本义一种兵器) 中国古代的主要兵器 戈,平头戟也。从弋、一,横之象形。', '小学', '1'),
    ('戏', 'xì', '6', '戈', '左右', NULL, '戏 (形声。从戈。虚声。本义一种兵器) 同本义 假借为麾”。军队中的帅旗 兵罢戏。--《史记·高帝纪》。正义大旗也。” 戏下骑从者八百余人。--《汉书·项籍传》。注大将之旗；组词：戏场(表演歌舞杂技的场子)；散戏；猴戏；游戏；排戏；配戏(配合主角演戏)；扮戏 戏剧 那明湖居本是个大戏园子,戏台 戏(', '小学', '1'),
    ('成', 'chéng', '6', '戈', '左右', NULL, '成 (会意。甲骨文字形,从|”(即杵”)。斧”、杵”具备就可以做成事情。本义完成,成就)；组词：落成(建筑物完工) 变成；成为 累寸不已,遂成丈匹', '小学', '1'),
    ('我', 'wǒ', '7', '戈', '左右', NULL, '我 (会意。从戈,从戈。我”表示兵器。甲骨文字形象兵器形。本义兵器。基本义第一人称代词) 自称;自己 我,施身自谓也。；组词：我行(我这里)；我身(我自己；我这个人)；我咱(我自', '小学', '1'),
    ('戒', 'jiè', '7', '戈', '半包围', NULL, '戒 (会意。小篆字形,上面是戈”,下面象两只手(即廾”)。两手持戈,表示戒备森严。本义警戒,戒备)；组词：戒慎(戒备谨慎)；戒书(用来自我警戒的文字)；戒旦(警告天将破晓)；戒守(警戒守卫)；戒命(禁止某些行为的命 戒jiè', '小学', '1'),
    ('或', 'huò', '8', '戈', '半包围', NULL, '或 (会意。甲骨文字形从囗(象城形),从戈(以戈守之)。表示以戈卫国。本义国家。有人,有的--泛指人或事物 或,有也。；组词：或人(某人', '小学', '1'),
    ('战', 'zhàn', '9', '戈', '左右', NULL, '战 (形声。从戈,单(占)声。本义作战,打仗) 同本义 战,斗也。--《说文》 皆陈曰战。--《左传·庄公十一年》 春秋敌者言战。--《公羊传·庄公三十年》 忠之属也,可以一战；组词：征战(出征作战)；战阀(战功)；战垒( 战(戰)zhàn 1.打仗~争', '小学', '1'),
    ('戚', 'qī', '11', '戈', '半包围', NULL, '戚〈名〉 (形声。从戉,尗声。斧子。本义古兵器名,斧的一种) 同本义。亦用为舞具 戚,戉也。；组词：戚扬(斧钺) 亲属,亲戚 何谓六戚?父母兄弟妻子', '小学', '1'),
    ('截', 'jié', '14', '戈', NULL, NULL, '截 (形声。从戈,雀声。本义断绝,切断) 同本义 巀,断也。--《说文》 截彼淮浦,王师之所。--《诗·大雅·常武》。笺就王师而断之。” 海外有截。--《诗·商颂·长发》。笺截；组词：截头(尽头)；截替(取代)；截齐(齐截)；截发留宾(截发剉荐', '小学', '1'),
    ('戳', 'chuō', '18', '戈', '左右', NULL, '戳 (形声。从戈,翟声。本义用锐器的尖端刺击) 同本义 戳,枪戳也。--《篇海类篇》 众强盗拚命死战,戳伤了几个庄客。--《醒世恒言》；组词：戳伤；戳舌(搬弄是非,挑拨)；戳弄(摆布,捉弄)；戳背脊(背后指责讥笑)；戳纱(一种特殊的刺绣品)；戳锅漏(方言', '小学', '1'),
    ('戴', 'dài', '17', '戈', NULL, NULL, '戴 (形声。本义增益) 同本义 分物得增益曰戴。--《说文》。段玉裁注引申之凡加于上皆曰戴。” 古国名。故址在今河南省民权县东 宋人、蔡人、卫人伐戴。--《春秋》 戴 加在头、颈', '小学', '1'),
    ('户', 'hù', '4', '户', '上下', NULL, '户 (象形。甲骨文字形,象门(閠)字的一半『字部首之一。从户”的多与门户有关。本义单扇门)；组词：户下(门边；户住的属下', '小学', '1'),
    ('房', 'fáng', '8', '户', NULL, NULL, '房〈名〉 (形声。从户,方声。上古边室皆用单扇门(即户”),庙门大门才用双扇门,故房”从户”。本义正室左右的住室) 古代堂中间叫正室,两旁的叫房 房,室在傍者也。；组词：厢房(正房前面两旁的房屋)；房植(房室四角的柱)；房 房 fáng 1.室,屋~屋', '小学', '1'),
    ('所', 'suǒ', '8', '户', '左右', NULL, '所 (形声。从斤,户声。斤,斧子。本义伐木声) 所”假借为处”。处所;地方 有截其所。--《诗·商颂·殷武》 不可不为择所而后错之。--《荀子·王霸》 必于无人之所；组词：哨所；寓所；诊所；交易所；看守 所suǒ 1.地方处~', '小学', '1'),
    ('扁', 'biǎn', '9', '户', NULL, NULL, '扁 (会意。从户,从册。本义在门户上题字) 同本义 扁,署也。--《说文》 六曰署书是也。--《秦书八体》；组词：扁表(题门表彰) 犹撇嘴', '小学', '1'),
    ('扇', 'shàn', '10', '户', NULL, NULL, '扇 摇扇 吹,扇助也。--《方言十二》 艳妻扇方处。--《诗·小雅·十月之交》。毛本作煽。 一扇息火,二扇生风,三扇下雨。--《西游记》；组词：扇风(摇扇以生风)；扇暍(传说周武王曾替中暑人扇风取凉)；扇枕温衾(对父母老人极尽孝道之意) 以掌批面 施展 宋官御史,', '小学', '1'),
    ('手', 'shǒu', '4', '手', NULL, NULL, '手 (象形。小篆字形,象伸出五指形。本义人体上肢的总称,一般指腕以下的部分) 同本义 手,拳也。；组词：手纽(手铐)；手杻(手铐之类的刑具)；手脚了得(手脚厉害,指有 手shǒu 1.人体的上肢(多指腕以下部分)~背', '小学', '1'),
    ('才', 'cái', '3', '扌', NULL, NULL, '才 (象形。甲骨文字形,上面一横表示土地,下面象草木的茎(嫩芽)刚刚出土,其枝叶尚未出土的样子。本义草木初生)；组词：才郎(有才学的郎君)；才哲(才智卓越的人)；才雄(杰出的人才)；才英(指才华杰出的文人)；才杰(杰出的人才) 才 才力', '小学', '1'),
    ('扎', 'zhā', '4', '扌', '左右', NULL, '扎 za 捆绑;缠束;拴;系 抄扎家私,分俵众军。--《水浒传》 又如扎抹(缠绑;收拾);扎爪(拴绑;缠绑);扎一根红头绳;扎花环;扎包(捆在腰间的长布);扎缚(捆扎;包扎)；组词：扎抹(缠绑；收拾)；扎爪(拴绑；缠绑)；扎一根红头绳；扎花环；扎包(捆在腰间的长布)；扎缚(捆扎；包扎)；扎脚(缠足)', '小学', '1'),
    ('扑', 'pū', '5', '扌', '左右', NULL, '扑 (形声。左形,右声。本义击,打) 同本义 扑,挨也。--《说文》 扑,击也。--《广雅》 连杖曰扑。--《通俗文》 荫不祥之木为雷电所扑。--《淮南子·说林》 举筑扑秦皇帝；组词：扑掌(拍掌', '小学', '1'),
    ('扒', 'bā', '5', '扌', '左右', NULL, '扒 刨,挖 扒了好几天,才扒出来这个大洞子。--《高玉宝》 用前足的钩扒掘地面。--《蝉》；组词：扒坑；扒开浮土；扒土；扒堤 攀援 他明朝就扒在我头上来哩', '小学', '1'),
    ('打', 'dǎ', '5', '扌', '左右', NULL, '打 (形声。从手,丁声。本义击) 同本义 打,击也。--《说文新附》 身世浮沉雨打萍。--宋·文天祥《过零丁洋》；组词：用棍打狗；打拍(敲击)；打火刀(用来敲打火石的刀形铁片) 殴打；斗殴', '小学', '1'),
    ('扔', 'rēng', '5', '扌', '左右', NULL, '扔 (形声。从手,乃声。甲骨文字形,象以手牵引或投掷东西的样子。本义牵引,拉) 同本义 扔,引也。', '小学', '1'),
    ('托', 'tuō', '6', '扌', '左右', NULL, '托〈动〉 推。同拓” 托,推也。--《玉篇》 拓,手推物也。或作托。--《集韵》 用手掌附着或承着 泛指承托', '小学', '1'),
    ('扛', 'káng', '6', '扌', '左右', NULL, '扛 gang 用两手举重物 扛,横关对举也。--《说文》。字亦作掆. 两人对举为扛。--《后汉书·费长房传》注 翘关扛鼎。--左思《吴都赋》 扛,举也。--《广雅》 力能扛鼎；组词：扛鼎(举鼎)；扛舁(举抬) 两人或两人以上共抬一物 磕；碰 阻拦 横架 这时城门已经上 扛gāng 1.使用两手举起东西', '小学', '1'),
    ('扣', 'kòu', '6', '扌', '左右', NULL, '扣〈动〉 (形声。从手,口声。本义拉住,牵住) 同本义 扣,牵马也。--《说文》 扣马而谏。--《史记·伯夷叔齐传》 梁由靡扣缪公之骖。--《淮南子·泛论》 太子与郭荣扣马；组词：扣马(牵住马,不使前进', '小学', '1'),
    ('执', 'zhí', '6', '扌', '左右', NULL, '执 (右边是人,手被铐住。本义拘捕;捉拿) 同本义 执,捕罪人也。--《说文》 而妻妾执。--《礼记·檀弓》。注拘也。” 使执连尹。--《吕氏春秋·慎行》。注囚也。” 遂袭虞；组词：执命(讨命；索命)；执讯(捉命并加以审问)；执囚(拘捕囚禁)；执问(拘留讯问)；执狱(治狱；审判案件) 拿；持 执之用黄', '小学', '1'),
    ('扩', 'kuò', '6', '扌', '左右', NULL, '扩 扩大;张开 扩,引张之意。--《玉篇》 知皆扩而充之矣。--《孟了·公孙丑上》 王者何修身正行,扩施善政?--《论衡·感虚》；组词：扩清(廓清；肃清)；扩广(扩张', '小学', '1'),
    ('扫', 'sǎo', '6', '扌', '左右', NULL, '扫 (会意。从手,从帚。手拿扫帚表示打扫。本义打扫) 同本义 埽,弃也。--《说文》。字亦作掃。 埽,除也。--《广雅》 掌五寝之埽除粪洒之事。--《周礼·隶仆》 子有廷内；组词：扫径(清洁路径)；扫尘(扫去尘垢；比喻扫荡残敌,平定乱事)；扫脑儿(秃子)；扫道(踩出来的路)；扫桃(扫面子)；扫花以待', '小学', '1'),
    ('扬', 'yáng', '6', '扌', '左右', NULL, '扬 (形声。从手,? 同本义 扬,飞举也。--《说文》 扬,举也。--《小尔雅》 杜篑洗而扬觯。--《礼记·檀弓》 盥洗扬斛。--《礼记·乡饮酒义》 南扬弓；组词：扬楫(行船)；扬袂(举袖)；扬眉(举目)；扬旌(高举军旗)；扬麋(扬眉)；扬觯(举起酒器)；扬鞭(挥鞭)；扬臂(振臂)', '小学', '1'),
    ('扭', 'niǔ', '7', '扌', '左右', NULL, '扭 〈动〉 (形声。从手,丑声。本义用手拧) 同本义 揪住 大众见他二人扭在一起。--《官场现形记》；组词：扭殴(揪打)；扭拽(拉扯)；扭拽(揪住)；扭搜(硬挤) 扭动；亿 只消把腰儿扭一扭就过去了', '小学', '1'),
    ('扮', 'bàn', '7', '扌', '左右', NULL, '扮 (形声。从手,分声。(蝦??))本义握,并) 打扮,装扮 鲁智深、武松扮作行脚僧。--《征四寇传》；组词：扮作客人；扮女人；扮相；扮戏子(化妆演戏的人) 装出 扮fěn 1.握持', '小学', '1'),
    ('扯', 'chě', '7', '扌', '左右', NULL, '扯 (形声。从手,奢声。扯是撦”的俗字。本义撕裂) 拉,牵引 撕 零买 拔起 谈话,多指漫无边际的谈话 扯 chě 1拉拉拉~~。 2撕;撕下把贴在墙上的报纸~下来', '小学', '1'),
    ('扰', 'rǎo', '7', '扌', '左右', NULL, '扰 (形声。从手,擾省声。本义搅扰;扰乱) 同本义 扰,扰乱也。--《玉篇》 各有攸处,德用不扰。--《左传·襄公四年》 秦失其道,豪杰并扰。--《史记·太史公自序》 当农桑时；组词：扰搅(搅扰)；扰怨(扰民惹怨)；扰紊(扰乱)；扰逼(骚乱逼迫)；扰累(扰害)；扰习(言习以为常)；扰夺(掠夺)；扰民(侵', '小学', '1'),
    ('扳', 'bān', '7', '扌', '左右', NULL, '扳 (形声。从手,反声。本义拉,引) 拉;引;拨动 日扳仲永环谒于邑人。--宋·王安石《伤仲永》；组词：扳罾(拉罾网捕鱼)；扳倒(用力拧转使之倒翻；翻倒)；扳闸 扭转；背转 帝谓能丰己,故扳公议立之', '小学', '1'),
    ('扶', 'fú', '7', '扌', '左右', NULL, '扶〈动〉 (形声。从手,夫声。从手”,表示与手的动作有关。本义搀扶) 同本义 危而不持,颠而不扶,则将焉用彼相矣?；组词：扶绰(搀扶,扶托)；扶策(扶助,搀扶)；扶掖(搀扶；扶助)；扶挈(以手搀扶)；扶将(搀扶) 扶持；护持 蓬生麻中,不扶而', '小学', '1'),
    ('批', 'pī', '7', '扌', '左右', NULL, '批〈动〉 (形声。从手,比声。本义反手打) 同本义 引申为打、攻击 贵) 引申为刺入 依乎天理,批大鄐,导大竨。', '小学', '1'),
    ('扼', 'è', '7', '扌', '左右', NULL, '扼 (形声。从手,厄声。本义抓住;掐住) 同本义 搤,捉也。--《说文》 力扼虎,射命中。--《汉书·李陵传》 搤其喉而不得进。--《后汉书·荀彧传》 不搤其亢；组词：扼虎(用双手掐住猛虎)；扼吭拊背(本指控制咽喉', '小学', '1'),
    ('找', 'zhǎo', '7', '扌', '左右', NULL, '找 (会意。从手,从戈。像用手拾戈。本义觅取,寻求) 同本义 这可丢了!往那里找去?--《红楼梦》 退有余,把超过应收的钱物退还 补不足 当下先秤了一半船钱,那一半直待到县时找足；组词：找补(添补；补偿；补充)；找价(补加价款) 希望与...见面 找zhǎo 1.觅取,寻求,想要得到你~什么?~事做', '小学', '1'),
    ('承', 'chéng', '8', '手', NULL, NULL, '承 (会意。甲骨文字形,上面象跽跪着的人,下面象两只手∠起来表示人被双手捧着或接着。本义捧着) 承,奉也。受也。；组词：承印(捧印)；承萼(指物件承托的联结部分)；承盘(托盘) 继承 朱明未承夜兮', '小学', '1'),
    ('技', 'jì', '7', '扌', '左右', NULL, '技 (形声。从手,支声。本义技艺,技巧,才艺) 同本义 技,巧也。--《说文》 尚技而贱车。--《礼记·坊记》。注犹艺也。” 无他抚。--《大学》 他技,奇巧异端也；组词：技jì 1.手艺,才能,本领~艺', '小学', '1'),
    ('抄', 'chāo', '7', '扌', '左右', NULL, '抄 (形声。从手,少声。本义叉取) 同本义 掠取,抢掠 抄写 搜查并没收 而抄捕南海馆之报忽至。--清·梁启超《谭嗣同传》；组词：抄籍(抄没并登记归公)；抄没(查抄没收) 从侧面绕过去 两手交叉在胸前或背后插在袖筒里 顺手牵羊拿走 抄 chāo 1写', '小学', '1'),
    ('把', 'bǎ', '7', '扌', '左右', NULL, '把 (形声。从手,巴声 。本义握持;执) 同本义 把,握也。--《说文》 其拱把而上者。--《庄子·人间世》 拱把之桐梓。--《孟子》。注以一手把之也。” 汤自把铖以伐昆吾；组词：把杯(拿着杯子)；把刀(掌刀,上灶烧菜)；把卷(持卷)；把玩(握在手中或置于手中赏玩)；把腕(握住手腕) 把守；看守', '小学', '1'),
    ('抑', 'yì', '7', '扌', '左右', NULL, '抑 (本写作归”。会意。小篆字形,象用手抑人使跽。本义按,向下压) 同本义 抑之欲其奥。--唐·柳宗元《柳河东集》；组词：抑按(按压)；抑首(按其首)；抑搔(按摩抓搔)；抑扬(按下与上举) 抑制 抑其兼并', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('抒', 'shū', '7', '扌', '左右', NULL, '抒 (形声。从手,予声。本义舀出) 同本义 抒,挹也。--《说文》 汲出谓之抒。--《通俗文》 抒,取也。--《苍颉篇》 或舂或揄。--《诗·大雅·生民》。毛传揄,抒臼也；组词：各抒己见；抒诚(申达诚意)；抒词(运用词语,表达词意)；抒意(表达心意)；抒愤(发泄怨愤) 通纾”', '小学', '1'),
    ('抓', 'zhuā', '7', '扌', '左右', NULL, '抓 (形声。从手,爪声。本义搔) 同本义 杜诗韩集愁来读,似倩麻姑痒处抓。--唐·杜牧《读韩杜集》；组词：抓挠(用指甲或轻或重地抓搔)；抓心(形容心里焦急得难受) 用手或爪取物 夫十围之木,始生而蘖,足可搔而绝,手可擢而抓', '小学', '1'),
    ('投', 'tóu', '7', '扌', '左右', NULL, '投〈动〉 (会意。从手,从殳。殳,古兵器∠起来表示手拿兵器投掷。本义投掷) 同本义 投,擿(掷)也。；组词：投兵(向人投掷兵刃', '小学', '1'),
    ('抖', 'dǒu', '7', '扌', '左右', NULL, '抖 (形声。从手,斗声。本义抖擞) 振动;甩动 颤动,哆嗦 把隐讳的事情揭露出来 振作 抖起精神 讽刺人突然得势或生活水平突然提高 讽刺或骂人耍威风 抖 dǒu 1使振动~~雨衣', '小学', '1'),
    ('抗', 'kàng', '7', '扌', '左右', NULL, '抗〈动〉 (形声。从手,亢声。本义抵抗,抵御) 同本义 抗,扦也。--《说文》 抗,御也。--《小尔雅·广言》 抗木横一缩。--《仪礼·既夕礼》 非抗于九国之师也；组词：抗木(旧时所用的葬具', '小学', '1'),
    ('折', 'shé', '7', '扌', '左右', NULL, '折〈动〉 she 断而犹连 使断成两截(如在变形应力或张应力下) 别太使劲,不然绳子就要折了 生意亏损 折 zhe 倒过来倒过去 只管把果子折在一个碟子里,端着就走。；组词：开水太烫,拿两个杯子折一折就凉了 折 zhe (会意', '小学', '1'),
    ('抚', 'fǔ', '7', '扌', '左右', NULL, '扶〈动〉 (形声。从手,夫声。从手”,表示与手的动作有关。本义搀扶) 同本义 危而不持,颠而不扶,则将焉用彼相矣?；组词：扶绰(搀扶,扶托)；扶策(扶助,搀扶)；扶掖(搀扶；扶助)；扶挈(以手搀扶)；扶将(搀扶) 扶持；护持 蓬生麻中,不扶而', '小学', '1'),
    ('抛', 'pāo', '7', '扌', '左右', NULL, '拋 (形声。本义丢弃) 同本义 管儿不作供奉儿,抛在东都双鬓丝。--唐·元稹《琵琶歌》 纸片抛落。；组词：抛漾(抛弃)；抛撒(抛弃；脱落；洒落)；抛撇(抛开；撇弃)；抛官(辞官,弃官)；抛除(丢弃,抛掉) 抛,掷 忆昔花间相见', '小学', '1'),
    ('抠', 'kōu', '7', '扌', '左右', NULL, '抠 (形声。从手,区声。本义抓,提) 同本义 使数人抠耳,力掀举之。--《聊斋志异·大力将军》；组词：抠衣(提起衣服前襟', '小学', '1'),
    ('抡', 'lún', '7', '扌', '左右', NULL, '抡 挥动或挥舞 那后生抡着棒又赶入来。--《水浒全传》 又如抡打(挥舞);抡大铁锤;抡荤的(说下流话) 任意浪费家财 猛拉 抡动 抡动他的手臂 抡眉竖目 所以即使是同伴之间；组词：抡打(挥舞)；抡大铁锤；抡荤的(说下流话) 任意浪费家财 猛拉 抡动 抡动他的手臂 抡眉竖目 所以即使是同伴之间,往往因', '小学', '1'),
    ('抢', 'qiǎng', '7', '扌', '左右', NULL, '抢 撞;碰;触 飞抢榆枋支遁。--《庄子·逍遥游》。注突也” 抢,刺也。--《汉书·扬雄传》注 以头抢地。--《战国策·魏策》 抢呼欲绝。--《聊斋志异·促织》；组词：抢地(碰触地面', '小学', '1'),
    ('护', 'hù', '7', '扌', '左右', NULL, '护 (形声。从言,蒦声。本义保卫;保护) 同本义 吏护还之乡。--唐·柳宗元《童区寄传》 吾欲护汝。--明·魏禧《大铁椎传》 从我杀贼护家室；组词：护队(行军所设防卫的军队)；护藏(保护经藏)；护梁(城楼上作护卫用的横梁)；护镜(护心镜', '小学', '1'),
    ('报', 'bào', '7', '扌', '左右', NULL, '报 (会意。从帇,从阜,金文字形,左边象刑具形,即帇(楮??))”。右象手按人使之跽跪意,即阜”。组合在一起表示治人罪之意。本义断狱,判决罪人)；组词：报囚(判决囚犯)；报当(判罪) 报答,报酬 欲报之于陛下也', '小学', '1'),
    ('披', 'pī', '8', '扌', '左右', NULL, '披〈名〉 (形声。从手,皮声。本义引柩帛) 古夹具。即用在柩车两旁牵挽的帛 披,从旁持曰披。', '小学', '1'),
    ('抬', 'tái', '8', '扌', '左右', NULL, '抬〈动〉 (形声。从手,台声。本义合力共举一物) 同本义 抠眼睛,捻鼻子,抬鼓弄,直打做一个攒盘。；组词：抬鼓弄(许多人把一个人抬起来翻倒)；抬轿子；抬出去；抬驾(抬轿)；抬盒(两人抬着盛放礼品的箱匣)；抬筐(两人抬的装物大筐', '小学', '1'),
    ('抱', 'bào', '8', '扌', '左右', NULL, '抱 (形声。从手,包声。本义用手臂围住) 同本义 公然抱茅入竹去。--唐·杜甫《茅屋为秋风所破歌》 遂相与一抱而别。--清·梁启超《谭嗣同传》 犹抱薪救火；组词：抱石(怀石', '小学', '1'),
    ('抵', 'dǐ', '8', '扌', '左右', NULL, '抵 (形声。从手,氐声。本义挤,推) 同本义 抵,挤也。--《说文》 抵,推也。--《广雅》 抵,距也。--《汉书·梁怀王揖传》注；组词：抵掎(排挤攻击)；抵斥(排斥)；抵排(排斥；抵触) 抵赖,拒不承认事实 延年抵曰', '小学', '1'),
    ('抹', 'mò', '8', '扌', '左右', NULL, '抹 ma 揩;擦 武松抹了桌子。--《水浒全传》 又如抹脱(擦掉);抹泪揉眵(揩拭眼泪);抹抹(揩抹干净) 捋;拉;推 抹 mo (形声。从手,末声。本义涂抹,涂敷;搽)；组词：抹脱(擦掉)；抹泪揉眵(揩拭眼泪)；抹抹(揩抹干净) 捋；拉；推 抹 mo (形声', '小学', '1'),
    ('押', 'yā', '8', '扌', '左右', NULL, '押 (形声。从手,甲声。本义签署,在公文、契约上签字或画记号,以做凭信) 同本义 随即押一纸公文。；组词：押了花字(押花)；押合同(签订合同)；押榜(在官府文告上签字)；押敕(签署诏令)；押文字(签字)；押字(签字)；押署(签', '小学', '1'),
    ('抽', 'chōu', '8', '扌', '左右', NULL, '抽 (形声。从手,由声。本义拔出,抽出) 拔出,把夹在中间的东西取出 抽,拔也。--《广雅》 每射,抽矢菆。--《左传·宣公十二年》 挈水若抽。--《庄子·天地》。李注引也；组词：抽简禄马(算命)；抽匣(抽剑出匣)；抽毫(抽笔出套)；抽宝剑；抽刀 从全部里取出一部分；拔除 言抽其棘', '小学', '1'),
    ('拂', 'fú', '8', '扌', '左右', NULL, '拂士 入则无法家拂士。--《孟子·告子下》 拂〈动〉 (形声。从手。弗声。本义拂拭;掸除)；组词：拂掉(拂杓', '小学', '1'),
    ('拄', 'zhǔ', '8', '扌', '左右', NULL, '拄 (形声。从手,主声。本义支撑) 同本义 修剑拄颐。--《战国策·齐策六》 又如拄颊(以手支颊);拄颐(顶到面颊。形容剑长);拄撑(支撑) 执持;靠 宝玉听说,只得拄了一支杖；组词：拄颊(以手支颊)；拄颐(顶到面颊', '小学', '1'),
    ('担', 'dān', '8', '扌', '左右', NULL, '担 (形声。从手,詹声。本义用肩挑) 同本义 儋,何也。从人,詹声。以背曰负,以肩曰儋。--《说文》。字亦作擔”。 担,负也。--《字林》 担囊行取薪；组词：肩不能担,手不能提；担戴(肩挑头顶) 背负 承当,承担 吾担悲也', '小学', '1'),
    ('拆', 'chāi', '8', '扌', '左右', NULL, '拆 (形声。从手,斥声。本义裂开) 同坼”。裂开;绽开 雷雨作而百果草木皆甲拆。--《易·解·彖传》；组词：拆裂(分裂；破裂)；拆副(裂开) 开启 公拆袄,出珠授之', '小学', '1'),
    ('拇', 'mǔ', '8', '扌', '左右', NULL, '拇 (形声。从手,母声。本义手大指) 同本义 拇,拇指也。--《说文》。按,中指为将指,大指为拇指,手足大指皆曰拇。 至于手拇毛脉。--《国语·楚语》。注大指也。”；组词：拇印(以手的拇指代印)；拇阵(拇战', '小学', '1'),
    ('拉', 'lā', '8', '扌', '左右', NULL, '拉〈动〉 (形声。从手,立声。本义摧折,折断) 同本义 拉,摧也。--《说文》 使力士彭生拉杀鲁桓公。--《史记·齐世家》 拉捭摧藏。--《文选·左思·吴都赋》 拉干而杀之；组词：摧枯拉朽(摧折枯枝朽木', '小学', '1'),
    ('拌', 'bàn', '8', '扌', '左右', NULL, '拌 搅和;调匀 拿香油一收,外加糟油一拌。--《红楼梦》 又如用水拌面粉;拌种;拌草;拌匀(搅拌使均匀) 争吵 拌 bàn 搅和往面条里~菜。 拌pān 1.舍弃;豁出；组词：用水拌面粉；拌种；拌草；拌匀(搅拌使均匀) 争吵 拌 bàn 搅和往面条里~菜', '小学', '1'),
    ('拍', 'pāi', '8', '扌', '左右', NULL, '拍〈动〉 (形声。从手,白声。本义拍击) 同本义 举手拍鞍马。--《玉台新咏·古诗为焦仲卿妻作》；组词：拍浮(游泳)；拍肩(轻拍别人的肩膀', '小学', '1'),
    ('拐', 'guǎi', '8', '扌', '左右', NULL, '拐 (形声。从手。本义拐杖) 同本义。通枴”。亦称拐棍 沉香拐拄一根。--《红楼梦》 又如拐子头(小孩。因老人需孩子扶行,其作用如同拐杖”;又俗称太监身边的小厮);拐儿(拐杖；组词：拐子头(小孩', '小学', '1'),
    ('拒', 'jù', '7', '扌', '左右', NULL, '拘 (形声。从手,巨声。本义抵御,抵抗) 同本义 其不可者拒之。--《论语》 拒敌也。--《荀子·仲尼》注 内以固城,外以拒难。--《荀子·君道》；组词：拒御(抵御)；拒敌(抵御敌人；匹敌,比得上)；拒捍(抵抗)；拒马(古代的一种防御战具', '小学', '1'),
    ('拓', 'tuò', '8', '扌', '左右', NULL, '拓〈动〉 ta 拓印 墨,显出文字图像来 其相承传拓之本,犹在秘府。--《隋书·经籍志》；组词：拓工(拓印的工艺)；拓手(摹印石碑上文字、图画的技艺)；拓本(拓片装订成的本子)；拓印(摹印石碑或器物上的文字、图画)', '小学', '1'),
    ('拔', 'bá', '8', '扌', '左右', NULL, '拔 (形声。从手,犮(蹢??)声。本义拔起,拔出) 同本义 拔,擢也。--《说文》 拔,引也。--《苍颉篇》 确乎其不可拔。--《易·乾》。郑注移也。” 拔河；组词：拔毛；拔草；拔秧 盐；提拔 是以先帝简拔以遗陛下', '小学', '1'),
    ('拖', 'tuō', '8', '扌', '左右', NULL, '拖 (形声。本作拕”,左形,右声。本义曳引) 同本义 拕,引也。--《广雅》 纵体拖发。--《淮南子·齐俗》 拖其衣被。--《淮南子·人间世》 拖舟而入水；组词：拖上州拔下县(被拖到州里,拉到县上)；拖罟(拖网)；拖钩(拔河的别称)；拖刀计(假装败走将刀垂下,乘机回击之计)；拖扯(', '小学', '1'),
    ('拗', 'niù', '8', '扌', '左右', NULL, '抝 (形声。从手,幼声。本义折断) 同本义 捣麝成尘香不灭,拗莲作寸丝难绝。--唐·温庭筠《达摩支曲》 十分小心的拗开了,焦皮里面窜出一道白气,白气散了,是两半个白面的馒头；组词：拗折(折断) 转折；弯转 读到这里,他总是微笑起来,而且将头仰起,摇着,向后面拗过去,拗过去', '小学', '1'),
    ('拘', 'jū', '8', '扌', '左右', NULL, '拘 (会意。从手,从句,句亦声。本义拘留,拘禁) 同本义 拘,止也。--《说文》 艮为拘随物系之。--《易·说卦》传 拘系之乃从。--《易·随》 盖文王拘而演；组词：拘证(缉拿审问)；拘刷(通缉；拘捕)；拘究(拘留审察)；拘制(拘禁,系缚)；拘责(拘留责罚)；拘闭(拘禁,扣押) 束缚', '小学', '1'),
    ('拙', 'zhuō', '8', '扌', '左右', NULL, '拙 (形声。从手,出声。本义笨拙,不灵活) 同本义 拙,不巧也。--《说文》 拙,钝也。--《广雅》 不利于人谓之拙。--《墨子·贵义》 予亦拙谋。--《书·盘庚》 理弱而媒拙兮；组词：性拙(生性 拙zhuō 1.笨,不灵巧~嘴', '小学', '1'),
    ('招', 'zhāo', '8', '扌', '左右', NULL, '招 (会意。从手。召声,呼唤。本义打手势叫人来) 同本义 招,手呼也。--《说文》 招者,召也。以手曰招,以言曰召。--《楚辞·招魂序》 招樊哙出；组词：招迎(招呼使接待；招引迎接)；招求(招引导求)；招招(招呼的样子)；招诱(招唤劝导)；招护(招呼,关照)；招应(招呼、理', '小学', '1'),
    ('拜', 'bài', '9', '手', '左右', NULL, '拜 (会意。从两手,从下。《说文》古文上象两手,乥为下”的古体。《说文》引扬雄说拜从两手下。”表示双手作揖,或下拜。隶书将乥”(下)并入右边的手”之下而成为拜”,一直沿用至今', '小学', '1'),
    ('拟', 'nǐ', '7', '扌', '左右', NULL, '拟 (形声。从手,以声。本义揣度,猜测) 同本义 拟,度也。--《说文》 行止而拟度焉。--《周礼·射人》注 拟之而后言,议之而后动；组词：悬拟(凭空虚构)；拟足(揣度脚步)；拟度(揣度；推测)；拟迹(揣度足迹)；拟题(应试举子揣度命题) 类似；比拟 复举剑拟', '小学', '1'),
    ('拢', 'lǒng', '8', '扌', '左右', NULL, '拢 (形声。从手,龙声。本义聚合,合拢) 同本义 拢万川乎巴梁。--郭璞《江赋》 又如拢钱 总计;合计 梳理;整理 傍靠 知郎旧时意,且请拢船头。；组词：拢钱 总计；合计 梳理；整理 傍靠 知郎旧时意,且请拢船头', '小学', '1'),
    ('拣', 'jiǎn', '8', '扌', '左右', NULL, '拣 (形声。从手,柬声。柬”亦兼表字义。本义挑选,选择) 同本义 揀,择也。--《广雅》；组词：拣人(挑人)；拣换(挑选,更换)；拣口儿(挑食,挑可口的食物)；拣发(选择；委派)；拣有头发的抓(选择有钱人作为进攻的对', '小学', '1'),
    ('拥', 'yōng', '8', '扌', '左右', NULL, '拥 (形声。从手,雍声。本义抱) 同本义 闭门,聚众鸣鼓。众恐,拥柱而歌。--汉·刘向《列女传》；组词：拥树(拥抱小孩；环抱树木)；拥矢(古代行投壶礼时,卑者抱矢而投)；拥社(抱持社主)；拥持(拥抱)；拥膝(抱膝) 簇拥 诸', '小学', '1'),
    ('拦', 'lán', '8', '扌', '左右', NULL, '拦 (形声。从手,阑(声。本义阻挡;遮拦) 同本义 拦,遮拦也。--《玉篇》 牵衣顿足拦道哭,哭 声直上干云霄。--唐·杜甫《兵车行》；组词：拦关(形容两臂力大无穷；又指粗壮的手臂)；拦护(阻拦,保护)；拦门(宋时娶妻,回至男家门时,乐人等拦在门外索要钱物)；拦', '小学', '1'),
    ('拧', 'nǐng', '8', '扌', '左右', NULL, '拧 (形声。从手,宁声。本义用拇指和另外一两个指头扭住皮肉用力转动) 同本义 扭;绞 团聚 拧 用力扭转 说罢,三步两步,跑到那马车跟前,伸手把机关一拧,用力一拉,开了门。；组词：拧转(扭转,转过)；水笼头拧不开；拧螺旋 别扭；意见相互不一致 他两个越说越拧,脸上的笑影儿都没有了', '小学', '1'),
    ('拨', 'bō', '8', '扌', '左右', NULL, '拨 (形声。从手,发声。本义治理) 同本义 撥,治也。--《说文》 玄王桓拨。--《诗·商颂·长发》 拨乱世,反诸正,莫近诸《春秋》。--《公羊传·哀公十四年》；组词：拨烦(治理烦杂的事务)；拨乱(治理乱政；平定祸乱)；拨畦(整治田畦)；拨通(开导；启发) 拨动东西；分开；拨开 香炉风雪', '小学', '1'),
    ('择', 'zé', '8', '扌', NULL, NULL, '择 (形声。从手,瞘声。本义选取,挑选) 同本义 择,柬选也。--《说文》 与恶剑无择。--《吕氏春秋·简选》。注别也。” 而错择名利。--《淮南子·俶真》。注取也。” 申此择辞；组词：择席之癖(有选择睡铺的习惯)；择吉结缡(选择吉日,迎娶完婚)；择邻(选择邻居)；择木(选择主人,为其效劳)；择术(选择职', '小学', '1'),
    ('括', 'kuò', '9', '扌', '左右', NULL, '括〈动〉 (形声。本义结,扎束) 用绳或带子结扎,捆束 括,絜也。--《说文》。按,絜者,束也。 括囊。--《易·坤》。注结也。” 括,约束也。--《韩诗章句》 卫北宫括；组词：括囊(结扎袋口)；括发(束发)；括结(结扎；捆缚)；括约肌 引申为约束 以礼括其君,使人于善也', '小学', '1'),
    ('拭', 'shì', '9', '扌', '左右', NULL, NULL, '小学', '1'),
    ('拯', 'zhěng', '9', '扌', '左右', NULL, '拯 (形声。从手,丞声。本义向上举) 同本义 艮期腓,不拯其随。--《易·艮》。王弼注随,谓趾也。止其腓,故其趾不拯也。”孔颖达疏拯,举也。” 救济;援救 吾必尽吾力以拯吾村；组词：拯弊(匡救衰病)；拯世(救世)；拯物(济世)；拯恤(援助；救济)；拯抚(救济安抚)；拯济(救助；救济) 拯zhěng救出', '小学', '1'),
    ('拱', 'gǒng', '9', '扌', '左右', NULL, '拱 (形声。从手,共声。本义抱拳,敛手。两手在胸前相合,表示恭敬) 同本义 拱,敛手也。--《说文》。注谓沓其手。右手在内,左手在外。男之吉拜尚左,女之吉拜尚右。凶拜反是；组词：拱默(拱手不言,以避免惹是非)；拱伏(两手抱拳以 拱gǒng 1.两手在胸前相合成拳状,〈表〉敬意低头~手', '小学', '1'),
    ('拳', 'quán', '10', '手', '上下', NULL, '拳〈名〉 (形声。夲义紧握的手。俗称拳头) 同本义 拳,手也。--《说文》。按,张之为掌,卷之为拳。” 鲁君许诺,乃使吏韆其拳。--《吕氏春秋》；组词：挥拳；赤手空拳 拳术；拳击 通弮”', '小学', '1'),
    ('拴', 'shuān', '9', '扌', '左右', NULL, '拴 (形声。从手,全声。本义绑住) 同本义 拴了倪二,拉着就走。--《红楼梦》 又如把你的马拴在树上;应当把恶狗拴好;拴束(捆绑;收拾) 插上门闩 武松把门关上,拴了；组词：把你的马拴在树上；应当把恶狗拴好；拴束(捆绑；收拾) 插上门闩 武松把门关上,拴了', '小学', '1'),
    ('拷', 'kǎo', '9', '扌', '左右', NULL, '拷〈动〉 (形声。从手,考声。本义打;拷打) 同本义 不听非法拷人。--《魏书·刑罚志》；组词：拷较(拷问刑讯)；拷讯(拷打审问)；拷究(拷打审问)；拷掠(拷打逼供)；拷勘(拷问) 拷kǎo 1.打~问', '小学', '1'),
    ('拼', 'pīn', '9', '扌', '左右', NULL, '拼〈动〉 绑 武松定睛看时,却是两个人,把虎皮缝做衣裳,紧紧拼在身上。--《水浒传》 随从 拼,从也。--《尔雅》。郭璞注为随从。” 合在一起;连合;连缀 拼命,不顾惜；组词：拼杀；拼到底；拼舍着脸(撕下脸；扳着脸)；拼命亡身(不顾一切的伤害自己)；拼死吃河豚(夸口；说大话) 同抨”', '小学', '1'),
    ('拾', 'shí', '9', '扌', '左右', NULL, '拾 (形声。从手,合声。本义捡取,从地上捡起来) 同本义 拾,掇也。--《说文》 犹拾遗于涂,摭弃于野。--《论衡·逢遇》 故周之夺殷也,拾遗于庭。--《韩非子·安危》 犹拾瀋也；组词：拾粪；拾麦穗儿；拾毛(拣界外球', '小学', '1'),
    ('拿', 'ná', '10', '手', '上下', NULL, '拿 (会意。手合起来,表示握持,字本作挐”。从手。奴声。本义握持) 同本义 手里拿串拍板。；组词：从架上拿书；用钳子拿钉子；他拿起帽子和大衣走了；别拿我的东西 捉拿 差人拿不将他来；差人都合他是一个人,谁肯拿他?--《', '小学', '1'),
    ('持', 'chí', '9', '扌', '左右', NULL, '持 (形声。从手,寺声。本义拿着) 同本义 持,握也。--《说文》 持弓矢审固。--《礼记·射义》 有持盈。--《国语·越语》 客持头往见楚王,王大喜；组词：持仗(手持武器)；持斧操斤(拿着斧头)；持笔；持戟 引申为掌握；控制 悖乱不可以持国', '小学', '1'),
    ('挂', 'guà', '9', '扌', '左右', NULL, '挂 (形声。从手,圭声。本义区别,区分) 同本义 挂,画也。--《说文》。段玉裁注《易·系辞传》分而为二以象两,挂一以象三。”...古本多作画者,此等皆有分别画出之意。陆德明云挂；组词：挂匾；挂筹( 挂(掛)guà 1.悬,悬吊~图片', '小学', '1'),
    ('指', 'zhǐ', '9', '扌', '左右', NULL, '指 手指。手掌的五个终端部分之一 指,手指也。--《说文》 骈拇枝指。--《庄子·骈拇》 是犹伛身而好升高也,指其顶者愈众。--《荀子·儒效》 指如削葱根；组词：指下(手指按下,比喻诊脉看病)；伸手不见五指；屈指可数；指甲,指爪(指纹痕迹,手指尖端,指端背面扁平的表皮角质层)；指尺', '小学', '1'),
    ('按', 'àn', '9', '扌', '左右', NULL, '按〈动〉 (形声。从手,安声。本义用手向下压或摁) 同本义 按,下也。谓手抑物使下。--《说文》 于是天子乃按辔徐行。--《史记·绛侯周勃世家》 项王按剑而跽曰；组词：按电钮；按铃；按手印 控制；抑止 以按徂旅', '小学', '1'),
    ('挎', 'kuà', '9', '扌', '左右', NULL, '挎〈动〉 胳膊弯起来挂着东西 把东西挂在肩头、脖颈或挂在腰里 挎kuà把东西挂在肩上、腰里或胳膊上等~枪。~钱包。~衣服。 挎kū 1.用手指钩着。 2.通"刳"。挖', '小学', '1'),
    ('挑', 'tiāo', '9', '扌', '左右', NULL, '挑〈动〉 用肩膀担 担挑双草履,壁依一乌藤。--陆游《自题传神》。 又如挑力(挑担。以肩荷物);挑包(肩挑包裹);挑码头(在码头上挑运东西);从对门坡上挑柴火;挑米;挑油；组词：挑力(挑担', '小学', '1'),
    ('挖', 'wā', '9', '扌', '左右', NULL, '挖 (挖为穵的俗字。形声。从手,穵声。本作穵”。穵,空大的意思。本义掘) 同本义 引申为探索;深入研究 抓。用爪子或指甲抓 镂,镂空 头上戴着一顶挖云鹅黄片金里大红猩猩毡昭君套；组词：挖云(镂穿成云头形的边饰)；挖垫(旧时女红之一', '小学', '1'),
    ('挚', 'zhì', '10', '手', '上下', NULL, '挚 (会意。从手,从执。本义 古代初次求见人时所送的礼物,见面礼) 同本义 挚,握持也。--《说文》。字亦作贽。 以禽作六挚。孤执皮帛,卿执羔,大夫执雁,士执雉,庶人执鹅；组词：挚币(古时用为祭祀或馈赠礼物的束帛) 古国名 挚仲氏任,自彼殷商,来嫁于周', '小学', '1'),
    ('挟', 'jiā', '9', '扌', '左右', NULL, '挟 (形声。从手,夹声。本义用胳膊夹住) 同本义 挟,俾持也。--《说文》 挟其枪。刈耨鑮。--《国语·齐语》 右掖曰挟。--《管子·小匡》注 挟经秉枹；组词：腋下挟着一本书；挟枪；挟弓；挟尺 挟制 今有奸雄曹操,挟寡人行势,当识也', '小学', '1'),
    ('挠', 'náo', '9', '扌', '左右', NULL, '挠 (形声。从手,尧声。本义扰乱) 同本义 挠,扰也。--《说文》 挠乱百度。--《国语·吴语》。韦昭注挠,扰也。” 挠乱国家,几危社稷。--《汉书·王莽传上》。颜师古注挠,扰也；组词：挠乱(搅乱；扰乱)；挠滑(惑乱,扰乱)；挠正(扰乱正气)；挠动(扰乱骚动) 搅,搅动 挠,搅也', '小学', '1'),
    ('挡', 'dǎng', '9', '扌', '左右', NULL, '挡 (形声。从手,当声。本义阻拦;抵挡) 同本义 攩,推也。--《方言十》 挡,遮遏也。--《正字通》；组词：挡人牌(挡箭牌', '小学', '1'),
    ('挣', 'zhèng', '9', '扌', '左右', NULL, '挣 撞;击 摐金挣玉,吐宫咽征。--前蜀·贯休《长持经僧》 用力张开 你挣着口袋,我量与你么。；组词：挣开；挣不脱手 用力支撑 林冲挣的起来,被枷碍了,曲身不得', '小学', '1'),
    ('挤', 'jǐ', '9', '扌', '左右', NULL, '挤 (形声。从手,齐声。本义推开;除去) 同本义 挤,排也。--《说文》 挤,推也。--《广雅》 小人老而无子,知挤于沟壑矣。--《左传·昭公十三年》 汉军却,为楚所挤；组词：挤住了(凑上遇上而又推脱不开) 排斥；排挤 故其君因其修以挤之', '小学', '1'),
    ('挥', 'huī', '9', '扌', '左右', NULL, '挥 (形声。从手,军声。本义抛洒、甩出) 同本义 挥,备也。--《说文》 而挥之,谓振去之也。--《周礼·考工记·幌氏》 饮玉爵者弗挥。--《礼记·曲礼》 挥涕恋行在,道八犹恍惚；组词：挥涕(洒泪,哭泣)；挥尘(拂尘)；挥墨(挥洒墨水) 舞动；摇动 挥手自兹去', '小学', '1'),
    ('挨', 'āi', '10', '扌', '左右', NULL, '挨〈动〉 (形声。从手,矣声。本义以手击背) 从后推击;打 挨,击背也。--《说文》 挨,击也。--《广雅》 靠近 对垒每欲相摩挨。--王安石《和王微之登高斋》。；组词：挨晚(傍晚)；学校挨着工厂；挨墙靠壁 拥挤 宝玉挨身而入', '小学', '1'),
    ('挪', 'nuó', '9', '扌', '左右', NULL, '挪 (形声。从手,那声。本义揉搓) 同本义 两手自相挪。--韩愈《读东方朔杂事》 移动,从一处移到另一处 行者叩头,启上如来千万望挪玉一降。”；组词：挪玉(移动玉步；劳动大驾)；挪桌子；那个理发店挪地方了；把椅子挪开；挪步(移动脚步) 移用 他向日挪我的五十两银子,得便', '小学', '1'),
    ('挫', 'cuò', '10', '扌', '左右', NULL, '挫 (形声。从手,坐声。本义折断;摧折) 同本义 挫,摧也。--《说文》 或挫或隳。--《老子》 而未尝有所挫也。--《国语·吴语》。注毁折也。”；组词：挫折(劈断,折断)；挫顿(摧折损伤) 失败 挫我于内', '小学', '1'),
    ('振', 'zhèn', '10', '扌', '左右', NULL, '振 搬动,挥动~动。~荡。~幅。~臂。~聋发聩(喻唤醒糊涂麻木的人)。 奋起,兴起~奋。~作。~兴。~~有辞。 古同赈”,救济。 古同震”,威震。 振zhèn 1.挥动,抖动', '小学', '1'),
    ('挺', 'tǐng', '9', '扌', '左右', NULL, '挺〈动〉 (形声。从手,廷声。本义拔出) 同本义 挺,拔也。--《说文》 挺剑而起。--《战国策·魏策》 尉剑挺。--《史记·陈涉世家》；组词：挺举；挺挏(上下推动) 举起 生出；生长 荔挺', '小学', '1'),
    ('挽', 'wǎn', '10', '扌', '左右', NULL, '挽 (形声。从手,免声。古字从车”,免声。本义牵引;拉) 同本义 挽,引也。--《小尔雅·广诂》 輓,引之也。--《说文》 輓,輓车也。--《广韵》 或輓之,或推之；组词：挽郎(出葬时,牵绋唱挽歌的少年)；挽强(拉强弓)；挽满(拉满弓)；挽车(拉车)；挽住(憋住)；挽手儿(缰绳)；挽歌郎(出', '小学', '1'),
    ('捂', 'wǔ', '10', '扌', '左右', NULL, '捂 (形声。从手,吾声。本义用手扪住) 同本义 抵触 人心不同,闻见异辞,班氏所谓疏略抵捂者,依违不悉辩也。', '小学', '1'),
    ('捅', 'tǒng', '10', '扌', '左右', NULL, '捅 (形声。从手,甬声。本义引;招引) 同本义 重柔之兵,则噪而恐之,振而捅之,出则击之,不出则回之。--银雀山汉墓竹简《孙膑兵法》 用棍、棒、刀或枪等戳刺 刺激、触动', '小学', '1'),
    ('捆', 'kǔn', '10', '扌', '左右', NULL, '捆 (形声。从手,困声。本义叩击使牢) 同本义 皆衣褐、捆屦、织席以为食。--《孟子·滕文公》。赵歧注织屦欲使坚,故叩之也。” 用绳、链或带子系、拴、扎紧 贾蓉忍不得便骂了几句；组词：捆风(扯谎说瞎话)；捆身子(内衣)；捆行李；捆谷草；捆住手脚；把书捆起来 捆 〈量〉 捆扎在一起的东西,以便携带和搬运', '小学', '1'),
    ('捉', 'zhuō', '10', '扌', '左右', NULL, '捉 (形声。从手,足声。本义握,持) 同本义 捉,搤也。--《说文》 捉,持也。--《广雅》 伊便能捉杖打人。--《世说新语·方正》 叔武将沐,闻君至,喜,捉发走出；组词：捉发(手握头发)；捉秤(拿秤,掌秤)；捉手(握手)；捉身(把握身体)；捉船(撑船,划船)；捉笔(执笔) 暮投石壕村,有吏', '小学', '1'),
    ('捌', 'bā', '10', '扌', '左右', NULL, '捌 用手分开 故解捽者不在于捌格。--《淮南子·说林》 又如捌格(分解) 捌 八”字的大写 捌 bā ''八''的大写。', '小学', '1'),
    ('捍', 'hàn', '10', '扌', '左右', NULL, '捍 (古字作抜”,后作捍”。形声。从手,旱声。本义抵御;保卫)同本义 抜,以手抜,又卫也。；组词：捍塞(防堵,阻塞)；捍难(抵御外侮)；捍遏(以武力阻隔)；捍城(护卫城池)；捍救(捍卫；救援)；捍护(防卫；护卫)；捍屏', '小学', '1'),
    ('捎', 'shāo', '10', '扌', '左右', NULL, '捎〈动〉 (形声。从手,肖声。本义选取) 同本义 捎,择也。--《广雅·释诂》 捎,自关已西,凡取物之上为挢捎。--《说文》 捎,选也。--《方言》 掠拂 风捎檐滴难开幌；组词：捎(抽打割勒', '小学', '1'),
    ('捏', 'niē', '10', '扌', '左右', NULL, '捏 (形声。从手,从土,曰声。本义用手指将软的东西捻成一定形状) 同本义 只见几个婆子手里都捧着一色捏丝戗金五彩大盒子走来。；组词：捏泥人儿；捏怪(塑造怪相)；捏素(塑像)；捏塑(以泥塑造) 握 俺捏住这玉佩慢慢的行将去', '小学', '1'),
    ('捐', 'juān', '10', '扌', '左右', NULL, '捐 (形声。从手,胦声。本义舍弃) 同本义 捐,弃也。--《说文》。按,粪除秽污谓之捐。故寺人谓之中涓。以涓为之。 捐殡。--《谷梁传·宣公十八年》。注弃也。” 而国无捐瘠者；组词：捐世(弃世', '小学', '1'),
    ('捕', 'bǔ', '10', '扌', '左右', NULL, '捕 (形声。从手,甫声。捕的原始意义是追捕逃亡的奴隶。本义捕捉,捉拿) 同本义 捕,取也。', '小学', '1'),
    ('捞', 'lāo', '10', '扌', '左右', NULL, '捞 (形声。从手,劳声。本义从水中寻取东西) 同本义 用不正当的手段获取 的流氓) 捉拿 唠,唠叨 为了某事(如消费、损失)给自己补偿 捞(撈)lāo 1.从液体中取东西~沙', '小学', '1'),
    ('损', 'sǔn', '10', '扌', '左右', NULL, '损 (形声。从手,员声。本义减少) 同本义,与益”相对 损,减也。--《说文》 损偏去也。--《墨子经》 损德之脩也。--《易·系辞》 损益,盛衰之始也；组词：损年(短报年岁；寿命减少)；损膳(减膳)；损薄(降低标准,减损)；损夺(削减)；损减(节制；减少) 损失；丧失 满招损,', '小学', '1'),
    ('捡', 'jiǎn', '10', '扌', '左右', NULL, '捡 (形声。从手,佥声。本义拱手) 约束 郡事皆以义法令捡式。--《汉书·黄霸传》 又如捡式(约束言行的法度、准则);捡点(同检点”。约束自己的言行;检查;逐一查看);捡局(拘束；组词：捡式(约束言行的法度、准则)；捡点(同检点”', '小学', '1'),
    ('换', 'huàn', '10', '扌', '左右', NULL, '换〈动〉 (形声。从手,奂声。本义互易) 同本义 换,易也。--《说文》 擅相换易。--《谷梁传·桓公元年》注；组词：以帛换酒；换过子(互相调换)；换了帖(异姓的人结拜为兄弟时交换写有年龄、籍贯、家世等的帖子) 变易,改变 几移几换', '小学', '1'),
    ('捣', 'dǎo', '10', '扌', '左右', NULL, '捣 (形声。从手,岛声。本义捣,舂) 同本义 攆,手推也。一曰,筑也。--《说文》。字亦作捣”。 攆肉之脯。--《仪礼·有司彻》 所以捣郁也；组词：捣碓(形容磕头如捣米似的)；捣嗓子(吃喝', '小学', '1'),
    ('捧', 'pěng', '11', '扌', '左右', NULL, '捧〈动〉 (形声。从手,奉声。本义两手承托。古多作奉”) 同本义 捧,两手承也。--《广韵》 捧馈而哭。--《穆天子传》。注捧,两手持也。” 捧土以塞孟津,多见其不知量也；组词：捧戴(托举；扶拥)；捧脚(捧承他人的脚', '小学', '1'),
    ('据', 'jù', '11', '扌', '左右', NULL, '据 (形声。本义手靠着;靠着) 同本义 据,杖持也。--《说文》 冯几据杖。--《战国策·燕策》 据轼低头。--《庄子·盗跖》 依靠,凭借 不可以据；组词：据着(凭着)；据梧(依靠着梧桐树)；据争(据理争辩)；据恃(凭仗)；据高临下(凭借高处俯控低处)；据凭(依仗) 根据 据', '小学', '1'),
    ('捶', 'chuí', '11', '扌', '左右', NULL, '捶 (形声。从手,垂声。本义棒打) 同本义 捶,以杖击也。--《说文》 捶笞膑脚。--《荀子·正论》。注捶笞皆杖击也。”；组词：捶鼓；捶衣裳；捶楚(用杖或板拷打) 拳打 舂；捣 同锤”', '小学', '1'),
    ('捷', 'jié', '11', '扌', '左右', NULL, '捷 (形声。从手,痗声。本义战利品) 同本义 捷,猎也。军获得也。--《说文》 军得曰捷。--《谷梁传》 六月,齐侯来献戎捷。--《春秋·庄公三十一年》 胜利 一月三捷；组词：大捷；祝捷大会；首战告捷；捷书；捷书(报告战胜的文书) 成功 捷,吾以女为夫人', '小学', '1'),
    ('捺', 'nà', '11', '扌', '左右', NULL, '捺〈动〉 (形声。从手,奈声。本义用手重按) 同本义 先须捺后脚,然后勒前腰。--《游仙窟》；组词：捺上花冠；捺头向水下；捺印(盖指模或图章)；捺抉(用力挤压)；捺弮(向下弯曲如弓弩', '小学', '1'),
    ('捻', 'niǎn', '11', '扌', '左右', NULL, '捻〈动〉 (形声。从手,念声。本义用手指搓转) 同本义 轻拢慢捻抹复挑。--唐·白居易《琵琶行(并序)》；组词：捻就(揉缩)；捻髯(用手指搓着腮上的胡须)；捻断髭须(比喻费尽心思)；捻绳；捻灯芯；将两股纱捻成一根线 领导 驱梨园领袖', '小学', '1'),
    ('掀', 'xiān', '11', '扌', '左右', NULL, '掀 (形声。从手,欣声。本义举起) 同本义 掀,举出也。--《说文》 乃掀公以出于淖。--《左传·成公十六年》；组词：掀掀(高举的样子)；掀然(高举的样子；飞扬的样子)；掀擢(举拔,拔擢)；掀拳裸袖(高举拳头,卷起衣袖', '小学', '1'),
    ('掂', 'diān', '11', '扌', '左右', NULL, '掂 (形声。从手,店声。本义以手称物) 同本义 掂一掂有多重 计较 折 掂 diān用手托着东西上下轻轻晃动来估量轻重~~分量。 【掂掇】 1斟酌。 2估计。', '小学', '1'),
    ('授', 'shòu', '11', '扌', '左右', NULL, '授 (会意。从手,从受,受声。本义给予;交给) 同本堰 授,予也。--《说文》。按,授”应是后起字。 则从而授之。--《周礼·邻长》 献俘授馘。--《左传·僖公二十八年》。注数也；组词：授受(交接；交付和接受)；授兵(把武器给战士)；授官厅(官府；衙门)；授玉(给予玉圭)；授室(把家事交给新妇)；授赏(奖', '小学', '1'),
    ('掉', 'diào', '11', '扌', '左右', NULL, '掉 (形声。从手,卓声。本义摇,摆动) 同本义 掉,摇也。--《说文》 且郦生一士,伏轼掉三寸之舌,下齐七十余城。--《史记·淮阴侯列传》 末大未折,尾大不掉；组词：掉尾巴；掉荡(摇荡)；掉眩(肢体摇动旋转)；掉擘(甩着臂膊走,又谓攘臂奋起)；掉舌(鼓舌,指游说、谈论)；掉嘴弄舌(摇唇', '小学', '1'),
    ('掌', 'zhǎng', '12', '手', '上下', NULL, '掌 本义手掌,手心 掌,手中也。--《说文》 指其掌。--《论语·八佾》 易于反掌,安于泰山。--枚乘《谏吴王书》；组词：掌上(手掌之上', '小学', '1'),
    ('掏', 'tāo', '11', '扌', '左右', NULL, '掏〈动〉 (形声。从手,匋声。本义挖取) 同搯”。挖取 探手取物 掏(搯)tāo 1.挖~个洞。 2.伸进去取~炉灰。把包里的糖果~出来。', '小学', '1'),
    ('掐', 'qiā', '11', '扌', '左右', NULL, '掐〈动〉 用指甲按或切入 用指甲切断或截取,摘 香菱等在山石边掐凤仙花呢。--《红楼梦》；组词：把杈子掐掉 用有力的外部压力按住喉部使窒息 镶嵌 黛玉换上掐金挖云红香羊皮小靴', '小学', '1'),
    ('排', 'pái', '11', '扌', '左右', NULL, '排〈动〉 (形声。从手,非声。本义推挤,推开) 同本义 排,挤也。--《说文》 排,推也。--《广雅》 献笑不及排。--《庄子·大宗师》 排淮泗。--《孟子》 力能排南山；组词：排闼(推门', '小学', '1'),
    ('掖', 'yè', '11', '扌', '左右', NULL, '掖 塞进 你来把我这边的被掖掖罢。--《红楼梦》 又如把被角掖好 藏 黛玉微微的点头,便掖在袖里。--《红楼梦》 插入腰带 说着,掖上那把刀,迈步出门,往外就走；组词：把被角掖好 藏 黛玉微微的点头,便掖在袖里', '小学', '1'),
    ('掘', 'jué', '11', '扌', '左右', NULL, '掘 (形声。从手,屈声。本义挖) 同本义 掘,搰也。--《说文》 掘,穿也。--《广雅》 掘褚师定子之墓。--《左传·哀公二十六年》 阙(掘)地下冰而床焉；组词：掘室(掘地而成的房间)；掘阅(小虫化生,穿地而出', '小学', '1'),
    ('掠', 'lüě', '11', '扌', '左右', NULL, '掠〈动〉 (形声。从手,京声。本义抢劫,夺取) 同本义 掠,夺取也。--《说文新附》 按掠是略”的分别字,以别于经略、简略的略 已恶而掠美为昏。--《左传·昭公十四年》 输掠其聚；组词：掠美(夺取他人的优点或成就)；掠卤(掳掠,抢夺)；掠掇(动手动脚)；掠贩的(拐卖人口的人)；掠阵(夺取阵地)；掠抄(抢劫', '小学', '1'),
    ('探', 'tàn', '11', '扌', NULL, NULL, '探〈动〉 (形声。从手,羇声。本义摸取) 同本义 探,远取之也。--《说文》。按,远取犹深取也。 探,取也。--《尔雅》。注摸取也。” 必探筹而定分。--《铨言》。注捉筹也；组词：探丸(摸取药丸；又指摸取弹丸以决定谋杀官吏之事)；探囊(伸手到袋中摸取) 探求 前来一探', '小学', '1'),
    ('接', 'jiē', '11', '扌', '左右', NULL, '接 (形声。从手,妾声。本义两手交叉) 交合;会合 接,交也。--《说文》 接,合也。--《广雅》 昼日三接。--《易·晋》 两君偃兵接好。--《国语·吴语》。注合也；组词：接场(迎接从科举考场回来的生员)；接构(联合)；接 接jiē 1.连,连着~骨', '小学', '1'),
    ('控', 'kòng', '11', '扌', '左右', NULL, '控〈动〉 (形声。从手,空声。本义开弓) 同本义 控,引也。--《说文》 控弦破左的。--曹植《白马篇》 或控弦以弊筋骨。--《抱扑子·金丹》 将军角弓不得控；组词：控弦(拉弓,持弓)；控弦之士(士兵', '小学', '1'),
    ('推', 'tuī', '11', '扌', '左右', NULL, '推〈动〉 (形声。从手,隹声。本义手向外用力使物体移动或向前移动) 同本义 推,排也。--《说文》 推,輕也,前也。--《仓颉篇》 若己推而内之沟中。--《孟子·万章上》 苟有险；组词：推毂(推动车轮轴,使车前进)；推抢(推拥抢夺,争抢)；推沟(推下沟)；推行(推动物体向前)；推引(推动；推拉)；推天抢地', '小学', '1'),
    ('掩', 'yǎn', '11', '扌', '左右', NULL, '掩 (会意。从手,从奄,奄亦声。本义遮蔽) 同本义 掩,敛也。小上曰掩。--《说文》 掩练帛,广终幅。--《仪礼·士丧礼》。注裹首也。” 掩薄草渚；组词：掩圹(将棺木放入墓穴内,加土掩埋)；掩心(护胸的铠甲)；掩土(盖土埋葬)；掩面(盖在尸体面部的白色的布或绢)；掩著(掩盖', '小学', '1'),
    ('措', 'cuò', '11', '扌', '左右', NULL, '措 (形声。从手,昔声。本义放置,安放) 同本义 措,置也。--《说文》。 则民无所措手足。--《论语·子路》 学之弗能,弗措也。--《礼记·中庸》。疏学不至于能,不措置休废也；组词：措置(安放；料理)；措身(安身,置身)；措手(着手处理)；措手不迭(形容做事迅速敏捷) 处理,安排 筹划办理 施行；用', '小学', '1'),
    ('掰', 'bāi', '12', '手', '左中右', NULL, '掰 用手把东西分开或折断 张开 我时常掰着嘴儿说一阵,劝一阵,哭一阵!--《红楼梦》 掰腕子 掰 bāi 分开或折断物体~成两块。', '小学', '1'),
    ('掷', 'zhì', '11', '扌', '左右', NULL, '掷 (形声。从手,郑声。本义扔,抛) 同本义 荆轲废,乃引其匕首以掷秦王。--《史记·刺客列传》 少间,帘内掷一纸出。--《聊斋志异·促织》；组词：掷丸(辽俗,于正旦抛掷饼团以惊鬼)；掷骰(掷色,掷博,掷博齿,掷卢,掷钱', '小学', '1'),
    ('掸', 'dǎn', '11', '扌', '左右', NULL, '掸 拂去 筛 无皮的罗儿掸三遍。--《中国民谣资料·孟姜女》 掸 shan 中国史书上对傣族的一种称呼 古国名 掸,西南夷国名', '小学', '1'),
    ('掺', 'chān', '11', '扌', '左右', NULL, '掺 chan 同参”。古时候的一种鼓曲名。也指击鼓三次 镗鎝《渔阳掺》,怨抑胡笳断。--《乐府诗集·横吹曲辞》 掺 shan 细小 掺,细也。--《方言》。戴震疏证掺,细小也', '小学', '1'),
    ('揉', 'róu', '12', '扌', '左右', NULL, '揉 (形声。从手, 柔声。本义 使木弯曲或伸直) 同本义 揉木为耒。--《易·系辞下》 揉辐必齐。--《考工记·轮人》；组词：揉辐(烤木使直,以作车轴)；揉斫(砍削烤揉)；揉木为耒 用手来回擦或搓 混合；融和 琢磨 摆弄；摆布 揉róu 1.来回', '小学', '1'),
    ('揍', 'zòu', '12', '扌', '左右', NULL, '揍 (形声。从手,奏声。本义打) 揍zòu 1.打,打击。 2.〈方〉打碎。 揍còu 1.插。 2.同"腠"。肌肉的纹理。 3.通"凑"。凑集。', '小学', '1'),
    ('描', 'miáo', '11', '扌', '左右', NULL, '描 (形声。从手,苗声。本义依样摹写或绘画) 同本义 特性等等) 描写 描miáo 1.依照原样画写或重复地画~摹。~花。~图。 2. 3.', '小学', '1'),
    ('提', 'tí', '12', '扌', '左右', NULL, '提 di 用于提防”、提溜”等 提防 只要提防他便了;岂不闻古人言吃饭防噎,走路防跌。”--《水浒传》 提 〈动〉 (形声。从手,是声。本义悬持;悬空拎着物品)；组词：提壶,提桶；提开水；提掳(拎,拿)；提举(提而举之) 提 dī又见tí', '小学', '1'),
    ('插', 'chā', '12', '扌', '左右', NULL, '插 (形声。从手,臿)声。本义刺入、挤放进去) 同本义 插,刺内也。--《说文》 沉吟放拨插弦中。--唐·白居易《琵琶行(并序)》 是日城内遍插白旗。--《广州军务记》；组词：插花筵席(流水席,即客人随到随开的筵席)；插标(古人出售物品时,把茅草插在物品上表示出售)；插管(双肩式大门的门闩) 参', '小学', '1'),
    ('揖', 'yī', '12', '扌', '左右', NULL, '揖 (形声。从手,咠声。本义拱手行礼) 同本义 自家拜揖,愿求恩官高姓大名。--《水浒全传》；组词：揖客(长揖不拜之客；向客拱手为礼)；揖游(古代行礼时依礼仪进退俯仰) 让出,逊主 公惟国家之统,揖大福大恩,事事谦让,动', '小学', '1'),
    ('握', 'wò', '12', '扌', '左右', NULL, '握 (形声。从手,屋声。本义攥在手里,执持) 同本义 握,搤持也。--《说文》 握,持也。--《广韵》 长尺有握。--《仪礼·乡射礼》 私握臣手；组词：握君(如意的别称)；握篆(手握官印)；握算(执算筹以计数', '小学', '1'),
    ('揣', 'chuāi', '12', '扌', '左右', NULL, '揣〈动〉 藏入;塞进 怀孕 强给;给与 揣〈动〉 (会意。本义测量;量度) 同本义 揣,量也。', '小学', '1'),
    ('揩', 'kāi', '12', '扌', '左右', NULL, '揩〈动〉 (形声。从手,皆声。本义擦抹;摩擦) 同本义 揩,摩也。--《字林》 揩,磨也。--《广雅》 揩枳落,突棘藩。--张衡《西京赋》 我方坐垢难磨揩；组词：揩锉(摩擦)；揩面(洗脸；擦脸)；揩磨(琢磨)；揩背(揩擦背部)；揩痒(在固定的硬物上摩擦以解痒)；揩抹(擦去；抹去)', '小学', '1'),
    ('揪', 'jiū', '12', '扌', '左右', NULL, '揪 (形声。从手,秋声。本义收聚) 同本义 佺揪聚军中币万余匹,悉袍、带并与之。--《新唐书》 抓;扯住 郑屠右手拿刀,左手便来要揪鲁达。--《水浒传》；组词：揪捽(抓住；扭住)；揪扯(揪抓拉扯)；揪撇(抛到一边)；揪采(瞅睬', '小学', '1'),
    ('揭', 'jiē', '12', '扌', '左右', NULL, '揭 标志 峨嵋为泉阳之揭。--郭璞《江赋》 揭 高亢 揭揭 修长的样子。 疾驰的样子。如车马揭揭 揭jiē 1.举,高举~旗。~竿而起(泛指人民起义)。 2.掀开,掀起~开', '小学', '1'),
    ('援', 'yuán', '12', '扌', '左右', NULL, '援 (形声。从手,爰声。本义拉,引) 同本义 援,引也。--《说文》 无然畔援。--《诗·大雅·皇矣》 不援其所不及。--《礼记·缁衣》 不援上。--《礼记·中庸》 男女授受不亲；组词：援及(动起)；援推(引之使来,推之使去) 攀援 猱蝯善援', '小学', '1'),
    ('揽', 'lǎn', '12', '扌', '左右', NULL, '揽 (形声。从手,览声。本义执,持) 同本义 俱可手揽。--《徐霞客游记·游黄山记》 又如揽跋(揽辔跋涉);揽镜(持镜;对镜);揽持(把持;掌握);揽摄(把持) 总揽(全面掌握)；组词：揽跋(揽辔跋涉)；揽镜(持镜；对镜)；揽持(把持；掌握)；揽摄(把持) 总揽(全面掌握)；一把抓 搂,拥抱,围抱 采摘', '小学', '1'),
    ('搀', 'chān', '12', '扌', '左右', NULL, '搀 (形声。从手,毚)声。本义扶,牵挽) 同本义 混杂;搀和 搀 chān 1搀扶让我~你一把。 2把一种东西混入另一种东西里~沙子、~假', '小学', '1'),
    ('搁', 'gē', '12', '扌', '左右', NULL, '搁 (形声。从手,阁声。本义放,放置) 同本义 况且我又年轻,不压人,怨不得不把我搁在眼里。；组词：搁手(放开手,作罢)；搁开(放下,放开)；再搁点糖 停顿；耽搁 原来这一向因凤姐病了,李纨探春料理家务,不得闲暇；接着过', '小学', '1'),
    ('搂', 'lǒu', '12', '扌', '左右', NULL, '搂 (形声。从手,娄声。本义引,拉拢) 同本义 搂,曳聚也。--《说文》 五霸者,搂诸侯以伐诸侯者也。--《孟子·告子下》；组词：搂伐(拉拢、挟持他国一起征伐)；搂沟子(奉迎拍马)；搂搜(乖张；执拗)；搂搜索落(找岔子数落人) 搂抱；用手或工具把东西', '小学', '1'),
    ('搅', 'jiǎo', '12', '扌', '左右', NULL, '搅〈动〉 (形声。从手,觉声。本义扰乱) 同本义 搅,乱也。--《说文》 袛搅我心。--《诗·小雅·何人斯》；组词：搅攘(扰乱)；搅恼(搅扰)；搅家精(拨弄是非、寻衅闹事,搅得家庭不和的人)；搅尸灵(方言', '小学', '1'),
    ('搏', 'bó', '13', '扌', '左右', NULL, '搏 (形声。从手,尃)声。本义搏斗,对打) 同本义 搏,索持也。--《说文》 搏,击也。--《广雅》 屏左右而相搏。--《谷梁传·僖公元年》 晋侯梦与楚子博；组词：搏执(拘捕)；搏获(捕获)；搏撠(揪住)；搏 搏 bó 1搏斗；扑上去抓肉~战', '小学', '1'),
    ('搓', 'cuō', '12', '扌', '左右', NULL, '搓 (形声。从手,差声。本义两掌互相摩擦) 同本义 搓,手搓碎也。--《广韵》 搓,搓挪也。--《康熙字典》；组词：搓手；搓手顿足(形容焦急不耐烦的样子)；搓熟的汤团(比喻服服帖帖)；搓草绳；搓挪 把东西放在手心运转 搓 急迫 填词莺啭', '小学', '1'),
    ('搔', 'sāo', '12', '扌', '左右', NULL, '搔〈动〉 (形声。从手,蚤声。本义用指甲轻刮) 同本义 搔,括也。--《说文》 而敬仰搔之。--《礼记·内则》。注摩也。” 足可搔而绝。--《汉书·枚乘传》。集注谓抓也；组词：搔背(以指甲搔脊背)；搔掐(以指甲抓刮)；搔扪(爬搔抚摸)；搔摸(呵痒)；搔首(爬搔头部)；搔耙(以指爪或他物抓刮爬梳)', '小学', '1'),
    ('搜', 'sōu', '12', '扌', '左右', NULL, '搜 聚集 搜索;搜查 搜,求也。秦晋之间曰搜,就室曰搜。--《方言二》 于是惠子恐,搜于国中,三日三夜。--《庄子·秋水》；组词：搜弊(搜查弊端,弄清欺诈行为)；搜猜(搜查,搜寻)；搜筒(搜检,搜查)；搜看(搜索检查,搜查)；搜阅(搜查,查看)；搜山', '小学', '1'),
    ('搞', 'gǎo', '13', '扌', '左右', NULL, '搞〈动〉 形声。从手,高声。本义做,干,办,弄 同本义 你们这里的事我搞不来,你们不是革命,是胡闹。；组词：搞得不坏；搞价(商议价钱) 进行；开展 暗中使用 拟订 生产 玩弄 挣 设法得到 使...变成--后面接补语 搞gǎo做', '小学', '1'),
    ('搪', 'táng', '13', '扌', '左右', NULL, '搪〈动〉 (形声。从手,唐声。本义张) 同本义 搪,张也。--《方言十三》。郭注谓彀张也。” 抵挡 斗不数合,小龙委实难塘。--《西游记》。；组词：搪不住风雨；搪拒(抵御,抗拒)；搪撑(牴触)；搪报(紧急军情报告)；搪撞(冲撞,冒犯)；搪击(抗击)；搪突(冒犯；抵触', '小学', '1'),
    ('搬', 'bān', '13', '扌', '左右', NULL, '搬 (形声。从手,般声。本义挪动) 同本义 师见僧搬土次,乃以一块土放僧担上。--《五灯会元·文益禅师》；组词：搬起石头打自己的脚；把货物搬走；他早就搬走了；搬场(迁居) 套用,移用 搬请；求助 挑拨 扮演 搬 bān 1移动物体的', '小学', '1'),
    ('搭', 'dā', '12', '扌', '左右', NULL, '搭 (形声。从手,莈声。本义打,击) 同本义 常于并州市搭杀人者。--《北齐书·神武纪》；组词：搭面(抽打面部)；扑搭；搭墩(跌坐) 披；挂；戴 行者的眼乖,见他屋檐下,有一条搭衣的绳子', '小学', '1'),
    ('携', 'xié', '13', '扌', '左右', NULL, '携 (形声。从手,隽声。本义提着) 同本义(把地上的物品举提起来) 携,提也。--《说文》 如璋如圭,如取如携。--《诗·大雅·板》；组词：携壶；携带(提挈,照顾)；携酒牵羊；携杖 拿着,持 闲携杖,漫出门,官槐满路叶纷纷', '小学', '1'),
    ('摄', 'shè', '13', '扌', '左右', NULL, '摄 (形声。从手,聂声。本义牵曳) 同本义 摄,引持也。--《说文》 摄车从之。--《左传·襄公二十三年》；组词：摄力(引力)；摄弓(张弓注矢作射击准备)；摄水(引水) 执；持 庭实皮,则摄之', '小学', '1'),
    ('摆', 'bǎi', '13', '扌', '左右', NULL, '摆 (形声。从手,罢声。本义撇开;摆脱) 同本义 何当摆俗累,浩荡乘沧溟?--杜甫《桥陵》；组词：摆落(摆脱) 排列；放置 说话时,已摆了茶果子来', '小学', '1'),
    ('摇', 'yáo', '13', '扌', '左右', NULL, '摇 (形声。从手,本义摇动;摆动) 同本义 摇,动也。--《说文》 摇,作也。--《尔雅》 摇者不定。--《管子·心术》 复命摇作。--《庄子·则阳》 夹而摇之；组词：摇旗打鼓(四处张扬,闹得满城风雨)；摇铃打鼓(摇旗打鼓)；摇飍(亿颤动', '小学', '1'),
    ('摊', 'tān', '13', '扌', '左右', NULL, '摊〈动〉 (形声。从手,难声。本义平铺) 同本义 摊派 分摊(分担) 把糊状食物倒在锅中使成为薄片 摊 〈名〉 摊子 古代 摊(攤)tān 1.展开,摆开~开。把意见~出来', '小学', '1'),
    ('摔', 'shuāi', '14', '扌', '左右', NULL, '摔 (形声。从手,率声。本义用力扔在地上) 同本义 盛酒瓮摔做碎瓷瓯。--元·康进之《李逵负荆》 小王把书包往地上一摔,气呼呼地走了；组词：摔丧驾灵(即摔盆引灵', '小学', '1'),
    ('摘', 'zhāi', '14', '扌', '左右', NULL, '摘 (形声。小篆字形,从手,啻声。本义用手采下或取下) 同本义 摘,摭果树实也。--《说文》 摘,取也。--《广雅》 一摘使瓜好,再摘令瓜稀。--《新唐书·承天皇帝传》 以摘之；组词：摘胆剜心(形容杀人者的凶残)；摘肩儿(摘下肩上的担子)；摘青(谓果实等未成熟即采摘)；摘瓜抱蔓(喻一扫而空)；摘桃子(比', '小学', '1'),
    ('摧', 'cuī', '14', '扌', '左右', NULL, '摧 (形声。从手,崔声。本义折断) 同本义 先祖于摧。--《诗·大雅·云汉》 商旅不行,樯倾楫摧。--范仲淹《岳阳楼记》；组词：摧折(折断毁坏)；摧剥(摧折剥落)；摧烧(折断而投于火中烧毁) 摧毁,破坏,毁坏 列缺霹雳,上峦崩摧', '小学', '1'),
    ('摩', 'mó', '15', '手', NULL, NULL, '摩 (形声。从手,麻声。本义摩擦,磨蹭) 同本义 摩,研也。--《说文》 刮摩之工。--《考工记》 鎋击摩车而相过。--《战国策·齐策》 人肩摩。--《战国策·秦策》 濯手以摩之；组词：摩戛(摩擦', '小学', '1'),
    ('摸', 'mō', '13', '扌', '左右', NULL, '摸 (形声。从手,莫声。本义用手接触或轻摩物体) 同本义 邕读(曹娥碑),能手摸其文读之。；组词：摸脸；摸摸她的手；这衣料摸着很软；摸索(抚摩,以手接触)；摸挲(亦作摸娑”', '小学', '1'),
    ('摹', 'mó', '14', '手', '上下', NULL, '摹 (形声。从手,莫声。本义临摹,照着样子描画、写字) 同本义 摹,规也。--《说文》。段注摹与模义略同。” 规摹宏远矣。--《汉书·高帝纪下》。邓展曰若画工规摹物之摹；组词：摹帖(摹字', '小学', '1'),
    ('撇', 'piě', '14', '扌', '左右', NULL, '撇〈动〉 (形声。从手,敝声。本义抛弃,弃置不顾) 同本义 我弟兄两个,便去镇上撇呵卖药,教使枪棒。；组词：撇骨池(寺院中专供抛撒骨灰的池塘)；撇脱些(方言', '小学', '1'),
    ('撑', 'chēng', '15', '扌', '左右', NULL, '撑 (形声。从手,掌声。本义支撑,支持) 同本义 天津流水波赤血,白骨相撑如乱麻。--李白《扶风豪士歌》；组词：用两手撑着下巴；撑扶(支撑扶持)；撑天拄地(喻顶天立地) 用篙抵住河底使船行进 维持,保持 他死活也得把这个门面撑着 两', '小学', '1'),
    ('撒', 'sā', '15', '扌', '左右', NULL, '撒〈动〉 抛开;放开 说着先就撒马前去。--《红楼梦》 又如撒开(张开,放开;撇开,散开);撒口(放松口气);撒开鸭子(放开腿脚);撒步(放开脚步);撒鸭子(放开脚步快走)；组词：撒开(张开,放开；撇开,散开)；撒口(放松口气)；撒开鸭子(放开腿脚)；撒步(放开脚步)；撒鸭子(放开脚步快走)；撒花开', '小学', '1'),
    ('撕', 'sī', '15', '扌', '左右', NULL, '撕 (形声。从手,斯声。斯”也有表意作用,劈开”。本义扯裂) 同本义 晴雯果然接过来,嗤”的一声,撕了两半。；组词：把纸撕成条儿；把墙上的标语撕下来；把一张报纸撕成两半；上衣在钉子上撕了一个口子；撕打(撕搏', '小学', '1'),
    ('撞', 'zhuàng', '15', '扌', '左右', NULL, '撞 (形声。从手,童声。本义撞击) 同本义 撞,乵捣也。--《说文》。字亦作揰,作摐。 善待问者如撞钟。--《礼记·学记》。犹击也。 摐金鼓。--司马相如《子虚赋》 撞洪钟；组词：撞跌(撞头跺脚)；撞木(敲击钟磬之木)；撞舂(撞击；冲击)；撞筵(撞钟的木枝) 遇上,碰到 撞zhuàng 1.敲击~钟', '小学', '1'),
    ('撤', 'chè', '15', '扌', '左中右', NULL, '撤 (形声。从手声。本义撤去) 同本义 撤屏视之,一人、一桌、一椅、一扇、一抚尺而已。--《虞初新志·秋声诗自序》；组词：撤酒席；撤火(撤去炉火)；撤帘(帝制时代,由太后代天子执政,叫垂帘', '小学', '1'),
    ('撩', 'liáo', '15', '扌', '左右', NULL, '撩〈动〉 揭起,向上掀起 用手舀水浇洒 撩〈动〉 (形声。从手,尞声。本义整理) 同本义 撩,理也。；组词：撩治(处理,料理)；撩理(整理；照料；逗引)；撩虎须(捋虎须', '小学', '1'),
    ('撬', 'qiào', '15', '扌', '左右', NULL, '撬〈动〉 (形声。从手,毳声。本义翘起。举起) 同本义 以物拨开或挑开;用金属或木杠子把东西顶起来 剥夺...的工作 撬qiào用棍、棒等拨、挑~门。~石头。', '小学', '1'),
    ('播', 'bō', '15', '扌', '左右', NULL, '播 (形声。从手,番声。本义撒种) 同本义 播,种也。--《说文》 其始播百谷。--《诗·豳风 ·七月》 播时百谷,--《书·舜典》 周弃能播殖百谷蔬。--《国语·郑语》；组词：条播；夏播；播田(种田；种植)；播植(播种；种植)；播谷(播种谷物) 散布开去,散布得开而远；传布 播于诸侯', '小学', '1'),
    ('撮', 'cuō', '15', '扌', '左右', NULL, '撮 (形声。从手,最声。本义用手指抓取粒状物) 用三指取物;抓取 撮,四圭也,一曰两指撮也。；组词：撮一点儿盐；撮药(抓药)；撮土(抓一把土)；撮拾(撮取)；撮台子(拾掇桌子) 把聚拢的东西用簸箕等物铲起 拉拢 玩弄 簇', '小学', '1'),
    ('撰', 'zhuàn', '15', '扌', '左右', NULL, '撰 (形声。从手,巽声。本义写作,纂集成整体) 同本义 隐士休歌紫芝曲,词人解撰河清颂。--杜甫《洗兵马》 撰长书以为贽。--明·宋濂《送东阳马生序》；组词：撰文(写文章)；撰次(写作；记述)；撰刻(撰写而勒刻)；撰修(书写', '小学', '1'),
    ('撵', 'niǎn', '15', '扌', '左右', NULL, '撵 (形声。从手,辇声。本义驱逐) 同本义 你趁早与我出去,我不着丫头撵你。--《金瓶梅》；组词：撵山(闯山,在山上转)；撵逐(驱逐)；撵他下台；撵蹿(赶走)；把孩子撵回屋；把猪撵进圈；你不好好干活,老板会撵你；把人撵', '小学', '1'),
    ('撼', 'hàn', '16', '扌', '左右', NULL, '撼 (形声。从手,感声。本义摇动;动摇) 同本义 撼,动也。--《广雅》 蚍蜉撼大树,可笑不自量。--韩愈《调张籍》 撼山易,撼岳家军难。--《宋史·岳飞传》；组词：撼落(摇落)；撼摇(摇动,动摇)；撼顿(摇动,颠踬) 撼hàn摇动震天~地', '小学', '1'),
    ('擂', 'lèi', '16', '扌', '左右', NULL, '擂 将某物(如石头)从上处滚下来以打击敌人 礌石相击。--《汉书·司马相如传上》。师古曰礌石,转石也。” 擂石车。--《新唐书·李光弼传》 祑,推石自高而下也', '小学', '1'),
    ('擅', 'shàn', '16', '扌', '左右', NULL, '擅〈动〉 (形声。从手,亶声。本义独揽,专权) 同本义 擅,专也。--《说文》。按,谓媾壹也。 权臣擅命也。--《诗·狡童序》 擅将其兵。--《史记·魏豹彭越传》 今乱世之君臣；组词：擅恣(专权放肆)；擅政(独揽朝政)；擅柄(独揽权柄)；擅朝(独揽朝政) 占有,据有 方五百里,赵独擅之', '小学', '1'),
    ('操', 'cāo', '16', '扌', '左右', NULL, '操 (形声。从手)声。本义拿着,握在手里) 同本义 操,把持也。--《说文》 操右契。--《礼记·曲礼》 不学操缦。--《礼记·学记》 盖以操之为巳蹙矣；组词：可操左券；同室操戈(兄弟相残或内部纷争)；操刀(持刀；执刀) 引申为掌握 操杀生之柄', '小学', '1'),
    ('擎', 'qíng', '16', '手', '上下', NULL, '擎〈动〉 举 与翠叶并擎。--明·李渔《亲情偶寄·种植部》 又如擎赍(拿着);擎奇(举,持);擎拳(举拳);众擎易举 支撑,承受住压力 力量) 执持 今朝擎剑去；组词：擎赍(拿着)；擎奇(举,持)；擎拳(举拳)；众擎易举 支撑,承受住压力 力量) 执持 今朝擎剑去,何日刺蛟回?--李贺《', '小学', '1'),
    ('擒', 'qín', '15', '扌', '左右', NULL, '擒〈动〉 (形声。从手,禽声。本义捕捉。古籍本作禽”) 同本义 射人先射马,擒贼先擒王。--杜甫《前出塞》诗之六；组词：擒捕(捕捉)；擒捉(捕捉)；擒讨(擒获处治) 捉拿 大敌之擒也', '小学', '1'),
    ('擦', 'cā', '17', '扌', '左右', NULL, '擦 (形声。从手,察声。本义摩擦) 同本义 那块铁...擦擦儿筋伤!--《西游记》 又如擦背(方言。搓澡);擦肩(肩膀相摩);擦拳磨掌(即摩拳擦掌”；组词：擦背(方言', '小学', '1'),
    ('攀', 'pān', '19', '手', '上下', NULL, '攀〈动〉 (形声。从手,樊声。本义拉,牵) 同本义 攀,引也。--《广雅》 右手攀右趾。--明·魏学洢《核舟记》；组词：攀恋(攀住车辕,恋恋不舍)；攀辕(拉住车把) 攀援,指用握住或抓住某物的方法爬或登 将士皆攀木援崖,鱼贯而进', '小学', '1'),
    ('攒', 'zǎn', '19', '扌', '左右', NULL, '攒 cuan 簇拥;围聚;聚集 攒,聚也。--《广韵》 攒,族聚也。--《韵会》 攒珍宝之玩好。--张衡《西京赋》 攒戾莎。--《汉书·司马相如传上》 复叠攒仄；组词：万头攒动；万箭攒心；攒簇(聚集；簇拥)；攒绕(聚集围绕)；攒仄(重叠相连)；攒蛾(皱眉) 结算 装配起来 拿；取 攒 待', '小学', '1'),
    ('攘', 'rǎng', '20', '扌', '左右', NULL, '攘 (形声。从手,襄声。本义推让,退让) 同本义 攘,推也。--《说文》。谓推手使前拱揖之容也,字亦作儴。 左右攘辟。--《礼记·曲礼上》 小子何敢攘焉', '小学', '1'),
    ('支', 'zhī', '4', '支', '上下', NULL, '支 (会意。小篆字形,上面是竹”的一半,下面是手(又)。《说文》从手持半竹。”本义去枝的竹子)；组词：支调(枝节)；支蘖(枝条,旁生树枝)；支辅(辅助枝叶) 分支 封弟子功臣自为支辅', '小学', '1'),
    ('收', 'shōu', '6', '攵', '左右', NULL, '收 (形声。从攴,收声) 同本义 收,捕也。--《说文》 女反收之。--《诗·大雅·瞻卬》。传拘收也。” 单于壮其节,朝夕遣人候问武,而收系张胜；组词：收领(捉拿)；收系(逮捕下狱)；收付(拘捕罪犯,交付办案)；收考(拘捕考问)；收夷(捕杀)；收劾(拘捕弹劾)；收案(拘捕', '小学', '1'),
    ('改', 'gǎi', '7', '攵', '左右', NULL, '改〈动〉 (会意。甲骨文字形,左边是己”,象一个跪着的小孩子;右边是攴”,象以手持杖或执鞭。表示教子改过归正之意。本义 改变)', '小学', '1'),
    ('攻', 'gōng', '7', '攵', '左右', NULL, '攻 (形声。从攴,工声。本义进攻,攻打) 同本义(与守”相对) 攻,击也。--《说文》 攻灵公于桃园。--《左传·宣公二年》 宽则两军相攻。--《战国策·秦策》 以此攻城；组词：攻车(古代的一种兵车', '小学', '1'),
    ('放', 'fàng', '8', '攵', '左右', NULL, '放〈动〉 (形声。从攴,方声。本义驱逐,流放) 同本义 放,逐也。--《说文》 见伯夷之放迹。--《楚辞·悲回风》 卿大夫外淫者放。--刘向《列女传》 放髈兜于崇山；组词：流放(把犯人驱逐到边远地方去)；放伐(以武力讨伐并放逐暴君)；放徒(放野', '小学', '1'),
    ('政', 'zhèng', '9', '攵', '左右', NULL, '政 (会意兼形声。从攴从正,正亦声。攴敲击。统治者靠皮鞭来推行其政治。正”是光明正大。本义匡正)；组词：正己 主持政事 盖善政者,视俗而施教,察失而立防,威德更兴,文武迭用', '小学', '1'),
    ('故', 'gù', '9', '攵', '左右', NULL, '故〈名〉 (形声。从攴,古声。从攴”,取役使之意。本义缘故,原因) 同本义 故,使为之也。；组词：借故(托故', '小学', '1'),
    ('效', 'xiào', '10', '攵', '左右', NULL, '效 (形声。从攴,交声。攴”有致力的意思。本义献出;尽力) 同本义 司城荡意诸来奔,效节于府人而出。；组词：效力；效绩(呈献功绩)；效玺(呈献国君的印章,表示臣服)；效己(贡献一己之力)；效芹(自称贡献微薄) 明白 由此效之也', '小学', '1'),
    ('敌', 'dí', '10', '攵', '左右', NULL, '敌 (形声。从攴,啇声。本义匹敌;对等) 同本义 敌,仇也。--《说文》 敌,匹也。--《尔雅》 四国之兵敌。--《战国策·秦策》。注强弱等也。” 且夫自敌以下；组词：试看天下谁能敌；敌体(彼此地位相等,不分上下)；敌礼(平等的礼节)；匹敌(谓才艺相当)；势均力敌 抵抗；抵挡 (司马懿)', '小学', '1'),
    ('敏', 'mǐn', '11', '攵', '左右', NULL, '敏 (形声。从攴,每声。甲骨文字形,像用手整理头发的样子。本义动作快) 同本义 敏,疾也。；组词：敏给(敏捷)；敏赡(敏捷而多智)；敏睿(敏捷聪慧)；敏疾(敏捷,迅速)；敏思(才思敏捷)；敏才(敏捷的才思) 思想敏锐,', '小学', '1'),
    ('救', 'jiù', '11', '攵', '左右', NULL, '救 (形声。从攴,轻轻敲击,求声。本义止;禁止;阻止) 同本义 救,止也。--《说文》 救,犹禁也。以礼防禁人之过者也。--《周礼·司救》注 使之相救。--《周礼·大司徒》。注救；组词：救止(阻止；纠正)；救祸(消除祸乱)；救灭(扑灭)；救熄(亦作救息”', '小学', '1'),
    ('教', 'jiào', '11', '攵', '左右', NULL, '教〈动〉 把知识和技能传授给别人 十三教汝织。--《玉台新咏·古诗为焦仲卿妻作》 教其不知,而恤其不足。--《左传》；组词：教课；教书；手把手教；教唱歌；教倌(教入塾)；教老者(方言,教员)；教率(教授引导)；教书匠(对教师的谑称) 使；令；让', '小学', '1'),
    ('敛', 'liǎn', '11', '攵', '左右', NULL, '敛 (形声。从攴,佥。本义收集,聚集) 同本义(收集的对象是物,常是财物) 敛,收也。--《说文》 既射则敛之。--《周礼·夏官·缮人》。注敛,藏也。” 狗彘食人之食不知敛；组词：敛局(邀人聚赌,从中抽头)；敛衣(聚集零碎布头所制成的衣服) 收获 自种自敛,服箱以走', '小学', '1'),
    ('敞', 'chǎng', '12', '攵', '左右', NULL, '敞 将高起的土地筑成平台,用以远望 同本义 敞,平治高土,可以远望也。--《说文》 张开,敞开 显露;露出 奇踪隐五百,一朝敞神界。--陶潜《桃花源诗》 敞 (形声。从攴,尚声；组词：敞平(宽阔平坦)；敞阔(宽阔清静) 随便 敞 chǎng 1宽绰；无遮掩这个地方真宽~', '小学', '1'),
    ('敢', 'gǎn', '11', '攵', NULL, NULL, '敢 (会意。本义勇敢,有胆量) 同本义 敢,进取也。--《说文》 敢,勇也。--《广雅》 信理遂惔谓之敢。--《贾子道术》 洁廉而果敢者也。--《大戴礼记·文王官人》；组词：敢毅(勇敢刚毅)；敢士(勇士)；敢直(果敢正直)；敢勇(果敢英 敢gǎn 1.有勇气,有胆量勇~', '小学', '1'),
    ('散', 'sàn', '12', '攵', NULL, NULL, '散 逍遥,懒散 庸众驽散。--《荀子·脩身》。注散,不拘检者也。” 又如懒散;散人(闲散无用或不为世用的人◇多指隐士);散袒(假日;消闲);散旦(散弹,散诞。舒散;不受拘束)；组词：懒散；散人(闲散无用或不为世用的人◇多指隐士)；散袒(假日；消闲)；散旦(散弹,散诞', '小学', '1'),
    ('敦', 'dūn', '12', '攵', '左右', NULL, '敦 (形声。从攴”,表示与以手持械的动作有关。本义投掷) 厚道。诚朴宽厚;厚重;笃实 说礼乐而敦诗书。；组词：敦雅(敦厚文雅)；敦固(敦厚巩固)；敦笃(敦厚笃实)；敦勉(敦厚勤勉)；敦至(笃实周全)；敦善(敦良,敦厚善良) 厚实', '小学', '1'),
    ('敬', 'jìng', '12', '攵', '左右', NULL, '敬 (会意。从攴,以手执杖或执鞭,表示敲打,从苟,有紧急、急迫之义。本义恭敬;端肃。恭在外表,敬存内心)；组词：敬让(恭敬谦让)；敬诚缉熙(恭敬诚实而光明)；敬jìng 1.尊重,热爱,仰慕,佩服尊~', '小学', '1'),
    ('数', 'shù', '13', '攵', '左右', NULL, '数 (形声。从攴,娄声。本义点数;计算) 同本义 數,计也。--《说文》 以岁之上下数邦用。--《周礼·廪人》 递数之不能终其物。--《礼记·儒行》 善数不用筹策；组词：从一数到十；数拾(查点；收拾)；数白道黑(卖弄口舌)；数白论黄(计较银钱', '小学', '1'),
    ('敲', 'qiāo', '14', '攴', '左右', NULL, '敲 (形声。从攴,高声。攴,轻击。象手(又)拿小棍轻击的样子。本义敲击,叩打) 同本义 敲,击头也。；组词：敲扑(拷打)；敲丝(银子', '小学', '1'),
    ('整', 'zhěng', '16', '攵', '上下', NULL, '整 (会意兼形声。从攴从束从正,正亦声。攴是敲打,束是约束,使之归于正∠起来表示整齐。本义整齐)；组词：整娖(整齐,条理分明)；整立(整齐地矗立)；整扮(打扮整齐)；整设(整齐阵列)；整蔚(整齐而华丽) 端正,端庄 王夷甫容', '小学', '1'),
    ('敷', 'fū', '15', '攵', '左右', NULL, '敷〈动〉 (形声。从攴,表示与动作有关。搏”是布列”的意思,在字中也具有表意作用。本义施予;给予)；组词：敷民(施于人民', '小学', '1'),
    ('文', 'wén', '4', '文', '上下', NULL, '文 (象形。甲骨文此字象纹理纵横交错形。文”是汉字的一个部首。本义花纹;纹理) 同本义 文,错画也。象交文。今字作纹。；组词：文驾(彩车)；文斑(杂色的斑纹)；文旆(有文彩的旗帜)；文绣(绣有彩色花纹的丝织品；刺花图案)；文织(有 文wén 1.', '小学', '1'),
    ('斋', 'zhāi', '10', '文', '上下', NULL, '斋 (形声。从示,斎齐省声。本义斋戒,旧指祭祀前整洁身心) 同本义 斋,戒洁也。--《说文》 王斋日三举。盖王日一举。--《周礼·膳夫》 日中及夕则馂余斋,则每食一太牢也；组词：斋宿(先一日斋戒,以表诚敬)；斋沐(斋戒沐浴)；斋事(斋戒祭祀的事)；斋舍(古人斋戒时的居所)；斋牛(供祭祀用的牛)', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('斑', 'bān', '12', '文', '左中右', NULL, '斑 (形声。本作班”,从文,辡声。本义杂色的花纹或斑点) 同本义 辬,驳文也。--《说文》。徐锴曰今作斑也。” 管中窥豹,时见一斑。--《晋书·王献之传》 唯余望乡泪,更染竹成斑；组词：汗斑；斑马；斑污(斑点污渍)；雀斑；豹子的斑；油斑 通班”', '小学', '1'),
    ('斗', 'dòu', '4', '斗', NULL, NULL, '斗 (象形。甲骨文字形,象两人怒发对打形。本义搏斗) 搏斗;引申为战斗 魕,两士相对,兵杖在后,象魕之形。；组词：拳斗；械斗；格斗(紧张激烈地搏斗)；斗心(战斗的意志)；斗臣(勇健善斗之士)；钩心斗角(屋角由屋心伸出来,像与屋心钩在一', '小学', '1'),
    ('料', 'liào', '10', '斗', '左右', NULL, '料〈动〉 (会意。从斗,从米,表示用斗量米。本义称量) 计数;计量;核计 料,量也。从斗,米在其中,会意。；组词：料校(计数检核)；料民(计点人数)；料数(计数)；料算(估算) 估量；揣度；料想 捭之者,料其情也', '小学', '1'),
    ('斜', 'xié', '11', '斗', '左右', NULL, '斜 (形声。从斗,余声。本义用斗倒出) 舀出 斜,抒也。--《说文》 又如斜酒(舀酒) 侧着移动,向偏离正中或正前方的方向移动 门子才斜签着坐下；组词：斜酒(舀酒) 侧着移动,向偏离正中或正前方的方向移动 门子才斜签着坐下', '小学', '1'),
    ('斟', 'zhēn', '13', '斗', '左右', NULL, '斟 (形声。从斗,甚声。本义用勺子舀取) 同本义 斟,勺也。--《说文》 斟,酌也。--《广雅》 孔子穷乎陈蔡之间,藜羹不斟,七日不尝粒。--《吕氏春秋》 太行何艰哉,北斗不可斟；组词：斟酒；斟一杯水；斟泻(倾注)；斟茶；给她斟一杯酒 考虑,考虑好坏,比较长短 斟量功伐', '小学', '1'),
    ('斤', 'jīn', '4', '斤', NULL, NULL, '斤〈名〉 (象形。甲骨文字形,上面是横刃,下为曲柄,象斧斤形。本义斧子一类的工具) 同本义 今,斫木斧也。；组词：斤斧(斧头)；斤墨(斧头与墨斗)；斤凿(斧头与凿子) 古代一种似锄但比锄小的农具 恶金以铸锄、夷、斤...--《国语》', '小学', '1'),
    ('斥', 'chì', '5', '斤', NULL, NULL, '斥 (形声。从广,屰声。从广”,表示与房屋有关。屰”(不顺)也兼表字义,表示人从房屋里逆行而出。本义驱逐)；组词：斥放(斥退放逐)；斥遣(斥退,驱逐)；斥远(摒拒疏远)；斥去(排斥并使之离去) 责备', '小学', '1'),
    ('斧', 'fǔ', '8', '斤', '上下', NULL, '斧〈名〉 (形声。从斤(斧头),父声。本义斧子,伐木工具) 同本义 斧,斫也。--《说文》 丧其资斧。--《易·巽卦》。注斧,所以断者也。” 既破我斧；组词：斧柯(斧柄；斧头与斧柄；做媒)；斧脑(斧之背)；斧砧(古代刑具)；斧绣(持斧绣衣', '小学', '1'),
    ('斩', 'zhǎn', '8', '斤', '左右', NULL, '斩 (会意。从车,从斤。古有车裂”之刑,故从车。斤,斧子,可用于杀人。本义古代死刑的一种。斩首或腰斩;杀)', '小学', '1'),
    ('断', 'duàn', '11', '斤', NULL, NULL, '断 (会意。本义截断,截开) 同本义 断,截也。--《说文》 断木为杵。--《易·系辞下》 三日断五匹,大人故嫌迟。--《玉台新咏·古诗为焦仲卿妻作》 公孙弘断发而为越王骑；组词：断梗(断枝', '小学', '1'),
    ('斯', 'sī', '12', '斤', '左右', NULL, '斯 (会意。从斤,其声。其所以盛木柿。斤,斧子。本义劈;砍) 同本义 斯,析也。--《说文》 墓门有棘,斧以斯之。--《诗·陈风·墓门》 有斯明享。--《书·酒诰》。郑注析也', '小学', '1'),
    ('新', 'xīn', '13', '斤', '左右', NULL, '新〈动〉 (形声。从斤,从木,辛声。据甲骨文,左边是木,右边是斧子。指用斧子砍伐木材。本义用斧子砍伐木材。新”是薪”的本字) 砍伐树木 新,取木也。；组词：新民(使民更新)；新美(刷新使之美好)；新醮(改嫁)；新梢(新长出的树梢) 新 〈形〉 初次出现', '小学', '1'),
    ('方', 'fāng', '4', '方', NULL, NULL, '方〈动〉 (象形。下从舟省,而上有竝头之象。故知并船为本义。本义并行的两船;泛指并列;并行)；组词：方轨(两车并排行驶)；方轩(并排的窗户) 等同；相当 方 fāng 1.四角都是直角的四边形或每个面都是直角四边形的六面', '小学', '1'),
    ('施', 'shī', '9', '方', '左右', NULL, '施 (形声。从,也声。本指旗帜) 旗飘动 旖施,柔顺摇曳之貌。--《说文》朱骏声通训定声 施,旗貌。--《说文》 旖旎(施)从风。--《史记·司马相如传》。索隐犹阿那也', '小学', '1'),
    ('旁', 'páng', '10', '方', '上下', NULL, '旁 bang (古通傍”) 依傍;依附 匈奴大发十余万骑,南旁塞至符奚庐山。--《汉书·赵充国传》；组词：旁沿(依附沿袭)；旁缘(依仗) 靠近 吾灵尚依依旁汝也', '小学', '1'),
    ('旅', 'lǚ', '10', '方', NULL, NULL, '旅〈名〉 (会意。甲骨文字形,象众人站在旗下。旗,指军旗;人,指士兵。小篆字形,表示旌旗;从从”,表示众人,即士兵。本义古代军队五百人为一旅) 军队编制单位。上古一般以五百人为旅；组词：旅长；两旅兵 军队 加之以师旅', '小学', '1'),
    ('旋', 'xuán', '11', '方', NULL, NULL, '旋 同本义 旋,周旋,旌旗之指麾也。--《说文》 旋入雷渊。--《楚辞·招魂》。注旋,转也。” 旋式正綦。--《史记·日者列传》。索隐旋,转也。” 鲵旋之潘为渊；组词：旋辟(进退周旋,环绕)；旋式(转动罗盘 旋xuán 1.转动,弯转~转', '小学', '1'),
    ('族', 'zú', '11', '方', NULL, NULL, '族 (会意。本义箭头) 同本义 族,矢锋也。束之族族也。--《说文》。 家族,氏族 克明俊德,以亲九族。--《书·尧典》。陆德明释文上自高祖,下至玄孙,凡九族。”；组词：大族(人口多、分支繁的家族)；族氏(宗族姓氏)；族正(清时聚族而居的地方；挑选族中地位名望最高的人主持和裁决本族事务,名', '小学', '1'),
    ('旗', 'qí', '14', '方', NULL, NULL, '旗〈名〉 同本义 旗,熊旗五游,以象罚星,士卒以为期。--《说文》 熊虎曰旗。--《广雅》 师都建旗。--《周礼·春官》 熊虎为旗及国之大阅。--《周礼·司常》 望其旗靡；组词：旗纛(古代军队和仪仗队用的大旗)；旗牌(担任传递号令等的武吏)；旗鼓(指枪棒等武艺的架式、门户)；旗头(旗手)；旗麾(将', '小学', '1'),
    ('无', 'wú', '4', '无', '上下', NULL, '无 (会意。据甲骨文字形,象一个人持把在跳舞。卜辞、金文中无、舞”同字。本义乐舞) 同本义 哲学范畴,指无形、无名、虚无等,或指物质的隐微状态 天下万物生于有,有生于无。', '小学', '1'),
    ('既', 'jì', '9', '旡', NULL, NULL, '既 (会意。甲骨文字形,左边是食器的形状,右边象一人吃罢而掉转身体将要离开的样子。本义吃罢,吃过)', '小学', '1'),
    ('日', 'rì', '4', '日', '全包围', NULL, '日 (象形。甲骨文和小篆字形。象太阳形。轮廓象太阳的圆形,一横或一点表示太阳的光。本义太阳)；组词：日冠(太阳上方的光体)；日昃(日斜,日过中午)；日昫儿(太阳；日光)；日月交食(对头；互相争斗)；日头搁山(太阳落山)', '小学', '1'),
    ('旦', 'dàn', '5', '日', '上下', NULL, '旦 (指事。甲骨文字形,象太阳从地面刚刚升起的样子。本义天亮,破晓,夜刚尽日初出时) 同本义 女曰鸡鸣”,士曰昧旦”。；组词：旦日(天亮时)；旦明(天亮时) 早晨 旦夕得甘毳以养亲', '小学', '1'),
    ('旧', 'jiù', '5', '日', '左右', NULL, '旧 (形声。甲骨文字形,上面是萑”,鸱鸟类;下面是臼”,作声符。本义鸟名) 鸺鷙,即猫头鹰 故交,老交情 待之若旧。--南朝梁·丘迟《与陈伯之书》 与之有旧；组词：怀旧；有旧；念旧；亲戚故旧；旧雨 原有的典章制度 不必循旧', '小学', '1'),
    ('旨', 'zhǐ', '6', '日', '上下', NULL, '旨 (会意。甲骨文字形。上象匕”即匙形,下面是口,以匙入口,表示味道好。”口”隶变为日”。《说文》从甘,匕声。本义味美)；组词：旨甘(美好的食物)；旨味(美味)；旨肴(美味的菜肴) 美好 垂功烈而不刊,不亦旨哉!--柳宗元《与李睦州论服气书》 旨', '小学', '1'),
    ('早', 'zǎo', '6', '日', '上下', NULL, '早 (会意。小篆字形,上面是日”,下面是甲”。甲”的最早写法象十”,指皮开裂,或东西破裂。早”即天将破晓,太阳冲破黑暗而裂开涌出之意。本义早晨)；组词：清早(清晨)；明早(明天早上)；早出晚归(整日在外)；起早贪黑；早天(早晨的天空)；早角(早晨的号角声)；早zǎo 1', '小学', '1'),
    ('旬', 'xún', '6', '日', '半包围', NULL, '旬 (会意。从勹日。甲骨文,上为交叉记号,表示由此开始,后来引长内曲,表示回环周遍。金文又加日”。本义十日。古代天干纪日,每十日周而复始,称一旬)；组词：兼旬(两个十天)；旬期(十天)；旬修(十天之中所作所为)；旬首(一旬之始)；旬浃(满十天)；旬宴(古 旬xún 1.十天', '小学', '1'),
    ('旭', 'xù', '6', '日', '半包围', NULL, '旭 (形声。从日,九声。本义太阳初出的样子) 同本义 旭,日旦出貌。--《说文》 旭日始旦。--《诗·邶风·匏有苦叶》 方出旭旭。--《太玄·从》。注未明之间。” 欢来苦夕短；组词：旭旭(日将出的样子) 旭 初出的太阳,晨曦 光 玄门一掩,寒灯无旭', '小学', '1'),
    ('旱', 'hàn', '7', '日', '上下', NULL, '旱 (形声。从日,干声。本义久不下雨) 同本义 旱,不雨也。--《说文》 旱既大甚,蕴隆虫虫。--《诗·大雅·云汉》 不得雨曰旱。--《谷梁传·僖公十一年》 二谷不收谓之旱；组词：旱涝(干旱与水涝)；旱云(干旱不雨的云)；旱亢(大旱)；旱苗得雨(久旱的禾苗喜逢甘霖滋润) 非水田的 迅猛', '小学', '1'),
    ('时', 'shí', '7', '日', '左右', NULL, '时 (形声。从日,寺声。从日”与时间有关。本义季度;季节) 同本义 时,四时也。--《说文》 四时,四方各一时,时,期也。--《释名》 谓其三时不害。--《左传·桓公六年》', '小学', '1'),
    ('旷', 'kuàng', '7', '日', '左右', NULL, '旷 (会义兼形声。从日,广声。本义光明;明朗) 同本义 旷,明也。--《说文》 旷,光明也。--《玉篇》 此人谓照旷。--《庄子·天地》 旷若发矇。--《后汉书》；组词：旷旷(光明；明亮) 心境开阔,开朗 则有心旷神怡', '小学', '1'),
    ('旺', 'wàng', '8', '日', '左右', NULL, '旺 (形声。从日,王声。本义光美) 日晕 旺,日晕。--《玉篇》 旺 火势炽烈 翠环道屋里火盆旺着呢!快向屋里烘去罢!”--《老残游记》 兴旺;旺盛 旺 使兴旺 旺wàng盛', '小学', '1'),
    ('昂', 'áng', '8', '日', '上下', NULL, '昂〈动〉 (形声。从曰,卬声。本义仰起,抬起) 同本义 袒胸露乳,矫首昂视,神情与苏黄不属。--明·魏学洢《核舟记》 柳树得春风,一低复一昂。；组词：昂首(仰着头)；昂首挺胸(仰着头,挺起胸膛', '小学', '1'),
    ('昆', 'kūn', '8', '日', '上下', NULL, '昆〈副〉 (会意。从日,从比。金文字形,表示二人在日光下并肩行走 。本义一起,共同) 同本义 昆,同也。；组词：昆群(同群) 后,然后 魂兮归徕,正始昆只', '小学', '1'),
    ('昌', 'chāng', '8', '日', '上下', NULL, '昌 (会意。从日,从曰。本义善,正当) 同本义 昌,美言也。--《说文》 禹拜昌言。--《书·大禹谟》；组词：昌言(正直的善言、好话)；昌教(善美的教化) 兴旺发达,与亡”相对 邦乃其昌', '小学', '1'),
    ('明', 'míng', '8', '日', '左右', NULL, '明 (会意。甲骨文以日、月”发光表示明亮。小篆从月囧,从月,取月之光;从囧,取窗牖之明亮。本义明亮,清晰明亮)', '小学', '1'),
    ('昏', 'hūn', '8', '日', '上下', NULL, '昏 (会意。从日,从氐省。氐”是下的意思∠起来表示日已下沉。本义黄昏) 同本义 昏,日冥也。；组词：昏旦(黄昏和早上)；昏晚(天刚黑)；昏黄(暮色,天色暗淡) 昏 引申为昏暗；无光 秋天漠漠向昏黑', '小学', '1'),
    ('易', 'yì', '8', '日', '上下', NULL, '易 (象形。本义蜥易) 换,交换 寒暑易节。--《列子·汤问》 寡人欲以百里之地易安陵。--《战国策·魏策》 以大易小。 弗敢易。 易寡人之璧；组词：易筋经(讲武术的书,托名南朝梁代达摩和尚所作)；易箦(换竹席', '小学', '1'),
    ('昔', 'xī', '8', '日', '上下', NULL, '昔 (象形。象残肉日以晞之,与俎同意。本义干肉) 同本义 昔,干肉也。--《说文》 假借为昨。”从前;过去(与今”相对) 二曰昔酒。--《周礼·酒正》。挚 昔之人无闻知；组词：抚今追昔；今非昔比；今胜于昔；在昔(过去,从前)；昔来(往日以来)；昔士(古之贤人) 昨日 昔者 昔xī 1.从前,过去', '小学', '1'),
    ('昙', 'tán', '8', '日', '上下', NULL, '昙 密布的云气 昙摩。意为法,佛法 聃也,御寇也,周也,中国之释也,其于昙也,犹契也,印也,不约而同也。--明·徐渭《论中》 昙(曇)tán 1.多云,密布的云彩。 2.', '小学', '1'),
    ('星', 'xīng', '9', '日', '上下', NULL, '星 (象形。从晶,生声。晶象形。本义星星) 同本义 星,万物之精,上为列星。--《说文》。按,散文则统谓之星,对文则五纬为星,二十八宿为辰。 日月星辰。--《书·尧典》 四曰星辰；组词：星筹(寿算之筹)；星霜(比喻年月)；星桥(神话传说中的鹊桥', '小学', '1'),
    ('映', 'yìng', '9', '日', '左右', NULL, '映 (形声。从日,央声。本义照) 同本义 映,明也。--《说文新附》 日阴曰映。--《通俗文》 冠盖相映。--《后汉书·张衡传》 映日荷花别样红；组词：映耀(辉映；照耀)；映日(映照着日光)；辉映(照耀,映射) 反映,因光线照射而显出 狭石分花径,长桥映水门', '小学', '1'),
    ('春', 'chūn', '9', '日', NULL, NULL, '春 (会意。甲骨文字形,从草(木),草木春时生长;中间是屯”字,似草木破土而出,土上臃肿部分,即刚破土的胚芽形,表示春季万木生长;屯”亦兼作声符。小篆字形,隶变以后, 除日”之外', '小学', '1'),
    ('昧', 'mèi', '9', '日', '左右', NULL, '昧 (形声。从日,未声。从日,与光线有关。本义昏暗不明) 同本义 昧,冥也。--《广雅·释诂四》 时甲子昧爽。--《书·牧誓》 日昧昧其将暮；组词：昧旦(天未全亮的时候)；昧然(昏暗不明的样子) 昧mèi 1.暗幽~', '小学', '1'),
    ('昨', 'zuó', '9', '日', '左右', NULL, '昨 (形声。从日,乍声。本义隔夜,上一天) 同本义 昨,垒日也。--《说文》。按,絫日,从日,乍声。 昨,隔日也。--《苍颉篇》 夏日复昨。--《尔雅》 周昨来,有中道而呼者；组词：昨伲(昨日)；昨而子(今天的前一天)；昨日子(昨天)；昨几(昨天)；昨夜(昨天夜里)；昨宵(昨夜)；昨暝(昨晚) 泛指往', '小学', '1'),
    ('昭', 'zhāo', '9', '日', '左右', NULL, '昭 (形声。从日,召声。本义明亮) 同本义 昭,日明也。--《说文》 倬彼云汉,昭回于天。--《诗·大雅·云汉》 青春受谢,白日昭只。--《楚辞·大招》；组词：昭式(光明的法度)；昭列(光明)；昭衍(光明广布)；昭亮(明亮)；昭美(光明美好) 彰明,显著 所以昭炯戒', '小学', '1'),
    ('是', 'shì', '9', '日', '上下', NULL, '是 (会意。小篆字形,从日正。本义正,不偏斜) 同本义 是,直也。--《说文》。按,十目烛隐曰直,以日为正曰是。 而疑是精粗之体。--《礼记·玉藻》。疏谓正也。” 上九,濡其首', '小学', '1'),
    ('昵', 'nì', '9', '日', '左右', NULL, '昵 (形声。从日,尼声。字又作暱”。从日,匿声。本义亲近,亲昵) 同本义 暱,日近也。--《说文》 暱,近也。--《尔雅》。孙注亲之近也。” 无自暱焉；组词：昵交(亲近的朋友)；昵侍(近侍,亲侍)；昵就(亲近；亲昵)；昵友(亲密的朋友)；昵比(亲近勾结)；昵好(亲善)；昵近(亲', '小学', '1'),
    ('昼', 'zhòu', '9', '日', '半包围', NULL, '昼 (会意。从日,从畫(画)省。从日,表示太阳。从畫,表示一种界限。本义白天。与夜”相对)；组词：昼日昼夜(日日夜夜)；昼夕(日夜)；昼眠(白天睡眠；午睡)；昼锦(衣锦昼行的省称,称富贵还乡)；昼暮(日夜)；昼宵(白昼', '小学', '1'),
    ('显', 'xiǎn', '9', '日', '上下', NULL, '显 (会意。从页从显,显亦声。今字从页,与人头有联系。本义头上的装饰品) 同本义 显,头明饰也。；组词：显轿(没有顶篷、扶手的大椅式轿子', '小学', '1'),
    ('晃', 'huàng', '10', '日', '上下', NULL, '晃〈形〉 (会意。从日,光亦声。本义明亮) 同本义 晃,明也。--《说文》 晃,暉也。--《广雅·释言》 天晃朗以弥高兮。--潘岳《秋兴赋》 或晃朗而拓落。--左思《魏都赋》；组词：晃烂(明亮有光彩)；晃然(明亮的样子)；晃朗(晃晃,明亮的样子)；晃昱(明亮；辉煌) 引申为美俊 却怎睃趁着你头上放毫光', '小学', '1'),
    ('晋', 'jìn', '10', '日', '上下', NULL, '晋 (会意。小篆字形,从日。指追着太阳一直前进。本义上进) 进 晉,进也。日出,万物进。--《说文》 晋者,进也。--《易·序卦》 王提马而走诸侯晋；组词：晋谒(晋见；谒见)；晋接(进见；接见)；晋食(进献食品) 晋升', '小学', '1'),
    ('晌', 'shǎng', '10', '日', '左右', NULL, '晌〈名〉 正午或午时前后 白天 春兰!没晌没夜的,你干什么哩?--粱斌《红旗谱》 片刻,一会儿。泛指比较短的一段时间 半晌恰方言。--王实甫《西厢记》；组词：半晌(过了好一会儿)；一晌(指片刻,过了一些时间) 量词', '小学', '1'),
    ('晒', 'shai', '10', '日', '左右', NULL, '晒 (曬俗作晒。形声。左形,右声。本义在阳光下曝干或取暖) 暴晒;晒干 曬,暴也。--《说文》 暴五谷之类。晋秦之间谓之曬。--《方言七》 答曰我晒书；组词：太阳晒得人喘不过气来；晒衣服；晒席(晒谷物等用的席子)；晒暖(方言', '小学', '1'),
    ('晓', 'xiǎo', '10', '日', '左右', NULL, '晓 (象形。从日,尧声。本义天明) 同本义。今专指天刚亮 晓,明也。--《说文》 冥冥之中,独见晓焉。--《淮南子·俶真》 晓驾炭车辗冰辙。--唐·白居易《卖炭翁》 晓看红湿处；组词：破晓(刚亮)；拂晓(天快亮)；晓雾；晓舌(鸟拂晓叫)；晓暝(天将亮的时候)；晓行；晓鸡初啼；晓星；晓岚；鸡鸣报晓；晓夕(', '小学', '1'),
    ('晕', 'yūn', '10', '日', '上下', NULL, '晕 昏倒 魏老儿上了一夹棍,贾魏氏上了一拶子,两个人都晕绝过去。--《老残游记》 又如晕绝(昏厥);头晕(头脑昏乱);晕昏(昏迷);晕迷(昏眩) 晕 (形声。从日,军声；组词：晕绝(昏厥)；头晕(头脑昏乱)；晕昏(昏迷)；晕迷(昏眩) 晕 (形声', '小学', '1'),
    ('晚', 'wǎn', '11', '日', '左右', NULL, '晚 (形声。从日,免声。本义傍晚;黄昏) 同本义 晚,莫也。--《说文》 晚,暮也。--《广韵》 四时失序,则辰星作异。...政急则出蚤,政缓则出晚；组词：晚曦(晚霞)；晚夕(傍晚,晚上)；晚半天儿(晚夕,晚晌,晚间,晚上)；晚钟(傍晚的钟声)；晚寒(傍晚的寒气)；晚晴；晚饷', '小学', '1'),
    ('晤', 'wù', '11', '日', '左右', NULL, '晤 (形声。从日,吾声。日”表日光。本义聪明,明白) 同本义 晤,明也。--《说文》。段玉裁注晤者,启之明也。” 真宗英晤之主。--《宋史·真宗纪赞》 少秀晤,能治《尚书》；组词：晤君(面见君主；看见君王)；晤 晤wù 1.相遇,见面~面', '小学', '1'),
    ('晦', 'huì', '11', '日', '左右', NULL, '晦 (形声。从日,每声。本义阴历每月的最后一天) 同本义 晦,月尽也。--《说文》 三十日日月合宿,谓之晦。--《论衡·四讳》 陈不违晦。--《左传·成公十七年》 朝菌不知晦朔；组词：晦望(农历每月末一日与十五日)；晦景(晦日,晦节)；晦日(农历每月最后的一天) 夜；晚 晦淫惑疾', '小学', '1'),
    ('晨', 'chén', '11', '日', '上下', NULL, '晨 (会意。从臼,从辰,辰时也。辰亦声。本义星名。即房星) 清晨 晨,早昧爽也。--《说文》 晨,早也。--《尔雅》 夜乡晨。--《诗·小雅·庭燎》 昏定而晨省；组词：凌晨五时；霜晨；晨步(清晨散步)；晨省(早晨向父母问安)；晨安(早安)；晨暝(旦夕)；晨旭(朝日)；晨旦(天亮) 晨 c', '小学', '1'),
    ('普', 'pǔ', '12', '日', '上下', NULL, '普〈形〉 (会意兼形声。小篆字形,从日,从并。并”亦可以看作声。普”是二人并排站着。本义日无光)；组词：普席(全席)；普及本(即普及版)；普天(遍天下)；普加(普遍赐与；普遍施与)；普存(普遍富足)；普讯(遍 普pǔ 1.全', '小学', '1'),
    ('景', 'jǐng', '12', '日', '上下', NULL, '景 (形声。从日,京声。本义日光) 同本义 景,日光也。--《说文》 浊明外景,清明内景。--《荀子·解蔽》 四时和谓之景风。--《尔雅》 南方景风。--《广雅》。按,犹日光风也；组词：景曜(光彩)；景光(亮光)；景焕(光彩照射)；景辉(光辉) 太阳 景jǐng 1.日光耀~', '小学', '1'),
    ('晰', 'xī', '12', '日', '左右', NULL, '晰 光亮 日月沈晖,三光寝晰。--南朝宋·谢灵运《庐山慧远法师诔》 又如晰晰(光亮的样子) 清楚;明白 钱献之辨之甚晰。；组词：晰晰(光亮的样子) 清楚；明白 钱献之辨之甚晰', '小学', '1'),
    ('晴', 'qíng', '12', '日', '左右', NULL, '晴 (形声。从日,青声。青古指蓝色,也有表意作用。《说文》作夝”。意思是夜间(夕)雨止,出现星星。本义雨止无云,天气晴朗)；组词：晴岚(晴日山中的雾气)；放晴(阴雨后转晴)；晴川(晴天下的江面)；晴日( 晴qíng天空无云或云量很少,跟"阴"相对~天', '小学', '1'),
    ('晶', 'jīng', '12', '日', '上下', NULL, '晶 (会意。甲骨文字形,从三日,表示光亮之意。本义光亮,明亮) 同本义 晶,精光也。--《说文》。徐灏曰晶即星之象形文。” 天高日晶。--欧阳修《秋声赋》；组词：晶天(清澈明亮的天空)；晶沁(亮光透入)；晶英(光亮；闪亮)；晶波(闪亮的水波) 同精” 清明；晴朗 八月凉风天气晶,万', '小学', '1'),
    ('智', 'zhì', '12', '日', '上下', NULL, '智 (会意兼形声。从日,从知,知亦声。知”的后起字。本义聪明,智力强) 同本义 然后智生于忧患。；组词：智赛隋何,机强陆贾(二人均为汉、楚时代智囊人物', '小学', '1'),
    ('晾', 'liàng', '12', '日', '左右', NULL, '晾〈动〉 (形声。从日,京声。本义晒干) 同本义 把东西放在通风或阴凉的地方使干燥 搁置', '小学', '1'),
    ('暂', 'zàn', '12', '日', '上下', NULL, '暂 (形声。从日,斩声。从日,与时间有关。本义时间短) 同本义 暂,不久也。--《说文》 宇文新州之懿范,暫帷暂驻。--唐·王勃 《滕王阁序》 暂则封舱,久则封港；组词：暂劳(一时的劳苦)；暂欢(短时间的欢乐)；暂云(行云,浮云) 暂 暂时 但暂还家', '小学', '1'),
    ('暇', 'xiá', '13', '日', '左右', NULL, '暇 (形声。从日,叚声。本义空闲,闲暇) 同本义 暇,闲也。--《说文》 不敢自暇自逸。--《书·无逸》 好以瑕。--《左传·成公十六年》 救亡不暇；组词：暇时；暇刻(空闲的时间)；暇晷(空闲的时日)；暇景(空闲的时光) 暇 悠闲 久之,且似瞑,意暇甚', '小学', '1'),
    ('暑', 'shǔ', '12', '日', '上下', NULL, '暑 (形声。从日,者声。本义炎热) 同本义 暑,热也。--《说文》。暑近湿如蒸,热近燥如烘, 一寒一暑。--《易·系辞》 六月徂暑。--《诗·小雅·四月》 土润溽暑；组词：暑溽(夏天闷热的气候)；暑岁(炎热干旱的年岁)；暑夏( 暑shǔ炎热~天', '小学', '1'),
    ('暖', 'nuǎn', '13', '日', '左右', NULL, '暖 (形声。从日,爰声。煗”,从火,聏声。本义温度不冷也不热) 同本义 煖,温也。--《说文》。字亦作煗、作暖。 海多大风,冬煗。--《国语·鲁语上》 孔席不煗；组词：暖谷(冬温的山 暖(煖)nuǎn 1.温和,不冷也不热~和', '小学', '1'),
    ('暗', 'àn', '13', '日', '左右', NULL, '暗〈形〉 (形声。从日,音声。本义昏暗) 同本义。与明”相对 暗,日无光也。--《说文》 日中光明,故其出入时光暗,故大。--《论衡·说日》 体之感何自起?曰,起于远近之比例；组词：昏暗(光线不足)；暗中摸索(在黑暗中寻找探索) 昏昧,愚昧；不明白 上暗则政险', '小学', '1'),
    ('暮', 'mù', '14', '日', '上下', NULL, '暮 (形声。从日,莫声。古字作莫”,像太阳落到草丛中,表示天将晚。暮”为后起字。本义日落时,傍晚)；组词：暮天(傍晚的天空)；暮雨(傍晚的雨)；暮途(傍晚的路程)；暮烟(傍晚的烟霭)；暮暮(每天傍晚)；暮鼓(鼓楼晚间报 暮mù', '小学', '1'),
    ('暴', 'bào', '15', '日', '上下', NULL, '暴 显露;暴露 暴于南荣。--《史记·司马相如传》 今我使二国暴骨。--《左传·宣公十二年》 尸捐不收,骨暴不葬。--《论衡·祸虚》 其所摧败,功亦足以暴于天下矣；组词：暴师(驻扎在野外的军队)；暴骸(暴露尸骸)；暴骨(暴露尸骨)；暴尸(暴露尸骸) 糟蹋,损害 田不以礼,曰暴天物', '小学', '1'),
    ('曙', 'shǔ', '17', '日', '左右', NULL, '曙 (形声。从日,署声。本义天刚亮时) 同本义 曙,东方明也。--《玉篇》 思不眠以至曙。--《楚辞·悲回风》 自昏达日曙,目不交睫。--《聊斋志异·促织》；组词：曙天(黎明时的天空)；曙日(朝阳)；曙月(晓月)；曙更(黎明的更柝声)；曙角(拂晓的号角声)；曙河(拂晓的银河)；曙星(', '小学', '1'),
    ('曲', 'qǔ', '6', '曰', NULL, NULL, '曲〈形〉 弯曲,不直 曲,象器曲受物之形。--《说文》 曲,折也。--《广雅·释诂一》 木曰曲直。--《书·洪范》 曲,不直也。--《玉篇》 木直中绳,輮以为轮,其曲中规；组词：曲录(弯弯曲曲)；曲律(曲吕', '小学', '1'),
    ('更', 'gèng', '7', '曰', '上下', NULL, '更 (形声。从攴,更”的小篆形是个形声字。丙声。 本义改变) 同本义 更,改也。--《说文》 更也,人皆仰之。--《论语·子张》 更爵洗。--《仪礼·大射仪》 更皮币', '小学', '1'),
    ('曹', 'cáo', '11', '曰', NULL, NULL, '曹 古代指诉讼的原告和被告。即两曹 两曹,今俗所谓原告被告也。--《说文》段玉裁注 古代分科办事的官署或部门 品其名位,犹不失下曹从事。--《资治通鉴》；组词：曹干(官署中的干事人员)；曹掾(泛指一般官员)；曹务(古代官署中分类所管理的事务)；法曹(唐、宋地方司法机关) 管某事的', '小学', '1'),
    ('曼', 'màn', '11', '曰', '上下', NULL, '曼 (形声。小篆字形,从又,冒声。又,手。从又”与手的动作有关。本义长) 同本义 曼,引也。；组词：曼胡(无刃的长戟', '小学', '1'),
    ('曾', 'céng', '12', '曰', NULL, NULL, '曾 (形声。从八,从曰。本义未明。副词。用来加强语气) 过去发生过--表示有过某些行为或情况 江南好,风景旧曾谙。--唐·白居易《忆江南》 斜阳草树,寻常巷陌,人道寄奴曾住；组词：曾不(不曾)；几年前我曾见过他一面；我曾去过杜坪乡 已经 竟,竟然；尚 以残年余力,曾不能毁山之一毛,其如土石何?--《', '小学', '1'),
    ('替', 'tì', '12', '曰', '上下', NULL, '替〈动〉 (形声。本作竝”。从竝,白声。竝,二人并立。本义废弃) 同本义 竝,废也。--《说文》。俗字作替。 不替孟明。--《左传·僖公三十二年》 勿替引之；组词：久替(长期废弃) 停止 荐可而替不', '小学', '1'),
    ('最', 'zuì', '12', '曰', '上下', NULL, '最 (会意。小篆字形,从冃,从取。本义冒犯夺取) 同本义 最,犯而取之。从曰,从取。会意。 公既诸将一禀睿筭,与贼遌,最,遂下之。--明·刘三吾《许国襄简王公神道碑铭》 聚', '小学', '1'),
    ('月', 'yuè', '4', '月', '半包围', NULL, '月 (象形。甲骨文字形。象半月形。月”是汉字部首之一。本义月亮) 同本义 月,太阴之精也。象上下弦阙形。；组词：月满则亏,水满则盈(喻指作事应适可而止,做得过分,就会走向反面)；月上半阑残(指夜已深)；月老冰人(月下老人)；月”字流', '小学', '1'),
    ('有', 'yǒu', '6', '月', NULL, NULL, '有 (会意。金文字形,从又(手)持肉,意思是手中有物。本义具有,与无”相对) 同本义 有,不宜有也。春秋传曰日月有食之。”；组词：有来有去(有板有眼)；有命无运(谓命好,运气却不好)；有酒胆无饭力(表面刚强,骨子里懦弱)；有竡划没是处(虽有安排,但无', '小学', '1'),
    ('朋', 'péng', '8', '月', '左右', NULL, '朋〈名〉 (象形。本义古代货币单位。相传五贝为一朋。或说五贝为一系,两系为一朋) 古代货币单位。五贝为一朋。一说两贝为一朋,也有说十贝为一朋的 既见君子,锡我百朋。；组词：朋故(朋友故旧)；朋曹(朋友辈)；朋好(朋友,好友)；朋伴(朋友, 朋péng 1.彼此友好的人~友', '小学', '1'),
    ('服', 'fú', '8', '月', '左右', NULL, '服〈动〉 (会意。古文从舟,兼做声符。本义舟两旁的夹木) 服从,顺服 敌已服矣。--《吕氏春秋·论威》 以一服八。--《孟子·梁惠王上》 以力服人者,非心服也；组词：服听(服从听命)；服低(屈服；低头)；服杀(折服；倾倒', '小学', '1'),
    ('朗', 'lǎng', '10', '月', '左右', NULL, '朗〈形〉 (形声。从月,良声。本义明亮) 同本义 朗,明也。--《说文》 高朗令终。--《诗·大雅·既醉》 其圣能光远宣朗。--《国语·楚语下》 新而不朗；组词：朗白(明亮发白)；朗朗(光明亮洁的样子；声音清脆嘹亮)；朗鉴(明鉴)；朗亮(雪亮)；朗明(明亮)；朗净(明净)；朗烈(明', '小学', '1'),
    ('望', 'wàng', '11', '月', '上下', NULL, '望 (会意。甲骨文字形,上面是臣”象眼睛,下面是壬”。象一个人站在土地上远望。小篆又加月”字,表望的对象。本义远望)', '小学', '1'),
    ('朝', 'cháo', '12', '月', '左右', NULL, '朝 chao (会意。甲骨文字形,从日在草中,从月。字象太阳已出草中而月亮尚未隐没形。本义早晨) 早晨省亲,子、媳向父母、公婆请安 晨见曰朝...子于父母、妇于舅姑皆是。', '小学', '1'),
    ('期', 'qī', '12', '月', '左右', NULL, '期〈动〉 (形声。从月,其声。金文从日,其声。战国古文从日,丌声。日、月都有表时间的意思。本义约会,约定)；组词：期要(约定,预先约定)；期(杘)jī 1.〈古〉周年,一个月~年', '小学', '1'),
    ('朦', 'méng', '17', '月', '左右', NULL, '朦 (形声。从月,蒙声。本义月不明) 同本义 朦,月朦朦也。--《说文新附》 空架鼓,枉悬钟,绘壁尘多彩象朦。--《西游记》；组词：朦朦(微明的样子) 凝不清的样子 迷糊,迷惘 空架鼓,枉悬钟,绘壁尘多彩象朦', '小学', '1'),
    ('木', 'mù', '4', '木', NULL, NULL, '木 (象形。甲骨文字形。象树木形。上为枝叶,下为树根。木”是汉字的一个部首。从木”的字表示树木或木器的名称。本义树木)', '小学', '1'),
    ('未', 'wèi', '5', '木', NULL, NULL, '未 (象形。基本义没有;不。未”字否定过去,不否定将来,与不”有别。但有时候也当不”字讲) 相当于没有”、不曾”、尚未” 未,无也。；组词：未际(未发迹)；未的(未必,不一定)；未从(未曾,尚 未wèi 1.没有,不曾~经许可', '小学', '1'),
    ('末', 'mò', '5', '木', NULL, NULL, '末 (指事。金文字形。木”上加一点,指明树木末梢所在处。本义树梢) 同本义 末,木上曰末。；组词：末大(树木枝端粗大', '小学', '1'),
    ('本', 'běn', '5', '木', NULL, NULL, '本 (指事。小篆字形,从木”,下面的一横是加上的符号,指明树根之所在。本义草木的根或靠根的茎干)；组词：水有源,木有本；本干(草木的根干) 本宗族 本支百世', '小学', '1'),
    ('术', 'shù', '5', '木', '半包围', NULL, '术 (形声。从行,术声。行,甲骨文中指道路。本义城邑中的道路) 同本义 術,邑中道也。--《说文》 术,道也。--《广雅》 审端径术。--《礼记·月令》 园圃术路；组词：术阡(道路)；术径(大道与小路)；术路(大道)；术衢(道路) 方法；策略 臣有百胜之术', '小学', '1'),
    ('朱', 'zhū', '6', '木', NULL, NULL, '朱 (指事。小篆字形,从木,一在其中指出这种木是红心的。 本义赤心木) 同本义 朱,赤心木,松柏属。', '小学', '1'),
    ('朴', 'pǔ', '6', '木', '左右', NULL, '朴刀 po 杨志提了朴刀,拿了藤条,自去赶那担子。--《水浒传》 朴 〈名〉 po (形声。左形,右声。古代二字意义不同。朴”,本义树皮。《说文》木皮也', '小学', '1'),
    ('朵', 'duǒ', '6', '木', '上下', NULL, '朵 (象形。小篆字形,下面是木”(树),上面象花实之类。本义花朵。朶为朵的俗字) 树木枝叶花实下垂貌。今指花朵,即植物的花或苞 朶,树木花朶朶也。；组词：朵云(对他人书信的敬称)；朵作千叶(花瓣极多) 耳朵 转指两旁 朵 花朵及花朵状物的计量单位 千朵万朵压枝低', '小学', '1'),
    ('机', 'jī', '6', '木', '左右', NULL, '机 木名。桤木树 机,机木。从木,几声。--《说文》 单狐之山多机木。--《山海经·北山经》。注似榆,可烧,以粪稻田。” 春机杨柳。--左思《蜀都赋》 通几”。几案；组词：机杖(几案与手杖)；机案(泛指案桌)；机筵(几案和坐席)；机榻(几案与床榻) 机 (形声', '小学', '1'),
    ('朽', 'xiǔ', '6', '木', '左右', NULL, '朽 (形声。从木,丂声。本义腐烂) 同本义 朽,腐也。--《说文》 荼蓼朽止。--《诗·周南·良耜》。释文烂也。” 其臭朽。--《礼记·月令》。注气若有若无为朽。” 锲而舍之；组词：朽索(腐朽的绳子)；朽壤(腐烂的泥土)；朽木不可雕(朽木不雕,朽木难雕,朽棘不雕', '小学', '1'),
    ('杀', 'shā', '6', '木', '上下', NULL, '杀 (形声。从殳,杀声。古字作杀”,甲骨文字形,在人(大)的下方做上一个被剁的记号,表示杀。殳兵器。从殳表示与杀有关。本义杀戮)', '小学', '1'),
    ('杂', 'zá', '6', '木', '上下', NULL, '杂 (形声。从衣,集声。本义五彩相合) 同本义 画绘之事,杂五色。--《周礼·考工记》 混合;搀杂 故先王以土与金木水火杂,以成百物。--《国语·郑语》 彼此错杂；组词：杂烩菜(将各种剩菜合并在一起的菜淆)；夹杂(搀杂)；杂就(参杂而成)；混杂(混合搀杂) 聚会；聚集 杂,聚也', '小学', '1'),
    ('权', 'quán', '6', '木', '左右', NULL, '权 (形声。从木,雚声。本义黄花木) 同本义 权,黄华木也。从木,雚声。--《说文》 权,黄英。--《尔雅·释木》。；组词：权舆(草木萌发的状态) 于嗟乎,不承权舆', '小学', '1'),
    ('杆', 'gǎn', '7', '木', '左右', NULL, '杆〈名〉 (形声。从木,干声。本义木名。即檀木”。一说为柘树) 杆子 杆 杆子,器物上像棍子的细长部分 作杠杆、把手或支承用的狭长的、通常有相当硬度的木条 兵器,盾牌 杆,古作干', '小学', '1'),
    ('杈', 'chā', '7', '木', '左右', NULL, '杈 (形声。从木,叉声。本义树干的分枝或树枝的分岔) 同本义 杈,杈枝也。--《说文》 江东谓树枝为桠杈。--《方言》 突杈枒而皆折,又有触邪之气也。--杜甫《雕赋》；组词：杈桠(杈丫；杈儿', '小学', '1'),
    ('杉', 'shān', '7', '木', '左右', NULL, '杉 sha 义同杉”,用于杉篙”杉木” 杉篙 杉〈名〉shan 亦称沙木”,杉木”,杉树” 白蚁的桅较少。供建筑、桥梁、造纸、造船等用。如水杉;红杉;紫杉 杉shā 1.树名', '小学', '1'),
    ('李', 'lǐ', '7', '木', '上下', NULL, '李〈名〉 (形声。从木,子声。本义李树) 同本义。落叶乔木,春天开白色花,果实叫李子,熟时黄色或紫红色,可吃 李,李果也。；组词：李下瓜田(容易引起嫌疑的地方)', '小学', '1'),
    ('杏', 'xìng', '7', '木', '上下', NULL, '杏 木名。杏树 杏,杏果也。从木,可省声。--《说文》。按,尚省声。 五沃之土,其木宜杏。--《管子》 孔子游缁帷之林,坐杏坛之上。--《庄子》 桃李梅杏,楂梨姜桂；组词：杏苑(杏树园林；泛指新科进士游宴处)；杏林(见杏田典故', '小学', '1'),
    ('材', 'cái', '7', '木', '左右', NULL, '材 (形声。从木,才声。本义木材,木料) 同本义 材,木梃也。--《说文》 五曰材贡。--《周礼·太宰》 驾而乘材。--《国语·晋语》。注横木也。” 无所取材。--《论语》；组词：木材；材器(材木与器物) 泛指原料、材料 饬化八材', '小学', '1'),
    ('村', 'cūn', '7', '木', '左右', NULL, '村 (形声。从邑,屯声。本义村庄) 同本义 邨,地名。--《说文》。徐铉曰今俗作村。” 村中闻有此人,咸来问讯。--陶潜《桃花源记》 僵卧孤村不自哀；组词：村坊(村庄)；村疃(村庄)；村上(村子里)；村井(村庄)；村公(村中长者)；村老(村中父老)；村戍(村里守卫之所)；村垣', '小学', '1'),
    ('杖', 'zhàng', '7', '木', '左右', NULL, '杖 (形声。从木,丈声。本义执;持) 同本义 杖,持也。--《说文》 王左杖黄钺。--《书·牧誓》 杖剑从之。--《汉书·韩信传》 杖斧。--《汉书·武帝纪》；组词：杖斧(持斧以为威权)；杖楫(持杖)；杖斧之臣(掌握兵权的武臣)；杖策(执马鞭)；杖节(执持旌节) 通仗”', '小学', '1'),
    ('杜', 'dù', '7', '木', '左右', NULL, '杜 (形声。从木,土声。本义杜梨,棠梨,一种木本植物) 同本义 杜,甘棠也。--《说文》。按牡曰棠,牝曰杜。” 杜树大者插五枝。--《齐民要术》 姓 杜 堵塞 杜,塞也；组词：杜耳恶闻(塞住耳朵不愿听)；杜隔(阻塞隔离)；杜闭(堵塞,关闭)；杜禁(堵塞) 关门,封闭 杜乃护王', '小学', '1'),
    ('束', 'shù', '7', '木', NULL, NULL, '束 (会意。从囗木。在木上加圈,象用绳索把木柴捆起来。本义捆绑) 同本义 束,缚也。--《说文》 束帛戋戋。--《易·贲》。子夏传五匹为束。” 束帛俪皮。--《仪礼·士冠礼》；组词：束刃(捆扎兵器)；束刍(捆成一束的干草)；束戈卷甲(捆起兵 束shù 1.系,绑,捆~带', '小学', '1'),
    ('杠', 'gàng', '7', '木', '左右', NULL, '杠 (形声。从木,工声。本义床前横木) 同本义 床,其杠,北燕、朝鲜之间谓之树,自关而西,秦 晋之间谓之杠。', '小学', '1'),
    ('条', 'tiáo', '7', '木', '上下', NULL, '条 (形声。从木,攸声。本义小枝) 同本义 条,小枝 也。--《说文》 桑柳丑条。--《尔雅》 遵彼汝坟,伐其条枚。--《诗·周南·汝坟》 高柯擢条干,远眺同天色', '小学', '1'),
    ('来', 'lái', '7', '木', NULL, NULL, '来 (象形。甲骨文字形。象麦子形。本义麦。小麦叫麦”,大麦叫黣”(或写作牟”)) 同本义 來,周所受瑞麥來黣也。；组词：来牟(古时大小麦的统称) 未来,将来 来日方长', '小学', '1'),
    ('杨', 'yáng', '7', '木', '左右', NULL, '杨 (形声。从木,? 杨柳科杨属植物的泛称 杨,杨木也。--《说文》 杨,蒲柳。--《尔雅》 杨与柳别。杨,枝劲脆而短,叶圆阔而尖;柳,叶长而狭,枝软而韧；组词：白杨；赤杨 姓 杨(楊)yáng杨树,落叶乔木', '小学', '1'),
    ('杭', 'háng', '8', '木', '左右', NULL, '杭 (形声。从木,亢声。本义抵御) 方舟并济或以船渡 杭,渡也。--《说文》 谁谓河广?一苇杭之!--《诗·卫风·河广》 魂中道而无杭。--《楚辞·九章·惜诵》；组词：杭筏(渡水的筏子)；杭绝(乘船渡过) 航行 惩往途而省究兮,吾庶以慎吾杭', '小学', '1'),
    ('杯', 'bēi', '8', '木', '左右', NULL, '杯 (形声。从木,不声。本义盛酒、茶或其他饮料的器皿) 同本义,也称耳杯” 执觞觚杯豆而不醉。；组词：茶杯；杯茗(茶杯与茶水)；杯酒戈矛(比喻为一件小事大动干戈)；杯杓(酒杯和杓子', '小学', '1'),
    ('杰', 'jié', '8', '木', '上下', NULL, '杰 (形声。从人,桀声。杰为傑的俗字。本义才智出众的人) 同本义 五人曰茂,十人曰选,百人曰俊,千人曰英,倍英曰贤,万人曰杰,万杰曰圣。；组词：人杰(才智超群的人)；英杰(豪杰', '小学', '1'),
    ('松', 'sōng', '8', '木', '左右', NULL, '松 (形声。从木,公声。本义松科植物的总称) 同本义 松,松木也。--《说文》 山有乔松。--《诗·郑风·山有扶苏》 如松茂矣。--《诗·小雅·斯干》 出户望南山,松生石上；组词：松塔；松涛；松针；松脂；松亭(旁 边有松树的亭子)；松活(以松柏的枝叶扎成人、鹤、鹿、亭等形状,作为冥器,叫做松活)；松', '小学', '1'),
    ('板', 'bǎn', '8', '木', '左右', NULL, '板 (形声。从木,反声。《说文》作版”。本义片状的木头◇凡施于宫室器用的片状物皆可称板) 同版”。木板 板,木片也。；组词：板舆(由人扛抬的板车', '小学', '1'),
    ('极', 'jí', '7', '木', '左右', NULL, '极 (形声。从木,亟声。本义房屋的正梁) 同本义 榦,栋也。--《说文》。按,在屋之正中至高处。 万载宫极。--《汉书·天文志》 有夫妻臣妾登极。--《庄子·则阳》。司马注屋栋也；组词：极峰(最高层的官员) 特指君位 建用皇极', '小学', '1'),
    ('构', 'gòu', '8', '木', '左右', NULL, '构 (会意。古字为冓。从木,冓声。字本作冓”,金文象屋架两面对构形。本义架木造屋) 同本义 冓,交积材也。；组词：构木(架木造物)；构天(构造天地)；构巢(构木为巢)；构厦(营造大厦)；构第(营造宅第) 构成,造成 构gòu 1.架(', '小学', '1'),
    ('枉', 'wǎng', '8', '木', '左右', NULL, '枉 (形声。从木,王声。本义弯曲;不正) 同本义 枉,邪曲也。--《说文》 是犹立直木而求其景之枉也。--《荀子·王霸》 枉道速祸。--宋·司马光《训俭示康》 枉用三尺；组词：枉法营私(曲解、破坏法律,以谋求私利)；枉矢(不直的箭)；枉径(弯曲的小路)；枉策(弯曲的马鞭)；枉路(弯曲的道路)；枉', '小学', '1'),
    ('析', 'xī', '8', '木', '左右', NULL, '析 (会意。从木,从斤。用斧子劈开木头。本义劈,劈木头) 同本义 析,破木也。--《说文》 析,劈也。--《声类》 析薪如之何?匪斧不克。--《诗·齐风·南山》 扶桑可薪；组词：析木(劈开木头)；析薪(劈柴) 分析,辨认 判天地之美,析万物之理', '小学', '1'),
    ('枕', 'zhěn', '8', '木', '左右', NULL, '枕 躺着时垫在头下的东西~头。落~。~席。 躺着的时候,把头放在枕头上或器物上~戈待旦。~藉(纵横相枕而卧)。 垫着~木(铁路上承受铁轨的横木)。~腕(写字运笔的一种方法', '小学', '1'),
    ('林', 'lín', '8', '木', '左右', NULL, '林〈名〉 (会意。从二木。表示树木丛生。本义丛聚的树木或竹子) 同本义 林,平土有丛木曰林。；组词：竹木林；山林(有山有树林的地方)；深山老林；防护林；林落(树林,丛林)；林浪(林琅、琳琅、林郎', '小学', '1'),
    ('枚', 'méi', '8', '木', '左右', NULL, '枚 (会意。从木,从攴。本义树干) 同本义 枚,枝干也。可为杖。--《说文》 竹曰个,木曰枚。--《释名》 枚,条也。--《广雅》 施于条枚。--《诗·大雅·旱麓》 遵彼汝坟；组词：枚méi 1.树干', '小学', '1'),
    ('果', 'guǒ', '8', '木', '上下', NULL, '果〈名〉 (象形。甲骨文字形,田象树上结的果实形,在木之上。本义果子,果实。这个意义后来曾写作菓”)；组词：果 果(菓)guǒ 1.果子,果实,某些植物花落后,含有种子的部分苹~', '小学', '1'),
    ('枝', 'zhī', '8', '木', '左右', NULL, '枝 (形声。从木,支声。本义主干上分出的茎条) 同本义 枝,木别生条也。--《说文》 草莇之枝。--《素问·移精变气论》 千朵万朵压枝低。--唐·杜甫《江畔独步寻花》 不蔓不枝；组词：枝任(树叶多的树枝)；枝末(树枝的梢头)；枝主(枝条和主干)；枝杪(树木枝条的梢头)；枝柯(枝条)；枝干(树枝和树干)', '小学', '1'),
    ('枢', 'shū', '8', '木', '左右', NULL, '枢 (形声。从木,区声。本义户枢。旧式门的转轴或承轴臼) 同本义 枢,户枢也。--《说文》 枢谓这椳。又枢达北方谓之落时。--《尔雅》 枢机之发。--《易·系辞》。注制动之主；组词：枢户(解脱门枢) 木名,即刺榆 山有枢,隰有榆', '小学', '1'),
    ('枣', 'zǎo', '8', '木', '上下', NULL, '枣 (会意。从双朿。朿,木芒。枣树多刺。本义枣树) 同本义 枣,羊枣也。--《说文》 枣有十一名,羊枣其一也。--《尔雅》 衣巾落枣花；组词：枣核(枣子的核)；枣菜(枣子与蔬菜)；枣脯(枣子制成的果干)；枣榛(枣子与榛子)；枣实(枣子)；枣蔬(枣子与蔬菜) 枣(', '小学', '1'),
    ('枪', 'qiāng', '8', '木', '左右', NULL, '枪 (形声。从木,仓声。本义二树的枝条互相抵拒) 古时长柄有尖头的刺击武器 枪,歫也。--《说文》。按,歫人之械也。 枪,谓木两 头锐者也。--《苍颉篇》 剡木伤盗曰枪；组词：红缨枪；枪缨(枪上用丝、线等做成的穗状饰物) 武器名', '小学', '1'),
    ('枫', 'fēng', '8', '木', '左右', NULL, '枫 (形声。从木,风声。本义木名。即枫香树) 同本义 枫,枫木也●叶弱枝,善摇。--《说文》 枫欇欇。--《尔雅·释木》。注树似白杨,叶圆而岐,有脂而香。”孙注生江上,有寄生枝', '小学', '1'),
    ('枯', 'kū', '9', '木', '左右', NULL, '枯〈形〉 (形声。从木,古声。本义枯槁,草木干枯) 同本义 枯,槁木也。--《说文》 草木蚤枯。--《礼记·月令》 离离原上草,一岁一枯荣；组词：枯荣(草木的繁荣与凋零◇指盛衰；也指干涸,干竭)；枯凋(枯槁凋零)；枯索(草木枯萎全无生机)；枯梧(枯萎的梧桐；泛指枯木', '小学', '1'),
    ('架', 'jià', '9', '木', '上下', NULL, '架 (形声。从木,加声。本义棚架) 同本义 葡萄,蔓延性缘,不能自举,作架以承之。--《齐民要术·种桃》 搁置或支持东西的用具 借书满架。--明·归有光《项脊轩志》；组词：十字架；三脚架；架桩(原指吃完鸡鸭剩的骨架,江湖暗语指人的尸体)；架阁(官署中用以保存公文案卷的木架；借指耽搁,放在一旁', '小学', '1'),
    ('枷', 'jiā', '9', '木', '左右', NULL, '枷 (形声。从木,加声。本义连枷。脱粒用的农具) 同本义(农具名) 枷,加也。加杖于柄头,以过穗而出其谷也。；组词：枷杻(刑具', '小学', '1'),
    ('柄', 'bǐng', '9', '木', '左右', NULL, '柄 (形声。从木,丙声。本义器物的把儿) 同本义 柄,柯也。(柯斧柄。)--《说文》 覆之南柄。--《仪礼·少牢礼》 有柄。--《仪礼·大射礼》 柄(铁椎把)铁折叠环复；组词：柄子(方言', '小学', '1'),
    ('柏', 'bǎi', '9', '木', '左右', NULL, '柏 (形声。从木,白声。本义木名,柏树,也称椈”) 柏科柏木属植物的通称 柏,鞠也。--《说文》 柏,椈。--《尔雅》 鬯臼以椈。--《礼记·杂记》 岁寒,然后知松柏之后凋也', '小学', '1'),
    ('某', 'mǒu', '9', '木', '上下', NULL, '某 (象形。金文字形。像木上结一个果实,本是梅”的象形。本义梅) 指一定的不明说的人或事物 如古人某。--清·周容《芋老人传》 狂生某者；组词：某人；某天；某官某(某某官(叫)某某的(人)', '小学', '1'),
    ('柑', 'gān', '9', '木', '左右', NULL, '柑〈名〉 (形声。从木,甘声。本义木名,柑树,果实也称柑) 同本义 丛生。果扁圆形,红色或橙黄色,中心柱大,味酸甜不一。种子多为多胚性。性较耐寒。用嫁接、压条、实生等法繁殖', '小学', '1'),
    ('柒', 'qī', '9', '木', '上下', NULL, '柒〈数〉 七”的大写 壹、 贰、 叁、 肆、 伍、 陆、 柒、 捌、 玖、 拾, 字书皆有之。--宋·陆游 《老学庵笔记》 柒qī"七"的大写。', '小学', '1'),
    ('染', 'rǎn', '9', '木', '上下', NULL, '染 (形声。从水,杂声。一说从木、从水、从九。会意。古染料多来源于植物,故从木;染料须加工成液体,故从水;染须反复进行,故从九。本义使布帛等物着色)；组词：染博士(染色的工匠)；染服(僧侣所穿的缁衣', '小学', '1'),
    ('柔', 'róu', '9', '木', '上下', NULL, '柔 (形声。从木,矛声。本义树木可曲可直) 同本义 柔,木曲直也。--《说文》。段注凡木曲者可直,直者可曲,曰柔。” 荏染柔木。--《诗·小雅·小弁》；组词：柔木(柔软而又坚韧的木) 柔弱；细嫩 柔,弱也', '小学', '1'),
    ('柜', 'guì', '8', '木', '左右', NULL, '柜 (形声。从木,匮声。本义收藏衣物、书籍的家具) 小匣 匮,匣也。从匚,贵声。俗作櫃。--《说文》 将为胠箧探囊发匮之盗。--《庄子·胠箧》 玉与石而同匮兮；组词：柜田 柜 同 柜jǔ 1.柜柳,落叶乔木,羽状复叶,树性耐湿、耐碱,可固沙', '小学', '1'),
    ('柠', 'níng', '9', '木', '左右', NULL, '柠 木名 柠,木皮入酒浸,治风。--《广韵》 柠檬 柠(檸)níng', '小学', '1'),
    ('查', 'chá', '9', '木', '上下', NULL, '査 (形声。从木,且声。本义木筏) cha 同本义。同楂” 有巨查浮于西海。--晋·王嘉《拾遗记·唐尧》；组词：查影(筏影,船影)；查头(船头) 树桩 树杈 查 审查,考查；检查 调查 在参考书中寻找 查 zha 渣滓 棍、 查 c', '小学', '1'),
    ('柬', 'jiǎn', '9', '木', NULL, NULL, '柬 (会意。从束,从八。束”,札束。八”,分别的意思。本义挑选,从事物中分别出好坏) 同本义。从作拣” 柬,分别择之也。；组词：柬汰(挑出剔去)；柬拔(盐)；柬寄(选择并委以重任)；柬择(选择)；柬擢(盐) 柬 信札、名帖等的统称(用硬纸或薄纸板制', '小学', '1'),
    ('柱', 'zhù', '9', '木', '左右', NULL, '柱 支撑。通拄” 且鳌足可以柱天,体必长大,不容于天地,女娲虽圣,何能杀之?--《论衡·谈天》；组词：柱天(撑天；支天)；柱地(立柱支地) 挡住；阻塞 内人共举机以柱门,兵斫门,不能破', '小学', '1'),
    ('柳', 'liǔ', '9', '木', '左右', NULL, '柳 (形声。从木,乯声。本义木名。枝条柔韧。种类很多,常见的有垂柳、旱柳、杞柳等) 同本义 梡,小杨也。；组词：柳花(柳树的花)；柳黄(像柳树芽那样的浅黄色)；柳陌花街(寻花买笑的场所)；柳绿(柳叶的青绿色)；柳眼(初发的柳芽)；柳', '小学', '1'),
    ('柴', 'chái', '10', '木', '上下', NULL, '柴 chai (形声。从木,此声。本义捆束的细木小柴) 同本义 大者可析谓之薪,小者合束谓之柴。；组词：柴荆(乡里用木板、荆条编制而成的门)；柴禾(木柴；柴草)；木柴；劈柴；柴水(打柴汲水)；柴市(木柴交易处)；柴山(生长矮', '小学', '1'),
    ('柿', 'shì', '9', '木', '左右', NULL, '柿 柿树 柿树属落叶乔木,品种很多,叶子椭圆形或倒卵形,背面有绒毛,花黄白色。结浆果,扁圆形或圆锥形,橙黄色或红色,可以吃。如柿叶(柿树的叶子) 这种植物的果实', '小学', '1'),
    ('栅', 'shān', '9', '木', '左右', NULL, '栅极 shan 柵 zha (会意兼形声。从木,从册,册亦声。本义栅栏) 同本义 栅,编竖木也。；组词：栅门(栅栏的门)；栅刺子(即栅栏)；栅塘(有栅栏围护的水塘)；栅垒(安装在栅栏上的锁)；栅孔(树立栅木的孔洞)；栅墙(用', '小学', '1'),
    ('标', 'biāo', '9', '木', '左右', NULL, '标 (形声。从木,票声。本义树梢) 同本义 标,木杪末也。--《说文》 大本而小标。--《管子·霸言》；组词：标枝(树梢的枝条)；标末(树梢) 末梢；事物的枝节或表面', '小学', '1'),
    ('栈', 'zhàn', '9', '木', '左右', NULL, '栈 (形声。从木,戔声。本义牲口棚) 同本义 栈,棚也。--《说文》。按,栅者,竖编之,棚者,横编之。 埋之马栈之下。--《战国策·齐策》 马栈最难；组词：皂栈(马房中的栅栏和方格木条) 古代用竹木条横排编成车箱的轻便车子 栈,竹木之车曰栈', '小学', '1'),
    ('栋', 'dòng', '9', '木', '左右', NULL, '栋 (形声。从木,东声。本义屋的正梁,即屋顶最高处的水平木梁,支承着椽皮 同本义 栋,极也。从木,东声。屋内至中至高之处亦曰阿,俗谓之正梁。；组词：栋宇(指房屋', '小学', '1'),
    ('栏', 'lán', '9', '木', '左右', NULL, '栏 (形声。从木,阑声。栏”和拦”都是后起字。阑”用作名词时写作栏”,用作动词时,写作拦”。本义栏杆)；组词：栏榡(栏杆)；栏干子(栏杆)；栏角(栏杆的转角)；栏船(有栏杆的大木船) 饲养家畜的圈 报纸或刊物中有固定标题或特写的部', '小学', '1'),
    ('树', 'shù', '9', '木', '左右', NULL, '树 (形声。从木,尌声。本义栽树) 同本义 树,生植之总名。--《说文》。段注植,立也。假借为尌竖字。 宿敢不封殖此树。--《左传·昭公二年》 夫坚树在始。--《国语·晋语》；组词：树事(种植草木之事)；树杨(种植杨树)；十年之计,在于树木；树其树以荫行人 种植 树,种也', '小学', '1'),
    ('栓', 'shuān', '10', '木', '左右', NULL, '栓 (形声。从木,全声。本义木钉;插子) 同本义 塞子,也泛指形状像塞子的东西 栓shuān 1.器物上用作开关的机件枪~。消火~。 2.塞子,起塞子作用的软木~。~剂。血~。', '小学', '1'),
    ('栖', 'qī', '10', '木', '左右', NULL, '栖 qi (棲本作西”。同栖”。形声。从木,妻声。本义鸟类歇息) 同本义 鸡栖于厅。--明·归有光《项脊轩志》 山有栖鹘。--宋·陆游《过小孤山大孤山》；组词：栖竿(捕虫鸟的黏竿)；栖山(栖息于山', '小学', '1'),
    ('栗', 'lì', '10', '木', '上下', NULL, '栗〈名〉 (会意。甲骨文象结了果实的栗树形。本义木名。果实也称栗,可食) 一种落叶乔木,果实叫栗子,果仁味甜,可以吃。木材坚实,供建筑和制器具用;树皮可供鞣皮及染色用；组词：栗主(用栗木做成的神牌位)；栗跗(栗花) 任一种栗属的乔木或灌木结的可食的甜味坚果 果至于梨栗枣之类', '小学', '1'),
    ('校', 'xiào', '10', '木', '左右', NULL, '校〈名〉jiao 古代刑具。枷械的统称 校,木囚也。从木,交声。--《说文》 屦校灭趾。--《易·噬嗑》。 何校灭耳。注若今枷项也。” 大校重牢,五木被体；组词：校猎(用木栏遮阻而猎取禽兽', '小学', '1'),
    ('株', 'zhū', '10', '木', '左右', NULL, '株 (形声。从木,朱声。本义露出地面的树根) 同本义 株,木根也。--《说文》。今语转曰桩。 命曰株送徒。--《史记·平准书》。集解根蒂也。” 若厥株驹。--《列子·黄帝》；组词：株橛(树桩、木根)；株蘖(树木砍伐后根株生出的枝条) 泛指草木 泽涸无鱼,山童无株', '小学', '1'),
    ('样', 'yàng', '10', '木', '左右', NULL, '样 (形声。从木,羕声。本义栩实,字亦作橡) 假借为像”。式样 去年中使宣口敕,天上取样人间织。--唐·白居易《缭绫》；组词：样银(用于测定银子成色的样品)；样儿(样子', '小学', '1'),
    ('核', 'hé', '10', '木', '左右', NULL, '核 (形声。从木,亥声。本义果核) 同本义 核,蛮夷以木皮为箧,状如籢尊。--《说文》 桃李丑核。--《尔雅·释木》 殽核维旅。--《诗·小雅·宾之初筵》 其实濡核；组词：枣核；樱桃核；葡萄核；橘核 原子核的简称 有核的果实 门启,华堂复阁甚秀,馆中有樽酒盘核', '小学', '1'),
    ('根', 'gēn', '10', '木', '左右', NULL, '根 (形声。从木,艮声。本义草木之根) 植物生长于土中或水中吸收营养的部分 根,木株也。--《说文》 蔓根为根,直根为柢。--《说文通训定声》 根深,则视久；组词：根莇(根', '小学', '1'),
    ('格', 'gé', '10', '木', '左右', NULL, '格 (形声。从木,各声。本义树木的长枝条) 同本义 格,木长貌。--《说文》。徐锴系传亦谓树高长枝为格。” 夭娇枝格,偃蹇杪颠。--司马相如《上林赋》 角者,言万物皆有枝格如角也；组词：五格的书架；格眼(格子和窟窿)；格子眼(窗孔)；格目(项目)；格gé 1.划分成空栏或框子方~纸', '小学', '1'),
    ('栽', 'zāi', '10', '木', '半包围', NULL, '栽 (形声本义筑墙立板) 同本义 栽,筑墙长版也。--《说文》。古筑墙之法,既度其广轮,先植桢于两头,又植干于两边,而后横施版于干内,以绳束干,实土筑之,一版竣,则层累而上；组词：栽树；栽莳( 栽zāi 1.种植,移植~种', '小学', '1'),
    ('桂', 'guì', '10', '木', '左右', NULL, '桂〈名〉 (形声。从木,圭声。本义木名。《说文》江南木,百药之长。”) 肉桂(cinnamomum cassia),常绿乔木,花黄色,果实黑色,树皮可做健胃剂；组词：桂霭(桂 桂guì 1.桂花树,常绿小乔木或灌木', '小学', '1'),
    ('桃', 'táo', '10', '木', '左右', NULL, '桃〈名〉 (形声。从木,兆声。本义果木名) 桃树 桃,桃果也。--《说文》 桃之夭夭。--《诗·周南·桃夭》 园有桃。--《诗·魏风·园有桃》 木名。蔷薇科,落叶小乔木。春季开花', '小学', '1'),
    ('桅', 'wéi', '10', '木', '左右', NULL, '桅 船上挂帆的柱杆 桅wéi', '小学', '1'),
    ('框', 'kuàng', '10', '木', '左右', NULL, '框〈名〉 (形声。从木,匡声。本义门窗的架子) 同本义 棺门 两手据地而欧之不出,喀喀然遂伏而死。', '小学', '1'),
    ('案', 'àn', '10', '木', '上下', NULL, '案〈名〉 (形声。从木,安声。本义木制的盛食物的矮脚托盘) 同本义 赵王张敖自持案进食。--《史记·田叔列传》 妻为具食,不敢于鸿前仰视,举案齐眉；组词：捧案；案杯(案酒) 无靠背的坐具 师田,则张幕设案', '小学', '1'),
    ('桌', 'zhuō', '10', '木', '上下', NULL, '桌 (形声。从木,卓省声。桌字本作卓”。卓有高而直立之义◇来人们又根据棹”是木制的特点另制桌”字。俗又作棹”。本义桌子)；组词：桌巾(桌布)；桌屏(摆在桌上当作装饰的小屏风)；桌帏(亦称桌帷”同桌围”', '小学', '1'),
    ('桐', 'tóng', '10', '木', '左右', NULL, '桐〈名〉 (形声。从木,同声。本义木名,也名荣”) 树名 桐,荣也。--《说文》 荣,桐木。--《尔雅》。按,与梧同类而异,皮青而泽,荚边缀子如乳者为梧,亦谓之青桐。皮白', '小学', '1'),
    ('桑', 'sāng', '10', '木', '上下', NULL, '桑〈名〉 (会意。从桑,从木。桑者。神桑也。本义植物名) 一种桑属的落叶乔木 桑,蚕所食叶木。；组词：桑麻(农事；农村；农民)；桑土(桑树的根)；桑户( 桑sāng桑树,落叶乔木', '小学', '1'),
    ('档', 'dàng', '10', '木', '左右', NULL, '档 (形声。从木,当声。本义器物上用以分格或撑的横木条) 同本义 俗谓横木框档。--《正字通》；组词：床档；十三档算盘 档案,排列或分类过的卡片或文件卷宗 存放案卷用的带格子的橱 按重要性、质量或价值排列的级别 指曲艺、杂', '小学', '1'),
    ('桥', 'qiáo', '10', '木', '左右', NULL, '桥 (形声。从木,乔声。本义桥梁) 同本义 桥,水梁也。从木,乔声。骈木为之者。独木者曰杠。；组词：桥阁(傍山架木为路', '小学', '1'),
    ('桦', 'huà', '10', '木', '左右', NULL, '桦 (形声。从木,华声。本义木名。桦木) 桦木属(betula)植物的泛称。落叶乔木或灌木 桦(樺)huà桦树,落叶乔木或灌木。有白~、黑~、坚~等多种。木材供建筑或制器具等使用', '小学', '1'),
    ('桨', 'jiǎng', '10', '木', '上下', NULL, '桨 (形声。从木,将声。本义划船用具。短小者称桨) 同本义 金桨木兰船,戏采江南莲。--南朝梁·刘孝威《采莲曲》 桨(槳)jiǎng划船的工具。上端为圆杆,利于手握;下端为板状', '小学', '1'),
    ('桩', 'zhuāng', '10', '木', '左右', NULL, '桩 (形声。从木庄声。本义桩子,打入地中以固基础的木橛) 同本义 樁,橛杙也。--《说文新附》 下整高颓,深平险谷,摆桩栝,开林丛。--唐·李白《大猎赋》；组词：船桩；桥桩；短树桩；铁桩；水泥桩；桩歌(夯歌)；桩橛(木桩', '小学', '1'),
    ('桶', 'tǒng', '11', '木', '左右', NULL, '桶 (形声。从木,甬声。本义量器名) 古量器名。方形斛 桶,木方,受六升。--《说文》。段玉裁注疑当作方斛,受六升。” 方斛谓之桶。--《广雅》 角斗桶', '小学', '1'),
    ('梁', 'liáng', '11', '木', '上下', NULL, '梁 (会意。从木,从水,剉声。从木”从水”,表示用木料在水上造桥。本义水桥) 同本义 梁,水桥也。；组词：河梁(桥,又借指送别之地)；津梁(渡和桥梁)；桥梁(桥)；梁 梁( 1.樑)liáng 1.支撑屋顶的横木屋~', '小学', '1'),
    ('梅', 'méi', '11', '木', '左右', NULL, '梅 (形声。从木,每声。本义楠木) 同本义 其木多梅梓。--《山海经·中山经》 有条有梅。--《诗·秦风·终南》 墓门有梅。--《诗·陈风·墓门》。按,子青不可食', '小学', '1'),
    ('梆', 'bāng', '10', '木', '左右', NULL, '梆 (本义木名) 梆子,用竹筒或挖空木头做成的发声器。用于巡更或聚众 知县才发二梆,不曾坐堂。', '小学', '1'),
    ('梗', 'gěng', '11', '木', '左右', NULL, '梗 (形声。从木,更声。本义一种树) 刺榆(hemiptelea davidii)的古名 梗,山枌榆。荚可为芜荑也。；组词：梗林(多刺的林丛)；梗莽(荆棘草莽)；梗刺(草木茎上有刺针) 草本植物的枝茎 桃梗土偶', '小学', '1'),
    ('梢', 'shāo', '11', '木', '左右', NULL, '梢〈名〉 (形声。从木,肖声。本义树木的末端) 同本义 梢,梢木也。--《说文》 梢,梢擢。--《尔雅》。注谓木无枝柯,梢擢长而杀者。” 开花寄树梢；组词：树梢；枝梢 树木的枝条 曳梢肆柴', '小学', '1'),
    ('梦', 'mèng', '11', '木', '上下', NULL, '梦 (会意。小篆字形,由宀”(房子)、爿”(床)、夢”(不明也)三字合成。意为夜间在床上睡觉,眼前凝看不清,即作梦。夢”由苜”(眼看不清)、宀”(人的变形)；组词：梦迷(梦后刚醒,尚未完全摆脱梦境)；梦梦铳铳(形容睡得迷迷糊糊)；梦梦查查(迷迷糊糊)；梦思(梦中的思念)；梦中梦(喻幻', '小学', '1'),
    ('梧', 'wú', '11', '木', '左右', NULL, '梧 木名。梧桐 屋梁上两头起支架作用的斜柱 斜柱,其名有五一曰斜柱,二曰梧,三曰迕,四曰枝樘,五曰叉手。', '小学', '1'),
    ('梨', 'lí', '11', '木', '上下', NULL, '梨 (形声。从木,利声。梨为棃的俗字。本义木名。果实也称梨) 同本义 棃,梨果也。--《说文》 楂棃姜桂。--《礼记·内则》 千树万树梨花开', '小学', '1'),
    ('梭', 'suō', '11', '木', '左右', NULL, '梭 (形声。本义织机的构件) 梭子 梭,织具也。--《通俗文》 机梭声札札,牛驴走纷纷。--唐·白居易《朱陈村》 如梭布(土布。因用梭子织出);穿梭;无梭织机;梭杼(机杼；组词：日月如梭；梭梭(往复如梭', '小学', '1'),
    ('梯', 'tī', '11', '木', '左右', NULL, '梯〈名〉 (形声。从木,弟声。本义便利人上下攀登(尤其建筑物)的用具或设备) 同本义 梯,木阶也。；组词：楼梯；云梯(攻城或救火时用的长梯)；阶梯(台阶和梯子)；梯航(梯与船)；梯梁(凿梯架桥)；梯磴(梯子的梯级)；软梯 形状', '小学', '1'),
    ('械', 'xiè', '11', '木', '左右', NULL, '械 (形声。从木,戒声。本义脚镣手铐一类的刑具) 同本义 械,桎梏也。--《说文》 拘罪人曰桁械。谓穿木加足曰械,大械曰桁。--《通俗文》 在手曰械；组词：械送(加刑具押送)；械索(泛指刑具', '小学', '1'),
    ('梳', 'shū', '11', '木', '左右', NULL, '梳 (形声。从木,疏省声。本义梳子) 同本义 梳,理发也。--《说文》 梳,栉也。--《广雅》 梳,言其齿疏也。--《释名》 朝有讽谏,犹发之有梳。--《新唐书·吴兢传》；组词：木梳；梳枇(齿稀的叫梳,齿密的叫枇)；梳掠(梳子', '小学', '1'),
    ('检', 'jiǎn', '11', '木', '左右', NULL, '检 (形声。从木,佥声。本义书匣上的标签) 同本义 检,书署也。--《说文》。按,今字作签。 辄皂囊施检。--《后汉书·公孙瓒传》；组词：检封(缄封,封藏)；检素(封好的信,书信) 法式,法度 检,法度也', '小学', '1'),
    ('棉', 'mián', '12', '木', '左右', NULL, '棉 (会意。从木,从帛。植物名) 木棉,也叫攀枝花”、英雄树” 棉,木棉,树名。《吴录》云其实如酒杯,中有绵如蚕绵,可作布。', '小学', '1'),
    ('棋', 'qí', '12', '木', '左右', NULL, '棋 (形声。从木,其声。本义古时通称博奕的子为棋) 同本义 棊,博棊也。--《说文》 五簙或谓之棊。--《方言》 故行棊者。--《淮南子·泰族》。注谓六博也。” 休与之山；组词：棋枰(棋盘)；棋子(一种干粮)；象棋；国际象棋；围棋；跳棋 棋 〈动〉 下棋 棋(棊、碁)qí文娱体育用品名称跳~', '小学', '1'),
    ('棍', 'gùn', '12', '木', '左右', NULL, '棍〈名〉 能够转动,用以缠绕线、弦的旋纽 棍,转也。谓箜篌上转绳也。--唐·玄应《一切经音义》 棍〈名〉 棍棒 是那一个实丕丕将着粗棍敲,打的来痛杀杀精皮掉。；组词：大棍；齐眉棍；三节棍；二节棍；大梢子棍；手捎子棍 品行很坏的人 山儿,我如今放你去,若拿得这两个棍徒,将功折罪；若拿不得', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('棒', 'bàng', '12', '木', '左右', NULL, '棒 (形声。从木,奉声。本义棍,杖) 同本义 人马逼战,刀不如棒。--《魏书·尔朱荣传》；组词：棒糖；棍棒；棒打鸳鸯(以强硬手段,破坏他人的夫妇关系,或指阻挠男女的婚事) 棒 用棍棒打 其或迟违,则赤棒棒之', '小学', '1'),
    ('棕', 'zōng', '12', '木', '左右', NULL, '棕 植物名。棕榈的省称 椶,栟榈也。--《说文》 又如龙棕;蜡棕;扇棕;棕片(棕衣。棕皮);棕车(以棕为盖顶的车);棕笋(棕榈的花苞) 棕毛或棕片 棕色的染料 棕 棕毛的颜色；组词：龙棕；蜡棕；扇棕；棕片(棕衣', '小学', '1'),
    ('棘', 'jí', '12', '木', '左右', NULL, '棘 (会意。从二-朿。朿”是刺”的本字。两个朿”字并排立着,表示棘树多刺,是矮小而成丛莽的灌木。本义丛生的小枣树) 酸枣树。一种落叶乔木,有刺。果实较枣小,味酸,种子、果皮；组词：棘薪(指酸枣树已长成薪柴) 泛指有芒刺的草木 攀草牵棘', '小学', '1'),
    ('棚', 'péng', '12', '木', '左右', NULL, '棚〈名〉 (形声。从木,朋声。本义用竹、木搭成的篷架或小屋) 同本义 棚,栈也。--《说文》。按,编木横竖为之皆曰栈曰棚,今谓于上以蔽下者曰棚。段玉裁注《通俗文》曰‘板阁曰栈；组词：窝棚(简陋的小屋)；棚井(棚户进庐)；棚摊(有棚子的货摊)；棚阁(用竹、木等搭建的篷架、陋屋)；棚杠(旧时为丧家承办搭棚', '小学', '1'),
    ('棠', 'táng', '12', '木', '上下', NULL, '棠 (形声。从木,尚声。本义乔木名) 同本义。甘棠,有红、白两种。白棠即棠梨 棠,牡曰棠,牝曰杜。--《说文》 野棠开尽飘香玉。--李洞《绣岭宫词》 棠táng 1. 2.', '小学', '1'),
    ('森', 'sēn', '12', '木', '上下', NULL, '森 (会意。从林从木。本义树木丛生繁密) 同本义 森,木多貌。--《说文》 林多木长貌。--《字林》 森槮柞朴。--马融《长笛赋》 弹言鸟于森木。--左思《蜀都赋》；组词：森标(树丛的顶端)；森木(高耸繁茂的树木)；森沉(林木繁茂幽深)；森阴(林木幽深繁密)；森萃(茂密)；森朗(繁密而又清朗', '小学', '1'),
    ('棱', 'léng', '12', '木', '左右', NULL, '棱 不棱登”助词。常用为某些形容词的后缀。如红不棱登;花不棱登 棱 (俗作楞”和稜”。形声。从木,夌声。本义有四角的木)；组词：棱光(威严的目光)；棱眼(威严的眼睛)；棱棱(威严的样子) 严厉 棱(稜)、楞léng 1.物体上不同方向的两个平面连结', '小学', '1'),
    ('棵', 'kē', '12', '木', '左右', NULL, '棵〈量〉 (形声。从木,果声。本义指植物的株数) 同本义 棵 指某些植物的茎 棵kē 1.量词。用于植物两~菜。三~树。 2. 3.', '小学', '1'),
    ('棺', 'guān', '12', '木', '左右', NULL, '棺〈名〉 (形声。从木,官声。本义棺材,装殓尸体的器具) 同本义。亦称棺木,棺函,棺柩,棺衬 棺,榇也,所以掩尸。孝经郑注周尸为棺。”；组词：棺材本(借指养老的钱)；棺材座子(棺材下面的底座)；棺尸(棺材中的尸体)；棺衾(棺材和衾被', '小学', '1'),
    ('椅', 'yǐ', '12', '木', '左右', NULL, '椅 木名。即山桐子” 另见譹 椅 (形声。从木,奇声。1本义木名。即山桐子。《诗·鋠风·定之方中》树之榛栗,椅桐梓漆。”2椅子。本字作倚”) 椅子, 有靠背的坐具 椅；组词：椅杌(椅子和凳子)；椅背(椅披', '小学', '1'),
    ('植', 'zhí', '12', '木', '左右', NULL, '植 (形声。从木,直声。本义关闭门户用的直木) 同本义 植,户植也。--《说文》。按,古门外闭,中竖直木,以铁了鸟关之,可加锁者。 季孙与邑人争门关,决植', '小学', '1'),
    ('椎', 'zhuī', '12', '木', '左右', NULL, '椎 (形声。从木,隹声。本义槌子,敲击的器具) 捶击的工具◇亦为兵器 椎,所以击也。--《说文》 椎,棒椎也。--《广韵》 杼上终葵首。--《考工记·玉人》。疏终葵,椎也。”；组词：椎拍(用椎拍击)；椎斧(椎和斧)；椎凿(槌子和凿子)；椎锻(锤子和打铁用的砧石)；椎额(额头突出如椎)；椎塘(臼) 椎髻', '小学', '1'),
    ('椒', 'jiāo', '12', '木', '左右', NULL, '椒〈名〉 (形声。从木,叔声。本义花椒) 同本义。芸香科植物 焚椒兰也。--唐·杜牧《阿房宫赋》；组词：椒科(泛指各种调味佐料)；椒图(椒涂', '小学', '1'),
    ('椭', 'tuǒ', '12', '木', '左右', NULL, '檈 (形声。从木,隋声。本义长圆形,狭长) 同本义 其方圆锐椭不同,盛水各异,其于灭火钧也。', '小学', '1'),
    ('椰', 'yē', '12', '木', '左右', NULL, '椰 椰子树 汁可做饮料,外果皮和中果皮的纤维可制船缆和刷子,叶子可编席和盖棚 椰yē 1. 、装饰品等。木材可做器具和供建筑用。 2.', '小学', '1'),
    ('椿', 'chūn', '13', '木', '左右', NULL, '椿 (形声。从木,春声。本义木名。指大椿。古代传说大椿长寿,后因以喻父。如椿年) 同本义 上古有大椿者。', '小学', '1'),
    ('楔', 'xiē', '13', '木', '左右', NULL, '楔 (形声。从木,契声。本义楔子,上粗下锐的小木橛) 同本义 楔,櫼也。--《说文》 复楔齿缀足。--《礼记·檀弓》 大者以为舟航柱梁,小者以为楫楔。--《淮南子》；组词：木楔,竹楔 楔形物 楔貌如轭上两末', '小学', '1'),
    ('楚', 'chǔ', '13', '木', '上下', NULL, '楚〈名〉 (形声。从林,疋声。本义灌木名。又名荆,牡荆) 同本义 楚,丛木也。一名荆。--《说文》 言刈其楚。--《诗·周南·汉广》 不流束楚。--《诗·王风·扬之水》 夏楚二物；组词：楚棘(荆棘)；楚焞(古时占卜用以灼龟的木棒', '小学', '1'),
    ('楞', 'léng', '13', '木', '左右', NULL, '楞〈名〉 (同棱”。本义四方木;棱角) 同本义 物体上一条条凸起来的部分 楞〈形〉 失神、发呆 班惊楞,逡巡来答。--干宝《搜神记》；组词：楞子眼(因酒醉或其他原因而眼神呆滞)；楞楞 (傻傻的模样)；楞神(失神、发呆)；楞然(惊奇发呆貌)；楞中楞(发呆貌)；楞', '小学', '1'),
    ('楣', 'méi', '13', '木', '左右', NULL, '楣 (形声。从木,眉声。本义屋檐口椽端的横板) 同本义 楣,屋边联也。齐谓之檐,楚谓之梠,秦谓之楣。；组词：楣机(比喻 楣méi 1.门框上的横木', '小学', '1'),
    ('楷', 'kǎi', '13', '木', '左右', NULL, '楷〈名〉kai (形声。从木,皆声。 1本义木名。即黄连木”。楷树枝干疏而不屈,因以形容刚直 2法式,典范) 法式,典范 楷,法也。；组词：楷法(法则；典范)；楷栻(同楷式”)；楷素(楷模)；为此所楷 楷书『字形体之一,由隶书演变而来,也叫正书”,真书” 姓', '小学', '1'),
    ('楼', 'lóu', '13', '木', '左右', NULL, '楼 (形声。从木,娄声。本义楼房,两层以上的房屋) 同本义 楼,重屋也。--《说文》 西北有高楼,上与浮云齐。--《古诗十九首》 五步一楼,十步一阁。--杜牧《阿房宫赋》；组词：教室楼；办公楼；科技楼；楼额(楼上的匾额)；楼观(高楼的泛称；道观的观名)；楼外楼(楼外有楼', '小学', '1'),
    ('概', 'gài', '13', '木', '左右', NULL, '概 (形声。从木,既声。本义量米粟时刮平斗斛用的木板。量米粟时,放在斗斛上刮平,不使过满)；组词：概量(概和斗斛等量谷物的器具) 节操,风度 而不概于王心邪', '小学', '1'),
    ('榄', 'lǎn', '13', '木', '左右', NULL, '榄 木名。橄榄的省称 榄(欖)lǎn[橄榄]见橄。', '小学', '1'),
    ('榆', 'yú', '13', '木', '左右', NULL, '榆〈名〉 榆树 榆,白枌。--《说文》。按,榆皮色赤,其白者为枌也。荚可食,亦可为酱。 堇萱枌榆。--《礼记·内则》 我决起而飞抢榆枋。--《庄子·逍遥游》 落叶乔木,叶卵形', '小学', '1'),
    ('榔', 'láng', '12', '木', '左右', NULL, '梠〈名〉 同榔”。渔人结在船舷上敲击以驱鱼入网的长木棒 榔láng 1.[榔头]锤子。 2.[榔槺]长、大、苯重,使用起来不方便的器物。', '小学', '1'),
    ('榕', 'róng', '14', '木', '左右', NULL, '榕 一种常绿乔木 榕,木名。--《玉篇》 福建省福州市的别称 榕róng 1. 2.福州市的别称。', '小学', '1'),
    ('榛', 'zhēn', '14', '木', '左右', NULL, '榛 落叶灌木或小乔木,结球形坚果,称榛子”,果仁可食。木材可做器物。 丛杂的草木~芜。莽~。~薄(草木丛生的地方,引申为指幽僻的地方)。 榛zhēn 1.落叶灌木或小乔木', '小学', '1'),
    ('榜', 'bǎng', '14', '木', '左右', NULL, '榜 木片 载米三十万斛,钱布数十舫,竖榜为城。--《资治通鉴》 匾额 魏时,凌云殿榜未题而匠者误钉之。--《晋书·王献之传》；组词：榜题(匾额题字)；榜字(写在匾额上的大字) 告示应试取录的名单 既而试榜出,时所推誉洞房花烛夜,金榜挂名时', '小学', '1'),
    ('榨', 'zhà', '14', '木', '左右', NULL, '榨 压出物体里汁液的器具 榨,打油具也。--《广韵》 又如榨斗(榨取蔗糖的器具之一);榨床(榨糖、榨油等器具的底座);榨盘(榨的部件之一) 榨 挤压 天晴好薅草,落雨好榨苕；组词：榨斗(榨取蔗糖的器具之一)；榨床(榨糖、榨油等器具的底座)；榨盘(榨的部件之一) 榨 挤压 天晴好薅草,落雨好榨苕', '小学', '1'),
    ('榴', 'liú', '14', '木', '左右', NULL, '榴〈名〉 (形声。从木,留声。本义木名。即石榴”) 同本义 略称石榴”,也简称榴” 武器名 榴liú', '小学', '1'),
    ('槐', 'huái', '13', '木', '左右', NULL, '槐 (形声。从木,鬼声。本义木名。槐树) 同本义 秋试之时) 槐属植物的泛称 槐huái槐树,落叶乔木。羽状复叶。夏季开黄白色花,夹果圆柱形,种子间收缩成串珠状。木材供建筑', '小学', '1'),
    ('槽', 'cáo', '15', '木', '左右', NULL, '槽 (形声。从木,曹声。本义四边高起,中间凹入的畜兽饮食器具) 同本义 骈死于槽枥之间。--唐·韩愈《杂说》 又尝梦三马同食一槽。；组词：马槽；猪槽；槽头(马厩,马圈)；槽子(槽；养牲口的槽)；槽道(牲口槽；规矩) 表面上比较大比较长的凹痕 于木槽中下水,脚', '小学', '1'),
    ('樊', 'fán', '15', '木', '上下', NULL, '樊〈名〉 (形声,棥声。棥”意思是篱笆,在字中也具有表意作用。本义篱笆) 同本义 营营青蝇,止于樊。；组词：樊棘(荆棘篱笆)；樊鹿(樊篱中的鹿)；樊圃(有篱的园圃) 关鸟兽的笼子 泽雉十步一啄,百步一饮,不蕲畜乎樊中', '小学', '1'),
    ('樟', 'zhāng', '15', '木', '左右', NULL, '樟 常绿乔木 樟zhāng 虫剂,还可用于制造炸药等。', '小学', '1'),
    ('模', 'mó', '14', '木', '左右', NULL, '模 (形声。从木,莫声。本义铸造器物的模子) 同本义 模,法也。--《说文》。按,水曰法,木曰模,土曰型,金曰閒,竹曰筪。 缤乎其犹模绣也。--《书·大传》。注模所琢文章之范；组词：模度(标准)；模准(样板,规范)；模宪(法则) 楷式,榜样', '小学', '1'),
    ('横', 'héng', '15', '木', '左右', NULL, '横〈名〉 (形声。从木,黄声。本义门框下部的横木) 同本义 横,闲木也。--《说文》。字亦作桁。 以横为之。--《诗·陈风·横门之下》；组词：横轼(古代车前供人凭倚的横木) 侧,旁边 时横雙以阳遂', '小学', '1'),
    ('樱', 'yīng', '15', '木', '左右', NULL, '樱 (形声。从木,婴声。本义木名。即樱桃树”) 同本义。泛指其树、其花、其果 樱桃花 尚疑樱欲吐,已怪菊成漂。--王安石《雨中》；组词：樱桃(借指美人的小口,谓其红润如樱桃)；樱桃九熟(骨牌戏用语,指两张地牌,一张么四共九点红点)；樱笋(樱桃与春笋)；樱笋', '小学', '1'),
    ('橄', 'gǎn', '15', '木', '左右', NULL, '橄榄 华大妈也黑着眼眶,笑嘻嘻的送出茶碗茶叶来,加上一个橄榄,老栓便去冲了水。--鲁迅《药》 橄榄绿色 橄榄枝 橄gǎn 1.橄榄树,我国特产。常绿乔木,羽状复叶,开白花', '小学', '1'),
    ('橘', 'jú', '16', '木', '左右', NULL, '橘 (形声。 从木, 矞声。 本义 橘树。果实也称橘”) 同本义 许多油腺, 广泛应用在糖果、 点心、 蜜饯和烹调方面, 通常有甜味或酸味', '小学', '1'),
    ('橙', 'chéng', '16', '木', '左右', NULL, '橙 (形声。从木,登声。本义果树名,果实叫橙子) 同本义 橙色 橙 1常绿乔木或灌木。果实叫橙子,呈圆形,果皮红黄色。 2红和黄合成的颜色。 橙chéng常绿乔木。花白色', '小学', '1'),
    ('橡', 'xiàng', '15', '木', '左右', NULL, '橡 栎树的别名 柞之实谓之橡。--《小尔雅》 栎有两种一种不结实者,...一种结实者,其名曰栩,其实为橡', '小学', '1'),
    ('橱', 'chú', '16', '木', '左右', NULL, '橱〈名〉 (形声。从木,厨声。本义 放置东西的家具)同本义 橱 chú前面有门的放置衣物的家具衣~、壁~。 橱(櫥)chú放置衣物的家具,前面有门书~。衣~儿。碗~子。', '小学', '1'),
    ('檀', 'tán', '17', '木', '左右', NULL, '檀〈名〉 (形声。从木,亶声。本义木名。古书中称檀的木很多,时无定指。常指豆科的黄檀,紫檀(即红木);榆科的青檀)；组词：檀车(古代车子多用檀木为之,故称)；檀板(乐器名', '小学', '1'),
    ('檐', 'yán', '17', '木', '左右', NULL, '檐 (形声。从木,詹声。本义屋檐) 同本义 复庙重檐。--《礼记·明堂位》。注重檐,重承壁材也。” 榆柳荫后檐,桃李罗堂前。--晋·陶潜《归园田居》 檐牙高啄(檐牙屋顶伸出的边沿；组词：檐石(屋檐下的石板)；檐宇(屋檐)；檐花(靠近屋檐下边开的花)；檐板(屋檐板)；檐阴(屋檐下阳光不到处)；檐梁(檐下的屋', '小学', '1'),
    ('檩', 'lǐn', '17', '木', '左右', NULL, '檩 架在房梁上托住椽子的横木。也称桁条”、檩条”、檩子” 檩,屋上横木。--《集韵》 檩条 檩子 檩(檁)lǐn也叫"桁条"。屋上托住椽子或屋面板底的横木。', '小学', '1'),
    ('檬', 'méng', '17', '木', '左右', NULL, NULL, '小学', '1'),
    ('欠', 'qiàn', '4', '欠', '上下', NULL, '欠〈动〉 (象形。甲骨文字形,象人张着口打呵欠。小篆字形下面是人(儿),上面象人呼出的气。本义打呵欠)；组词：呵欠(哈欠) 身体或身体的一部分稍微向上移动 犹恐是梦,忙又将身子欠起来', '小学', '1'),
    ('次', 'cì', '6', '欠', '左右', NULL, '次 (形声。从欠,二声。本义临时驻扎和住宿) 同本义 次,舍也。--《礼记·檀弓上》注 楚师伐郑,次于鱼陵。--《左传·襄公十八年》 泰伯素服郊次；组词：次止(驻止；止宿) 次 第二,居其次 凡用兵之法,全国为上,破国次之', '小学', '1'),
    ('欢', 'huān', '6', '欠', '左右', NULL, '欢 (形声。从欠,雚声。本义喜悦,高兴) 同本义 欢,喜乐也。--《说文》 君子不尽人之欢。--《礼记·曲礼》 夫妇不得不髈；组词：欢容(喜悦的容颜)；欢 欢 (歡、懽、髈、讙)huān 1.喜悦,高兴~喜', '小学', '1'),
    ('欣', 'xīn', '8', '欠', '左右', NULL, '欣〈形〉 (形声。从欠,斤声。实与忻同字。本义喜悦) 同本义 欣,笑喜也。--《说文》。段注言部詃下曰‘喜也。’义略同。” 欣,乐也。--《尔雅》 旨酒欣欣；组词：欣惧(欣喜而惶恐)；欣赞(欣喜赞美)；欣欢(欣喜欢乐)；欣赖(欣喜仰赖) 欣〈动〉 爱戴 百姓欣而奉之,国可以固', '小学', '1'),
    ('欧', 'ōu', '8', '欠', '左右', NULL, '欧 通讴”。歌唱 百姓欧歌。--《隶释·三公山碑》 又如欧歌(讴歌,歌颂) 同驱” 或导之以德教,或欧之以法令。。--《大戴礼·礼察》 驱使;疾行 通殴”；组词：欧歌(讴歌,歌颂) 同驱” 或导之以德教,或欧之以法令', '小学', '1'),
    ('欲', 'yù', '11', '欠', '左右', NULL, '欲 (形声。从欠,谷声。欠”表示有所不足,故产生欲望。本义欲望;嗜欲) 同本义 欲,贪欲也。；组词：欲令智昏(欲火使人丧失理智)；欲障(嗜欲)；欲海(佛教语', '小学', '1'),
    ('欺', 'qī', '12', '欠', '左右', NULL, '欺〈动〉 (形声。从欠,其声。欠”与出气、说话有关。本义欺骗) 同本义 欺,诈欺也。--《说文》 仁义修立谓之任,反任为欺。--《贾子道术》 禄不遂行兹谓欺；组词：欺诳(欺瞒)；欺上罔下(对上欺骗,对下隐瞒)；欺诞(夸大欺骗)；欺谩(欺骗)；欺三瞒四(隐蔽实情欺骗他人)；欺天罔人(骗', '小学', '1'),
    ('款', 'kuǎn', '12', '欠', '左右', NULL, '款 (会意。从欠,塞。省。本义真诚;诚恳) 同本义 款,诚也。--《广雅·释诂一》 谒款天神。--《史记·司马相如传》 欲效其款款之愚。--《汉书·司马迁传》 又 辞气愿款；组词：款服(诚心归服)；款款深深(亲切；恳挚)；款交(至交)；款语(亲切谈话)；款语温言(真诚而柔和的话)；款心(诚心)；款迎', '小学', '1'),
    ('歇', 'xiē', '13', '欠', '左右', NULL, '歇 (形声。从欠。曷声。歇息与出气有关,故从欠”。本义休息) 同本义(侧重于放松身体的紧张状态以消除疲劳) 歇,息也。；组词：歇泊(休息)；歇子(小歇；稍憩)；歇午(歇中,歇晌', '小学', '1'),
    ('歉', 'qiàn', '14', '欠', '左右', NULL, '歉〈形〉 (形声。从欠,兼声。本义吃不饱) 同本义 歉,食不满也。--《说文》 健儿立霜雪,腹歉衣裳单。--李商隐《行次西郊作诗》 收成不好 一谷不升曰歉。--《广雅》；组词：歉荒(歉收；灾荒)；歉俭(荒歉)；歉薄(收成微薄) 贫困 惭愧', '小学', '1'),
    ('歌', 'gē', '14', '欠', '左右', NULL, '歌 (形声。从欠,哥声。从欠”,表示与口有关系。本义唱) 同本义 歌,咏也。--《说文》 歌者,长引其声以诵之也。--《说文系传》 不鼓缶而歌。--《易·离》 歌永言；组词：对歌(一问一答地 歌gē 1.能唱的诗、词语诗~', '小学', '1'),
    ('止', 'zhǐ', '4', '止', NULL, NULL, '止 (趾”的本字。象形。甲骨文字形。上象脚趾头,下象脚面和脚掌。本义脚) 同本义 止,下基也。象草木出有址,故以止为足。', '小学', '1'),
    ('正', 'zhèng', '5', '止', '上下', NULL, '正 农历一年的第一个月 正,岁之首月,夏以建寅月为正,殷以建丑月为正,周以建子月为正。--《集韵·清韵》 箭靶的中心 终日射候,不出正兮', '小学', '1'),
    ('此', 'cǐ', '6', '止', '左右', NULL, '此 (会意。从止,从人。甲骨文字形,左边是一只脚(止),右边是人”,意思是一只脚踩在别人身上,是跐”的本字。1本义踩,踏。2指示代词,这) 这;这个 陈康肃公尧咨善射,当世无双；组词：此等(这样)；此生(这辈子)；此地(这里)；此个(这个)；此家(此人) 表示此时或此地 如此,这般 虎因喜,计之曰技止此', '小学', '1'),
    ('步', 'bù', '7', '止', NULL, NULL, '步 (会意。甲骨文字形,由两只脚的象形符号重迭而成,表示两脚一前一后走路。本义行走) 同本义 步,行也。；组词：止步；信步(随意走动；散步)；步步虚心(时时虚怀若谷,毫不自满)；步阁(步廊,走廊)；步趋(行走) 以脚步测量远近 步', '小学', '1'),
    ('武', 'wǔ', '8', '止', NULL, NULL, '武 (会意。从止,从戈。据甲骨文,人持戈行进,表示要动武。本义勇猛;猛烈) 同本义 楚庄王曰,夫文止戈为武。又曰,夫武禁暴戢兵保大定功安民和财者也。；组词：英武(英俊威武)；威武(武力；权势；力量强大)；武色(凶猛的神色)；武车(威猛的兵车)；武健(勇武刚健)；武断乡曲(以威', '小学', '1'),
    ('歧', 'qí', '8', '止', '左右', NULL, '歧〈形〉 (同跂”。形声。从止,支声。或作岐”。本义多余的脚趾) 同本义 跂,《说文》足多指也。”或作枝歧。；组词：歧歧(禽鸟举翅飞行的样子)；歧旨(歧义)；歧言(指离别之言)；歧意(二心) 不同,不一致,有差别 歧qí 1.岔道,大路', '小学', '1'),
    ('歪', 'wāi', '9', '止', '上下', NULL, '歪 (会意∠不正二字为一字,不正”为歪。本义不正,偏斜) 同本义 适值公案桌歪欹,...其案桌遂不歪欹。--明·孙高亮《于谦全传》；组词：歪辣(脚跟不正', '小学', '1'),
    ('歹', 'dǎi', '4', '歹', '上下', NULL, '歹 (象形。本作歺”,音??。甲骨文字形,象有裂缝的残骨。隶变作歹”。歹”是汉字部首之一,从歹”的字多与死、坏或不吉祥等义有关。1本义残骨。《说文》 列 骨之残也。” 2坏) 坏', '小学', '1'),
    ('死', 'sǐ', '6', '歹', NULL, NULL, '死 (会意。小篆字形。右边是人,左边是歺”,残骨,指人的形体与魂魄分离。本义生命终止) 同本义 死,民之卒事也。；组词：死生(死亡和生存)；死过(死去,去世)；死限(死期,寿命的期限) 死sǐ 1.生物失去生命,跟"活"相对~亡', '小学', '1'),
    ('歼', 'jiān', '7', '歹', '左右', NULL, '歼 (形声。从歹(表示与死有关),韱声。本义消灭) 同本义 歼,微尽也。--《说文》 歼,尽也。--《尔雅》 歼我良人。--《诗·秦风·黄鸟》 齐人歼于遂；组词：歼夷(杀光夷平)；歼殄(消灭,灭绝)；歼除(灭绝铲除)；歼殛(消灭)；歼夺(使丧之)；歼一警百(同杀一儆百”,杀一个人来', '小学', '1'),
    ('殃', 'yāng', '9', '歹', '左右', NULL, '殃 (形声。从歺,央声。歺,剔肉后残剩的骨头。多与死亡、灾祸有关。本义祸害,灾难) 同本义 殃,咎也。；组词：殃煞(骂人话', '小学', '1'),
    ('殉', 'xùn', '10', '歹', '左右', NULL, '殉 (形声。从歹(本作歺),旬声。歺,剔过肉剩下的骨头,常与死亡”有关。本义殉葬;以人从葬)；组词：殉死；殉葬 献身或丧生 今世俗之君子,多危身弃生以殉物', '小学', '1'),
    ('殊', 'shū', '10', '歹', '左右', NULL, '殊 (形声。从攴,朱声。小篆字形。攴,分解后剩下的骨头。隶变为歹”。本义斩首,断其首身而死)；组词：不殊(不死) 断绝 殊,断也', '小学', '1'),
    ('残', 'cán', '9', '歹', '左右', NULL, '残 (形声。从歹)声。从歹”表示与死亡有关。本义伤害) 同本义 残,伤也。--《苍颉篇》 昔智伯瑶残范中行。--《战国策·秦策》。注灭也。” 废为残贼；组词：摧残(使蒙受严重损失)；残心(残害人的心)；残贼(杀害)；残灭(残杀毁灭)；残 cán 1不完整~缺', '小学', '1'),
    ('殖', 'zhí', '12', '歹', '左右', NULL, '殖 (形声。从歺,直声。歺,残骨,隶书写作歹”。本义脂膏因放置时间过久而变质) 同本义 殖,殖膏久殖也。；组词：生殖(生物产生幼小个体以繁殖后代)；养殖(培育和繁殖) 经营,从事买卖活动 父宗善殖财货,富拟王侯', '小学', '1'),
    ('殴', 'ōu', '8', '殳', '左右', NULL, '殴 (形声。从殳,区声。殳,古代兵器,用以撞击。本义打击,捶击) 同本义 殴,捶击物也。--《说文》 后数复殴伤郎。--《汉书·梁王襄传》 或至相殴；组词：殴曳(殴打拖曳)；殴仗(以仗殴打)；殴逐(殴打追逐)；殴伤(殴斗致伤,打伤)；殴击(殴打)；殴骂(打骂)；殴挞(殴打,鞭', '小学', '1'),
    ('段', 'duàn', '9', '殳', NULL, NULL, '段 (形声。从殳,聑声。殳”,是古代的一种兵器,这里用作意符,表示与手持器械的动作有关。金文字形,会意,字形象手持物在山崖中敲棰石之形。本义锤击)；组词：段氏(锻工', '小学', '1'),
    ('殷', 'yīn', '10', '殳', '左右', NULL, '殷 yan 黑红色 殷红 殷红的血迹 血流殷地。--清·薛福成《观巴黎油画记》 殷 yin (会意。从殷从殳。本义盛乐)', '小学', '1'),
    ('殿', 'diàn', '13', '殳', '左右', NULL, '殿 (形声。本义击声) 古代泛指高大的房屋,后专指供奉神佛或帝王受朝理事的大厅 殿,堂之高大者也。；组词：宫殿(泛指帝王居住的高大华丽的房屋)；殿陛(帝王宫殿的台阶', '小学', '1'),
    ('毁', 'huǐ', '13', '殳', '左右', NULL, '毁〈动〉 (形声。从土”,表示与瓦器有关。本义瓦器缺损) 毁坏;破坏 毁山一毛。--《列子·汤问》 毁于椟中。--《论语·季氏》 毁其外门。 毁其盆', '小学', '1'),
    ('毅', 'yì', '15', '殳', '左右', NULL, '毅 (形声。从殳,殳”指兵器。本义意志坚强、果断) 同本义 毅,有决也。--《说文》 毅,强而能断也。--《论语·泰伯》 刚、毅、木、讷近仁。--《论语·子路》 士不可以不弘毅；组词：毅武(刚强勇武)；毅烈(刚毅节烈) 坚决 心毅,则憎心见于下', '小学', '1'),
    ('母', 'mǔ', '5', '母', NULL, NULL, '母 (象形。甲骨文字形,象母亲有乳之形。本义母亲) 同本义 母,牧也。从女。象怀子形,一曰,象乳子也。；组词：母难(生日', '小学', '1'),
    ('每', 'měi', '7', '母', NULL, NULL, '每 (形声。小篆字形,从屮,母声。屮,草木初生。一说每”为母”的异体字。本义草旺盛生长)；组词：每常间(往日,平常)；春秋佳日,每作郊游 每一次 相如每朝', '小学', '1'),
    ('毒', 'dú', '9', '母', '上下', NULL, '毒 (会意。从屮(象草木初生),毒声。本义毒草滋生) 毒物;毒纯洁 毒,厚也,害人之草,往往而生。；组词：服毒；下毒；毒汁,毒矢(毒箭)；毒尽癍回(出天花后身上的癍痕消退)；毒女(染有病毒的女子)；毒熨(用药物熨贴毒病患处以治', '小学', '1'),
    ('比', 'bǐ', '4', '比', '左右', NULL, '比 (会意。从二匕,匕亦声。甲骨文字形,象两人步调一致,比肩而行。它与从”字同形,只是方向相反。《说文》二人为从,反从为比。”本义并列;并排)', '小学', '1'),
    ('毕', 'bì', '6', '比', '上下', NULL, '毕 (会意。甲骨文字形,上端象网形,下端是柄,古时用以捕捉鸟兽、老鼠之类的器具。金文又在上面加个田”,意思是田猎所用的网。本义打猎用的有长柄的网)；组词：毕戈(毕为捕兽所用之网,戈为射鸟所用的系绳之箭', '小学', '1'),
    ('毙', 'bì', '10', '比', '上下', NULL, '毙 (形声。从死,敝声。在先秦古书中的獘,在流传中往往被改成斃。本义仆倒;倒下去) 同本义 郑人击简子中肩,毙于车中。；组词：毙死(仆倒而死)；毙踣(倒毙) 垮台,失败 多行不义,必自毙', '小学', '1'),
    ('毛', 'máo', '4', '毛', NULL, NULL, '毛 (象形。金文字形。毛”是汉字的一个部首,从毛”的字多与皮毛有关。本义眉毛、头发、兽毛)', '小学', '1'),
    ('毡', 'zhān', '9', '毛', '半包围', NULL, '毡 (形声。从毛,占声。本义加工羊毛或其他动物毛而成的块片状材料) 同本义 氈,撚毛也。--《说文》 共其毳毛为毡,以待邦事。--《周礼·天官·掌皮》；组词：毡单(毡垫)；毡布(指毛织成的布)；毡车(以毛毡为篷的车子)；毡衫(毡制的衣衫)；毡屋(即毡帐)；毡席(毡制的铺垫用具)', '小学', '1'),
    ('毫', 'háo', '11', '毛', '上下', NULL, '毫〈名〉 (毫为豪的俗字。形声。从毛,高省声。本义长而尖的毛) 同本义 未成毫狗。--《尔雅·释畜》；组词：毫光(如毫毛的光芒 )；毫芒(毫毛的细尖)；毫黍(毫毛与黍粒', '小学', '1'),
    ('毯', 'tǎn', '12', '毛', '半包围', NULL, '毯〈名〉 厚实有毛绒的织品 毯,毛席。--《广韵》。又如毯布(用细毛织成的布);线毯;地毯;挂毯;毛毯;绒毯 毯子 毯tǎn毯子,厚实而有毛绒的织物毛~。床~。地~。壁~。', '小学', '1'),
    ('氏', 'shì', '4', '氏', NULL, NULL, '氏 (象形。甲骨文字形,象物体欲倾倒而将其支撑住的形象。是支”的本字。本义古代贵族标志宗族系统的称号)', '小学', '1'),
    ('民', 'mín', '5', '氏', NULL, NULL, '民 (指事。从古文之象。古文从母,取蕃育意。古代指黎民百姓,平民。与君、官对称) 同本义 民,众萌也。从古文之象。', '小学', '1'),
    ('氓', 'máng', '8', '氏', '左右', NULL, '氓 mang --流氓”原指无业游民,后来指品质恶劣、不务正业、为非作歹的人 氓 meng (会意。从民,亡声。亡”亦有表意作用,指自彼来此之民。本义外来的百姓)；组词：群氓(统治阶级对百姓的蔑称)；氓 氓máng 1. 15."', '小学', '1'),
    ('气', 'qì', '4', '气', NULL, NULL, '气 (象形。甲骨文、小篆字形。象云气蒸腾上升的样子。气”是汉字部首之一。本义云气) 同本义 气,云气也。；组词：气朔(指显示吉凶的云气和每月的朔日)；气祲(古代泛指据以占卜吉凶的云气)；气纬(指云气星象)；气晕(日、月四周所生的晕气', '小学', '1'),
    ('氛', 'fēn', '8', '气', '半包围', NULL, '氛 (形声。从气,分声。本义凶气,古时迷信说法指预示吉凶的云气,多指凶气 ) 同本义 楚氛甚恶。；组词：氛慝,氛邪(邪恶之气)；氛厉(祸害之气)；氛霓(凶气,妖气)；氛杂(杂乱之气)；氛秽(邪恶肮脏之气)；氛妖(妖气) 泛指', '小学', '1'),
    ('氢', 'qīng', '9', '气', '半包围', NULL, '氢 化学元素名。一价非金属元素。在正常情况下,氢是无色、无臭、极易燃烧的双原子气体,在地球上和地球大气中只存在极稀少的游离状态氢 氢(氫)qīng化学元素。符号h', '小学', '1'),
    ('氧', 'yǎng', '10', '气', '半包围', NULL, '氧 一种非金属元素,原子序数8,主要是两价,一般是无色无嗅无味不可燃的双原子气体,稍溶于水,是地球上含量最丰富的元素之一,以游离状态存在于空气中,按体积计,空气含氧达 21%', '小学', '1'),
    ('氨', 'ān', '10', '气', '半包围', NULL, '氨〈名〉 氮和氢的化合物nh3,比空气轻,有极强的刺激性气味,易溶于水,冷却加压下很易冷凝成液体,因此常用液氨蒸发吸热来人工致冷。', '小学', '1'),
    ('氮', 'dàn', '12', '气', '半包围', NULL, '氮 一种普通的非金属元素,原子序数7,游离态的氮通常为无色、无嗅、无味的不溶性双原子惰性气体,约占空气的78%(按体积计) 氮 dàn符号n。无色、无臭气体。不能燃烧', '小学', '1'),
    ('氯', 'lǜ', '12', '气', '半包围', NULL, '氯 lǜ卤族元素。符号cl新拉chlorum。黄绿色,异臭,有毒,有腐蚀性。性活泼,溶于水。用于漂白、杀菌,制漂白粉、染料、颜料和合成盐酸,在生产农药六六六', '小学', '1'),
    ('水', 'shuǐ', '4', '水', NULL, NULL, '水 (象形。甲骨文字形。中间像水脉,两旁似流水。水”是汉字的一个部首。从水的字,或表示江河或水利名称,或表示水的流动,或水的性质状态。本义以雨的形式从云端降下的 液体', '小学', '1'),
    ('永', 'yǒng', '5', '水', NULL, NULL, '永 (象形。小篆字形,象水流曲曲折折的样子。本义水流长) 同本义 永,水长也。象水巠理之长。', '小学', '1'),
    ('汁', 'zhī', '5', '氵', '左右', NULL, '汁 (形声。从水,十声。本义含有某种物质的液体) 同本义 汁,液也。--《说文》 拾瀋。--《左传·哀公三年》。释文北土呼汁为瀋。” 函牛之鼎以亨鸡,多汁则淡而不可食；组词：汁子(汁液；汤汁)；汁滓(汁液与渣滓)；汁献(求神用香酒)；墨汁；豆汁；胆汁；茄汁；酸橙汁 雨夹雪 汁zhī含有某种物质', '小学', '1'),
    ('求', 'qiú', '7', '水', NULL, NULL, '求 (《说文》以求”为裘”之古文。省衣,象形。金文与战国古文作求”。本是裘衣”的裘”。古人皮衣一般毛朝外,所以甲骨文在衣”字外加毛。表示裘衣。本义皮 衣) 裘”的古字；组词：求浼(请求；央求)；求神福(祈求神灵保佑；祝福)；求张良,拜 求qiú 1.寻找,想办法得到~解', '小学', '1'),
    ('汇', 'huì', '5', '氵', '左右', NULL, '汇 (形声。从匚,筐子,淮声。本义盛器) 同本义 汇,器也。--《说文》。段玉裁注谓有器名汇也。” 用外币或本国货币兑换的票据 收集；组词：汇行(绕道行走) 以即期汇票、 汇(滙、卹、 4. 5.彙)huì 1.水流会合~成江河', '小学', '1'),
    ('汉', 'hàn', '5', '氵', '左右', NULL, '菡萏 (形声。从苃,函声。菡萏。本义荷花) 同本义 迨至菡萏成花。--明·李渔《闲情偶寄·种植部》 菡萏 汉(漢)hàn 1.朝代名 1汉朝(西汉、东汉)', '小学', '1'),
    ('汗', 'hàn', '6', '氵', '左右', NULL, '汗 可汗,古代鲜卑、柔然、突厥、回纥、蒙古等族对其统治者的称号 汗,可汗。蕃王称。--《广韵》 咸丰四年,土谢图汗、车臣汗两部汗、王、公、台吉等请捐助军需,温旨鄐之', '小学', '1'),
    ('汛', 'xùn', '6', '氵', '左右', NULL, '汛 同本义 汛,洒也。--《说文》。按,此字经传多误作汛滥之汛。 汛埽反道。--《礼记·郊特性》 汛拚席。--《管子·弟子职》 况尽汛扫前圣数千载功业,专用己之私；组词：汛扫(洒扫)；汛逐(清扫驱除) 防守 大军汛黄河而角其前,荆州下宛、叶而犄其后', '小学', '1'),
    ('汞', 'gǒng', '7', '水', '上下', NULL, '汞 本义一种有毒的银白色一价和二价重金属元素,它是常温下唯一的液体金属,游离存在于自然界并存在于辰砂、甘汞及其他几种矿中。常常用焙烧辰砂和冷凝汞蒸气的方法制取 汞', '小学', '1'),
    ('江', 'jiāng', '6', '氵', '左右', NULL, '江 (形声。从水,工声。本义长江的专称) 同本义 江,江水也。犊 江之永矣。--《诗·周南·汉广》 滔滔江汉。--《诗·小雅·四月》 江上几人在,天涯孤棹还；组词：江汉(长江与汉水)；江水(即长江)；江左烟霞(江东的山水风景', '小学', '1'),
    ('池', 'chí', '6', '氵', '左右', NULL, '池 (形声。从水,也声。本义水停积处) 水塘 池,停水曰池。--《广韵》 穿地畜水,圆者曰池,方者曰塘。--《中文大辞典》 池之竭矣。--《诗·大雅·召》 或饮于池；组词：游泳池；池苑(池林园', '小学', '1'),
    ('污', 'wū', '6', '氵', '左右', NULL, '污 (形声。从水,于声。本义停积不流的水) 浊水池。一说小水坑 污,秽也,一曰小池为污。--《说文》 字亦作汙 潢汙行潦之水。--《左传·隐公三年》。服注水不流谓之汙；组词：污池(蓄水的池子) 污垢,脏东西 污,秽也', '小学', '1'),
    ('汤', 'tāng', '6', '氵', '左右', NULL, '汤汤 shang 衔远山,吞长江,浩浩汤汤,横无际涯。--范仲淹《岳阳楼记》 东边是流水汤汤的延河,隔河是清凉山。', '小学', '1'),
    ('汪', 'wāng', '7', '氵', '左右', NULL, '汪〈形〉 (形声。从水,王声。本义深广的样子) 同本义 汪,深广也。--《说文》 汪是土也。--《国语·晋语》。注大貌。” 泽汪濊。--《汉书·礼乐志》 汪汪若千顷陂；组词：汪波(盈盈水波)；汪汪(水宽广的样子)；汪浵(水深的样子)；汪流(水深的样子)；汪然(深广的样子)；汪茫(气势广大的样子', '小学', '1'),
    ('汰', 'tài', '7', '氵', '左右', NULL, '汰〈动〉 淘洗 作热汤,于大盆中浸豆黄。良久,淘汰,挪去黑皮,漉而蒸之。--《齐民要术》 淘汰 洗涤、清洗 总为设教令,明赏罚,磨治洗汰,其俗一变', '小学', '1'),
    ('汹', 'xiōng', '7', '氵', '左右', NULL, '汹 (形声。从水,凶声。本义水猛烈地向上涌腾) 同本义。通常作汹涌” 洶,涌也。--《说文》 大江动我前,汹若溟渤宽。--唐·杜甫《大会渡》 填其汹渊,毋使水清；组词：汹呶(水势喧嚣翻腾貌)；汹急(水势湍急)；汹怒(水流激荡)；汹然(汹涌翻腾貌)；汹溶(水势翻腾上涌) 汹 形容声音大；喧', '小学', '1'),
    ('汽', 'qì', '7', '氵', '左右', NULL, '汽〈动〉 水枯竭 汽,水涸也。--《说文》 泣下 汽...或曰泣下。--《说文》 汽在饭上的...还有碗腊肉', '小学', '1'),
    ('沃', 'wò', '7', '氵', '左右', NULL, '沃 (形声。从水,夭声。本义把水从上浇下) 同本义 使火燃,以水沃之,可谓水贼火。--《论衡·偶然》；组词：沃盥(浇水洗手)；沃酹(以酒浇地而祭奠)；沃漏(以沸水浇灌漏壶)；沃醊(以酒浇地而祭祀)；沃雪(以热水浇雪', '小学', '1'),
    ('沈', 'shěn', '7', '氵', '左右', NULL, '沈 (形声。从水,冘声。甲骨文字形,中间是牛,周围是水,表示把牛沉到水中。商代祭祀用牲的方法。本义没入水中)；组词：石沉大海；沉溺(沉没水中) 埋没 投水 沈chén 1.没入水中,跟"浮"相对~舟', '小学', '1'),
    ('沉', 'chén', '7', '氵', '左右', NULL, '沉 (形声。从水,冘声。甲骨文字形,中间是牛,周围是水,表示把牛沉到水中。商代祭祀用牲的方法。本义没入水中)；组词：石沉大海；沉溺(沉没水中) 埋没 投水 沉 chén 1落入水中石~大海', '小学', '1'),
    ('沐', 'mù', '7', '氵', '左右', NULL, '沐 (形声。从水,木声。本义洗头发) 同本义 沐,濯发也。--《说文》 予发曲局,薄言归沫。--《诗·小雅·采绿》 共王之沐浴。--《周礼·宫人》 沐则心覆；组词：沐发(洗发)；沐澡(洗头洗澡)；沐濯(洗头洗澡)；沐芳(用香草水洗头)；沐巾(洗发用的巾)；沐盆 沐mù洗头发~雨栉风(', '小学', '1'),
    ('沙', 'shā', '7', '氵', '左右', NULL, '沙〈名〉 (会意。从水,从少。《说文》水少沙见。”金文字形,左边是水,右边少”象沙粒形。本义极细碎的石粒)；组词：沙芦(泥沙里的芦苇)；沙砾(细沙和碎石', '小学', '1'),
    ('沛', 'pèi', '7', '氵', '左右', NULL, '沛〈名〉 (形声。从水,市声。本义沛水) 同本义 沛,沛水。出辽东番汗塞外,西南入海。--《说文》 泽名。沛泽 齐侯田于沛。--《左传·昭二十年》。注沛,泽名', '小学', '1'),
    ('沟', 'gōu', '7', '氵', '左右', NULL, '沟 (形声。从水,冓声。本义田间水道) 同本义 沟,水渎,广四尺,深四尺。--《说文》 九夫为井,井间广四尺、深四尺,谓之沟。--《考工记·匠人》 十夫有沟,沟上有畛；组词：沟洫(沟浍', '小学', '1'),
    ('没', 'méi', '7', '氵', '左右', NULL, '没 不领有,不具有,不存在 恐怕没来由走去撞在乱兵之手,死了也没说处。--《二刻拍案惊奇》；组词：没谱(没有标准)；没根蒂(没有根据)；没脚手(没有雨具)；没个了局(没有了结；没完没了)；没个道理(没有办法)；没仁没义', '小学', '1'),
    ('沥', 'lì', '7', '氵', '左右', NULL, '沥 (形声。从水,歷声。字又作砯”,从石从水会意。本义踩着石头过河) 水、泪、酒等液体下滴 动滴沥以成响,殷雷应其若警。--汉·王延寿《鲁灵光殿赋》 以杓酌油沥之；组词：沥血(刺破皮肤使滴血,以发誓、表竭诚或作祭祀)；沥液(水滴)；沥滴(水下滴) 竭尽(如自己的)全力 从毛孔或裂缝小口慢慢', '小学', '1'),
    ('沦', 'lún', '7', '氵', '左右', NULL, '沦 (形声。从水,仑声。本义水起微波) 同本义 沦,小波为沦。--《说文》 河水清且沦猗。--《诗·魏风·伐檀》。传小风水成文转如轮也。” 从流而风曰沦。沦,文貌。” 沉沦；组词：沦化(变化；沦落)；沦降(沦落)；沦倾(陷落)；沦滞(陷入苦境) 灭亡；丧亡 沦,一曰没也', '小学', '1'),
    ('沧', 'cāng', '7', '氵', '左右', NULL, '沧 (形声。从水,仓声。本义寒冷) 同凔”‘冷 沧,寒也。--《说文》 天地之间有沧热。--《周书·周祝》 疾养滄热,滑铍轻重以形体异。--《荀子·正名》 欲汤之滄,一人炊之；组词：沧凉(寒凉；寒冷)；沧热(寒冷与炎热) 通苍”', '小学', '1'),
    ('沪', 'hù', '7', '氵', '左右', NULL, '沪 捕鱼的竹栅 潮生鱼沪短,风起鸭船斜。--陆游《村舍》 列竹于海澨曰沪。--唐·陆龟蒙《渔具》诗序 上海的简称 沪(滬)hù 1.上海的简称', '小学', '1'),
    ('沫', 'mò', '8', '氵', '左右', NULL, '沫 (形声。从水,末声。本义沫水) 同本义 沫,沫水也。出蜀西徼外东南入江。--《说文》 古水名,即今四川省大渡河 泡沫,沫子 瀑下一曰沫也。--《说文》 沫流赭；组词：沫血(水面上的泡沫像血一样)；沫雨(骤雨成潦,上浮泡沫)；沫流(冒着泡沫的水流', '小学', '1'),
    ('沮', 'jǔ', '8', '氵', '左右', NULL, '沮 (形声。从水,且声。1本义古水名。在今陕西省。2阻止) 同阻”。阻止,阻遏;终止 乱庶斯沮。；组词：沮挠(阻挠；阻止)；沮丘(背水的山丘)；沮格(阻拦)；沮厄(阻挠遏止)；沮止(阻止,遏止) 畏惧,恐惧 沮之以兵', '小学', '1'),
    ('河', 'hé', '8', '氵', '左右', NULL, '河〈名〉 (形声。从水,可声。本义黄河) 同本义 河,河水出敦煌塞外昆仑山,发原注海。--《说文》 导河积石。--《书·禹贡》 河阳之北。--《列子·汤问》 三豕涉河；组词：河堧(黄河河边之地)；河湟(黄河与湟水)；河朔(泛指黄河北岸的地方)；河洛(黄河与洛水)；河堑(黄河沿岸的壕沟) 河流的', '小学', '1'),
    ('沸', 'fèi', '8', '氵', '左右', NULL, '沸〈形〉 (形声。从水,弗声。本义泉水大量涌出的样子) 同本义 沸,滭沸滥泉也。--《说文》。按,涌出之貌。 觱沸槛泉。--《诗·小雅·采菽》 百川沸騰；组词：沸沸(翻滚涌现的样子；行事迅速果断的样子)；沸射(喷射)；沸然(水腾涌的样子) 水波翻涌的样子 宫殿摆簸,云烟沸涌', '小学', '1'),
    ('油', 'yóu', '8', '氵', '左右', NULL, '油 (形声。从水,由声。本义油水) 同本义 油,油水出武陵孱陵西,东南入江。--《说文》。按,在今湖北荆州府公安县北。 古水名。也作繇”。发源于湖北五峰县界,东流经松滋县界；组词：油尽灯枯(形容人被消耗得心力衰竭,生命垂危)；油盏(油灯)；油海(指特大的油田)；油火虫虫(方言', '小学', '1'),
    ('治', 'zhì', '8', '氵', '左右', NULL, '治 (形声。从水,台声。1本义水名。2引申义治水;整治;修治) 同引申义 昔禹治洪水。--郦道元《水经注》 民治渠。--褚少孙《西门豹治邺》 遂治别院,使夫妇成礼。；组词：治酒(置办酒食)；治步(修整仪容,举止合乎法度)；治任(整理行装)；治行(治严', '小学', '1'),
    ('沼', 'zhǎo', '8', '氵', '左右', NULL, '沼 (形声。从水,召声。本义水池,积水的洼地。上古时期,池和沼都表水池,塘在中古时期才表示水池。一说圆曰池,曲曰沼)；组词：沼沚(池塘', '小学', '1'),
    ('沽', 'gū', '8', '氵', '左右', NULL, '沽 (形声。从水,古声。本义古水名) 同本义 沽,沽水,出渔阳塞外,东入海。--《说文》 古水名,即今河北首河 即今河北省州河。下流为蓟运河；组词：沽酒市脯(买酒买菜)；沽酒(从市场上买来的酒；买酒) 卖,出售', '小学', '1'),
    ('沾', 'zhān', '8', '氵', '左右', NULL, '沾 古水名 沾,沾水,出上党壶关东入淇。从水,占声。--《说文》 淇水支流。源出山西省壶关县南赵掌尖老山南麓,东流入河南省,至鹤壁市西注入淇水。今上流建有弓上水库 沾 假借为霑”', '小学', '1'),
    ('沿', 'yán', '8', '氵', '左右', NULL, '沿 同本义 王沿夏,将欲入鄢。--《左传》 沿于江海,达于淮泗。--《书·禹贡》 又如沿溯(顺水下行与逆水上行);沿涉(顺流而行);沿流(顺流而下) 遵循;因袭 五帝殊时；组词：沿溯(顺水下行与逆水上行)；沿涉(顺流而行)；沿流(顺流而下) 遵循；因袭 五帝殊时,不相沿乐,三王异世,不相袭理', '小学', '1'),
    ('泄', 'xiè', '8', '氵', '左右', NULL, '泄 (形声。从水,世声。本义泄水。在江西) 假借为歇”。发泄;发散 运物之泄也。--《庄子·山木》。司马注发也。” 穷岫泄云。--左思《魏都赋》。注犹出也。” 宗气泄也；组词：泄宣(宣泄,宣露)；泄冤(表白或洗雪冤屈)；泄写(宣泄,倾吐', '小学', '1'),
    ('泉', 'quán', '9', '水', '上下', NULL, '泉〈名〉 (象形。甲骨文字形。象水从山崖泉穴中流出的样子。本义泉水) 同本义 泉,人原也。象水流出成川形。字亦作洤。；组词：温泉；矿泉；清泉；泉根(泉源)；泉脉(地下伏流的泉水)；泉涌(泉川喷涌)；泉鱼(渊鱼)；泉绅(从高山上飞泻下来的泉 泉q', '小学', '1'),
    ('泊', 'bó', '8', '氵', '左右', NULL, '泊 (形声。从水,白声。本义停船) 同本义 西有鸾冈,洪崖先生乘鸾所憩泊也。--《水经注·赣水》 晚泊沙夹,距小孤一里；组词：泊船；泊舟(船停泊靠岸)；泊步(埠头,码头)；泊主(船家)；船泊港外 栖止,停留 独泊灵台侧', '小学', '1'),
    ('泌', 'mì', '8', '氵', '左右', NULL, '泌 分泌 泌 bì地名用字。泌阳。在河南省。又见mì。 泌mì 1.从生物体里产生、排泄某种物质分~。~尿。', '小学', '1'),
    ('法', 'fǎ', '8', '氵', '左右', NULL, '法 (会意。从水”,表示法律、法度公平如水;从廳”,即解廳,神话传说中的一种神兽,据说,它能辨别曲直,在审理案件时,它能用角去触理曲的人。基本义刑法;法律;法度) 同基本义 灋', '小学', '1'),
    ('泛', 'fàn', '7', '氵', '左右', NULL, '泛 (形声。从水,乏声。汎、泛实同一词。本义漂浮) 同本义 汎,浮貌。从水,凡声。与泛略同。与氾迥别。；组词：泛然(漂浮,浮动的样子)；泛浮(漂浮)；泛萍(比喻漂荡 泛 fàn 1.漂浮~船', '小学', '1'),
    ('泞', 'nìng', '8', '氵', '左右', NULL, '泞 (形声。从水,宁声。本义泥浆) 同本义 泞,荥泞也。--《说文》 按,荥泞叠韵连语,小水之貌。 戎马还泞而止。--《左传·僖公十五年》 不泞车辆；组词：泞淖(泥泞；泥淖)；泞溺(被泥泞掩盖)；泞滞(谓泥水淤积难行)；泞潦(泥水淤积)；路泞难行 泞(濘)nìng 泞zhù', '小学', '1'),
    ('泡', 'pào', '8', '氵', '左右', NULL, '泡〈名〉 古水名。又名丰水 泡,泡水,出山阳平乐,东北入泗。--《说文》 鼓起而松软的东西 泡 〈形〉 盛大 泡,盛也。--《方言》二；组词：泡溲(水盛大的样子) 泡 〈量〉 用于屎尿或涕泪 相当于番”、回” 顺便去会制台,着实恭维一泡', '小学', '1'),
    ('波', 'bō', '8', '氵', '左右', NULL, '波 (形声。从水,皮声。本义波浪,水自身涌动而成波动的水面) 同本义 波,水涌流也。--《说文》 规有摩而水有波。--《韩非子·八说》 起波涛。--《淮南子·人间》。注波者,涌起；组词：波磔(向右下捺的一笔叫磔,波浪形的叫波磔)；波查(苦难；折磨)；波平如镜(水面平静如镜)；波臣为虐(指水灾)；波骇(水波', '小学', '1'),
    ('泣', 'qì', '8', '氵', '左右', NULL, '泣〈动〉 (形声。从水,立声。本义无声或低声地哭) 同本义 持其踵为之泣。--《战国策·赵策》 如闻泣幽咽。--唐·杜甫《石壕吏》诗 连拜且泣；组词：泣励(哭着激励)；泣詈(边哭边骂)；泣血捶膺(形容悲痛欲绝的样子)；泣血(无声痛哭,泪如血涌)；泣别(流泪告别) 哭 泣', '小学', '1'),
    ('泥', 'ní', '8', '氵', '左右', NULL, '泥〈名〉 (形声。从水,尼声。本义泥水) 中国古水名,泾水支流,即今甘肃省庆阳地区的东河及其下流马连河 泥,泥水也。出北地郁郅北蛮中。亦曰白马水。一名东河。；组词：泥木(土木)；泥水(带泥土的水)；泥牛(即土牛)；泥冈子(土山冈)；泥坂(土坡)；泥灰(灰土)；泥尘(尘土 泥ní 1.', '小学', '1'),
    ('注', 'zhù', '8', '氵', '左右', NULL, '注 (形声。从水,主声。本义灌入,注入) 同本义 注,灌也。--《说文》 振眜注流。--左思《吴都赋》 丰水东注。--《诗·大雅·文王有声》 声如震雷破山,泪如倾河注海；组词：把酒注到瓶里；注溉(灌溉)；注萤(以水浇灌萤火)；注集(流泻汇集)；注溜(倾泻的水流) 集中；聚集 及弊田,令禽注于虞中', '小学', '1'),
    ('泪', 'lèi', '8', '氵', '左右', NULL, '泪 (形声。从水,戾声。简化字泪”是个从水”从目”的会意字。本义眼泪) 同本义 望其碑者莫不流涕,杜预因名为坠泪碑。；组词：涕泪(先秦时期,涕”指眼泪,后来出现了泪”,表示眼泪,与涕”同义并用)；泪波(泪水如波)；泪泉(指眼泪)；泪球(泪珠,泪', '小学', '1'),
    ('泰', 'tài', '10', '水', NULL, NULL, '泰〈形〉 (形声) 同本义 泰,亦作汰。疑泰、太、汰三形实同字。--朱骏声《说文通训定声》 安定平和 泰,安也。', '小学', '1'),
    ('泳', 'yǒng', '8', '氵', '左右', NULL, '泳 (形声。从水,永声。本义潜行水中;游泳) 同本义 泳,潜行水中也。--《说文》 泳,游也。--《尔雅·释言》 潜行为泳。--《尔雅·释水》 泳之游之；组词：泳涵(涵泳,沉浸)；游泳(人或动物在水里游动)；仰泳；蛙泳 泳yǒng游水游~', '小学', '1'),
    ('泵', 'bèng', '9', '水', '上下', NULL, '泵 音译字。吸入和排除流体的机械。能提升、输送或压缩流体 泵 bèng吸入和排出流体的机械。能把流体抽出或压入容器,也能把液体提送到高处。如水泵。又叫唧筒。 泵pìn 1.方言', '小学', '1'),
    ('泻', 'xiè', '8', '氵', '左右', NULL, '泻 倾泻 泻,倾也。--《玉篇》 以浍写(泻)水。--《周礼·地官·稻人》 急雨如河泻瓦沟,空堂卧对一灯幽。--宋·陆游《雨夜》；组词：泻泪(形容泪流如注)；泻溜(泻下小股水流)；泻月(形容泉水如月光倾洒)；泻润(谓雨水倾泻滋润', '小学', '1'),
    ('泼', 'pō', '8', '氵', '左右', NULL, '泼 (形声。从水,发声。本义水漏出。见《玉篇》。用力向外倒或洒) 同本义 又夹百千求救声,曳屋许许声,抢夺声,泼水声。；组词：泼丢泼养(像泼脏水那样去养育小儿,指让小儿风里吹,泥里滚,反能养大)；泼撒(花钱大手大脚)；泼水难收(比喻不可挽回的局面', '小学', '1'),
    ('泽', 'zé', '8', '氵', NULL, NULL, '泽 (形声。从水。瞘声。本义光泽,润泽) 同本义 泽,光润也。--《说文》 共饭不泽手。--《礼记·曲礼》 泽剑首。--《礼记·少仪》 实诸泽器。--《考工记·慌氏》 顺非而泽；组词：泽雨(润泽万物之雨)；泽器(润泽光滑的器皿)；色泽(颜色和光泽) 水深 泽(澤)zé 1.聚积水的地方沼~〓~', '小学', '1'),
    ('洁', 'jié', '9', '氵', '左右', NULL, '洁 (形声。从水,絜声。本义干净,清洁。按洁”和潔”本是不同的两个字。洁”是河流名,后来成为潔”的俗字,现在是潔”的简化字)；组词：整洁(整齐清洁)；清洁(没有尘土,油垢等)；洁癖(过分爱清洁的癖性)；洁疾(过分爱清洁的特殊行为)；洁粢(洁净的黍稷', '小学', '1'),
    ('洋', 'yáng', '9', '氵', '左右', NULL, '洋 (形声。从水,羊声。本义古水名) 同本义 洋水 昆仓之丘...洋水出焉,而西南流注于丑涂之水。', '小学', '1'),
    ('洒', 'sǎ', '9', '氵', '左右', NULL, '洒 (形声。从水,西声。本义把水散布在地上) 同本义 洒,滌水也。古文以为灑掃言。--《说文》 洒,濯也。--《字林》 一洒之者也。--《孟子》 洒扫室堂及庭；组词：黎明即起,洒扫庭除；洒削(洒水以磨刀)；洒泼(胡乱挥霍)；扫地先洒些水；洒酒(把酒浇洒在地上)；洒削(洒水磨刀) 东西散', '小学', '1'),
    ('洗', 'xǐ', '9', '氵', '左右', NULL, '洗 (形声。从水,先声。据甲骨文,上为足形,下为水形。本义用水洗脚) 同本义 洗,洒足也。；组词：洗头(宋时礼俗', '小学', '1'),
    ('洛', 'luò', '9', '氵', '左右', NULL, '洛〈名〉 (形声。从水,各声。本义水名。指洛水) 同本义 洛,洛水,出左冯翊归德北夷界中,东南入渭。', '小学', '1'),
    ('洞', 'dòng', '9', '氵', '左右', NULL, '洞 (形声。从水,同声。本义水流急) 同本义 洞,疾流也。--《说文》 幽深 广阔 深 清澈 透彻 洞 窟窿;孔穴 心气内洞。--《素问·四气调神大论》。注洞,谓中空也', '小学', '1'),
    ('津', 'jīn', '9', '氵', '左右', NULL, '津〈名〉 (会意。金文字形,从舟,从淮。淮”表示淮水。泛指一般的河流。船停泊在河旁,用来渡河。本义渡口)；组词：津梁(渡口的桥梁)；津人(在渡口以摆渡为生的人)；津门(在河流渡口所设置的关隘)；津吏(掌管桥梁及河流渡口的官吏)；津主', '小学', '1'),
    ('洪', 'hóng', '9', '氵', '左右', NULL, '洪〈名〉 (形声。从水,共声。本义大水) 同本义 洪,洚水也。--《说文》 汤汤洪水方割。--《书·尧典》 洪水芒芒。--《诗·商颂·长发》 洪水横流。--《孟子·滕文公上》；组词：山洪；防洪；蓄洪；分洪；洪河(大河)；洪峰 河道陡窄流急之处 定国既去逾月,复与参寥师放舟洪下,追怀曩游,已为陈迹,喟然', '小学', '1'),
    ('洲', 'zhōu', '9', '氵', '左右', NULL, '洲 (形声。从水,州声。洲”本作州”,后人加水以别州县之字。本义水中的陆地) 同本义 关关雎鸠,在河之洲。；组词：洲沚(洲渚,洲淤', '小学', '1'),
    ('活', 'huó', '9', '氵', '左右', NULL, '活 (形声。从水,昏声。本义流水声。用本义时读 生存。与死”相对 不我活兮。--《诗·邶风·击鼓》 不可活。--《书·太甲》 民非水火不生活；组词：鱼在水里才能活；这个孩子只活三个月；活到高龄而且精力充沛；活头儿(生存的趣味) 救活 臣活之', '小学', '1'),
    ('洼', 'wā', '9', '氵', '左右', NULL, '洼 (形声。从水,圭声。本义深池) 同本义 竏,深池也。从水,窐声。--《说文》 马生渥洼水中。--《汉书·武帝纪》 似洼者。--《庄子·齐物论》 泽无洼水；组词：洼子(低洼存水的地方) 低凹的地方 古水名 渥洼”的省称', '小学', '1'),
    ('洽', 'qià', '9', '氵', '左右', NULL, '洽〈动〉 (形声。从水,合声。本义沾湿,浸润) 同本义 洽,沾也。--《说文》 仁洽道丰。--张衡《东京赋》 是泽南洽而威北畅也。--《汉书·终军传》 内洽五藏；组词：洽濡(沾湿,滋润)；洽润(润泽)；洽衿(沾湿衣襟) 合,符合 以洽百礼', '小学', '1'),
    ('派', 'pai', '9', '氵', NULL, NULL, '派〈名〉 (形声。本义水的支流) 同本义 派,别水也。--《说文》 百川派别。--左思《吴都赋》 九派乎浔阳。--郭璞《江赋》 茫茫九派流中国,沉沉一线穿南北；组词：九派(一般指长江的很多支流)；派流(水的支流) 泛指江河的流水 人物、事物的系统、流别 气派；风度 派pài 1.水的支', '小学', '1'),
    ('流', 'liú', '10', '氵', '左右', NULL, '流〈动〉 (会意。本义水流动) 同本义 观其流泉。--《诗·大雅·公刘》 顄淡滂流。--《文选·马融·长笛赋》 血流殷地。--清·薛福成《观巴黎油画记》 黄河流水；组词：流迸(涌流而出)；流水行云(流动的水和飘浮的云彩)；流冰(冰块在河面上漂动和流动)；流泉(流动的泉水)；引申为流动', '小学', '1'),
    ('浅', 'qiǎn', '8', '氵', '左右', NULL, '浅 通践”。实行,实现 臣之梦浅矣。--《韩非子·难四》 浅 (形声。从水,戔声。本义水不深)', '小学', '1'),
    ('浆', 'jiāng', '10', '水', '上下', NULL, '浆 (从水,将声。本义饮料) 古代一种微酸的饮料 浆,酢浆也。--《说文》 饮酒浆饮俟于东房。--《仪礼·公食礼》 箪食壶浆。--《三国志·诸葛亮传》；组词：浆水(一种饮料)；浆糗(饮料与干粮) 浓厚的液体 浆 用粉浆或米汤浸纱、布、衣服,使干后变硬变挺 浆(漿)jiāng 1', '小学', '1'),
    ('浇', 'jiāo', '9', '氵', '左右', NULL, '浇〈动〉 (形声。从水,尧声。本义沃灌,灌溉) 同本义 浇,沃也。--《说文》 有酒唯浇赵州土。--李贺《浩歌》 浇花亦自有时。--欧阳修《洛阳风俗记》；组词：浇花(用水灌花)；浇溉(灌溉)；浇沃(浇灌) 饮酒 淋；洒 浇铸 浇(澆)jiāo 1.灌溉~花', '小学', '1'),
    ('浊', 'zhuó', '9', '氵', '左右', NULL, '浊 (形声。从水,蜀声。本义浊水) 同本义 浊水出齐郡厉伪山,东北入钜定。--《说文》。今曰北阳水。 源出山东省益都县西南,北流注入小清河 浊 液体浑浊。与清”相对 载清载浊；组词：浊河(混浊的河流', '小学', '1'),
    ('测', 'cè', '9', '氵', '左右', NULL, '测 (形声。从水,则声。本义度量水的深浅) 度量;测量 测,深所至也。--《说文》 测土深。--《周礼·大司徒》。注犹度也。” 穷高极远,而深深厚。--《礼记·乐记》。疏知也；组词：测海(测量海水的深浅', '小学', '1'),
    ('济', 'jì', '9', '氵', '左右', NULL, '济 (形声。从水,齐声。本义水名,即济水。古四渎之一) 同本义。 济,济水也。出常山房子赞皇山东入沞', '小学', '1'),
    ('浑', 'hún', '9', '氵', '左右', NULL, '浑 (形声。从水,军声。本义大水涌流声) 同本义 浑,水喷涌之声也。--《玉篇》 浑,混流声也。--《说文》 溟海浑瀋涌其后。--《文选·张协·七命》 浑浑若川', '小学', '1'),
    ('浓', 'nóng', '9', '氵', '左右', NULL, '浓 (形声。从水,农声。本义露多) 同本义 浓,露多也。--《说文》 零露浓浓。--《诗·小雅·蓼萧》；组词：浓浓(露多的样子) 稠密；厚；多 浓雾半作', '小学', '1'),
    ('浙', 'zhè', '10', '氵', '左右', NULL, '浙 (形声。从水,折声。本义水名。浙江,即钱塘江) 同本义 浙,江水东至会稽山阴为浙江。--《说文》。按,即禹贡三江之南江也,但江故道今不可考,世俗以钱塘江当之。非是', '小学', '1'),
    ('浦', 'pǔ', '10', '氵', '左右', NULL, '浦〈名〉 (形声。从水,甫声。本义水滨) 同本义 浦,濒也。--《说文》 率彼淮浦。--《诗·大雅·常武》 江浦之橘。--《吕氏春秋·本味》 望涔阳兮极浦；组词：浦淑(水边的美女)；浦帆(水滨的帆船)；浦溆(水边)；浦鸥(水边的鸥鸟)；浦滩(滩岸) 指池、塘、江河等水面 江河与支流', '小学', '1'),
    ('浩', 'hào', '10', '氵', '左右', NULL, '浩〈形〉 (形声。从水,告声。本义水势浩大) 同本义 浩,浇也。从水,告声。虞书曰洪水浩浩。；组词：浩波(大波,洪波)；浩汗(浩浩,浩然,浩瀚', '小学', '1'),
    ('浪', 'làng', '10', '氵', '左右', NULL, '浪〈名〉 波浪,水因风吹、石激而形成的涌动 风起浪涌。--《世说新语·雅量》 长风破浪会有时,直挂云帆济沧海。--李白《行路难》 温泉毖涌而自浪。--左思《魏都赋》；组词：风浪(水面上的风和波浪)；激浪(汹涌急剧的波浪)；浪波(浪头', '小学', '1'),
    ('浮', 'fú', '10', '氵', '左右', NULL, '浮〈动〉 (形声。从水,孚声。本义漂流,漂浮) 同本义 浮,氾也。--《说文》 载沉载浮。--《诗·小雅·菁菁者莪》 浮,漂也。浮游也。--《广雅》 乘桴浮于海；组词：油浮于水面；浮梗(随水漂浮的残梗)；浮蛆(酿酒未熟时,漂浮在酒浆上的泡沫)；浮没(漂流淹没)；浮月(浮在水面的月影)', '小学', '1'),
    ('浴', 'yù', '10', '氵', '左右', NULL, '浴 (形声。从水,谷声。本义洗澡) 同本义 浴,洒身也。--《说文》 共王之沐浴。--《周礼·宫人》 浴去身垢。--《论衡·讥月》 浴乎沂。--《论语·先进》 新浴者必振衣；组词：沐浴(洗澡；比喻受润泽)；浴渪(洗澡)；淋浴(喷水洗澡)；浴桶(洗澡用的大桶) 鸟飞忽上忽下 黑鸟浴,黑鸟者何也?乌也', '小学', '1'),
    ('海', 'hǎi', '10', '氵', '左右', NULL, '海〈名〉 (形声。从水,每声。本义大海,海洋) 百川会聚之处◇指邻接大陆而区域范围小于洋的咸水水体 海,天池也。以纳百川者。从水,每声。；组词：近海(靠近陆地的海域)；沿海(靠海的一带)；海岳(大和山岳)；海藏(大海', '小学', '1'),
    ('浸', 'jìn', '10', '氵', '左右', NULL, '浸 (形声。从水,籀文寝声。本义古水名。浸水) 同本义 浸,浸水也。出魏郡武安东北,入呼沱水。；组词：巨浸(大湖) 浸 泡在水里,被水渗入 冽彼下泉,浸彼苞稂', '小学', '1'),
    ('涂', 'tú', '10', '氵', '左右', NULL, '涂〈名〉 (形声。从水,余声。本义涂水) 同本义 古水名。即今云南省之牛栏江。发源于寻甸,北流至威宁折向西北,至鲁甸县注入金沙江 涂,水。出益州牧靡南山,西北入渑。；组词：涂次(路上；途中)；涂夫(路人)；涂巷(道路；街坊)；涂轨(本指车行之道', '小学', '1'),
    ('消', 'xiāo', '10', '氵', '左右', NULL, '消 (形声。从水,肖声。本义消除;消灭) 同本义 消,尽也。--《说文》 消息阴阳。--枚乘《七发》。注消,灭也。” 消雰埃于中宸。--张衡《西京赋》。注消,散也；组词：消索(灭尽,散亡)；消炎(消除炎症；消除炎热)；消弭(消灭停止) 消失,完全不存在 内君 消xiāo 1.溶解,散失~融', '小学', '1'),
    ('涉', 'shè', '10', '氵', '左右', NULL, '涉〈动〉 (会意。从水步。甲骨文字形。中间是水,两边两只脚,象涉水之形。本义趟水过河) 同本义 涉,徒行瀢水也。；组词：涉水登山(涉渡溪水并攀登山岭)；涉浅(徒步趟过浅水)；涉厉(涉水', '小学', '1'),
    ('涌', 'yǒng', '10', '氵', '左右', NULL, '涌 (形声。从水,甬声。本义水向上冒) 同本义 涌,滕也。--《说文》 涌,出也。--《广雅》 滥泉正出。正出,涌出也。--《尔雅·释水》 泉暴出者曰涌；组词：涌沸(喷涌出沸腾的水)；涌泉(水向上喷出的泉) 引申指云、雾、烟、气等上腾冒出 洪波涌起', '小学', '1'),
    ('涎', 'xián', '9', '氵', '左右', NULL, '涎 (形声。从水,延声。本义唾沫,口水) 同本义 涎,小儿唾也。--《三苍》 喷浪飞唌(涎)。--郭璞《江赋》 群犬垂涎。--柳宗元《三戒》；组词：口角流涎；垂涎三尺 粘液 咳则腰背相引而痛,甚则咳涎', '小学', '1'),
    ('涕', 'tì', '10', '氵', '左右', NULL, '涕〈名〉 (形声。从水,弟声。先秦时期,涕”指眼泪,后来出现了泪”,两字就同义并用了。本义眼泪)', '小学', '1'),
    ('涛', 'tāo', '10', '氵', '左右', NULL, '涛〈名〉 (形声。从水,寿声。本义大波) 同本义 涛,大波也。--《说文新附》 扬波涛于碣石。--《后汉书·班彪传上》 何必湘渊与涛濑?--《汉书·扬雄传上》 水泫泇而涌涛；组词：涛水(波涛汹涌的大水)；涛雪(波涛激汤,水花如雪)；涛雷(波涛汹涌,声大如雷)；涛波(大波,波涛) 像波涛一样的声音 阴', '小学', '1'),
    ('涝', 'lào', '10', '氵', '左右', NULL, '涝 (形声。从水,劳声。本义水名。在陕西省。源出秦岭,北流入渭水) 同本义 又名潦水。在陕西省户县、周至两县界上,源出秦岭,为关中八川之一 涝水北注甘水,而乱流入于渭。；组词：涝漉(浸润其中)；涝疏旱溉(指庄稼受涝应排水,受旱应灌溉)；沥涝(沥水淹了庄稼)；内涝(地势低洼,积水不能及时排水而造成', '小学', '1'),
    ('涡', 'wō', '10', '氵', '左右', NULL, '涡 guo 水名。今称涡河 濄水,首受淮阳扶沟浪汤洰东入淮。从水,过声。--《说文》 源出河南省通许县,流经安徽省西北部,于怀远县入淮,长382公里', '小学', '1'),
    ('涣', 'huàn', '10', '氵', '左右', NULL, '涣 (形声。从水,奂声。本义流散,离散) 同本义 涣,流散也。--《说文》 方涣涣兮。--《诗·郑风·溱洧》 涣者离也。--《易·序卦传》 则涣然离矣。--《汉书·刑法志》 涣兮；组词：涣然冰释(如冰之溶解消散', '小学', '1'),
    ('涤', 'dí', '10', '氵', '左右', NULL, '涤 (形声。从水,条声。本义洗) 同本义 涤,洒也。--《说文》 射人宿视涤。--《仪礼·大射仪》 水曰清涤。--《礼记·曲礼》 及执事,视涤濯。--《周礼·太宰》；组词：涤篆(洗印', '小学', '1'),
    ('润', 'rùn', '10', '氵', '左右', NULL, '润 (形声。从水, 闰声。本义雨水下流,滋润万物) 同本义 润,水曰润下。--《说文》 润,渍也。--《广雅》 润之以风雨。--《易·系辞》 雨润万物；组词：润一润喉咙；润下(雨水下以滋润万物)；润雨(受雨水滋润)；润改(滋润涵养)；润滋(滋润) 修饰,使有光彩 润,饰也', '小学', '1'),
    ('涧', 'jiàn', '10', '氵', '左右', NULL, '涧 (形声。从水,间声。本义夹在两山间的水沟) 同本义 涧,山夹水也。--《说文》 于涧之中。--《诗·召南·采蘩》 时鸣春涧中。--唐·王维《鸟鸣涧》 陕西大涧；组词：涧谷(溪涧山谷)；涧籁(山涧的水声) 涧谷,山谷 古代数词', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('涨', 'zhǎng', '10', '氵', '左右', NULL, '涨 (形声。从水,张声。本义水上升) 同本义 江涨柴门外,儿童报急流。--唐·杜甫《江涨》 冰入春风涨御沟,上林花气欲飞浮。--宋·王安石《祥云》 渭流涨腻,弃脂水也；组词：涨滩(由于河水上涨,泥沙堆积成可供耕植的陆地)；涨痕(涨水的痕迹)；涨溢(水流上涨泛滥) 增长；高出 涨少霾草树', '小学', '1'),
    ('涩', 'sè', '10', '氵', '左右', NULL, '涩 (形声。从水,歰声。声符为本字,象四只脚两两相抵,表示不滑,是会意字。本义不滑溜) 同本义 濇,不滑也。；组词：涩噎(因不滑润而梗噎)；涩道(刻有花纹的倾斜石砌)；涩巴巴(形容不滑润)；涩浪(古代宫墙基垒石凹入,作文纹状)；涩脉(脉', '小学', '1'),
    ('涮', 'shuàn', '11', '氵', '左右', NULL, '涮 (形声。从水,刷声。本义荡洗。用水摇动或放在水里摆动洗清) 同本义 涮,涮洗也。--《广韵》；组词：涮罐子；把衣服涮一涮；把瓶子涮干净 把生的肉片、鱼片之类放在开水锅里略煮一下就吃 欺骗或哄骗 涮shuàn 1.稍微洗洗', '小学', '1'),
    ('涯', 'yá', '11', '氵', '左右', NULL, '涯 (会意兼形声。从水,从厓,厓亦声。厓,山边。本义水边) 同本义 涯,水边也。--《说文新附》 各在天一涯。--《古诗十九首》 大海亦有洼,高山亦有岑。--孟郊《病客吟》；组词：涯歡(水边；岸)；涯灌(岸边丛木)；涯邻(崖畔) 岸,靠近大水体的陆地；特指靠近滨海的陆地 驾舟载男女,筑宫东海涯', '小学', '1'),
    ('液', 'yè', '11', '氵', '左右', NULL, '液 (形声。从水,夜声。本义汁,流质) 同本义 液,汁也。--《字林》 人有精气津液。--《素问·调经论》。注精之渗于空窍,留而不行者为液也。” 鼻出清液；组词：泪液(眼内泪腺分泌的无色透明液体)；胃液；津液；唾液；溶液 在动物或植物体内的非固态物质 液 冰冻融解；溶化 渔兮其若冰', '小学', '1'),
    ('涵', 'hán', '11', '氵', '左右', NULL, '浛〈动〉 同涵”。沉浸 浛天荡荡望沧沧,乘桴轻漾著日旁。--晋·王嘉《拾遗记》 浛,《方言》沉也”。', '小学', '1'),
    ('淀', 'diàn', '11', '氵', '左右', NULL, '淀 (形声。从水,定声。本义浅水湖泊)同本义 淀 (形声。从水,殿声。本义沉淀下来的泥滓) 同本义 淀谓之滓。；组词：淀塞(淤塞) 蓝靛', '小学', '1'),
    ('淆', 'xiáo', '11', '氵', '左右', NULL, '淆 (形声。从水,肴声。本义错杂;混杂) 同本义 淆,乱也,杂也。--《字汇》 又如淆舛(混杂错乱);淆紊(混杂纷乱);淆讹(搅乱,弄错) 彻底地搀和;搅合 澄之不清,淆之不浊；组词：淆舛(混杂错乱)；淆紊(混杂纷乱)；淆讹(搅乱,弄错) 彻底地搀和；搅合 澄之不清,淆之不浊,不可量也', '小学', '1'),
    ('淋', 'lín', '11', '氵', '左右', NULL, '淋〈动〉 (形声。从水,林声。本义浇) 同本义。让水或其他液体自上落下 淋,以水沃也。--《说文》 被淋洒其靡靡兮。--王褒《洞箫赋》；组词：用水淋头；日晒水淋；淋浴 浸渍 淋,渍也', '小学', '1'),
    ('淌', 'tǎng', '11', '氵', '左右', NULL, '淌〈动〉 (形声。从水,尚声。本义流下) 同本义 打大前日,河里就淌凌。--《老残游记》；组词：淌凌(流淌冰块)；他脸上淌着汗水；淌眼泪；淌眼抹泪(一边哭泣,一边擦眼泪)；伤口淌血 迅速流动 用同趟”,在浅水里走 他', '小学', '1'),
    ('淑', 'shū', '11', '氵', '左右', NULL, '淑 (形声。从水,叔声。本义水清澈) 同本义 淑,清湛也。--《说文》 其何能淑。--《诗·大雅·桑柔》。按,清也。；组词：淑淑(清净)；淑清(明朗；纯净)；淑然(清纯的样子) 淑”假借为俶”', '小学', '1'),
    ('淘', 'táo', '11', '氵', '左右', NULL, '淘〈动〉 (本作洮”。形声。从水匋声。本义用水冲洗,去除杂质) 同本义 浪淘尽。--宋·苏轼《念奴娇·赤壁怀古》；组词：淘炊(淘米烧饭)；淘盆(淘米器)；淘洗(洗濯)；淘濯(淘洗)；淘干净；淘沙(冲刷沙砾；淘沙取金)；淘漉(冲洗滤过)；淘荡', '小学', '1'),
    ('淡', 'dàn', '11', '氵', '左右', NULL, '淡 (形声。从水,炎声。本义味淡;味道不浓,不咸) 同本义 淡,薄味也。--《说文》 淡而不厌。--《礼记·中庸》 君子淡以成。--《礼记·表记》。注无酸酢少味也。” 淡也者；组词：淡酒；淡味；淡句(平淡乏味的诗句)；淡而不厌(指诗文恬淡而不乏味)；淡菜 稀薄 天高云淡,望断南飞雁', '小学', '1'),
    ('淤', 'yū', '11', '氵', '左右', NULL, '淤〈名〉 (形声。从水,於声。本义水中沉淀的泥沙) 同本义 春夏干燥, 少水时也, 故使河流迟, 贮淤而稍浅。；组词：淤滩(淤泥形成的滩地)；引淤肥田 泥沙冲积成的地带 楚人种麦满河淤,仰看浮槎栖古木', '小学', '1'),
    ('淫', 'yín', '11', '氵', '左右', NULL, '淫 (形声。从水,侌声。本义浸淫;浸渍) 同本义 淫,侵淫随理也。--《说文》。徐锴注随其脉理而浸渍也。” 善防者水淫之。--《考工记·匠人》 女娲积芦苇以止淫水；组词：淫溢(逐渐浸染) 特指通奸；奸淫 男女不淫', '小学', '1'),
    ('淮', 'huái', '11', '氵', '左右', NULL, '淮〈名〉 (形声。从水,隹声。本义水名。也称淮河) 同本义 淮,淮水也。--《说文》。朱骏声曰出今河南南阳府桐柏县桐柏山,经安微至江苏清河县合于河,经安东县至云梯关入海；组词：淮洪(淮河与洪河,一说淮河中的洪水', '小学', '1'),
    ('深', 'shēn', '11', '氵', '左右', NULL, '深 (形声。从水,深声。本是河流名。深浅的深,本作深”。本义水名) 古水名 深,深水。出桂阳 南平,西入营道。', '小学', '1'),
    ('淳', 'chún', '11', '氵', '左右', NULL, '淳 (形声。本义浇灌) 敦厚;质朴;朴实 浇天下之淳,析天下之朴。--《淮南子·齐俗》 又如淳良(朴实善良);淳古(古代朴质的风尚精神);淳和(淳朴而温和);淳风(淳朴的风俗)；组词：淳良(朴实善良)；淳古(古代朴质的风尚精神)；淳和(淳朴而温和)；淳风(淳朴的风俗)；淳粹(朴实完善) 味道浓厚的', '小学', '1'),
    ('混', 'hùn', '11', '氵', '左右', NULL, '混 (形声。从水,昆声。本义水势盛大) 同本义 混,丰流也。--《说文》 汩乎混流。--司马相如《子虚赋》 或混沦乎泥沙。--郭璞《江赋》；组词：混沦(水旋转的样子)；混澒(水流漫涌回旋的样子)；混瀥(水大无边的样子) 浑浊,水多泥多杂质而不清澈 时混混兮浇饡', '小学', '1'),
    ('淹', 'yān', '11', '氵', '左右', NULL, '淹 (形声。从水,奄声。本义古水名,即今金沙江的一段) 同本义。在四川省南部。即今金沙江自发源地至四川省攀枝花市的一段 淹水,一曰复水也,出今四川宁远府徼外,合金沙江入江。；组词：淹荠燎菜(形容肮脏、破旧)；淹渍(浸泡,淹浸) 淹没；沉没 宅中水淹', '小学', '1'),
    ('添', 'tiān', '11', '氵', '左右', NULL, '添〈动〉 (形声。从水,忝声。本义增加,增补) 同本义 如添嘴送舌(添言加语;搬弄是非); 如她最近添了一个女孩儿 添tiān增加增~。锦上~花。~砖加瓦。', '小学', '1'),
    ('清', 'qīng', '11', '氵', '左右', NULL, '清〈形〉 (形声。从水,青声。青”,碧绿透彻,也有表意作用。本义水清) 同本义。与浊”相对 沧浪之水清兮。；组词：清直(河水清澈顺流貌)；清波(清澈的水流)；清泚(清清的河水)；清涟(清澈的细水波)；清活活(水清澈而流动貌)；清照(清', '小学', '1'),
    ('渊', 'yuān', '11', '氵', NULL, NULL, '渊 (会意。《说文》古文字形,外边大框象水潭,里面是打漩的水。本义打漩涡的水) 同本义 渊,回水也。；组词：渊环(回旋环绕)；渊洑(水流汹涌起伏的样子) 深潭 如临深渊', '小学', '1'),
    ('渐', 'jiàn', '11', '氵', '左右', NULL, '渐 流入;入 东渐于海。--《书·禹贡》 又如渐渐(流淌的样子) 淹没,浸泡 其渐之滫,君子不近,庶人不服。--《荀子·劝学》 淇水汤汤,渐车帏裳。--《诗·卫风·氓》 渐,渍也；组词：渐渐(流淌的样子) 淹没,浸泡 其渐之滫,君子不近,庶人不服', '小学', '1'),
    ('渔', 'yú', '11', '氵', '左右', NULL, '渔 (会意。从水,从鱼。小篆从二鱼。本义捕鱼) 同本义 渔,捕鱼也。--《说文》 命渔师伐蛟,命渔师始渔。--《礼记·月令》 獭祭鱼然后渔。--《诗·鲡传》 渔者走渊；组词：渔樵(打鱼砍柴)；渔采(捕捞采集)；渔事(捕渔业)；渔弋(捕鱼猎禽)；渔泽(可供垂钓的水泽)；渔矶(可供垂钓的水边岩石)', '小学', '1'),
    ('渗', 'shèn', '11', '氵', '左右', NULL, '渗 (形声。从水,参声。本义水往下渗透) 同本义 渗,下漉也。--《说文》 滋液渗漉。--《汉书·司马相如传》。注谓润泽下究。” 泽渗离而下降。--《汉书·扬雄传》 百年老屋；组词：渗沥(滴漏)；渗泄(小便)；渗淫(小水', '小学', '1'),
    ('渠', 'qú', '11', '氵', '上下', NULL, '渠〈名〉 (形声。从水,榘省声。本义水停积处,也指人工开凿的水道) 同本义 渠,水所居。--《说文》 渠,坑也。--《广雅·释水》 门闾沟渠必步。--《礼记·曲礼》。疏沟也；组词：干渠(从水源引水的渠道)；支渠；毛渠；渠堑(沟渠)；灌溉渠；渠田(水田)；渠长(古官名', '小学', '1'),
    ('渡', 'dù', '12', '氵', '左右', NULL, '渡〈动〉 (形声。从水,度声。本义渡过,过水) 同本义 渡,济也。--《说文》。朱骏声曰子史皆以度为之。” 度江河,亡维楫。--《汉书·贾谊传》。按,后世分用,渡河不写作度；组词：渡仔(渡子', '小学', '1'),
    ('渣', 'zhā', '12', '氵', '左右', NULL, '渣 (形声。从水,查声。本义渣滓,物质经提炼或使用后的残余部分) 同本义 今人谓糟滓为苴作,侧加反,俗字作渣,乃沮之形变也。--章炳麟《新方言》；组词：渣柜(方言', '小学', '1'),
    ('渤', 'bó', '12', '氵', '左右', NULL, '渤 水涌的样子 鲸归穴兮渤溢,鳌载山兮低昂。--元稹《有酒》 又如渤溢(水涌起的样子);渤荡(涨潮) 渤 渤海 黄海相通。如渤海桑田(大海变成桑田,桑田变成大海；组词：渤溢(水涌起的样子)；渤荡(涨潮) 渤 渤海 黄海相通', '小学', '1'),
    ('温', 'wēn', '12', '氵', '左右', NULL, '温 (形声。从水,昷声。本义水名) 古水名 即今贵州省遵义市东的洪江 即今南盘江上游 温江,岷江支流,在今四川省温江县 温度 人有寒温之病,非操行之所及也。', '小学', '1'),
    ('港', 'gǎng', '12', '氵', '左右', NULL, '港〈名〉 (形声。从水,巷声。本义江河的分流) 同本义 道于杨墨老庄佛之学,而欲之圣人之道,犹航断港绝潢,以望至于海也。--唐·韩愈《送王秀才序》；组词：港鱼(港养的鱼产)；港养(养殖海产生物的一种方式)；港渎(河渠) 港湾；码头；港口 香港的简称 港gǎng 1.与河、沟', '小学', '1'),
    ('渴', 'kě', '12', '氵', '左右', NULL, '渴〈形〉 (形声。从水,曷声。本义水干 ) 口渴 渴,饥渴。--《广韵》 苟无饥渴。--《诗·王风·言子于役》 载饥载渴。--《诗·小雅·采薇》 日高人渴漫思茶；组词：好渴；当你渴的时候到罐子那里去喝水 比喻迫切 饥渴而顿踣', '小学', '1'),
    ('游', 'yóu', '12', '氵', '左右', NULL, '游 (形声) 同本义 游,旌旗之流也。--《说文》 为下国缀旒。--《诗·长发》 韖厉游缨,昭其数也。--《左传·桓公十二年》 江河的一段 溯游从之,宛在水中央；组词：上游；下游；中游 鸟媒,猎人驯养用以招引野鸟的家鸟 恐吾游之晏起,虑原禽之罕至', '小学', '1'),
    ('渺', 'miǎo', '12', '氵', '左右', NULL, '渺 (形声。从水,眇声。本义水面辽阔) 同本义 四际渺弥。--宋·陆游《过小孤山大孤山》；组词：浩渺(形容水面辽阔)；渺冥(渺远)；渺弥(水流旷远的样子)；渺漭(水势辽阔的样子)；渺绵(水流不断的样子) 遥远；邈远', '小学', '1'),
    ('湃', 'pai', '12', '氵', '左右', NULL, '湃〈动〉 (形声。从水,拜声。联绵词澎湃”为波涛冲击声。叠音词湃湃”为水波相击声) 冰镇或用冷水浸;漂 湃pài 湃bá 1.用冰或冷水镇物使冷。', '小学', '1'),
    ('湖', 'hú', '12', '氵', '左右', NULL, '湖〈名〉 (形声。从水,胡声。本义陆地上聚积的大水体) 湖泊,积水的大泊 湖,大陂也。--《说文》 扬州浸有五湖。浸,川泽所仰以灌溉也。--《周礼·职方》。按古言鸿隙大陂；组词：湖池(湖泊池沼)；湖胶(湖水结冰)；湖埭(湖的堤坝)；湖海(湖与海的合称；泛指天下之地) 古州名 古县名 湖hú 1.陆', '小学', '1'),
    ('湘', 'xiāng', '12', '氵', '左右', NULL, NULL, '小学', '1'),
    ('湾', 'wān', '12', '氵', '左右', NULL, '湾 (形声。从水,弯声。本义河水弯曲处) 同本义 湾,水曲也。--《广韵》 潮来汹涌,水浸湾环。--《西游记》；组词：河湾；湾矶(弯曲水流中的石头)；湾湾(水边湾曲处)；湾头(水湾)；湾埼(弯曲的水岸)；湾澳(弯曲的水边)；湾回(河水弯曲', '小学', '1'),
    ('湿', 'shī', '12', '氵', '左右', NULL, '湿 (会意兼指事。从水,顯声。本义潮湿) 同本义 溼,幽溼也。从水,一所以覆也。覆土而有水,故溼也。', '小学', '1'),
    ('溃', 'kuì', '12', '氵', '左右', NULL, '溃 (形声。从水,贵声。本义水冲破堤岸) 同本义 溃,决也。--《说文系传》 溃,漏也。--《说文》 溃,旁决也。--《苍颉篇》 不遵其道曰洚,亦曰溃；组词：溃围(突围)；溃冒(冲决泛滥)；溃溢(堤防崩溃,洪水 溃kuì 1.水冲破堤坝~决', '小学', '1'),
    ('溅', 'jiàn', '12', '氵', '左右', NULL, '溅溅 溪谷溅溅 黄河流水鸣溅溅 溅 (从水,贱声。本义用污水挥洒) 同本义 溅,污洒也。--《说文》。段玉裁注谓用污水挥洒也。” 液体受到冲激向四外飞射 颈血溅大王；组词：溅血(飞溅的鲜血)；溅沫(飞溅的水花)；溅泪(飞洒眼泪)；溅了一脸水；钢花四溅 流 溅落 重物自高处落入水中 指人造卫星', '小学', '1'),
    ('溉', 'gài', '12', '氵', '左右', NULL, '溉〈动〉 (形声。从水,既声。本义灌注) 同本义 溉,灌也。--《广韵》 溉,一曰灌注也。--《说文》 此渠皆可行舟,有余则用溉。--《汉书·沟洫志》 西门豹引漳水溉邺；组词：溉田(灌溉田亩)；溉汲(汲水浇田)；溉浸；溉灌(灌溉)；溉沃万顷 洗,洗涤 挹彼注兹,可以濯溉', '小学', '1'),
    ('源', 'yuán', '13', '氵', '左右', NULL, '源〈名〉 (形声。从水,原声。原”有表义作用,指水源。本义水源,源泉。字本作原”) 同本义 或源也,或委也。；组词：源委(指水的发源和归宿', '小学', '1'),
    ('溜', 'liū', '13', '氵', '左右', NULL, '溜〈动〉 滑动 偷偷地走 瞟,偷偷地看 说着,却把眼溜着金桂一笑。--《红楼梦》 偷偷地拿 差人各溜过几件细软东西。--《醒世恒言》 略略热一下 略微煮一下', '小学', '1'),
    ('溢', 'yì', '13', '氵', '左右', NULL, '溢 (形声。从水,益声。本作益”。象水从器皿中漫出。本义水漫出来) 同本义 溢,器满也。--《说文》 溢,盈也。--《尔雅》 溢,满也。--《广雅》。按,过满为溢。 满而不溢；组词：溢决(水满破堤)；溢满(平满) 水泛滥成灾,淹没 虽有凶旱水溢,民无菜色', '小学', '1'),
    ('溪', 'xī', '13', '氵', '左右', NULL, '溪 (溪本作豨) 山间不与外界相通的小河沟 嵠,山渎无所通者。--《说文》 是故溪狭者速涸。--《墨子·亲士》 子越自石溪。--《左传·文公十六年》。注入庸道。” 振溪通谷；组词：溪步(水涯与渡船处)；溪径(小路', '小学', '1'),
    ('溯', 'sù', '13', '氵', '左右', NULL, '溯 (形声。从水,朔声。本义端直地逆流而上) 同本义 逆流而上曰溯洄。--《尔雅》 溯洄从之,道阻且长。--《诗·秦风·蒹葭》 至于夏水襄陵,沿溯阻绝；组词：溯涉(逆流跋涉)；溯流(逆着水流方向)；溯洄(逆流而上)；溯游(顺着河流向下) 追朔 探求 由此上溯到一千八百四十年,从', '小学', '1'),
    ('溶', 'róng', '13', '氵', '左右', NULL, '溶 (形声。从水,容声。本义水盛大的样子) 同本义 溶,水盛也。--《说文》 体溶溶而东回。--《楚辞·逢纷》。注波貌。”；组词：溶溢(水盛大的样子)；溶溶荡荡(水波浮动的样子)；溶溶澹澹(水波盛大起伏的样子)；溶漾(水波荡漾的样子)；溶瀛(水势浩大', '小学', '1'),
    ('溺', 'nì', '13', '氵', '左右', NULL, '溺〈动〉ni 没入水中 嫂溺,则援之以手乎?--《孟子·离娄上》 溺死者。--《吕氏春秋·察今》 河中溺死。--《汉书·李广苏建传》 人马烧溺死者甚众。--《资治通鉴》；组词：溺女(将刚生下的女婴投入水中淹死)；沉溺(陷入不良的境地)；溺没(沉没)；溺溺(沉没)；溺毙(淹死) 沉湎,无节制 困于', '小学', '1'),
    ('滋', 'zī', '12', '氵', '左右', NULL, '滋 滋水 滋水出牛饮山白陉谷,东入呼沱。从水,兹声。--《说文》 一名兹水,今名磁河。源出河北省阜平县西部南坨山东,今为潴龙河支流 浆,液汁 墨井盐池,玄滋素液', '小学', '1'),
    ('滑', 'huá', '12', '氵', '左右', NULL, '滑 (形声。从水,骨声。本义滑溜,光滑) 同本义 间关莺语花底滑。--唐·白居易《琵琶行(并序)》 道中迷雾冰滑。--清·姚鼐《登泰山记》；组词：滑擦(滑擦擦', '小学', '1'),
    ('滓', 'zǐ', '13', '氵', '左右', NULL, '滓 (形声。从水,宰声。本义液体里下沉的杂质) 同本义 滓,淀也。--《说文》。泥之黑者为滓,字亦作淄。 化白于泥淄。--《太玄·更》。注黑也。” 脉不粘肤,食不留滓；组词：滓方(收集茶叶渣的器具)；滓脚(渣子,渣末) 用同汁” 行到灶前毛器具,目滓流落拭卖干', '小学', '1'),
    ('滔', 'tāo', '13', '氵', '左右', NULL, '滔〈形〉 (形声。从水,舀声。本义水势盛大的样子) 同本义 滔,水漫漫大貌。--《说文》 滔,漫也。--《广雅》 象恭滔天。--《书·尧典》 浩浩滔天。 汶水滔滔；组词：滔涸(水漫溢与干涸)；滔漭(水弥漫浩广的样子)；滔滔滚滚,滔漫(大水漫溢) 傲慢,专横霸道 士不滥, 官不滔', '小学', '1'),
    ('滚', 'gǔn', '13', '氵', '左右', NULL, '滚 (形声。从水,衮声。本义大水奔流貌) 同本义 无边落叶萧萧下,不尽长江滚滚来。--唐·杜甫《登高》；组词：滚滚(水涌流的样子) 连续不断,急速翻腾的样子 尘滚滚东向驰去◇遂不复至', '小学', '1'),
    ('滞', 'zhì', '12', '氵', '左右', NULL, '滞 (形声。从水,带声。本义水流不畅) 同本义 滞,凝也。--《说文》 凡珍异之有滞者。--《周礼·廛人》 淹回水而凝滞。--《楚辞·涉江》 流而不滞；组词：滞狱(指因积压或拖延未予审决的案件)；滞讼(积压的讼案)；滞积(积压)；滞货(积压的货物) 停止；阻塞；静止 是故能天运', '小学', '1'),
    ('满', 'mǎn', '13', '氵', '左右', NULL, '满 (形声。本义填满,布满) 同本义 满,盈溢也。--《说文》 无几何而往,则户外之屦满矣。--《庄子·列御寇》 荆有云梦,犀兕麋鹿满之。--《墨子·公输》 奸邪满侧；组词：满口胡柴(满口胡说)；满坑满谷(形容积聚得特多)；满面生花(满面 满(漨)mǎn 1.全~分', '小学', '1'),
    ('滤', 'lǜ', '13', '氵', '左右', NULL, '滤(瀡)lǜ使液体、气体通过布、纸、沙等,除去其中的杂质、毒气等过~。', '小学', '1'),
    ('滥', 'làn', '13', '氵', '左右', NULL, '滥 (形声。从水,监声。本义浮起,浮现) 同本义 滥,泛也。--《说文》 江出于岷山,其始出也,其源可以滥觞。--《荀子·子道》 滥泉正出。--《尔雅·释水》 滥水之潘为渊；组词：泛滥(江河湖泊的水溢出)；滥泉(从地下向上涌出的泉水)；滥汜(泛滥,浮沉) 浸渍,泡在水里 滥车之水', '小学', '1'),
    ('滨', 'bīn', '13', '氵', '左右', NULL, '滨 (形声。从水,宾声。本义水边) 湖、河、海的水边陆地 南涧之滨。--《诗·召南·采蘯》 率土之滨。--《诗·小雅·北山》。传滨,涯也。” 海滨广斥；组词：湘江之滨；溪滨；滨涯(水边)；湖滨；海滨 古州名 姓 滨 通濒”', '小学', '1'),
    ('滩', 'tān', '13', '氵', '左右', NULL, '滩〈名〉 (形声。从水,难声。本义河道中水浅流急多沙石的地方) 同本义 却放轻舟下急滩。--《唐崔道融溪夜诗》 滩,水滩。--《广韵·平声寒韵》 按,滩濑”的滩”是后起字；组词：滩燀(水中沙滩)；滩碛(浅水下的沙石滩)；滩声,滩响(水激滩石发出的声音) 滩头', '小学', '1'),
    ('滴', 'dī', '14', '氵', '左右', NULL, '滴 (形声。从水,啇声。本义液体一点一点落下来。成语滴水成冰) 同本义 滴,水注也。--《说文》 若何滴滴。--《列子·力命》 临岐别数子,握手泪再滴；组词：滴沥(水下滴)；滴溜(涓滴的水)；滴水(滴下来的水)；滴溜当啷(不断下滴的样子) 滴 水点；点点下落的液体 滴 形容雨水', '小学', '1'),
    ('漂', 'piāo', '14', '氵', '左右', NULL, '漂〈动〉 (形声。从水,票声。本义浮,浮流) 同本义 漂,浮也。--《说文》 血流漂杵。--《伪书武成》 漂通川之碄碄。--张衡《思玄赋》 流血漂橹。--汉·贾谊《过秦论》；组词：漂泼(漂泊)；漂泛(浮舟而行,随波飘流)；漂拔(漂肝起)；漂海(漂浮于海上)；漂橹(漂浮船桨)；漂激(漂流激动)；漂杵(', '小学', '1'),
    ('漆', 'qī', '14', '氵', '左右', NULL, '漆〈名〉 (形声。从水,梤声。本义漆水) 同本义。古水名 渭水支流,今名漆水河。发源于陕西麟游县西,东南流至武功县西,注入渭水 在陕西省邠县西,流注泾水 石川河上源之一', '小学', '1'),
    ('漏', 'lòu', '14', '氵', '左右', NULL, '漏〈名〉 (形声。从水,屚声。本义漏壶的简称。古代滴水计时的仪器) 同本义 漏尽钟鸣,箭驰风追。；组词：漏下(漏刻的水面已经下落)；漏永更长(比喻深夜)；漏尽钟鸣(黎明时分)；漏夜(深夜)；漏板(古代报更用的铜板)；漏刻(古', '小学', '1'),
    ('漓', 'lí', '13', '氵', '左右', NULL, '漓 浅薄;浇薄 漓 漓江 漓( 2.灕)lí 1. 3."。 2.漓江,在广西壮族自治区。', '小学', '1'),
    ('演', 'yǎn', '14', '氵', '左右', NULL, '演 (形声。从水,寅声。本义水长流) 同本义 演,长流也。--《说文》 南国风光当世少,西陵演浪过江难。--李白《代封人寄翁参枢先輩》 子未闻杨都之巨伟也,左沧海,右岷山；组词：演延(绵延,广远)；演迤(绵延不绝貌) 演 yǎn 1水长流', '小学', '1'),
    ('漠', 'mò', '13', '氵', '左右', NULL, '漠 (形声。从水,莫声。本义沙漠) 同本义 漠,北方流沙也。--《说文》 逾陇堆兮渡漠。--《楚辞·疾世》 大漠孤烟直,长河落日圆。--唐·王维《使至塞上》；组词：漠北,漠南(蒙古高原大沙漠以南(北)的地区)；漠野(我国北方沙漠地区) 漠 淡泊,恬淡,即不追求名利 澹而静乎!漠而清乎', '小学', '1'),
    ('漩', 'xuán', '14', '氵', '左右', NULL, '漩 (形声。从水,旋声。本义回旋的水流) 同本义 水理漩洑,鹏风翱翔。--唐·司空图《诗品》；组词：漩纹(回环的纹路) 漩 水流旋转 龙归窟穴深潭漩,蜃作波涛古岸鐀', '小学', '1'),
    ('漫', 'màn', '14', '氵', '左右', NULL, '漫 (形声。从水,曼声。本义水过满向外流) 同本义 诸山崩,鸿水溢。--《三国志·吴主传》 譬如写水著地,正自纵横流漫,略无正方圆者。--《世说新语·文学》 渐见江势阔；组词：漫溢(水满向外流)；漫口(堤岸被水冲溃)；水漫金山；漫溃(水涨破堤而出)；漫泄(水满外流)；漫流(水势很大的河流)；漫然', '小学', '1'),
    ('漱', 'shù', '14', '氵', '左右', NULL, '漱 形声。同本义 漱,眜口也。 咸盥漱。--《礼记·内则》 凡内外,鸡初鸣,咸盥漱。--《礼·内则》；组词：漱盂(盛漱口水的器皿)；漱流(以流水漱口', '小学', '1'),
    ('漾', 'yàng', '14', '氵', '左右', NULL, '漾 古水名。漾水 汉水上流,源出陕西省宁羌县北潘冢山 即今嘉陵江上源的西汉水 漾,漾水。出陇西相氐道,东至武都为汉。；组词：漾驰(水流平缓) 因充满或盛满而溢出 泛,荡 飘动；晃动 抛掷；丢弃 把一大块石头漾在奉符县河里', '小学', '1'),
    ('潘', 'pān', '15', '氵', '左右', NULL, '潘〈名〉 淘米水 古水名 在河南省荥阳县境 在浙江省绍兴市境,后堙。或以为是今运河经绍兴的一段河道 约在山东省淄博市一带,或以为是淄水 山名', '小学', '1'),
    ('潜', 'qián', '15', '氵', '左右', NULL, '潜 (形声。本义没入水中,而且在水下活动) 同本义 潜,涉水也。--《说文》。朱骏声按没水以涉曰潜。 潜龙。--《易·乾龙》 潜虽伏矣。--《诗·小雅·正月》 游鱼潜绿水；组词：潜水 隐藏 潜服贼器不入宫', '小学', '1'),
    ('潦', 'liáo', '15', '氵', '左右', NULL, '潦〈名〉lao 水名。即涝水” 潦 〈形〉lao 雨水盛大的样子 水潦降,不献鱼鳖。--《礼记》；组词：潦浸(指大雨泛滥成灾)；潦潦(雨大水流的样子)；潦雨(大雨)；潦水(雨后的积水) 潦 〈名〉 雨后积水 潦水尽而寒潭清', '小学', '1'),
    ('潭', 'tán', '15', '氵', '左右', NULL, '潭〈名〉 (形声。从水,覃声。本义水名) 同本义 潭,水。出武陵镡成玉山,东入郁林。--《说文》 深水池 潭,渊也。--广雅·释水》 泝江潭兮。--《楚辞·九章·抽思》。注潭；组词：潭心(潭底,渊底)；潭石(深谷里的岩石)；潭影(潭中的光影)；潭府(深渊)；潭渊(深渊) 待我先 潭tán 1.深水坑或', '小学', '1'),
    ('潮', 'cháo', '15', '氵', '左右', NULL, '潮 (形声。从水,朝声。本义海水的涨落) 同本义 潮,水朝宗于海。--《说文》 牛女为江潮。--《春秋·元命苞》 水朝夕而至曰潮。--《初学记卷六水》 有江盗百艘,张帜乘潮；组词：大潮,小潮；低潮；退潮；落潮 比喻大规模的社会变动或运动发展的起伏形势 气温变化或持续一段时间的炎热或寒冷的天气 微湿,', '小学', '1'),
    ('澄', 'chéng', '15', '氵', '左右', NULL, '澄 cheng (形声。从水,登声。本义水静而清) 同本义 澄,水清定也。--《集韵》 澄,水静而清也。--《增韵》 水色澄碧。--黄肇敏《黄山纪游》；组词：澄水(清澈而平静无波的水)；澄江(清澄明澈的江水)；澄泉(清泉)；澄酒(清酒,淡酒) 清澈,透明 心澄体静', '小学', '1'),
    ('澈', 'chè', '15', '氵', '左右', NULL, NULL, '小学', '1'),
    ('澎', 'péng', '15', '氵', '左右', NULL, '澎〈动〉 (形声。从水,彭声。本义波涛发出冲击声) 同本义 迸发 一个女人家有甚么胆气,小的到他门上澎出几句闲话,他怕族人知道,他自然给小的百十两银子,买告小的。；组词：澎澎(象声词)；澎澎渤渤(蓬勃,旺盛) 满而溢出 溅 澎 〈名〉 古县名 澎,县名,在东海', '小学', '1'),
    ('澜', 'lán', '15', '氵', '左右', NULL, '澜 (形声。从水,阑声。本义大波浪) 同本义 澜,大波也。--《说文》 大波为澜,小波为沦。--《尔雅》 天下安澜。--《四子讲德论》 观水有术,必观其澜；组词：狂澜；巨澜；澜倒波随(犹言随波逐流', '小学', '1'),
    ('澡', 'zǎo', '16', '氵', '左右', NULL, '澡 (形声) 同本义 澡,洒手也。--《说文》 澡葛綕带。--《仪礼·士虞礼》 日三澡漱,然后饮食。--《魏书》 后泛指洗涤 常以月旦祓龟,洗以清水澡之。--《史记·龟策传》；组词：澡沐(沐浴)；澡雪(洗清)；澡瓶(寺庙里供僧人洗涤用的水瓶)；澡刷(洗刷)；澡涤(洗刷', '小学', '1'),
    ('澳', 'ào', '15', '氵', '左右', NULL, '澳〈名〉 (形声。从水,奥声。本义水边地) 港湾,海边弯曲可以停船的地方 无港澳以容舟楫。；组词：澳闸(拦河水闸) 澳水 澳门的简称 澳大利亚的简称 澳ào海边弯曲且可停泊船只的地方', '小学', '1'),
    ('激', 'jī', '16', '氵', '左右', NULL, '激 (形声。本义水势受阻遏后腾涌或飞溅) 同本义 激,水碍袤疾波也。--《说文》 激而行之,可使在山。--《孟子》 激水之疾,至于漂石者,势也。--《孙子·势》 泉水激石；组词：激激(急流声；水势湍急的样子)；激浪(怒涛)；激射(喷射,冲击) 鼓动人心,使有所感发 激而发之', '小学', '1'),
    ('濒', 'bīn', '16', '氵', '左右', NULL, '濒 (形声。从水,频声。本义水边) 同本义 是故昔者舜耕于历山,陶于河濒。--《墨子·尚贤》 行举濒河之郡。--《汉书·成帝纪》。师古曰滨,水涯也。” 濒海之观毕至；组词：濒危；濒近；濒于(亦作濒於”', '小学', '1'),
    ('瀑', 'bào', '18', '氵', '左右', NULL, '瀑 bao (形声。从火,虹声。本义爆烈) 急雨,暴风雨 瀑,疾雨也。《诗》曰终风且瀑”。', '小学', '1'),
    ('灌', 'guàn', '20', '氵', '左右', NULL, '灌〈名〉 (形声。从水,雚声。本义灌水) 同本义 灌,灌水也。出庐江雩娄北入淮。--《说文》 灌水,源出河南省商城县南,东北经固始县西南曰曲河,北合史河流入淮水 丛生的树木 灌木；组词：灌木；灌莽；灌丛 灌 浇；灌溉 灌,浇也,渍也', '小学', '1'),
    ('火', 'huǒ', '4', '火', NULL, NULL, '火 (象形。甲骨文字形象火焰『字部首之一。本义物体燃烧所发的光、焰和热) 同本义 火,南方之行也。炎而上,象形。；组词：火链( 火huǒ 1.物体燃烧时所发的光和焰烈~熊熊', '小学', '1'),
    ('灭', 'miè', '5', '火', '上下', NULL, '灭 (形声。从水,威声。简化字灭”为会意,从一”从火”,一”表示覆压火上。本义消灭;灭亡)；组词：灭于绛；一朝而灭；灭(滅)miè 1.熄,熄火~ 火', '小学', '1'),
    ('灯', 'dēng', '6', '火', '左右', NULL, '灯 (形声。从火,登声。本写作 镫”。本义置烛用以照明的器具。镫”在古代还作盛熟食的器具”解。隶变以后,作照明器具用的写作燈”,而镫”多作马鞍两旁的铁脚 踏讲)；组词：油灯；电灯；日光灯；信号灯；探照灯；灯法(使用灯烛所作的幻术) 彩灯', '小学', '1'),
    ('灰', 'huī', '6', '火', NULL, NULL, '灰 (会意。从手,从火。意思是火已熄灭,可以用手去拿。本义火灰) 同本义 灰,死火余烬也。；组词：灰灭(灰没', '小学', '1'),
    ('灵', 'líng', '7', '火', '上下', NULL, '灵 (形声。从巫,靈声。本义巫) 古时楚人称跳舞降神的巫为灵 灵,灵巫也。以玉事神。--《说文》 命灵氛为余占之。--《离骚》 灵连踡兮既留。--《楚辞·云中君》 灵偃蹇兮姣胶；组词：灵子(指巫', '小学', '1'),
    ('灶', 'zào', '7', '火', '左右', NULL, '灶 (会意。从火从土。繁体从穴,鼀声。本义用砖石等砌成,供烹煮食物、烧水的设备) 同本义 灶,炊穴也。；组词：灶床脚(紧靠炉灶旁边的地面)；锅灶；行军灶；灶妄(掌炉煮饭的婢女)；灶下养(厨役', '小学', '1'),
    ('灸', 'jiǔ', '7', '火', '上下', NULL, '灸 (形声。从火,久声。本义用艾火烧灼。中医的一种疗法) 同本义 灸,灼也。--《说文》 所谓不病而灸,无忧而自默。--向秀《难养生论》；组词：灸刺(艾灸和针刺)；灸客(接受灸疗的病人)；灸眉(用艾炷烧灼眉头以治狂疾)；灸师(以灸术治病的医师) 烧灼 拄,支撑 灸', '小学', '1'),
    ('灼', 'zhuó', '7', '火', '左右', NULL, '灼 (形声。从火,勺声。本义烧,灸) 同本义 灼,炙也。--《说文》 皆忧心如火灼烂之矣。--《诗·节南山》笺 征丝灼之。--《史记·龟策传》 不可灼也；组词：灼艾(燃烧艾绒熏灸人体一定的穴位)；灼臂落发(烧炙手臂剃去头发', '小学', '1'),
    ('灾', 'zāi', '7', '火', '上下', NULL, '灾 (会意。甲骨文字形,象火焚屋的形状。小篆从川,表水;从火。水火都是灾祸之源。本义火灾)；组词：灾火(火灾)；灾燀(火灾) 灾害,祸患 大烖', '小学', '1'),
    ('灿', 'càn', '7', '火', '左右', NULL, '灿 (形声。从火,粲声。本义灿烂,光彩鲜明耀眼) 同本义 灿若图绣。--《徐霞客游记·游黄山记》；组词：灿然(明亮)；灿灿(闪闪发光的样子) 鲜艳；鲜明 明白,清楚 灿 cǎn灿烂】鲜明耀眼星光~', '小学', '1'),
    ('炉', 'lú', '8', '火', '左右', NULL, '炉 (形声。从火,眗声。本义贮火的器具,作冶炼、烹饪、取暖等用) 火炉 鑪,金鑪也。--《说文》 炉,火所居也。--《声类》 邾庄公废于鑪炭。--《左传》 鑪橐埵坊；组词：炉鸭(放在火炉上烧烤出来的鸭子)；炉饼(烧饼)；炉的(蒸的)；炉铫(煎药或烧水用的器具)；炉火(炉中之火)；炉灰(燃料在', '小学', '1'),
    ('炊', 'chuī', '8', '火', '左右', NULL, '炊 (形声。从火,吹省声。本义烧火做饭) 同本义 析骸而炊之。--《公羊传》 一人炊之。--《汉书·枚乘传》 先炊之属。--《史记·封禅书》。注先炊,古炊母之神也。” 急应河阳役；组词：炊米(煮饭)；炊人(厨子)；炊妇(煮饭的妇人)；吹家子(古代军中掌管炊事的人)；吹沙成饭(比喻徒劳无功) 烧火 炊 ch', '小学', '1'),
    ('炎', 'yán', '8', '火', '上下', NULL, '炎 (会意。从二火。本义火苗升腾) 同本义 炎,火光上也。--《说文》 火曰炎上。--《书·洪范》 秉畀炎火。--《诗·小雅·大田》 南有炎火千里。--《楚辞·大招》 顷之；组词：炎上(火焰向上；火向上燃烧) 焚烧 大炎昆冈,玉石俱焚', '小学', '1'),
    ('炒', 'chǎo', '8', '火', '左右', NULL, '炒 (形声。从火,少声。本义煎炒,火干) 一种烹调方法。把食物或其他东西放在锅里加热翻动使熟或使干,一般先要放少量的食油 中药炮制法之一。将药材放在锅内加热、翻动至一定要求 吵闹', '小学', '1'),
    ('炕', 'kàng', '8', '火', '左右', NULL, '炕〈动〉 张开 守宫槐,叶昼聂宵炕。--《尔雅》 另见葫杮衡 炕 〈动〉 (形声。从火,亢声。本义干,烘干)', '小学', '1'),
    ('炫', 'xuàn', '9', '火', '左右', NULL, '炫 (形声。从火,玄声。本义晃眼) 同本义 炫,烂耀也。--《说文》 炫光貌。--《埤仓》 炫熿干道。--《战国策·秦策》 大盆盛水,置剑其上,视之者精芒炫目。--《晋书》；组词：炫视(目光炫乱)；炫目(光彩夺目)；炫色(闪烁光芒)；炫炫(光耀明亮的样子) 迷惑；惑乱 显示；夸耀 生已沽名炫气豪,死', '小学', '1'),
    ('炬', 'jù', '8', '火', '左右', NULL, '炬 (形声。从火,巨声。本义火把) 同本义 苣,束苇烧。从苃,巨声。俗字作炬。--《说文》 束苣乘城。╠《后汉书·皇甫嵩传》 炬可以昭明。--《张衡传》注 牛尾炬火,光明炫耀；组词：炬烛(指蜡烛) 炬 火烧；放火 楚人一炬,可怜焦土', '小学', '1'),
    ('炭', 'tàn', '9', '火', '上下', NULL, '炭〈名〉 (形声。从火,岸省声。本义木炭) 同本义 炭,烧木余也。--《说文》 火所烧余木曰炭。--《释名》 坐于涂炭。--《孟子》。注墨也。” 可怜身上衣正单,心忧炭贱愿天寒；组词：木炭；草炭；骨炭；活性炭；炭炉(烧木炭的炉子)；炭薪(柴炭)；炭精纸(一种涂有炭精供复写的纸)；炭笔(用细木枝烧焦或用炭', '小学', '1'),
    ('炮', 'pào', '9', '火', '左右', NULL, '炮 bao 一种烹调方法 用锅等在旺火上急炒 中药制法之一。把药物放在高温铁锅里急炒,使其焦黄爆裂。如炮姜 把物品放在器物上烘烤或焙 炮 pao (形声。从火,包声', '小学', '1'),
    ('炸', 'zhà', '9', '火', '左右', NULL, '炸 把食物放在滚沸的油锅中熬熟 将旧金属器物加工,使重现光泽 妹妹的项圈我瞧瞧,只怕该炸一炸去了。；组词：瓶子炸了；爆炸 用炸药、炸弹爆破 炸(煠)zhá将食物放入沸油或沸水里弄熟~饼', '小学', '1'),
    ('点', 'diǎn', '9', '灬', '上下', NULL, '点 (形声。从黑,占声。本义斑点) 细小的黑色斑痕 点,黑也。--《说文》。按,小黑曰点。；组词：墨点儿；斑点；污点；点缺(瑕疵,缺点)；点漆(形容极黑) 小滴 七八个星天外,两三点雨山前', '小学', '1'),
    ('炼', 'liàn', '9', '火', '左右', NULL, '炼 (形声。从火,柬声。本义提炼) 同本义。用加热等方法使物质溶化并趋于纯净或坚韧 炼,铄冶金也。；组词：提炼(用理化方法从化合物或混合物中提取)；精炼(提炼精华,除去杂质)；炼石(烧炼丹石)；炼金(炼丹)；炼汞(道家烧炼金石', '小学', '1'),
    ('烁', 'shuò', '9', '火', '左右', NULL, '烁 (形声。从火,乐声。本义发光的样子) 同本义 中夜有大流星长数丈,光烁如电。--《新唐书·天文志》 热;烫;烤灼 烁 摇曳;闪烁 其外浅处,紫碧浮映,日光所烁也；组词：烁金(熔化金属；另指伤人的谗言) 烁(爍)shuò发光的样子闪~', '小学', '1'),
    ('烂', 'làn', '9', '火', '左右', NULL, '烂 (形声。从火,阑声。本义煮烂) 同本义 実,孰也。--《说文》。字亦作爛。 熟而不烂。--《吕氏春秋·本味》 三日三夕不烂。--晋·干宝《搜神记》 又 此儿头不烂。 是必烂也；组词：烂饭(加水较多而煮成的又软又烂的饭)；烂煮(煮至熟烂)；烂蒸(蒸至烂熟)；烂椹(熟透的桑椹) 火烧伤 焦头烂额为上客', '小学', '1'),
    ('烈', 'liè', '10', '灬', '上下', NULL, '烈〈形〉 (形声。从火,列声。火”字在下面一般写作四点。本义火势猛) 同本义 烈,火猛也。；组词：烈烧(炽烈的野火)；烈燧(炽烈的烽火)；烈烈(猛火炎炽貌)；烈光(炽热的阳光) 猛烈；激烈 其使民也酷烈', '小学', '1'),
    ('烘', 'hōng', '10', '火', '左右', NULL, '烘〈动〉 (形声。从火,共声。本义烧,焚烧) 同本义 烘,燎也。--《尔雅·释言》 卬烘于歮。--《诗·小雅·白华》；组词：烘眼(角膜炎之类的眼病,俗称红眼”)；烘焰(光焰)；烘腾腾(火旺盛貌) 烤干；烤热 衬托；渲染 映照 用同哄”', '小学', '1'),
    ('烙', 'lào', '10', '火', '左右', NULL, '烙〈动〉lao (形声。从火,各声。本义把食物放在烧热的器物上焙熟) 用高温的金属烧灼。引申为打上或留下标志 烧之剔之,刻之烙之。；组词：烙花 在烧热的锅内焙烤 用烙器(烧灼器)或烧灼剂烫 沙僧只叫脚底烙得慌!”--《西游记》 又如烙铁 烙〈动〉luo 灼', '小学', '1'),
    ('烛', 'zhú', '10', '火', '左右', NULL, '烛 (形声。从火,蜀声。本义古代照明用的火炬) 同本义 烛,庭燎大烛也。--《说文》。按,燋也。未爇曰燋,执之曰日烛,树地曰庭燎。苇薪为之,小者麻蒸为之。 执烛于西阶上；组词：烛火(火炬,火把)；烛 烛(爐)zhú 1.以线绳或苇子做中心,周围用蜡和油脂包裹,点燃取光的东西蜡~成灰泪始干', '小学', '1'),
    ('烟', 'yān', '10', '火', '左右', NULL, '烟 (形声。从火,因声。本义物质因燃烧而产生的气体) 同本义 火壮则煙微。--陆机《连珠》 煙炎之毁熸。；组词：烟火邻居(指紧邻)；烟扛扛(形容烟雾腾腾的样子)；烟爨(炊烟)；烟蓬(小火轮客舱顶上的散座)；烟祀(香烟与祭祀', '小学', '1'),
    ('烤', 'kǎo', '10', '火', '左右', NULL, '烤〈动〉 (形声。从火,考声。本义用火烘熟或烤干) 同本义 暴晒 炙热的阳光烤着他瘦长的身子。--巴金《将军集》 烤kǎo 1.用火把东西烘干或烘熟~烟。~鸭', '小学', '1'),
    ('烦', 'fán', '10', '火', '左右', NULL, '烦 (会意。从页,从火。从页”表示与头部有关;从火”,表示发烧。本义头痛发烧) 烦躁,烦闷 烦,热头痛也。；组词：心烦(心里烦躁)；烦积(烦闷积郁)；烦困(烦躁疲劳)；烦怨(烦恼怨恨) 通繁”', '小学', '1'),
    ('烧', 'shāo', '10', '火', '左右', NULL, '烧 (形声。从火,尧声。本义使物着火) 同本义 烧,爇也。--《说文》 雏烧。--《礼记·内则》。注烧烟,于火中也。” 齐之北泽烧火。--《管子·轻重甲》。注猎而行火曰烧；组词：干柴好烧；他把衣服烧了一个洞；烧葬(烧焚祭品)；烧丹炼汞(道家用朱砂水银等物炼成金丹以求长生不老)；烧糊了卷子(喻外貌丑', '小学', '1'),
    ('烫', 'tàng', '10', '火', '上下', NULL, '烫〈动〉 (本作汤) 以热水温物 叫浑家把肠子煮了,烫起酒来。--《儒林外史》 又如烫酒(用热水暖酒；组词：烫酒(用热水暖酒', '小学', '1'),
    ('热', 'rè', '10', '灬', '上下', NULL, '热 (形声。本义温度高) 同本义。跟冷”相对 肺甚畏热。--《素问·五常变大论》 清暖寒热,不得不救。--《韩非子·有度》 如水益深；组词：热天；热釜(热锅)；热浪；炽热；滚热；火热 满腔热情；热心肠 有权势的,权势显赫的 热(熱)rè 1.物理学上指凡能使物', '小学', '1'),
    ('烹', 'pēng', '11', '灬', '上下', NULL, '烹〈动〉 (形声。从火,亨声。本义烧煮) 同本义 烹,煮也。--《集韵》 故曰治大国者若烹小鲜。--《韩非子·解老》 卒买鱼烹食。--《史记·陈涉世家》；组词：烹炮(烹调的手艺)；烹鲜(比喻治理国家)；烹龙炮凤(形容山珍海味)；烹石(煎药)；烹炙(烹煮煎烤)；烹庖(烹治；烹煮)', '小学', '1'),
    ('焊', 'hàn', '11', '火', '左右', NULL, '焊 焊接 焊点 焊缝 焊工 焊喉 焊(鋓、鈌)hàn加热使熔化,连结金属或玻璃等的一种方法~接。电~。', '小学', '1'),
    ('焕', 'huàn', '11', '火', '左右', NULL, '焕 (形声。从火,奂声。本义火光) 同本义 焕,火光也。--《说文新附》 焕 光亮,鲜明 焕乎其有文章。--《论语》。集解明也。”；组词：焕乎(光亮的样子)；焕炳(光耀明亮)；焕发(光彩四现)；焕焕(显赫的样子) 闪耀强烈光亮的 焕 照耀；焕发光彩,放射光芒', '小学', '1'),
    ('焙', 'bèi', '12', '火', '左右', NULL, '焙 微火烘烤 夜火焙茶香。--白居易《题施山人野居》 又如焙炙(烘烤);焙火(焙烘的火力);焙茶(烘制茶叶);焙烘(烘烤) 焙干 焙烧 焙 bèi用微火烘烤(药材、食品、烟叶；组词：焙炙(烘烤)；焙火(焙烘的火力)；焙茶(烘制茶叶)；焙烘(烘烤) 焙干 焙烧 焙 bèi用微火烘烤(药材、食品、烟叶、茶', '小学', '1'),
    ('焚', 'fén', '12', '火', '上下', NULL, '焚〈动〉 (会意。从火,从林。甲骨文字形,象火烧丛木。古人田猎,为了把野兽从树林里赶出来,就采用焚林的办法。本义烧山) 用火烧山林宿草。 焚,烧田也。', '小学', '1'),
    ('焦', 'jiāo', '12', '灬', '上下', NULL, '焦〈动〉 (会意。金文字形,上面是隹”,短尾鸟,下面是火”。把鸟放在火上烤。本义物经火烧而变黄或成炭)；组词：焦盆(焦杯', '小学', '1'),
    ('焰', 'yàn', '12', '火', '左右', NULL, '焰 (形声。从火,臽声。本义火苗) 同本义 烟焰迷漫 。--清·薛福成《观巴黎油画记》 烟焰雾雨。--清·邵长蘅《青门剩稿》。；组词：内焰(火焰的中间部分)；外焰(火焰最外层)；焰段(见艳段”)；焰烘烘(焰腾腾', '小学', '1'),
    ('然', 'rán', '12', '灬', '上下', NULL, '然 (会意兼形声。下形,上声。四点是火的变形。是狗肉的意思,下面加火以烤狗肉。本义燃烧)；组词：然海(古代传说中的油海,其水可燃)；然脂(点油脂或蜡烛照明)；然灰(死灰复燃)；然除(烧毁)；然火(点火)；然炬(点燃火', '小学', '1'),
    ('煌', 'huáng', '13', '火', '左右', NULL, '煌 (形声。从火,皇声。皇”亦兼表字义。本义光明;光亮) 同本义 煌,煌煇也。--《说文》 煌,光也。--《苍颉篇》 煌光驰而星流。--《东京赋》 煌然而成篇谓之篇；组词：煌煌烨烨(明亮光辉', '小学', '1'),
    ('煎', 'jiān', '13', '灬', '上下', NULL, '煎 (形声。从火,前声。火”字写在下面时常变形成为四点。本义煎熬) 同本义 煎,熬也。--《説文》 煎,火干也。凡有汁而干谓之煎。--《方言七》 帐下烹煎皆美人；组词：煎米(指熬粥)；煎服(煎汁服下)；煎盘(方言', '小学', '1'),
    ('煞', 'shà', '13', '灬', '上下', NULL, '煞 同杀”。弄死,杀死 立性凶暴,多行煞戮。--杨衒之《洛阳伽蓝记》 又如令杖煞之;打煞人了 停止;结束 煞住脚往里细听。；组词：令杖煞之；打煞人了 停止；结束 煞住脚往里细听', '小学', '1'),
    ('煤', 'méi', '13', '火', '左右', NULL, '煤 (形声。从火,某声。本义烟尘) 同本义 试扫其煤以为墨,黑光如漆,松墨也。--宋·沈括《梦溪笔谈》 指墨 中官欲于苑中作墨灶,取西湖九里松作煤。--宋·陆游《老学庵笔记》；组词：煤精(煤的一种', '小学', '1'),
    ('照', 'zhào', '13', '灬', '上下', NULL, '照 (形声。从火,昭声,字亦作炤。本义明亮;光明) 同本义 照,明也。--《说文》 亦孔之炤。--《诗·小雅·正月》 月出照兮。--《诗·陈风·月出》 昔者十日并出,万物皆照；组词：照彻(透明晶莹 )；照澄(明朗清爽)炤” 照 照射,照耀 照耀煇煌', '小学', '1'),
    ('煮', 'zhǔ', '12', '灬', '上下', NULL, '煮 (形声。从火,者声。本义把东西放在有水的锅里加热使熟) 同本义 东煮海水为盐。--《汉书》 命妪煮芋。--清·周容《芋老人传》 又 妪煮芋进。 时挑野菜和根煮,旋斫生柴带叶烧；组词：煮瀑(即煮泡,放在水中煮)；煮爆(煮)；煮汤(熬药)；煮海(煮海水为盐)；煮井(煮盐井之水为盐)；煮汁(药物和水熬成汁液', '小学', '1'),
    ('熄', 'xī', '14', '火', '左右', NULL, '熄 (形声。从火,息声。本义火熄灭) 同本义 熄,畜火也。从火,息声。亦曰灭火。--《说文》。按,蓄与灭一义之引申。；组词：熄火罐头(指能降伏擒拿凡人的法宝)；熄火；熄灯(灭灯)；火势已熄 消亡；平息；止 安居而天下熄', '小学', '1'),
    ('熊', 'xióng', '14', '灬', '上下', NULL, '熊 (形声。从能,炎省声。能,熊”。本义动物名) 属于食肉目熊科(ursidae)的一种大型笨重的哺乳动物 熊兽似豕,山居各蛰。', '小学', '1'),
    ('熏', 'xūn', '14', '灬', NULL, NULL, '熏 (俗作燻。会意。金文,上面象火烟冒出,中间是烟突(本古窗”字),两点表示烟苔,下面是火焰∠起来是烟突冒烟。本义火烟向上冒)；组词：熏天(上蒸而弥漫于天)；熏焌(热气升腾) 烧灼,火烫 我心惮暑,忧心如熏', '小学', '1'),
    ('熔', 'róng', '14', '火', '左右', NULL, '熔 (熔为鎔的俗字。形声。从火,容声。本义用高温使固体物质转变为液态) 同本义 鎔,冶器法也。；组词：熔炼(熔化炼制；喻培养)；熔造(将固体熔化后,再铸造新的器物)；熔铄(熔化金属) 熔 铸造器物的模子 犹金之在鎔,惟冶者', '小学', '1'),
    ('熙', 'xī', '14', '灬', '上下', NULL, '煕 (形声,本义曝晒;晒太阳) 同本义 熙,燥也。--《说文》 仰熙丹崖,俯澡绿水。--《文选·卢谌·赠刘琨》 振兴;兴起 允厘百工,庶绩咸熙。--《书·尧典》；组词：熙朝(使朝廷兴隆)；熙隆(兴盛,盛隆)；熙国(振兴国家) 通嬉”', '小学', '1'),
    ('熟', 'shú', '15', '灬', '上下', NULL, '熟 (形声。从火,孰声。本作孰”。熟”是后起字。本义煮熟,食物烹煮到可吃的程度) 同本义 熟治万物。；组词：熟末(指煮得烂熟的食物)；熟切店(卖熟肉的店铺)；熟水(开水)；熟献(指烹熟的上献祭品) 谷物、水果或微生物等成熟 秋,', '小学', '1'),
    ('熬', 'áo', '14', '灬', '上下', NULL, '熬〈动〉 把蔬菜等加水并放在文火上煮。如熬白菜;熬豆腐 熬(爊)āo 煮~肉。 熬áo 1.久煮~药。 2.忍受,勉强支持~夜。~痛。煎~。', '小学', '1'),
    ('燃', 'rán', '16', '火', '左右', NULL, '燃 (形声。从火,然声。然”有表意作用。本作然”。燃”是后起字。本义燃烧) 同本义 煮豆燃豆萁,豆在釜中泣。--曹植《七步诗》；组词：燃藜图(劝人勤学苦读的画)；燃灰(死灰复燃)；燃灼(燃烧；烧灼)；燃顶(以香火烧灼头顶,表示虔诚) 引火点着 .....', '小学', '1'),
    ('燎', 'liáo', '16', '火', '左右', NULL, '燎〈名〉 放在地上的火炬,大火把 夜未央,庭燎之光。--《诗·小雅·庭燎》。疏庭燎者,树之于庭,燎之为明,是烛之大者。 火在地曰燎,执之曰烛。--《仪礼·士丧礼》注；组词：燎火(火炬)；燎炬(火把)；燎烛(烛炬) 燎〈动〉 烫 燎〈动〉 (形声', '小学', '1'),
    ('燕', 'yàn', '16', '灬', '上下', NULL, '燕 古国名 周代诸侯国名。本作匽、郾。姬姓;周召公之后,世称北燕,拥有今河北省北部和辽宁省西端,建都蓟(今北京)。战国时成为七雄之一◇灭于秦 燕赵韩魏。', '小学', '1'),
    ('燥', 'zào', '17', '火', '左右', NULL, '燥〈名〉 sao 剁细的肉 燥 〈形〉 快 从此以后,匡超人的肉和豆腐都卖得生意又燥,不到日中就卖完了,把钱拿来家伴着父亲。；组词：燥吻(干燥的嘴唇)；燥坼(干燥坼裂)；燥劲(干燥强劲)；燥刚(干燥刚劲)；燥气(干燥之气)；燥急(干渴得利害)；燥渴 燥', '小学', '1'),
    ('爆', 'bào', '19', '火', '左右', NULL, '爆 (形声。从火,暴声。本义炸裂发声) 同本义 爆,灼也。--《说文》 火爆声。--《虞初新志·秋声诗自序》；组词：车胎爆了；爆烈(猛烈爆炸)；爆响(突然而猛裂地发出声响) 燃着 湿薪未爆先烟', '小学', '1'),
    ('爪', 'zhǎo', '4', '爪', NULL, NULL, '爪 zhao (象形。按甲骨文和小篆字形,又”是手,两点表手爪甲形。本义人的指甲、趾甲)；组词：爪甲(指或趾前的角质硬壳)；爪翦(修剪手指甲或脚趾甲) 鸟兽的脚趾 蚓无爪牙之利', '小学', '1'),
    ('爬', 'pá', '8', '爪', '半包围', NULL, '爬〈动〉 (形声。从爪,巴声。爪,手爪。本义搔,爬梳) 同本义 爬,搔也。--《广韵》 怯烦类决痈,惬兴剧爬疥。--韩愈等《雨中寄孟刑部几道联句》 支分闲事了,爬背向阳眠；组词：爬挲(爬搔,摩挲)；爬栉(梳理,整理', '小学', '1'),
    ('爱', 'ài', '10', '爫', '上下', NULL, '爱〈动〉 (形声。从心,旡声。本义亲爱;喜爱) 对人或事物有深厚真挚的感情 惠,爱也。--《尔雅》 爱施者,仁之端也。--《说苑·说丛》 君子自爱,仁之至也', '小学', '1'),
    ('爵', 'jué', '17', '爫', '上下', NULL, '爵 (象形。甲骨文字形,象古代饮酒器。本义古代酒器。青铜制) 盛酒的礼器,形似雀,青铜制,有流、两柱、三足,用以温酒或盛酒,盛行于殷代和西周初期 爵,礼器也。象爵之形,中有鬯酒', '小学', '1'),
    ('父', 'fù', '4', '父', '上下', NULL, '父〈名〉 对有才德的男子的美称,多附缀于表字后面 维师尚父,时维鹰扬。--《诗·大雅》 三月,公及邾仪父盟于眜。--《春秋》 余弟安国平父,安上纯父；组词：渔父；田父 通甫”', '小学', '1'),
    ('爷', 'yé', '6', '父', '上下', NULL, '爷 (形声。从父,耶声。简体字卩”只是个符号。本义父亲) 同本义。也作耶” 愿为市鞍马,从此替爷征。；组词：爷娘皇天(呼爹叫娘,嚎天喊地) 爷爷 祖父--多叠用 爷爷会织布、会种田、还会养牛 对与祖父辈分相同、年龄相仿的男子的敬', '小学', '1'),
    ('爸', 'bà', '8', '父', '上下', NULL, '爸 (形声。从父,巴声。本义父亲) 爸,父也。--《广雅·释亲》。王念孙曰爸者,父亲之转。”；组词：爸爸(父亲)；阿爸 这个地方离三爸的律师事务所不远,三爸怎么会不晓得?--巴金《家》 爸bà 1.即父亲', '小学', '1'),
    ('爹', 'diē', '10', '父', '上下', NULL, '爹 (形声。从父,多声。本义父亲) 对老者、长者的尊称 女(徐七娘)臭项 阿爹!妈等你吃中饭呢!--茅盾《春蚕》 旧时对官长的尊称或作官长的代称 比及爹有这个心,小人打听在肚里了', '小学', '1'),
    ('爽', 'shuǎng', '11', '爻', NULL, NULL, '爽 (会意。甲骨文字形,像人左右腋下有火,表示明亮(从于省吾说)。本义明亮;亮) 同本义 爽,明也。；组词：神清目爽；爽旦(黎明,清晨)；爽别(清亮)；爽拔(清朗秀技)；爽明(黎明)；爽曙(明晓)；爽豁(清楚而明显) 畅快；舒适', '小学', '1'),
    ('片', 'piàn', '4', '片', NULL, NULL, '片〈名〉 指有图像、景物或录有声音的片子 片〈动〉 (指事。甲骨文字形,象劈开的木片。本义劈开树木之类)；组词：片批(切肉的一种刀法', '小学', '1'),
    ('版', 'bǎn', '8', '片', '左右', NULL, '版 (形声。从片,反声。片”,意思是破开的木片或草片。从片”的字大都与木板有关。本义筑墙的夹板)；组词：版筑 供建筑或其他使用的木板◇作板” 牍', '小学', '1'),
    ('牌', 'pái', '12', '片', '左右', NULL, '牌〈名〉 (形声。从片,卑声。片”指锯开的木头的一半,又泛指扁而薄的东西。本义题榜,招牌) 户籍板。犹今之户口簿 簧牌,籍也。', '小学', '1'),
    ('牍', 'dú', '12', '片', '左右', NULL, '牍 (形声。从片,卖声。片”,本指木头竖剖成的一半。古时用木片作书写材料。故从片”。本义古代写字用的木片,也称木简)；组词：牍背(狱吏于书板背面书写文句◇用为遭受冤狱的典实) 引申为公文 无丝竹之乱耳,无案牍之 牍 dú 1古代书写用的木片', '小学', '1'),
    ('牙', 'yá', '4', '牙', NULL, NULL, '牙 (象形。金文字形,象上下牙齿交错形。牙”是汉字的一个部首。本义槽牙) 大牙,臼齿。古时,当唇者称齿,在辅车之后者称牙 牙,牡齿也。象上下相错之形。；组词：牙祭(旧指东家给伙计在每月初二、十六吃肉食)；牙疼咒(牙疼誓', '小学', '1'),
    ('牛', 'niú', '4', '牛', NULL, NULL, '牛 (象形。甲骨文字形作牜”。中间一竖表示牛面,上面两竖加弯表牛角,下面两小撇表示牛耳) 牛属或近缘属的成员。哺乳动物,体型粗壮,角中空,由头骨向两侧呈大弧度伸出。力大,能耕田', '小学', '1'),
    ('牡', 'mǔ', '7', '牜', '左右', NULL, '牡 (会意。从牛,土声。甲骨文字形,左为阳性生殖器。本义雄性的鸟兽) 同本义 牡,畜父也。', '小学', '1'),
    ('牢', 'láo', '7', '牛', '上下', NULL, '牢〈名〉 (象形指事。据甲骨文,里面是个牛”字,外面象养牛的圈。泛指一般养性畜的栏圈。本义关养牛马等牲畜的圈)；组词：牢栈(圈养牲畜的栅栏)；牢筴(猪圈)；牢藉(猪圈) 古代祭祀或宴享时用的牲畜', '小学', '1'),
    ('牧', 'mù', '8', '牜', '左右', NULL, '牧 (会意。甲骨文字形。从牛,从攴,表示手拿棍棒牧牛(羊)。本义放牧牲畜) 同本义 掌牧六牲。；组词：牧所(牧养牲畜的处所)；牧苑(牧场', '小学', '1'),
    ('物', 'wù', '8', '牜', '左右', NULL, '物 (形声,从牛,勿声。勿”是一种杂色旗,表示杂色。本义万物) 同本义 物,万物也。牛为大物,天地之数起于牵牛,故从牛。；组词：物品(各种财货、物件)；物母(万物的本源)；物曲(物的性能)；物如(事物的本源)；物序(事物的规律)；物祖(万物之祖)', '小学', '1'),
    ('牲', 'shēng', '9', '牜', '左右', NULL, '牲 (形声。从牛,从生。本义古代供祭祀用的全牛) 同本义 牲,牛完全也。--《说文》。按,牛完全当为字之训。 全曰牲,伤曰牛。--《谷梁传·哀公元年》 始养之曰畜,将用之曰牲；组词：牲体(古时祭祀用的牺牲的躯体)；牲礼(祭祀时的用牲之礼)；牲玉(供祭祀用的牺牲和玉器)；牲事(古代祭祀中有关准备牺牲的事', '小学', '1'),
    ('牵', 'qiān', '9', '牛', '上下', NULL, '牵 (形声。从牛,冖”象牵牛的绳,玄声。本义牵牛) 同本义。引申为牵拉 牵,引前也。--《说文》 牵,引也。--《广雅》 飱牵。--《周礼·宰夫》。司农注牲牢可牵而行者；组词：牵笼(拉扯)；庆(牵巾', '小学', '1'),
    ('特', 'tè', '10', '牜', '左右', NULL, '特〈名〉 (形声。从牛,寺声。本义雄性的牛马) 同本义 特,朴特,牛父也。--《说文》 凡马,特居四之一。--《周礼·夏官·校人》 特,牡牛也。--《玉篇》；组词：特处士(赋予公牛以处士头衔)；特牛(一头公牛) 泛指牛 高辛氏人家生一犬,初如小特', '小学', '1'),
    ('牺', 'xī', '10', '牜', '左右', NULL, '牺 (形声。从牛,羲声。本义做祭品用的毛色纯一的牲畜) 同本义 牺,宗庙之牲也。--《说文》 今殷民乃攘窃神祇之牺牷牲用。--《书·微子》。传色纯曰牺。” 共其牺牲；组词：牺牛(古代祭祀用的纯色牛 牺(犧)xī 1.〈古〉作祭品用的纯毛色的牲畜', '小学', '1'),
    ('犀', 'xī', '12', '牛', NULL, NULL, '犀 犀牛 犀,南徼外牛,一角在鼻,一角在顶,似豕,从牛,尾声。--《说文》 犀,似水牛,猪头,大腹,庳脚,脚有三蹄,黑色,三角,一顶上,一额上,一鼻上,鼻上者即食角也。小而不椭；组词：犀牛望月(形容长久盼望)；犀分(划分', '小学', '1'),
    ('犁', 'lí', '11', '牛', '上下', NULL, '犁 (形声。从牛,利声。本义牛耕) 同本义 犂,耕也。--《说文》。字亦作犁。 犁其庭。--《汉书·匈奴传》。注耕也。” 犂牛之子。--《论语》。皇疏或音梨,谓耕犂也；组词：犁耕(用犁耕田；耕田)；犁花(犁翻的土块)；犁春(春耕) 摧毁,平毁 割开,划开', '小学', '1'),
    ('犬', 'quǎn', '4', '犬', NULL, NULL, '犬〈名〉 (象形。犬”是汉字部首之一。本义狗) 同本义。古时特指大狗,后来犬、狗通名 犬,狗之有县蹏者也。象形。孔子曰视犬之字如画狗也。；组词：牧羊犬；猎犬；警犬；玩赏犬；挽曳犬；皮肉用犬；犬羊(狗和羊)；犬马(狗和马)；犬人(官名', '小学', '1'),
    ('犯', 'fàn', '5', '犭', '左右', NULL, '犯〈动〉 同本义 犯,侵也。--《说文》。按,字本言犬犯人。转注为凡干陵违逆之称。 軓又义兴水中有蛟,山中有白额虎,并皆暴犯百姓。--《世说新语·自新》；组词：人不犯我,我不犯人；犯界(侵犯他国领土)；犯境(犯边', '小学', '1'),
    ('状', 'zhuàng', '7', '犬', '左右', NULL, '状 (形声。从犬,爿声。用具体的动物犬”表示事物各具形态。本义犬形) 同本义。引申为形状,形态 状,犬形也。；组词：状类(形似)；粉状；杆状；块状；粒状；絮状；海绵状；奇形怪状 情形；状况 舍人弟上变,告信欲反状于吕后', '小学', '1'),
    ('犹', 'yóu', '7', '犭', '左右', NULL, '犹 (形声。从犬,酋(尤)声。本义一种猿类动物) 兽名★属,也叫犹猢”,形如麂 猶,愑属。', '小学', '1'),
    ('狂', 'kuáng', '7', '犭', '左右', NULL, '狂〈形〉 (形声。本义狗发疯) 同本义。也指狗发疯 狂,猳犬也。--《说文》 值狂犬之暴怒,加楚害于微躯。--三国魏·阮籍《鸠赋》；组词：狂犬(凶猛的狗) 引申指人的精神失常”,疯癫” 狂夫瞿瞿', '小学', '1'),
    ('狈', 'bèi', '7', '犭', '左右', NULL, '狈 传说中的一种兽,狼属。前腿特别短,走路时要爬在狼身上,没有狼,它就不能行动,所以用狼狈形容困苦或受窘的样子 狈 bèi传说中的兽名。前腿特别短。', '小学', '1'),
    ('狐', 'hú', '8', '犭', '左右', NULL, '狐 (形声。从犬,瓜声。本义狐狸) 同本义 朕狐疑。--《汉书·文帝纪》。注狐性多疑,每渡冰河,且听且渡,故言疑者称狐疑。” 小狐汔济。--《易·未济》 狐鸣呼曰；组词：狐丘(狐穴居之小山)；狐白(狐腋下的白毛)；狐兔(狐和兔)；狐仙(传说狐狸能修炼成仙,化为人形,与人来往) 喻坏人,小人', '小学', '1'),
    ('狗', 'gǒu', '8', '犭', '左右', NULL, '狗 (形声。从犬,句声。本义犬。原指小犬◇为狗犬的通称) 同本义 狗,犬也。大者为犬,小者为狗。', '小学', '1'),
    ('狞', 'níng', '8', '犭', '左右', NULL, '狞 红肌拂拂酒光狞,当街背拉金吾行。--唐·顾况《公子行》 如狞目(凶恶的眼睛);狞毒(凶狠恶毒);狞狰(狰狞,凶恶);狞厉(凶恶可怕) 猛烈,气势大、力量大 通獰”', '小学', '1'),
    ('狠', 'hěn', '9', '犭', '左右', NULL, '狠〈形〉 (形声。从犬,艮声。本义犬争斗声。又指凶狠,残忍) 通很”。凶狠;凶残 有能耐的,有本领的 坚决 狠 〈动〉 下定决心 他爱钱如命,可是为维持事情,不得不狠了心', '小学', '1'),
    ('狡', 'jiǎo', '9', '犭', '左右', NULL, '狡〈名〉 (形声。从犬,交声。本义小狗) 同本义 狡,少狗也。匈奴地有狡犬,巨口而黑身。--《说文》 狡狗之死也。--《淮南子·俶真》；组词：狡犬(狡狗', '小学', '1'),
    ('独', 'dú', '9', '犭', '左右', NULL, '独 (形声。从犬,蜀声。犬性好斗,多独居,故字从犬。本义单独;单一) 同本义 独,犬相得而斗也。羊为群,犬为独也。', '小学', '1'),
    ('狭', 'xiá', '9', '犭', '左右', NULL, '狭 (形声。从犬,夹声。本义窄,宽度、广度小) 同本义 阜隘狭而幽险兮。--《楚辞·怨思》。注陋也。” 其生民也陿阨。--《汉书·刑法志》。注地小也。” 险道狭路,可击；组词：狭缝；狭路相逢；狭长(窄而长)；狭迫(窄小局促) 心胸狭窄 小人狭薄,尚为激然之气,战燎于胸中', '小学', '1'),
    ('狮', 'shī', '9', '犭', '左右', NULL, '狮 犬生二子称狮” 狮,犬生二子。--《广韵》 猛兽名 的粗糙鬣毛。如狮儿(喻雄视一世的俊杰);狮子口(狱门);狮子座(狮子坐。佛坐之处)', '小学', '1'),
    ('狰', 'zhēng', '9', '犭', '左右', NULL, '狰 (形声。从犬,争声。犬”泛指兽类。本义传说中的奇兽)同本义 又如狰狞(形容面目凶恶) 狰zhēng', '小学', '1'),
    ('狱', 'yù', '9', '犭', '左右', NULL, '狱 狱,确也。--《说文》 而有狱讼者。--《周礼·大司徒》。注争罪曰狱。” 利用狱。--《易·噬嗑》 毋敢折狱。--《易·象上传》 以两剂禁民狱；组词：狱诉(告状)；狱讼(诉讼)；狱犴(诉讼)；狱司(管理诉讼、牢狱的机构) 狱 讼案 夫君臣无狱', '小学', '1'),
    ('狸', 'lí', '10', '犭', '左右', NULL, '狸〈名〉 (狸为貍的俗字。形声。从豸,长脊的野兽,里声。本义狸子,也叫野猫、山猫) 同本义 捕鼠不知狸狌,此家猫也。；组词：狸狌(野猫)；狸制(狸兽毛皮制成的服饰)；狸力(神兽名) 黄鼠狼的别名 狸lí 1.貉的别称', '小学', '1'),
    ('狼', 'láng', '10', '犭', '左右', NULL, '狼〈名〉 (形声。从犬,良声。本义狼) 同本义 狼,似犬,锐头,白颊,高前广后。--《说文》 并驱从两狼兮。--《诗·齐风·还》 犬属的任何一种大型犬形哺乳动物,狡猾、贪婪,对牛', '小学', '1'),
    ('猎', 'liè', '11', '犭', '左右', NULL, '猎 (形声。从犬,巤声。本义打猎,捕捉禽兽) 同本义 猎,放猎逐禽也。--《说文》 不狩不猎,胡瞻尔庭有县貆兮?--《诗·魏风·伐檀》 执弓挟矢以猎。--《礼记·月令》 楚蒵艾猎；组词：猎火(打猎时焚山以驱兽的火)；猎围(猎捕禽兽的围子)；猎士(打猎的壮士)；猎夫(猎手、猎民、猎者、猎客、猎师、猎徒', '小学', '1'),
    ('猖', 'chāng', '11', '犭', '左右', NULL, '猖 (形声。从犬,昌声。本义猖狂) 同本义 猖 猖狂的人 苏枯弱强,龈其奸猖。--唐·韩愈《曹成王碑》 猖 chāng凶猛~狂(狂妄而放肆)。 【猖獗】 1凶猛而放肆黑市~', '小学', '1'),
    ('猛', 'měng', '11', '犭', '左右', NULL, '猛 (形声。从犬,孟声。本义健壮的狗) 同本义 猛,健犬也。--《说文》 驱猛兽。--《孟子》 猛虞趪趪。--张衡《西京赋》。注怒也。”；组词：大猛(大狗) 猛 凶恶可怕 公之狗甚猛', '小学', '1'),
    ('猜', 'cāi', '11', '犭', '左右', NULL, '猜〈动〉 (形声。从犬,青声。本义疑恨;忌恨) 同本义 猜,恨贼也。--《说文》。按,字从犬,如狡狯狂猛之类,本以言犬,移以言人。 耦俱无猜。--《左传·僖公九年》。注两无猜恨；组词：猜忍(猜忌残忍)；猜迫(疑忌而加以逼迫)；猜忿(疑忌愤恨)；猜刻(疑忌而刻薄)；猜虐(疑忌暴虐)；猜狠(疑忌而凶狠)；猜', '小学', '1'),
    ('猩', 'xīng', '12', '犭', '左右', NULL, '猩 猩猩的省称 鲜红色 俄而大轿内抬着一个乌帽猩袍的官府来了。--《红楼梦》 猩xīng', '小学', '1'),
    ('猪', 'zhū', '11', '犭', '左右', NULL, '猪 猪只 达,热时喜浸水散热;特指家养种的成员 猪,豕而三毛丛居者。从豕,者声。--《说文》。按,豕子也。 如猪魈(猪怪;猪精);猪膀胱(又称猪尿泡”、猪胞”、猪尿脬”、猪脬”)', '小学', '1'),
    ('猫', 'māo', '11', '犭', '左右', NULL, '猫 家猫,久已被人类驯养的一种食肉类动物 区别在于皮毛的长短,体形以及尾的有无 迎猫,为其食田鼠也。；组词：猫儿眼(宝石名称,又名猫睛石”', '小学', '1'),
    ('猬', 'wèi', '12', '犭', '左右', NULL, '猬 兽名。即刺猬 矢如猬毛。--宋·司马光《资治通鉴·唐纪》 脊椎动物亚门,哺乳纲,食虫目,猬科。如猬毛(猬之毛。比喻众多);猬缩(刺猬遇敌则缩。比喻人畏缩不前)', '小学', '1'),
    ('献', 'xiàn', '13', '犬', '左右', NULL, '献 (会意。从犬,鬳声。犬”代表进献之物。本义献祭) 同本义 献,宗庙犬,名羹献。犬肥者以献之。；组词：献尸(向代表死人的尸者进献祭品)；献帛(祭祀礼仪之一,献上巾帕)；献爵(祭祀礼仪之一,献酒)；献台(祭台) 下对上、卑对', '小学', '1'),
    ('猴', 'hóu', '12', '犭', '左右', NULL, '猴〈名〉 猴子。即弥猴 比喻机灵的人 猴 〈动〉 像猴子似地蹲坐 像猴子一样攀援纠缠 宝玉听话,便猴向凤姐身上立刻要牌。', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('猾', 'huá', '12', '犭', '左右', NULL, '猾〈形〉 (形声。从犬,骨声。本义狡诈,狡猾) 同本义 猥胥报充里正。--清·姚鼐《登泰山记》；组词：猾虏(狡猾之徒)；猾伯(最狡猾虚妄的人)；狡胥(狡猾的小吏)；猾恶(狡猾奸恶) 猾 〈动〉 扰乱；侵犯 弄,播弄 遇兆,', '小学', '1'),
    ('猿', 'yuán', '13', '犭', '左右', NULL, '猿 (形声。从犬,袁声。猿似犬,故从犬。本义灵长类动物,形态与猴相似) 同本义 蝯善援,禺属。；组词：猿猴献果(指将人的四肢在胸前捆在一起的姿势)；猿狖(猿猴)；猿眩(猿临悬崖而目眩', '小学', '1'),
    ('玄', 'xuán', '5', '玄', '上下', NULL, '玄 (象形。小篆字,下端象单绞的丝,上端是丝绞上的系带,表示作染丝用的丝结。本义赤黑色,黑中带红)', '小学', '1'),
    ('率', 'lǜ', '11', '玄', NULL, NULL, '率〈名〉 法令;条例 规格;标准 有军功者,各以率受上爵。--《史记》 比例;比率 假借锊”。古重量名 其罚百率。--《史记·周本纪》 率 率〈动〉 lv 率 shuai (象形', '小学', '1'),
    ('玉', 'yù', '5', '玉', NULL, NULL, '玉 (象形。甲骨文字形。象一根绳子,串着一些玉石。玉”是汉字的一个部首。本义温润而有光泽的美石)；组词：玉情儿(玉石的质量、成色)；玉墀(白玉台阶)；玉阙(宝座；皇宫)；玉虚(道教指玉帝的居处)；玉树(指槐树)；玉砚(玉石制', '小学', '1'),
    ('王', 'wáng', '4', '王', '上下', NULL, '王 (会意。本作士”,是能独立任事的人,后加一横,表示在士”之上,即人间的最高统治者,而帝 是天上的最高统治者◇帝”、王”同步降职,帝成了人间的皇帝,而王 ”成了对臣子的最高封爵', '小学', '1'),
    ('玖', 'jiǔ', '7', '王', '左右', NULL, '玖 (形声。从玉,久声。本义似玉的黑色美石) 同本义 玖,石之次玉,黑色。--《说文》 报之以琼玖。--《诗·卫风·木瓜》 贻我佩玖', '小学', '1'),
    ('玛', 'mǎ', '7', '王', '左右', NULL, NULL, '小学', '1'),
    ('玩', 'wán', '8', '王', '左右', NULL, '玩 (形声。从玉,元声。本义以手玩弄 玩耍;玩弄 玩,弄也。--《说文》 将还玩吾国于股掌之上。--《国语·吴语》 民狎而玩之,则多死焉,故宽难；组词：玩服(玩赏佩用之物)；玩爱(玩赏珍爱)；玩饰(供玩赏的佩饰) 玩赏；欣赏 展玩不可晓', '小学', '1'),
    ('玫', 'méi', '8', '王', '左右', NULL, '玫瑰 (形声。从玉,文声。双音词玫瑰”,指美玉,或珍珠,又植物名) 一种蔷薇属落叶灌木(rosa rugosa),羽状复叶,小叶3╠9片,椭圆形或椭圆状倒卵形,花单生', '小学', '1'),
    ('环', 'huán', '8', '王', '左右', NULL, '环 (形声。从玉,本义圆形而中间有孔的玉器) 同本义 环,璧也。--《说文》 肉好若一谓之不。--《尔雅·释器》。李注其孔及边肉大小适等。” 行步则有环珮之声；组词：环佩(古人衣带上所系的佩玉)；环玦(玉环和玉玦)；环琨(环与琨,并为玉佩)；环塡(两种玉制的耳饰', '小学', '1'),
    ('现', 'xiàn', '8', '王', '左右', NULL, '现 (形声。从玉,见声。本义出现) 同本义(明显看得见) 现,俗见字。--《广韵》 东坡现右足。--明·魏学洢《核舟记》；组词：现弄(在人面前炫示自己)；现化(佛教所称佛或菩萨在人间显现的化身)；现示(显示) 见 帝宣,三人借袍现帝', '小学', '1'),
    ('玲', 'líng', '9', '王', '左右', NULL, '玲〈象,形〉 (形声。从玉,令声。玲玎玉石等相击的清脆声) 象声词。玉声 玲,玉声。--《说文》 玲珑,玉声也。--《埤苍》 和氏珑玲。--扬雄《甘泉赋》；组词：玲玲；玲琅(玉声) 明亮或美好的样子 珊瑚幽茂而玲珑', '小学', '1'),
    ('玷', 'diàn', '9', '王', '左右', NULL, '玷 (形声。本义白玉上的斑点) 同本义 玷,玉瑕。--《广韵》 白圭之玷,尚可磨也。--《诗·大雅·抑》。传玷,缺也。” 不知其玷；组词：玷缺(白玉有斑点、缺损', '小学', '1'),
    ('玻', 'bō', '9', '王', '左右', NULL, '玻璃 玻璃板 玻璃钢 玻璃纤维 玻璃纸 玻璃砖 玻 bō 【玻尔半径】在玻尔理论中是氢原子处于基态时电子绕核运行所作的圆轨道的半径。是原子物理学中的一种长度单位。常用表示', '小学', '1'),
    ('珊', 'shān', '9', '王', '左右', NULL, '珊瑚 珊瑚,色赤,生于海,或生于山。--《说文》。按,似树,大者高三尺余,枝格交错,无叶,有青色者,曰琅玕', '小学', '1'),
    ('珍', 'zhēn', '9', '王', '左右', NULL, '珍 (本义珠玉等宝物) 同本义 珍,宝也。--《说文》 珍圭。--《周礼·典瑞》。注王使之瑞节。” 多珍怪些。--《楚辞·招魂》。注金玉为珍。” 珍怪奇物；组词：珍积(积蓄的财宝)；珍翰(墨宝)；珍币(珍宝财物)；珍赂(珍赀', '小学', '1'),
    ('珠', 'zhū', '10', '王', '左右', NULL, '珠 (形声。从玉,朱声。本义珍珠。蛤蚌壳内由分泌物结成的有光小圆体) 同本义 珠,蚌之阴精。；组词：珠户(采珠的民户；珠饰的门户)；珠履(以珍珠为饰的鞋子)；珠碧(珍珠与碧玉)；珠英(美如珍珠的花)；珠翠(珍珠与翠玉)', '小学', '1'),
    ('班', 'bān', '10', '王', '左中右', NULL, '班 (会意。从玨,从刀。金文,中间是刀,左右是玉。象用刀割玉。本义分割玉) 分瑞玉。瑞玉是古代玉质的信物,中分为二,各执其一以为信 班,分瑞玉也。；组词：班瑞(颁还瑞玉；颁赐祥瑞) 分开；离群 挥手自兹去,萧萧班马鸣', '小学', '1'),
    ('球', 'qiú', '11', '王', '左右', NULL, '球〈名〉 (形声。从玉,求声。本义美玉) 同本义 球,王磬也。--《说文》。按,古以为磬,亦为笏,亦为刀室饰。 球琳琅珰。--《书·禹贡》。郑注美玉也。” 天球。--《书·顾命》', '小学', '1'),
    ('琅', 'láng', '11', '王', '左右', NULL, '琅 (形声。从玉,良声。本义似玉的美石或青色的珊瑚) 同本义 琅,琅玕似珠者。--《说文》 厥贡惟球琳琅玕。--《书·禹贡》。传石似玉。”；组词：琳琅(美玉,比喻优美珍贵的东西)；琅花(琅华', '小学', '1'),
    ('理', 'lǐ', '11', '王', '左右', NULL, '理〈动〉 (形声。从玉,里声。本义加工雕琢玉石) 同本义 理,治玉也。顺玉之文而剖析之。--《说文》 理者,成物之文也。长短大小、方圆坚脆、轻重白黑之谓理', '小学', '1'),
    ('琉', 'liú', '11', '王', '左右', NULL, '琉璃 等。亦指琉璃灯座 一盏琉璃 琉liú', '小学', '1'),
    ('琐', 'suǒ', '11', '王', '左右', NULL, '琐 (形声。本义玉件相击发出的细碎声音) 同本义 琐,玉声也。--《说文》 也作琐琐” 玉珂声琐琐,锦帐梦悠悠。--唐·杜牧《送刘三复郎中赴阙》 镂玉为连环叫琐,后以金属为之；组词：琐闱(镌刻连琐图案的宫中旁门)；琐闼(镌刻连琐图案的宫中小门) 加在门、箱等上面使人不能随便开启的器具◇作锁” 锁,铁锁', '小学', '1'),
    ('琢', 'zhuó', '12', '王', '左右', NULL, '琢 zhuo (形声。从玉,豿声。本义雕刻加工玉石) 同本义 琢,治玉也。--《说文》 雕谓之琢。--《尔雅》 玉不琢,不成器。--《礼记·学记》 和之璧,井里之厥也。玉人琢之；组词：琢玉(雕刻加工玉石)；琢火(琢石冒出火星)；琢治(雕琢玉石等)；琢克(雕刻)；琢雕(雕琢,指雕刻金玉为器)', '小学', '1'),
    ('琳', 'lín', '12', '王', '左右', NULL, '琳〈名〉 (形声。从玉,林声。本义美玉) 同本义 琳,美玉也。--《说文》 琳,玉也。--《尔雅》 琳珉昆吾。--《汉书·司马相如传》。注玉也。” 厥贡惟救琳琅玕；组词：琳珉(美玉名)；琳华(仙界的花)；琳札(珍贵的书札)；琳珪(美玉)；琳球(指美玉)；琳与(美玉) 青色玉 琳琅 琳琅满目', '小学', '1'),
    ('琴', 'qín', '12', '王', '上下', NULL, '琴 (本作珡”。象形。小篆字形,象乐器形,上面玨”象弦和弦柱,下面象琴身。本义拨弦乐器。俗称古琴)；组词：琴史(琴和史籍)；琴书(琴与书；谈论琴艺的典籍)；琴床(琴案；琴几)；琴柱(琴上用以系弦的柱) 某些乐器的通称 琴qín', '小学', '1'),
    ('琼', 'qióng', '12', '王', '左右', NULL, '琼 (形声。左形,右声。本义赤色玉) 同本义。泛指美玉 投我以木瓜,报之以琼琚。--《诗·卫风·木瓜》 精琼靡与秋菊兮。--《汉书·扬雄传》 楚子玉自为琼弁玉缨；组词：琼斝(一种玉质酒器)；琼窗(玉砌的窗户', '小学', '1'),
    ('瑞', 'ruì', '13', '王', '左右', NULL, '瑞 (形声。从玉,聑声)声。本义玉制的符信,作凭证用) 同本义 瑞,以玉为信也。--《说文》 掌玉瑞器之藏。--《周礼·典瑞》。注;符信也,人执以见曰瑞。” 成六瑞益王所用镇圭也；组词：瑞珪(天子赐的作为凭信的圭玉)；瑞节(玉节；瑞与节)；瑞令(符命)；瑞玉(玉制信物) 吉祥的事物 世间谓之圣王之瑞,为圣', '小学', '1'),
    ('瑟', 'sè', '13', '王', '上下', NULL, '瑟〈名〉 (指事。从珡,必声。本义 古代拨弦乐器。形似古琴,每弦一柱,但无征位) 瑟,庖牺所作弦乐也。；组词：调瑟(调准瑟弦的音)；琴瑟(琴与瑟) 古水名 瑟sè 1.拨弦乐器之一,一般有二十五根弦', '小学', '1'),
    ('瑰', 'guī', '13', '王', '左右', NULL, '瑰 (形声。从玉, 鬼声。本义 美玉; 美石) 同本义 瑰,攻瑰火齐也。--《说文》 赤玉攻瑰。--《史记·司马相如传》 何以赠之,琼瑰玉佩。--《诗·秦风·渭阳》；组词：瑰琼(美石；美玉)；瑰瓒(美玉与不纯的玉)；瑰室(玉石砌成的房子) 瑰 〈形〉 珍贵；珍奇 固瑰材而究奇,抗应龙之虹梁', '小学', '1'),
    ('璃', 'lí', '14', '王', '左右', NULL, '璃 (形声。从玉,离声。琉璃光洁如玉的石珠)--见玻璃” 璃(瓈)li 1. 2. 璃lí 1.见"琉璃"。 2.见"玻璃"。', '小学', '1'),
    ('璧', 'bì', '18', '玉', '上下', NULL, '璧 (形声。从玉,辟声。本义平而圆,中心有孔的玉) 同本义 璧,瑞玉环也。--《说文》 肉倍好谓之璧。--《尔雅·释器》。注肉边好孔。玉人,璧好三寸。” 璧者,方中圆外；组词：璧不可以防寒(比喻物品虽然贵重,但无实际的用处)；璧雍(璧堂', '小学', '1'),
    ('瓜', 'guā', '5', '瓜', NULL, NULL, '瓜 (象形。小篆字形,两边象瓜蔓,中间是果实,是藤上结瓜的形象。从瓜”的字,多与瓜果有关。草木蔓生植物名。种类很多,果实也称瓜)；组词：瓜田(种瓜的田)；瓜润(瓜受到灌溉后,长得更为丰美)；瓜练(冬瓜的瓤)；瓜瓤(瓜肉) 指形状如瓜的饰物、仪仗、兵器之类的', '小学', '1'),
    ('瓢', 'piáo', '16', '瓜', '左右', NULL, '瓢〈名〉 瓠的一种。也称葫芦” 瓢,蠡也。从瓠省,票声。--《说文》 瓢,瓠勺也。--《三苍》 一瓢饮。--《论语》；组词：瓢冠(瓜瓢形的僧帽)；瓢堂(简陋的堂室) 用葫芦干壳做成的勺 (把老熟的葫芦剖成两半所做成的勺子) 量词', '小学', '1'),
    ('瓣', 'bàn', '19', '瓜', '左中右', NULL, '瓣〈名〉 (形声。从瓜,辡声。本义瓜类的籽) 同本义 瓣,瓜中实也。--《说文》 瓠栖瓣。--《尔雅》。按,今曰瓜子仁。 水中有甘蔗,及梅李核瓜瓣；组词：橘瓣,瓜瓣 组成花冠的各片 植物的种子、果实或球茎可以分开的片状物 面如桃瓣,目若秋波', '小学', '1'),
    ('瓤', 'ráng', '22', '瓜', '左右', NULL, '瓤 (形声。从瓜,襄声)声。本义瓜类的肉) 同本义 瓤肉莹白如冰雪。--唐·白居易《荔枝图序》；组词：红瓤西瓜；南瓜瓤', '小学', '1'),
    ('瓦', 'wǎ', '4', '瓦', NULL, NULL, '瓦 (象形。象屋瓦俯仰相承的样子。瓦”是汉字的一个部首。本义已烧土器的总称) 同本义 瓦,土器已烧之总名。；组词：瓦大(瓦制的酒器)；瓦缶(口小腹大的瓦器)；瓦器(用泥土烧制的器皿)；瓦伶(陶瓦制的偶像)；瓦卮(陶制的盛酒器)；瓦豆(', '小学', '1'),
    ('瓮', 'wèng', '8', '瓦', '上下', NULL, '瓮 (形声。从瓦,公声。本义陶制盛器,小口大腹) 同本义 罋,汲缾也。--《说文》 瓮,瓶也。--《广雅·释器》 罋,瓶也。 按,瓶”是汲水器,不是今天的所谓瓶 抱畒而出灌；组词：瓮水(一瓮所装的水)；瓮问(瓮下)；瓮牖(以破瓮为窗,指贫寒之家)；瓮头春(酒瓮的口)；瓮天蠡海(自瓮窥天,以瓢测海', '小学', '1'),
    ('瓶', 'píng', '10', '瓦', '左右', NULL, '瓶 (形声。从瓦,并声。《说文》本从缶。缶,瓦器,即陶制器皿。本义汲水器) 古代比缶小的容器,用以汲水,也用以盛酒食 瓶,瓮也。(瓮,汲瓶也)。；组词：花瓶(插花用的瓶子)；瓷瓶；暖瓶；两瓶牛奶；喝了一瓶酒；瓶彝(祭器)；瓶落水(不”的隐语', '小学', '1'),
    ('瓷', 'cí', '10', '瓦', '上下', NULL, '瓷 (形声。从瓦,次声。本义用高岭土烧制成的质料。也指瓷器) 同本义 肴止于脯、醢、菜羹,器用瓷、漆。--司马光《训俭示康》；组词：瓷碗；细瓷；瓷枕；瓷仙(瓷器的人物造像)；瓷注(陶瓷茶壶) 瓷 严志和弯下腰,瓷着眼珠盯着地上老半天', '小学', '1'),
    ('甘', 'gān', '5', '甘', '半包围', NULL, '甘〈形〉 (会意兼指事。小篆从口,中间的一横象口中含的食物,能含在口中的食物往往是甜的、美的『字部首之一,从甘”的字往往与甜”、美味”有关。本义味美)；组词：甘肥(味美香浓的食品)；甘味(甘肥', '小学', '1'),
    ('甚', 'shèn', '9', '甘', '上下', NULL, '甚 疑问代词。什么 人(什么人) 为什么,怎么 甚 (会意。小篆字形,从甘,从匹。甘是快乐,匹,匹耦。沉溺于男女欢情。本义异常安乐)', '小学', '1'),
    ('甜', 'tián', '11', '甘', '左右', NULL, '甜 (会意。从甘,从舌。舌头能品尝甜味。本义味甘) 像糖或蜜的味道 甛,美也。--《说文》 甜,甘也。--《广雅》 草木不复抽,百味失苦甜。--韩愈《苦寒》；组词：甜物(甜的食品)；甜酒(甘甜的米酒)；甜雪(甘甜的雪水)；甜酸苦辣(指种种不同的味道)；甜香 比喻幸福；快乐 如甜沃沃(', '小学', '1'),
    ('生', 'shēng', '5', '生', NULL, NULL, '生 (会意。甲骨文字形,上面是初生的草木,下面是地面或土壤。生”是汉字部首之一。本义草木从土里生长出来;滋长)', '小学', '1'),
    ('甥', 'shēng', '12', '生', '左右', NULL, '甥 (形声。从男,生声。本义姐妹的儿子) 同本义 甥,谓我舅者,我谓之甥。--《说文》 舅谓姊妹之子曰甥。甥亦生也。出配他男而生,故其制字男傍作生也。--《释名》 青阳；组词：甥徒(外甥辈)；甥孙(姊妹之孙)；甥婿(外甥和女婿；外甥女婿)；甥舅(外甥和舅舅,亦指女婿和岳父) 古代为姑之子、舅之子', '小学', '1'),
    ('用', 'yòng', '5', '用', NULL, NULL, '用 (象形。甲骨文字形,象桶形。桶可用,故引申为用。本义使用,采用) 同本义 用,可施行也。', '小学', '1'),
    ('甩', 'shuǎi', '5', '用', NULL, NULL, '甩 扔;抛开 将手里的绢子一甩,向宝玉脸上甩来。--《红楼梦》 等我紧走慢赶地快要走近他时,他又噔噔地自个儿向前走了,一下又把我甩下几丈远。--《百合花》 脱', '小学', '1'),
    ('甫', 'fǔ', '7', '用', NULL, NULL, '甫〈名〉 (象形。甲骨文字形,象田中有菜苗之形。金文字形,变为从田父声的形声字。本义苗) 中国古代对男子的美称。多用于表字之后 甫,男子美称也。；组词：台甫(敬辞,旧时用于问人的表字) 通父”', '小学', '1'),
    ('田', 'tián', '5', '田', '半包围', NULL, '田〈动〉 (象形。小篆认为象阡陌纵横或沟浍四通的一块块农田。田”是汉字的一个部首,从田”的字多与田猎耕种有关。本义种田) 后作佃”。耕作 田,树谷曰田。；组词：田戍(屯田戍守)；田作(耕作)；田畜(耕种与畜牧)；田桑(种田和养蚕)；田农(农耕)；田种(耕种)；田穑(耕作) 打猎◇', '小学', '1'),
    ('由', 'yóu', '5', '田', '独体', NULL, '由 (《说文》无由”字,古字字形) 树木生新枝。亦泛指萌生 今在析木之津,犹将复由。--《左传》；组词：由蘖(树木枯槁或被砍伐后重发的枝条)；经,由 谁能出不由户?--《论语·雍也》 余在刑部狱,见死而由窦出者日三四人', '小学', '1'),
    ('甲', 'jiǎ', '5', '田', NULL, NULL, '甲 (象形。小篆字形,像草木生芽后所戴的种皮裂开的形象。本义种籽萌芽后所戴的种壳) 同本义 甲,东方之孟阳气萌动。从木,戴孚甲之象。；组词：莩甲；甲坼(甲宅', '小学', '1'),
    ('申', 'shēn', '5', '田', NULL, NULL, '申〈动〉 同本义;约束 申,束身也。--《说文》 约车申辕。--《淮南子·原道》。注束也。” 畏忌自申。--《汉书·韦元成传》。注言自约束也。” 勒兵申教令；组词：申束(约束) 舒展', '小学', '1'),
    ('电', 'diàn', '5', '田', NULL, NULL, '电 (形声。从雨,申声。本义闪电) 同本义 电,阴阳激耀也。--《说文》 电,电光也。--《五经通义》 三月癸酉,大雨震电。震,雷也,电,霆也。--《谷梁传·隐公九年》。疏霆者；组词：电火(闪电) 物理学名词 库仑)度量,从摩擦生电物体的吸引和排斥上可以观察到它的', '小学', '1'),
    ('男', 'nán', '7', '田', '上下', NULL, '男〈名〉 (会意。从田,从力。表示用力(一说指耒)在田间耕作。本义男人,与女”相对) 同本义 男,丈夫也。从男从力,言男用力于田也。；组词：男事(古指成年男子应尽的职责)；男夫(成年男子)；男圻(犹男服)；男教(对男子的教化)；男德(有德行的男子)；男权(男子', '小学', '1'),
    ('甸', 'diàn', '7', '田', '半包围', NULL, '甸 (会意。从田,包省声,田亦声。本义王田) 古时都城的郭外称郊,郊外称甸 甸,天子五百里地。；组词：甸地；甸邑；甸服(古制称离王城五百里的区域；泛指京城附近的地方)；甸畿(古代九畿之一', '小学', '1'),
    ('画', 'huà', '8', '田', '上下', NULL, '画 (会意兼指事。金文。上面是聿”,象以手执笔的样子,是笔”的本字;下面象画出的田界。整个字形,象人持笔画田界之形。本义划分,划分界线)；组词：画野分疆(划分疆域而治)；画土分贡(中国古代实行分封制,天子划分封地给诸侯,诸侯定期向天子朝贡)；画地(在地上画界线)', '小学', '1'),
    ('畅', 'chàng', '8', '田', '左右', NULL, '畅 (形声。从申,? 同本义 登台四望,三面皆畅。--《韩非子·说林上》 美在其中,而畅于四支。--《易·坤》；组词：通畅(运行无阻)；顺畅(顺利通畅,没有阻碍) 舒畅 旧国旧都,望之畅然', '小学', '1'),
    ('界', 'jiè', '9', '田', '上下', NULL, '界 (会意。从田,介声。本义边垂,边境) 同本义 界,境也。--《说文》。按,田畔也。 界,垂也。--《尔雅》 田边谓之界；组词：界分(分界处；地界)；界约(两国为明定疆界的界址而缔结的条约)；界贼(扰乱国境的盗贼)；界至(指边界) 界限；界jiè', '小学', '1'),
    ('畏', 'wèi', '9', '田', NULL, NULL, '畏 (会意。据甲骨文意思是鬼手拿杖打人,使人害怕。本义害怕) 同本义(对威势、威严的害怕) 畏,惧也。；组词：畏 畏wèi 1.怕,恐惧~惧', '小学', '1'),
    ('畔', 'pàn', '10', '田', '左右', NULL, '畔〈名〉 (形声。从田,半声。本义田界) 同本义 畔,田界也。--《说文》。段玉裁注田界者,田之竟处也。”按,一户百亩,百亩有界。 如农之有畔。--《左传》 修其疆畔；组词：畔岸(边际；范围限制)；畔涯(边际)；畔衅(边界争端)；畔际(界限；边际)；畔界(疆界) 被发行吟泽畔', '小学', '1'),
    ('留', 'liú', '10', '田', '上下', NULL, '留 (会意。从田,从乯,乯亦声。从田”,表示停留的地方。本义停留,留下) 同本义(停止在某一处所,含有不动的意思) 畱,止也。；组词：逗留( 留liú 1.停止在某处停~', '小学', '1'),
    ('畜', 'chù', '10', '田', '上下', NULL, '畜〈名〉 chu (会意。甲骨文字形) (表示牵引,下象出气的牛鼻形。牛鼻被牵着,说明是已被人类驯服豢养的家畜。本义家畜)；组词：家畜、牲畜、幼畜、畜牧(饲养的禽兽)；畜牲(指牛、马、羊、鸡、狗、猪等六畜) 畜 xu 饲养 畜鸟者则勿佛也', '小学', '1'),
    ('略', 'lüè', '11', '田', '左右', NULL, '略 (形声。从田,各声。本义封疆土地) 同本义 略,经略土地也。--《说文》 天子经略土地,定城国,制诸侯。--《左传·昭公七年》 巡视;巡行 公曰吾将略地焉；组词：略地(巡视侵边境)；略阵(巡视阵地) 通掠”', '小学', '1'),
    ('畦', 'qí', '11', '田', '左右', NULL, '畦〈名〉 (形声。从田,圭声。本义田畦。一说五十亩为畦) 同本义 畦,田五十亩曰畦。--《说文》 病于夏畦。--《孟子》。刘注;今俗以二十五亩为小畦,五十亩为大畦。” 一畦之间', '小学', '1'),
    ('番', 'fān', '12', '田', NULL, NULL, '番〈动〉fan (象形。小篆字形,上面象野兽的足掌和爪,下面的田”象兽足踩出的印子。1本义兽足。2更替,替代,轮流) 更替,轮值 顿兵一万,番代往来。；组词：番代(轮流更换)；番休(轮流休息)；番更(轮流巡夜) 用同翻” 番〈量〉 次,回 迭为三番', '小学', '1'),
    ('畴', 'chóu', '12', '田', '左右', NULL, '畴 (形声。从田,寿声。本义已耕作的田地) 同本义 畴,耕地也。--《苍颉篇》 畴,耕治之田也。象耕屈之形。--《说文》 取我田畴而伍之。--《左传·襄公三十年》 田畴荒芜；组词：田畴(田地)；畴陇(畦田；田亩) 特指种麻的田 同类,类别◇作俦” 十日不食,无畴类尽死矣', '小学', '1'),
    ('畸', 'jī', '13', '田', '左右', NULL, '畸 (形声。从田,奇声。本义零片的田地) 同本义 畸,残田也。--《说文》。段注残田者,余田不整齐者也。” 道千乘之国。--《论语·学而》。集解三百一十六里有畸。”；组词：畸余(未被侵占的残余土地)；畸零(小块零散土地) 数的零头；余数 古称军队阵形的一翼 畸 不整齐的,不正规的 墨子有见于', '小学', '1'),
    ('疆', 'jiāng', '19', '田', '左右', NULL, '疆 (指事。从土,从弓,从畺。从弓”,表示以弓记步,即以弓来丈量土地。本义田界) 同本义 畺,界也。从田,三其界画也。指事。；组词：疆陇(田界)；疆畛(地界；界限)；疆畎(指田地,垄亩沟渠) 引申为国界、边界 出疆必请', '小学', '1'),
    ('疏', 'shū', '12', '疋', '左右', NULL, '疏 (会意。疋”有通的意思。本义疏导,开通) 同本义 疏,通也。--《说文》。疋者,破包足动也。孕则塞,生则通。因转注为开通分远之谊,俗字作痚,故汉疏广之后,隐其半为束氏；组词：疏决(疏浚；开通)；疏漏(漏水)；疏源(疏通水源)；疏瀹(疏浚,疏通)；疏辟(疏通开浚)；疏涤(疏浚清理；疏通清除)；疏', '小学', '1'),
    ('疑', 'yí', '14', '疋', NULL, NULL, '疑 (形声。小篆字形。从子止匕,矢声。止,不通。子,幼子。幼子多惑。本义怀疑) 同本义 疑,惑也。；组词：疑思(疑虑)；疑影(怀疑；疑团)；疑猜(怀疑猜测)；疑龊(疑惑)；疑狐(怀疑；狐疑)；疑念(因怀疑而思索 疑yí 1.猜', '小学', '1'),
    ('疗', 'liáo', '7', '疒', NULL, NULL, '疗 (形声。从疒,表示疾病有关,尞声。本义医治) 同本义(含有对症下药之意) 疗,治也。--《广雅·释诂》 凡疗疡,以五毒攻之。--《周礼·天官·疡医》 不可救疗；组词：疗治(治疗,调治)；疗疾(疗病', '小学', '1'),
    ('疙', 'gē', '8', '疒', NULL, NULL, '疙 如疙蹅蹅(象声词。敲击器物的声音);疙皱(蹙眉。表示烦恼、发愁);疙颤颤(抖动摇晃的样子;颤巍巍);疙秃(头上突起的疮疖) 疙gē 1皮肤或肌肉上起的硬块腿上起了个~瘩', '小学', '1'),
    ('疚', 'jiù', '8', '疒', NULL, NULL, '疚 (形声。从疒,表示与疾病有关,久声。本义久病) 同本义 无饥馑疾疚祸罪之殃。--《韩非子》；组词：疚病(疾病)；疚疾(疾病)；疚头怪脑(丑头怪脸的样子) 贫穷 维昔之富不如时,维今之疚不如兹', '小学', '1'),
    ('疟', 'nüè', '8', '疒', NULL, NULL, '疟 nue (形声。从疒,虐声。本义病名,即疟疾) 同本义 疟者,风寒之气不常也。--《素问·疟论》 许悼公疟。--《左传·昭公十九年》 疟,寒热休作。--《说文》 疟,酷虐也；组词：疟病(疟疾)；疟患(疟病的祸患)；疟寒(疟病)；疟疠(疟疾；疟疫) 通虐”', '小学', '1'),
    ('疤', 'bā', '9', '疒', NULL, NULL, '疤〈名〉 (形声。从疒,巴声。从疒”表示与疾病有关。本义疮疤) 同本义 器物上像疤的痕迹 疤瘌,疤拉 同疤” 疤瘌眼 疤 bā 1疮口或伤口长好后留下的痕迹伤~', '小学', '1'),
    ('疫', 'yì', '9', '疒', NULL, NULL, '疫 (形声。从疒,役省声。本义瘟役) 同本义。急性传染病流行的通称 疫,民皆疾也。--《说文》 疫,病流行也。--《字林》 氐为天根生疫。--《史记·天官书》 鬻棺者欲岁之疫；组词：时疫；疫死(因染患流行的传染病而死)；疫旱(传染病与旱灾)；疫症(疫病)；疫疠(瘟疫)；疫疾(疫病；疫病流行) 疫鬼,古', '小学', '1'),
    ('疮', 'chuāng', '9', '疒', NULL, NULL, '疮 (形声。从疒,仓声。本义皮肤上肿烂溃疡的病) 痈、瘫、疽、疖等的总称 疮,疮痍也。--《玉篇》 所恶成疮痏。--张衡《西京赋》。薛注疮痏,谓褊也。” 医得眼前疮,剜却心头肉；组词：疮毒(诸疮毒肿)；疮疹(指疹子)；疮疾(泛指疥癣痈疽等皮肤及外科疾患) 伤口；外伤', '小学', '1'),
    ('疯', 'fēng', '9', '疒', NULL, NULL, '疯 (形声。 从疒, 表示与疾病有关。风声。 本义头风病) 同本义 疯, 头病。-- 《集韵》 瘫痪 他那半肢疯,半个身子简直不能动。 -- 茅盾 《子夜》 疯 神经错乱', '小学', '1'),
    ('疲', 'pí', '10', '疒', NULL, NULL, '疲〈形〉 (形声。从疒,皮声。病字旁念 档芿杮L据甲骨据甲骨文,象人躺在床上害病的样子。以它作形旁的字一般与疾病有关。本义疲乏;困倦)；组词：筋疲力尽；疲敝(疲乏困苦)；疲玩(疲塌轻忽)；疲曳(疲弱困顿,比喻年老)；疲钝(疲倦困顿)；疲顽(疲困倦怠)；疲匮(疲累', '小学', '1'),
    ('疹', 'zhěn', '10', '疒', NULL, NULL, '疹 皮肤上起的小颗粒,通常是红色,多由皮肤表层发炎浸润而起湿~。麻~(亦称疹子”)。风~。丘~。疱~。 疹zhěn皮肤上出现小颗粒(针尖至黄豆大)的一种病变,一般为红色丘~。疱~', '小学', '1'),
    ('疼', 'téng', '10', '疒', NULL, NULL, '疼〈动〉 (形声。从疒,冬声。本义痛) 同本义 (仅表示身体上的难受) 疼,痛也。--《广雅》 寒胜其热,则骨疼肉枯。--《灵枢经·刺节真邪》 丝细缲多女手疼,扎扎千声不盈尺；组词：疼痒(痛痒) 疼爱 满庭花落地,则有谁疼?--孟称舜《桃花人面》 又如疼热(疼爱,爱护)；疼顾(关心照顾) 疼téng', '小学', '1'),
    ('疾', 'jí', '10', '疒', NULL, NULL, '疾 (会意。甲骨文字形,从大(人),从矢,字形象人腋下中箭。段玉裁《说文解字注》矢能伤人,矢之去甚速,故从矢会意。”本义受兵伤。泛指疾病) 轻微的叫疾 疾,病也。', '小学', '1'),
    ('病', 'bìng', '10', '疒', NULL, NULL, '病 (形声。疒形丙声。本义上古时指重病) 同本义 病,疾加也。--《说文》 疾病外内皆埽。--《仪礼·既夕礼》。注疾甚曰病。” 坎为心病。--《易·说卦》 疾病而立之；组词：病革(病势危急将死)；病亟(病革) 生理上或心理上不正常的状态 君之病在肌肤', '小学', '1'),
    ('症', 'zhèng', '10', '疒', NULL, NULL, '症 腹中结块的病 脉沉重而中散者,因寒食成症。--晋·王叔和《脉经》 又如病症(病征。按病征的 症”,在古时只作譪”。症是近代的俗字);症坚(症结);症痼(腹中积久未消的痞块)；组词：病症(病征', '小学', '1'),
    ('痊', 'quán', '11', '疒', NULL, NULL, '痊〈动> 病除;病愈 今予病少痊,予又且复游于六合之外。--《庄子》 又如痊除,痊疴,痊差,痊较(痊愈);痊瘥;痊济,痊疗(病愈) 痊quán病好了,完全恢复健康~愈。', '小学', '1'),
    ('痒', 'yǎng', '11', '疒', NULL, NULL, '痒 (形声。从疒,养声。本义一种皮肤不适、引人欲搔的感觉) 同本义 形容某些难以抑制的强烈愿望 花前技痒又成诗。--宋·陆游《还东》；组词：痒滋滋(形容按捺不下某种兴奋的情绪)；痒酥酥(形容产生某种难以压抑的强烈愿望；形容轻松愉快的感觉)；痒处(指心里怀的强烈', '小学', '1'),
    ('痕', 'hén', '11', '疒', NULL, NULL, '痕〈名〉 (形声。从疒,表示与疾病有关,艮声。本义疮伤痊愈后留下的疤) 同本义 痕,胝瘢也。；组词：痕瑕(褊,斑点)；痕挞(伤痕)；痕瘕(疤痕', '小学', '1'),
    ('痘', 'dòu', '12', '疒', NULL, NULL, '痘 (形声。从疒,豆声。本义病名。俗称天花,也叫痘疮或天疮) 同本义 (出痘的病人);痘神(旧时所谓痘疮之神);痘瘢(人患痘疮后留下的褊) 指痘苗', '小学', '1'),
    ('痛', 'tòng', '12', '疒', NULL, NULL, '痛 (形声。从疒,甬声。疒,与疾病有关。本义疼痛) 同本义 痛,病也。--《说文》 坎为耳痛。--《易·说卦》 桓侯体痛。--《韩非子·喻老》 身体痛；组词：痛不欲生；痛定思痛；创巨痛深；累得酸痛；痛毒(痛苦,残酷)；痛疾(病痛)；痛脚(疼痛的脚)；痛煞(疼痛之甚)；痛痹(病名', '小学', '1'),
    ('痢', 'lì', '12', '疒', NULL, NULL, '痢〈名〉 (形声。从疒,表示与疾病有关,利声。本义病名。即痢疾”) 同本义 凡山水甚强寒,饮之皆令人痢。--曹操《魏武令》 又如痢症(痢疾) 痢( 2.鬁)lì 1.', '小学', '1'),
    ('痪', 'huàn', '12', '疒', NULL, NULL, '痪 瘫痪 痪,瘫痪,四体麻痹不仁,皆因风寒暑湿所致。--《正字通》 痪huàn', '小学', '1'),
    ('痰', 'tán', '13', '疒', NULL, NULL, '痰〈名〉 呼吸道分泌而由口、鼻腔排出的粘液 痰tán气管或支气管粘膜分泌的粘稠液体~液。禁止随地吐~。', '小学', '1'),
    ('痴', 'chī', '13', '疒', NULL, NULL, '痴 (形声。从疒,疑声。本义不聪慧;迟钝) 同本义 皏,不慧也。字俗作痴。--《说文》 又如痴哑(痴呆喑哑);痴呆呆(傻乎乎) 疯癫,癫狂 此人素有痴名；组词：痴哑(痴呆喑哑)；痴呆呆(傻乎乎) 疯癫,癫狂 此人素有痴名', '小学', '1'),
    ('痹', 'bì', '13', '疒', NULL, NULL, '痹 (形声。从疒),畀声。本义痹症。中医指由风、寒、湿等引起的肢体疼痛或麻木的病) 同本义 痹,湿病也。；组词：痹厥(神经系病', '小学', '1'),
    ('瘟', 'wēn', '14', '疒', NULL, NULL, '瘟 (形声。从疒,昷声。本义瘟疫) 同本义 前日被瘟官打的棒疮...好不疼痛!--清·张南庄《何典》；组词：瘟官(害人的官)；瘟瘴(瘟疫)；瘟瘴(即瘟疫)；瘟君(又叫瘟鬼,瘟神爷', '小学', '1'),
    ('瘤', 'liú', '15', '疒', NULL, NULL, '瘤 瘤子,身体组织增生形成的赘生物,多由刺激或微生物寄生而起。分癌瘤、肉瘤、淋巴瘤、血管瘤、脂瘤和骨瘤等 瘤,肿也。从疒,留声。；组词：瘤牛；瘤赘(体表或筋骨间增生的肉疙瘩) 树木干、根外皮隆起的块状物 瘤牛 瘤胃 瘤liú生物体的局部组织异常增殖,所形成', '小学', '1'),
    ('瘦', 'shòu', '14', '疒', NULL, NULL, '瘦 (形声。从疒,叟声。从疒,表明与疾病有关。本义肌肉不丰满) 同本义 瘦,舑也。--《说文》。 毁瘠羸瘦。--《孝经》 久则瘦舑腐败。--《周礼·廛人》注 有书生避雨檐下；组词：瘦怯(瘦弱；瘦削)；瘦怯怯(瘦弱的样子)；瘦亭亭(亦作瘦棱楼”', '小学', '1'),
    ('瘩', 'dá', '14', '疒', NULL, NULL, '瘩背 瘩 dá见"瘩背"。 【瘩背】病名。中医称生在背部的痈。', '小学', '1'),
    ('瘪', 'biě', '15', '疒', NULL, NULL, '瘪 用同憋”。闷 既然要钱,为什么不说明,叫我瘪了两三个月呢?--《官场现形记》 瘪三 瘪 biē又见biě 【瘪三】。乞讨或偷窃为生的游民的鄙称。 瘪 biě物体表面凹下去', '小学', '1'),
    ('瘫', 'tān', '15', '疒', NULL, NULL, '瘫〈名〉 (形声。从疒,难声。疒,与疾病有关。本义瘫痪,指肌体不能随意运动,也比喻机构不能正常运转) 同本义 (谓躺卧);瘫倒(倒下难以动弹) 瘫(癱)tān', '小学', '1'),
    ('瘸', 'qué', '16', '疒', NULL, NULL, '瘸〈形〉 本谓手或脚偏废的病◇特指腿脚有病,行步不平衡 瘸 〈动〉 变成残废 瘸qué腿脚有病,走路不平衡他是~子。一~一拐地走路。', '小学', '1'),
    ('瘾', 'yǐn', '16', '疒', NULL, NULL, '瘾 (形声。从疒,隐声。本义不良的癖好) 同本义 洋烟瘾发之人,涕洢交流,遍身瘫软。--曾国藩《劝诫营官》；组词：瘾民(吸鸦片成瘾的人)；烟瘾；酒瘾 泛指浓厚的兴趣 瘾(癮)yǐn 1.特别深的嗜好烟~', '小学', '1'),
    ('癌', 'ái', '17', '疒', NULL, NULL, '癌 发生于上皮组织的恶性肿瘤 。如肝癌、胃癌、食道癌、血癌(白血病)、肺癌、喉癌、子宫癌、肠癌 癌ái 1.来源于上皮组织的恶性肿瘤胃~。乳腺~。皮肤~。 2.一般人所说的"癌"', '小学', '1'),
    ('癞', 'lài', '18', '疒', NULL, NULL, '癞痢 la 癞 lai (形声。从疒,表示与疾病有关,赖声。本义病名。即麻疯”) 同疬”。麻风病 癞 坏;低劣 脏 但凡客商在路,早晚安歇,有两件事免不得,吃癞饭,睡死人床。', '小学', '1'),
    ('癣', 'xuǎn', '19', '疒', NULL, NULL, '癣 由真菌(尤其是发癣菌属和小孢子菌属)所引起的人类和家畜皮肤、毛发或趾(指)甲的接触性传染病,特征为皮肤有环形脱色斑,覆以疱疹及鳞屑 其中是多豪鱼...可以已白癣。；组词：癣疥(皮肤病', '小学', '1'),
    ('登', 'dēng', '12', '癶', '上下', NULL, '登 (象形。本义上车) 同本义 登,上车也。--《说文》 登,陞也。--《尔雅》 登车则有光矣。--《礼记·玉藻》 登轼而望之。--《左传·庄公十年》 升,上；组词：捷足先登；登宝(登基；帝王即位)；登筵(登上筵席)；登平(上升)；登仙(声名 登 dēng 1由低处到高处(多指人步行)', '小学', '1'),
    ('白', 'bái', '5', '白', NULL, NULL, '白 (象形。甲骨文字形,象日光上下射之形,太阳之明为白,从白”的字多与光亮、白色有关。本义白颜色)', '小学', '1'),
    ('百', 'bǎi', '6', '白', '上下', NULL, '百 (会意。从一,从白。白”假借为百”。本义数词) 十个十。一百,100 百,十十也。--《说文》 律中百钟。--《淮南子·时则》 虽人有百手,手有百指,不能指其一端；组词：百辆之迎(用隆重仪式迎娶新妇)；百日(一百天；人死后的一百天,请僧道诵经或作道场)；百户(一百户人家；统兵百人之官) 概', '小学', '1'),
    ('皂', 'zào', '7', '白', '上下', NULL, '皂 皂斗的略称(指栎实、柞实等),其壳斗煮汁,可以染黑,本作皁”,后作皂” 一日山林,其植物宜皂物。；组词：皂物(柞栗之类', '小学', '1'),
    ('的', 'de', '8', '白', '左右', NULL, '的 用在定语后,表示词与词或短语之间的修饰关系 用在定语后,表示定语和中心词之间的领属关系 pron. 附着在词或短语之后,构成的”字结构,代替所指的人或物。如卖菜的;吃的 助词', '小学', '1'),
    ('皆', 'jiē', '9', '白', '上下', NULL, '皆〈副〉 (会意。从比,从白。从比”,有并”的意思。本义都,全) 同本义 皆,俱词也。--《说文》 百堵皆兴。 皆死皆殡。--《左传·哀公十一年》 予及汝皆亡', '小学', '1'),
    ('皇', 'huáng', '9', '白', '上下', NULL, '皇 (象形。金文,象灯火辉煌形。上面的三点,象灯光参差上出之形;中间的部分象灯缸;下面的土”是灯柱。皇”即煌”的古字。本义灯火辉煌)；组词：皇祜(大福)；皇业(大业；帝王的事业)；皇道(大道)；皇竹(大竹名) 美好 皇,美也', '小学', '1'),
    ('皮', 'pí', '5', '皮', NULL, NULL, '皮〈动〉 (会意。金文字形上面是个口,表示兽的头;一竖表示身体;右边半圆表示已被揭起的皮;右下表手。皮”是汉字部首之一。本义用手剥兽皮)；组词：皮面 酥脆的东西变韧 皮 〈名〉 兽皮 孤执皮帛', '小学', '1'),
    ('皱', 'zhòu', '10', '皮', '左右', NULL, '皱 (形声。从皮,刍声。本义皮肤因松弛而起的纹路) 同本义 莫道韶华镇长在,发白面皱专相待。--唐·李贺《嘲少年》 面皮嘴唇烧的紫绛皱裂。；组词：皱皮(皮肤上的皱纹)；皱文(皱纹) 衣、物等经折叠而显出痕迹 前低划开阔,烂漫堆众皱', '小学', '1'),
    ('皿', 'mǐn', '5', '皿', NULL, NULL, '皿 (象形。小篆字形,象碗、盆之类的食器。本义器皿) 同本义。泛指碗碟杯盘一类饮食用具 皿,饭器之用器也。；组词：皿金(金属器皿)；皿卷(清代科举,顺天乡试监生的试卷)；皿器(盛物用具的统称) 皿mǐn', '小学', '1'),
    ('盅', 'zhōng', '9', '皿', '上下', NULL, '盅 (形声。从皿,中声。本义杯类;没有把的小杯子) 同本义 又取出三个茶盅,倒了三碗茶送了上来。', '小学', '1'),
    ('盆', 'pén', '9', '皿', '上下', NULL, '盆〈名〉 (形声。从皿,分声。皿,泛指盘碗一类器具。本义盛东西或洗涤用的器皿。通常为圆形,口大底小,比盘深)；组词：炭盆(烧木炭的火盆)；脸盆；大铜盆(一种较浅的口大底小的盛器,多为圆形)；盆吊(把囚犯倒吊处死的一种酷刑)；盆冤(覆盆之', '小学', '1'),
    ('盈', 'yíng', '9', '皿', '上下', NULL, '盈 (会意。从皿。《说文》满器也。”) 同本义 盈,满器也。--《说文》 盈莫不有也。--《墨子经》 盈,满也。--《广雅》 不盈。--《易·坎》。虞注溢也。” 乐主其盈；组词：盈盈(充盈、充积的样子)；车马盈门；充盈(充满)；盈抱(满杯)；盈科(水多满坑坎)；盈衍(充斥；充满)；盈庭(亦作盈廷', '小学', '1'),
    ('益', 'yì', '10', '皿', '上下', NULL, '益 (会意。小篆字形。象器皿中有水漫出。从皿,从水。水”已隶变。本义溢”的本字。水漫出)；组词：增益；延年益寿；益甲(增兵)；益兵(增加兵力)；益封(增加封邑)；益军(益兵)；益损( 益yì 1.好处,有好处的利~', '小学', '1'),
    ('盏', 'zhǎn', '10', '皿', '上下', NULL, '盏 (形声。从皿,戔声。从皿,表示与器皿有关。本义浅而小的杯子) 同本义 横飞玉盏家山晓,远蹀金珂塞草春。--唐·韩愈《酬振武胡十二丈》诗；组词：把盏(端着酒杯敬客)；盏斝(泛指酒杯) 盏 酒、茶或灯的计量单位 那妇人拿起一盏茶来,把帕子去茶盅口边一抹,双手递与和尚', '小学', '1'),
    ('盐', 'yán', '10', '皿', '上下', NULL, '盐 (形声。从卤,监声。本义食盐) 同本义 若作和羹,尔惟盐梅。--《书·说命下》 鲁盐漆丝。--《史记·货殖列传》；组词：盐酱口(说不吉利的话,且得到应验)；盐枭(私贩食盐的人)；盐斤(宋代官盐以百斤、千斤为计算单位,故称盐”为盐斤”)；盐捕', '小学', '1'),
    ('监', 'jiān', '10', '皿', NULL, NULL, '监 (会意。甲骨文字形,左边是一个人睁大眼睛在往下看(臣,竖目),右边是个器皿。金文又在器皿上加一小横,表示器中有水。古人以水为镜,监”就是一个人弯着腰,睁大眼睛', '小学', '1'),
    ('盒', 'hé', '11', '皿', '上下', NULL, '盒 (形声。从皿,合声。从皿”,表示与器皿有关。本义底盖相合的盛器) 同本义 合,器名。--《广韵》 合子,盛物器。--《正韵》；组词：盒仗(礼盒挑子)；盒礼(盒装的礼物)；盒菜(盒子包装的副食品)；盒担(盒形盛物器,叠合为两组,用扁担挑起输送) 盒hé底', '小学', '1'),
    ('盔', 'kuī', '11', '皿', '上下', NULL, '盔〈名〉 (形声。从皿,灰声。本义钵) 同本义。盂一类容器 盔,盔器,盂属也。--《龙龛手鉴》 首铠。古代战士用以保护头部的帽子。也指消防人员或矿工带的金属帽子 三通鼓罢；组词：盔缨(头盔上的丝织饰物) 盔kuī 1.作战时用于保护头部的帽子,多用金属制成头~', '小学', '1'),
    ('盖', 'gài', '11', '皿', '上下', NULL, '盖 (形声。从苃,盍声。本义用芦苇或茅草编成的覆盖物) 苫,用茅草编成的遮盖物,可以蔽体或覆屋顶 李巡曰编菅茅以覆屋曰苫。；组词：苫盖(茅草覆盖物) 雨伞 今王公贵人处于重屋之下,出则乘舆,风则袭裘,雨则御盖,凡所以虑患之具莫不备至', '小学', '1'),
    ('盗', 'dào', '11', '皿', '上下', NULL, '眎 (会意。甲骨文字形,意思是看到人家的器皿就会贪婪地流口涎,存心不善。本义盗窃,偷东西)；组词：偷盗(偷窃)；盗跖下惠(跖和柳下惠,两人虽是兄弟,但跖被诬为大盗,而柳下惠却被视为圣人)；盗名(偷取美名) 抢 盗 dà', '小学', '1'),
    ('盘', 'pán', '11', '皿', '上下', NULL, '盘 (形声。从皿,般声。皿,盘碗一类器具。本义盘子,浅而敞口的盛物器) 同本义 及日中则如盘盂。；组词：盘羞(盘盛的食品)；冷盘(盛在盘子里的凉菜)；茶盘(放茶壶茶杯的盘子)；盘儿(脸盘儿)；盘器(盘类器皿)；盘担(内装盘馔', '小学', '1'),
    ('盛', 'shèng', '11', '皿', '上下', NULL, '盛 cheng 放在祭器里的谷物 盛,黍稷在器中以祀者也。--《说文》 天子亲耕以共粢盛。--《谷梁传·桓公十四年》。注黍稷曰粢,在器曰盛。”；组词：粢盛 器皿,如杯、碗之类 旨酒一盛兮', '小学', '1'),
    ('盟', 'méng', '13', '皿', '上下', NULL, '盟 (会意。甲骨文字形,下面象个盘盂,中间放着牛耳。古代盟会要割牲歃血,主盟人手执牛耳,掘穴埋牲。本义在神前发誓结盟)', '小学', '1'),
    ('目', 'mù', '5', '目', '全包围', NULL, '目 (象形。甲骨文和小篆字形。象眼睛形,外边轮廓象眼眶,里面象瞳孔。小篆处理为线条。先秦时期多用目”,两汉以后,用眼逐渐多起来。目”具有书面语色彩。本义眼睛)；组词：目 目mù 1.眼睛~不暇接', '小学', '1'),
    ('盯', 'dīng', '7', '目', '左右', NULL, '盯 (形声。从目,丁声。本义注视) 同本义 紧跟着不放松 盯 dīng集中视力看。 【盯梢】见【钉梢】。 盯chéng 1.见"盯"、"枚"。', '小学', '1'),
    ('盲', 'máng', '8', '目', '上下', NULL, '盲 (形声。从目,亡声。本义眼睛失明) 同本义 盲,目无牟子也。--《说文》 目不能决黑白之色则谓之盲。--《韩非子·解老》 目不见青黄曰盲。--《论衡·别通》 五色令人目盲；组词：盲冥(眼睛失明)；盲废(因丧失视力而致残)；盲聋(眼瞎耳聋)；盲聩(眼瞎耳聋)；盲妹,盲女(旧时多指以卖唱为生的失明女子', '小学', '1'),
    ('直', 'zhí', '8', '目', '上中下', NULL, '直 (会意。小篆字形,从l,从十,从目。徐锴l,隐也,今十目所见是直也。”本义不弯曲,与枉”、曲”相对)；组词：直线；直路；笔直；直迫(直直愎愎 直zhí 1.端正,不弯折,跟"曲"相对坐~', '小学', '1'),
    ('相', 'xiāng', '9', '目', '左右', NULL, '相 交互;互相 故曰教学相长也。--《礼记·学记》 民至老死不相往来。--《老子·小国寡民》 生当复来归,死当长相思。--汉·苏武《留别妻》 当国者相见；组词：相 相xiāng 1.交互,互往来~关', '小学', '1'),
    ('盹', 'dǔn', '9', '目', '左右', NULL, '盹 (形声。从目,屯声。本义闭目小睡) 同本义 盹 dǔn短时间的入睡。 盹zhūn 1.见"盹盹"。', '小学', '1'),
    ('盼', 'pàn', '9', '目', '左右', NULL, '盼〈形〉 (形声。从目,分声。本义眼睛黑白分明的样子) 同本义。喻美目流转 盼,目黑白分也。；组词：盼刀(旧时相术用语', '小学', '1'),
    ('盾', 'dùn', '9', '目', NULL, NULL, '盾 (象形。小篆字形。上面象盾形,下面是目”,表示以盾蔽目(身体)。本义盾牌) 同本义 掌五兵五盾。；组词：盾威(指军心士气)；盾矛(矛盾)；盾橹(古代防护兵器)；盾鼻(盾牌的把手)；盾墨(盾鼻上磨墨) 盾形的物品 盾牌 比喻推', '小学', '1'),
    ('省', 'shěng', '9', '目', '上下', NULL, '省 sheng (会意。从眉省,从屮。甲骨文和小篆字形,象眼睛观察草。本义察看) 王宫禁署,禁中 禁台省中,连闼对门。--左思《魏都赋》；组词：省中(宫禁之中)；省内(宫禁之内) 官署名称 投词院直至省,将冤屈叫几声,诉出咱这实情', '小学', '1'),
    ('眉', 'méi', '9', '目', NULL, NULL, '眉 (象形。甲骨文,小篆字形。象目上毛形。本义眉毛) 眼上方的弓或嵴,亦指生长在这条嵴上的眉毛 眉,目上毛也。；组词：眉心(双眉之间)；眉间广尺(两眉间隔宽有一尺,表示人的相貌奇特)；眉泉(眉头)；眉寸(双眉之间)；眉下添眉(比喻重复、多', '小学', '1'),
    ('看', 'kàn', '9', '目', '上下', NULL, '看〈动〉 守护 原是一个老军看管。--《水浒全传》 又如看坡(守护庄稼);看陵(看守皇帝陵墓);看养(守护,照料);看钱奴(守财奴);看鸡(孵鸡);看肚兜铜钱(仅有的几个钱)；组词：看坡(守护庄稼)；看陵(看守皇帝陵墓)；看养(守护,照料)；看钱奴(守财奴)；看鸡(孵鸡)；看肚兜铜钱(仅有的几个钱)', '小学', '1'),
    ('真', 'zhēn', '10', '目', '上下', NULL, '真 (会意。小篆字形,从华,从目,从乚,从八。《说文》仙人变形而登天也。”匕,变化。目,眼睛。乚,隐藏。八,乘载的工具。本义道家称存养本性或修真得道的人为真人)；组词：真人府(道人居住的地方)；真仙(仙人)；真君(道教对神仙的尊称)；真味(真实的意旨或意味) 本性；本原 真zhēn 1.', '小学', '1'),
    ('眠', 'mián', '10', '目', '左右', NULL, '眠 (形声。从目,民声。本义闭上眼睛) 同本义 眠,寐也。--《玉篇》 吾子有疾,虽不能省视,而竟夕不眠。--《后汉书·第五伦传》 致命于帝,然后得眠些；组词：不眠之夜；失眠(夜间睡不着)；安眠(安稳地熟睡)；眠食(睡眠和饮食) 横卧；平放 眠琴绿阴,上有飞瀑', '小学', '1'),
    ('眨', 'zhǎ', '9', '目', '左右', NULL, '眨 (形声。从目,乏声。本义眼睛一闭一开) 同本义 沼似颇黎镜,当中见鱼眨。--唐·皮日休《二游诗》；组词：眨眨(眼光闪烁不定的样子)；眨眉(眨眼)；眨闪(眼睛开合闪动)；眨动(眼睑开合) 比喻时间极短 眨zhǎ眼睛很快地开闭~', '小学', '1'),
    ('眯', 'mī', '11', '目', '左右', NULL, '眯 眼皮微微合拢 眯 通迷”。迷乱 眯 (形声。从目,米声。(譭??)本义灰沙等物入眼)', '小学', '1'),
    ('眶', 'kuàng', '11', '目', '左右', NULL, '眶〈名〉 眼眶 涣余涕之盈眶。--柳宗元《吊屈原文》 又如热泪盈眶;夺眶而出 眶kuàng眼圈,眼的四周眼~子。泪水夺~而出。', '小学', '1'),
    ('眷', 'juàn', '11', '目', '上下', NULL, '眷 (形声。本义回头看) 同本义 眷,顾也。--《说文》 乃卷西顾。--《诗·大雅·皇矣》；组词：眷言(回顾的样子', '小学', '1'),
    ('眼', 'yǎn', '11', '目', '左右', NULL, '眼 (形声。从目,艮声。本义眼珠) 同本义 眼,目也。--《说文》 眼,限也。瞳子限限而出也。--《释名》 巽为多白眼。--《易·说卦》 比干剖心,子胥抉眼,忠之祸也；组词：眼馋肚饱(贪得无厌；不知足)；眼意心期(眼中传意,心中期待)；眼黄地黑(心怀叵测,见财起意)；眼空四海(目中无人,妄自尊', '小学', '1'),
    ('着', 'zhe', '11', '目', NULL, NULL, '着 zhao (著的俗字) 放置 文成示温,温以着坐处。--晋·陶潜《晋故西征大将军长史孟府君传》；组词：着盐(搁盐；炒菜放盐)；板上着碗 安顿 更有南堂堪着客,不忧门外故人车', '小学', '1'),
    ('睁', 'zhēng', '11', '目', '左右', NULL, '睁 (形声。从目,争声。本义张开眼睛) 同本义 武行者睁着双眼喝道你这厮好不晓道理。”--《水浒传》；组词：睁眼苫眉(装模作样)；睁着眼做,合着眼受(比喻自作自受,心甘情愿)；睁着眼跳黄河(比喻进退维谷,走上绝路) 看,望；瞪', '小学', '1'),
    ('睛', 'jīng', '13', '目', '左右', NULL, '睛 (形声。从目,青声。本义眼珠) 同本义 虽达视犹不能见其睛。--《淮南子·主术》 又如定睛一看;画龙点睛;火眼金睛 眼睛 那行者睁睛看处,真个的背在身上；组词：定睛一看；画龙点睛；火眼金睛 眼睛 那行者睁睛看处,真个的背在身上', '小学', '1'),
    ('睡', 'shuì', '13', '目', '左右', NULL, '睡 (会意。从目,垂声。指眼睑下垂,打瞌睡。本义坐着打瞌睡) 同本义 睡,坐寐也。--《说文》 读书欲睡,引锥自剌其股。--《战国策·秦策》 孝公既见卫鞅,语事良久,孝公时时睡；组词：睡晌觉(睡午觉)；睡寐(瞌睡；打盹) 童微伺其睡,以缚背刃,力上下,得绝,因取刃杀之', '小学', '1'),
    ('督', 'dū', '13', '目', '上下', NULL, '督 (形声。从目,叔声。本义察看督促,监督) 同本义 督,察也。--《说文》 禁督逆祀命者。--《周礼·春官·大祝》 植中枢,立督虑。--《太玄卷一周》 行督责之术；组词：督邮(官员', '小学', '1'),
    ('睦', 'mù', '13', '目', '左右', NULL, '睦 (形声。从目,坴声。本义和好,亲近) 同本义 睦,目顺也。--《说文》 讲信修睦。--《礼记·礼运》。注皆训亲。” 睦于父母之堂。--《礼记·坊记》 则百姓亲睦；组词：睦友(和睦友爱)；睦睦(和睦,亲密)；睦亲(对宗族和睦,对外亲友好)；睦族(和睦亲族) 调和 通穆” 睦,敬和也', '小学', '1'),
    ('睬', 'cǎi', '13', '目', '左右', NULL, '睬 理睬,答理 不是远老泰山为人忒歹,亲女婿昂然不睬。--王实甫《破窑记》 王太太不倸,坐着不动。--《儒林外史》 又如不睬;不要睬他 睬 cǎi理会;答理不理不~。', '小学', '1'),
    ('睹', 'dǔ', '13', '目', '左右', NULL, '睹 (形声。从目,者声。本义见,看见) 同本义 睹,见也。--《说文》 圣人作而万物睹。--《易·文言传》 今我睹子之难穷也。--《庄子·秋水》 云霞明灭或可睹；组词：有目共睹；睹睐(看见；发现)；睹闻(亲见亲闻)；睹始知终(看见事物的开始阶段,就预见到它的最终结果)；睹记(见闻与记忆)', '小学', '1'),
    ('瞄', 'miáo', '13', '目', '左右', NULL, '瞄〈动〉 (形声。从目,苗声。本义注视目标;视力集中到一点上) 同本义 眼睛迅速地注视,迅速地看 瞄miáo注意看,视力集中在目标上~准。', '小学', '1'),
    ('瞎', 'xiā', '15', '目', '左右', NULL, '瞎 (形声。从目,害声。本义一目失明) 同本义 吾闻瞎儿一泪,信乎?--《资治通鉴》→三省注瞎,一目盲也。” 双目失明 盲人骑瞎马,夜半临深池。--《世说新语》；组词：瞎生(旧称以卜卦算命为业的盲人) 形容糊涂,不明事理 这呆子!石头又不是人,又不会说话,又不会还礼,唱他喏怎的,可不是个', '小学', '1'),
    ('瞒', 'mán', '15', '目', '左右', NULL, '瞒 (形声。本义眼睑低。闭目貌) 同本义 瞒,平目也。--《说文》 酒食声色之中,则瞒瞒然。--《荀子》；组词：瞒瞒(闭目貌) 通满” 通颟” 瞒 隐藏实情 什么事瞒的过我?--《红楼梦》 又如瞒产(隐瞒产量)；瞒落(隐瞒留下)；瞒', '小学', '1'),
    ('瞧', 'qiáo', '17', '目', '左右', NULL, '瞧〈形〉 (形声。从目,焦声。本义眼昏花) 同本义 觛文籍则目瞧,脩揖让则变伛,袭章服则转筋,谭礼典则齿龋；组词：瞧女人 撇呆打坠,早被那人瞧破', '小学', '1'),
    ('瞪', 'dèng', '17', '目', '左右', NULL, '瞪 睁大眼睛直视 瞪,直视貌。--《广韵》 文瞪眸不转。--《晋书·郭文传》 齐首目以瞪眄。(眄斜视)--王延寿《鲁灵光殿赋》；组词：瞪目(睁大眼睛直视)；瞪瞪(睁大眼睛直视的样子；发呆的样子) 瞪 用力睁大 瞪,怒目直视貌', '小学', '1'),
    ('瞬', 'shùn', '17', '目', '左右', NULL, '瞬 (形声。从目,舜声。本义眨眼) 同本义 尔先学不瞬,而后可言射矣。--《列子·汤问》；组词：一瞬(一眨眼工夫) 眼珠转动 直视,不能瞬', '小学', '1'),
    ('瞭', 'hóu', '11', '目', '左右', NULL, NULL, '小学', '1'),
    ('瞳', 'tóng', '17', '目', '左右', NULL, '瞳〈名〉 (形声。从目,童声。本义瞳孔) 同本义 瞳,目珠子也。--《玉篇》 舜目盖重瞳子。--《史记·项羽本纪》；组词：瞳子(虹膜中心的小圆孔)；瞳神 借指目光 瞳 〈形〉 无知的样子 瞳 〈动〉 看见 大嫂兜出檐口放,上瞳格子下瞳人', '小学', '1'),
    ('瞻', 'zhān', '18', '目', '左右', NULL, '瞻 (形声。从目,詹声。本义向远处或向高处看) 同本义 瞻,临视也。--《说文》 瞻,视也。--《尔雅》 瞻望弗及。--《诗·邶风·燕燕》 瞻彼日月；组词：观瞻(外观和对外观发生的反应)；高瞻远瞩；瞻略(谋略；智谋)；瞻眄(观看,察看)；瞻相(观察)；瞻视(观看；顾盼)；瞻察', '小学', '1'),
    ('矗', 'chù', '24', '目', '上下', NULL, '矗〈动〉 (会意。从三直。本义直立) 同本义 五步一楼,十步一阁,......矗不知其几千万落。--杜牧《阿房宫赋》 释宫斯阐,上矗星斗', '小学', '1'),
    ('矛', 'máo', '5', '矛', NULL, NULL, '矛 (象形。金文字形,是古代用来刺杀敌人的进攻性武器。本义长矛) 同本义 矛,酋矛也。建于兵车,长二丈,象形。；组词：矛戈(矛与戈', '小学', '1'),
    ('矢', 'shǐ', '5', '矢', NULL, NULL, '矢 (象形。甲骨文字形。象镝括羽之形。本义箭) 同本义。以竹为箭,以木为矢 矢又谓之箭。--《释名》 矢,弓弩矢也。--《说文》 掌六弓、四弩、八矢法。--《周礼·司弓矢》 矢；组词：飞矢；矢 矢shǐ 1.箭弓~', '小学', '1'),
    ('知', 'zhī', '8', '矢', '左右', NULL, '知 (会意。小篆字形,从口矢。段玉裁识敏,故出于口者疾如矢也。”意思是认识、知道的事物,可以脱口而出。本义知道)；组词：知不到(不知道)；知风(知道情况 知zhī 1.晓得,明了~晓', '小学', '1'),
    ('矩', 'jǔ', '9', '矢', '左右', NULL, '矩 (本字作巨,今字作矩。形声。从矢,巨声。本义矩尺,画直角或方形的工具) 同本义 求榘鑪之所同。；组词：矩墨(曲尺及绳墨', '小学', '1'),
    ('矫', 'jiǎo', '11', '矢', '左右', NULL, '矫情 凡事别矫情 矫〈动〉 (形声。从矢,乔声。本义把箭杆揉直的一种器具。引申为正曲使直”) 把弯曲的物体弄直 矫,直也。；组词：矫矢(矫直箭矢)；矫揉(使物或曲或直', '小学', '1'),
    ('短', 'duǎn', '12', '矢', '左右', NULL, '短〈形〉 (会意。从矢,豆声。从矢”,表示短不短可以用矢来量。古代弓长箭短,量长的用弓作标准,量短的用箭作标准。本义不长)；组词：短趁(打短工)；短盘驴子(短途来往的驴子)；短盘(分段作短程行走)；短票(借贷的凭证,借约)；短绠(短绳', '小学', '1'),
    ('矮', 'ǎi', '13', '矢', '左右', NULL, '矮 (形声。从矢,委声。本义身材短) 同本义(古汉语多用短,少用矮) 矮,短人也。--《说文新附》 道州地产民多矮,每年常配乡户,竟以其男号为矮奴。--《旧唐书·阳城传》。；组词：又矮又胖；矮个(身材短小的人) 低,不高 矮墙低屋的,难道都不怕亲戚们听见笑话了吗?--《红楼梦》', '小学', '1'),
    ('石', 'shí', '5', '石', NULL, NULL, '石 dan 容量单位,十斗为一石 十斗为一石。--《说苑·辨物》 关石和钧。--《国语·周语》。注今之斛也。” 一石沙,几斤重,朝载暮载将何用?--唐·白居易《官牛》 重量单位', '小学', '1'),
    ('矾', 'fán', '8', '石', '左右', NULL, '矾 各种金属(如铜、铁、锌)的硫酸盐,尤指具有玻璃质状态表面或光泽的该种硫酸盐的水合物 矾山”);矾水(溶明矾的水);矾粉(脱胶的明矾粉末)', '小学', '1'),
    ('矿', 'kuàng', '8', '石', '左右', NULL, '矿 (形声。从石,广声。本义矿产,矿物) 同本义 其下则金矿丹砾。--晋·郭璞《江赋》 又如铁矿;矿田;矿丁(旧时对矿工的称呼);矿夫(即矿兵)；组词：铁矿；矿田；矿丁(旧时对矿工的称呼)；矿夫(即矿兵)；矿屯(用驻军开采矿产以节省国家开支的一种措施)；矿主(旧时占有矿山', '小学', '1'),
    ('码', 'mǎ', '8', '石', '左右', NULL, '码 码磟(亦作玛瑙”。一种似玉而次于玉的宝石) 码,码磟,石次玉也。--《玉篇》 表示数目的符号 计算数目的用具 英制长度单位,美制码等于0.9144米,在英国', '小学', '1'),
    ('砂', 'shā', '9', '石', '左右', NULL, '砂〈名〉 沙”的俗字。指石之细碎者 泛指细碎如砂的物质 锅) 道家所炼丹砂,简称砂”。朱砂”的简称 砂shā 1.沙子,砂子,极细碎的石粒~石。~滩。泥~子。 2.像~子的~糖', '小学', '1'),
    ('砌', 'qì', '9', '石', '左右', NULL, '砌〈名〉 (形声。从石,切声。本义台阶) 同本义 雕阑玉砌应犹在,只是朱颜改。--李煜《虞美人》词 砌水(滴在台阶上的雨水);砌石(阶石);砌阶(台阶) 门限,门槛 于是玄墀釦砌', '小学', '1'),
    ('砍', 'kǎn', '9', '石', '左右', NULL, '砍〈动〉 (形声。从石,欠声。本义猛劈) 同本义 刀砍不入。--《广东军务记》 又如砍柴禾;砍树;砍削(用刀、斧劈或削);砍杀(用刀斧杀人;拼杀);砍头(杀头)；组词：砍柴禾；砍树；砍削(用刀、斧劈或削)；砍杀(用刀斧杀人；拼杀)；砍头(杀头)；砍脍(细切鱼肉) 镢头举得挺高,可是落到地', '小学', '1'),
    ('研', 'yán', '9', '石', '左右', NULL, '研 (形声。从石,幵声。本义细磨) 同本义 打取杏仁,以汤脱去黄皮,熟研,以水和之,绢滤取汁。；组词：研石(磨墨的用具)；研弄(磨墨弄笔) 研究；探讨 能研诸侯之虑', '小学', '1'),
    ('砖', 'zhuān', '9', '石', '左右', NULL, '砖 (形声。从石,专声。本义用粘土烧成的长方形块状建材) 同本义 是犹以塼涂塞江海也。--《荀子·正论》。注塼涂,以涂垒塼也。” 蒙诏赐银百两,已于扬州小郊北地烧砖；组词：青砖；红砖；砖匠(从事铺方砖或雕砖的工人)；砖橛子(碎砖；断砖)；砖位(古代朝官班位的标识)；砖塔(以砖为主要建筑材料的', '小学', '1'),
    ('砚', 'yàn', '9', '石', '左右', NULL, '砚 (形声。从石,见声。本义砚台,磨墨器) 光滑的石头 砚,石滑也。--《说文》。段玉裁注谓石性滑利也。 砚,研也。研墨使和濡也。--《释名》 砚台 一砚；组词：砚瓦(砚台)；笔砚 砚 制作砚 砚yàn 1.磨墨用的文具~台', '小学', '1'),
    ('砰', 'pēng', '10', '石', '左右', NULL, '砰 砰pēng像声词~ ~ ~,连响 三声。', '小学', '1'),
    ('破', 'pò', '10', '石', '左右', NULL, '破〈动〉 (形声。从石,皮声。本义石头开裂;破碎,碎裂) 同本义 破,石碎也。--《说文》 石破天惊逗秋雨。--李贺《李凭箜篌引》 沉船、破甑。--《史记·项羽本纪》 卵破子死；组词：爆破(用炸药炸毁)；破瓦(古代一种占卜方法', '小学', '1'),
    ('砸', 'zá', '10', '石', '左右', NULL, '砸 重物掉落在物体上,或用重物撞击 又把宝玉的一碗茶砸的碗碎茶流。--《红楼梦》 又如天塌砸众人;砸杀(将某物砸入地下,纹丝不动。比喻将事情定下,不允许再有变更);砸姜磨蒜(方言；组词：天塌砸众人；砸杀(将某物砸入地下,纹丝不动', '小学', '1'),
    ('砾', 'lì', '10', '石', '左右', NULL, '砾 (从石,乐声。本义小石,碎石) 同本义 飞沙走砾。--明·袁宏道《满井游记》 又如砾石;砾洲(沙洲);砾琹(碎石与美石；组词：砾石；砾洲(沙洲)；砾琹(碎石与美石', '小学', '1'),
    ('础', 'chǔ', '10', '石', '左右', NULL, '础〈名〉 (形声。从石,楚声。本义柱脚石,垫在房屋柱子下的石头) 同本义 云蒸柱础润。--《淮南子·说林》。；组词：础石；事物的基底或根基 础(礱)chǔ柱子底下的石礅', '小学', '1'),
    ('硅', 'guī', '11', '石', '左右', NULL, '硅〈名〉 一种四价的非金属元素,以化合物的形式,作为仅次于氧的最丰富的元素存在于地壳中,通常是在电炉中由碳还原二氧化硅而制得的,主要以合金的形式使用(如硅铁合金)', '小学', '1'),
    ('硕', 'shuò', '11', '石', '左右', NULL, '硕 (形声。从页,石声。页,头。本义头大) 同本义 硕,头大也。--《说文》 引申为大 硕鼠硕鼠,无食我黍。--《诗·魏风·硕鼠》 硕果不食。--《易·剥》 彼其之子,硕大无朋；组词：壮硕；肥硕；硕德(大德)；硕见(高见)；硕大；硕画；硕望；硕量；硕谋(远大的谋略)；硕虑(深远的思虑) 通石”', '小学', '1'),
    ('硝', 'xiāo', '12', '石', '左右', NULL, '硝 硝石 硝,药石也。方书硝七种。--《正字通》 又如硝子石(硝石。又称假水晶;也喻指眼睛);硝云弹雨(硝烟如云,子弹像雨。形容激烈的战斗) 经过硝制变软的皮革 若南方短毛革硝；组词：硝子石(硝石', '小学', '1'),
    ('硫', 'liú', '12', '石', '左右', NULL, '硫〈名〉 硫磺。一种非金属的、多价的、无味无嗅不溶于水的元素 硫liú化学元素之一,通称"硫磺(黄)"。符号s。淡黄色,质硬而脆,不导电,不易传热。用于制硫酸、火药、火柴、橡胶', '小学', '1'),
    ('硬', 'yìng', '12', '石', '左右', NULL, '硬 (形声。从石,更声。本义坚硬) 同本义 山原川泽,土有硬软。--《通典》 由于血压长期升高,可促使细小动脉硬化。--唐时华等《高血压病》；组词：硬米糁(未煮熟的米饭)；硬牌(旧制在府官到达前,必派前站带木牌先行通知地方官绅人等迎接)；硬帮(坚硬)；硬撑撑(坚硬结实', '小学', '1'),
    ('确', 'què', '12', '石', '左右', NULL, '确 (形声。左形,右声。本作碻”、塽”。本义坚固) 同本义 确乎能其事者而已矣。--《庄子·应帝王》 確乎其不可拔。--《易·乾卦》 夫乾確然,示人易矣', '小学', '1'),
    ('硼', 'péng', '13', '石', '左右', NULL, '硼〈名〉 三价高熔点非金属元素。在自然界中,硼只以其化合物形式存在着(像在硼砂、硼酸中,在植物和动物中只存在有痕量的硼)', '小学', '1'),
    ('碉', 'diāo', '13', '石', '左右', NULL, '碉 (形声。从石,周声。本义石屋) 石室 碉堡 碉堡 碉楼 碉 diāo碉堡。 【碉堡】军事上防守用的建筑物,多用砖、石、钢筋混凝土等建成。主要用于掩护射击。', '小学', '1'),
    ('碌', 'lù', '13', '石', '左右', NULL, '碌〈名〉lu (形声。从石,录声。本义石青色) 小石 矿物名 碌 〈形〉 平庸无能(多叠用) 繁忙 哆嗦,颤动 碌(磟)liù 1. 碌lù 1.平庸庸~。 2.繁忙忙~。劳~', '小学', '1'),
    ('碍', 'ài', '13', '石', '左右', NULL, '碍 (形声。从石,疑声。本义妨碍,阻挡) 同本义。 碍,止也。--《说文》 限至曰碍。--《通俗文》 孰能碍之。--《列子·力命》。注止也。” 碍诸以礼乐。--《法言·问道》；组词：碍手碍脚 妨碍别人做事,使人感到不方便；障碍(挡住道路,使不能顺利通过；也指阻挡物)；碍着脸(难为情,怕伤情面) 遮蔽', '小学', '1'),
    ('碎', 'suì', '13', '石', '左右', NULL, '碎 (形声。从石,卒声。石”是汉字部首之一,从石”的字与石头有关。本义破碎) 同本义 碎,细破也。；组词：碎首(撞碎其头)；碎折(破碎断裂)；碎扯百裂(撕裂得粉碎)；碎身粉骨(身体粉碎', '小学', '1'),
    ('碑', 'bēi', '13', '石', '左右', NULL, '碑 (形声。从石,卑声。本义古时宫、庙门前用来观测日影及拴牲畜的竖石) 竖石 碑,竖石也。', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('碗', 'wǎn', '13', '石', '左右', NULL, '碗 一种圆形凹心盛食品的器具,在形式上通常接近半球形,一般比盘子深,比茶杯大和重 芙蓉玉碗,莲子金杯。--北周·庾信《春赋》；组词：饭碗；瓷碗；搪瓷碗；摆碗筷；碗泥(烧制瓷器的粘土)；碗窑(烧制瓷器的窑) 像碗的东西 碗 用来计量用碗装的饮食 滑出出,', '小学', '1'),
    ('碘', 'diǎn', '13', '石', '左右', NULL, '碘〈名〉 一种非金属一价和多价元素,原子序数53,属于卤素,主要用于医药(例如用于抗菌、治疗呆小病和甲状腺肿)、照相和分析 碘 diǎn非金属元素。符号l(iodium)', '小学', '1'),
    ('碟', 'dié', '14', '石', '左右', NULL, '碟 (形声。从石,枼声。本义盛食品的小盘) 同本义 瓜子 碟 dié盛食物等的器皿,底浅平,比盘子小。', '小学', '1'),
    ('碧', 'bì', '14', '石', '上下', NULL, '碧 (形声。从玉,从石,白声。本义青绿色的玉石) 同本义 碧,石之青美者。--《说文》 高山,其下多青碧。--《山海经·西山经》 又 章峨之山多瑶碧。 昆仑碧树瑶树在其北；组词：碧卢(像玉的美石)；碧箫(用碧玉制的箫)；碧玉椽(用碧玉做的椽子) 指代绿水 碧水东流至此回', '小学', '1'),
    ('碰', 'pèng', '13', '石', '左右', NULL, '踫 (形声。从石,并声。本义两物相触或相撞) 同本义 掽,蒲孟切,彭去声,搕掽,撞也。--《字汇》。段注今俗谓卒然相遇曰掽。”按,掽是晚起字,今字作碰”；组词：小车碰到电线杆；鸡蛋碰石头；碰头(磕响头,表示惶恐服罪)；碰关(方言', '小学', '1'),
    ('碱', 'jiǎn', '14', '石', '左右', NULL, '碱 (碱”为鹼”的俗字。鹼”已简化为硷。而礆、鹻、塧、鹹、礆为过去俗用过的杂字) 盐鹵 鹹,北方味也。从鹵,咸声。', '小学', '1'),
    ('碳', 'tàn', '14', '石', '左右', NULL, '碳〈名〉 一种主要呈四价的非金属元素,存在于自然界中(如以金刚石和石墨形式),是煤、石油、沥青、石灰石和其他碳酸盐以及一切有机化合物的成分 碳tàn化学元素之一。有三种同素异形体', '小学', '1'),
    ('碴', 'chá', '14', '石', '左右', NULL, '碴 剃后残余或复生的短毛发;胡子丛生的样子 碴 小碎块 器物破口上的残缺部分 崭新黑漆的车,把头折了一段,秃碴碴的露着两块白木碴儿,非常的不调和,难看', '小学', '1'),
    ('碾', 'niǎn', '15', '石', '左右', NULL, '碾〈动〉 (形声。从石,展声。本义磙压;碾轧) 同本义 碾,所以轹物器也。--《集韵》 又如碾米;碾轧(磙压);碾械(木制者称檑木”,石制者称礌石”；组词：碾米；碾轧(磙压)；碾械(木制者称檑木”,石制者称礌石”', '小学', '1'),
    ('磁', 'cí', '14', '石', '左右', NULL, '磁 (形声。从石,兹声。本义磁石。也指磁性) 同本义。也为石名,即磁石,俗称吸铁石 瓷的俗字。指瓷器 地名 磁 紧密', '小学', '1'),
    ('磅', 'páng', '15', '石', '左右', NULL, '磅 300克到1070克范围内各种不同的重量单位名称之一 从前用过的重量名称,现只理论上存在,每磅等于5760格令或373克 现时讲英语民族普遍使用的重量名称', '小学', '1'),
    ('磕', 'kē', '15', '石', '左右', NULL, '磕〈象〉 (形声。从石声。本义石声或鼓声) 同本义 石头撞击声 磕,石声。--《说文》 物相碰声 榜舫兮下流,东注兮磕磕。--汉·王褒《九怀尊嘉》；组词：磕擦擦(形容物体磨擦碰撞声或马蹄声)；磕磕(物相碰声)；磕扑扑(急促的脚步声) 眯稳莸犊痴渡鄙H磕叉(磕叉叉；磕擦', '小学', '1'),
    ('磨', 'mó', '16', '石', NULL, NULL, '磨 (形声。从石,麻声。本义磨治石器) 同本义 如切如磋,如琢如磨。--《诗·卫风·淇奥》 切磋琢磨,乃成宝器。--《论衡·量知》 不曰坚乎,磨而不磷。--《论语·阳货》；组词：切磋琢磨(加工骨称切”,加工象牙称磋”,加工玉称琢”,加工石称磨”)；磨渲(磨治)；磨拭(琢磨)；磨琢(犹琢磨)；磨斫(', '小学', '1'),
    ('磷', 'lín', '17', '石', '左右', NULL, '磷 (形声。从石,粦声。本义薄石)一种氮族非金属多价元素,原子序数15,广泛存在于它的各种化合物中 磷 〈形〉 含有磷酸盐的 磷磷,形容岩石、水明净 泛泛东流水,磷磷水中石', '小学', '1'),
    ('磺', 'huáng', '16', '石', '左右', NULL, '磺 硫磺 澹水在磺山之下,日出磺气上腾,东风一发,感触易病,雨则磺水入河,食之往往得病以死。--《台海使槎录》 磺huáng', '小学', '1'),
    ('礁', 'jiāo', '17', '石', '左右', NULL, '礁〈名〉 (形声。从石,焦声。本义江海中隐现于水面上下的岩石。如暗礁) 同本义 由珊瑚虫的遗骸堆积成的岩石状物 矿石名', '小学', '1'),
    ('示', 'shì', '5', '示', '上下', NULL, '示 (会意。小篆字形,二”是古文上”字,三竖代表日月星。甲骨文本作t”,象祭台形。示”是汉字的一个部首,其义多与祭祀、礼仪有关。本义地神。引申义让人看,显 示) 显现;表示 示', '小学', '1'),
    ('礼', 'lǐ', '5', '礻', '左右', NULL, '礼 (会意。从示,从豱。豱”是行礼之器,在字中也兼表字音。本义举行仪礼,祭神求福) 同本义 秠,履也。所以事神致福也。', '小学', '1'),
    ('社', 'shè', '7', '礻', '左右', NULL, '社〈名〉 (会意。从示从土。土亦声。社土同字。本义土地神) 同本义 社,地主也。--《说文》 共工之子句龙为社神。--《春秋传》 社,土也。--《论衡·顺鼓》 以社以方', '小学', '1'),
    ('祈', 'qí', '8', '礻', '左右', NULL, '祈〈动〉 (形声。从示,斤声。本义向上天或神明求福) 同本义 祈,求福也。--《说文》 掌六祈。--《周礼·大祝》 祭有祈焉。--《礼记·郊特牲》；组词：祈场(向神祈祷的场所)；祈祝(祈求祝福)；祈死(祈求速死)；祈克(祈求克敌)；祈祉(祈求幸福)；祈祓(祈神除灾去秽)；祈', '小学', '1'),
    ('祖', 'zǔ', '9', '礻', '左右', NULL, '祖 (形声。从示,且。从示”与祭祀、宗庙有关。本义祖庙) 同本义 祖,始庙也。--《说文》。段注始兼二义,新庙为始,远庙亦为始。” 左祖右社；组词：祖祢(祖祢庙', '小学', '1'),
    ('祝', 'zhù', '9', '礻', '左右', NULL, '祝 (会意。甲骨文字形,象一个人跪在神前拜神、开口祈祷。从示,从儿口。儿”是古文人”字。本义男巫,祭祀时主持祝告的人,即庙祝)；组词：祝人(古代掌祭祀的 )；巫 祝zhù 1.〈表〉良好的愿望~愿', '小学', '1'),
    ('神', 'shén', '9', '礻', '左右', NULL, '神 (会意。从示申。申”是天空中闪电形,古人以为闪电变化莫测,威力无穷,故称之为神。本义神灵) 传说中的天神,即天地万物的创造者或主宰者 神,天神引出万物者也。；组词：神司(负责某种职责的天神)；神会(迎神赛会)；神祗(神指天神,祗指地神', '小学', '1'),
    ('祟', 'suì', '10', '示', '上下', NULL, '祟 (会意。从示,从出。示,与鬼神有关。表示鬼魅出来作怪。本义鬼神制造的灾祸) 同本义 寡人不祥,被于宗宙之祟,沉于谄谀之臣,开罪于君；组词：祸祟(灾祸)；祟书(迷信者认为,人害病是鬼神作祟,而且鬼神何日何时作祟,可在书上查出,此书称为祟书”)；祟恶(指鬼神所作', '小学', '1'),
    ('祠', 'cí', '9', '礻', '左右', NULL, '祠 (形声。从示,司声。本义春祭) 同本义 春祭曰祠,品物少,多文辞也。--《说文》 仲春之月祠不用牺牲,用圭璧及皮币。--《礼记·月令》 供奉鬼神、祖先或先贤的庙堂 祠,神祠也；组词：宗祠(祠堂)；祠灶(宗祠；祠堂)；祠馆(犹祠堂) 祠禄的省称 祠 〈动〉 引申为祭祀 此秦王之所以庙 祠 cí祠堂宗~', '小学', '1'),
    ('祥', 'xiáng', '10', '礻', '左右', NULL, '祥 (形声。从示,羊声。本义凶吉的预兆,预先显露出来的迹象) 同本义 无道曰祥。--《周书·武顺》 吉事有祥。--《易·系辞》 辰马,农祥也。--《国语·周语》 将有大祥', '小学', '1'),
    ('票', 'piào', '11', '示', '上下', NULL, '票 (会意。本义 火飞) 同本义 见票如累明。--《太玄·沈》。注飞光也。” 通飘”。轻举的样子 票然逝。--《汉书·礼乐志》。注轻举意。”；组词：票票(轻浮)；票然(轻举的样子) 票 〈动〉 摇动 票昆仑', '小学', '1'),
    ('祭', 'jì', '11', '示', '上下', NULL, '祭 (会意。甲骨文字形,左边是牲肉;左边是又”(手);中间象祭桌。表示以手持肉祭祀神灵。古人杀牲,一是为自己吃,再就是常把牲肉放在祭台上,祭”字就是有酒肉的祭祀, 即牲祭', '小学', '1'),
    ('祷', 'dǎo', '11', '礻', '左右', NULL, '祷 (形声。从示,寿声。向神求福的一种迷信行为) 祈祷,祈神求福 祷,告事求福也。--《说文》 祷,祭也。--《广雅》 五曰祷。--《周礼·大祝》。注祷,贺庆言福祚之辞；组词：祷巫(犹言巫祝祈祷)；祷祀(有事祷求鬼神而致祭)；祷雨(祈神降雨)；祷祈(祈祷)；祷牲(祈 祷 dǎo 1教徒或迷信的人', '小学', '1'),
    ('祸', 'huò', '11', '礻', '左右', NULL, '祸 (形声。从示,楇声。本义灾祸,祸患) 同本义 禍,害也。神不福也。--《说文》 禍灾杀礼。--《周礼·掌客》 禍兮福所倚。--《史记·屈原贾生列传》 逆其类者谓之禍', '小学', '1'),
    ('禀', 'bǐng', '13', '示', '上中下', NULL, '禀 (会意。禀为禀的俗字。本义给予谷物) 同本义 禀,赐谷也。--《说文》 既禀称事。--《礼记·中庸》。注稍食也。” 食闻吏禀当受粥者,或以陈粟。--《汉书·文帝纪》 葬阵亡者；组词：禀赡(指以公粮赈济百姓)；禀谷(官府给予粮食)；禀粮(供给粮食)；禀食(公家配给粮食) 赋予；给与 禀,予也', '小学', '1'),
    ('禁', 'jìn', '13', '示', '上下', NULL, '禁〈动〉 胜任,承受得起 不能禁失吾之悲。--清·林觉民《与妻书》 又如禁久(经久,耐久);禁奈(禁得起,受得起);禁不过(禁不的,禁不起。承受不住,受不了);禁当(担当;承受)；组词：禁久(经久,耐久)；禁奈(禁得起,受得起)；禁不过(禁不的,禁不起', '小学', '1'),
    ('福', 'fú', '13', '礻', '左右', NULL, '福〈名〉 (形声。从示,畐”声。声符亦兼表字义。畐”,本象形,是腹”字的初文,上象人首,田”象腹部之形。腹中的十”符,表示充满之义,则畐”有腹满义。福”富 ”互训,以明家富则有福', '小学', '1'),
    ('离', 'lí', '10', '忄', '上下', NULL, '离 (形声。从隹,表示与鸟类有关,离声。离”是鹂”的本字,因而声符亦兼表字义。本义鸟名。即黄鹂,也称仓庚,鸣声清脆动听)', '小学', '1'),
    ('禽', 'qín', '12', '忄', '上下', NULL, '禽〈名〉 (象形。本义走兽总名) 同本义 禽,走兽总名。--《说文》 禽者何?鸟兽之总名--《白虎通》 命主祠祭禽于四方。--《礼记·月令》。疏兽之通名也。” 傅翼戴角,分牙布爪', '小学', '1'),
    ('禾', 'hé', '5', '禾', '上下', NULL, '禾〈名〉 (象形。金文字形,象垂穗的禾本科农作物『字部首之一。从禾”的字多与农作物有关。本义谷类作物的总称) 古代指粟,即今之小米 禾,嘉谷也,二月始生,八月而孰,得时之中；组词：禾粟(谷粟)；禾畴(种植禾谷的田野)；禾颖(带芒的谷穗)；禾绢(谷穗)；禾线(谷穗)；禾稿(连茎带穗的谷类收获物)；禾菽', '小学', '1'),
    ('秀', 'xiù', '7', '禾', '上下', NULL, '秀 (会意。石鼓文,上为禾”,下象禾穗摇曳。本义谷物抽穗扬花) 同本义 荣而实者谓之秀。--《尔雅》 秀,出也。--《广雅》 实发实秀,实坚实好。--《诗·大雅·生民》；组词：秀发(指植物生长繁茂,花朵盛开)；秀穗(植物从叶鞘长出穗)；秀而不实(禾谷叶穗开花而不结实) 草类结实 又如秀孚(开花结', '小学', '1'),
    ('私', 'sī', '7', '禾', '左右', NULL, '私 (形声。从禾,厶声。本义禾;庄稼) 同本义 私,禾也。北道名禾主人曰私主人。--《说文》。段玉裁注盖禾有名私者也。” 中国古时女子称姊妹之夫为私 谭公维私；组词：私病；私处(生殖器) 日常衣服 薄污我私', '小学', '1'),
    ('秃', 'tū', '7', '禾', '上下', NULL, '秃〈形〉 (象形。从人,上象禾粟之形。本义头顶无发) 同本义 秃,无发也。--《说文》 秃者不免。--《礼记·问丧》 秃者不髽。--《礼记·丧服四制》 齐人谓无发为秃揭；组词：秃厮(光头家伙)；秃科子(秃脑瓜)；秃驴(光头驴', '小学', '1'),
    ('秆', 'gǎn', '8', '禾', '左右', NULL, '秆 (形声。从禾,旱声。本义禾茎) 同本义◇泛指草木的茎 稈,禾茎也。--《说文》 稻穰谓之稈。--《广雅》；组词：秆草(作饲料的禾茎杂草)；麦秆；麻秆儿 秆(稈)gǎn稻、麦、竹、甘蔗等植物的茎麦~', '小学', '1'),
    ('秉', 'bǐng', '8', '禾', NULL, NULL, '秉 (会意。从又,从禾,表示以手持禾。又”篆体象一只手。本义禾把,禾束) 同本义 秉,禾束也。；组词：秉穗(收稻时遗留在田中的禾把与禾实)；秉握(一握稻把', '小学', '1'),
    ('秋', 'qiū', '9', '禾', '左右', NULL, '秋 (象形。甲骨文字形为蟋蟀形,虫以鸣秋,借以表达秋天”的概念。另一写法,是蟋蟀形下加火”字,表示秋天禾谷熟,似火灼。籀文又添加禾”旁。本义收成,成熟的庄稼)；组词：麦秋(收割麦子的时候)；秋麦(成熟的禾稼)；秋禾(秋熟 秋(秌)qiū 1.一年四季中的第三季~季', '小学', '1'),
    ('种', 'zhǒng', '9', '禾', '左右', NULL, '种 植物的种子 诞降嘉种。--《诗·大雅·生民》 其谷宜五种。谓黍、菽、麦、稻也。--《周礼·职方氏》 种不得下。--《汉书·沟洫志》。注五谷之子也；组词：点种(点播种子)；种籽(即种子)；种食(谷种种粮食)；种粮(谷物的种子)；种实(即种子)；种粒(犹种子)；种子田(也叫留', '小学', '1'),
    ('科', 'kē', '9', '禾', '左右', NULL, '科〈名〉 (会意。从禾,从斗。斗”的意思是量”∠起来指衡量、分别谷子的等级品类。本义品类,等级)；组词：科品(种类；等级)；科荣(科第荣华)；科爵(指封建王朝官员的品级爵位) 法令；刑律 三仪同科', '小学', '1'),
    ('秒', 'miǎo', '9', '禾', '左右', NULL, '秒 (形声。从禾,少声。本义禾芒) 同本义 秒,禾芒也。--《说文》 造计秒忽。--《汉书·叙传下》。注引刘德秒,禾芒也。”；组词：秒忽(秒是禾芒,忽是细丝,比喻微细)；秒末(微小) 末端 癸巳七月之秒,余从西俗避暑白雷登海口', '小学', '1'),
    ('秕', 'bǐ', '9', '禾', '左右', NULL, '秕 中空或不饱满的谷粒 秕,不成粟也。从禾,比声。--《说文》 用秕稗也。--《左传·定公十年》。注谷不成者。今苏俗呼谷不充者曰瘪谷,盖即此字。字亦以粃为之。”；组词：秕稗(秕与稗', '小学', '1'),
    ('秘', 'mì', '10', '禾', '左右', NULL, '秘 bi 秘鲁的简称 秘鲁 秘 (形声。从禾,必声。 本义一种香草) 不可测知;不公开 祕,神也。从示,必声。；组词：秘箓(秘文)；秘法(秘术,秘密 秘 bì 1见【便秘】', '小学', '1'),
    ('租', 'zū', '10', '禾', '左右', NULL, '租 (形声。从禾,且声。从禾,与谷物有关。本义田赋,征收的农产品,又指按田地征收的捐税)；组词：租更(指田赋和践更的钱)；租委(输纳的田赋)；租刍(田赋)；租输(上缴的田赋)；租限(旧时地主规定佃户交租的期限) 赋税', '小学', '1'),
    ('秤', 'chèng', '10', '禾', '左右', NULL, '秤 用秤量物之轻重 权衡;衡量 秤 同称”。利用杠杆原理量物体轻重的器具 同称”。中国古代重量单位。十五斤为一秤 俺有敕命一道,封宋江为镇国大将军,总领辽兵大元帅,赐与金一提', '小学', '1'),
    ('秦', 'qín', '10', '禾', NULL, NULL, '秦〈名〉 (会意。从禾,从舂省。本义禾名。假借为专名用字) 秦,部落名 秦,伯益之后所封国。；组词：秦越肥瘠(喻指相去遥远,互不相关)；秦庭鹿(指秦朝的政权) 汉时西域诸 秦qín 1.周代诸侯国名,战国时七雄之一,在今', '小学', '1'),
    ('秧', 'yāng', '10', '禾', '左右', NULL, '秧 (形声。从禾,央声。本义植物的幼苗) 稻的初生幼苗 秧,禾若秧穰也。--《说文》。谓秆上皮葳蕤之状。 秧,今俗谓稻之初生者曰秧。--清·段玉裁《说文解字注》；组词：秧信(谓可插秧的信息)；秧秧(稻苗茂密貌)；秧针(指水稻秧苗的叶尖如针)；秧马(古代农民拔秧时所坐的器具) 泛指草木初生', '小学', '1'),
    ('秩', 'zhì', '10', '禾', '左右', NULL, '秩 (形声。从禾,失声。本义聚积) 同本义 秩,积也。--《说文》 大合百县之秩刍。--《礼记·月令》 九十日有秩。--《礼记·王制》 故人君御谷物之秩相胜,而操事于其不平之间；组词：秩秩(积聚的样子) 按次序排列 天秩有理', '小学', '1'),
    ('秫', 'shú', '10', '禾', '左右', NULL, '秫 (象形。从古文术,加禾。本义谷物之有粘性者。也指不粘者) 同本义 秫,稷之黏者也。--《说文》 稻黍秫稷粟麻秔。--《急就篇》 染羽以朱湛丹秫。盖有赤白二种；组词：秫田(种植黏粟之田)；秫酒(用秫酿成的酒)；秫蘖(制酒用的糯黍与曲)；秫稻(即糯稻)；秫谷(黍米)；秫黍(高粱) 通鉥”', '小学', '1'),
    ('积', 'jī', '10', '禾', '左右', NULL, '积 (形声。从禾,责声。从禾”,表示与农作物有关。本义堆积谷物) 同本义 积,聚也。--《说文》。按,禾谷之聚曰积。 令野修道委积。--《周礼·大司徒》。注少曰委,多曰积；组词：积谷(存积米谷以备灾荒)；积居(聚积；囤积)；积仓(贮存谷物的粮仓) 累积；堆叠 积土成山,风雨兴焉', '小学', '1'),
    ('称', 'chēng', '10', '禾', '左右', NULL, '称 chen 符合,相当 令作诗,不能称前时之闻。--宋·王安石《伤仲永》 薄罚不为慈,诛严不为戾,称俗而行也。；组词：对称；相称；称合(相当)；称任(称职,犹胜任)；称位(与职位相符) 称 cheng (形声', '小学', '1'),
    ('秸', 'jiē', '11', '禾', '左右', NULL, '秸 (形声。从禾,皆声。农作物的茎杆。如麦秸) 谷物脱馏的茎杆 秸(穖)jiē有些农作物脱馏的茎杆豆~。稻~。 秸jí 1.见"秸鞠"。', '小学', '1'),
    ('移', 'yí', '11', '禾', '左右', NULL, '移 (形声。从禾,多声。本义移秧) 同本义。泛指移植 移,禾相倚移也。--《说文》。徐灏注戴氏侗曰‘移,移秧也。凡种稻必先苗之而移之,迁移之义取焉,别作。灏按禾苗茂密乃移种之；组词：移花(移植花木)；移根(犹移植)；移种,移莳(犹移植) 假借为迻”', '小学', '1'),
    ('秽', 'huì', '11', '禾', '左右', NULL, '秽 (形声。从禾,岁声。本义荒废;长满野草) 同本义 秽,芜也。从草,岁声。字亦作秽。--《说文》 涂薲则塞。--《荀子·王霸》 国之薲孽也。--《荀子·大略》 粤地涂泥多草薲；组词：秽草(杂草,恶草)；秽荒(荒芜；杂草丛生)；秽莽(杂草；恶草) 弄脏,弄污 面一旦不修饰,则尘垢秽之；心一朝不思善,则邪', '小学', '1'),
    ('稀', 'xī', '12', '禾', '左右', NULL, '稀 (形声。从禾,希声。本义稀疏) 同本义 稀,疏也。--《说文》 月明星稀。--《文选·曹操·短歌行》。经传皆以希为之。 重露成涓滴,稀星乍有无；组词：稀棱挣(稀疏的样子)；稀撒撒(稀剌剌)；稀星(稀疏的星)；稀零零(极稀疏)；稀稀落落(稀疏的样子；稀疏冷落的样子) 少,', '小学', '1'),
    ('程', 'chéng', '12', '禾', '左右', NULL, '程 (形声。从禾,呈声。本义称量谷物,并用作度量衡的总名) 度量衡的总称 按度程。--《礼记·月令》 程者,物之准也。--《荀子·致仕》 法式;章程,规格 张苍定章程；组词：章程(书面写定的组织规程或办事条例)；程考(按科举常规考试)；程品(法式；规范)；程法(程式；法则) 典范；法度 匪先民', '小学', '1'),
    ('稍', 'shāo', '12', '禾', '左右', NULL, '稍〈名〉 (形声。从禾,肖声。本义禾末) 同本义 稍,出物有渐也。--《说文》。按,此字当训禾末,与秒为谷芒者别。；组词：稍秣(给牛马吃的草料) 泛指事物的末端,枝叶 俸禄,官吏的薪水 均其稍食', '小学', '1'),
    ('税', 'shuì', '12', '禾', '左右', NULL, '税 (形声。从禾,兑声。本义田赋,征收的农产品) 同本义 税,租也。--《说文》 敛财曰赋,敛谷曰税,田税曰租。--《急就篇》注 初税亩。--《谷梁传·宣公十五年》 税十取一', '小学', '1'),
    ('稚', 'zhì', '13', '禾', '左右', NULL, '稚 (形声。从禾,隹声。本义晚植的谷类。引申为幼禾) 同本义 穡,幼禾也。--《说文》。字亦作穉,作稚。 稚,幼稼也。--《韩诗传》 考灵曜百谷稚熟。--《尚书》。注晚熟曰稚；组词：稚稼(迟期种植的稻谷) 孩子,儿童 使老稚转乎沟壑', '小学', '1'),
    ('稠', 'chóu', '13', '禾', '左右', NULL, '稠 (形声。从禾,周声。本义禾多而密) 多 稠,多也。--《说文》。按,禾多也。 歌者稠。--《礼记·文王世子》注 书策稠浊。--《战国策·秦策》。注多也。” 稠人广众；组词：稠人(众人)；稠人广坐(很多人聚会的场所)；稠伙(犹稠众)；稠众(众多) 繁密 稠,密也', '小学', '1'),
    ('稳', 'wěn', '14', '禾', '左右', NULL, '稳 (形声。从禾,隐省声。禾”与粮食有关,有了粮食,心就安定了。本义安定,平稳) 同本义 地名破冢,真破冢而出,行人安稳,布帆无恙。；组词：安稳(稳当；平稳)；稳拍拍(稳稳当当)；稳惬(稳定使满意)；稳善(安稳美好)；稳脚(犹稳步)；稳疾(安稳而快速)；稳平(', '小学', '1'),
    ('稻', 'dào', '15', '禾', '左右', NULL, '稻 (形声。从禾,舀声。本义水稻) 同本义 其谷宜稻。--《周礼·职方氏》 浸彼稻田。--《诗·小雅·白华》 一种一年生的草本植物,在温暖气候下广泛栽培,种子用作人类主食', '小学', '1'),
    ('稼', 'jià', '16', '禾', '左右', NULL, '稼 (形声。从禾,家声。本义种植五谷) 同本义 不稼不穑。--《诗·魏风·伐檀》 巫载民不稼不穑食也。--《山海经·大荒南经》 宜稼于田。--《仪礼·少牢礼》 后稷教民稼穑；组词：稼桑(栽种桑树的一种方法', '小学', '1'),
    ('稽', 'jī', '15', '禾', '左右', NULL, '稽 (形声。从禾,象树木曲头止住不上长的样子,从尤,旨声。本义停留;阻滞) 同本义。引申为囤积 稽,留止也。；组词：稽欠(滞留拖欠)；稽身(拖住身子)；稽留(在外久留)；稽诣(停顿)；稽固(稽留停滞) 延迟 明晨炊米尽,吾起不容稽', '小学', '1'),
    ('稿', 'gǎo', '15', '禾', '左右', NULL, '稿 (形声。从禾,高声。本义禾秆) 禾秆,谷类植物的茎杆。也作穢” 穢,秆也。--《说文》 民惊走持穢。--《汉书·五行志》 又出穢税。--《书·禹贡传》 茭穢；组词：稿本(香草名', '小学', '1'),
    ('穆', 'mù', '16', '禾', '左右', NULL, '穆 (形声。本义禾名) 同本义 穆,禾也。--《说文》。段玉裁注盖禾有名穆者也。” 古时宗庙制度,父居左为昭,子居右为穆。参见昭穆” 辩庙祧之昭穆。--《周礼·小宗伯》。注父曰昭；组词：昭穆(左边和右边) 姓 穆 恭敬 于穆清庙', '小学', '1'),
    ('穗', 'suì', '17', '禾', '左右', NULL, '穗 (会意。从禾,惠声。稻麦等禾本科植物的花或果实聚生在茎上顶端部分。亦泛指穗状花实) 同本义 趙茎素毳,并柯共穗之瑞。；组词：穗肥(禾谷作物幼穗分化期施用的追肥,可使幼穗有充足养分,穗大粒多,增加产量)；麦穗 穗状之物 烛花或灯花 时复见残灯,和', '小学', '1'),
    ('穴', 'xué', '5', '穴', '上下', NULL, '穴 (象形。小篆字形,上面是宀”,表覆盖物;下面两边表示洞孔。本义土窟窿,地洞) 同本义 穴,土室也。；组词：洞穴(地洞或山洞)；穴人(在洞穴中采钟乳石的人)；穴流(洞穴中的水流) 墓穴；埋棺材的坑 临其穴', '小学', '1'),
    ('究', 'jiū', '7', '穴', '上下', NULL, '究 (形声。从穴,九声。本义穷;尽) 同本义 究,穷也。--《说文》 靡届靡究。--《诗·大雅·荡》 害气将究。--《汉书·食货志》 此告民究也。--《吕氏春秋·任地》 靡届靡究；组词：究途(走完全部的路程', '小学', '1'),
    ('穷', 'qióng', '7', '穴', '上下', NULL, '穷 (形声。从穴,躬声。躬,身体,身在穴下,很窘困。简化字为会意,力在穴下,有劲使不出。本义穷尽,完结)', '小学', '1'),
    ('空', 'kōng', '8', '穴', '上下', NULL, '空〈形〉 空虚;内无所有。引申为空虚处,空档 空,空虚。--《广韵》 小东大东,杼柚其空。--《诗·小雅·大东》 常有高猿长啸,属引凄异,空谷传响；组词：空衔(有官衔无实职或俸禄)；空脑子(心中无盘算,没有头脑之意)；空花阳焰(比喻不切实际的想法', '小学', '1'),
    ('穿', 'chuān', '9', '穴', '上下', NULL, '穿〈动〉 (会意。从牙,从穴。牙在穴中,表示穿通的意思。本义穿通,穿破) 同本义 穿,通也。；组词：穿墉(在墙上打洞)；穿着鼻(受人摆布)；穿穴(犹穿凿)；穿空(犹穿孔)；穿胸(胸前穿孔透背) 挖掘；开凿 通过、透过(空', '小学', '1'),
    ('突', 'tū', '9', '穴', '上下', NULL, '突〈动〉 (会意。从穴,从犬。本义犬从洞穴中突然窜出) 狗从穴中突然而出 突,犬从穴中暂出也。；组词：突轶(袭击；冲击)；突战(伏兵袭击的战术)；突然 突tū 1.鼓起,凸出来~凸', '小学', '1'),
    ('窃', 'qiè', '9', '穴', '上下', NULL, '窃 (会意。 从米,以米为穴,意为虫在穴中偷米吃,是会意字。本义偷) 同本义 窃,盗自中出曰窃。；组词：窃窥(偷看)；失窃(财物被人偷走)；偷窃(盗窃', '小学', '1'),
    ('窄', 'zhǎi', '10', '穴', '上下', NULL, '窄 (形声。从穴,乍声。本义狭小) 同本义 窄,陿也。--《广雅》 齐室逼窄。--《华山亭碑》 素标插人头,前途渐就窄。--陶潜《杂诗》；组词：窄索(窄小)；窄溜溜(形容窄)；窄逼逼(形容非常狭窄)；窄鳖鳖(非常狭窄的样子)；窄逼(狭隘；狭小)；窄窄别别(形容非常', '小学', '1'),
    ('窍', 'qiào', '10', '穴', '上下', NULL, '窍 (形声。从穴,巧声。本义孔,洞) 同本义 空中而多窍。--宋·苏轼《石钟山记》 又如窍穴(洞穴;窟窿);窍隙(孔洞;缝隙);窍星(小洞);窍坎(洞穴);窍窦(孔穴)；组词：窍穴(洞穴；窟窿)；窍隙(孔洞；缝隙)；窍星(小洞)；窍坎(洞穴)；窍窦(孔穴)；窍凿(洞穴)；窍木(中空之木) 指耳鼻', '小学', '1'),
    ('窑', 'yáo', '11', '穴', '上下', NULL, '窑 (会意。从穴,从缶。穴,土室;缶,瓦器。表示烧制瓦器的地方。本义烧砖瓦陶瓷器的灶) 同本义 竒,烧瓦灶也。；组词：窑头土坯(窑头上未经烧制的砖瓦坯', '小学', '1'),
    ('窒', 'zhì', '11', '穴', '上下', NULL, '窒 (形声。从穴,至声。洞穴狭小阻塞,故从穴。本义阻塞,不通) 同本义 窒,塞也。--《说文》 有孚窒。--《易·讼》。虞注塞止也。” 精不流则气郁；组词：窒塞；窒阂(闭塞,阻隔) 抑止住使不发泄 损,君子以惩忿窒欲', '小学', '1'),
    ('窖', 'jiào', '12', '穴', '上下', NULL, NULL, '小学', '1'),
    ('窗', 'chuāng', '12', '穴', '上下', NULL, '窗 (象形。从穴,囱声。窗”本作囱”,小篆字,象天窗形,即在屋上留个洞,可以透光,也可以出烟(后来灶突也叫囱”)◇加穴”字头构成形声字。本义天窗)', '小学', '1'),
    ('窘', 'jiǒng', '12', '穴', '上下', NULL, '窘 (形声。从穴,君声。本义生活或处境困迫,没有办法) 同本义 窘,迫也。--《说文》 又窘阴雨。--《诗·小雅·正月》。传困也。” 夫唯捷径以窘步。--《离骚》 窘若囚拘；组词：窘极(极端窘迫)；窘冗(困迫繁忙)；窘辱(窘迫凌辱)；窘涩(窘迫；为难)；窘穷(窘迫穷困)；窘敝(窘迫疲敝)；窘暴(穷困', '小学', '1'),
    ('窜', 'cuàn', '12', '穴', '上下', NULL, '窜 (会意。从鼠,从穴。老鼠在洞穴里,表示隐匿”、逃窜”。简化为窜”,形声,从穴,串声。本义躲藏)；组词：逃窜(逃跑流窜)；窜亡(逃亡；逃跑)；窜走(逃跑；潜逃', '小学', '1'),
    ('窝', 'wō', '12', '穴', '上下', NULL, '窝 鸟兽昆虫的巢穴 巢穴,窟,尤指用作隐藏或避难用的洞穴 竎,穴居也。--《集韵》 又如贼窝;土匪窝；组词：贼窝；土匪窝；窝窝凹凹(偏僻处) 身体表面的天然凹隐 借指人的安身处 指人或物体所在或所占的地方 物成团或簇', '小学', '1'),
    ('窟', 'kū', '13', '穴', '上下', NULL, '窟 (形声。从穴,屈声。本义土穴) 同本义 窟,兔崛也。--《说文》。字亦作窟。 兔之所息谓之窟。--《小尔雅·广兽》 兽穴曰窟。--《通俗文》。按,凡穴土皆曰堀。 西厌月窟；组词：窟弄(洞；孔)；窟窍(窟窿；洞)；窟窦(洞空貌)；窟宠(窟窿) 洞穴 狡兔有三窟', '小学', '1'),
    ('窥', 'kuī', '13', '穴', '上下', NULL, '窥 (形声。从穴,规声。本义从小孔或缝里看) 暗中察看。亦泛指观看 窥,小视也。--《说文》 钻穴隙相窥,逾墙相从。--《孟子·滕文公下》 窥见室家之好；组词：窥觑(偷看)；窥瞰(窥探；暗中偷看)；窥欲(窥伺贪求) 观察,侦探 窥谷忘反', '小学', '1'),
    ('窿', 'lóng', '16', '穴', '上下', NULL, '窿〈形〉 高起;突出 用同癃” 窿 〈名〉 窿lóng〈方〉煤矿坑道。', '小学', '1'),
    ('立', 'lì', '5', '立', '上中下', NULL, '立 (会意。甲骨文象一人正面立地之形。本义笔直的站立) 同本义 立,俲也。--《说文》 君子以立不易方。--《易·恒》 哙遂入,披帷西乡立。--《史记·项羽本纪》 持璧却立；组词：挺立(直立)；坐立不安；把电线杆立起来；肃立(恭敬庄严地站着)；立托(依托)；立容(站立时的仪态容表)；立戟(卫士持戟侍', '小学', '1'),
    ('竖', 'shù', '9', '立', '上下', NULL, '竖 竖,竖立也。--《说文》 竖,立也。--《广雅》 槐树自拔倒竖。--《后汉书·灵帝纪》 (佛印)卧右膝,诎右臂支船,而竖其左膝。--明·魏学洢《核舟记》 鲁有执长竿入城门者；组词：竖柜(一种直立的较高的柜子,前面开门,有的装有隔板或若干抽屉,多用来存放衣物等)；竖一个目标来向它射击 竖 纵', '小学', '1'),
    ('站', 'zhàn', '10', '立', '左右', NULL, '站 (形声。从立,占声。本义直立) 站立,直立。以基本直立的姿势用双脚或一脚支撑自己 凡射,或对贼、对把,站定观把子或贼人,不许看扣。--明·戚继光《纪效新书》；组词：站门子(妓女站在门口招人或接客)；站眙(久立而不行走)；站堂(旧时衙门开审时,差役排列在公堂上以应差)；站柜台(指营业员', '小学', '1'),
    ('竞', 'jìng', '10', '立', '上下', NULL, '竞 (会意。甲骨文字形,象二人竞逐。本义争竞;角逐;比赛) 同本义 競,逐也。--《说文》 职竞用力。--《诗·大雅·桑柔》 犹不能与罗者竞多。--《淮南子·原道》 相与优游；组词：竞进(争逐拥进)；竞斗(争斗,打斗)；竞心(争强好胜之心)；竞逐(角逐,竞争)；竞爽(争胜,争强) 争辩 竞(競)jìn', '小学', '1'),
    ('竟', 'jìng', '11', '立', '上下', NULL, '竟 (会意。从音,从人。本义奏乐完毕) 同本义 竟,乐曲尽为竟。--《说文》 凡乐成则告备。--《周礼》『·郑玄注成,谓所奏一竟。” 泛指结束,完毕 竟,终也。--《玉篇》 竟；组词：竟学(学完,学到底)；未竟之业；事竟 追究 竟jìng 1.完毕,终了看书既~(既已经)', '小学', '1'),
    ('章', 'zhāng', '11', '立', '上下', NULL, '章 (会意。从音十。音指音乐,十”是个位数已终了的数,合起来表示音乐完毕。本义音乐的一曲)；组词：章夏(古代乐章名', '小学', '1'),
    ('竣', 'jùn', '12', '立', '左右', NULL, '竣 (形声。本义退位) 同本义 有司已于事而竣。--《国语》。韦昭注竣,伏退也。” 完成或完毕某项工作,结束、终止 完成,使完整、使圆满,在满足一切要求、需要后结束 竣 完成', '小学', '1'),
    ('童', 'tóng', '12', '立', '上下', NULL, '童〈名〉 (形声。重省声。本义男奴仆) 同本义 得童仆贞。--《易·旅》 童子执帚。--《仪礼·既夕礼记》 小童持斧。--宋·苏轼《石钟山记》；组词：童奴(仆役)；童隶(犹童仆)；童仆(家僮和仆人)；童妾(婢女；小妾) 小孩', '小学', '1'),
    ('竭', 'jié', '14', '立', '左右', NULL, '竭 (形声。从立,曷声。本义背举;用肩背负) 同本义 五行之动,迭相竭也。--《礼记·礼运》。注犹负戴也。” 干涸;枯竭 伊洛竭而夏亡。--《国语·周语》。注涸也。” 渊泉不能竭；组词：竭涸(干涸无水)；枯竭(水源干涸) 穷尽 再而衰,三而竭', '小学', '1'),
    ('端', 'duān', '14', '立', '左右', NULL, '端 (形声。从立,聑声。本义站得直) 同本义 端,直也。--《说文》。按立容直也。” 端,正也。--《广雅·释诂一》 以端其位。--《礼记·祭义》 端行颐靋如矢；组词：端行(端正身躯而快步行走)；端拱(端正身子拱手)；端伟(笔直壮大)；端端(端正；不倾斜)；端身(摆正身体) 端正', '小学', '1'),
    ('竹', 'zhú', '6', '竹', NULL, NULL, '竹 (象形。小篆字形,象竹茎与下垂的叶片。竹”是汉字的一个部首。从竹”的字大部分是乐器、竹器和记载文字的东西。本义竹子)；组词：竹笋汤(竹板子)；竹夫人(中空、有孔的竹编床上用品)；竹撞(竹编提盒)；竹箨(竹笋的皮；笋衣)；竹笥(竹箱)；竹蓖(竹棍', '小学', '1'),
    ('竿', 'gān', '9', '竹', '上下', NULL, '竿〈名〉 (形声。从竹,干声。本义竹竿) 同本义。竹子的主干 竿,竹梃也。--《说文》 籫籫竹竿。--《诗·卫风·竹竿》 禁藏母拊竿。--《管子》 竿殳之所搉毕；组词：立竿见影；揭竿为旗；竿木(古代艺人借以在其上表演各种技艺动作的长竿)；竿殳(竹杖)；竿首(竹竿顶端)；竿头(竹竿的顶端)', '小学', '1'),
    ('笆', 'bā', '10', '竹', '上下', NULL, '笆 (形声。从竹,巴声。本义竹名。即棘竹) 一种长刺的竹子 用竹片或树的枝条编织成的器物 用竹或荆条编成的障隔 笆斗', '小学', '1'),
    ('笋', 'sǔn', '10', '竹', '上下', NULL, '笋 (形声。从竹,尹声。本义竹笋) 竹子初从土里长出的嫩芽,味鲜美,可以做菜,也叫竹笋” 箂,竹胎也。；组词：笋玉(喻指女人的手指)；笋剥(像剥笋似地脱掉,剥光)；笋枯(笋干)；笋鞭(竹的地下茎)；笋尖(笋的尖嫩部分)；笋衣(笋壳', '小学', '1'),
    ('笑', 'xiào', '10', '竹', '上下', NULL, '笑〈动〉 (会意。从竹,从夭。杨承庆曰,竹得风其体夭屈,如人之笑”。字或从竹,从夭。本义因喜悦开颜或出声)', '小学', '1'),
    ('笔', 'bǐ', '10', '竹', '上下', NULL, '笔 (会意。从竹,从聿。聿”),是笔”的本字,小篆象以手执笔。古时毛笔笔杆都是以竹制成,故从竹。简化字笔”,从竹从毛”会意,指旧时用的毛笔。此字最早见于北齐 隽修罗碑；组词：毛笔；钢笔；圆珠笔；笔削(修改文章)；笔帕之敬(雅洁的礼品)；笔楮难穷(文字难以充分表达', '小学', '1'),
    ('笙', 'shēng', '11', '竹', '上下', NULL, '笙 (形声。从竹,生声。本义簧管乐器) 同本义 笙,十三簧象凤之身也。笙,正月之音,物生故谓之笙。；组词：笙弄(弄笙)；笙簧(簧管乐器),通常用长短不同的若干(十三至十九)个竹管制成', '小学', '1'),
    ('笛', 'dí', '11', '竹', '上下', NULL, '笛 (形声。从竹,由声。本义笛子,管乐器名,竹制,左一孔为吹口,次孔加竹膜,右六孔皆上出,又谓之横吹)；组词：笛竹(用以制笛的竹子)；笛吹(吹笛) 响声尖锐的发音器 笛卡儿坐标 照参考轴至 笛 dí 1横吹的管乐器', '小学', '1'),
    ('笤', 'tiáo', '11', '竹', '上下', NULL, '笤〈名〉 笤帚 如笤把,笤篱(即笤帚);笤帚星(扫帚星。彗星的俗称) 笤帚 笤tiáo', '小学', '1'),
    ('符', 'fú', '11', '竹', '上下', NULL, '符〈名〉 (形声。从竹,付声。从竹”,表示与竹子有关。本义古代朝廷传达命令或调兵将用的凭证,双方各执一半,以验真假) 符信 符,信也『制以竹长六寸分而相合。；组词：符玺(古代帝王的印章)；符宝郎(古官名', '小学', '1'),
    ('笨', 'bèn', '11', '竹', '上下', NULL, '笨 (形声。从竹,本声。本义竹里。指竹的内表面) 竹子的内层。通称竹黄” 笨,竹里也。从竹,本声。', '小学', '1'),
    ('第', 'dì', '11', '竹', '上下', NULL, '第 (形声。从竹,弟声。本写作弟”。本义次第,次序) 同本义。有时也用于数字前表示次序 第,次也。；组词：等第(名次等级)；第次(等级；次第)；第老的(排行最小的)；第三本《诗经》(指宋朱熹编注的《诗经传》)；第六感觉(指眼、', '小学', '1'),
    ('笼', 'lóng', '11', '竹', '上下', NULL, '笼 (形声。从竹,龙声。本义竹笼) 用竹片编成的盛物的器具 笼,举土器也。--《说文》 共丘笼。--《周礼·遂师》 貂裘而负笼。--《淮南子·说山》 荷笼负锸；组词：笼臿(盛土的笼和铲挖泥土的锹)；笼篰(竹笼和小竹篓)；笼屉(蒸笼) 饲养鸟、虫、家禽等的笼子 闭以雕笼', '小学', '1'),
    ('等', 'děng', '12', '竹', '上下', NULL, '等 (会意。从竹,寺声。寺官曹之等平也,寺者,简册杂积之地,寺亦声。本义整齐的简册) 同本义 等,齐简也。；组词：优等；等例(等级差别,地位高低的差别)；等子(宋代的御林军；标本,样本)；等分(等级名分)；等外品(质量差,不列入等级的', '小学', '1'),
    ('筋', 'jīn', '12', '竹', '上下', NULL, '筋〈名〉 (会意。从肉,从力,从竹。因为竹多筋,故从竹”。本义附着在骨上的韧带) 同本义 筋,肉之力也。；组词：筋皮(筋骨与皮肉)；筋厮锁(身体已肢解,只剩筋络相连', '小学', '1'),
    ('筏', 'fá', '12', '竹', '上下', NULL, '筏 (形声。从竹,伐声。本义筏子) 同本义 筏,大曰筏,小曰桴,乘之渡水。--《广韵》 重五斤以上诸林木,渥水中,无过一筏。--《墨子·杂守》 无数涪江筏,鸣桡总发时；组词：筏渡(用筏子渡水)；筏工(以撑筏子为业的人) 筏(栰) fá用竹、木或兽皮等编排制做的水上交通运输工具竹~子', '小学', '1'),
    ('筐', 'kuāng', '12', '竹', '上下', NULL, '筐〈名〉 (形声。从竹,匡声。本义筐子,盛东西的方形竹器) 同本义◇亦用柳条或荆条等编成 维筐及筥。；组词：筐篚(盛物竹器)；筐簏(盛物的竹器)；筐笼(泛指盛物竹器)；筐箩(箩筐', '小学', '1'),
    ('筑', 'zhù', '12', '竹', '上下', NULL, '筑 (形声。从木,筑声。本义筑墙。古代用夹板夹住泥土,用木杆把土砸实) 捣土使坚实 篵,捣也。；组词：筑踏(捣土并以足踏之,使之坚实) 修建；建造(仅指建筑物从无到有的建造) 曰止曰时,筑垒于兹', '小学', '1'),
    ('筒', 'tǒng', '12', '竹', '上下', NULL, '筒 (形声。从竹,同声。本义竹筒,粗大的竹管) 同本义 筒,通箫也。--《说文》 筒,竹管也。--《三苍》 筩,断竹也。--《说文》 教吏为缿筩。--《汉书·李广汉传》。注竹筩也；组词：筒箭(放在竹筒里发射的箭矢)；筒竹(竹筒)；筒炙(古时利用竹筒熏烤的一种烹调方法', '小学', '1'),
    ('答', 'dá', '12', '竹', '上下', NULL, '答 (形声。从竹,合声。1本义以竹补篱。2答谢,报答) 回话;应对 听言则答。--《诗·小雅·雨无止》 既发则答君而俟。--《仪礼·乡射礼记》 见渔人,乃大惊,问所以来。具答之；组词：应答如流；答教(预先写好的准备答问的书面文字)；答言(用言语回答)；答语(回答的话；应对的话) 报礼；报答', '小学', '1'),
    ('策', 'cè', '12', '竹', '上下', NULL, '策 (形声。从竹,朿)声。朿”,指带有芒刺的植物,作策”的声符,同时兼表字义。本义竹制的马鞭(头上有尖刺))；组词：策辔(马鞭与马缰)；策彗(以 策 cè 1古代写字用的竹片或木片简~', '小学', '1'),
    ('筛', 'shāi', '12', '竹', '上下', NULL, '筛 (形声。从竹,师声。本义一种竹器,筛子) 同本义 滤泉花满筛。--唐·李洞《喜鸾公自蜀归》；组词：筛子喂驴(歇后语', '小学', '1'),
    ('筝', 'zhēng', '12', '竹', '上下', NULL, '筝 (形声。从竹,争声。从竹,与乐器有关。本义拨弦乐器。形似瑟。筝是拨弦乐器,战国时已流行于秦地,故又称秦筝”)；组词：筝人(弹筝的人)；筝阮(秦筝与阮咸', '小学', '1'),
    ('筷', 'kuài', '13', '竹', '上下', NULL, '筷〈名〉 (形声。从竹,快声。本义筷子。也叫箸”,夹取食物的用具) 同本义 筷kuài夹取食物的用具,用竹、木或金属等制成,细棍儿状用~子夹熟食。', '小学', '1'),
    ('筹', 'chóu', '13', '竹', '上下', NULL, '筹 (形声。从竹,夀声。本义计数的用具) 壶矢。古代投壶用的签子,形如箭筩 筹,壶矢也。--《说文》。谓投壶之矢为 筹。 筹室中五扶。--《礼记·投壶》。注矢也。” 箭筹八十；组词：竹筹；筹马(古时投壶计数的用具) 筹 算计 运筹帷幄之中', '小学', '1'),
    ('签', 'qiān', '13', '竹', '上下', NULL, '签 (形声。从竹,佥声。本义署名押字) 同本义 用简单的文字拟具意见 粗粗地缝合起来 引,导引 下令征调 刺;插 签 旧时官府交给差役拘捕犯人的片状凭证,多用竹', '小学', '1'),
    ('简', 'jiǎn', '13', '竹', '上下', NULL, '简 (形声。从竹,间声。本义竹简。古代书写了文字的狭长竹片) 同本义。战国至魏晋时代的书写材料,是削制成的狭长竹片或木片,竹片称简”,木片称札”或牍”,统称为简”；组词：简素(竹简与缣素', '小学', '1'),
    ('箍', 'gū', '14', '竹', '上下', NULL, '箍 用篾或金属条等围束器物 绕缠 广聚跟小元抬头一看,见他头上箍着块白手巾', '小学', '1'),
    ('箕', 'jī', '14', '竹', '上下', NULL, '箕 (形声。从竹,其声。本义簸箕,扬米去糠的器具) 同本义 箕,簸也。--《说文》 以箕自乡而报之。--《礼记·曲礼》。注箕去弃物。” 良弓之子,必学为箕。--《礼记·学记》；组词：箕帚(簸箕和扫帚', '小学', '1'),
    ('算', 'suàn', '14', '竹', '上下', NULL, '算 (会意。从竹,从具。竹”跟算筹有关,具”表示齐备。本义计算) 同本义 算,数也。--《说文》 无算爵。--《仪礼·乡饮酒礼》 亲则月算如邦人。--《仪礼·丧服记》 明衣不在算；组词：算还(结算支付)；算尽镏铢(极微小的数量也要算)；算来(计算起来)；算刻(犹计算)；算定(经过计算而确定或断定)；算程(', '小学', '1'),
    ('管', 'guǎn', '14', '竹', '上下', NULL, '管〈名〉 (形声。从竹,官声。本义一种类似于笛的管乐器◇泛指管乐器) 中国古代的一种管乐器,起初用玉制成,改用竹,有六孔,长一尺◇泛指管乐器 管,如箎,六孔,十二月之音,物开地牙；组词：管色(管类乐器)；管儿(指笛子之类的管乐器)；管弦(用管乐器弦乐器演奏 管(筦)guǎn 1.吹奏的乐器,有笙、箫、笛等', '小学', '1'),
    ('箩', 'luó', '14', '竹', '上下', NULL, '箩 (形声。从竹,罗声。本义竹制的盛器,多方底圆口) 同本义 箩,箕也。--《广雅·释器》 所以注斛,陈魏宋楚之间谓之箩。--《方言》五；组词：箩斗(即箩兜', '小学', '1'),
    ('箫', 'xiāo', '14', '竹', '上下', NULL, '箫 (形声。从竹,肃声。从竹,与乐器有关。本义洞箫,竹制的管乐器) 同本义 箫,参差管乐也。象凤之翼。；组词：箫韶(大磬', '小学', '1'),
    ('箭', 'jiàn', '15', '竹', '上下', NULL, '箭 (形声。从竹,前声。本义竹名。箭竹) 同本义 箭,矢竹也。--《说文》 其利金锡竹箭。--《周礼·职方氏》 东南之美者,有会稽之竹箭焉。╠《尔雅·释地》 如竹箭之有筠也；组词：箭笋(箭竹嫩笋)；箭茁(笋芽)；箭萌(小笋)；箭筠子竹(一种竹棍子)；箭笄(竹制的簪子) 搭在弓弩上发射的竹制武器 自关', '小学', '1'),
    ('箱', 'xiāng', '15', '竹', '上下', NULL, '箱 (形声。从竹,相声。本义车箱) 同本义 箱,大车牝服也。--《说文》 不以服箱。--《诗·小雅·大东》。传箱,大车之箱也。” 乃求万斯箱', '小学', '1'),
    ('篇', 'piān', '15', '竹', '上下', NULL, '篇〈名〉 (形声。从竹,扁声。本义竹简) 同本义;简册。古代文章写在竹简上,为保持前后完整,用绳子或皮条编集在一起称为篇” 篇,书也。...谓书于简册可编者也。；组词：篇翰(篇章；篇简)；篇卷(指书籍)；篇册(犹书籍)；篇典(典籍)；篇秩(书籍的篇卷)；篇次(谓书籍中篇章的顺序) 特指诗', '小学', '1'),
    ('篓', 'lǒu', '15', '竹', '上下', NULL, '篓 (形声。从竹,娄声。本义篾篓) 同本义。盛东西的器具,用竹或荆条等编成 篾篓挑将水边货。--唐彦谦《蟹》；组词：字纸篓 篓(簍)lǒu用竹篾、荆条等编制的盛物器油~', '小学', '1'),
    ('篙', 'gāo', '16', '竹', '上下', NULL, '篙 (形声。从竹,高声。从竹”,表示与竹有关。本义撑船的竿) 同本义 尝发所在竹篙,有一官长连根取之,仍当足,乃超两阶用之。；组词：篙眼(篙痕', '小学', '1'),
    ('篡', 'cuàn', '16', '竹', '上下', NULL, '簒 (形声。从竹,算声。本义非法地夺取) 同本义 自关而西,秦晋之间,凡取物而逆谓之篡。--《方言》一 且如人有财,见篡于盗。--王安石《原过》 豪民子闻难,鸠宗族僮奴百许人；组词：篡逆(用强力夺取君位的叛逆)；篡取(夺取)；篡事(篡夺之事) 特指臣子夺取君位 及王莽篡位,歆为国师', '小学', '1'),
    ('篮', 'lán', '16', '竹', '上下', NULL, '篮 (形声。从竹,监声。本义篮子,有提梁的竹制盛器。也有用藤条、柳条等编制而成的) 同本义 篮,大篝也。；组词：篮儿(篮子)；竹篮；提篮 篮球架上供投球用的带网的铁圈 竹轿 篮(籃)lán 1.用竹、藤、柳条、塑料带等编成的上有提梁', '小学', '1'),
    ('篱', 'lí', '16', '竹', '上下', NULL, '篱 (形声。从竹,离声。本义篱笆) 同本义。用竹、苇或树枝等编成的蔽障物,以保护场地。也说笆篱” 采菊东篱下,悠然见南山。--晋·陶潜《饮酒》 庭中始为篱；组词：樊篱(篱笆)；篱子(即篱笆)；篱花(篱菊', '小学', '1'),
    ('篷', 'péng', '16', '竹', '上下', NULL, '蓬〈名〉 (形声。从苃,逢声。本义草名。蓬蒿) 同本义 蓬,蒿也。--《说文》 彼茁者蓬。--《诗·召南·驺虞》 桑蓬矢六。--《礼记·内则》 若纵火于秋蓬。--《楚辞·沈江》；组词：蓬厂(草棚)；蓬窗(草窗,意为破败的窗户)；蓬麻(比喻良好的学习环境)；蓬转(蓬草随风飞转)；蓬衡(陋室茅舍；蓬户衡门)', '小学', '1'),
    ('簇', 'cù', '17', '竹', '上下', NULL, '簇 (形声。从竹,族声。本义小竹丛生) 同本义 簇,小竹丛生也。--《正字通》 丛集;聚集 律中太簇,言万物始簇而生。--《史记·独断》 微微风簇浪,散作满河星；组词：簇集(聚集)；簇带(簇戴', '小学', '1'),
    ('簸', 'bò', '19', '竹', '上下', NULL, '簸 (形声。从箕,皮声。本义用簸箕盛粮食等上下颠动,扬去糠粃尘土等物) 同本义 簸,扬米去糠也。；组词：簸秕,簸扬糠秕(扬米去糠,糠在米上)；簸箩(盛物的竹筐) 摇动；颠动 宫殿摆簸', '小学', '1'),
    ('簿', 'bù', '19', '竹', '上下', NULL, '薄 (形声。从竹,溥)声。本义登记事物的册子) 同本义 上问上林尉诸禽兽簿。(上皇上;上林尉官名。)；组词：练习薄；账簿；簿籍(财物出纳的账册)；簿钞(簿牒；簿籍文书) 文书 儒生所短,不徒以不晓簿书', '小学', '1'),
    ('籍', 'jí', '20', '竹', '上下', NULL, '籍 (形声。从竹,耤声。古书以竹制成,故从竹”。本义登记册,户口册) 同本义 籍,簿书也。；组词：籍口(户口)；籍戎(编入军籍)；籍地(官宦门第)；削籍(官吏被革职,在官籍中除名)；除籍(于簿籍中除名) 泛指书,成册的', '小学', '1'),
    ('米', 'mǐ', '6', '米', NULL, NULL, '米 (象形,甲骨文字形。象米粒琐碎纵横之状。米”是汉字的一个部首,从米”的字与米、粮有关。本义谷物和其他植物子实去壳后的子实)；组词：粟米；花生米 特指稻米 饷米千斛,修书累纸', '小学', '1'),
    ('类', 'lèi', '9', '米', '上下', NULL, '类 (形声。从犬,? 同本义 类,种类相似,惟犬最甚。--《说文》 皆守株之类。--《韩非子·五蠹》 无法者以类举。--《荀子·王制》 壹统类。╠《荀子·非十二子》 其负类反伦；组词：类考(学院的科考)；类族(事 类(類)lèi 1.种,具有共同特征事物的综合同~', '小学', '1'),
    ('籽', 'zǐ', '9', '米', '左右', NULL, '籽 植物的种子 籽zǐ植物的子实瓜~。棉花~。萝卜~。', '小学', '1'),
    ('粉', 'fěn', '10', '米', '左右', NULL, '粉〈名〉 (会意。从米,从分,分亦声。本义米细末。亦指谷类、豆类作物子实的细末) 同本义 粉,傅面者也。；组词：脂粉；粉面(傅粉的脸) 泛指细末状物质 用米、豆类或马铃薯等淀粉制 粉 fěn 1.细末~末', '小学', '1'),
    ('粒', 'lì', '11', '米', '左右', NULL, '粒〈名〉 (形声。从米,立声。本义米粒,谷粒) 同本义 粒状物 粒 〈动〉 进食;吃饭 养活 生我百谷,粒我焌民。--晋·傅咸《喜雨赋》 通立”。成 焌民乃粒,万邦作乿。', '小学', '1'),
    ('粗', 'cū', '11', '米', '左右', NULL, '粗 (形声。从米,且声。本义糙米) 同本义 粗,疏也。--《说文》。按,粝米也√黍粟十六斗大半斗为米一斛。 粮则无矣,麤则有之。--《左传》；组词：粗糠(糠', '小学', '1'),
    ('粘', 'zhān', '11', '米', '左右', NULL, '粘〈形〉 nian (形声。从米,占声。本义具有粘性) 同本义 厚而带粘性)', '小学', '1'),
    ('粟', 'sù', '12', '米', '上下', NULL, '粟 (会意,象草木果实下垂的样子◇隶变为西”。本义粟子,谷子) 同本义 谷物、干草和饲料 粟,嘉谷实也。；组词：粟入(税粟的收入)；粟粒(谷物的颗粒) 谷粒 迁淳安知县', '小学', '1'),
    ('粤', 'yuè', '12', '米', '上下', NULL, '粤〈助〉 助词。古与聿”、越”、曰”通用,用于句首或句中 粤,于也。审慎之词也。从于,从寀,会意。；组词：粤若(发语词', '小学', '1'),
    ('粥', 'zhōu', '12', '米', '左中右', NULL, '粥〈动〉yu 同鬻”。卖 则使其贾粥之。--《周礼·巫马》 不粥祭器。--《礼记·曲礼下》 田里不粥。--《礼记·王制》 又 戎器不粥于市。；组词：粥画(卖画的) 养育 初俊羔助厥母粥', '小学', '1'),
    ('粪', 'fèn', '12', '米', '上下', NULL, '粪 (会意。小篆字形,从采(矢)∠起来表示双手持簸箕清除污秽。本义扫除) 同本义 粪,弃除也。；组词：粪除(扫除)；粪洒(洒扫) 施肥 凡粪种', '小学', '1'),
    ('粮', 'liáng', '13', '米', '左右', NULL, '粮 (形声。从米,量声。本义旅行用的干粮;行军作战用的军粮) 同本义 紌,谷食也。--《说文》 桂馥曰谷也者,非古训。紌乃行者之干食。” 则治其紌与其食。--《周礼·地官·廪人》；组词：粮仗(粮草和兵器)；粮台(清代经理部队粮饷军需的机构) 引申指谷类；粮食 在陈绝紌', '小学', '1'),
    ('粱', 'liáng', '13', '米', '上下', NULL, '粱〈名〉 (形声。从米,梁省声。本义植物名。古代指粟的优良品种,子实也称粱,为细粮) 同本义 粱,米名也。；组词：粱糗(用稻粱制成的干粮)；粱菽(米与豆) 高粱 精美的饭食 粱liáng 1.〈古〉指粟的优良品种,视为美食', '小学', '1'),
    ('粹', 'cuì', '14', '米', '左右', NULL, '粹 (形声。从米,卒声。本义精米) 同本义 播精而择粹。--《天工开物》 精华 粹 不含添加、替代或异质物质的;纯的；组词：粹毛(纯色的毛)；粹正(纯正)；粹然(纯正的样子) 美好 粹 精通,擅长 粹 cuì 1不杂；纯', '小学', '1'),
    ('精', 'jīng', '14', '米', '左右', NULL, '精 (形声。从米,青声。本义挑选过的好米,上等细米) 同本义 精,择也。--《说文》 鼓筴播精。--《庄子·人间世》 食不厌精。--《论语》；组词：精凿(舂过的净米)；精粲(精米) 精气 祓除其心精也', '小学', '1'),
    ('糊', 'hú', '15', '米', '左右', NULL, '糊 〈动〉 涂抹 泛指遮掩 词缀 ∶叠用在形容词后加重程度。如黑糊糊,粘糊糊 糊 (形声。从米,胡声。本义同餬”。稠粥)', '小学', '1'),
    ('糕', 'gāo', '16', '米', '左右', NULL, '糕 (形声。从米,羔声。本义用米粉、面粉等为原料制成的一种食品) 同本义 糕(餻)gāo使用面粉或米粉等与其它食料搀和制成的食品蛋~。年~。糯米~。绿豆~。', '小学', '1'),
    ('糖', 'táng', '16', '米', '左右', NULL, '糖〈名〉 (形声。从米,唐声。本义食用糖及糖制食品的统称) 食糖。古代以麦作饴,即麦芽糖◇多用甘蔗、甜菜等制糖 糖,饴也。；组词：红糖；白糖；冰糖；糖餵(一种甜饼)；糖霜(细白沙糖)；糖馈(一种甜饼', '小学', '1'),
    ('糙', 'cāo', '16', '米', '左右', NULL, '糙 (形声。从米,造声。本义没有精碾的粗米) 脱壳未舂的谷,或米舂得不白的 毛糙,不光滑 不在乎或不注意精确性的 不贵重的,不值钱的 糙 cāo粗糙;不细致~米、活儿很~。', '小学', '1'),
    ('糜', 'mí', '17', '米', NULL, NULL, '糜子 糜 (形声。从米,麻声。本义粥) 同本义 糜,糁也。--《说文》 糜,煮米使糜烂也。--《释名·释饮食》 糜,糜粥。--《广韵》 粥之稠者曰糜；组词：糜沸(比喻世事混乱之甚,如糜粥之沸于釜中)；糜粥(粥) 糜 粉碎,捣烂 以糜敝之', '小学', '1'),
    ('糟', 'zāo', '17', '米', '左右', NULL, '糟 (形声。从米,曹声。从米,与制酒有关。本义古指未漉清的带滓的酒◇指酒渣) 同本义 糟,酒滓也。；组词：糟鼻子(酒糟鼻；红鼻子)；糟油(加入甜糟或酒糟调制的油', '小学', '1'),
    ('糠', 'kāng', '17', '米', '左右', NULL, '糠 (形声。从米,康声。本义从稻、麦等谷皮上脱下的皮、壳) 本作穅”,康”。谷的外壳 邻有糠槽而欲窃之。；组词：糠菜半年粮；糠覈(糠中的粗屑', '小学', '1'),
    ('糯', 'nuò', '20', '米', '左右', NULL, '糯 粘性稻 酒的别称 金荷,斟香糯。--汤显祖《牡丹亭》 糯 粘性的 糯(穤、穕)nuò稻的一种。碾出的米叫"糯米",粘性强,可制作糕点、糍粑等。', '小学', '1'),
    ('系', 'xì', '7', '糸', '上下', NULL, '系 ji 拴;系结 忽风云腾涌,急系缆。--陆游《过小孤山大孤山》 系之苇召。--《荀子·劝学》；组词：系腰(腰带)；系鞋带；把晾衣服绳系在树上；她的头发上系了一根红缎带；腰上系了一根紫色的...腰带；把卡片系在包上；把衣服', '小学', '1'),
    ('紊', 'wěn', '10', '糸', '上下', NULL, '紊 (形声。从糸,文声。本义乱) 同本义 紊,乱也。--《说文》 有条而不紊。--《书·盘庚上》；组词：紊纷(纷乱)；紊淆(紊乱)；紊弃(杂乱并弃失)；紊绪(混乱序分)；紊入(参杂进去)；紊淆(混乱) 繁盛 其运风,其化呜,', '小学', '1'),
    ('素', 'sù', '10', '糸', '上下', NULL, '素 (会意。小篆字形。上是垂”,下是糸。糸,丝。织物光润则易于下垂。本义没有染色的丝绸)；组词：素幭(古代盖在车前横木上的白绸)；素服缟冠(丧服,素、缟,指白绘) 用作写字的丝绸或纸张 英骨秀气,洒落毫素', '小学', '1'),
    ('索', 'suǒ', '10', '糸', '上下', NULL, '索 (会意。意为用绳子把木头束起。于省吾认为是绳索。本义大绳子) 同本义 索,草有茎叶可作绳索。；组词：索苇(用苇作成的绳索)；索头(绳头)；索桥(用绳索连结两岸的桥) 人的发辫 法度 皆启以商政,疆以周索', '小学', '1'),
    ('紧', 'jǐn', '10', '糸', NULL, NULL, '紧〈形〉 (会意。从舘,坚。从糸,细丝。本义缠丝急) 同本义 紧,缠丝急也。--《说文》 弛紧急之弦张兮。--傅毅《舞赋》 引申为物体受拉力或压力后呈现的紧张状态。同松”相对 )；组词：紧事(急事)；紧绸(紧凑；急促)；紧溜(急 紧(緊)jǐn 1.紧,跟"松"相对', '小学', '1'),
    ('紫', 'zǐ', '12', '糸', '上下', NULL, '紫 (形声。从糸,此声。本义紫色,蓝和红组成的颜色) 同本义 紫,帛黑赤色也。--《说文》 恶紫之夺朱也。--《论语》。孔注间色之好者。” 玄冠紫緌。--《礼记·玉藻》 紫衣狐裘；组词：紫棠色(黑里带红的颜色)；紫玉(紫色的宝玉；箫笛', '小学', '1'),
    ('累', 'lèi', '11', '糸', '上下', NULL, '累 (形声。从糸,表示与线丝有关,畾(雷)声。本义绳索) 同本义。也作缧” 累,一曰大索也。；组词：累绁(绑罪犯的绳索', '小学', '1'),
    ('絮', 'xù', '12', '糸', '上下', NULL, '絮 (形声。从糸,如声。本义粗丝绵) 同本义 絮,敝绵也。--《说文》。按,好者为绵,恶者为絮。 絮三斤。--《汉书·高帝纪》。古无木绵,以絮纳袷中,谓之装褚,曰袍。 剖其中；组词：絮衣(绵衣)；絮缯(丝帛之类的总称) 经过弹制的棉花胎 他们的婴孩没有棉衣,只好成天躺在土炕上那一堆破絮里', '小学', '1'),
    ('繁', 'fán', '17', '糸', '上下', NULL, '繁 緐,马髦饰也。--《说文》。段玉裁注引申为緐多。又俗改其字作繁,俗形行而本形废,引申之义行而本义废矣。” 繁〈形〉 众多 正月繁霜,我心忧伤。--《诗·小雅·正月》 奉之弥繁；组词：繁剧(事务繁重)；繁伙(众多)；繁星(众多的星星)；繁霜(浓霜,借喻为白色)；繁言(多言)；繁虑(很多的忧虑) 盛大；旺', '小学', '1'),
    ('纠', 'jiū', '5', '纟', '左右', NULL, '纠 (形声。从糸,表示与线丝有关,乴声。本义三股的绳子) 同本义 纠,绳三合也。--《说文》。按,俗字作糺。单股曰纫,两股曰纠,三股曰纠,亦曰徽。” 徽以纠墨；组词：纠纆(绳索', '小学', '1'),
    ('红', 'hóng', '6', '纟', '左右', NULL, '红 (形声。从糸,表示与线丝有关,工声。本义粉红色) 同本义 红,帛赤白色也。--《说文》。段注按,此今人所谓粉红、桃红也。” 缙红繎。--《急就篇》。颜注红,色赤而白也。” 红；组词：红衣(荷花瓣儿)；红香(花瓣)；红脂(蟹黄) 后也指各种红色 日出江花红胜火,春来江水绿如蓝', '小学', '1'),
    ('纤', 'xiān', '6', '纟', '左右', NULL, '纤 qian 用于拉船的绳索 我比不得他们扯篷拉纤的图银子。--《红楼梦》 又如纤道(江河两岸纤夫挽船前进的小路);纤路(纤道) 牵牲口的绳索 马牛有纤,私属有闲；组词：纤道(江河两岸纤夫挽船前进的小路)；纤路(纤道) 牵牲口的绳索 马牛有纤,私属有闲', '小学', '1'),
    ('约', 'yuē', '6', '纟', '左右', NULL, '约 (形声。从糸,勺声。糸是细丝,有缠束作用。本义绳索) 同本义 人寻约。--《左传》注；组词：寻约(八尺长的绳子) 共同商定的事,共同议定要遵守的条文 盟约；相期的诺言 负约不偿城', '小学', '1'),
    ('级', 'jí', '6', '纟', '左右', NULL, '级 (形声。从糸,表示与线丝有关,及声。本义丝的次第) 同本义 级,丝次弟也。--《说文》。段玉裁注本谓丝之次弟,故其字从系。引申为凡次弟之称。” 引申为等级；组词：超级(超过一般等级的)；震级(地震等级)；晋级(升到较高的等级)；级差级 (等级之间的差距) 石阶 乃领宾者延之而 级j', '小学', '1'),
    ('纪', 'jì', '6', '纟', '左右', NULL, '纪 (形声。从糸,表示与线丝有关,己声。本义散丝的头绪) 同本义 纪,别丝也。--《说文》 三纲六纪。纪者,理也。--《白虎通》 众之纪也。--《礼记·礼器》。注丝缕之数有纪；组词：乱其纪(事情乱了端绪) 要领 义也者,万事之纪也', '小学', '1'),
    ('纫', 'rèn', '6', '纟', '左右', NULL, '纫 (形声。从糸,刃声。本义搓绳) 同本义 纫,禅绳也。--《说文》。朱骏声曰凡单展曰纫,合绳曰纠, 织绳曰辫。” 纫针请补缀。--《礼记·内则》 纫秋兰以为佩,岂惟纫夫蕙茝；组词：纫佩(捻缀秋兰,佩带在身) 缝纫；缝补 公受珠,内所著披袄中,纫之', '小学', '1'),
    ('纬', 'wěi', '7', '纟', '左右', NULL, '纬 (形声。从糸,韦声。本义织横纱) 同本义 纬,织横丝也。--《说文》 恃纬萧而食者。--《庄子·列御寇》。释文织也。”；组词：纬萧(用蒿草编织窗帘子) 缠捆,系束 组织 治理 纬 纬纱；织物的横丝 东西向的道路或土地', '小学', '1'),
    ('纯', 'chún', '7', '纟', '左右', NULL, '纯 (形声。从糸,屯声。从糸”,表示与线丝有关。本义蚕丝) 同本义 纯,丝也。--《说文》 纯衣。--《仪礼·士冠礼》 被我纯缋。--《法言·孝至》；组词：纯衣(古时士的祭服,以丝为之) 同一颜色的丝织品 一色成体谓之醇,白黑杂合谓之驳', '小学', '1'),
    ('纱', 'shā', '7', '纟', '左右', NULL, '纱 (会意。从糸,从少。本义轻细的绢) 轻细的丝麻织物,古时多以蚕丝为之。古亦作沙” 白纱入缁,不染自黑。--汉·王充《论衡》 绸缎一百三十卷,纱绫一百八十卷。；组词：纱元(纸制的纱缎和元宝；祭品)；纱绢(细薄丝织品的通称；纱手帕)；纱罗(轻软细薄的丝织品的通称)；纱笼中人(喻命中富贵,', '小学', '1'),
    ('纲', 'gāng', '7', '纟', '左右', NULL, '纲 (形声。从糸,表示与线丝有关,冈声。本义提网的总绳) 同本义 纲,维紘绳也。--《说文》 若网在纲,有条而不紊。--《书·盘庚》 纲纪四方。--《诗·大雅·棫朴》。笺张之为纲；组词：纲挈目张(犹纲举目张)；纲提领挈(提起网纲,挈住裘领', '小学', '1'),
    ('纳', 'nà', '7', '纟', '左右', NULL, '纳 (形声。从糸,内声。本义丝被水浸湿) 同本义 纳,丝湿纳纳也。--《说文》 衣纳纳而掩露。--刘向《九叹·逢纷》；组词：纳纳(潮湿的样子) 收藏；收入 察纳雅言', '小学', '1'),
    ('纵', 'zòng', '7', '纟', '左右', NULL, '纵 (形声。从糸,从声。本义松缓) 同本义 纵,缓也。--《说文》 蓬发施纵,无形仪,不治家业。--《南齐书》；组词：纵缓(松懈)；纵弛(松懈；放松) 南北称纵,东西称横', '小学', '1'),
    ('纷', 'fēn', '7', '纟', '左右', NULL, '纷 (形声。从糸,分声。从糸”,表示与线丝等有关。本义马尾韬,扎束马尾的丝麻织物) 同本义 纷,马尾韬也。；组词：佩纷(佩饰丝带) 花边 次席纷纯,左右玉几', '小学', '1'),
    ('纸', 'zhǐ', '7', '纟', '左右', NULL, '纸 (形声。从糸,氏声。纸的原料本是破旧的丝绵,故从糸。本义纸张) 同本义 纸,絮也,一曰苫也。；组词：纸撚儿(用易燃纸搓成的点火纸卷儿)；纸标儿(纸做的出售标志)；纸筋(用于做纸浆的废纸)；纸阄(带有标记的纸片,用于拈韵)', '小学', '1'),
    ('纹', 'wén', '7', '纟', '左右', NULL, '纹 (形声。从糸,文声。本义丝织品上的花纹) 同本义 纹,绫纹也。--《玉篇》 纹,绫也。--《广韵》 作断纹焉。--明·刘基《郁离子·千里马篇》；组词：纹杇(丝织品的皱纹,常用来形容水波) 物品表面的皱痕,或指水面涟漪 皮肤上的纹理 主人,近三十岁的容貌,眉宇间已露艰辛的', '小学', '1'),
    ('纺', 'fǎng', '7', '纟', '左右', NULL, '纺 (形声。从糸,方声。本义将丝麻纤维制成纱或线) 同本义 纺,网丝也。--《说文》 纺焉以度而去之。--《左传·昭公十九年》 村南有夫妇守贫者,织纺井臼,佐读勤苦', '小学', '1'),
    ('纽', 'niǔ', '7', '纟', '左右', NULL, '纽 (形声。从糸,丑声。从糸,与丝线有关。本义指可解的结) 同本义 纽,系也。一曰结而可解。；组词：纽约(用以扣合衣服的纽结) 比喻事物的根本,关键 禹 舜之所纽也', '小学', '1'),
    ('线', 'xiàn', '8', '纟', '左右', NULL, '线 (形声。从糸,戔声。本义用棉麻丝毛等材料拈成的细缕) 同本义 线,缕也。--《说文》。按古文从糸,泉声。 中国不绝如线。--《公羊传·僖公四年》 爱惜起东西来；组词：线儿提的(提线木偶', '小学', '1'),
    ('练', 'liàn', '8', '纟', '左右', NULL, '练 (形声。从糸,表示与线丝有关,柬声。本义把生丝煮熟;亦指把麻或织品煮得柔而洁白) 同本义 练,湅缯也。；组词：练丝(未染色的熟丝) 练习；操演 练之禾定', '小学', '1'),
    ('组', 'zǔ', '8', '纟', '左右', NULL, '组 (形声。从糸,且声。与丝织品有关,故从糸。本义具有文采的宽丝带。古代多用作佩印或佩玉的绶)；组词：组帐(系以丝带的华丽帷帐)；组缨(系冠的丝带 组zǔ 1.〈古〉丝带,编织织~', '小学', '1'),
    ('绅', 'shēn', '8', '纟', '左右', NULL, '绅 (形声。从糸,申声。本义士大夫束在衣外的大带) 同本义 绅,大带也。--《说文》 绅,带也。--《广雅》。按,大带束腰,垂其余以为饰,谓之绅。 绅长制士三尺,有司二尺有五寸；组词：绅笏(大带与笏板)；绅带(古时士大夫束腰之大带)；绅緌(绅,大带；緌冠带之末端下垂部分', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('细', 'xì', '8', '纟', '左右', NULL, '细 (形声。从系,囟声。系,细丝。本义细小) 同本义⊥大”相对 细,微也。--《说文》。按,细者,细之微也。 细,小也。--《广雅》 细人之爱人也以姑息；组词：细崽(细作；西崽)；细人(细作；姬妾)；细探人(多指军队中的探子)；细士(小人) 纤细⊥粗”相 细xì 1.微,小,跟"', '小学', '1'),
    ('织', 'zhī', '8', '纟', '左右', NULL, '织 (形声。从糸,埴声。从糸”,与丝织品有关。本义织布,制作布帛的总称) 同本义 织,作布帛之总名也。；组词：织纸(纺织缝紝)；织紝(泛指织布', '小学', '1'),
    ('终', 'zhōng', '8', '纟', '左右', NULL, '终 (形声。从糸,冬声。甲骨文字形,象一束丝,两头象结扎的末端。本义把丝缠紧) 同本义 终,絿丝也。', '小学', '1'),
    ('绊', 'bàn', '8', '纟', '左右', NULL, '绊 羁绊;拘束;束缚 细推物理须行乐,何用浮荣绊此身。--杜甫《曲江二首》 今绊姜维于沓中,使不得东顾。；组词：绊脚(用绳子绑住脚) 走路或跑步时被别的东西挡住或缠住 被门槛子绊倒', '小学', '1'),
    ('绍', 'shào', '8', '纟', '左右', NULL, '绍 (形声。从糸,召声。本义继承;紧密连续) 同本义 绍,继也。--《说文》 绍庭上下。--《诗·周颂·访落》 弗念厥绍。--《诗·大雅·抑》 使寡君之绍续昆裔；组词：绍真(继承正统；统一天下)；绍天明命(承受上天之命)；绍衣(承服奉行先人的德化和教言)；绍兴(继续发扬光大；另县名) 介', '小学', '1'),
    ('绎', 'yì', '8', '纟', NULL, NULL, '绎 (形声。从糸,瞘声。本义抽丝) 同本义 绎,抽丝也。--《说文》 绎,理也。丝曰绎之。--《方言一》 绎,抽也。--《三苍》 引出头绪,寻求事理 陈述 庶言同则绎。--《书》；组词：绎志(抒陈自己的志向；书名) 陈列 射之为言者绎也,或曰舍也', '小学', '1'),
    ('经', 'jīng', '8', '纟', NULL, NULL, '泾 (形声。从水,巠声。本义泾水) 同本义 泾,泾水也。--《说文》 雍州其川,泾沬。--《周礼·职方氏》 泾以渭浊。--《诗·邶风·谷风》 渭水支流。有南、北二源', '小学', '1'),
    ('绑', 'bǎng', '9', '纟', '左右', NULL, '绑 (形声。从糸,邦声。古无此字。绑”字出现于元、明之间。本义捆,缚) 同本义 众军向前,用索绑缚住了。；组词：绑扎所(军队在战地特设为伤员包扎、治疗的处所)；绑缚(捆绑) 绑票 绑带,绑带儿 绑 bāng 用绳、带等缠或捆~腿', '小学', '1'),
    ('绒', 'róng', '9', '纟', '左右', NULL, '绒 (形声。从糸,戎声。本义鸟兽身上的柔毛) 同本义 被服) 丝、棉纱或羊毛等的纺织物 熟丝 绒,熟练丝。', '小学', '1'),
    ('结', 'jié', '9', '纟', '左右', NULL, '结 植物生长果实 结 坚硬;牢固 健壮 结 用绳、线、皮条等绾成的疙瘩 旧时向官府承担责任或承认了结的书面的字据 关键 诚信者,天下之结也。', '小学', '1'),
    ('绕', 'rào', '9', '纟', '左右', NULL, '绕 (形声。从糸,尧声。本义缠束) 同本义 绕,缠也。--《说文》 绕黄山而款牛首。--张衡《西京赋》。注裹也。”；组词：把丝绕在卷筒上；绕搭(缠绕)；绕缭(缭绕,盘旋围绕)；绕手(犹棘手)；绕网(陷入罗网)；绕结(回旋缠结) 环绕 白水绕东', '小学', '1'),
    ('绘', 'huì', '9', '纟', '左右', NULL, '绘 (从糸(与线丝有关),会声。本义五彩绣品) 同本义。也作会” 绘,会五采绣也。--《说文》 杂彩曰绘。--《小尔雅·广训》 山龙华虫作绘。--《虞书》；组词：绘绚(彩绘绚丽) 绘 绘画 自绘败状', '小学', '1'),
    ('给', 'gěi', '9', '纟', '左右', NULL, '给 gei 使对方得到或遭受到 让;使;叫 给 表示对象、目的,相当于为”、替” 给伤员包扎 引进动作行为的主动者,或表示被动语态,相当于被” 表示方向,相当于朝”、对”', '小学', '1'),
    ('络', 'luò', '9', '纟', '左右', NULL, '络子 lao 倒不如打个络子,把玉络上呢。--《红楼梦》 络 (形声。从糸,表示与丝线有关。各声。本义缠绕,捆缚)；组词：络着手(缠 络lào 1.网状的东西', '小学', '1'),
    ('绝', 'jué', '9', '纟', '左右', NULL, '绝 (会意。从糸,表示与线丝有关,从刀,从卩(人)。表示人用刀断丝。本义把丝弄断) 同本义 绝,断丝也。；组词：绝缨(冠缨断绝', '小学', '1'),
    ('绞', 'jiǎo', '9', '纟', '左右', NULL, '绞〈动〉 (会意。从交,从糸,表示与线丝有关,交亦声。本义用两股以上的细长条扭结成一根绳索;扭,拧)；组词：绞带(古代丧礼中所系麻带)；绞绡(生丝织成的薄纱、薄绸)；把铁丝绞在一起；绞汁(挤压汁水)；绞巾(拧毛巾) 缠绕 根绞怪', '小学', '1'),
    ('统', 'tǒng', '9', '纟', '左右', NULL, '统 (形声。从糸,充声。本义丝的头绪) 同本义 统,纪也。--《说文》 茧之性为丝,然非得工女煮以热汤而抽其统纪。--《淮南子·泰族训》；组词：统绪(头绪) 世代相继的系统 求其统类', '小学', '1'),
    ('绢', 'juàn', '10', '纟', '左右', NULL, '绢 (形声。从糸,胦声。本义生丝织物●而疏者称绢) 同本义 绢,缯如麦绢者。从糸,胦声。谓粗厚之丝为之。；组词：绢地(书画之绢底)；绢帖(以绢作底的书帖)；绢丝(织纺工程的产品', '小学', '1'),
    ('绣', 'xiù', '10', '纟', '左右', NULL, '绣 (形声。从糸,秀声。从糸”与丝织有关。本义刺绣) 同本义 绣,五采备也。--《说文》。按考工记,以言画缋之事。则凡黹与画之五采备者,皆曰绣也。 絺绣。--《书·益稷》；组词：绣幌(乡花的帷幔,窗帘)；绣鹄(锦绣的飞禽图梆)；绣鹄(绣花的头巾)；绣佛(用彩色的丝刺绣成 绣(纁)xiù 1.用彩色', '小学', '1'),
    ('继', 'jì', '10', '纟', NULL, NULL, '继 同本义(把断了的丝接续上) 继,续也。--《说文》 大人以继明照于四方。--《易·象传》。注谓不绝也。” 折琼枝以继佩。--《楚辞·离骚》 齐人未尝赂秦,终继五国迁灭；组词：继继(前后相继,接续不断)；继踪(继续前人所做的事)；继踵(步履前后相接', '小学', '1'),
    ('绩', 'jì', '11', '纟', '左右', NULL, '绩 把麻纤维披开接续起来搓成线 绩,缉也。从糸,责声。--《说文》 不绩其麻。--《诗·陈风·东门之枌》 八月载绩。--《诗·豳风·七月》。传载绩,丝事毕而麻事起矣；组词：绩绪(搓麻线)；绩女(纺织的女郎)；绩火(夜晚纺织时用来照明的灯火)；绩纺(泛指纺纱,绩麻诸事', '小学', '1'),
    ('绪', 'xù', '11', '纟', '左右', NULL, '绪 (形声。从糸,者声。本义丝的头) 同本义 绪,丝端也。--《说文》 凡茧滚沸时,以竹签拨动水面丝绪。--《天工开物》；组词：绪余(抽丝后留在蚕茧上的残丝) 头绪,开端 反覆终始,不知其端绪', '小学', '1'),
    ('续', 'xù', '11', '纟', '左右', NULL, '续 (形声。从糸,卖声。本义连接起来,接上) 同本义 续,联也。--《说文》 续,继也。--《尔雅》 续衽钩边。--《礼记·深衣》 貂不足,狗尾续；组词：续弦；续篇；续编 继续 岁时更续', '小学', '1'),
    ('绰', 'chuō', '11', '纟', '左右', NULL, '绰 chuo (形声。从糸,卓声。本义宽大,舒缓) 同本义 宽兮绰兮。--《诗·卫风·淇奥》；组词：绰步(大步)；绰板婆(大脚婆娘)；绰绰(宽舒裕如) 姿态柔美 柔情绰态,媚于语言', '小学', '1'),
    ('绳', 'shéng', '11', '纟', '左右', NULL, '绳 (形声。从糸,蝇省声。本义绳子) 同本义 绳,索也。--《说文》 大者谓之索,小者谓之绳。--《小尔雅》 巽为绳直。--《易·说卦》 作结绳而为网罟；组词：绳床(交床；交椅)；绳缢跌扑(用绳子吊死,跌倒摔死)；绳文(文字未创造以前,结绳代替文字,称为绳文)；绳桥(用绳索连结两', '小学', '1'),
    ('维', 'wéi', '11', '纟', '左右', NULL, '维 (形声。从糸,隹声。本义系物的大绳) 同本义 维,紘也。--《玉篇》 维,车盖系也。--《说文》 维,系也。--《广雅》 斡维焉系。--《楚辞·天问》 维王之大常；组词：维纲(用以系物和提网的绳', '小学', '1'),
    ('绵', 'mián', '11', '纟', '左右', NULL, '绵 (会意。从帛,从糸。本义丝棉,精丝绵,新丝绵) 同义 绛缇絓紬丝絮绵。--《急就篇》。颜注渍茧擘之,精者为绵,粗者为絮。今则谓新者为绵,故者为絮。” 身衣布衣,木緜皁帐；组词：绵子(丝绵)；绵衣(内装丝绵的衣服)；绵帛(丝绵绢帛的总称)；绵矩(加工丝绵的工具) 通棉” 丝絮状物 想见东郊携手日,', '小学', '1'),
    ('绷', 'bēng', '11', '纟', '左右', NULL, '绷 (形声。从糸),朋声。本义束缚,捆绑) 缠束;包扎 繃,束也。--《说文》 禹葬会稽,桐棺三寸,葛以繃之。--《墨子·节葬篇》 襁,即今儿小儿繃也。今俗犹云繃小儿矣；组词：绷吊拷讯(捆绑并吊起来拷问)；绷爬吊拷,绷巴吊拷,绷扒吊拷(强行脱衣服,捆好吊起来拷打) 张紧,在两端或边上用力造成平直', '小学', '1'),
    ('绸', 'chóu', '11', '纟', '左右', NULL, '绸 (形声。从糸,周声。本义缠绕) 同本义 绸,缪也。--《说文》 绸,缠也。--《广雅》 绸缪束薪,三星在天。--《诗·唐风·绸缪》。毛传绸缪犹缠绵也。” 捆缚 薜荔柏兮蕙绸；组词：绸直(情情慎密,操行正直)；绸沓(密集) 绸 chóu薄而软的丝织品~缎、红~', '小学', '1'),
    ('综', 'zōng', '11', '纟', '左右', NULL, '综 zeng 织布机上使经线上下交错以受纬线的一种装置 推而往,引而来者,综也。--《古列女传》 综 (形声。从金,呈声。本义器物经磨擦后闪光耀眼)', '小学', '1'),
    ('绽', 'zhàn', '11', '纟', '左右', NULL, '绽 (形声。从糸,定声。糸,细丝。本义衣服裂开) 同本义 衣裳绽裂。--《礼记·内则》 又如绽破(衣缝裂开);将绽(衣缝快要裂开) 皮肉破裂 饱满、开裂。特指花果 春色方盈野；组词：绽破(衣缝裂开)；将绽(衣缝快要裂开) 皮肉破裂 饱满、开裂', '小学', '1'),
    ('绿', 'lǜ', '11', '纟', '左右', NULL, '绿 lu 通菉”。一种野菜 终朝采绿,不盈一掬。--《诗·小雅·绿竹猗猗》 河出绿图,地出乘黄。--《墨子》 又用于绿林(绿林山)、绿营(清代汉人地方武装)', '小学', '1'),
    ('缀', 'zhuì', '11', '纟', '左右', NULL, '缀 同本义 缀,合箸也。--《说文》 缀衣。--《书·立政》。传掌衣服。” 出缀衣于庭。--《书·顾命》 为下国缀旒。--《诗·大雅·长发》 缀甲厉兵。--《战国策·秦策一》；组词：缀甲(缝制甲衣)；缀拾(采集连缀)；缀纯(连缀杂彩以为缘边)；缀葺(修补；缝补)；缀缀(相连缀的样子) 著作', '小学', '1'),
    ('缅', 'miǎn', '12', '纟', '左右', NULL, '缅 (形声。从糸,面声。本义微丝) 同本义 缅,微丝也。--《说文》 缅甸的简称 缅 遥远 举下缅也。--《谷梁传·庄公三年》 缅然引领南望。--《国语·楚语》；组词：缅然(遥远的样子)；缅求(远求)；缅渺(遥远的样子)；缅远(久远；辽远；遥远)；缅迈(远行) 尽貌 冀阙缅其堙尽', '小学', '1'),
    ('缆', 'lǎn', '12', '纟', '左右', NULL, '缆 (形声。从糸,表示与线丝有关,览声。本义系船用的粗绳) 同本义 结缆排鱼网。--杜甫《舟中》；组词：新船砍缆下水 许多股绞成的粗绳 缆 拴；系 急系缆', '小学', '1'),
    ('缎', 'duàn', '12', '纟', '左右', NULL, '缎 (形声。从糸,段声。本义缝贴于鞋跟的革片、丝绦之类) 同本义 履舄鞜襞绒缎紃。--《急就篇》 一种质地厚密而有光泽的丝织物 诏赐抚臣名马衣缎。--《聊斋志异·促织》；组词：缎疋(缎的总称', '小学', '1'),
    ('缓', 'huǎn', '12', '纟', '左右', NULL, '缓 (形声。从糸,爰声。本义宽松;宽大) 同本义 慢;不急迫。与急”相对 缓,舒也。--《广韵》 夫人于事己者过急,于事人者过缓。--《战国策·卫策》 民事不可缓也；组词：缓缓(缓慢的样子', '小学', '1'),
    ('缔', 'dì', '12', '纟', '左右', NULL, '缔 (形声。从糸,帝声。本义结在一起) 同本义 缔,结不解也。--《说文》 合从缔交。--贾谊《过秦论》。注连接也。” 缔交翩翩。--左思《吴都赋》；组词：缔婚(结婚)；缔生(联结而生)；缔连(联结) 引申为郁结 气缭转而自缔', '小学', '1'),
    ('缕', 'lǚ', '12', '纟', '左右', NULL, '缕 (形声。从糸,表示与线丝有关。娄声。本义麻线) 同本义 缕,线也。--《说文》。段注凡蚕者为丝,麻者为缕。” 麻缕丝絮轻重同,则贾相若。--《孟子·滕文公上》 有布缕之征；组词：缕綦(用线织綦)；缕緕(用各色不同的线缕成其文采) 泛指细而长的东西,线状物 汉氏诸陵无不发掘,乃至烧取玉匣金缕', '小学', '1'),
    ('编', 'biān', '12', '纟', '左右', NULL, '编 (形声。从糸),扁声。本义顺次排列,编结在一起) 同本义 编,次简也。--《说文》 以绳次物曰编。--《声类》 春秋编年,四时具而后为年；组词：编号；编组；编队；编户(编入户籍的普通人家)；编民(编入户籍的平民)；编人(户籍编制之内的贫民', '小学', '1'),
    ('缘', 'yuán', '12', '纟', '左右', NULL, '缘 器物的边沿 低下头去把嘴唇搁在杯缘。--茅盾《蚀·追求》 又如缘石(砌筑在车行道与人行道之间的长条形石块或混凝土块,用以保护人行道并使车行道的路边水流通畅);缘海(边缘海；组词：缘石(砌筑在车行道与人行道之间的长条形石块或混凝土块,用以保护人行道并使车行道的路边水流通畅)；缘海(边缘海；沿海,接海', '小学', '1'),
    ('缚', 'fù', '13', '纟', '左右', NULL, '缚 (形声。从糸,表示与线丝或缠织等有关。尃声。本义捆绑) 同本义 缚,束也。--《说文》 战之明日,晋襄公缚秦囚。--《左传·文公二年》 主缚者亦然,不如所欲,缚时即先折筋骨；组词：缚人(捆绑人)；缚绑(捆绑)；缚住(捆住)；缚虎(捆住猛虎', '小学', '1'),
    ('缝', 'féng', '13', '纟', '左右', NULL, '缝 (形声。从糸,表示与线丝等有关, 逢声。本义以针线连缀) 同本义 缝,以针紩衣也。--《说文》 缝,合也。--《广雅》 缝齐倍要。--《礼记·玉藻》。注紩也。” 可以缝裳；组词：缝衣(缝制衣服)；缝刺(缝纫与刺绣)；缝缉(缝纫)；缝织(缝纫编织) 补合 缝 缝合处 古者冠缩缝,今也衡缝', '小学', '1'),
    ('缠', 'chán', '13', '纟', '左右', NULL, '缠 (形声。从糸,廛)声。本义围绕,缠绕) 同本义 缠,绕也。--《说文》 臣有所与供儋缠采薪者九方鄄。--《淮南子·道应》 动胃缠缘。--《史记·扁仓传》。正义谓脉缰绕胃也；组词：缠裹(缠绕裹束；衣著,装束) 纠缠；搅扰 应付；对付 缠 chán 1缠绕~脚', '小学', '1'),
    ('缤', 'bīn', '13', '纟', '左右', NULL, '缤 (形声。从糸,宾声。本义繁盛,众多) 同本义 芳草鲜美,落英缤纷。--晋·陶渊明《桃花源记》；组词：缤翻(繁盛的样子) 紊乱 时缤纷其变易兮', '小学', '1'),
    ('缨', 'yīng', '14', '纟', '左右', NULL, '缨 (形声。从糸,婴声。本义系在脖子上的帽带) 同本义 缨,冠系也。--《说文》 鲜冠组缨,绛衣博袍。--《墨子·公孟》 正冠而缨绝。--《庄子·让王》 沧浪之水清兮,可以濯吾缨；组词：缨冠(把帽带连同帽子一齐加于头上', '小学', '1'),
    ('缩', 'suō', '14', '纟', '左右', NULL, '缩 (形声。从糸,宿声。糸,细丝,与绳索有关。本义捆束) 同本义 其绳则直,缩版以载。--《诗·大雅·緜》 缩,乱也。--《说文》。朱曰许书之乱字皆治也,理也。此说解及尔雅之乱；组词：缩栗(冷缩颤栗)；缩气(收敛气焰)；缩瑟(瑟缩', '小学', '1'),
    ('缭', 'liáo', '15', '纟', '左右', NULL, '缭 (形声。从糸,表示与丝有关尞声。本义缠绕) 同本义 缭,缠也。--《说文》 再缭四寸。--《礼记·玉藻》。疏绕也。” 弗缭。--《仪礼·乡饮酒礼》。注犹絞也；组词：缭肘(即镣?”', '小学', '1'),
    ('缰', 'jiāng', '16', '纟', '左右', NULL, '缰 马缰绳 缰,马绁也。--《说文》 缰,疆也,系之使不得出疆限也。--《释名·释车》 青骢白马紫丝缰。--《乐府诗集》；组词：脱缰；信马由缰 缰绳 缰(韁)jiāng 缰绳,拴系牲口的绳子信马由~', '小学', '1'),
    ('缴', 'jiǎo', '16', '纟', '左右', NULL, '缴〈动〉 (形声。从糸,表示与线丝有关。敫声。1本义系在箭上的生丝绳,射鸟用。2缴绕缠绕,纠缠不清) 缠绕 名家苛察缴绕。；组词：缴臁(绑脚布)；缴壁(墙帏)；缴绕(纷乱,纠缠)；缴消(公事办理完毕后消清手续)；缴缠(纠缠；缠绕) 交纳 扭动；搅动', '小学', '1'),
    ('缸', 'gāng', '9', '缶', '左右', NULL, '缸 (形声。从缶,表示与瓦器有关,工声。本义瓦制长颈容器,可受十升) 大口而常无颈的陶器 醯酱千缸。；组词：水缸；缸砚(用酒缸碎片制成的砚台)；缸面酒(用缸酿制的酒) 像缸的器物 用同鈍”', '小学', '1'),
    ('缺', 'quē', '10', '缶', '左右', NULL, '缺〈形〉 (形声。从缶,夬声。缶,瓦器。夬”也有表意作用。水缺为决”,玉缺为玦”,器缺为缺”,都有破损之意。本义器具破损)；组词：墙缺了一块；缺落(破损剥落)；缺啮(折角,破损)；缺坏(破缺损坏)；缺触(残缺剥蚀)；缺唇(又叫缺嘴”,上唇缺损', '小学', '1'),
    ('罐', 'guàn', '23', '缶', '左右', NULL, '罐 (形声。从缶,雚声。从缶”,表示与瓦器有关。本义用陶或金属制成的汲水器、容器) 同本义 煤矿装煤用的斗车 罐车 罐笼 罐头 罐(罆、鑵)guàn 1.汲水', '小学', '1'),
    ('网', 'wǎng', '6', '网', '半包围', NULL, '网 (象形。网”捕鸟兽的叫网”,捕鱼的叫罟。笼统地说,两字没有不同。本义捕鱼鳖鸟兽的工具)；组词：鱼网(捕鱼用的网)；网户(渔家)；网密(网目细密)；网丝(蜘蛛网)；网虫(指蜘蛛)；网羈(捕鱼之网)；网羘9(鱼网) 泛', '小学', '1'),
    ('罕', 'hǎn', '7', '冖', '上下', NULL, '罕 (古字为爳”。形声。小篆字形,从网,干声。本义捕鸟用的长柄小网) 同本义 爳,网也。《说文》 罕车飞扬。--扬雄《羽猎赋》 毕曰罕车,主弋猎。；组词：罕车(载有猎狩等网具的车；星宿名,毕宿的别名', '小学', '1'),
    ('罗', 'luó', '8', '罒', '上下', NULL, '罗 (会意。甲骨文字形,象网中有隹,表示以网捕鸟的意思。小篆增加了糸”,表示结网所用的材料。本义用绳线结成的捕鸟网)；组词：罗尉(捕鸟的网)；罗落(截捕禽兽的用具)；罗弋(捕鸟的工具) 轻软的丝织品 遍身罗绮', '小学', '1'),
    ('罚', 'fá', '9', '罒', '上下', NULL, '罚 (会意。小篆字,从刀,从詈。刀”指刑法。本义处罚,惩办) 同本义 羛,罪之小者。从刀、从詈,会意。未以刀有所贼,但持刀骂詈则应罚。；组词：罚规(处罚的规章)；罚约(输者受罚的约定 罚(羥) fá处分,惩处惩~', '小学', '1'),
    ('罢', 'bà', '10', '罒', '上下', NULL, '罢 (会意。从网,从能。表示用网捕住有贤能的人。网”在字的上部楷书多写作罒”。本义罢官;免去;解除)；组词：罢谢(辞官去职)；罢归(辞职或免官归里) 遣返,遣归 停止 罢 bà 1中止某种活动~课、~工', '小学', '1'),
    ('罩', 'zhào', '13', '罒', '上下', NULL, '罩 (形声。从网,卓声。本义捕鱼的竹笼) 同本义 持罩入深水,金鳞大如手。--唐·温庭筠《罩鱼歌》；组词：罩罗(泛指捕鱼或捕鸟的竹器)；罩笼(泛指捕鱼的竹器) 捕鸟的竹笼或掩网 弛罩出凤雏', '小学', '1'),
    ('罪', 'zuì', '13', '罒', '上下', NULL, '罪 (会意。从辛,从自,言罪人蹙鼻苦辛之忧,自亦声。本义作恶或犯法的行为) 同本义 辠,犯法也。；组词：罪首(罪魁祸首)；罪失(罪愆和过 罪(辠)zuì 1.犯法,犯法的行为~犯', '小学', '1'),
    ('置', 'zhì', '13', '罒', '上下', NULL, '置 (会意。从网直,有亦声。网直宜赦。本义赦罪,释放) 同本义 置,赦也。--《说文》 见十置一。--《汉书·尹赏传》。注放也。” 高帝曰置之。”乃释通之罪；组词：置锥之地(安身立足之地)；置室(安置妻室；取妻)；置酒(陈 置(寘)zhì 1.搁,摆,设,安放~若罔闻', '小学', '1'),
    ('署', 'shǔ', '13', '罒', '上下', NULL, '署 (形声。从网,者声。部署任务,各有系统,故从网。本义布置;部署) 同本义 署,都署有所系属。；组词：部署(安排；布置)；署用(署理任用)；署事(处理事务)；署置(设置官署任用官吏) 签名,签署 吏呼名至史公,公瞿然注视,', '小学', '1'),
    ('羊', 'yáng', '6', '羊', NULL, NULL, '羊 (象形。甲骨文字形,像羊头形。羊”是汉字的一个部首。本义一种哺乳动物) 同本义 羊,羊兽也。；组词：羊群里跑出骆驼来(喻指平常的人忽然变成了出类拔萃的人物了)；羊群蚁阵(形容众多而聚集)；羊酒花红(丰厚的赏赐和显赫的荣耀', '小学', '1'),
    ('美', 'měi', '9', '羊', '上下', NULL, '美 (会意。金文字形,从羊,从大,古人以羊为主要副食品,肥壮的羊吃起来味很美。本义味美)；组词：美酒；美甘甘(形容非常甘美或甜蜜)；美味(美好的滋味；可口的食品)；美食(味美的食品；吃味美的食物) 形貌好看,漂亮 美', '小学', '1'),
    ('羔', 'gāo', '10', '灬', '上下', NULL, '羔 (会意。从羊,从火,下面的四点由火”变来。甲骨文字形正象羊在火上。本义小羊) 同本义 羔,羊子也。；组词：羔裘(古代诸侯用为朝服的小羊皮袍)；羔雁(羔羊和大雁；为订婚的一种礼物；古代用为卿、大夫的贽礼)；羔币(古代用羔皮作币帛', '小学', '1'),
    ('羞', 'xiū', '10', '羊', NULL, NULL, '羞 (会意兼形声。据甲骨文,以手持羊,表示进献。小篆从羊,从丑,丑亦声。丑”是手的讹变。本义进献)；组词：羞豆(古代祭祀宴享时进献食物的一种盛器)；羞膳(进献食品) 推荐；进用 有武德以羞为正卿', '小学', '1'),
    ('羡', 'xiàn', '12', '羊', '上下', NULL, '羡 (会意。本义羡慕,因喜爱而希望得到) 同本义 羡,贪欲也。--《说文》 羡,贪慕也。--《广韵》 慕欲曰羡。--《字林》 帝谓文王,无然畔援,无然歆羡；组词：歆羡(羡慕)；艳羡(十分羡慕)；称羡(称赞羡慕)；欣羡(喜爱而羡慕)；叹羡(赞叹羡慕) 超过,盖过 德隆乎三皇,功羡于五', '小学', '1'),
    ('群', 'qún', '13', '羊', '左右', NULL, '群 (形声。从羊,君声。本义羊群;兽群;人群) 三个以上的禽兽相聚而成的集体 群,辈也。--《说文》 兽三为群。--《国语·周语》 或群或友。--《诗·小雅·吉日》 三百维群；组词：群才(有才能的人们)；群生(一切生物)；群立(站立在人群中)；群有(佛教指众生或万物)；群儿(一群小儿', '小学', '1'),
    ('羹', 'gēng', '19', '羊', '上下', NULL, '羹〈名〉 (会意。从羔,从美。古人的主要肉食是羊肉,所以用羔”美”会意,表示肉的味道鲜美。用肉或菜调和五味做成的带汁的食物。《说文》五味和羹。”按上古的羹”, 一般是指带汁的肉；组词：菜羹(煮熟的菜,加上米屑,古代贫者所食 羹gēng 1用肉类或菜蔬等制成的带浓汁的食物', '小学', '1'),
    ('羽', 'yǔ', '6', '羽', '左右', NULL, '羽 (象形。甲骨文字形,象羽毛形,即鸟的长翎形。羽”是汉字的一个部首,从羽”的字多与羽毛有关。本义鸟毛,特指鸟的长毛)；组词：羽葆鼓吹(仪仗乐队)；羽葆翠盖(以翠羽连缀为饰的华丽车盖)；羽葆花旌(仪仗旗帜)；羽仪廊庙(指受到朝廷重视,其德行为满朝', '小学', '1'),
    ('翁', 'wēng', '10', '羽', '上下', NULL, '翁 (形声。从羽,公声。本义鸟颈毛) 同本义 翁,颈毛也。--《说文》 鸟头上毛曰翁。翁,一身之最上。--唐·玄应《一切经音义》 祖父 假借为公”。父亲 翁,父也；组词：翁媪(年老的父母', '小学', '1'),
    ('翅', 'chì', '10', '羽', '半包围', NULL, '翅 (形声。从羽,支声。本义鸟类、昆虫的翅膀) 同本义 翅,翼也。--《说文》 审视,巨身修尾,青项金翅。--《聊斋志异·促织》；组词：翅关(翅膀)；翅趫(像张开两翼的样子)；翅羽(鸟类两翅上的长羽) 翼状物', '小学', '1'),
    ('翎', 'líng', '11', '羽', '左右', NULL, '翎〈名〉 (形声。从羽,令声。本义翎毛,鸟翅和尾上的长羽毛) 同本义 何当有翅翎,飞去堕尔前!--杜甫《彭衙行》 如翎篁(指羽毛。借指毛发);翎羽(指鸟羽)', '小学', '1'),
    ('翔', 'xiáng', '12', '羽', '左右', NULL, '翔 (形声。从羽,羊声。本义翅膀平直不动盘旋地飞) 同本义 翔,回飞也。--《说文》 鸢鸟丑其飞也翔。--《尔雅·释鸟》 凤以之翔。--《淮南子·原道》。注大飞不动曰翔；组词：翱翔(在空中回旋地飞)；翔回(回旋飞翔)', '小学', '1'),
    ('翘', 'qiào', '12', '羽', '半包围', NULL, '翘 (形声。从羽,尧声。羽,鸟毛。本义鸟尾上的长羽) 同本义 翘,尾长毛也。--《说文》 斑尾扬翘。--潘岳《射雉赋》 砥室翠翘,挂曲琼些。--《楚辞·招魂》；组词：翠翘(用翠鸟尾羽做的拂尘用具)；翘英(华丽的尾羽) 鸟尾 摇翘奋羽,驰风骋雨,游无穷兮', '小学', '1'),
    ('翠', 'cuì', '14', '羽', '上下', NULL, '翠 (形声。从羽,卒声。本义翠鸟) 鸟名,翠鸟。又专指雌性的翠鸟 又如翠以羽自残(翡翠鸟因羽色之美而被残杀。比喻人因有才而遭嫉害);翠毛(翠鸟的羽毛);翠羽(翠鸟的羽毛；组词：翠以羽自残(翡翠鸟因羽色之美而被残杀', '小学', '1'),
    ('翩', 'piān', '15', '羽', '左右', NULL, '翩〈形〉 (形声。从羽,扁声。本义疾飞的样子) 同本义 翩,疾飞也。--《说文》 翩扇不富。--《易·泰卦》 翩彼飞鴞。--《诗·鲁颂·泮水》 众鸟翩翻；组词：翩联(共飞的样子；联翩；结姻)；翩飞(轻快地飞舞)；翩旋(轻快地飞舞) 轻舞,飘扬 又如翩翻(飘动、摇曳的样子)；翩连(', '小学', '1'),
    ('翰', 'hàn', '16', '羽', '左右', NULL, '翰 (形声。从羽,倝声。本义天鸡,也叫锦鸡或山鸡) 同本义 翰,天鸡,赤羽也。--《说文》 蜀人以文翰;文翰者,若皋鸡。--《逸周书·王会》；组词：翰音(鸟的叫声上达于天,而鸟仍旧在地', '小学', '1'),
    ('翻', 'fān', '18', '羽', '左右', NULL, '翻〈动〉 (形声。从羽,番声。本义鸟飞) 同本义 青菰临水映,白鸟向山翻。--王维《辋川闲居》；组词：翻泊(或飞或止)；翻翔(翻飞,飞翔)；翻簸(飞驰) 翻转；翻腾 波翻晓霞影', '小学', '1'),
    ('翼', 'yì', '17', '羽', '上下', NULL, '翼 (形声。从羽,異声。《说文》小篆从飞,異声。本义翅膀) 同本义 翼,翅也。--《说文》 六足四翼。--《战国策·楚策》 三年不翅,将以长羽翼；组词：翼虎(添上翅膀的老虎)；翼张(如鸟展翅', '小学', '1'),
    ('耀', 'yào', '20', '羽', '左右', NULL, '耀 (形声。从光,翟声。本义照耀) 同本义 耀,照也。--《说文》 焜燿寡人之望。--《左传·昭公三年》 以淳耀燿大。--《国语·郑语》 星耀而玄运；组词：耀目晶光(光彩夺目)；耀夜(萤火虫的别名)；耀芒(光芒照射)；耀采(光彩照耀)；耀亮(照亮)；耀燿(光辉照耀) 晃眼 炫', '小学', '1'),
    ('老', 'lǎo', '6', '老', '上下', NULL, '老〈形〉 (会意。甲骨文字形,象一个手里拿着拐杖的老人形。本义年老,衰老) 五十至七十岁的高龄 老,考也。七十曰老。；组词：老钝(年老迟钝)；老家人(老仆人)；老院子(老仆人)；老丹青(老画 老lǎo 1.年纪大 1跟"少"、"幼"相对百岁~人', '小学', '1'),
    ('考', 'kǎo', '6', '聅', NULL, NULL, '考 (形声。从老省,丂声。按甲骨文、金文均象偻背老人扶杖而行之状,与老同义。本义老,年纪大)；组词：考寿(长寿)；考终(考终年)；考终年(享尽天年) 考 去世的父亲 父为考', '小学', '1'),
    ('者', 'zhě', '8', '聅', NULL, NULL, '者 (《说文》别事词也。相当于这”) 同本义 那边走,者边走,莫厌金杯酒。--五代·王衍《醉妆词》；组词：者回(这回)；者般(这般)；者流(犹言这个流派)；者番(这番；这次)；者里(这里)；者个(这个)；者边(这边) 用在形容', '小学', '1'),
    ('而', 'ér', '6', '而', NULL, NULL, '而 (象形。小篆字形,象胡须形。上面的一”表示鼻端,|”表示人中;下面分内外两层,外层象两腮的胡子,内层象生在嘴下的胡子。而”是汉字部首之一。本义颊毛) 同本 义 而,颊毛也', '小学', '1'),
    ('耍', 'shuǎ', '9', '而', '上下', NULL, '耍 (会意。从而,从女。而,颊毛。盖谓用颊毛戏弄女子。本义戏耍。一般指不正当的行为) 玩耍,游玩;消闲取乐 长颦知有恨,贪耍不成妆。--宋·周邦彦《意难忘》 一群猴子耍了一会；组词：耍水(玩水,游泳)；耍货(玩具)；耍拳(打拳)；耍歇(玩耍休息) 戏谑；捉弄 等他来时,诱他去粪窖边,只做参贺他,双手抢', '小学', '1'),
    ('耐', 'nai', '9', '而', '左右', NULL, '耐〈动〉 (会意。从而,从寸。而亦声。而”指面颊,寸”指法度,刑法。在面颊上施刑罚,指剃须。字本作聐”。从而,从彡。本义古时一种剃掉胡须两年的刑罚)；组词：耐罪(古代剃去鬓须的刑罚', '小学', '1'),
    ('耕', 'gēng', '10', '耒', '左右', NULL, '耕 (形声。从耒,井声。从耒”,表示与耕作有关。本义犁田) 同本义。翻松田土 耕,治田也。；组词：耕食(依赖耕田为生)；耕桑(耕田、种谷、植桑、养蚕', '小学', '1'),
    ('耗', 'hào', '10', '耒', '左右', NULL, '耗〈名〉 (形声。从耒,毛声。本义一种稻子) 消息;音信 赤岭久无耗,鸿门犹合围。--李商隐《即日》；组词：耗音(音耗,音信,消息)；耗问(消息；音信)；耗息(消息)；恶耗,凶耗 方言称老鼠为耗子”', '小学', '1'),
    ('耘', 'yún', '10', '耒', '左右', NULL, '耘 (形声。从耒,云声。本义除草) 同本义 植杖而耘耔。--晋·陶渊明《归去来兮辞》 又如耘艾(耕耘与收割。艾同刈);耘耔(翻土除草,指农耕);耘治(锄草治田)；组词：耘艾(耕耘与收割', '小学', '1'),
    ('耙', 'pá', '10', '耒', '左右', NULL, '耙 用于碎土、平地和消灭杂草的整地农具 耙 用耙碎土平地 耙地 耙路机 耙 bà 1用以碎土和整地的农具。有钉齿和圆盘耙等。 2用耙弄碎土块这块地还没~。又见pá。 耙pá 1.', '小学', '1'),
    ('耳', 'ěr', '6', '耳', NULL, NULL, '耳 (象形。甲骨文字形,象耳朵形『字部首之一。本义耳朵) 同本义 耳,主听也。--《说文》 耳者,肾之候。--《白虎通·情性》 耳者,心之候。--《春秋·元命苞》 耳目者；组词：耳目官(指耳、目两种器官)；耳斡儿(亦作耳挖子”', '小学', '1'),
    ('耸', 'sǒng', '10', '耳', '上下', NULL, '耸 (形声。从耳,从声。本义耳聋) 同本义 子野听耸,离朱目眩。--马融《广成颂》 耸,聋也...生而聋,陈、楚、江、淮之间谓之耸。荆阳之间及山之东西双聋者谓之耸。；组词：耸昧(既聋又瞎', '小学', '1'),
    ('耻', 'chǐ', '10', '耳', '左右', NULL, '耻 (形声。从心,耳声。本义耻辱,可耻的事情) 同本义(因声誉受损害而至的内心羞愧) 耻,辱也。；组词：无耻(不顾(知)羞耻)；羞耻(不光彩；不体面)；耻心(知耻之心) 羞愧 坐縻廪粟而不知耻', '小学', '1'),
    ('耽', 'dān', '10', '耳', '左右', NULL, '耽 (形声。从耳,冘声。本义耳朵大而且下垂) 同本义 夸父耽耳。--《淮南子·地形》。高注耽耳,耳垂在肩上。”；组词：耽毵(毛长下垂纷披的样子) 耽 沉溺 于嗟女兮,无与士耽', '小学', '1'),
    ('耿', 'gěng', '10', '耳', '左右', NULL, '耿 (形声。从火,圣省声。本义耳贴于颊) 同本义 通炯”。明亮,光明 跪敷衽(铺开衣襟)以陈辞兮,耿吾既得此中正(指正道)。；组词：耿耀(照耀)；耿光(光明；光辉)；耿晶晶(形容物体明亮闪光的样子)；耿烈(光明炽热)；耿介(光明正大) 心情不安；悲伤', '小学', '1'),
    ('聂', 'niè', '10', '耳', '上下', NULL, '聂 (会意。从三耳。本义附耳小语) 同本义 聂,附耳私小语也。--《说文》 乃效女儿咕嗫私语。--《史记·魏其武安侯列传》；组词：聂许(附耳私语)；聂聂(轻小,轻虚平和的样子) 假借为摄”', '小学', '1'),
    ('聊', 'liáo', '11', '耳', '左右', NULL, '聊〈动〉 (形声。从耳,卯声。本义耳鸣) 同本义 聊,耳鸣也。--《说文》 横舟航而济湘兮,耳聊啾而戃慌。--刘向《九叹》；组词：聊啾(耳鸣) 依赖,凭藉 百姓不聊生', '小学', '1'),
    ('聋', 'lóng', '11', '耳', '上下', NULL, '聋 (形声。从耳,龙声。本义丧失听觉能力) 同本义 聋,无闻也。--《说文》 聋者无以与乎钟鼓之声。--《庄子·逍遥游》 耳不听五声之和为聋,目不别五色之章为昧；组词：聋聩(耳聋或天生的聋子', '小学', '1'),
    ('职', 'zhí', '11', '耳', '左右', NULL, '职 (形声。从耳,只声。职”是记”的意思。段玉裁凡言职者,谓其善听也。”故从耳。本义识;记。职为识之本字)；组词：职称言路(做谏官)；职任民社(管理人民与国家)；职客(红、白喜事的主持人)；职内(古官名', '小学', '1'),
    ('联', 'lián', '12', '耳', '左右', NULL, '联 (会意。从耳,从丝。战国文字,中间是耳,两边是丝相联。本义连结) 同本义 聯,连也。从耳,耳连于颊也。从糸,糸连不绝也。会意。；组词：联垂(一种发式', '小学', '1'),
    ('聘', 'pìn', '13', '耳', '左右', NULL, '聘〈动〉 (形声。从耳,甹声。探问消息要靠耳朵,故从耳”。本义访问,探问) 同本义 聘,访也。；组词：聘弓(古代聘问时持用之弓)；聘贡(聘问朝贡)；聘享(聘问献纳)；聘使(奉命聘问) 聘请 聘pìn 1.招请,请人担任工作', '小学', '1'),
    ('聚', 'jù', '14', '耳', '上下', NULL, '聚 (形声。小篆,下面是三个人,表示人多;上面的取”,作声符。本义村落) 同本义 聚,会也。；组词：聚落(村落里邑,人群聚居的地方) 众；集团；一伙 我是以有辅氏之聚', '小学', '1'),
    ('聪', 'cōng', '15', '耳', '左右', NULL, '聪 (形声。从耳,总声。本义听力好) 同本义 聪,察也。--《说文》 听曰聪。--《书·洪范》 闻审谓之聪。--《管子·宙合》 耳彻为聪。--《庄子·外物》 尚寐无聪；组词：聪耳(听觉灵敏的耳朵) 明察', '小学', '1'),
    ('肃', 'sù', '8', '聿', NULL, NULL, '肃 (会意。小篆字形。表示人战战兢兢,非常畏惧小心。本义{恭敬}) 同本义 肃,持事振敬也。；组词：肃敬(恭恭敬敬)；肃迓(恭迎)；肃奉(恭敬地接受或遵奉)；肃括(恭敬而有法度', '小学', '1'),
    ('肄', 'yì', '13', '聿', '左右', NULL, '肄 学习;练习 兵官皆肄孙吴兵法。--《后汉书》 又如肄业上庠(在京都学堂读书) 检阅,检查 肄yì练习,学习以~舟师。讲~之场。~业(在校学习中断,未达到毕业)；组词：肄业上庠(在京都学堂读书) 检阅,检查 肄yì练习,学习以~舟师', '小学', '1'),
    ('肆', 'sì', '13', '聿', '左右', NULL, '肆 (形声。从长,聿声。本义摆设;陈列) 同本义 肆,极陈也。--《说文》。朱骏声曰此字本训长。” 肆,陈也。--《广韵》 或剥或享,或肆或将。--《诗·小雅·楚茨》 肆筵设席；组词：肆筵(摆设筵席)；肆肆(并列的样子) 古时处死刑后陈尸示众 吾力犹能肆诸市朝', '小学', '1'),
    ('肉', 'ròu', '6', '肉', NULL, NULL, '肉 (象形。甲骨文 字形,小篆,象动物肉形。肉”是汉字的一个部首。本义动物的肌肉) 指供食用的动物肉 肉,胾肉。；组词：吃肉；蟹肉；家禽的黑肉；肉醢(肉酱)；肉山脯林(积肉如山,列脯如林)；肉林(食用之肉极多,悬挂于林,形容穷奢极欲)；肉腥', '小学', '1'),
    ('肋', 'lèi', '6', '月', '左右', NULL, '肋〈名〉 lei (形声。从肉,力声。本义肋骨) 同本义 肋,肋骨也。--《说文》 肋,勒也,所以捡勒五脏也。--《释名·释形体》；组词：肋下(腋下)；肋肢(腋下,胳肢窝)；肋窝(也作肋罗”', '小学', '1'),
    ('肌', 'jī', '6', '月', '左右', NULL, '肌 (形声。从肉,几声。本义肌肉) 同本义(先秦时期,肌”表示人的肉;肉”表示禽兽的肉) 肌,肉也。；组词：肌肥骨重(形容身躯壮实魁悟)；肌肌(肌肉强直的样子)；肌肪(肌肤)；肌革(肌肤,皮肉)；肌骨(肌肉与骨骼) 引申指皮肤', '小学', '1'),
    ('肖', 'xiāo', '7', '月', '上下', NULL, '肖 姓。萧”字的俗写 肖 〈形〉 假借为小”。细微 肖,小也。--《方言十二》 肖翘之物。--《庄子·?箧》 达生之情者傀,达于知者肖。--《庄子》；组词：肖翘(细小能飞的生物) 肖 〈动〉 假借为消”', '小学', '1'),
    ('肘', 'zhǒu', '7', '月', '左右', NULL, '肘 (会意。从肉从寸,寸,腕下寸口”部位。点明肘所在的范围。本义上下臂相接处可以弯曲的部位)；组词：肘膊(手臂', '小学', '1'),
    ('肚', 'dù', '7', '月', '左右', NULL, '肚 (形声。从肉,土声。本义人或动物的腹部) 同本义 物体突起或中间鼓出的部分 指思维器官 肚 dǔ胃。特指用做食物的猪羊等的胃猪~。又见dù。 肚 dù腹部。又见dǔ', '小学', '1'),
    ('肛', 'gāng', '7', '月', '左右', NULL, '肛 (形声。从肉,工声。本义肛门) 同本义 肛,肛门。--《集韵》 大肠端,肛门也。”--《六书故》 肛管和肛门的总称 脱肛属气热、气虚、血虚、血热', '小学', '1'),
    ('肝', 'gān', '7', '月', '左右', NULL, '肝 (形声。从肉,干声。本义肝脏) 同本义 肝,木藏也。--《说文》 肝,榦也。于五行属木,故其体状有枝干。--《释名·释形体》 赞以肝从。--《仪礼·士昏礼》 祭先肝；组词：肝肺(肝与肺)；肝鬲(体内的肝和膈', '小学', '1'),
    ('肠', 'cháng', '7', '月', '左右', NULL, '肠 (形声。从肉,? 肠子或肠子制成的食品 内心,情怀 肠 cháng(~子)消化器官的一部分,形状像管子,上端连胃,下端通肛门。起消化和吸收作用。又叫肠管', '小学', '1'),
    ('股', 'gǔ', '8', '月', '左右', NULL, '股〈名〉 (形声。从肉,殳声。本义大腿) 同本义 股,髀也。--《说文》 膝上曰股,膝下曰胫。--《论语·宪问》疏 读书欲睡,引锥刺其股。--《战国策·秦策》 余皆股栗；组词：股掌(大腿与手掌)；股弁(大腿发抖) 事物的分支或一部分 注如淳曰股,支别也', '小学', '1'),
    ('肢', 'zhī', '8', '月', '左右', NULL, '肢 (形声。从肉,支声。本义人的手足与鸟兽翼足的总称) 同本义 劳其四肢,伤其五脏。--《商君书》 四肢六道,身之体也。--《管子》；组词：肢节(四肢关节)；肢骸(肢体骸骨)；上肢；下肢；假肢 指人体的腰部 协肩屏气,舐痔折肢', '小学', '1'),
    ('肤', 'fū', '8', '月', '左右', NULL, '肤 (形声。从肉,眗省声。本义人的皮肤) 同本义 肤受之愬。--《论语·颜渊》 衣不暖肤。--《商君书·算地》 手如柔荑,肤如凝脂。--《诗·卫风·硕人》；组词：肌肤(肌肉皮肤)；肤革(皮肤的表皮和真皮；外面,表面)；肤不生毛(皮肤上长满了厚茧而长不出毛) 树木、果实的表皮 某些像', '小学', '1'),
    ('肥', 'féi', '8', '月', '左右', NULL, '肥〈形〉 (会意。从肉,本义脂肪多) 同本义 肥,多肉也。--《说文》 坚土之人肥。--《大戴礼记·易本命》 瞻肥瘠。--《礼记·月令》 吾牲牷肥。--《左传·桓公六年》；组词：肥猪；肥肉(喻指有钱的人)；肥腻(含油脂多的食物；油脂多)；肥汉(肥胖的男子) 引申为肥沃 不爱珍器重肥饶之地', '小学', '1'),
    ('肩', 'jiān', '8', '月', NULL, NULL, '肩 (象形。从户,从肉。本义肩膀) 同本义 肩,髆也。从肉,象形。--《说文》 北方有比肩之民焉。迭食而迭望。--《尔雅》 肩臂臑。--《仪礼·少牢礼》 肩之所倚；组词：肩巴(肩膀)；肩甲(即肩胛)；肩磨(肩膀耸动,浑身发抖)；肩排(并肩排列；并排) 动物的腿根部 项王曰赐之彘肩', '小学', '1'),
    ('肪', 'fáng', '8', '月', '左右', NULL, '肪〈名〉 脂肪 窃见玉书,称美玉白如截肪。--曹丕《与钟大理书》 也特指动物腰部肥厚的油 脂在腰曰肪。', '小学', '1'),
    ('肮', 'āng', '8', '月', '左右', NULL, '肮脏 脏;不干净 肮脏的街道 肮脏的池塘 比喻卑鄙、丑恶;道义上应受指责 肮脏的交易 肮háng 1.咽喉。', '小学', '1'),
    ('肯', 'kěn', '8', '月', '上下', NULL, '肯 (会意。小篆字形从肉,从冎省。本义着骨之肉) 同本义 胓,骨间肉胓胓着也。--《说文》。俗字误作肯。 技经肯綮之未尝。--《庄子·养生主》；组词：肯綮 肯 〈动〉 假借为可”', '小学', '1'),
    ('育', 'yù', '8', '月', '上下', NULL, '育〈动〉 (会意。甲骨文字形,象妇女生孩子。上为母”及头上的装饰,下为倒着的子”。) 同本义 育,生也。；组词：节育(节制生育)；育孕(怀胎足月以至分娩)；生儿育女 抚养；教育 育,养子使作善也', '小学', '1'),
    ('肴', 'yáo', '8', '月', '上下', NULL, '肴 (形声。小篆字形。从肉,爻声。本义做熟的鱼肉等) 同本义 肴,啖也。凡熟馈可啖之肉,折俎,豆实皆是。；组词：肴蔌(鱼肉与菜蔬)；肴核(肉类和果类食品)；肴俎(肉食)；肴品(荤菜；佳肴)；肴俎(盛菜肴的器皿)；肴羞(美味的菜肴)', '小学', '1'),
    ('肺', 'fèi', '8', '月', '左右', NULL, '肺〈名〉 肺,金臧也。--《说文》 肺有金之精,制割立断。--《春秋·元命苞》 肺为气。--《淮南子·精神》 肺藏于右。--《素问·刺禁论》 吾师肺肝,皆铁石所铸造也；组词：肺肠(肺和肠', '小学', '1'),
    ('肾', 'shèn', '8', '月', NULL, NULL, '肾 位于脊椎动物体腔内脊柱近旁的一对内脏器官,它排出尿液、尿酸和其它代谢的排泄物 肾,水藏也。从肉,茞声。；组词：肾肠(肺腑,比喻诚意)；肾痹(五脏痹症之一,主要症状为骨萎弱不能行走,腰背弯曲或关节肿胀) 指外肾,即睾丸 指性功能 胃', '小学', '1'),
    ('肿', 'zhǒng', '8', '月', '左右', NULL, '肿 (形声。从肉,中(重)声。本义痈) 同本义 肿,痈也。--《说文》 肉暴长曰肿。--《论衡·状留》 肿疡。--《周礼·疡医》。注痈而上创者。” 郁处头,则为肿为风；组词：肿泄(病名', '小学', '1'),
    ('胀', 'zhàng', '8', '月', '左右', NULL, '胀 (形声。从肉,长声。从肉,表示与身体有关。本义皮肉鼓胀) 同本义 胀,胀满。--《广韵》 寒气泄注腹胪胀。--《急就篇》。注胀,谓腹鼓胀也。” 人或嚥气,气满腹胀,不能餍饱；组词：胀闷(又胀又闷)；胀病；鼓胀；单腹胀；头胀；胁胀 膨胀,体积变大 斯须之间,见囊大胀如吹', '小学', '1'),
    ('胁', 'xié', '8', '月', '左右', NULL, '胁 (形声。从肉(月),劦声。本义腋下肋骨所在的部分) 同本义 胁,两膀也。--《说文》。按,腋下之名也。其骨谓之肋,牲体则谓之拍。 两胁里急。--《素问·至真要大论》 兵尚胁盾；组词：胁胑(由腋下到腰以上的部位)；胁窝里(比喻两侧)；胁不沾席(形容佛教徒勤苦修行)；胁骨(肋骨)；胁衣(女人的内衣', '小学', '1'),
    ('胃', 'wèi', '9', '月', '上下', NULL, '胃 (象形。据小篆字形。上象口袋形的消化器官,下为肉。本义人和动物贮藏和消化食物的器官)；组词：重瓣胃；胃疸(中医指胃部虚热)；胃气痛(方言', '小学', '1'),
    ('胆', 'dǎn', '9', '月', '左右', NULL, '胆 (形声。从肉,詹声。本义胆囊。动物体内消化器官之一) 同本义。通称胆或苦胆 膽,连肝之府也。；组词：胆结石(胆石症)；胆裂(胆为之破裂', '小学', '1'),
    ('背', 'bèi', '9', '月', '上下', NULL, '背 人用脊背驮 早背胡霜过戍楼,又随寒日下汀州。--罗邺《雁》 又如背粮食;背头(男子头发由鬓角起都向后梳的发式);背锅(方言。驼背) 负担；组词：背粮食；背头(男子头发由鬓角起都向后梳的发式)；背锅(方言', '小学', '1'),
    ('胎', 'tāi', '9', '月', '左右', NULL, '胎〈名〉 (形声。从肉,台声。本义未生的幼体,胚胎) 同本义 胎,妇孕三月也。--《说文》 胎,始也。--《尔雅》 九窍者胎生。--《庄子·知北游》 毋杀孩虫胎天飞鸟；组词：胎夭(刚出生及尚未出生的小动物)；胎胞(胎儿的胞衣)；胎动(胎儿在母体内蠕动)；胎卵(胎生与卵生)；胎形；胎位 怀孕或生', '小学', '1'),
    ('胖', 'pàng', '9', '月', '左右', NULL, '胖 (会意兼形声。从月(肉),从半,半亦声。半,分牛。本义古代祭祀时用的半边牲肉) 同本义 胖,半体肉也。；组词：发胖(身体变胖)；虚胖；胖壮(肥胖壮实)；胖子年(方言', '小学', '1'),
    ('胚', 'pēi', '9', '月', '左右', NULL, '胚 (形声。《说文》作胹”,从月(肉),不声。本义妇女怀胎一月之称) 初期发育的幼孢子体,由精细胞和卵细胞结合发展而成 胹,妇孕一月也。；组词：胚芽；胚胎；胚种 毛坯,半制成品 混沌 胚pēi 1.初期发育的生物体~芽', '小学', '1'),
    ('胜', 'shèng', '9', '月', '左右', NULL, '胜 (形声。从力,朕声。本义胜任,禁得起) 同本义 胜,任也。--《说文》 胜,克也。--《尔雅》 莫之胜说。--《易·遯》。虞注能也。” 武王靡不胜。--《诗·商颂·烈祖》；组词：不胜其苦(苦得受不住)；胜任愉快(有能力承担并能愉快地完成任务)；胜兵(能充当士兵参战的人) 战胜,打败 胜殷遏刘', '小学', '1'),
    ('胞', 'bāo', '9', '月', '左右', NULL, '胞 (形声。从肉,包声。包”亦兼表字义。本义胎衣) 同本义 胞,儿生裹也。--《说文》 同胞之徒。--《汉书·东方朔传》 善臧我儿胞。--《汉书·外戚传》；组词：胞衣地(埋胞衣的地方)；胞胎(犹胞衣', '小学', '1'),
    ('胡', 'hú', '9', '月', '左右', NULL, '胡 (形声。从肉,古声。本义牛脖子下的垂肉) 鸟兽颔下的垂肉或皮囊 胡,牛顄垂也。--《说文》。徐锴曰牛颔下垂皮也。” 狼跋其胡。--《诗·豳风·狼跋》。传老狼有胡；组词：胡髯朗(羊的别名→,颈下垂肉；髯,须)；胡皱(牛颔下松弛有皱纹的皮)；胡袋(某些鸟类颌下的皮囊,也称喉囊) 器物上下垂如', '小学', '1'),
    ('胧', 'lóng', '9', '月', '左右', NULL, '胧 (形声。从月,龙声。朦胧月色不明的样子。引申为凝不清”) 同本义 灯在月胧明,觉来闻晓莺。--温庭筠《菩萨蛮》；组词：胧月(微明的月亮)；胧明(微明)；胧胧(微明的样子) 胧(杤)lóng朦胧]见朦', '小学', '1'),
    ('胯', 'kuà', '10', '月', '左右', NULL, '胯〈名〉 (形声。从肉,夸声。本义两股之间) 同本义 胯,股也。--《说文》。段注合两股言曰胯。” 出我胯下。--《史记·淮阴侯传》；组词：胯子(腰的两侧和大腿之间的部分)；胯夫(指韩信『淮阴侯韩信早年未得志时,,有人欺侮他,让他从胯下爬了过去)', '小学', '1'),
    ('胰', 'yí', '10', '月', '左右', NULL, '胰 胰腺 胰yí 1.胰腺,旧称"脺脏"。人和高等动物的腺体之一。能分泌胰液,帮助消化蛋白质、脂肪和糖类等,还分泌胰岛素调节糖的代谢等。 2. 1猪、牛、羊等的胰脏', '小学', '1'),
    ('胳', 'gē', '10', '月', '左右', NULL, '胳 (形声。从骨,各声。本义禽兽之骨。引申为人或动物的骨骼”) 骨头 骼,禽兽之骨曰骼。--《说文》 骼,腰骨也。--《埤苍》 掩骼埋胔。--《礼记·月令》 死人的骨头', '小学', '1'),
    ('胶', 'jiāo', '10', '月', '左右', NULL, '胶〈名〉 (形声。古代胶”用动物的皮煮制而成,所以从肉”。段玉裁说皮近肉,故字从肉。”本义粘性物质,用动物的皮角或树脂制成)；组词：胶鳔(用鱼鳔煮治而成的胶)；胶漆(胶与漆', '小学', '1'),
    ('胸', 'xiōng', '10', '月', '左右', NULL, '胸 (形声。从肉,匈声。本作匈”,胸是后起字。本义胸膛) 同本义 胸满腹胀。--《素问·腹中论》 两手紧抱胸前。--宋·宋慈《洗冤录》；组词：胸雪(雪白的胸部', '小学', '1'),
    ('能', 'néng', '10', '月', '左右', NULL, '能〈名〉 (象形。金文作字形象熊形。本义熊) 传说中的一种像熊的兽 能,熊属。足似鹿。--《说文》 梦黄能入于寝门。--《左传·昭公七年》。贾注兽也。” 近者三奸悉破碎；组词：能处(本事；能耐)；无能(没有能力)；低能(能力低下)；逞能(显示自己能干)；各 能néng 1.才干,本领~力', '小学', '1'),
    ('脂', 'zhī', '10', '月', '左右', NULL, '脂 (形声。从肉,旨声。本义动植物所含的油脂) 同本义 脂,戴角者脂,无角者膏。--《说文》 有羽者脂。--《易·本命》 脂,肪也。--《广苍》 脂膏以膏之。--《礼记·内则》；组词：脂灰(油脂和石灰,犹今油灰之类)；脂水(旧指妇人盥洗后的剩水；或指石油；脓水)；脂炬(即脂烛)；脂韦(油脂和软皮) 润滑', '小学', '1'),
    ('脆', 'cuì', '10', '月', '左右', NULL, '脃 (会意。从肉,绝省声。本义易折断) 同本义 其脃易泮。--《老子》 脃薄。--《后汉书·许荆传》 华而不实,脆而不坚。--毛泽东《改造我们的学习》；组词：脆断(脆而折断)；脆薄(不坚牢)；脆帮根儿咬(比喻做事应抓住主要矛盾)；脆促(生命脆弱而短暂) 鲜嫩爽口的 声音清爽(高', '小学', '1'),
    ('脉', 'mài', '9', '月', '左右', NULL, '脉脉 mo 温情脉脉 叶子底下是脉脉的流水。--朱自清《荷塘月色》 脉 mai (会意∠起来表示身体里的一种支脉。本义血管)；组词：动脉；静脉；脉脉相通(血管彼此相通) 指事物如血管连贯有条理者 雪缕青山脉,云生白鹤毛', '小学', '1'),
    ('脊', 'jǐ', '10', '月', NULL, NULL, '脊 (本义背中间的骨头) 同本义 脊,背吕也。--《说文》 举肺脊。--《仪礼·特性礼》 坎为美脊。--《易·说卦传》 或碎脑以折脊。--李白《大猎赋》；组词：脊杖(在罪犯脊背上施加的杖刑)；脊令(脊令原', '小学', '1'),
    ('脏', 'zāng', '10', '月', '左右', NULL, '脏 (形声。左形,右声。本义中医学以心、肝、脾、肺、肾为五脏◇因以为身体内脏的通称)同本义 脏,五脏也。', '小学', '1'),
    ('脐', 'qí', '10', '月', '左右', NULL, '脐 (形声。从肉,齐声。本义肚脐) 同本义 螃蟹腹部的厣,雌者圆形称团脐”,雄者尖形称尖脐” 某些物体中央凹凸处状如脐 脐(臍)qí 1. 2.螃蟹腹部的甲壳,雄尖雌圆,故有尖~', '小学', '1'),
    ('脑', 'nǎo', '10', '月', '左右', NULL, '脑 (形声。本义脑髓) 同本义 卍,头髓也。从匕,匕,相比著也。巛象发,囟象脑形。--《说文》。按,囟头会卍盖也。字亦作膞。 蹙于(脑)而休于气。--《考工记·弓人》 其荣发也；组词：脑箍(用刑时套在头上的刑具)；脑揪(揪住头发)；脑(膞)nǎo 1.通称"脑髓"', '小学', '1'),
    ('脓', 'nóng', '10', '月', '左右', NULL, '脓 (形声。从肉,农声。本义从疮口流出的黄绿色粘液) 同本义 脓血流离。--《聊斋志异·促织》；组词：脓血(脓和血的混合物)；脓团(脓包', '小学', '1'),
    ('脖', 'bó', '11', '月', '左右', NULL, '脖 (形声。从肉,孛)声。本义颈项。俗称脖子) 同本义 青龙偃月刀,九九八十一斤,脖子里着一下。--关汉卿《单刀会》；组词：脖梗(亦称脖儿梗”、脖梗子”；颈项)；脖项(颈项)；脖领(围在脖子上的领套)', '小学', '1'),
    ('脚', 'jiǎo', '11', '月', '左右', NULL, '脚〈名〉 (形声。从肉,却声。本义胫,小腿) 同本义 脚,胫也。--《说文》 捶笞膑脚。--《荀子·正论》；组词：脚膀(指小腿)；脚胫(小腿)；腿杆(方言', '小学', '1'),
    ('脯', 'pú', '11', '月', '左右', NULL, '脯〈名〉fu (形声。从肉,甫声。本义干肉) 同本义 吾子淹久于敝邑,唯是脯资饩牵竭矣。--《左传·僖公三十三年》 谓加姜桂锻治者谓之,不加姜桂以盐干之者谓之脯；组词：肉脯；牛脯；脯饩(干肉和生肉)；脯糗(干肉和干粮)；脯腊(干肉)；脯枣(干肉和枣类果品) 干燥脱水的瓜果 熟肉 脯〈动〉', '小学', '1'),
    ('脱', 'tuō', '11', '月', '左右', NULL, '脱〈动〉 (形声。从肉,兑声。本义肉去皮骨) 同本义 脱,消肉舑也。--《说文》 肉去骨曰脱。--《尔雅》 肉曰脱之,鱼曰作之,枣曰新之。--《礼记·内则》 其状若脱；组词：脱祸(摆脱祸害)；脱了干系；脱凡(脱离凡俗)；脱tuō 1.离开,落掉~离', '小学', '1'),
    ('脸', 'liǎn', '11', '月', '左右', NULL, '脸 (形声。从肉,佥声。古代表示人的整个面部用面”。脸”字在魏晋时期才出现,只表示两颊的上部,到了唐宋时期,口语中才用脸”表示整个面部。本义两颊的上部)；组词：脸蛋(脸的两旁部分)；脸巴子(面颊)；脸上(面颊之上) 脸面,人头的前部,包括下巴、嘴、鼻、颊、眼,且通常包括前额 脸波', '小学', '1'),
    ('脾', 'pí', '12', '月', '左右', NULL, '脾〈名〉 (形声。从月(肉);卑声。本义脾脏。人和脊椎动物的内脏之一,是贮血和产淋巴与抗体的器官,有调节新陈代谢的作用。中医称五脏”之一)；组词：脾土(中医用语,指脾)；脾析(牛胃)；脾家(脾脏所在之处)；脾和(脾性相合,意气相投)；脾味(兴趣爱好；脾性,脾气) 通', '小学', '1'),
    ('腊', 'là', '12', '月', '左右', NULL, '腊 (形声。从肉,巤声。本义年终祭祀) 祭名。古代阴历十二月的一种祭祀。冬至后第三个戌日祭祀众神 冬至后三戌,腊祭百神。；组词：腊日(古时腊祭之日', '小学', '1'),
    ('腋', 'yè', '12', '月', '左右', NULL, '腋 (形声。从肉,夜声。本作亦”,大”(人)下两点表示腋的部位。本义胳肢窝) 同本义 胳谓之腋。；组词：腋毛；腋翅(腋下生翅,意犹飞身)；腋臊(腋臭,狐臭) 禽兽翅膀或前腿内侧和胸部相连的部分 腋状物 腋臭 腋毛 腋yè 1', '小学', '1'),
    ('腌', 'yān', '12', '月', '左右', NULL, '腌舎 晚到一步,事没办成,腌舎极了 腌舎泼才 腌ā 1.[腌舎]肮脏。不干净。 腌(醶)yān 1.用盐等浸渍食物~肉。~菜。 腌āng 1.肮脏。亦谓弄脏。 2.丑陋;恶劣', '小学', '1'),
    ('腐', 'fǔ', '14', '肉', NULL, NULL, '腐〈动〉 (形声。从肉,府声。本义腐烂变质) 同本义 腐,烂也。--《说文》 腐,败也。--《广雅》 人死,五藏腐朽。--汉·王充《论衡·订鬼篇》 流水不腐；组词：腐散(腐烂消散)；腐坏(腐烂损坏)；腐秽(腐烂肮脏)；腐浊(腐臭浑浊) 通拊”', '小学', '1'),
    ('腔', 'qiāng', '12', '月', '左右', NULL, '腔〈名〉 (会意兼形声。从月(肉),从空,空亦声。本义人和动物体内的空处) 同本义 腔,内空也。从肉,从空,空亦声。；组词：腔子(胸腔)；口腔；胸腔；生殖腔；胚盘下腔；胸膜腔；心腔；肾球囊腔；颅腔；腹腔；肠腔；子宫腔；髓腔 曲调；曲谱 口音 腔', '小学', '1'),
    ('腕', 'wàn', '12', '月', '左右', NULL, '腕 (形声。从肉,宛声。本义臂下端与手掌相连可以活动的部分) 同本义 又如腕表(手表);腕脱(手腕脱位。形容书写忙迫紧张);腕钏(手镯);腕法(写字用腕的方法);腕头(犹言手上)；组词：腕表(手表)；腕脱(手腕脱位', '小学', '1'),
    ('腥', 'xīng', '13', '月', '左右', NULL, '腥 腥气,泛指肉鱼、类及油脂的臭气味 腥臊并御。--《楚辞·屈原·涉江》。注臭也。” 王之厨馔,腥蝼不可飨。--《列子·周穆王》 水居者腥。--《吕氏春秋·本味》 扁地腥云；组词：这碗鱼汤有点腥；腥腻(腥气油腻)；血腥；腥臭；土腥气 病猪肉中像星或米粒的息肉 豕盲眡而交睫,腥', '小学', '1'),
    ('腮', 'sāi', '13', '月', '左右', NULL, '腮 颊 莲花泛水,艳如越女之腮。--萧统《十二月启》 又如腮庞(面颊,面容);腮斗儿(腮,脸蛋儿) 水生动物的呼吸器官 裴初不信,乃鲙鲤鱼无腮者,令左右食之；组词：腮庞(面颊,面容)；腮斗儿(腮,脸蛋儿) 水生动物的呼吸器官 裴初不信,乃鲙鲤鱼无腮者,令左右食之', '小学', '1'),
    ('腰', 'yāo', '13', '月', '左右', NULL, '腰 (形声。从肉,要声。本作要”。本义紧接肋或胸以下的部分;胸和髋之间的身体的一部分) 同本义 楚王好细腰,宫中多饿死。；组词：腰板(人的腰和背', '小学', '1'),
    ('腹', 'fù', '13', '月', '左右', NULL, '腹〈名〉 (形声。从肉,复声。此为后起形声字,初文应即畐”字,象人腹部之形。本义肚子) 同本义 腹,厚也。；组词：腹痛(肚子痛)；腹肠(肚肠,肚子)；腹围(腰带)；腹如垂瓠(形容肚皮松瘪难看)；腹便便(形容肚子肥满) 比喻中央部分 腹', '小学', '1'),
    ('腺', 'xiàn', '13', '月', '左右', NULL, '腺 生物体内能分泌某些化学物质的组织 腺xiàn生物体内具有分泌功能的组织或器官~体。乳~。甲状~。', '小学', '1'),
    ('腻', 'nì', '13', '月', '左右', NULL, '腻 (形声。从肉,贰声。本义肥) 同本义 腻,肥也。--《说文》 靡颜腻理。--《楚辞·招魂》 石钱差复藉,厚叶皆蟠腻。--唐·李贺《昌谷》 浓 粘糊 亲昵 细腻 肌理细腻骨肉匀；组词：腻泽(细腻光润)；腻玉(纹理细腻润泽的玉', '小学', '1'),
    ('腾', 'téng', '13', '月', NULL, NULL, '腾〈动〉 (形声。从马,朕声。本义马奔腾) 同本义 腾,传也。--《说文》。谓传车马驰。 腾,奔也。--《广雅》 腾众车使径待。--《离骚》 腾驴驘以驰逐；组词：奔腾(许多马跳跃着奔跑)；腾夷(在平地上奔驰', '小学', '1'),
    ('腿', 'tuǐ', '13', '月', '左右', NULL, '腿 胫和股的总称 石人战摇腿。--唐·韩愈《嘲鼾睡》 又如腿花(棍子打在腿上;腿伤);大腿;粗腿;腿股(大腿);腿脡(腿码,腿銗腿,言其直而修长);腿胯(腰以下至大腿的部分；组词：腿花(棍子打在腿上；腿伤)；大腿；粗腿；腿股(大腿)；腿脡(腿码,腿銗腿,言其直而修长)；腿胯(腰以下至大腿的部分', '小学', '1'),
    ('膀', 'bǎng', '14', '月', '左右', NULL, '膀 (形声。从肉,旁声。本义肩膀) 同本义 十分腰围膀阔。--《水浒传》 又如膀阔腰圆;腰细膀宽 臂膀。指肩和肘之间的手臂 兽类或家畜腿的上部或前肢和躯干相连的部分 肉则羊膀豕胁；组词：膀阔腰圆；腰细膀宽 臂膀', '小学', '1'),
    ('膊', 'bó', '14', '月', '左右', NULL, '膊 (形声。从肉,尃(醤??)声。本义肩臂) 同本义 膊bó 1肩膀;胳臂。亦泛指身体的上部。 2古量词。 3用同"脖"。 【膊子】膀子,胳膊。 膊pò 1谓分裂肢体而曝露之', '小学', '1'),
    ('膏', 'gāo', '14', '月', '上下', NULL, '膏〈名〉 (形声。从肉,高声。从肉,表示与肉体有关。本义溶化的油脂,无角动物的油脂) 同本义 膏,肥也。', '小学', '1'),
    ('膘', 'biāo', '15', '月', '左右', NULL, '膘 肥肉 膘,牛胁后髀前合革肉也。从肉,票声。--《说文》 自膘而射之。--《诗·车攻传》 马无他损,特膘稍落,微磨破耳。(特仅仅,只。)--李新《与冯德夫》；组词：膘肥体壮(形容牲畜肥壮结实)；膘息(指牲畜的肥硕处) 膘情 膘实,骠实 这匹马很膘实 膘壮 牧场上膘壮的马群在嬉戏追逐', '小学', '1'),
    ('膛', 'táng', '15', '月', '左右', NULL, '膛〈名〉 (形声。从肉,堂声。本义胸腔) 同本义 休便要斩首开膛。--纪君祥《赵氏孤儿》；组词：开膛(剖开胸腔) 器物中空的部分 膛音,膛音儿 这老人虽已年过半百,但讲话膛音很大,底气十足 膛子 膛táng 1.胸腔', '小学', '1'),
    ('膜', 'mó', '14', '月', '左右', NULL, '膜 (形声。从肉,莫声。本义生物体内部的薄皮形组织) 同本义 熏于肓膜,散于胸服。--《素问·痹论》；组词：耳膜；竹膜；细胞膜；鼓膜 通常有柔韧性的透明薄片 比喻细微的间隔 膜 专指礼拜神佛的跪拜 膜mó 1.动、植物体内像薄皮', '小学', '1'),
    ('膝', 'xī', '15', '月', '左右', NULL, '膝 (形声。从肉,梤声。本义膝头) 大腿和小腿相连关节的前部。通称膝盖 今之君子,进人若将加诸膝,退人若将队诸渊。；组词：膝馒头(膝盖)；膝下荒凉(指无子女)；膝踝(膝盖与足踝)；膝拐(方言', '小学', '1'),
    ('膨', 'péng', '16', '月', '左右', NULL, '膨〈动〉 (形声。从肉(月),彭声。本义胀大) 同本义。体积或长度增大 膨péng 1.胀~大。 2. 1物体的体积或长度增大空气遇热~胀。 2指数量增加通货~胀。 3.', '小学', '1'),
    ('膳', 'shàn', '16', '月', '左右', NULL, '膳 (形声。从肉,善声。本义饭食) 同本义,一般指肉食 膳,具食也。--《说文》 膳,肉也。--《广雅》 掌王之食饮膳羞。--《周礼·膳夫》。注膳,牲肉也。” 徧尝膳；组词：早膳；供给膳宿；膳部员外郎(唐代礼部专管膳食的长官之一)；膳服(饮食和服用)；膳羞(美味的食品)；膳饮(饮食) 膳 〈动', '小学', '1'),
    ('臀', 'tún', '17', '月', '上下', NULL, '臀 屁股 臀,尻也。--《声类》 姤臀元肤,困。臀困于株木。--《易·夬》 故名之曰黑臀。--《国语·周语》；组词：臀杖(刑罚名', '小学', '1'),
    ('臂', 'bì', '17', '月', '上下', NULL, '臂 (形声。从肉,辟声。本义胳膊) 胳臂 臂,手上也。--《说文》 肱谓之臂。--《广雅·释亲》 肩臂。--《仪礼·少牢礼》。注肱骨。” 奋袖出臂；组词：臂缚(古时缚在两臂以抵御兵刃的铠甲', '小学', '1'),
    ('臊', 'sào', '17', '月', '左右', NULL, '臊 (形声。从肉(月),声。本义腥臊) 同本义 臊,豕膏臭也。--《说文》 犬赤股而躁臊。--《周礼·内饔》 其臭臊。--《素问·金匮真言论》 露申辛夷死林薄兮；组词：腥臊(动物体上散发的一种难闻的气味', '小学', '1'),
    ('臣', 'chén', '6', '臣', NULL, NULL, '臣 (象形。甲骨文字形,象一只竖立的眼睛形。人在低头时,眼睛即处于竖立的位置,字形正表示了俯首屈从之意。本义男性奴隶)；组词：臣妾(古时对奴隶的称谓', '小学', '1'),
    ('自', 'zì', '6', '自', NULL, NULL, '自 (象形。小篆字形。象鼻形。自”是汉字的一个部首。本义鼻子) 同本义 自,鼻也。--《说文》。段玉裁注许谓自与鼻义同音同,而用自为鼻者绝少也。” 始;开头 故法者,王之本也；组词：自顷(近来) 自 自己,自我；本身 不自为政,卒劳百姓', '小学', '1'),
    ('臭', 'chòu', '10', '自', '上下', NULL, '臭 chou (会意。从犬,从自(鼻)。狗鼻特别灵敏,故从二字会意。本义闻气味) 气味之总名 臭,禽走臭而知其迹者,犬也。；组词：臭不 可当(极言其臭)；臭短臊长(各种污言秽语)；臭皮囊(肉体；躯壳) 香气 臭 chòu 1(气味)难闻~气冲天', '小学', '1'),
    ('至', 'zhì', '6', '至', '上下', NULL, '至 (象形。从一,一犹地,指事,不去而下来。古文从土,上亦象飞下之形。尾上首下。本义到来,到达)', '小学', '1'),
    ('致', 'zhì', '10', '至', '左右', NULL, '致 同本义 致,送诣也。--《说文》 君子以致命遂志。--《易·象下传》 远莫致之。--《诗·卫风·竹竿》 卿致馆。--《诗·卫风·聘礼》 殷人既葬而致事；组词：致聘(送交定亲礼品) 招引；招致 致天下之士', '小学', '1'),
    ('臼', 'jiù', '6', '臼', NULL, NULL, '臼 (象形。小篆字形,象舂米器具形,中间的四点表示有米。本义中部下凹的舂米器具) 同本义 臼,舂也。古者掘地为臼,其后穿木石。；组词：臼杵(臼与杵)；臼塘(凿成船形的木臼,别称臼塘)；臼中无釜(比喻妻子亡故) 又指用以形容臼状物 臼 用臼舂米 织纺井臼', '小学', '1'),
    ('舀', 'yǎo', '10', '臼', '上下', NULL, '舀 (会意。上为爪”,下为臼”(榞??)),象伸手掏取之形。本义用瓢勺取物) 同本义 舀子 舀yǎo 1.用瓢、勺等取东西(多指舀液体)~酒。~水。~牛奶。 2.', '小学', '1'),
    ('舅', 'jiù', '13', '臼', '上下', NULL, '舅 (形声。从男,臼声。本义舅父,指母之兄或弟) 同本义 母之兄、弟。妻之父为外舅,从男,臼声。凡异姓之称,不得称父,则舅之。；组词：舅氏(对舅的尊称)；舅公(父亲的舅父)；舅弟(舅父的儿子,年纪小于自己的', '小学', '1'),
    ('舆', 'yú', '14', '臼', '半包围', NULL, '舆 (形声。从车,舁声。本义车厢) 同本义 舆,车舆也。--《说文》。按,车中受物之处。 舆人为车。--《考工记》 木材...曲者宜为轮,直者宜为舆。--《潜夫论》 车辆；组词：舆士(车夫)；舆服(车子和衣冠的总称)；舆几(车子与几案)；舆马(车马)；舆轮(车轮)；舆骑(车骑)；舆帅(主管兵车的官', '小学', '1'),
    ('舌', 'shé', '6', '舌', '上下', NULL, '舌〈名〉 (会意。从干,从口。本义舌头) 同本义 舌,在口所以言也,别味也。从干,从口,会意。言犯口而出,食犯口而入也。；组词：舌举(舌翘起而不能动', '小学', '1'),
    ('舍', 'shě', '8', '舌', '上下', NULL, '舍 放在一边;丢开 捨,释也。从手,舍声。--《说文》 捨,置也。--《广雅》 舍车而徒。--《易·贲》；组词：舍手(放开手；放下手)；舍置(丢开)；舍脸(沉下脸) 放弃；舍弃 万物捨此而求生', '小学', '1'),
    ('舒', 'shū', '12', '舌', '左右', NULL, '舒 (会意兼形声。从舍,从予,予亦声。本义伸展,舒展) 同本义 舒,伸也。--《说文》 匪安匪舒。--《诗·大雅·江汉》 舒,展也。--《广雅》 舒勃,展也。东齐之间；组词：舒卷(张开或卷起)；舒手(松手；伸手)；舒头(伸头)；舒直立(伸腰直立)；舒勃(开展,展开)；舒眉(展眉', '小学', '1'),
    ('舔', 'tiǎn', '14', '舌', '左右', NULL, '舔〈动〉 (形声。从舌,忝声。本义以舌取食) 同本义 如舔舕(吐出舌头的样子);舔粥碗;舔干净;舔邮票;舔笔 使...湿润 如舔舔嘴唇 舔tiǎn用舌头去接触或者摄取东西~食。', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('舞', 'wǔ', '14', '夕', '上下', NULL, '舞 (形声。从舛,两足相背。古舞字象人执牛尾而舞之形。本义舞蹈) 同本义 舞,动其容也。--《礼记·乐记》 乐容曰舞--蔡邕《月令章句》；组词：舞旋(旋转的舞蹈；耍弄,舞弄)；舞判(装扮钟馗、判官等形象的舞蹈)；芭蕾舞；歌舞(唱歌和舞蹈的合称)；舞局(舞会)；舞咏', '小学', '1'),
    ('舟', 'zhōu', '6', '舟', NULL, NULL, '舟 (象形。甲骨文字形,象船形。两边象船帮,中间三条线代表船头、船舱和船尾。先秦多用舟”,汉以后用船”渐多起来。本义船)', '小学', '1'),
    ('航', 'háng', '10', '舟', '左右', NULL, '航〈名〉 船;方舟 航,船也。--《广韵》 航,方舟也。本作斻。--《集韵》 大者以为舟航柱梁。--《淮南子·主术》 譬临河而无航。--《后汉书·张衡传》 长鲸吞航；组词：航人(船夫) 两船相并,因指连船而成的浮桥 航空,飞机的飞行活动 航〈动〉 船行；航行 渡过 峡甚逼仄,故一木航之', '小学', '1'),
    ('般', 'bān', '10', '舟', '左右', NULL, '般 种,类 草木知春不久归,百般红紫斗芳菲。--唐·韩愈《晚春》 又如这般东西;百般劝解;般般(种种;样样;件件) 般 通搬”。搬运 般,运也。；组词：这般东西；百般劝解；般般(种种；样样；件件) 般 通搬”', '小学', '1'),
    ('舰', 'jiàn', '10', '舟', '左右', NULL, '舰 (形声。从舟,监声。本义大型的战船) 同本义 舰,版屋舟。--《玉篇》 舰,御敌船 舳舻千里,前驱不过百舰。--《文选·陆机·辨亡论下》 方连船舰；组词：巡洋舰；驱逐舰；航空母舰；舰户(船舰的门户) 任何大型的航海的船只 用桨、橹、帆或动力推进的有甲板或没有甲板的军用小船', '小学', '1'),
    ('舱', 'cāng', '10', '舟', '左右', NULL, '舱 (形声。从舟,仓声。本义船上居人置物的部位) 船或飞机中分隔开来载人或装东西的部分 中轩敞者为舱。--明·魏学洢《核舟记》；组词：客舱 构成宇宙飞船整体结构的一部分的一个独立单元 船上用来盛水、油或液体的分隔仓柜 舱 cāng 1船或飞机中隔开用来载', '小学', '1'),
    ('舵', 'duò', '11', '舟', '左右', NULL, '舵 (形声。从舟,它声。本义船尾用以控制行向的装置) 同本义。也作柁、杕 可活动的辅助机翼,在飞行时用来控制其水平动向 舵 duò船只、飞机等控制方向的装置', '小学', '1'),
    ('舶', 'bó', '11', '舟', '左右', NULL, '舶 (形声。从舟,白声。本义大船,海船) 同本义 昔孙权装大船,名之曰长安”亦曰大舶。--郦道元《水经注》；组词：舶物(用船舶运来的外国货物)；舶主(古代波斯国的别名', '小学', '1'),
    ('舷', 'xián', '11', '舟', '左右', NULL, '舷 (形声。从舟,玄声。字义船边) 船、飞机等两侧的边沿 两兄弟凭舷痛饮,谈说古今的事。--《儒林外史》 船的两侧 舷xián船的两侧右~。左~。', '小学', '1'),
    ('船', 'chuán', '11', '舟', '左右', NULL, '船〈名〉 (形声。本义水运工具。古称舟) 同本义 船,舟也。--《说文》。段注古人言舟,汉人言船,毛以今语释古,故云舟即今之船也。” 小曰舟,大曰船。--《说文义证》 有渔父者；组词：船坞(船厂；停泊、修理或制造船只的地方)；船把板(船主)；船不漏针(比喻绝无遗失)；船多不碍路(数量虽多,但互不妨碍)', '小学', '1'),
    ('艇', 'tǐng', '12', '舟', '左右', NULL, '艇〈名〉 (形声。从舟,廷声。本义轻便小船) 同本义 岸上无人小艇斜。--唐·孙光宪《竹枝词》 以小艇游庙中。--宋·陆游《过小孤山大孤山》；组词：游艇；救生艇；橡皮艇；鱼雷艇；艇板(跳板)；艇子(小船；亦指船夫) 大船 如登陆艇；潜水艇 艇tǐng 1.轻便或轻便快', '小学', '1'),
    ('艘', 'sōu', '15', '舟', '左右', NULL, '艘 (形声。从舟,叟声。《说文》从木。本义船的总称) 同本义 海中大船 艘,海大舡也。--《艺文类聚》 艘 用于船只计数 乃取蒙冲斗舰十艘,载燥荻枯柴,灌油其中；组词：两艘油船；三艘巡洋舰 艘次 艘sōu量词', '小学', '1'),
    ('良', 'liáng', '7', '艮', '上下', NULL, '良〈形〉 (形声。本义善良) 同本义 良,善也。--《说文》 德音无良。--《诗·邶风·日月》 人之无良。--《诗·鄘风·鹑之奔奔》 侍中、侍郎郭攸之、费袆、董允等,此皆良实；组词：天良(良心)；驯良(和顺善良)；良正(善良正直) 良好；美好 良剑期乎断,不期乎镆铘；良马期乎千里,不期乎骥骜', '小学', '1'),
    ('艰', 'jiān', '8', '艮', '左右', NULL, '艰 (形声。表示与土有关,艮声。本义土难治理) 同本义 艰,土难治也。--《说文》。段玉裁注引申之,凡难理皆曰艰。” 艰难;困难 艰,难也。--《尔雅》 艰则无咎；组词：艰虞(艰难困苦)；艰屯(艰苦险阻)；艰患(艰难祸患)；艰急(困难)；艰深(艰难深奥,晦涩难解)；艰(芼)jiān 1.', '小学', '1'),
    ('色', 'sè', '6', '色', '上下', NULL, '色〈名〉 (会意。甲骨文中象一个人驮另一个人,仰承其脸色。本义脸色) 同本义 色,颜气也。；组词：面色(脸上的气色)；色喜(脸上显出欢喜之色)；色笑(开颜欢笑)；色沮(脸 色shǎi 1.指颜色(用于口语)掉~儿', '小学', '1'),
    ('艳', 'yàn', '10', '色', '左右', NULL, '艳 从色。豷,丰大。色,色彩。丰大而有色彩。本义鲜艳,艳丽) 同本义 苂,好而长也。--《说文》 目逆而送之,曰,美而艳。--《左传·桓公元年》 艳妻煽方处；组词：艳色(常用以指美女、美色)；艳段(宋元杂剧中,在正剧之前表演的一段短剧)；艳质(美丽的姿质) 文辞华丽 信言不艳,贯居于', '小学', '1'),
    ('艺', 'yì', '4', '艹', '上下', NULL, '艺 (会意。甲骨文字形。左上是木”,表植物;右边是人用双手操作。又写成埶”,从坴,土块;从乵,拿◇繁化为藝”。艺”从帅”,乙声。本义种植)；组词：艺植(耕种；栽植)；艺人(耕种的人)；艺圃(种植花卉园圃) 艺 技能；才能 艺(藝)yì 1.才能,技能,本领手~', '小学', '1'),
    ('艾', 'ài', '5', '艹', '上下', NULL, '艾〈名〉 (形声。本义草名) 即艾蒿 。一种菊科的多年生草本植物叶制成艾绒,供针灸用 艾,冰台也。；组词：艾人(用艾草结成的草人', '小学', '1'),
    ('节', 'jié', '5', '艹', NULL, NULL, '节 --用于节骨眼”、节子”等复音词中 节骨眼,节骨眼儿 榞枅祵溃樬蕩畧? 做工作要抓住节骨眼儿,别乱抓一气 节子 节 (形声。从竹,即声。本义竹节)；组词：节根(草木的节与根)；节旄(竹节上所缀 节(節)jiē 1. 2.见jié', '小学', '1'),
    ('芋', 'yù', '6', '艹', '上下', NULL, '芋〈名〉 (形声。从苃,于声。本义植物名。俗称芋艿”) 同本义 芋,大叶实根,骇人,故谓之芋也。；组词：芋火(煨芋的炭火)；芋渠(大芋头', '小学', '1'),
    ('芍', 'sháo', '6', '艹', '上下', NULL, NULL, '小学', '1'),
    ('芒', 'máng', '6', '艹', '上下', NULL, '芒 (形声。从苃,亡声。本义谷类植物种子壳上或草木上的针状物) 同本义 芒,草聑也。--《说文》。徐锴曰谓麦谷为芒种是也。” 种之芒种。--《周礼·地官·稻人》。郑众注芒种；组词：芒茅(茅草的一种)；芒履(芒屣,芒屦,芒鞋)；芒鞋(用芒茎外皮编成的鞋', '小学', '1'),
    ('芙', 'fú', '7', '艹', '上下', NULL, '芙 (形声。从苃,夫声。芙蕖荷花的别名。本义芙蓉荷花的别名) 同本义 芙蓉覆水,秋兰被涯。', '小学', '1'),
    ('芜', 'wú', '7', '艹', '上下', NULL, '芜 (形声。从苃,无声。本义土地不耕种而荒废) 同本义 田甚芜,仓甚虚。--《老子》 田彼南山,芜秽不治。--杨恽《报孙会宗书》 田园将芜。--晋·陶渊明《归去来兮辞》；组词：芜荒(荒芜)；芜绝(荒芜断绝)；芜蔓(荒芜；荒凉)；芜废(荒废)；芜荟(荒芜)；芜蒌(野草)；芜旷(犹荒芜) 杂乱 陆文', '小学', '1'),
    ('芝', 'zhī', '6', '艹', '上下', NULL, '芝 (会意。从苃,从之,之亦声。本义灵芝,菌类植物的一种) 同本义 芝,神草也。--《说文》 采三秀兮于山间。--《楚辞·山鬼》。注三秀,芝草也。” 拔搴元芝兮；组词：芝zhī 1. 2.〈古〉指白芷', '小学', '1'),
    ('芥', 'jiè', '7', '艹', '上下', NULL, '芥 (形声。从苃,介声。本义蔬菜名。即芥菜”) 同本义 芥,芥菜也。--《说文》 天地之行,芥苦味也。--《春秋繁露》 脍,春用葱,秋用芥。--《礼记·内则》；组词：芥子(芥菜的种子', '小学', '1'),
    ('芦', 'lú', '7', '艹', '上下', NULL, '芦 (形声。从苃,眗声。本义草名。芦菔) 芦菔,似芜菁。今作萝卜 芦,芦菔也。--《说文》。段注今之萝卜也。” 芜菁,共紫华者谓之芦菔。--《方言》三；组词：芦萹(莱菔的别名', '小学', '1'),
    ('芬', 'fēn', '7', '艹', '上下', NULL, '芬〈名〉 (会意。从苃,从分,分亦声。本义香气) 同本义 芬,草初生其香分布也。--《说文》 芬,芬香也。--《广雅》 天地之行分、苦味也。--《春秋繁露》 苾苾芬芬；组词：芬苾(芳香)；芬烈(香气郁烈)；芬郁(香气浓郁；亦谓芳香和腐臭)', '小学', '1'),
    ('芭', 'bā', '7', '艹', '上下', NULL, '芭 (形声。巴声。本义1香草名。2芭蕉) 古书上说的一种香草 传芭兮代舞。--《楚辞·九歌·礼魂》 芭蕉 乘兴书芭叶,闲来入豆房。--段成式《赠诸上人》；组词：芭叶(芭蕉的叶片)；芭蕉扇 通笆”', '小学', '1'),
    ('芯', 'xīn', '7', '艹', '上下', NULL, '芯〈名〉 灯心草茎中的髓,俗称灯芯” 家有千金,不添双芯,俭之积也', '小学', '1'),
    ('花', 'huā', '7', '艹', '上下', NULL, '花 同本义 草木花的总称 百卉含蘤。--《汉书·张衡传》。注蘤,古花字也。经传皆以华为之。” 菊垂今秋花,石戴古车辙。--杜甫《北征》 一丛深色花,十户中人赋', '小学', '1'),
    ('芳', 'fāng', '7', '艹', '上下', NULL, '芳〈名〉 (形声。从苃,方声。本义花草) 同本义 野芳发而幽香。--宋·欧阳修《醉翁亭记》；组词：芳芷(香草名)；芳苓(芳荃', '小学', '1'),
    ('芹', 'qín', '7', '艹', '上下', NULL, '芹〈名〉 芹菜 芹,楚葵也。--《说文》 即今之水芹菜》 言采其芹。--《诗·小雅·采菽》 薄采其芹。--《诗·鲁颂·泮水》 菜之美者,云梦之芹。--《吕氏春秋·本味》 芹菹兔醢', '小学', '1'),
    ('芽', 'yá', '7', '艹', '上下', NULL, '芽 (形声。从苃,牙声。本义尚未发育成长的枝、叶或花的雏体) 同本义 芽,萌芽也。--《说文》。段注古多以牙为芽。” 芽,孽也。--《广雅·释草》 遂令黄泉下,萌芽夭句尖；组词：芽茶(最嫩的茶叶) 形状像芽的东西 芽yá 1.植物的幼体,刚长出来能发育成茎、叶或花的部分发~', '小学', '1'),
    ('苇', 'wěi', '7', '艹', '上下', NULL, '苇 (形声。从苃,韦声。本义芦苇) 同本义 苇,大葭也。--《说文》 震为萑苇。--《易·说卦》；组词：苇车(简陋的柴车)；苇杖(蒲鞭,用以施轻刑的草鞭子)；苇索(一种用蒲苇编结而成的绳索', '小学', '1'),
    ('苍', 'cāng', '7', '艹', '上下', NULL, '苍 (形声。从苃,仓声。本义草色) 同本义,引申为青黑色 苍,草色也。--《说文》 苍,青也。--《广雅》 在色为苍。--《素问·阴阳应象大论》。注谓薄青色。” 彼苍者天；组词：苍山(青山)；苍苔(青苔)；苍头(旧指仆人『时奴仆皆以深青色巾包头,故名；又指老年人) 灰白色 满面尘灰烟火色,两鬓苍苍', '小学', '1'),
    ('苏', 'sū', '7', '艹', '上下', NULL, '苏 (形声。从苃,稣声。从苃,与植物有关。本义植物名,即紫苏) 同本义 的种子。可以入药、榨油) 柴草 樵苏脂烛,莫非种植之物也。', '小学', '1'),
    ('苔', 'tái', '8', '艹', '上下', NULL, '舌苔” 舌上的垢腻 苔〈名〉 (形声。从苃,台声。本义青苔;也指苔类植物) 植物名。本作菭。又名地衣,水衣。属隐花植物类,根、茎、叶区别不明显,有青、绿、紫等色,多生于阴湿地方；组词：苔衣(即青苔', '小学', '1'),
    ('苗', 'miáo', '8', '艹', '上下', NULL, '苗 (会意。从田,从苃。田里生长的形状象草的东西。本义禾苗,未吐穗的庄稼) 同本义;泛指初生的植物 苗,草生于田者。；组词：补苗；间苗；秧苗；麦苗；豆苗；壮苗(健壮的幼苗) 指禾谷之实 苗miáo 1.没有吐穗的庄稼', '小学', '1'),
    ('苛', 'kē', '8', '艹', '上下', NULL, '苛〈名〉 (形声。本义小草) 同本义 苛,小草也。--《说文》 疥疮 疾痛苛痒。--《礼记·内则》；组词：苛痒(疥疮痒) 病', '小学', '1'),
    ('苞', 'bāo', '8', '艹', '上下', NULL, '苞 (形声。本义席草,可制席子和草鞋) 同本义 苞,苞草也,南阳以为粗履。--《说文》 浸彼苞稂。--《诗·曹风·下泉》 又 浸彼包萧。 浸彼苞蓍。 系于包桑；组词：包屦(古人居丧所穿的一种草鞋) 苞片,花未开时包着花朵的变态叶 山桃发红萼,野蕨渐紫苞', '小学', '1'),
    ('苟', 'gǒu', '8', '艹', '上下', NULL, '苟 (形声。从苃,句声。本义草名。又菜名) 同本义 苟,苟草也。--《说文》 苟贞夫。--《急就篇》。注苟,草名也。” 苟 随便,轻率 生亦我所欲,所欲有甚于生者,故不为苟得也；组词：一丝不苟；不苟言笑；苟言(言谈轻率随便) 贪求 卑下 苟 姑且；暂且 苟者,偷合之称', '小学', '1'),
    ('若', 'ruò', '8', '艹', '上下', NULL, '若 (象形。甲骨文字形,象一个女人跪着,上面中间象头发,两边两只手在梳发,表示顺从”。本义顺从)；组词：若时(顺应天时)；若淑(温顺而善良) 如同；像 圣人之德,若天之高,若地之普', '小学', '1'),
    ('苦', 'kǔ', '8', '艹', '上下', NULL, '苦〈名〉 (形声。从苃,古声。本义苦菜) 同本义,即荼” 苦,大苦苓也。--《说文》 采苦采苦,首阳之下。--《诗·唐风·采苓》 濡豚包苦实蓼。--《礼记·内则》 天子于是食苦；组词：苦苣(野苣', '小学', '1'),
    ('苫', 'shān', '8', '艹', '上下', NULL, '苫〈名〉 (形声。占声。本义用茅草编成的覆盖物) 同本义 苫,盖也。--《说文》 白盖谓之苫。--《尔雅》。注白茅苫。今江东呼为盖。”李注编菅茅以盖屋者曰苫。” 寝苫；组词：草苫子；苫宇(草庐)；苫茨(茅草盖的屋顶)；苫盖(茅草编的覆盖物', '小学', '1'),
    ('英', 'yīng', '8', '艹', '上下', NULL, '英 (形声。从苃,央声。本义花) 同本义 英,草荣而不实者。--《说文》 有女同行,颜如舜英。--《诗·郑风·有女同车》。传华也。” 秋菊之落英。--《离骚·夕餐》。注华也；组词：落英(花落)；英华(言花木之美) 矛上的羽饰 二矛重英,河上乎翱翔', '小学', '1'),
    ('苹', 'píng', '8', '艹', '上下', NULL, '苹 (形声。从苃,平声。本义浮萍) 同本义 苹,无根浮水而生者。--《说文》 蒿的一种。即青蒿 呦呦鹿呜,食野之苹。--《诗·小雅·鹿鸣》；组词：苹藻主(妻子)；苹敬(礼金) 同蘯”', '小学', '1'),
    ('茁', 'zhuó', '8', '艹', '上下', NULL, '茁 (会意。从苃,从出,出亦声。本义植物才生长出来的样子)同本义 茁,草初生出地貌。--《说文》 彼茁者葭。--《诗·召南·驺虞》 向东风种就,一亭兰茁,玉香初茂；组词：茁茁(草刚长出的样子)；茁茂(茂盛)；茁肥(肥壮)；茁实(扎实；健壮结实) 茁 生出；生长 牛羊茁壮长而已矣', '小学', '1'),
    ('茂', 'mào', '8', '艹', '上下', NULL, '茂 (形声。从苃,戊声。本义草木繁盛) 同本义 茂,草丰盛也。--《说文》 草不溃茂。--《诗·大雅·召卬》 种之黄茂。--《诗·大雅·生民》 树木丛生,百草丰茂；组词：茂英(繁盛的花朵)；茂苑(花木茂盛的苑囿)；茂育(滋长繁盛)；茂实(丰盛的果实', '小学', '1'),
    ('范', 'fàn', '8', '艹', '上下', NULL, '范 (形声。从车,筪省声。本义古代遇大事出车,先辗过祭坛及祭牲的一种祭祀活动,祭路神) 同本义 假借为筪。法则 範,法也。範,常也。；组词：范防(防范)；范轨(法则,模范) 典范 宇文新州之懿范', '小学', '1'),
    ('茄', 'qié', '8', '艹', '上下', NULL, '茄 jia 荷梗 通荷” 译音用字。如雪茄 茄克 茄〈名〉qie (形声。从苃,加声。本义茄子。植物名)', '小学', '1'),
    ('茅', 'máo', '8', '艹', '上下', NULL, '茅 (形声。从苃,矛声。本义草名。即白茅,俗称茅草) 同本义 茅,菅也。--《说文》。按,菅之不滑泽有毛者,可缩酒;又以为藉。 藉用白茅。--《易·大过》 昼尔于茅；组词：茅飞渡江；抱茅入竹；茅卜(古代卜法之一', '小学', '1'),
    ('茉', 'mò', '8', '艹', '上下', NULL, '茉莉,茉莉花 (形声。从苃,末声。茉莉,植物名) 茉mò 1常绿灌木,夏季开白花,香味浓。供观赏。花可提取芳香油,也常用来熏制茶叶。 2', '小学', '1'),
    ('茎', 'jīng', '8', '艹', NULL, NULL, '茎 (形声。从苃,巠声。本义植物的主干) 同本义 茎,枝柱也。谓众枝之主。--《说文》 茎,本也。--《广雅》。按,字从苃,苃曰茎,木日干。散文则草木枝亦皆曰茎。 西方有木焉；组词：块茎；根茎；球茎；鳞茎；地上茎；地下茎；茎立(像草茎一样的直立)；茎英(古乐名) 柱；竿 抗仙掌以承露,擢双立之金茎', '小学', '1'),
    ('茧', 'jiǎn', '9', '艹', '上下', NULL, '茧 许多昆虫幼虫在化蛹前包围身体大部分的由丝组成的外皮,在其中化蛹。家蚕的茧是商业蚕丝的来源 生自蚕茧。；组词：蚕茧；茧儿(喻指秘事；名堂；见不得人的事)；茧素(白色的生绢)；茧纸(用蚕茧制作的纸) 指茧丝 絮丝棉的衣服 通趼”', '小学', '1'),
    ('茫', 'máng', '9', '艹', '上下', NULL, '茫 (形声。从水,芒声。本义水浩大的样子) 同本义 悯其若迷。--唐·韩愈《朱文公校昌黎先生集》 拔剑四顾心茫然。--唐·李白《行路难》；组词：茫无涯际(茫无边际', '小学', '1'),
    ('茬', 'chá', '9', '艹', '上下', NULL, '茬 (形声。从苃,在声。)本义草茂盛的样子) 栽培植物(如麦子、玉米、苜蓿、豆或草)收割后余留的残株 茬口 茬子 他下巴 茬 chá 1农作物收割后留在地里的茎和根麦~', '小学', '1'),
    ('茴', 'huí', '9', '艹', '上下', NULL, '茴 茴香 茴,茴香。--《玉篇》 蘹香,北人呼为茴香,声相近也。--《本草纲目》引苏颂《图经本草》 该种植物种子,常用作香料 茴香 茴香豆 茴香子 茴huí 1. 2. 香油', '小学', '1'),
    ('茵', 'yīn', '9', '艹', '上下', NULL, '茵 (形声。从苃,因声。本义车垫子。字本作因”) 同本义 茵,车重席也。--《说文》 交茵畅毂。--《秦风·小戎》。传文茵虎皮也。” 茵席。--《礼记·少仪》。注著褥也；组词：茵伏(茵轼', '小学', '1'),
    ('茶', 'chá', '9', '艹', '上下', NULL, '茶 茶树 茶叶。由茶树的嫩叶加工制成,供泡取饮料用 前月浮梁买茶去。--唐·白居易《琵琶行(并序)》；组词：茶市(茶叶市场) 用茶叶泡制、烹制或煎制而成的饮料 唐人煎茶,用姜用盐', '小学', '1'),
    ('茸', 'róng', '9', '艹', '上下', NULL, '茸 (形声。本义草初生时又细又柔软) 同本义 茸,草茸茸貌。--《说文》 在阘茸之中。--司马迁《报任安书》。注细毛也。”；组词：茸壑(长着青草、苔藓的山洞、土穴) 茸 鹿茸的简称 河天月晕鱼分子,槲叶风微鹿养茸', '小学', '1'),
    ('荆', 'jīng', '9', '艹', '左右', NULL, '荆 (形声。从苃,刑声。本义一种灌木) 灌木名。又名楚 荆,楚木也。--《说文》 以牡荆书幡。--《汉书·郊祀志》。注作幡柄也。” 白刑堪为履；组词：荆 荆jīng 1.落叶灌木,掌状复叶或单叶,夏秋开紫蓝色小花', '小学', '1'),
    ('草', 'cǎo', '9', '艹', '上下', NULL, '草 (形声。从苃,早声。小篆苃,象两棵草形,是草的本字。今草”字系假借字,原是皂”的本字。《说文》草,草斗,栎实也”(栎实栎树的荚果,即皂角)。借为草木”之 草”以后', '小学', '1'),
    ('荐', 'jiàn', '9', '艹', '上下', NULL, '荐 (形声。从草,存声。本义草垫子) 同本义 荐,薦席也。--《说文》。按,凡亲地者谓之筵,加于筵者谓之席。席即因也,重于筵也。 荐 再;又;接连 荐,再也。--《尔雅》 荐；组词：荐仍(接连而来)；荐更(反复经历)；荐臻(荐蓁', '小学', '1'),
    ('荒', 'huāng', '9', '艹', '上下', NULL, '荒 (形声。从乷,巟声。本义荒芜) 同本义 荒,芜也,一曰草荒地也。--《说文》 我居圉卒荒。--《诗·大雅·召》 野荒民散则削之。--《周礼·大司马》 地广大荒而不治；组词：荒陂(荒芜的坡地)；荒梗(土地荒废,道路阻隔)；荒楚(杂草树木蔓生的地方)；荒白(荒芜)；荒居(荒凉的住处', '小学', '1'),
    ('荔', 'lì', '9', '艹', '上下', NULL, '茘 草名。即马蔺” 荔枝 荔(茘)lì', '小学', '1'),
    ('荚', 'jiá', '9', '艹', '上下', NULL, '荚 (形声。从苃,夹声。本义荚果”的简称) 同本义。豆科植物的长角果或蓇葖,为单片或有两个以上果片(如蒴果) 荚,草实也。；组词：豆荚；皂荚；结荚；荚物(植物果实的一种名称', '小学', '1'),
    ('荞', 'qiáo', '9', '艹', '上下', NULL, '荞 荞麦 荞(蕎)qiáo 荞jiāo 1.药草名。即大戟。', '小学', '1'),
    ('荠', 'qí', '9', '艹', '上下', NULL, '荠 ji 指荠菜 荠麦弥望。--宋·姜夔《扬州慢》词 荠麦青青。 其甘如荠。--《诗·邶风·谷风》 荠菜 见荸荠” qi 荠(薺)qi 1. 荠(薺)jì 1.荠菜', '小学', '1'),
    ('荡', 'dàng', '9', '艹', '上下', NULL, '荡 (会意。从皿,从汤,汤亦声。本义洗涤) 同本义 荡亡秦之毒螫。--班固《西都赋》 动;摇动;震动 此四六者不荡,胸中则正。；组词：荡突(冲撞)；荡心(摇荡心神)；荡摇(动摇)；荡荡悠悠(摇荡、飘流的样子) 清除 荡平塞表', '小学', '1'),
    ('荣', 'róng', '9', '艹', '上下', NULL, '荣 (形声。从木,荧省声。本义梧桐。又金文字形,象两支如火把相互照耀的花朵或穗头形) 同本义 荣,桐木也。；组词：荣悴(草木的开花与凋萎)；荣年(百花争艳的季节)；荣色(花的色彩) 飞檐,屋檐两头翘起的部分 直于东荣', '小学', '1'),
    ('荤', 'hūn', '9', '艹', '上下', NULL, '荤 (形声。从乷,军声。本义指葱蒜类辛臭的蔬菜) 同本义 荤,臭菜也。--《说文》 荤,辛菜也。--《苍颉篇》 膳荤。--《仪礼·士相见礼》。注辛物,葱韭之属。” 膳于君有荤桃茢；组词：荤辛(味道浓重、辛辣的蔬菜', '小学', '1'),
    ('荧', 'yíng', '9', '艹', '上下', NULL, '荧 (会意。从焱冂。焱,火花。冂,远方的边界∠起来表示远处的火花,光微弱。本义光微弱的样子)；组词：荧烛(微弱的烛光)；荧然(光微弱的样子)；荧燎(微光)；荧耀(微光)；荧华(闪烁的亮光)；荧煌(辉煌)；荧晔(光明的样子', '小学', '1'),
    ('药', 'yào', '9', '艹', '上下', NULL, '药 (形声。从苃,乐声。本义治病的物品。药物;药材。一般是植物,故从苃) 同本义 药,治病草也。；组词：药肆(药店)；药贴(处方单)；药封(用红纸袋封送的诊断费)；药案(药方)；药王(指治病用药如神的人)；药引(中医处方中先', '小学', '1'),
    ('荷', 'hé', '10', '艹', '上下', NULL, '荷〈名〉 (形声。从苃,何声。本义植物名。也称莲,别称芙蕖、芙蓉。地下茎称藕,子实称莲,花叶供观赏) 植物名。即莲 荷,芙蕖叶。；组词：荷月(指农历六月,以荷花盛开,故名荷月)；荷衣(荷叶)；荷芰(莲与菱)；荷花(莲花', '小学', '1'),
    ('荸', 'bí', '10', '艹', '上下', NULL, '荸荠 一种多年生草本植物,种植在水田中,具匐匍茎,先端膨大为球茎 这种植物的球茎,可作蔬菜,可代水果,也可制淀粉,作中药 荸 bí 【荸荠】多年生草本植物,通常栽培在水田里', '小学', '1'),
    ('莉', 'lì', '10', '艹', '上下', NULL, '莉〈名〉 人名用字 见茉莉” 莉lì见于人名。', '小学', '1'),
    ('莫', 'mò', '10', '艹', '上下', NULL, '莫 表示否定,相当于不” 莫相知。--唐·柳宗元《三戒》 莫敢过其门。--唐·柳宗元《童区寄传》 故莫能知。--宋·苏轼《石钟山记》 莫能得。；组词：莫得(没有)；爱莫能助；一筹莫展；莫可奈何(犹言无可奈何)；莫之奈何(对它们无可奈何)；莫或(没有)；莫奈何(无可奈何)', '小学', '1'),
    ('莱', 'lái', '10', '艹', '上下', NULL, '莱 (形声。从苃,来声。本义草名。即藜) 草名,又名藜 莱,蔓华也。--《说文》 南山有台,北山有莱。--《诗·小雅·南山有台》 郊外休耕的田 古国名 姓 莱驹为右', '小学', '1'),
    ('莲', 'lián', '10', '艹', '上下', NULL, '莲 (形声。从苃,连声。本义莲子,荷的种子) 同本义 莲,扶渠之实也。--《说文》 荷其实莲。--《尔雅》。注谓房也。” 益树莲茭。--《淮南子·本经》 莲藕觚卢；组词：莲的(莲房之实', '小学', '1'),
    ('获', 'huò', '10', '艹', '上下', NULL, '获 (形声。从犬,蒦声。按甲骨文从隹从又,表示捕鸟在手。本义猎得禽兽) 同本义 获,猎所获也。；组词：获兽；获兔；获者(猎得禽兽者) 俘获 遇犬获之', '小学', '1'),
    ('莹', 'yíng', '10', '艹', '上下', NULL, '莹 (形声。从玉,荧省声。本义珠光的光采) 同本义 莹,玉色。一曰石之次玉者。--《说文》 如玉之莹。--《逸论语》 良珠度寸,虽有白仞之水,不能掩其莹。--《韩诗外传》；组词：莹华(光辉) 似玉的宝石 尚之以琼莹乎而', '小学', '1'),
    ('莺', 'yīng', '10', '艹', '上下', NULL, '莺 (形声。从鸟,荣省声。本义鸟羽有文彩的样子) 同本义 春莺,《考声》‘莺,鸟毛有斑纹貌也。--唐·慧琳《一切经音义》 有莺其羽。；组词：莺背色(浅黄带绿的颜色)；莺粉(黄色的粉) 莺 黄莺 暮春三月,江南草长,杂花生树,群莺乱飞', '小学', '1'),
    ('莽', 'mǎng', '10', '艹', '上下', NULL, '莽 (会意。从犬,从茻。原意是犬跑到草丛中逐兔,假借为茻,草丛) 草丛 莽,草也。--《小尔雅》 暴骨如莽。--《左传·哀公元年》 在野曰草芒之臣。--《孟子》 罗千乘于林莽；组词：莽林(泛指草木密集连绵而不能通过的森林；专指热带雨林)；莽渺(深远而渺茫的样子)；莽草(一种有毒植物,又称水莽草”) 草', '小学', '1'),
    ('菇', 'gū', '11', '艹', '上下', NULL, '菇〈名〉 蘑菇 菇(菰)gū蕈香~。蘑~。草~。毒红~。', '小学', '1'),
    ('菊', 'jú', '11', '艹', '上下', NULL, '菊 (形声。从苃,匊声。本义植物名,通称菊花”) 同本义 采菊东篱下。--晋·陶渊明《饮酒诗》 松菊犹存。--晋·陶渊明《归去来兮辞》 还束就菊花；组词：菊实(菊花的果实、种子)；菊枕(菊花枕头)；菊灯(菊花形状的灯笼)；菊水(在河南省西南部', '小学', '1'),
    ('菌', 'jūn', '11', '艹', '上下', NULL, '菌 低等植物的一大类,不开花,没有茎和叶子,不含叶绿素,不能自己制造养料,靠寄生生活,种类很多如细菌、真菌等 组成裂殖菌纲的一大类微小植物中的任一种 菌 (形声。从苃,囷声', '小学', '1'),
    ('菜', 'cài', '11', '艹', '上下', NULL, '菜 (形声。采声。上古时期,菜只指蔬菜,不包括肉类、蛋类,到了中古以后,菜就包括内类、蛋 类及其熟食在内了。本义蔬菜)；组词：种菜；干菜(晒干的蔬菜)；菜食(以食菜为主) 泛指一切菜肴 专指油菜 菜 cài 1蔬菜', '小学', '1'),
    ('菠', 'bō', '11', '艹', '上下', NULL, '菠菜 菠萝 菠萝蜜 菠 bō 【菠菜】藜科。一二年生草本,叶子略呈三角形,根略带红色,雌雄异株。原产伊朗。现为我国主要食用菜之一。 【菠萝】凤梨科,多年生草本。叶大,边缘有锯齿', '小学', '1'),
    ('菩', 'pú', '11', '艹', '上下', NULL, '菩〈名〉 菩提(音译)意为正觉。指对佛教真理”的觉悟 菩,梵言菩提,汉言王道。--《广韵》 又指觉悟的智慧和觉悟的途径;亦指树名,即菩提树 菩萨”佛教名词', '小学', '1'),
    ('菱', 'líng', '11', '艹', '上下', NULL, '菱 柳叶菜科,菱属植物的泛称 菱角 菱形 菱líng 1.又叫"芰"。一年生草本,生在池沼地里。果实有硬壳,有角或无角,绿色或褐色,叫"菱"或"菱角",可生吃也可制淀粉。 2.', '小学', '1'),
    ('菲', 'fēi', '11', '艹', '上下', NULL, '菲〈形〉 花草的香气很浓的--常叠用 菲菲,香也。--《广雅》 芳菲菲兮满堂。--《楚辞·东皇太一》 别来春物已再菲,西望不见红日围；组词：菲薇(草木茂密的样子) 菲〈名〉 一种无色结晶烃c14h10,熔点约100度,其母核由某些生物碱降解生成,用于染料和药物', '小学', '1'),
    ('萄', 'táo', '11', '艹', '上下', NULL, '如葡萄” 萄táo[葡萄]见葡。', '小学', '1'),
    ('萌', 'méng', '11', '艹', '上下', NULL, '萌 (形声。从苃,明声。本义草木的芽) 同本义 萌,草芽也。--《说文》 句者毕出,萌者尽达。--《礼记·月令》。注句,屈生者;芒而直曰萌。” 乃舍萌于四方；组词：萌甲(嫩芽,花木的芽苞) 比喻事情刚刚显露的发展趋势或情况；开端 圣人见微而知萌', '小学', '1'),
    ('萍', 'píng', '11', '艹', '上下', NULL, '萍〈名〉 (会意兼形声。从水,苹,苹亦声。本义浮萍) 同本义 萍,苹也。水草也。--《说文》 蓱始生。--《礼记·月令》。注蓱,萍也。其大者曰蘯。” 山河破碎风飘絮；组词：萍合(浮萍易散,飘泊不定,故用以比喻暂时的聚合)；萍浮(浮萍飘迹水面', '小学', '1'),
    ('萎', 'wěi', '11', '艹', '上下', NULL, '萎 (形声。从苃,委声。本义 同本义 萎,蔫也。--《广韵》 萎,草木枯死。--《集韵》 虽萎绝其何伤兮,哀众芳之芜秽。--《楚辞·离骚》 萎,草木菸也；组词：萎绝(草木枯落)；萎枯(干枯)；萎败(枯萎)；萎悴(枯萎；憔悴) 引申指病危 哲人其萎乎?--《礼记·檀弓上》', '小学', '1'),
    ('萝', 'luó', '11', '艹', '上下', NULL, '萝 (形声。从苃,罗声。本义植物名。指某些蔓生植物,即莪”) 同本义 萝,莪也。蒿属。--《说文》；组词：女萝；藤萝；茑萝；萝蓏(女萝和瓜类) 萝(蘿)luó 1.通常指某些能爬蔓的植物茑~', '小学', '1'),
    ('萤', 'yíng', '11', '艹', '上下', NULL, '萤 动物名。节肢动物门,昆虫纲。萤火虫 萤,萤火。--《广韵》 萤火獜也。--《广雅》 腐草为萤。--《礼记·月令·季夏》。注萤,飞虫营火也。” 红烛秋光冷画屏,轻罗小扇扑流萤；组词：萤焰(萤火虫发出的亮光)；萤光(萤火虫发出的光)；萤点(指萤火虫)；萤案(用萤光照明,以诵读诗书)；萤烛(萤光与烛光', '小学', '1'),
    ('营', 'yíng', '11', '艹', '上下', NULL, '营 (形声。从宫,荧省声。宫,房子,与居住有关。本义四周垒土而居) 同本义 营,币居也。--《说文》。段玉裁注币居,谓围绕而居。”桂馥义证营谓周垣。” 众目营方。--《五等论》；组词：营回(萦回,盘旋往复)；营合(环绕合拢,形成包围圈)；营周(循环)；营绕(环绕) 扎营 营(爄)yíng 1.经管,料理', '小学', '1'),
    ('萧', 'xiāo', '11', '艹', '上下', NULL, '萧 (形声。从苃,肃声。本义艾蒿) 同本义 萧,艾蒿也。--《说文》 萧萩。--《尔雅》。注即蒿。” 共萧茅。--《周礼·甸师》 彼采萧兮。--《诗·王风·采葛》；组词：萧艾(臭草名', '小学', '1'),
    ('萨', 'sà', '11', '艹', '上下', NULL, '萨 佛教用语,即菩萨 姓。明有萨琦 萨(薩)sà姓。', '小学', '1'),
    ('落', 'luò', '12', '艹', '上下', NULL, '落〈动〉luo (形声。从苃,洛声。本义叶落,花落) 同本义 落,凡草曰零,木曰落。--《说文》 草木黄落。--《礼记·月令》 及荣华之未落兮。--《楚辞·离骚》 唯草木之零落兮；组词：落红(落花)；落花媒人(不正当男女关系的撮合人)；落英缤纷(落地零乱的样子)；落木(落叶)；落花时节(指暮春季节) 脱离', '小学', '1'),
    ('著', 'zhù', '11', '艹', '上下', NULL, '著 (形声。从苃,者声。苃”长在地面上,表示显露。本义明显,显著;突出) 同本义 著,明也。；组词：著海内(天下著名)；昭著(明显)；卓著(突出的好)；著姓(有显著名声的家族；使姓氏显著)；著号(著名；著称) 著 显现', '小学', '1'),
    ('葛', 'gě', '12', '艹', '上下', NULL, '葛〈名〉 (形声。从苃,曷声。本义一种植物,纤维可以织布) 植物名。豆科多年生草本植物(pueraria lobata),茎长二三丈,缠绕他物上,花紫红色。茎可编篮做绳；组词：葛巾(用葛布缝制的头巾)；葛衣(葛布制成的衣服)；葛帔(用葛制 葛gě姓', '小学', '1'),
    ('葡', 'pú', '12', '艹', '上下', NULL, '葡糖 葡萄 葡萄干 葡pú', '小学', '1'),
    ('董', 'dǒng', '12', '艹', '上下', NULL, '董 (形声。从苃,重声。1本义草名,即鼎蕫。2督察) 监督;督察 董之用威。--《书·大禹谟》。传董,督也。” 董逋逃。--《左传·文公六年》 董之以武师；组词：董正(监督纠正)；董统鹰扬(为督察纲纪而大展雄才)；董治(监督管理)；董摄(监督治理) 统率 主持；主管 董 dǒng', '小学', '1'),
    ('葫', 'hú', '12', '艹', '上下', NULL, '葫〈名〉 (形声。从苪,胡声。本义蔬菜名。即大蒜”) 蒜有大小,大蒜为葫,小蒜为蒜。--《尔雅翼》 葫芦 一年生蔓草,叶如心形、互生,花白色,果实如大小二球重叠,除其果肉', '小学', '1'),
    ('葬', 'zàng', '12', '艹', '上下', NULL, '葬 (会意。小篆字形。从死”,在茻”中,一”其中,所以荐之。指人死后盖上草席埋藏在丛草中。荐,草席覆盖。本义人死用草覆盖埋葬,后用棺木埋入土中)；组词：葬堂(为古代我国南方少数民族处置死者遗骨的一种方式)；葬式(葬礼)；葬虞(葬礼和虞祭', '小学', '1'),
    ('葱', 'cōng', '12', '艹', '上下', NULL, '葱 (形声。从苃,悤声。本义葱,一种蔬菜) 有圆筒状中空叶的植物之一 ? 葱有冬春二种,有胡葱、木葱、山葱,二月别小葱,六月别大葱,夏葱曰小,冬葱曰大。', '小学', '1'),
    ('葵', 'kuí', '12', '艹', '上下', NULL, '葵〈名〉 (形声。从苃,癸声。本义植物名。指冬葵”,古代主要的蔬菜。《说文》菜也。”也指向日葵”) 蔬菜名。我国古代重要蔬菜之一。可腌制,称葵菹 葵,葵菜也。；组词：葵倾(像葵花向日一样地倾慕)；葵藿(葵花', '小学', '1'),
    ('蒂', 'dì', '12', '艹', '上下', NULL, '蒂 (形声。从苃,帝声。本义花、叶或瓜、果与枝茎连结的部分) 同本义 引申为末尾 蒂落 蒂 dì花朵或瓜果等根茎、枝相连的部分根深~固。', '小学', '1'),
    ('蒋', 'jiǎng', '12', '艹', '上下', NULL, '蒋 (形声。从苃,将声。本义植物名。即茭白”) 古国名 姓 蒋(蕐)jiǎng姓。 蒋jiāng 1.植物名。菰。即茭白。 2.见"蒋蒋"。', '小学', '1'),
    ('蒙', 'méng', '13', '艹', '上下', NULL, '蒙 昏迷,暂时失去知觉的 蒙 欺骗 胡乱猜测 蒙 (形声。从苃,冡声。本义草名) 草名。即菟丝 指蒙童 蒙(矇)mēng 1.欺骗莫~人。欺上~下。 2.昏头发~', '小学', '1'),
    ('蒜', 'suàn', '13', '艹', '上下', NULL, '蒜 (形声。从苃,祘声。本义一种多年生草本植物。有大蒜、小蒜两种) 同本义 栽,从古已有。蒜苗、蒜苔作蔬菜,蒜头作佐料和入药 蒜,荤菜也。；组词：蒜果(蒜头)；蒜气(腋下的气味', '小学', '1'),
    ('蒲', 'pú', '13', '艹', '上下', NULL, '蒲〈名〉 (形声。从水乷,浦声。本义植物名。香蒲) 同本义 蒲,水草也。可以作席。--《说文》 有蒲与荷。--《诗·陈风·泽陂》 共其苇蒲之事。--《周礼·泽虞》。注以为席；组词：蒲甸儿(亦作蒲垫”', '小学', '1'),
    ('蒸', 'zhēng', '13', '艹', '上下', NULL, '蒸 (形声。焌声。本义麻秆) 同本义 蒸,析麻中干也。--《说文》。今俗谓之麻骨棓,古烛用之,故凡用麻干葭苇竹木为烛皆曰蒸。 蒸,炬也。--《广雅》 故云烛用蒸也；组词：蒸薪(木柴) 以麻秸、竹木制成的火炬 中药炮制法之一 蒸zhēng 1.细小的木柴冬伐薪~', '小学', '1'),
    ('蒿', 'hāo', '13', '艹', '上下', NULL, '蒿〈名〉 (形声。从苃,高声。本义草名。有白蒿、青蒿、牡蒿、臭蒿等多种。特指青蒿) 即青蒿 呦呦鹿鸣,食野之蒿。；组词：蒿目时艰(形容对时局忧虑不安) 物之精气蒸出的样子 用同薅” 我把花子 蒿hāo"青蒿"、"黄花蒿"、"茵陈蒿"等植物的', '小学', '1'),
    ('蓄', 'xù', '13', '艹', '上下', NULL, '蓄 (形声。从苃,畜声。本义积聚,储藏) 同本义 蓄,积也。--《说文》 蓄,聚也。--《广雅》 我有旨蓄,亦以御冬。--《诗·邶风·谷风》 洪恩素蓄。--张衡《东京赋》 蓄积者；组词：蓄火(蓄留火种)；蓄菜(把蔬菜制成菜干、咸菜等加以储藏', '小学', '1'),
    ('蓉', 'róng', '13', '艹', '上下', NULL, '蓉 四川成都市的简称 豆类、瓜果煮熟晒干后磨粉做的糕点馅儿 蓉róng 1.成都市的别称。 2.[苁蓉]见苁。[芙蓉]见芙。', '小学', '1'),
    ('蓖', 'bì', '13', '艹', '上中下', NULL, '蓖 bì 【蓖麻】草本植物。种子叫蓖麻子,榨的油可做泻药或润滑油。', '小学', '1'),
    ('蓝', 'lán', '13', '艹', '上下', NULL, '蓝 (形声。从苃,监声。本义蓼蓝) 同本义 蓝,染青草也。--《说文》 终朝采蓝。--《诗·小雅·采绿 青,取之于蓝而青于蓝。--《荀子·劝学》 春来江水绿如蓝；组词：木蓝、菘蓝、马蓝等 佛寺', '小学', '1'),
    ('蓬', 'péng', '13', '艹', '上下', NULL, '蓬〈名〉 (形声。从苃,逢声。本义草名。蓬蒿) 同本义 蓬,蒿也。--《说文》 彼茁者蓬。--《诗·召南·驺虞》 桑蓬矢六。--《礼记·内则》 若纵火于秋蓬。--《楚辞·沈江》；组词：蓬厂(草棚)；蓬窗(草窗,意为破败的窗户)；蓬麻(比喻良好的学习环境)；蓬转(蓬草随风飞转)；蓬衡(陋室茅舍；蓬户衡门)', '小学', '1'),
    ('蔑', 'miè', '14', '艹', '上下', NULL, '蔑〈形〉 (会意。从苜,从戍。苜”是眼睛歪斜无神,戍”是戍守人∠而表示人过于劳倦眼睛歪斜无神。本义眼睛红肿看不清)；组词：蔑如(微细；没有什么了不起)；蔑贱(犹微贱) 蔑 轻视；轻侮', '小学', '1'),
    ('蔓', 'màn', '14', '艹', '上下', NULL, '蔓 (形声。从苃,曼声。本义藤蔓,草本蔓生植物的枝茎) 同本义 蔓,葛属。--《说文》 青树翠蔓。--唐·柳宗元《至小丘西小石潭记》 丹藤翠蔓；组词：蔓生(蔓延生长)；蔓衍(扩展延伸)；蔓 蔓mán 蔓màn 1.蔓生植物的枝茎瓜~', '小学', '1'),
    ('蔗', 'zhè', '14', '艹', '上下', NULL, '蔗 (形声。从苃,庶声。本义甘蔗) 同本义 制成的软糖);蔗浆(甘蔗汁) 比喻甜美 蔗zhè甘蔗,多年生草本。茎有节,含甜汁多,可生吃,主要用于制糖~糖', '小学', '1'),
    ('蔚', 'wèi', '14', '艹', '上下', NULL, '蔚 wei (会意。从苃,尉声。本义牡蒿) 同本义 蓼蓼者莪,匪我伊蔚。--《诗·小雅·蓼莪》 病 五藏无蔚气。--《淮南子·俶真》；组词：蔚气(病气) 蔚 草木茂盛 蔚蔚,茂也', '小学', '1'),
    ('蔫', 'niān', '14', '艹', '上下', NULL, '蔫〈形〉 蔫,物不鲜也。--《广韵》 又如让太阳晒蔫了的花;菠菜蔫了;蔫菸(衰败;枯萎);花瓶里的花蔫了 下垂的样子 我如今剌搭着两箇蔫耳朵；组词：让太阳晒蔫了的花；菠菜蔫了；蔫菸(衰败；枯萎)；花瓶里的花蔫了 下垂的样子 我如今剌搭着两箇蔫耳朵', '小学', '1'),
    ('蔬', 'shū', '15', '艹', '上下', NULL, '蔬 (形声。从苃,疏声。本义蔬菜) 同本义 蔬,菜也。--《说文新附》。先秦无蔬”字,用疏”表示。蔬”是汉魏间字。 令发五苑之蓏、蔬、枣、栗,足以活民；组词：蔬菲(指果菜类粗食)；蔬笋(蔬菜和笋)；蔬饭(蔬菜饭食', '小学', '1'),
    ('蔼', 'ǎi', '14', '艹', '上下', NULL, '蔼 树木生长繁茂 蔼蔼,盛也。--《广雅》 蔼,茂盛貌。--《集韵》 离芳蔼之方壮兮,余萎约而悲愁。--《楚辞·宋玉·九辩》。；组词：蔼彩(芳鲜茂盛的样子) 盛多的样子 蔼蔼、济济,止也', '小学', '1'),
    ('蔽', 'bì', '14', '艹', '上下', NULL, '蔽 (形声。从苃,敝声。本义小草) 遮住,遮掩 蔽,蔽蔽小草也。--《说文》。朱骏声曰此字本训盖覆也。” 蔽,障也,隐也。--《广雅》 蒲蔽。--《周礼·巾车》。注车旁御风尘者；组词：隐蔽(借旁的事物来遮掩)；屏蔽；蔽天(遮蔽天空,布满了整个天空) 蔽 bì 1遮盖；挡住掩~、浮云~日', '小学', '1'),
    ('蕉', 'jiāo', '15', '艹', '上下', NULL, '蕉〈名〉 (形声。从苃,焦声。本义生麻。麻未沤称蕉) 同本义 覆之以蕉。--《列子·周穆王》；组词：蕉布(蕉麻纤维织成的布)；蕉衣(麻布制的衣服)；蕉衫(用麻布缝制的衣衫) 指蕉布 植物名', '小学', '1'),
    ('蕊', 'ruǐ', '15', '艹', '上下', NULL, '蕊 (形声。从苃,惢声。)声。本义花蕊,植物的生殖器官) 同本义 蕊,聚也。--《苍颉篇》 蕊,华也。--《广雅》 贯薜荔之落蕋。--《楚辞·离骚》；组词：蕊香(花蕊的芬芳)；蕊黄(古代妇女装饰面容时,以黄点额,其形似花蕊,故名蕊黄) 花苞 嫩蕊商量细细开', '小学', '1'),
    ('蕴', 'yùn', '15', '艹', '上下', NULL, '蕴 (形声。从苃,蕴声。本义积聚,蓄藏) 同本义 蘮,积也。--《说文》 字亦作蕴”。 蘮,聚也。--《广雅》 芟夷蘮崇之。--《左传·隐公六年》 蓄而弗治将蘮；组词：蕴积(蕴藏；积聚)；蕴哲(蓄藏智慧)；蕴艺(藏蓄的才华) 包藏；包含 万物尽然,而以是相蕴', '小学', '1'),
    ('蕾', 'lěi', '16', '艹', '上下', NULL, '蕾〈名〉 (形声。从苃,雷声。本义含苞未放的花朵) 同本义 蕾lěi含苞待放的花朵莫摘花~。爱护蓓~。', '小学', '1'),
    ('薄', 'báo', '16', '艹', '上下', NULL, '薄 如临深渊,如履薄冰。--《诗·小雅》 又如薄衣(单薄的衣服);薄眉(淡扫蛾眉,用浅黛画的眉毛);薄唇轻言(嘴唇薄,说话声音轻细。引申指说话刻薄);薄纸;薄肉片 土地含养分少；组词：薄衣(单薄的衣服)；薄眉(淡扫蛾眉,用浅黛画的眉毛)；薄唇轻言(嘴唇薄,说话声音轻细', '小学', '1'),
    ('薇', 'wēi', '16', '艹', '上下', NULL, '薇〈名〉 草名,又名大巢菜” 采薇而食之。--《史记·伯夷传》 采薇而食者。--明·顾炎武《复庵记》 知君秉性甘薇蕨,暇日相思还杖藜。--方文《访姚若侯山中不值留此》；组词：薇藿(薇,菜名,又名野豌豆；藿为豆叶', '小学', '1'),
    ('薛', 'xuē', '16', '艹', '上下', NULL, '薛 一种草本植物,即赖蒿” 薛、莎、青藊。--司马相如《子虚赋》 用莎草编制的雨衣 春秋时国名 姓 薛xuē 1.一种草。 2.周代诸侯国名。在今山东省滕州一带。', '小学', '1'),
    ('薪', 'xīn', '16', '艹', '上下', NULL, '薪〈名〉 同本义 薪,荛也。--《说文》 收秩薪柴。--《礼记·月令》。注大者可析谓之薪。” 薪蒸材木。--《周礼·委人》。注粗者曰薪,细者曰蒸。” 以薪以蒸；组词：薪火(柴火)；薪桂(薪贵于桂', '小学', '1'),
    ('薯', 'shǔ', '16', '艹', '上下', NULL, '薯 薯类作物的统称 藷藇,署预也。--《广雅》。王念孙曰今之山药也。根大,故谓之藷藇 景山,其上多藷藇。--《北山经》。藷与藇同。 一种草本植物的块茎,这种植物的膨大地下茎', '小学', '1'),
    ('藏', 'cáng', '17', '艹', '上下', NULL, '藏 (形声,臧声。本义把谷物保藏起来) 储积,收藏 农夫春耕夏耘,秋敛冬藏。--《墨子·三辩》 子不闻藏书者乎?--清·袁枚《黄生借书说》；组词：矿藏；收藏(收集保藏) 隐匿 藏,匿也', '小学', '1'),
    ('藐', 'miǎo', '17', '艹', '上下', NULL, '藐 (形声。从苃,貌声。本义小,幼稚) 同本义 孤女藐焉始孩。--潘岳《寡妇赋》 又如藐孤(弱小的孤儿);藐躬(孱弱的躯体);藐然(幼小的样子)；组词：藐孤(弱小的孤儿)；藐躬(孱弱的躯体)；藐然(幼小的样子)；藐藐(幼小的样子) 孤独的 通邈”', '小学', '1'),
    ('藕', 'ǒu', '18', '艹', '上下', NULL, '藕〈名〉 莲的地下茎,肥大有节,中间有管状小孔,可以吃,也可作中药 莲实与藕。--明·李渔《闲情偶寄·种植部》；组词：藕心(古代钱币名称,汉时所铸,四方而有孔,形似破藕)；藕灰(藕色)；藕合(藕荷)；藕荷(浅紫而略带红的颜色)；藕色(浅灰', '小学', '1'),
    ('藤', 'téng', '18', '艹', '上下', NULL, '藤〈名〉 (形声。从艹,滕声。本义木本蔓生植物的枝茎) 同本义 石角钩衣破,藤枝刺眼新。--杜甫《奉陪郑驸马韦曲》 丹藤翠蔓。--宋·陆游《过小孤山大孤山》 交加之藤', '小学', '1'),
    ('藻', 'zǎo', '19', '艹', '上下', NULL, '藻 (形声。从苃,澡声。本义藻类植物,古专指水藻) 同本义 薄采其藻。--《诗·鲁颂·泮水》 蘯蘩蕰藻之菜。--《左传·隐公三年》。注聚藻也。” 于以采藻,于彼行潦；组词：藻火(水藻和火焰', '小学', '1'),
    ('蘑', 'mó', '19', '艹', '上下', NULL, '蘑菇 蘑菇 你别跟她蘑菇了,她还有急事呢 蘑mó蘑菇,泛指食用菌类松~。口~。', '小学', '1'),
    ('蘸', 'zhàn', '22', '艹', '上下', NULL, '蘸 用物沾染液体 脱了衣裳,坐在石上,把七尺混天绫放在水里,蘸水洗澡。--《封神演义》 又如蘸甲(斟酒满杯,手端酒杯时,指甲沾到酒。比喻畅饮)；组词：蘸甲(斟酒满杯,手端酒杯时,指甲沾到酒', '小学', '1'),
    ('虎', 'hǔ', '8', '虍', NULL, NULL, '虎〈名〉 (象形。金文字形象以虎牙、虎纹为特征的虎形。本义老虎) 同本义 虎,山兽之君。--《说文》 阚如虓虎。--《诗·大雅·常武》 虎狼之心；组词：虎螭(虎与龙)；虎啸(虎吼叫)；虎跃(猛虎腾跃)；虎残(虎口余生) 凡伤害物 虎hǔ 1.通称老虎', '小学', '1'),
    ('虏', 'lǔ', '8', '虍', NULL, NULL, '虏 (形声。从力,从毌声。毌”即贯”字,是穿钱用的绳索。这里表示用绳索拘捕的意思。本义俘获)；组词：虏掠(虏获掠夺)；虏夺(虏掠抢夺)；虏暴(残害暴虐他人,一如奴隶)；虏略(虏获掠夺) 虏(虜)lǔ 1.俘获~获', '小学', '1'),
    ('虐', 'nüè', '9', '虍', NULL, NULL, '虐〈形〉 (会意。小篆字形。从虍,爪人。即虎足反爪伤人。隶变后省略人”字。本义凶恶,残暴)；组词：虐世(残暴的时代)；虐人(残暴凶狠的人)；虐暴(暴虐,残暴酷虐)；虐焰(残暴的气焰)；虐行(残暴的行为)；虐刻(残暴苛刻', '小学', '1'),
    ('虑', 'lǜ', '10', '虍', NULL, NULL, '虑 (形声。从思,虍声。本义思虑,谋划) 同本义 虑,谋思也。--《说文》 非士无与虑国。--《墨子·亲士》 弗虑弗图。--《诗·小雅·雨无止》 礼之中焉,能思索谓之能虑；组词：考虑(思索问题,以便做出决定)；虑尽(谋划穷尽)；虑佚(思虑放荡失当)；虑事多暗(考虑事情不明)；虑思(思虑,考虑)；虑', '小学', '1'),
    ('虚', 'xū', '11', '虍', NULL, NULL, '虚 (墟”的古字)(形声。小篆字。从丘,虍声。丘,山丘。本义大土山) 同本义 虚,大丘也。昆仑丘谓之昆仑虚。；组词：虚莽(墟丘和草莽) 住所；处所 郑国,今河南之新郑,本高辛氏火正祝融之虚也', '小学', '1'),
    ('虫', 'chóng', '6', '虫', NULL, NULL, '虫 (会意『字部首之一,从虫”的字多与昆虫、蛇等有关。按虫”甲骨文字形象蛇形,本读琯穓即虺,是一种毒蛇◇为蟲”的简体。本义昆虫的通称)；组词：虫豸(昆虫；虫子)；虫蛭(小虫子)；虫天(百虫能各自适应所处的环 虫 chóng昆虫和类似昆虫的小动物', '小学', '1'),
    ('虱', 'shī', '8', '虫', NULL, NULL, '虱(蝨)shī寄生在人、畜身上,吸食血液的一种昆虫。有头~。体~子、阴~子等。能传播斑疹伤寒、回归热等疾病讲卫生,爱清洁,消灭~子。', '小学', '1'),
    ('虹', 'hóng', '9', '虫', '左右', NULL, '虹〈名〉 (形声。从虫,工声。甲骨文虹”与杠梁、古玉璜之形相似。本义雨后天空出现的弧形彩晕。主虹称虹,副虹称霓)；组词：虹女(古代把虹比作美人,故称虹霓为虹女)；虹梁(形状似虹的曲梁)；虹霓(即彩虹)；虹霓吐颖(吐气成虹霓', '小学', '1'),
    ('虽', 'suī', '9', '虫', '上下', NULL, '虽 (形声。从虫,唯声。古读。本义虫,似蜥蜴而大) 秦兵旦暮渡易水,则虽欲长侍足下,岂可得哉?；组词：虽故(虽然)；他虽身负重伤,但坚决不下火线 即使...也；纵使 虽人有百口,手有百指,不能指其一端', '小学', '1'),
    ('虾', 'xiā', '9', '虫', '左右', NULL, '虾 xia 动物名 虾,鱼名。又,虾虫多须而善游好跃。--《篇海类编》 又如虾须镯(金丝编成的镯子);虾杯(以海虾虾头与前两脚壳制成的杯子);虾魁(即虾姑；组词：虾须镯(金丝编成的镯子)；虾杯(以海虾虾头与前两脚壳制成的杯子)；虾魁(即虾姑；指巨虾) 像虾一样弯曲 满语对侍卫的称呼', '小学', '1'),
    ('蚀', 'shí', '9', '虫', '左右', NULL, '蚀 (会意。从虫,从食,从人,食亦声。本义虫等蛀伤物) 同本义 蝕,败创也。--《说文》。字亦作蚀。 精铜不蠹蚀。--梅尧臣《刘原甫古钱劝酒》 凡物侵蠹皆曰蚀；组词：蚀败(蛀蚀败坏)；蚀啮(咬啮损坏)', '小学', '1'),
    ('蚁', 'yǐ', '9', '虫', '左右', NULL, '蚁 (形声。从虫,义声。本作螘”。本义蚂蚁) 膜翅类昆虫名。俗称蚂蚁 羊肉不慕蚁,蚁慕羊肉,羊肉螘也。；组词：蚁附蝇趋(如蚁附膻,如蝇逐臭', '小学', '1'),
    ('蚂', 'mǎ', '9', '虫', '左右', NULL, '蚂蟥 蚂蚁 蚂蚁搬泰山 蚂蚁啃骨头 蚂mà 蚂mā 蚂mǎ 1. 2.', '小学', '1'),
    ('蚊', 'wén', '10', '虫', '左右', NULL, '蚊 蚊子 飞蚊伺暗声如雷。--刘禹锡《聚蚊谣》 虽得一饷乐,有如聚飞蚊。--唐·韩愈《醉赠张秘书》 细若蚊足。--明·魏学洢《核舟记》；组词：蚊力(比喻力量微小)；蚊市(黄昏时,蚊子聚集如市', '小学', '1'),
    ('蚌', 'bàng', '10', '虫', '左右', NULL, '蚌 (形声。从虫,丰声。本义一种软体动物。有的能产珍珠) 同本义 离为蚌。--《易·说卦》 蚌方出曝,而鹬啄其肉,蚌合而其喙。--《战国策·燕策》 巨 蝝函蛛；组词：蚌蛤(蚌与蛤', '小学', '1'),
    ('蚓', 'yǐn', '10', '虫', '左右', NULL, '蚓 蚯蚓 蚓无爪牙之利,筋骨之强。--《荀子·劝学》 又如蚓曲(古代说传说蚯蚓夏夜能发出鸣声,其鸣声叫做蚓曲。也称蚓笛”);蚓操(蚯蚓唯壤土、水而自足,别无所求；组词：蚓曲(古代说传说蚯蚓夏夜能发出鸣声,其鸣声叫做蚓曲', '小学', '1'),
    ('蚕', 'cán', '10', '虫', '上下', NULL, '蚕 (形声。本义一种能吐丝结茧的昆虫) 同本义 遍身罗绮者,不是养蚕人。--宋·张俞《蚕妇》；组词：蚕舍(蚕屋', '小学', '1'),
    ('蚜', 'yá', '10', '虫', '左右', NULL, '蚜 蚜虫ˇ虫名。通称腻虫 蚜yá蚜虫,也叫"蜜虫"(因能分泌一种甜汁故名),俗称"腻虫"。体小,绿色,也有黄色或褐色的。有翅或无翅。种类很多,如麦~虫、菜~虫、棉~虫、桃~虫等', '小学', '1'),
    ('蚣', 'gōng', '10', '虫', '左右', NULL, '见蜈蚣” 蚣 gōng 蚣shōng 1.见"蚣蝑"。', '小学', '1'),
    ('蚤', 'zǎo', '9', '虫', '上下', NULL, '蚤 (形声) 同本义 蚤,啮人跳蚤。--《说文》 鸱鸺夜撮蚤。--《庄子·秋水》 得蚤者莫不糜之齿牙,为害身也。--曹植《贪恶鸟论》；组词：沙蚤；水蚤；蚤蚊(跳蚤和蚊子', '小学', '1'),
    ('蚪', 'dǒu', '10', '虫', '左右', NULL, '蚪--见蝌蚪” 蚪dǒu 1.见"蝌蚪"。 2.通"陡"。参见"蚪峰"。', '小学', '1'),
    ('蚯', 'qiū', '11', '虫', '左右', NULL, NULL, '小学', '1'),
    ('蛀', 'zhù', '11', '虫', '左右', NULL, '蛀 (形声。从虫,主声。本义蛀虫) 同本义 蠹侵嘉树,蛀耗米珠。--明·顾大韶《又后虱赋》；组词：蛀食(谓蛀虫咬吃)；蛀心虫(二化螟、三化螟、大螟、玉米螟等幼虫的统称)；蛀书蠹(蛀蚀书卷的蠹鱼', '小学', '1'),
    ('蛆', 'qū', '11', '虫', '左右', NULL, '蛆〈名〉 蝇类的幼虫。亦指似蝇蛆的虫 的东西) 蛆qū苍蝇的幼虫,白色,线条状,体柔软,有环节,多生长在粪便、垃圾等污物中灭~灭蛹。 蛆jū 1.见"蝍蛆"。', '小学', '1'),
    ('蛇', 'shé', '11', '虫', '左右', NULL, '蛇 (形声。从虫,它声。本写作它”。甲骨文字形,是象形字。本义一种爬行动物) 同本义 蛇,它或从虫。；组词：蛇豕(比喻贪婪残暴的人)；蛇虺(喻指阴狠毒辣的人)；蛇食(像蛇吃东西 蛇yí 1. 蛇(蚮)shé 1.俗称"长虫"', '小学', '1'),
    ('蛉', 'líng', '11', '虫', '左右', NULL, '白蛉子”一种小一种小飞虫,比蚊子小,吸人畜的血,能传染黑热病 蛉líng', '小学', '1'),
    ('蛋', 'dàn', '11', '虫', '上下', NULL, '蛋 禽类或龟、蛇等所产的卵 骂人的话 完蛋 形状像蛋的东西 蛋 dàn 1家禽、鸟、龟、蛇等所产的卵;特指鸡蛋。 2形状象蛋的东西山药~', '小学', '1'),
    ('蛔', 'huí', '12', '虫', '左右', NULL, '蛔 蛔虫 蛕,腹中长虫也。从虫,有声。字亦作蛓,俗作蛔。--《说文》 又如蛔厥(中医病名。症状有腹痛、呕吐、四肢冰凉等。为比较厉害的蛔虫感染症,因为可以发生神经症状；组词：蛔厥(中医病名', '小学', '1'),
    ('蛙', 'wā', '12', '虫', '左右', NULL, '蛙 (形声。从虫,圭声。本义田鸡类动物。青蛙) 同本义 ...苏俗谓之田鸡,扬州谓之水鸡,亦曰吠蛤。；组词：蛙市(夜晚蛙群聚集而鸣,称为蛙市)；蛙吹(蛙鸣)；蛙角(将头发束起,形状宛如青蛙头上左右凸出而对称的部分)；蛙怒(形容青', '小学', '1'),
    ('蛛', 'zhū', '12', '虫', '左右', NULL, '蛛 蜘蛛 蚁穿万孔萃,蛛挂千丝扰。--《次韵王子钦》 又如蛛丝(蜘蛛吐出腹内分泌物而形成的丝);蛛煤(蜘蛛网和烟尘);蛛蝥(蜘蛛的别名);蛛螫(毒害) 蛛丝马迹 大开通同转假之门；组词：蛛丝(蜘蛛吐出腹内分泌物而形成的丝)；蛛煤(蜘蛛网和烟尘)；蛛蝥(蜘蛛的别名)；蛛螫(毒害) 蛛丝马迹 大开通同转假之门', '小学', '1'),
    ('蛤', 'há', '12', '虫', '左右', NULL, '蛤 (形声。从虫,合声。本义蛤蜊) 同本义。产于浅海泥沙中,也可以人工养殖。肉可食 民食果蓏蝝蛤,腥臊恶臭而伤腹胃,民多疾病。；组词：蛤子(小蛤蜊)；蛤蟹(蛤蜊与螃蟹)；蛤灰(以蚌蛤壳烧成的灰)；蛤像(蛤蛎的佛像)；蛤蛎(即蛤蜊) 蛤蚧 蛤蜊 蛤〈名〉', '小学', '1'),
    ('蛮', 'mán', '12', '虫', '上下', NULL, '蛮 (形声。本义中国古代对南方各族的泛称。旧时也用以泛指四方的少数民族) 同本义 蛮,南蛮也。；组词：蛮声哈剌(南方叽哩呱拉的声音)；蛮人(指南方人)；蛮布(蛮人所织的布)；蛮风(指南方蛮地的风；蛮 蛮(衭)mán 1.粗', '小学', '1'),
    ('蛹', 'yǒng', '13', '虫', '左右', NULL, '蛹 动物学名词。指完全变态的昆虫 蛹,茧虫也。从虫,甬声。--《说文》。按,凡虫成茧后,体在中曰蛹,蚕其一也。 亦指蚕蛹 蛹以为母,蛾以为父。--《荀子·蚕赋》；组词：蛹卧(蚕蛹蜷伏茧中', '小学', '1'),
    ('蛾', 'é', '13', '虫', '左右', NULL, '蛾 (形声。从虫,我声。本义蛾子。昆虫。形似蝴蝶,体躯一般粗大,四翅,静止时平放体侧。多在夜间飞行)；组词：蛾罗(即蛾子)；蛾蝶(指飞蛾)；蛾眉(指飞蛾) 蛾眉的简称 扬蛾微眺', '小学', '1'),
    ('蜀', 'shǔ', '13', '虫', '上下', NULL, '蜀 (象形。从虫。上目象蜀头形,中象其身蜎蜎。本义蛾蝶类的幼虫◇作蠋”) 同本义 蜀,葵中蚕也。；组词：蜀江(蜀郡之内的江河)；蜀魄(杜鹃鸟的代称', '小学', '1'),
    ('蜂', 'fēng', '13', '虫', '左右', NULL, '蜂 (形声。从虫,夆声。本义蜂,一种昆虫。有蜜蜂、胡蜂、细腰蜂等。特指蜜蜂”) 同本义 蜂,飞虫螫人者。；组词：蜂虿(蜂与蝎子', '小学', '1'),
    ('蜈', 'wú', '13', '虫', '左右', NULL, NULL, '小学', '1'),
    ('蜒', 'yán', '12', '虫', '左右', NULL, '蜒 (形声。从虫,延声。本义蜒蚰,虫名) 同本义,又名蛞蝓”、鼻涕虫” 的害虫。如蚰蜒(节肢动物,像蜈蚣而略小) 蜒 蜿蜒,龙蛇爬行 南有炎火千里,蝮蛇蜒只。；组词：蜒蜒(龙蛇之类曲折爬行的样子)；蜒蜿(蜿蜒', '小学', '1'),
    ('蜓', 'tíng', '12', '虫', '左右', NULL, '见[蜻蜓] 蜓tíng 1. 2. 蜓diàn 1.见"蝘蜓"。', '小学', '1'),
    ('蜕', 'tuì', '13', '虫', '左右', NULL, '蜕〈动〉 (形声。从虫,兑声。本义蝉、蛇之类脱皮去壳) 蝉、蛇等脱皮。亦谓鸟换羽 蜕,蝉蛇所解皮也。；组词：蜕蝉(蝉脱壳) 道家认为修道者死后留下形骸,魂魄散去成仙,称为尸解,也叫蜕”◇因以蜕为死的讳称 解脱成仙)；蜕衣(谓肉体', '小学', '1'),
    ('蜗', 'wō', '13', '虫', '左右', NULL, '蜗 动物名,蜗牛 的利益);蜗蜒(即蜗牛);蜗踖(即蜗涎);蜗痕(蜗涎) 蜗(蝸)wō 1. 2. 蜗luó 1.见"蜗醢"、"蜗旋"。', '小学', '1'),
    ('蜘', 'zhī', '14', '虫', '左右', NULL, NULL, '小学', '1'),
    ('蜜', 'mì', '14', '虫', '上下', NULL, '蜜 (形声。从虫,宓声。本义蜂蜜,蜜蜂采取花液酿成的甜汁) 同本义 蜜为蜂液,食蜜少多,则令人毒。--汉·王充《论衡》；组词：蜜勺(蜜酒)；蜜供(涂有蜜汁的糕点)；蜜酒(以蜂蜜酿造而成的酒)；蜜浆(以蜂蜜制作的饮料)；蜜饵(在米面中加蜜调制而成的', '小学', '1'),
    ('蜡', 'là', '14', '虫', '左右', NULL, '蜡 (形声。从虫,声。本义动物、植物或矿物所产生的某些油质。如蜂蜡) 动物、矿物或植物所产生的油质,具有可塑性,能燃能熔,不溶于水,是一羟基醇或固醇的脂肪酸酯 蜡烛有心还惜别；组词：蜡圆(蜡丸)；蜡弹(蜡丸,用蜡封裹的密件)；蜡查(蜡埚,蜡滓', '小学', '1'),
    ('蜻', 'qīng', '14', '虫', '左右', NULL, '蜻〈名〉 蜻蜓 海上之人有好蜻者,每居海上,从蜻游,蜻之至者有百数而不止,前后左右尽蜻也。；组词：蜻蜓撼石柱(比喻力量小却想动摇大东西,不自量力)；蜻蜓吃尾巴(比喻自己吃自己) 蜻qīng 蜻jīng 1.见"蜻蛚"、', '小学', '1'),
    ('蝇', 'yíng', '14', '虫', '左右', NULL, '蝇 多指苍蝇。动物名。属昆虫类中的双翅类 上无枝上蜩,下无盘中蝇。--唐·韩愈《秋怀诗》；组词：蝇头小楷(非常小的正楷毛笔字)；蝇头细批(用小字密密批注)；蝇附狗偷(比喻依附低俗下作的行径)；蝇营(如蝇到处营钻', '小学', '1'),
    ('蝉', 'chán', '14', '虫', '左右', NULL, '蝉 (形声。从虫,单声。本义一种昆虫。也称知了”) 同本义。节肢动物门,昆虫纲,同翅目,蝉科,蝉属 蝉,以旁鸣者。；组词：寒蝉(秋天天冷时的蝉) 古代一种极薄的丝织品', '小学', '1'),
    ('蝌', 'kē', '15', '虫', '左右', NULL, NULL, '小学', '1'),
    ('蝎', 'xiē', '15', '虫', '左右', NULL, '蝎 毒虫名。也称钳蝎”。节肢动物门,蜘蛛纲,蜘蛛亚纲,蝎目 蝎,蝤蛴也。从虫,曷声。--《说文》 虽蝎焉避之。--《国语·晋语》 虽蝎谮之。--《国语·鲁语》；组词：蝎梢(蝎子的尾巴)；蝎蝎螫螫(比喻在小事情上过分关心或怜惜)；蝎子(钳蝎；钳蝎之子)；蝎唇(状如蝎子嘴的酒器)；蝎子妈(', '小学', '1'),
    ('蝗', 'huáng', '15', '虫', '左右', NULL, '蝗 蝗虫 蝗,螽也。从虫,皇声。--说文》 蝗螟农夫得而杀之。--《吕氏春秋》 又如蝗螟(蝗与螟。庄稼的两种害虫);蝗螽(即蝗虫) 蝗灾。蝗虫造成的灾荒 蝗huáng蝗虫；组词：蝗螟(蝗与螟', '小学', '1'),
    ('蝙', 'biān', '15', '虫', '左右', NULL, '蝙蝠 蝙蝠衫 蝙 biān 【蝙蝠】具有飞翔能力的哺乳动物。头部和躯干像老鼠,四肢和尾部之间有皮质的膜,夜间在空中飞翔,视力很弱,靠本身发出的超声定位来引导飞行。', '小学', '1'),
    ('蝠', 'fú', '15', '虫', '左右', NULL, '蝠〈名〉 蝙蝠 蝙蝠,服翼也。从虫,畐声。--《说文》 蝙蝠伏匿,故夜食。--《孝经·援神契》。按,形绝类鼠,肉翅与足相连,夜捉蚊蚋食之,俗言老鼠所化也。 燕避戊巳,蝠伏庚申', '小学', '1'),
    ('蝴', 'hú', '15', '虫', '左右', NULL, '蝴 (形声。从虫,胡声。本义蝴蝶虫名。种类很多) 蝴蝶 蝴蝶结 蝴蝶梦 人事等蜉蝣。朝暮营营不自由,打破世界蝴蝶梦价格休', '小学', '1'),
    ('蝶', 'dié', '15', '虫', '左右', NULL, '蝶 (形声。从虫,葉声←蝶)同本义 身影);蝶戏(谓蝴蝶飞舞嬉戏);蝶意莺情(比喻爱恋春色的情意);蝶舞(比喻荡子之流嫖妓) 蝶 dié蝴蝶。 【蝶泳】游泳姿势之一。俯卧水面', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('螃', 'páng', '16', '虫', '左右', NULL, '螃蟹 时值香橙螃蟹月,景当新酒菊花天。--明·徐元《八义记》 螃páng', '小学', '1'),
    ('融', 'róng', '16', '虫', '左右', NULL, '螎 (形声。从鬲,虫省声。鬲,古代一种烹饪器,与鼎相似。本义炊气上升) 同本义 融融者皆趣热之士,其得炉冶之门者,惟夹炭之子。；组词：融流(融化流动)；融陶(熔化陶冶)；融液(融化成液体)；融释(消失；化解)；融蚀(消磨；侵蚀)；融炼(熔化锤炼) 融合', '小学', '1'),
    ('螟', 'míng', '16', '虫', '左右', NULL, '螟 螟虫,螟蛾的幼虫 稻的害虫);螟蠹(两种害虫名) 螟蛾 螟蛉 螟蛉作食物。古人误认为蜾赢不产子,喂养螟蛉为子,因此用螟蛉”比喻义子 周侗年迈,巴不得将平生一十八般武艺', '小学', '1'),
    ('螺', 'luó', '17', '虫', '左右', NULL, '螺 (又作蠃。形声。从虫,累声。本义凡软体动物腹足类,被有旋线的硬壳都叫螺,种类繁多) 同本义 蠃,蜾蠃也。；组词：螺填(即螺钿)；螺壳(海螺的外壳)；螺壳钱(螺壳所制的货币)；螺蚌(螺与蚌', '小学', '1'),
    ('蟀', 'shuài', '17', '虫', '左右', NULL, '蟀 蟋蟀 秋蟀载吟,竞鸣机杼。--《徐州刺史侯安都德政碑》 蟀shuài 1."蟋蟀"的省称。', '小学', '1'),
    ('蟆', 'má', '16', '虫', '左右', NULL, '蟆 旁一蟆。--《聊斋志异·促织》 又如蟆入草间;蟆更(虾蟆更的简称);蟆蝈(方言。即青蛙);蟆衣草(车前草的别名) 蟆ma 蟆má 1.虾蟆。 蟆mò 1.小蚊。', '小学', '1'),
    ('蟋', 'xī', '17', '虫', '左右', NULL, '蟋 蟋蟀的简称 蟋蟀 蟋xī', '小学', '1'),
    ('蟹', 'xiè', '19', '虫', '上下', NULL, '蟹 螃蟹 蠏,有二敖、八足、旁行、非蛇鲹之穴无所庇。--《说文》 离为蟹,外刚而内柔也。--《易·说卦》 蟹六跪而二螯。--《荀子·劝学》 蟹白栗黄；组词：蟹眼(喻指水初沸时冒起的小水泡)；蟹爪(指一种形如蟹爪的画笔)；蟹火(渔人夜晚用来捕蟹的火)；蟹厄( 蟹行田中,为害禾稼', '小学', '1'),
    ('蠕', 'rú', '20', '虫', '左右', NULL, '蠕 虫类爬行的样子;微动貌 蠕rú虫类慢慢爬行的样子~动。蠕虫如绦虫、蛔虫、蚯蚓等。', '小学', '1'),
    ('蠢', 'chǔn', '21', '虫', '上下', NULL, '蠢 (形声。本义昆虫慢慢地爬行) 同本义 蠢,虫动也。--《说文》 蠢尔蛮荆。--《诗·小雅·采芑》 今王室实蠢蠢焉。--《左传·昭公二十四年》 万物蠢生。--左思《吴都赋》；组词：蠢动；蠢蠢(蠕动的样子) 引申为骚动,动乱 蠢 愚蠢；愚昧 时人愚蠢,不知相绳责也', '小学', '1'),
    ('血', 'xuè', '6', '血', '上下', NULL, '血 xie 粥样);血渌渌(鲜血淋漓);血心(忠心;热忱);血的教训;流了一点血,不要紧 血 xue (指事。小篆字形,从皿,一”象血形。表示器皿中盛的是血。本义牲血', '小学', '1'),
    ('衅', 'xìn', '11', '血', '左右', NULL, '衅 (会意。从爨省,与酒有关,表祭祀。分,表示分布∠起来表杀牲以祭。本义古代血祭新制的器物。杀牲,用其血涂于器物缝隙中来祭祀)', '小学', '1'),
    ('行', 'xíng', '6', '行', '左右', NULL, '行〈名〉hang (象形。本义道路) 同本义 行,道也。--《说文》 行有死人。--《诗·小雅·小弁》 遵彼微行。--《诗·豳风·七月》；组词：行苇(路旁芦苇)；行阡(道路)；行神(路神)；行程(路程)；行街(大路) 直排为行,横排为列 左右陈行,戒我师旅', '小学', '1'),
    ('衍', 'yǎn', '9', '行', NULL, NULL, '衍 (会意。从水,从行。本义水流入海) 水循河道流汇于海 衍,水朝宗于海貌也。--《说文》 至今衍于四海。--《书大传》。注犹溢也。” 水直衍。--《太玄·法》。注达也。” 溢出；组词：衍溢(水满溢)；衍涝(谓雨水满溢) 散开 衍溢漂疾', '小学', '1'),
    ('衔', 'xián', '11', '行', NULL, NULL, '衔 口含 蟾蜍衔之。--《后汉书·张衡传》 又如燕子衔泥;衔环相报(衔环);衔刀(口中叼刀);衔土(口含泥土);衔口垫背(古代一种殓葬习俗给死人口含珠、玉或米；组词：燕子衔泥；衔环相报(衔环)；衔刀(口中叼刀)；衔土(口含泥土)；衔口垫背(古代一种殓葬习俗给死人口含珠、玉或米', '小学', '1'),
    ('街', 'jiē', '12', '行', NULL, NULL, '街 (形声。从行,圭声。街”,小篆象纵横相交的十字路。本义四路相通的大道) 城市的大道,两边有房屋的、比较宽阔的道路,通常指开设商店的区段 街,四通道也。；组词：大街小巷；街市(街巷；市井)；街鼓(街上报更的鼓)；街基(街直', '小学', '1'),
    ('衙', 'yá', '13', '行', NULL, NULL, '衙 (形声。从行,吾声。本义列队行进的样子) 旧时官署之称 诸州县长官在公衙亦准此。--张昭远《旧唐书·仪卫志》 衙,衙府也。；组词：衙头(金人军队的统帅部)；衙职(官衙中的职役)；衙庭(官署的庭堂)；衙堂(官署的大堂)；衙里(衙署内)；衙子(在衙门中当', '小学', '1'),
    ('衡', 'héng', '16', '行', NULL, NULL, '衡〈名〉 (形声。从角,从大,行声。本义绑在牛角上的横木) 同本义。一说穿于牛鼻的横木 秋而载尝,夏而糕。；组词：衡辀(车辕与辕前横木)；衡轸(辕前横木与车后横木)；衡盖(车辕前端的横 衡héng 1.称东西轻重的器具,如秤,天平等', '小学', '1'),
    ('衣', 'yī', '6', '衣', NULL, NULL, '衣 (象形。甲骨文字形。上面象领口,两旁象袖筒,底下象两襟左右相覆,为上衣形。衣”是汉字的一个部首。从衣”的字与衣服有关。本义上衣)；组词：衣祛(衣袖)；衣袖(衣服的袖子)；衣裤(上衣与裤子) 服装 衣yī 1.上衣', '小学', '1'),
    ('补', 'bǔ', '7', '衤', '左右', NULL, '补 (形声。从衣,甫声。本义补衣服) 同本义 补,完衣也。--《说文》 田赞衣补衣。--《吕氏春秋·顺说》 补褐防寒岁。--唐·白居易《村居卧病》；组词：补衣；补袜；补衬(打补丁,衬里子)；补衣(打过补丁的衣服) 修补；整修破旧的东西 牵萝补茅屋', '小学', '1'),
    ('表', 'biǎo', '8', '衣', '上下', NULL, '表 (会意。从毛,从衣,毛”又兼作声符。小篆字形,衣字中间加个毛字。古人穿皮衣,毛朝外面,所以表”从毛”。本义外衣)；组词：表裘(外衣)；表礼(作为礼物的衣料)；表里(衣服的面子与里子；里外；也指作为礼物的衣料) 外面(与里”相对) 表 biǎ', '小学', '1'),
    ('衩', 'chǎ', '8', '衤', '左右', NULL, '衩--裤衩”短裤 衩chǎ 衩chà衣裙旁边开口的部位~口。', '小学', '1'),
    ('衫', 'shān', '8', '衤', '左右', NULL, '衫〈名〉 古代指无袖头的开衩上衣 朝成绣夹裙,晚成单罗衫。--《玉台新咏·古诗为焦仲卿妻作》；组词：衫子(指古代妇女穿的一种袖子宽大的上衣；上衣的通称)；衫帽(凉衫便帽', '小学', '1'),
    ('衬', 'chèn', '8', '衤', '左右', NULL, '衬 (形声。从衣,觝声。本义外衣内的单衫) 同本义。又称衬衫 附在衣服鞋帽里的布 垫,衬垫 衬 施舍,布施 衬托 相帮 衬 chèn 1在里面托一层~一点纸。 2衬在里面的~衣', '小学', '1'),
    ('衰', 'shuāi', '10', '衣', NULL, NULL, '衰 cui 古代用粗麻布制成的毛边丧服 共丧衰亦如之。--《周礼·天官·内司服》 无衰麻之服。--《荀子·礼论》 子墨衰緻,梁弘御戎,莱驹为右。--《左传·僖公三十三年》；组词：衰衣(衰服', '小学', '1'),
    ('衷', 'zhōng', '10', '衣', NULL, NULL, '衷 (形声。从衣。中声。本义贴身的内衣) 同本义 衷,里亵衣。--《说文》。段玉裁注亵衣有在外者,衷则在内者也。”；组词：衷衣(里衣,内衣)；衷服(贴身内衣) 通中”', '小学', '1'),
    ('袁', 'yuán', '10', '衣', NULL, NULL, '袁〈形〉 长衣的样子 袁,长衣貌。从衣,叀省声。--《说文》 袁 〈名〉 姓。如袁纥(我国古代部族名) 袁大头 的银元,也叫大头” 袁yuán姓。', '小学', '1'),
    ('袄', 'ǎo', '9', '衤', '左右', NULL, '袄 (形声。从衣,夭声。本义有衬里的上衣) 皮衣之类的御寒衣服 身上穿着银红撇花半旧大袄。；组词：皮袄；袄子(棉袄的俗称) 泛指上衣', '小学', '1'),
    ('袋', 'dài', '11', '衣', '上下', NULL, '袋 (形声。从衣,代声。本义有口的盛器,囊属。也指衣袋) 同本义 羊骨杂他骨,作五袋盛之。；组词：网袋；塑料袋；旅行袋；工具袋；子弹袋；烟叶袋；水泥袋 袋 计量用口袋装的东西 袋 dài 1口袋；兜子衣~、面~', '小学', '1'),
    ('袍', 'páo', '10', '衤', '左右', NULL, '袍〈名〉 有夹层、中着棉絮的长衣 衣敝縵袍。--《论语》。按,衣有箸者,今之绵衣,或曰箸以乱麻曰袍。 纩为茧,縵为袍。--《礼记·玉藻》；组词：袍子 中式长衣的通称', '小学', '1'),
    ('袒', 'tǎn', '10', '衤', '左右', NULL, '袒 (形声。从衣,旦声。本义绽开) 同本义 袒,衣缝解也。--《说文》 脱去上衣,露出身体的一部分 乃右肉袒于庙门之东。--《仪礼·遂觏礼》 劳毋袒。--《礼记·曲礼》 袒右；组词：袒臂(袒露胳膊', '小学', '1'),
    ('袖', 'xiù', '10', '衤', '左右', NULL, '袖 (古字作褎。形声。从衣,由声。本义衣袖) 同本义 褎,袂也。--《说文》。字亦作褎、作袖 攘袖见素手。--《文选·曹子建·乐府》 长袖善舞。--《韩非子》；组词：袖搭(衣袖多由两片布料缝合而成,靠近袖口的一截称为袖搭)；袖佉(袖子的边口) 袖口 袖,衣袂端也', '小学', '1'),
    ('袜', 'wà', '10', '衤', '左右', NULL, '袜 针织或编织的足套,袜子 袜 穿袜子 客初至时,不冠不袜。--清·魏禧《大铁椎传》 袜(襪、韤)wà穿在脚上的东西,它是用布、纱线或锦纶等制成布~子。棉~子。~底。锦纶丝~', '小学', '1'),
    ('被', 'bèi', '10', '衤', '左右', NULL, '被 (形声。从衣,皮声。本义睡眠时用以覆体的夹被;被子) 同本义 被,寝衣,长一身有半。--《说文》 翡翠珠被。--《楚辞·招魂》 谣俗被服饮食奉生送死之具也；组词：棉被；夹被；毛巾被；被窝(覆以棉被,容人安睡的地方)；被卧(睡眠用的被子) 表面 被 被覆；遮盖 被袗衣', '小学', '1'),
    ('袭', 'xí', '11', '衣', '上下', NULL, '袭 (形声。从衣,从两龙”省声。本义死者穿的衣服,衣襟在左边) 同本义 袭,左衽袍也。--《说文》。按,凡敛死者,左衽,不纽。 陈袭事于房中,西领南上,不緋。--《仪礼·士丧礼》；组词：袭衣(尸衣；也指古代行礼时穿在裼衣外面的上衣)；袭玩(衣着器用) 姓 袭 衣一套为一袭 赐衣被一袭', '小学', '1'),
    ('袱', 'fú', '11', '衤', '左右', NULL, '袱〈名〉 妇女的包头巾 首取帛为袱,体用衾自裹。--元·方回文 包袱 袱(襩) fú包裹,用于覆盖的布单把~拿走。包~布。塑料布包~', '小学', '1'),
    ('裁', 'cái', '12', '衣', '半包围', NULL, '裁 (形声。从衣)声。本义裁制,剪裁) 同本义 裁,制衣也。--《说文》 夷衾质杀之,裁犹冒之。--《礼记·丧大记》。注犹制也。” 十四学裁衣；组词：套裁；剪裁；对裁；裁衣(裁剪衣料制作衣服) 裁定；判断 大王裁其罪', '小学', '1'),
    ('裂', 'liè', '12', '衣', '上下', NULL, '裂〈动〉 裂巴 裂 〈名〉 (会意。从衣,从列,列亦声。本义裁剪后的丝绸残余) 同本义 裂,缯余也。；组词：裂繻(汉制,裂缯帛为符信,凭以出入关隘) 裂缝 两相邻部分连接处形成的线或沟；常指裂开而成的线 裁剪；扯裂 裂liě〈方', '小学', '1'),
    ('装', 'zhuāng', '12', '衣', '上下', NULL, '装 (形声。从衣,壮声。本义行装) 同本义 装,裹也。--《说文》 橐中装。--《史记·郦生陆贾传》 简元辰而俶装。--张衡《思玄赋》。注束也。” 顾形影,自整装；组词：装囊(行囊,远行者携带的袋子)；装束(束装,整理行装) 服装 富者赂数十百金,贫亦罄衣装', '小学', '1'),
    ('裆', 'dāng', '11', '衤', '左右', NULL, '裆 (形声。从衣,当声。本义两裤腿相连的地方) 同本义 两条裤腿缝相接触的接口部分 裆,穷裦也。今以裦有当而旁开者为裆。；组词：横裆；直裆；裤裆 又指两条腿的中间,由于两条腿的分离而形成的一个形似锐角的空间', '小学', '1'),
    ('裕', 'yù', '12', '衤', '左右', NULL, '裕 (形声,从衣,谷声。衣物丰饶。本义富饶。财物多。也指使富饶) 同本义 裕,衣物饶也。--《说文》 有孚裕无咎。--《易·晋》 天地裕于万物。--《法言·孝至》 包众容物谓之裕；组词：泽光前(造阁辈,光耀祖先)；裕民(使民众富裕)；裕饶(富饶)；裕民足国(裕国足民', '小学', '1'),
    ('裙', 'qún', '12', '衤', '左右', NULL, '裙 (形声。从衣,君声。《说文》从巾”。本义下裳,古代男女都有下裳) 古指下裳,今专指裙子 裙,下裳也。；组词：连衣裙；连衫裙；围裙；短裙；超短裙；裙布钗荆(形容妇女服饰俭朴)；裙袄(衣裤)；裙门(裙子的前幅)；裙刀(压衣服用 裙(', '小学', '1'),
    ('裤', 'kù', '12', '衤', '左右', NULL, '裤 (形声。从衣,库声。本义裤子。古指套裤,今为成人满裆裤及小儿开裆裤的通称) 同本义 底下绛裤红鞋,鲜艳夺目。--《红楼梦》 裤(裦)kù下装长~子。内~。丝棉~。牛仔~。', '小学', '1'),
    ('裳', 'shang', '14', '衣', '上下', NULL, '裳 (形声。从衣,尚声。本义下衣) 古人穿的遮蔽下体的衣裙,男女都穿,是裙的一种,不是裤子 裳下饰也。；组词：裳衣(裳与衣', '小学', '1'),
    ('裸', 'luǒ', '13', '衤', '左右', NULL, '裸 (形声。从衣,果声。本义赤身露体) 同本义 舏,袒也。--《广雅》 赵简子梦童子裸而转以歌。--《左传·昭公三十一年》 其动物宜舏物。--《周礼·大司徒》 平怒；组词：裸衣(脱衣露体)；裸行(赤身露体行走)；裸戏(裸身作戏)；裸形(裸体)；裸国(古国名', '小学', '1'),
    ('裹', 'guǒ', '14', '衣', NULL, NULL, '裹 (形声。从衣,果声。本义包,缠) 同本义 裹,缠也。--《说文》 朱三百,裹。--《穆天子传》 富之以国裹。--《管子·君臣》。注谓财货所苞裹而藏也。” 无不裹也；组词：裹束(包裹束缚)；裹足(包裹足部', '小学', '1'),
    ('褂', 'guà', '13', '衤', '左右', NULL, '褂〈名〉 中式的单上衣 罩在外面的长衣。如大褂(身长过膝的中式单衣);小褂(中式的贴身穿的单上衣);长褂;短褂 古时军装的一种,有罩甲的短袖戎衣 清代礼服外服的名称', '小学', '1'),
    ('褐', 'hè', '14', '衤', '左右', NULL, '褐〈名〉 (形声。从衣,曷声。本义用粗麻织成的袜子) 同本义 褐,编枲袜。--《说文》。段玉裁注取未绩之麻,编之为足衣,如今草韕之类。” 指粗布或粗布衣;最早用葛、兽毛；组词：褐巾(用粗布缝成的头巾)；褐衣(粗布衣', '小学', '1'),
    ('褒', 'bāo', '15', '衣', NULL, NULL, '褒 (形声。从衣,保声。本义衣襟宽大) 同本义 褒,衣博裙。--《说文》 岂必褒衣博带,句襟委章甫哉?--《淮南子·泛论》；组词：褒袖(宽大的袖子)；褒衣博带(大衣服,宽带子', '小学', '1'),
    ('褥', 'rù', '15', '衤', '左右', NULL, '褥 (形声。从衣,辱声。本义坐卧的垫具) 同本义 褥,荐也。--《三苍》 寝必重褥。--明·刘基《苦斋记》；组词：褥甸(小的褥子,供坐卧)；坐褥；褥垫；褥席(坐卧用的垫具或席具)；褥子；褥位(铺有锦褥的座位)；褥草(一种主要的垫料', '小学', '1'),
    ('褪', 'tuì', '14', '衤', '左右', NULL, '褪〈动〉tui 减色;消退 退,后退 褪色 这幅油画珍藏40年没褪色 褪〈动〉tun (形声。从衣,退声。这个后起字,解作卸衣、花谢、色减、退却。本义卸衣)；组词：褪落(卸脱) 消除 春事阑珊,山村未褪寒', '小学', '1'),
    ('襟', 'jīn', '18', '衤', '左右', NULL, '襟〈名〉 (形声。从衣,禁声。本义古代指衣的交领) 同本义◇指衣的前幅。 泣下沾襟。--宋·欧阳修《新五代史·伶官传》；组词：襟袂(襟袖', '小学', '1'),
    ('西', 'xī', '6', '西', NULL, NULL, '西 (象形。据小篆字形,上面是鸟的省写,下象鸟巢形。西”是栖”的本字。本义鸟入巢息止) 同本义 西,鸟在巢上,象形。；组词：西迟(游息,流连', '小学', '1'),
    ('要', 'yào', '9', '覀', '上下', NULL, '要 (象形。小篆字形。中间象人形,两旁为两手形。表示两手叉腰。本义人腰) 腰”的古字 昔者,楚灵王好细要。；组词：要膂(腰和脊骨', '小学', '1'),
    ('覆', 'fù', '18', '覀', '上下', NULL, '覆〈动〉 (形声。覆盖,復声。本义翻转,倾覆) 同本义 见若覆夏屋者矣。--《礼记·檀弓》。注谓茨瓦也。” 载舟覆舟,所宜深慎。--唐·魏征《谏太宗十思疏》 覆舟斟寻；组词：覆盆(翻扣的盆子', '小学', '1'),
    ('见', 'jiàn', '4', '见', '半包围', NULL, '见 (会意。甲骨文字形,上面是目”,下面是人”。在人的头上加只眼睛,就是为了突出眼睛的作用。本义看见,看到)', '小学', '1'),
    ('观', 'guān', '6', '见', '左右', NULL, '观 (形声。从见,雚声。本义仔细看) 同本义 观,谛视也。--《说文》 观,视也。--《广雅·释诂一》 观者如市。--《庄子·人间世》 观于大海；组词：观觑( 观(觀)guān 1.看~看', '小学', '1'),
    ('规', 'guī', '8', '见', '左右', NULL, '规 (会意。金文字形,从聿从周,当系以规画之意。本义画圆的器具,今指圆规) 同本义 规,有法度也。从矢,从见,会意。；组词：规绳(规矩绳墨)；规旋(如圆规般旋转)；规轮(圆规和车轮)；规轴(圆规之轴', '小学', '1'),
    ('觅', 'mì', '8', '见', '上下', NULL, '觅 (会意。从爪,从见。表示用手和眼去寻找。本义寻找,到处寻找) 同本义 是犹欲登山者,涉舟航而觅路。；组词：觅汉(雇工)；觅举(士人到处请托人,求人荐举)；觅句(指诗人构思、寻觅诗句)；觅食(寻找食物)；觅死(求死,寻死)；觅取', '小学', '1'),
    ('视', 'shì', '8', '见', '左右', NULL, '视 (会意兼形声。从见示,示亦声。见,看见。示,表现。本义看) 同本义 视,瞻也。--《说文》 天视自我民视,天听自我民听。--《书·泰誓中》 目不能徧视,手不能徧操；组词：视探(看望,探望)；视(眎)shì 1.看~力', '小学', '1'),
    ('览', 'lǎn', '9', '见', NULL, NULL, '览 (会意。从见,从监。监”亦兼表字音。监”的本义是借水照形,这里表示看。本义观看) 同本义 览,观也。；组词：览观(阅览)；览读(阅读)；览阅(阅览)；览核(查阅)；览究(阅读研究) 观赏 会当凌绝顶,一览众山小', '小学', '1'),
    ('觉', 'jué', '9', '见', '上中下', NULL, '觉〈动〉 jiao 睡醒 觉,悟也。从见,寃省声。--《说文》 上欲起贤,未觉。--《汉书·董卓传》 觉而之渐台。--《汉书·邓通传》；组词：觉卧(觉醒时和寝卧时)；觉寤(睡醒)；觉寝(自睡中觉醒) 通挍”、校”', '小学', '1'),
    ('角', 'jiǎo', '7', '角', '上下', NULL, '角〈名〉 (象形。甲骨文字形,象兽角形。本义动物的角) 同本义 角,兽角也。--《说文》 麟之角。--《诗·周南·麟之趾》 北方之美者,有幽都之筋角焉。╠《尔雅·释地》 旃裘筋角；组词：角灯(用透明角质物做罩的灯)；角带(缀有角质饰物的腰带)；角弓(用兽角作装饰的硬弓)；角枕(以兽角来装饰的枕头)；角马(', '小学', '1'),
    ('解', 'jiě', '13', '角', '左右', NULL, '解 (会意。从刀,从牛,从角。表示用刀把牛角剖开。本义分解牛,后泛指剖开) 同本义 解,判也,从刀,判牛角。；组词：解腕(断腕)；解手刀(随身携带的小佩刀', '小学', '1'),
    ('触', 'chù', '13', '角', '左右', NULL, '触〈动〉 (形声。从角,蜀声。本义以角撞物) 用角抵人或物 触,牴也。--《说文》 兽穷则触。--《新序杂事》 触槐而死。--《左传》 羝羊触藩。--《易·大壮》；组词：触藩(以角触撞藩篱)；触藩羝羊(公羊抵触藩篱,角被挂,无法摆脱很焦急) 撞,碰 手之所触', '小学', '1'),
    ('言', 'yán', '7', '言', '上下', NULL, '言 (指事。甲骨文字形,下面是舌”字,下面一横表示言从舌出。言”是张口伸舌讲话的象形。从言”的字与说话或道德有关。本义说,说话)', '小学', '1'),
    ('誉', 'yù', '13', '言', '上下', NULL, '誉 (形声。从言,舆声。本义称赞,赞美) 同本义 誉,偁也。--《说文》 誉名美也。--《墨子经》 状古述今曰誉。--《周书·谥法》 君子不以口誉人。--《礼记·表记》 佞誉诬谀；组词：誉人(称赞人)；誉谀(歌颂阿谀)；誉叹(赞叹) 通举”', '小学', '1'),
    ('誊', 'téng', '13', '言', '上下', NULL, '誊〈动〉 照原稿抄写清楚 謄,迻书也。从言,朕声。--《说文》。按,謄录字,元代始用之。 自剪短笺誊断稿,不嫌墨浅字倾欹。--陆游文；组词：誊一遍；誊本(根据原本抄写的本子) 誊(謄)téng抄写,转录~写', '小学', '1'),
    ('誓', 'shì', '14', '言', '上下', NULL, '誓 (形声。从言,折声。本义发誓;立誓) 同本义 誓,以言约束也。--《说文》。段注凡自表不食言之辞皆曰誓,亦约束之意也。” 约信曰誓。--《礼记·曲礼》 予誓,告汝誓命', '小学', '1'),
    ('警', 'jǐng', '19', '言', '上下', NULL, '警 (会意。从言,从敬,敬亦声。本义戒敕) 同本义 警,戒也。--《说文》 正岁,则以法警戒群吏。--《周礼·宰夫》 所以警众也。--《礼记·文王世子》 乃一篇之警策；组词：警告；警励(告诫策励)；警迹人(元代被列入盗贼户籍的人)；警鼓(报警之鼓)；警动(使人警觉悚动)；警新(警策动人,语意新', '小学', '1'),
    ('譬', 'pì', '20', '言', '上下', NULL, '譬〈名〉 (形声。从言,辟声。本义譬如,比喻) 同本义 譬,喻也。--《说文》 譬彼舟流。--《诗·小雅·小弁》 能近取譬。--《论语》 臣窃为公譬可也。--《战国策·齐策》；组词：譬如(举例以比喻)；譬犹(譬诸', '小学', '1'),
    ('计', 'jì', '4', '讠', '左右', NULL, '计 (会意。从言,从十。言”有数的意思;十”是整数,表示事物成一个数目。数数字,所以有计算的意思。本义算账;总计;计算)', '小学', '1'),
    ('订', 'dìng', '4', '讠', '左右', NULL, '订 (形声。从言,丁声。本义评议) 同本义 订,平议也。--《说文》。按,字亦作评。 订太平文王之道。--《诗·天作》笺 两论相订,是非乃见。--《论衡·案书》；组词：订铨(评议衡量)；《订鬼篇》 改正,修正 下足以订史氏之失者', '小学', '1'),
    ('认', 'rèn', '4', '讠', '左右', NULL, '认 (形声。从言,忍声。本义认识,辨明) 同本义 你去营中寻林教头来,认他一认。--《水浒传》 过了数日,待没了认色,却将去本府告赏。--《古今小说》；组词：认出他失散多年的兄弟；认记(辨认的记号)；认色(辨认的标记)；认旗(军中作为标志、信号的旗帜)；认领(辨认并领取)；认证', '小学', '1'),
    ('讥', 'jī', '4', '讠', '左右', NULL, '讥 (形声。从言,幾声。本义旁敲侧击地批评) 同本义 讥,诽也。--《说文》 此何以书讥。--《公羊传·隐公二年》。注犹谴也。” 诛讥罢只。--《楚辞·大招》。注非也', '小学', '1'),
    ('讨', 'tǎo', '5', '讠', '左右', NULL, '讨〈动〉 (会意。从言,从寸。言,言论。寸,法度。用言论和法度进行处治。本义声讨) 同本义 讨,治也。；组词：征讨(出兵讨伐)；讨掩(讨伐掩捕', '小学', '1'),
    ('让', 'ràng', '5', '讠', '左右', NULL, '让 (形声。从言,襄声。本义责备) 同本义 让,相责让也。--《说文》 诘责以辞谓之让。--《小尔雅》 让,责也。--《广雅》 且让之。--《左传·昭公二十五年》 让不贡；组词：让书(有责备言语的书信)；让勖(既责备又勉励)；让诮(责让讥诮) 退让；谦让 让者,礼之主也', '小学', '1'),
    ('训', 'xùn', '5', '讠', '左右', NULL, '训 (形声。从言,川声。本义教育,教导) 同本义 训,说教也。--《说文》 大训。--《书·顾命》 告之训典。--《左传·文公六年》 是为明训。--《国语·晋语》。注教也；组词：训蒙(在私塾教授小学生)；训蒙教授(教幼童的私塾先生)；训人(负责教育的官员或师长)；训章(训示规范) 解说,注释', '小学', '1'),
    ('议', 'yì', '5', '讠', '左右', NULL, '议 (形声。从言,义声。本义商议,讨论) 同本义 议,语也。--《说文》 议,谋也。--《广雅》。按,谓论事之宜。 唯酒食是议。--《诗·小雅·斯干》 法而不议；组词：议计(商议合计)；议妥(商量妥当)；议婚(商谈联姻之事) 评议是非 议论证据古今', '小学', '1'),
    ('讯', 'xùn', '5', '讠', '左右', NULL, '讯 同本义 讯,问也。--《说文》。按,字亦作询『宣帝名询。 讯之占梦。--《诗·小雅·正月》。传问也。” 多其讯。--《礼记·学记》。注或为訾,按,訾犹咨也。” 执讯而与之书', '小学', '1'),
    ('记', 'jì', '5', '讠', '左右', NULL, '记 (形声。从言,己声。本义记住) 同本义 记,疏也。--《说文》 记,识也。--《广雅》 记有成。--《礼记·内则》 记间之学。--《礼记·学记》 凡所经履,莫不暗记；组词：记混了；记错了；切记；牢记；铭记；记不清；记省(回忆,记忆)；记心(记在心上,常用于叮嘱)；记念(挂心；惦念)；记忆(记', '小学', '1'),
    ('讲', 'jiǎng', '6', '讠', '左右', NULL, '讲 (形声。从言,冓声。本义和解) 同本义 讲,和解也。--《说文》 而秦未与魏讲也。--《战国策·西周策》 与魏讲罢兵。--《史记·樗里子甘茂传》 以中情出,小曰閒,大曰讲；组词：讲息(和解息争)；讲贡(讲和纳贡)；讲款(讲和,议款)；讲盟(订盟媾和) 讲习(共同讨论研习学问) 道士讲火经', '小学', '1'),
    ('讳', 'huì', '6', '讠', '左右', NULL, '讳 (形声。从言,韦声。本义避忌。有顾忌而躲开某些事或不说某些话) 同本义 讳,説也。--《说文》 讳,避也。--《广雅·释诂三》 卒哭乃讳。--《礼记·曲礼》 舍故而讳新；组词：直言不讳；讳名(对尊长避免说写其名,表示尊敬的心意)；讳恶(先王的名讳与国家的凶恶)；讳亡(忌言亡国) 隐；隐蔽 恐犯忌', '小学', '1'),
    ('讶', 'yà', '6', '讠', '左右', NULL, '讶 (形声。从言,牙声。本义迎接) 同本义 讶,相迎也。从言,牙声。周礼曰,诸侯有卿讶发。按,乍接必以言,故从言,俗字作迓。周官有讶士,有掌讶。；组词：讶客(迎接宾客)；讶宾(迎宾) 诧异,感到意外 若夫道德,则不然,无讶无訾', '小学', '1'),
    ('许', 'xǔ', '6', '讠', '左右', NULL, '许 (形声。从言,午声。本义应允,许可) 同本义 许,听也。--《说文》。按,听从其言也。 王子许。--《吕氏春秋·首时》。注诺也。” 亟请于武公,公弗许；组词：特许；只许成功,不许失败；准许；默许；许认(同意,承认)；许肯(应允)；许允(答应 许xǔ 1.应允,认可~可', '小学', '1'),
    ('讹', 'é', '6', '讠', '左右', NULL, '讹 (形声。从言,化声。字本作譮”。本义谣言) 同本义 譮,伪言也。--《说文》 字亦作讹” 民之讹言。--《诗·小雅·沔水》 讹言大水至。--《汉书·成帝纪》；组词：讹言(谣言) 差错 讹 訛 讹诈 改变；感化 或降于阿,或饮于池,或寝或讹', '小学', '1'),
    ('论', 'lùn', '6', '讠', '左右', NULL, '论 《论语》的简称 论语 子》、《大学》、《中庸》合为四书”,使之在儒家经典中的地位日益提高。今本论语共计20篇,1.2万字 论 (形声。从言,仑声。本义评论,研究', '小学', '1'),
    ('讼', 'sòng', '6', '讠', '左右', NULL, '讼 (形声。从言,公声。从言的字与讲话有关。本义争论) 同本义 讼,争也。...以手曰争,以言曰讼。；组词：聚颂纷纭；讼辩(争辩)；讼斗(争斗)；讼怨(争吵怨恨)；讼直(申辩是非曲直)；讼争(争辩,争吵)；讼罪(争辩无罪)；讼曲', '小学', '1'),
    ('讽', 'fěng', '6', '讠', '左右', NULL, '讽 (形声。从言,风声。本义背诵;朗读;传诵) 同本义 讽,诵也。--《说文》 兴道讽诵言语。--《周礼·大司乐》。注倍文曰讽,以声节之曰诵。” 少不讽。--《荀子·大略》；组词：讽味(诵读诗文而玩索其中的意味)；讽经(念经)；讽书(背书)；讽术(背诵经艺) 婉言微辞或指责 讽,谏也', '小学', '1'),
    ('设', 'shè', '6', '讠', '左右', NULL, '设 (会意。从言,从殳。本义摆设;陈列) 同本义 詏,施陈也。--《说文》 钟鼓既设。--《诗·小雅·彤弓》 整设于门外。--《礼记·月令》。注陈也。” 规矩陈设；组词：陈设(摆设)；设醮修禳(僧道为禳除灾祟而设的道场)；设蓍(占卦', '小学', '1'),
    ('访', 'fǎng', '6', '讠', '左右', NULL, '访 (形声。从言,方声。本义广泛地征求意见) 同本义 詌,泛谋也。--《说文》 詌,谋也。--《尔雅》 王访于箕子。--《书·洪范》 访予落止；组词：访断(咨询决疑)；访覃(问及)；访讯(讯问；打听) 引申为访问、拜访(敬词) 此行殊访戴,自可缓归桡', '小学', '1'),
    ('诀', 'jué', '6', '讠', '左右', NULL, '诀 (形声。从言,夬声。本义辞别,告别。特指长别) 同本义 与死者辞曰诀。--《通俗文》 相诀而去。--《史记·孔子世家》 与王诀曰。--《史记·廉颇蔺相如列传》 诀妻子；组词：诀行(告别而行)；诀去(话别离去)；诀音(遗言)；诀绝(诀别,长别) 通决”', '小学', '1'),
    ('证', 'zhèng', '7', '讠', '左右', NULL, '证 谏正 证,谏也。从言,正声。--《说文》 士尉以证靖郭君,靖郭君不听。--《战国策·齐策》。高诱注证,谏也。”；组词：证谏(直言规劝) 证 通症”', '小学', '1'),
    ('评', 'píng', '7', '讠', '左右', NULL, '评 (形声。从言,平声。本义议论是非高下) 同本义 评,议也。--《广雅》 评,评量。--《广韵》 嵘品古今诗为评,言其优劣。--《南史·钟嵘传》 蔡伯喈评之曰；组词：评决(评定)；评泊(量度或评论)；评品(议论人或事物而定其高下)；评跋(评论,量度)；评断(评议决断)；讲评(讲述和评论', '小学', '1'),
    ('诅', 'zǔ', '7', '讠', '左右', NULL, '诅 (形声。从言,且声。本义诅咒) 同本义 诅,詶也。--《说文》 否则厥口诅祈。--《书·无逸》。疏请神加殃谓之诅。” 以诅射颍考叔者。--《左传·隐公十一年》 出此三物；组词：诅让(咒骂责备)；诅詈(诅咒；咒骂)；诅恨(诅咒怨恨)；诅书(诅咒的文字)；诅魇(用诅咒来害人)；诅祝(祈求鬼神加害于敌', '小学', '1'),
    ('识', 'shí', '7', '讠', '左右', NULL, '识 (形声。从言。戠声。善于言谈,表示有知识,故从言。本义知道;懂得) 同本义 譺,知也。；组词：识味(知味)；识空便(知趣；识相)；识道(知圣道)；识义(知义 识(譺)shí 1.知道,认得,能辨别~字', '小学', '1'),
    ('诈', 'zhà', '7', '讠', '左右', NULL, '诈 (形声。从言,乍声。从言,说明与言论有关。本义欺骗) 同本义 诈,欺也。--《说文》 诈,伪也。--《尔雅》 匿行曰诈。--《荀子·脩身》 有掎挈伺诈；组词：诈端(讹诈的理由)；诈掯(敲诈勒索)；诈哄(欺骗)；诈伪(欺骗)；诈力(诈术与暴力)；诈人(专务诈欺作伪的人) 假装；冒', '小学', '1'),
    ('诉', 'sù', '7', '讠', '左右', NULL, '诉 (形声。本义告状;控告) 同本义 诉,告也。--《说文》 负孝公之周愬天子。--《公羊传·昭公三十一年》 必东愬于齐。--《战国策·齐策》 即连楮为巨幅,广二丈,大书一屈”字；组词：起诉；上诉；公诉；诉呈(诉状)；诉权(起诉和诉原的权利)；诉辩(申诉并辩白)；诉牒(诉状)；诉告(上诉；告状) 告诉,说', '小学', '1'),
    ('诊', 'zhěn', '7', '讠', '左右', NULL, '诊 医生为断定疾症而察看病人身体内部、外部的情况门~。~断。~室。~脉。 察看,验证匠石觉而~其梦”。 诊zhěn看病,检查病人就~。~病。~断。随到随~。巡廻~治。', '小学', '1'),
    ('词', 'cí', '7', '讠', '左右', NULL, '词 (形声。从言,司声。本义言词。按,辞”、词”在言词”这个意义上是同义词。但在较古的时代,一般只说辞”,不说词”『代以后逐渐以词”代辞”)；组词：名词；动词；形容词；词色(声色)；词锋(犀利的文笔,好像刀剑的锋芒)；词不达意 诗文中的词语 词 cí 1言词；词句歌~', '小学', '1'),
    ('译', 'yì', '7', '讠', NULL, NULL, '译 (形声。从言,瞘声。本义翻译,把一种语言文字翻译成另一种语言文字) 同本义 译,传译四夷之言者。；组词：汉语被译成日语；译品(翻译的作品)；译义(意译)；译写(翻译写作)；译经(翻译经典) 解释；阐述 夫圣人为天口,贤者为圣', '小学', '1'),
    ('试', 'shì', '8', '讠', '左右', NULL, '试 (形声。从言,式声。本义用;任用) 同本义 试,用也。--《说文》 明试以功。--《虞书》 今予将试以汝迁。--《书·盘庚》 师干之试。--《诗·小雅·采芑》 兵革不试；组词：试兵(用兵) 尝试 试,尝也', '小学', '1'),
    ('诗', 'shī', '8', '讠', '左右', NULL, '诗 (形声。从言,寺声。本义诗歌) 同本义 诗言志,歌永言。--《书·舜典》 诗,志也。--《说文》 诗所以合意,歌所以咏诗也。--《国语·鲁语》 教六师,曰风,曰赋,曰比,曰典；组词：诗筒(装诗稿的竹筒)；诗瓢(放诗稿的瓢勺)；诗友(以诗词唱和的朋友)；诗虎(作成诗句的灯谜)；诗流(诗的流别系统)；诗案', '小学', '1'),
    ('诚', 'chéng', '8', '讠', '左右', NULL, '诚 (形声。从言,成声。本义诚实,真诚) 同本义 诚,信也。--《说文》 币必诚。--《礼记·郊特牲》 诚者自成也。--《礼记·中庸》 帝感其诚,命夸娥氏二子负二山,一厝朔东；组词：诚款(真诚恳切)；诚敬(真诚,敬重)；诚虔(虔诚,恭敬而有诚意) 真实 善人为邦百年,亦可以胜残去杀矣', '小学', '1'),
    ('话', 'huà', '8', '讠', '左右', NULL, '话 (形声。从言,舌声。本义言语) 同本义 话,合会善言也。--《说文》 著之话言。--《左传·文公六年》 不知话言。--《左传·文公十八年》 告之话言；组词：话言(话语)；话差(言语纠葛；争吵)；话白儿(闲话)；话布口袋(比喻一肚子的话) 话题 话本；故事 授意表达的言词 话h', '小学', '1'),
    ('诞', 'dàn', '8', '讠', '左右', NULL, '诞 (形声。从言,延声。本义说大话) 同本义 诞,词诞也。--《说文》 诞惟民怨。--《书·酒诰》 肆朕诞以尔东征。--《书·大诰》 言神事如迂诞。--《汉书·郊祀志上》；组词：诞诈(诞妄奸诈)；诞辞(虚诞的言辞)；诞言(夸大的话) 虚妄；荒唐 是言诞也', '小学', '1'),
    ('诡', 'guǐ', '8', '讠', '左右', NULL, '诡 (形声。从言,危声。本义责成,要求) 同本义 诡,责也。--《说文》 自诡灭贼。--《汉书·赵充国传》 今臣得出守郡,自诡效功,恐未效而死。--《汉书·京房传》；组词：诡求(要求,责求)；诡驳(责难驳斥)；诡责(责备；责问)；诡令(责令) 违反,自相矛盾 诡,违也', '小学', '1'),
    ('询', 'xún', '8', '讠', '左右', NULL, '询 (形声。从言,旬声。本义询问,请教) 同本义 今因经无以询为问罪字,遂用讯不用询,其实讯询一字也。--朱骏声《说文通训定声》 询事考言。', '小学', '1'),
    ('该', 'gāi', '8', '讠', '左右', NULL, '该 (形声。从言,亥声。本义军中互相戒守的约言。《说文》该,军中约也。”引申为完备”。引申义完备,包括一切。通赅”) 同引申义 此该之变而道之也。；组词：该洽(完备周详)；该备(完备,详备)；该尽(完备无遗)；该详(完备详尽) 广博 该 包容；包括 该gāi 1.应当应~', '小学', '1'),
    ('详', 'xiáng', '8', '讠', '左右', NULL, '详 (形声。从言,羊声。本义审察,审理) 同本义 详,审议也。--《说文》 度作详刑,以诘四方。--《书·吕刑》。郑注审察之也。” 凤姐详情度理,说他们必不敢多说一句话；组词：详允(审判得当、公平)；详当(详审而允当)；详阅(审查批阅) 详细说明 又如详梦(解梦；析梦)；内详；另详 清楚地知道', '小学', '1'),
    ('诫', 'jiè', '9', '讠', '左右', NULL, '诫 (形声。从言,戒声。本义告诫,警告) 同本义 誡,敕也。--《说文》 前车覆,后车诫。--《汉书》 规劝 宾临终,诫其二子速侯、回题,令善事帝；组词：引以为诫 规劝告诫之文 诫jiè 1.警告,劝告告~', '小学', '1'),
    ('诬', 'wū', '9', '讠', '左右', NULL, '诬 欺骗 因为诬上,卒从吏议。--司马迁《报任安书》 佞誉诬谀。--唐·柳宗元《柳河东集》；组词：诬禄(假冒有功而受禄) 无中生有,捏造事实害人 诬善之人,其辞游', '小学', '1'),
    ('语', 'yǔ', '9', '讠', '左右', NULL, '语 (形声。从言,吾声。本义谈论;议论;辩论) 同本义 语,论也。--《说文》 于时语语。--《诗·大雅·公刘》。传论难曰语。” 旦日,卒中往往语。--《史记》 子不语怪、力、乱；组词：语怪(谈论怪物)；语冰(谈论冰)；语议(言谈议论) 交谈,说话 语,言也', '小学', '1'),
    ('误', 'wù', '9', '讠', '左右', NULL, '误 谬误;错误 误,谬也。--《说文》 群臣议皆误。--《史记·萧相国世家》 兴尽晚归舟,误入藕花深处。--李清照《如梦令》 误落尘网中。--晋·陶渊明《归田居》 土木之误；组词：笔误；误错(失误差错)；误证(错误的证明)；误本(有错字的版本)；误谬(谬误；差错) 误 耽误 郑以救公误之,遂失秦伯', '小学', '1'),
    ('诱', 'yòu', '9', '讠', '左右', NULL, '诱 (形声。从言,秀声。字本作羑”,从厶,从羑。厶,同私”。羑,诱导。本义教导;引导;劝导)；组词：诱兵(战争时诈败以引诱敌人中计的士兵或引诱敌兵)；诱敌(诱引敌人进入埋伏的地方) 向导,引 诱yòu 1.引导,教导,劝', '小学', '1'),
    ('诲', 'huì', '9', '讠', '左右', NULL, '诲 (形声。从言,每声。本义教导) 同本义 诲,说教也。--《说文》 慢藏诲盗,野容诲淫。--《易·系辞》 胥教诲。--《书·无逸》 诲尔序爵。--《诗·大雅·桑柔》 夫子诲之髽；组词：诲示(教导,晓示)；诲诱(教导循诱)；诲谕(教诲晓喻)；诲翰(诲函', '小学', '1'),
    ('说', 'shuō', '9', '讠', '左右', NULL, '说 shui 说服;劝说 义兴人谓为三横,而处尤剧。或说处杀虎斩蛟,实冀三横唯余其一。--《世说新语·自新》 鲰生说我曰距关,毋内诸侯,秦地可尽王也；组词：游说；说士(游说的人)；说客(游说之士)；说项(本意为称道人善,后引申凡替人游说,阐说人情都可称说项”)；说难(指用言语', '小学', '1'),
    ('诵', 'sòng', '9', '讠', '左右', NULL, '诵 (形声。从言,甬声。本义背诵、朗读) 同本义 诵,讽也。--《说文》。徐锴曰临文为诵。” 兴道讽诵言语。--《周礼·大司乐》。注背文曰讽,以声节之曰诵。” 春诵夏弦；组词：熟读成诵；过目成诵；背诵；诵经；记诵(默记和背诵)；诵笃笃(叽叽咕咕,嘟嘟噜噜)；诵咏(诵 诵sòng 1.背读,用抑扬', '小学', '1'),
    ('请', 'qǐng', '10', '讠', '左右', NULL, '请 通情”。情况,实情 上下请通。--《墨子·尚同中》 四璧而知请。--《管子·白心》 请 (形声。从言,青声。本义拜访)；组词：请谒(拜见) 请求；要求 请,求也', '小学', '1'),
    ('诸', 'zhū', '10', '讠', '左右', NULL, '诸 (形声。从言,者声。本义辩,问辩) 同本义 诸,辩也。--《说文》。按,者亦意辩词也。 诸诸便便,辩也。--《尔雅》 穷研细诸问,岂得信虚辞!--《敦煌变文集·燕子赋》；组词：诸问(问辩) 诸 众；各 诸郡县苦秦吏', '小学', '1'),
    ('诺', 'nuò', '10', '讠', '左右', NULL, '诺 (形声。从言,若声。本义表示) 同本义(一般用于上对下、尊对卑或平辈之间,卑对尊用谨诺” 诺,应也。；组词：诺诺(连声应诺)；诺唯(应诺)；诺许(许诺；应允) 古时批字于公文之尾,表示许可叫诺”,犹今签字 是谁画诺谁传诏,一纸明', '小学', '1'),
    ('读', 'dú', '10', '讠', '左右', NULL, '读 (形声。从言,卖声。本义读书) 籀书,抽释理解书的意义 读,诵书也。--《说文》 主人习其读而问其传。--《公羊传·定公元年》 读其书。--《孟子》 相随观读,讽述以谈；组词：读法(诵读法令)；读祝(祭祀时宣读祈祷文)；读鞫(审判时,宣读起诉理由) 阅读 好读书,不求甚解', '小学', '1'),
    ('诽', 'fěi', '10', '讠', '左右', NULL, '诽 (形声。从言,非声。本义背地议论,指责他人) 同本义 诽,谤也。--《说文》。按,放言曰谤,微言曰诽、曰讥。” 诽,明恶也。--《墨子经上》 至于怨诽之多,则固前知其如此也；组词：诽怨(责备怨恨)；诽议(责难,非议) 毁谤 经诽誉', '小学', '1'),
    ('课', 'kè', '10', '讠', '左右', NULL, '课 (形声。从言,果声。本义考核) 同本义(根据一定的标准验核) 课,试也。--《说文》 操杀生之柄,课群臣之能者也。--《韩非子·定法》 成器不课不用,不试不藏；组词：课其事业；课试(试验,考核)；课绩(考绩) 督促完成指定的工作 课家人负物百斤,环舍趋走', '小学', '1'),
    ('谁', 'shuí', '10', '讠', '左右', NULL, '谁 (形声。从言,隹声。金文字形,象鸟在叫。1基本义什么人。《左传·隐公元年》其谁曰不然?”2什么。《说文》何也。”) 哪个人或哪些人 莫愁前路无知己；组词：那是谁；站在门口的人是谁；这个单位谁当政；你把书给了谁?谁承望(谁想到)；谁家子(谁,何人)；谁子(谁氏,何人)；谁当(', '小学', '1'),
    ('调', 'diào', '10', '讠', '左右', NULL, '调 diao (形声。从言,周声。本义声音调和;协调) 盐或提拔官吏 调故吏。--《汉书·昭帝纪》。注谓发选也。” 调关东轻车锐卒。--《汉书·宣帝纪》 十年不得调,亡所知名；组词：调头(换地方；自主的妓女迁居)；调职(公务员调换服务单位) 征用,提取,征发 特选横调', '小学', '1'),
    ('谅', 'liàng', '10', '讠', '左右', NULL, '谅 (形声。从言,京声。本义诚实;信实) 同本义 谅,信也。--《说文》 众信曰谅。--《方言一》 请肆简谅。--《礼记·内则》 友直友谅。--《论语》 易直子谅之心；组词：谅直(诚信正直)；谅士(诚信之士)；谅节(高尚的节操)；谅实(真诚) 固执,坚持己见 君子贞而不谅', '小学', '1'),
    ('谆', 'zhūn', '10', '讠', '左右', NULL, '谆 (形声。本义教诲恳切耐心的样子) 同本义。多叠用,也单用 谆,告晓之熟也。--《说文》。字亦作詒。 诲尔谆谆。--《诗·大雅·抑》 不必谆谆。--《史记·司马相如传》；组词：谆谆醇醇(恳切淳厚)；谆谆教导；谆谕(谆谆告谕)；谆熟(再三告诫要牢记在心) 诚恳；忠诚 谆谆忠谨之貌也', '小学', '1'),
    ('谈', 'tán', '10', '讠', '左右', NULL, '谈 (形声。从言,炎声。本义说,谈论) 同本义 谈,语也。--《说文》。字亦作谭。 不敢戏谈。--《诗·小雅·节南山》 三日不谈。--《庄子·天运》 宏为人谈笑多闻；组词：谈笑自若；谈聚(相聚在一起尽情交谈)；谈会(聚在一起谈论)；洽谈(接洽商谈)；座谈(不拘形式地讨论)；谈天(谈论天文)', '小学', '1'),
    ('谊', 'yì', '10', '讠', '左右', NULL, '谊 (会意兼形声。从言,从宜,宜亦声。宜,表示合宜。本义合宜的道德、行为或道理) 同本义 舍生取谊。--班固《幽通赋》 素闻先生高谊。；组词：谊士(义士)；谊主(指明礼义的国君) 意义,意思 会意者,比类合谊', '小学', '1'),
    ('谋', 'móu', '11', '讠', '左右', NULL, '谋 (形声。从言,某声。本义考虑;谋划) 同本义(侧重于商议出办法或盘算出主意) 虑难曰谋。；组词：谋谟殚神(筹谋划策,竭尽全力)；不谋而合；合谋( 谋móu 1.计划,计策,主意~划', '小学', '1'),
    ('谍', 'dié', '11', '讠', '左右', NULL, '谍 (形声。从言,枼声。本义间谍,细作) 间谍 谍,军中反间也。--《说文》 掌斩杀贼谍而搏之。--《周礼·掌戮》 搏贼谍。--《周礼·环人》。注反间为国贼。” 晋人获秦谍；组词：防谍；谍贼(暗探和叛国贼)；谍人(间谍) 传递的情报 宁边军数日间连受八十余谍', '小学', '1'),
    ('谎', 'huǎng', '11', '讠', '左右', NULL, '谎 (形声。从言,荒声。本义谎言,假话) 同本义 梦中讲的话 谎,梦言也。--《说文》 不公平或欺骗的价格 谎 哄骗,用假话或手段骗人 谎 虚假 谎huǎng 1.骗人,假话~骗', '小学', '1'),
    ('谐', 'xié', '11', '讠', '左右', NULL, '谐 (形声。从言,皆声。本义和谐) 同本义(强调配合得匀称) 谐,和也。--《尔雅》 克谐以孝。--《书·尧典》 掌司万民之难而谐和之。--《周礼·调人》 如乐之和,无所不谐；组词：谐当(妥当)；谐和(各组成部分之间协调地相互联系在一起的)；谐调(和谐)；谐奏(和协地演奏)；谐律(谐合于音律) 言语', '小学', '1'),
    ('谒', 'yè', '11', '讠', '左右', NULL, '谒 (形声。从言,曷声。本义禀告,陈述) 同本义 谒,白也。--《说文》 谒,告也。--《尔雅》 摈者谒诸天子。--《仪礼·觐礼》 能典谒矣；组词：谒急(告急)；谒言(进谏) 告发；检举 伍、官、连、县而邻,谒过赏,失过诛', '小学', '1'),
    ('谓', 'wèi', '11', '讠', '左右', NULL, '谓 (形声。从言,胃声。本义告诉) 同本义 谓,报也。--《说文》 人以谓霍氏。--《汉书·霍光传》。注告语也。” 太后明谓左右。--《战国策·赵策》 谓安陵君曰', '小学', '1'),
    ('谚', 'yàn', '11', '讠', '左右', NULL, '谚 (形声。从言,彦声。本义谚语) 同本义 谚,传言也。字亦作喭。--《说文》 故谚有之曰。--《礼记·大学》 谵有之曰。--《国语·越语》。注谚俗之善谣也。” 谚所谓辅车相依；组词：农谚；谚言(俗语、直语、直接明说的俗话)；无知便是福”是个古谚 谚 通唁”', '小学', '1'),
    ('谜', 'mí', '11', '讠', '左右', NULL, '谜儿 mei 猜谜儿 謎谜 mi (会意兼形声。从言,迷声。本义谜语) 同本义 谜,隐言也。；组词：猜谜；谜语；灯谜(贴在灯上的谜语) 没有弄清楚的事物 谜底 谜语的答案 谜团 谜团 难解的谜团 谜语 谜(詸)mí让人猜', '小学', '1'),
    ('谢', 'xiè', '12', '讠', '左右', NULL, '谢 (形声。从言,射声。本义向人认错道歉) 同本义 自谢曰。--《战国策·赵策》 长跪而谢。--《战国策·魏策》 旦日不可不蚤自来谢项王。--《史记·项羽本纪》 惊谢曰；组词：谢咎(引咎自退；悔过；谢罪)；谢错(认错赔不是)；谢室(待罪之室) 用言辞委婉地推辞拒绝 乃召拜黯为淮阳太守,黯伏谢不受', '小学', '1'),
    ('谣', 'yáo', '12', '讠', '左右', NULL, '谣 (形声。) 有章句曰歌,无章曲曰谣。--《韩诗章句》 辨妖祥于谣。--《国语·晋语》 其歌声比余谣。--《书·大传》 西王母为王谣。--《列子·周穆王》 心之忧矣,我歌且谣；组词：谣诱(花言巧语,诱人上当) 行歌,乐曲 吾闻文、成之世,童谣有之', '小学', '1'),
    ('谤', 'bàng', '12', '讠', '左右', NULL, '谤 (形声兼会意。从言,旁声。本义在背后公开地议论或批评某人的短处) 同本义 谤,毁也。--《说文》。按,谤者道人之实,事与诬谮不同。大言曰谤,小言曰诽,曰讥。 厉王虐,国人谤王；组词：谤书(攻击别人或揭发别人隐私的文书；亦专指《史记》) 诽谤 信而见疑,忠而被谤,能无怨乎?--《史记·屈原贾生列传》 是', '小学', '1'),
    ('谦', 'qiān', '12', '讠', '左右', NULL, '谦 (形声。从言,兼声。本义谦虚,谦逊) 同本义 谦,敬也。--《说文》。按,侧重于内心上的恭顺谨慎。 谦,逊让也。--《玉篇》 谦也者,致恭以存其位者也。又,谦者,德之柄也；组词：谦洽(谦虚和蔼)；谦光(虽谦抑而辉光益显)；谦冲(谦虚)；谦克(谦逊自制)；谦厚(谦逊温厚) 谦 通"嫌"', '小学', '1'),
    ('谨', 'jǐn', '13', '讠', '左右', NULL, '谨〈形〉 (形声。从言,堇声。本义谨慎,小心) 同本义 谨,慎也。--《说文》 以谨无良。--《诗·大雅·民劳》 以谨罔极。 谨畜藏。--《荀子·王制》 谨厚以为厚；组词：谨畏(小心谨慎)；谨肃(严谨认真)；谨言(谨慎说话)；谨厚(谨慎忠厚)；谨介(谨慎耿介) 恭敬 谨斩樊於期头', '小学', '1'),
    ('谬', 'miù', '13', '讠', '左右', NULL, '谬 (形声。本义极端错误,非常不合情理) 同本义 谬,狂者之妄言也。--《说文》 考之三王而不谬。--礼记·中庸》 天下悦之以谬悠之说。--《庄子》 解心之谬；组词：谬戾(荒谬乖僻)；谬谈(谬语妄说)；谬举(妄举,举用不适当的人才)；谬种流传(荒谬错误的文章或议论辗 谬miù 1.错误', '小学', '1'),
    ('谭', 'tán', '14', '讠', '左右', NULL, '谭 (形声。从言,覃声。本义同谈”,说) 同本义 夫子何不谭我于王。--《庄子·则阳》 又如谭笑(谈笑);谭艺(谈论文学艺术);谭说(议论;谈论);谭吐(说话时的措词和态度)；组词：谭笑(谈笑)；谭艺(谈论文学艺术)；谭说(议论；谈论)；谭吐(说话时的措词和态度)；谭助(谈资)；谭言微中(说话隐微曲折', '小学', '1'),
    ('谱', 'pǔ', '14', '讠', '左右', NULL, '谱 (形声。从言,普声。本义记载事物类别或系统的书) 同本义 谱,牒也。--《广雅》 谱,籍录也。--《说文新附》。朱骏声曰桓君山云,太史公三代世表,旁行斜上,普效周谱；组词：食谱；歌谱；谱学(研究氏族或宗族世系的学科)；谱录(用谱表的方式记录世系)；家谱；棋谱 符号或文字列记乐歌的音节、声调,', '小学', '1'),
    ('谴', 'qiǎn', '15', '讠', '左右', NULL, '谴 (形声。本义责备,斥责) 同本义 谴,谪问也。--《说文》 谴,呵也。--《苍颉篇》 畏此谴怒。--《诗·小雅·小明》 闻而谴友。--《孔子家语·五行》 某时有客过而予汝金；组词：谴谪(责备)；谴斥(受责备)；谴告(谴责警告)；谴呵(谴责申叱)；谴咎(谴责罪过)；谴怒(怒责) 旧时官吏被贬或谪戍 又', '小学', '1'),
    ('谷', 'gǔ', '7', '谷', '上下', NULL, '谷〈名〉 (会意。甲骨文字形,上面的部分象水形而不全,表示刚从山中出洞而尚未成流的泉脉;下面象谷口。谷”是汉字部首之一。本义两山之间狭长而有出口的低地,往往包含一个流 域)；组词：向斜谷；裂谷；山谷；河谷；峡谷；幽谷；谷口(两山之间的入口)；谷水(山谷的水) 两山之间的水流 泉出通川为谷 谷(穣)g', '小学', '1'),
    ('豁', 'huō', '17', '谷', '左右', NULL, '豁 空缺;露出缺口;缺损 豁 裂开;割裂 舍弃,狠心付出某种代价 豁 〈名 豁huō 1.缺,裂开一个~口。~子(缺的口子)。~唇。 2.舍弃,狠心付出高价~命拼搏', '小学', '1'),
    ('豆', 'dòu', '7', '豆', '上中下', NULL, '莣豆 (象形。甲骨文字形,形似高脚盘,或有盖『字部首之一,从豆”的字或与食器有关。或与豆类有关。本义古代一种盛食物的器皿)', '小学', '1'),
    ('豌', 'wān', '15', '豆', '左右', NULL, NULL, '小学', '1'),
    ('象', 'xiàng', '11', '豕', '上中下', NULL, '象 (象形。甲骨文字形,突出其长鼻。本义大象,一种哺乳动物) 象科的,特别是象属(elephas)和非洲象属(loxodonta)的体型极大而粗重的几乎无毛的四足动物 象；组词：象口(象状香炉口)；象王(象中最大者,佛家喻佛) 象牙的省称 南方之美者,有梁山 象xiàng 1.现存的陆地上最大的哺', '小学', '1'),
    ('豪', 'háo', '14', '豕', '上下', NULL, '豪〈名〉 (形声。从豕,猪,高省声。本义豪猪) 同本义 豪,豪豕鬣如笔管者,出南郡。--《说文》。俗字作毫”。 鹿台之山,其兽多白豪。--《山海经·西山经》 豪,猪也；组词：豪毛(豪猪身上的长而末端尖细的毛)；豪豨(豪彘±猪) 通毫”', '小学', '1'),
    ('豫', 'yù', '15', '豕', '左右', NULL, '豫 (形声。从象,予声。本义大象) 同本义 豫,象之大者。--《说文》 豫焉若冬涉川。--《老子》。范应元注豫,象属。” 地名。豫州,古九州之一 指通豫南', '小学', '1'),
    ('豹', 'bào', '10', '豸', '左右', NULL, '豹 (形声。从豸,勺声。豸”),象形字,本指长脊的野兽。本义豹子) 同本义 豹,似虎圆文。；组词：豹尾(豹的尾巴；用豹尾做装饰的车或旗等)；豹跳(暴跳；躁怒之相)；豹隐(喻隐居) 豹 bào 1豹子', '小学', '1'),
    ('豺', 'chái', '10', '豸', '左右', NULL, '豺 (形声。从豸),才声。从豸”,表示与野兽有关。本义野兽名。形似犬而残猛如狼,俗名豺狗)', '小学', '1'),
    ('貌', 'mào', '14', '豸', '左右', NULL, '貌 (形声。从豹省,皃声。本作皃”,从人白”,象人面形。儿,古文人”字。本义面容,相貌,容貌)；组词：貌团团(形容面容姣圆、丰润的样子)；貌侵(容貌丑陋 貌(皃)mào 1.面容,长相面~', '小学', '1'),
    ('贝', 'bèi', '4', '贝', '半包围', NULL, '贝 (象形。甲骨文和金文字形,象海贝形『字部首之一。古时以贝壳为货币,又用作装饰,故从贝”的字多与钱财宝物、装饰品或贸易商品有关。本义海贝) 牡蛎；组词：贝阁(用贝壳装饰宫门前的楼观)；贝阙(以贝装饰的宫门楼观)；贝文(贝壳的纹彩)；贝饰(贝制的饰物)；贝雕(在贝壳上雕刻或', '小学', '1'),
    ('贞', 'zhēn', '6', '贝', '上下', NULL, '贞 (会意。从卜,从贝(甲骨文作鼎”,后省改为贝”)。鼎本是食器,这里表火具,即用火具而卜。本义占卜)；组词：贞龟(占卜', '小学', '1'),
    ('负', 'fù', '6', '贝', '上下', NULL, '负 (会意。从人,从贝。本义恃,即依恃,凭仗) 同本义 负,恃也。从人守贝,有所恃也。--《说文》 秦贪,负其强。--《史记·廉颇蔺相如列传》 负势竞上,互相轩邈；组词：负固(依仗地势险固)；负固不悛(依凭险阻而不悔改)；负宠(依仗宠爱)；负学(依恃才学)；负险(凭借险固的地形)；负势(依', '小学', '1'),
    ('贡', 'gòng', '7', '贝', '上下', NULL, '贡 (形声。从贝,工声。本义进贡,把物品进献给朝廷) 同本义 贡,献功也。--《说文》 贡,上也。--《释言》 贡,献也。--《广雅》 尔贡包茅不入；组词：贡奉(进献物品给朝廷)；贡云(宋宫中假山艮岳既成,命 贡gòng 1.〈古〉将物品进献给皇帝进~', '小学', '1'),
    ('财', 'cái', '7', '贝', '左右', NULL, '财 (形声。从贝,才声。本义财物) 同本义(多指日常生活必需品,包括米粟在内) 财,人所宝也。', '小学', '1'),
    ('责', 'zé', '8', '贝', '上下', NULL, '责 (形声。小篆字形。从贝,朿声。本义债款,债务) 索取(财物) 责,求也。--《说文》 往责于东邑。--《吕氏春秋·慎行论》 责之里正。--《聊斋志异·促织》 责一头；组词：责偿(索取赔偿)；责货(索贿)；责诺(求取他人的许诺)；责义(以合乎礼义要求别人)；责债(索债)；责赂(索求财物) 责备', '小学', '1'),
    ('贤', 'xián', '8', '贝', NULL, NULL, '贤 (形声。从贝,与财富有关。本义多财) 有德行;多才能 贤,多才也。--《说文》 以财分人之谓贤。--《庄子·徐无鬼》 相如既归,赵王以为贤大夫。--《史记》 闲贤臣；组词：贤声远达(好的名声远扬四处)；贤歌(品行技艺都好的歌妓)；贤才(德才并美之人)；时贤(指当代有贤能有声望的人) 对人的敬', '小学', '1'),
    ('败', 'bài', '8', '贝', '左右', NULL, '败 (会意。从贝,从攴。攴,甲骨文象以手持杖,敲击的意思,汉字部首之一。在现代汉字中,攴”大多写成攵”,只有极少数字保留着攴”的写法。从攴”的字多与打、敲、 击等手的动作有关。败', '小学', '1'),
    ('账', 'zhàng', '8', '贝', '左右', NULL, '账 (古作帐”。形声。从贝,长声。从贝,表明与财富有关。本义账目,关于银钱财物出入的记载)；组词：账略(简要的账目) 债务,欠别人的东西(如金钱、货物等) 账簿 账(賬)zhàng 1.钱财出入的记载记~', '小学', '1'),
    ('货', 'huò', '8', '贝', '上下', NULL, '货 (形声。从贝,化声。本义财物) 财物,金钱珠玉布帛的总称 货,财也。--《说文》 二曰货。--《书·洪范》。郑注掌金帛之官。” 商贾阜通货贿。--《周礼·太宰》。注金玉曰货；组词：货儿(货郎)；货易(即贸易)；货huò 1.钱~币', '小学', '1'),
    ('质', 'zhì', '8', '贝', NULL, NULL, '质 (形声。从贝,斦声。朱骏声认为斦”是砧板。从贝,与财富有关。本义抵押;以...作人质)；组词：质库(当铺)；质作(抵押其身,使服劳役)；质鬻(典押出卖)；质录(收押)；质卖(典押和出卖)；质债(抵债)；质当(典当', '小学', '1'),
    ('贩', 'fàn', '8', '贝', '左右', NULL, '贩 (形声。从贝,反声。本义贱买而贵卖的人) 同本义 贩,买贱卖贵也。--《说文》 贩夫贩妇。--《周礼·司市》 虽负贩者,必有尊也。--《礼记·曲礼》；组词：菜贩；摊贩；贩商(商贩)；贩人(商贩) 古国名 贩,古国名', '小学', '1'),
    ('贪', 'tān', '8', '贝', '上下', NULL, '贪 (形声。从贝,今声。从贝”,与财物有关。本义贪财) 同本义 贪,欲物也。--《说文》 晋、魏河内之比,谓惏曰残。楚谓之贪。--《方言一》 贪于饮食,惰于作务；组词：贪赃(官吏接受贿赂)；贪便宜；贪得无厌；贪冒(贪图财利)；贪鄙(贪婪卑鄙)；贪汙(贪求私利,取非分的财物)；贪墨(贪财受', '小学', '1'),
    ('贫', 'pín', '8', '贝', '上下', NULL, '贫 (会意兼形声。从贝从分,分亦声。贝”是古货币,一个贝”还要分开,表示贫困。本义缺少财物,贫困。与富”相对)；组词：贫难(贫苦,困难)；贫胎(骂人的话', '小学', '1'),
    ('贬', 'biǎn', '8', '贝', '左右', NULL, '贬 (形声。从贝,乏声。本义减少;减损) 同本义 贬,损也。--《说文》 贬,减也。--《广雅》 何以不氏,贬。--《公羊传·隐公二年》。注犹损也。” 贬食省用；组词：贬颜(容颜瘦损)；贬乐(减少声色之娱)；贬价(降低价格)；贬悴(瘦损憔悴) 降级 请自贬三等,以督厥咎', '小学', '1'),
    ('购', 'gòu', '8', '贝', '左右', NULL, '购 (形声。从贝。从贝”,表示与财物有关。本义悬赏征求) 同本义 购,以财有所求也。--《说文》 购,偿也。--《广雅·释言》 吾闻汉购我头千金,邑万户,吾为若德；组词：购求(设置奖金以捉捕犯人)；购问(悬赏征询)；购募(悬赏募求)；购悬(悬赏缉拿) 原指用重金收买,后泛指买 帝方博购王羲', '小学', '1'),
    ('贮', 'zhù', '8', '贝', '左右', NULL, '贮 (形声。从贝,宁声。从贝与财物有关。本义积存,收藏) 同本义(侧重于保存,含有积累储存的过程) 賏,积也。', '小学', '1'),
    ('贯', 'guàn', '8', '贝', '上下', NULL, '贯 (会意。从毌,从贝(表示与钱财有关)。毌”是贯穿之贯,象穿物之形。本义穿钱的绳子) 同本义 贯,钱贝之贯也。；组词：贯朽(串钱的绳子朽断,形容积钱多而经久不用) 旧时用绳索穿钱,每一千文为一贯 着落店主人家追要原典身钱三千贯', '小学', '1'),
    ('贰', 'èr', '9', '贝', '半包围', NULL, '贰 (会意。从贝,弍,声。本义副) 同本义 贰,副益也。--《说文》。段注当云副也,益也。” 簋贰用缶。--《易·坎卦》 大祭三贰。--《周礼·乃酒正》 取贰绥；组词：贰佐(州县官的副)；贰相(副相)；贰官(副职) 二的大写 因贰以济民行', '小学', '1'),
    ('贱', 'jiàn', '9', '贝', '左右', NULL, '贱 (形声。从贝,戋声。本义价格低) 同本义 贱,买少也。--《说文》 籴甚贵,伤民,甚贱伤农。--《汉书·食货志》 心忧炭贱愿天寒。--唐·白居易《卖炭翁》；组词：贱敛贵出(低价买入,高价售出)；贱酬(降价付钱)；贱发(降价发卖)；贱贸(低价出售)；贱售(贱卖) 地位低下,人格卑鄙', '小学', '1'),
    ('贴', 'tiē', '9', '贝', '左右', NULL, '贴〈动〉 (形声。从贝,占声。本义典当) 同本义 民日贴妇卖儿。--《聊斋志异·促织》 又如贴钱(典钱;质钱);贴典(典质;典押);贴子(典押儿子) 贴补。补偿；组词：贴钱(典钱；质钱)；贴典(典质；典押)；贴子(典押儿子) 贴补', '小学', '1'),
    ('贵', 'guì', '9', '贝', '上下', NULL, '贵 (形声。小篆字形,从贝,臾声。从贝”,表示与钱物有关。本义物价高,与贱”相对) 同本义 贵,物不贱也。；组词：春雨贵如油；昂贵(价格很高)；贵腾(价格暴涨)；贵踊(物价上涨)；贵贾(高价) 社会地位高 贵,尊也', '小学', '1'),
    ('贷', 'dài', '9', '贝', '上下', NULL, '贷 (形声。从贝,代声。从贝”,表示与钱财有关。本义施予;给予) 同本义 贷,施也。--《说文》 贷,予也。--《广雅》 以财投长曰贷。--《大戴礼记·千乘》 凡民之货者；组词：贷施(施舍)；贷恤(赈施抚恤) 借出钱财 宁积粟腐仓而不忍贷人一斗', '小学', '1'),
    ('贸', 'mào', '9', '贝', '上下', NULL, '贸 (形声。从贝,卯声。从贝,与财物有关。本义交换财物,交易) 同本义 贸,易财也。--《说文》 贸,市也。--《尔雅》 氓之蚩蚩,抱布贸丝。--《诗·卫风·氓》。传买也；组词：以臣等贸马；贸籴(买进粮食)；贸迁(贩运买卖)；贸载(指贩运货物的车子)；贸买(购买)；贸售(贩卖,出售)；贸货(买卖货', '小学', '1'),
    ('费', 'fèi', '9', '贝', '上下', NULL, '费 (形声。从贝,弗声。从贝”表示与钱财有关。本义花费 同本义 费,散财用也。--《说文》 费,耗也。--《广雅》 非爱其费也。--《吕氏春秋·安死》。注财也。” 君子惠而不费；组词：费耗(费用)；费钞(花费钱钞)；费钞费贯(耗贯钱财)；费出(花费,支出) 耗损 费神伤魂', '小学', '1'),
    ('贺', 'hè', '9', '贝', '上下', NULL, '贺 奉送礼物表示庆祝 贺,以礼相奉庆也。--《说文》 不然,则重币帛,以贺其福而吊其凶。--《左传·襄公二十八年》 受天之祜,四方来贺。--《诗·大雅·下武》 叔向贺之；组词：贺敬(贺礼)；贺吊往还(庆贺吊唁往来应酬)；贺冬(庆祝冬至节)；贺厦(庆祝大厦落成) 嘉奖；犒劳 今文余一人贺之', '小学', '1'),
    ('贼', 'zéi', '10', '贝', '左右', NULL, '贼 (会意。小篆字形,从戈,则声。从戈,刀毁贝。 本义残害;伤害) 同本义 贼,败也。--《说文》 害良为贼。--《荀子·修身》 不僭不贼,鲜不为则；组词：贼毫(书法的败笔', '小学', '1'),
    ('贾', 'jiǎ', '10', '贝', '上下', NULL, '贾 (形声。本义做买卖) 同本义 贾,市也。--《说文》 父母已去,兄嫂令我行贾。--《乐府诗集·孤儿行》 鄙谚曰长袖善舞,多财善贾。”--《韩非子·五蠹》；组词：贾资(做买卖的资金)；贾道(做买卖之道)；贾贸(买卖；交易)；贾贷(买卖) 坐卖', '小学', '1'),
    ('贿', 'huì', '10', '贝', '左右', NULL, '贿 (形声。从贝,有声。本义财物) 同本义 贿,财也。--《尔雅》 窃贿为盗。--《左传·文公十八年》 以尔车来,以我贿迁。--《诗·卫风·氓》 商贾阜通货贿。--《周礼·太宰》；组词：贿交(以财物相交)；贿货(财物)；贿赂(财货) 贿赂的财物 贿 赠送财物 孟献子聘于周,王以为有礼 贿huì 1.〈古〉', '小学', '1'),
    ('赁', 'lìn', '10', '贝', '上下', NULL, '赁 (形声。从贝,任声。本义给人做雇工) 同本义 穷困,赁佣于齐,为酒人保。--《史记·栾布列传》；组词：赁工(雇工)；赁力(出卖劳力)；赁作(受雇为人劳作)；赁保(受人雇用)；赁书(受雇为人抄写)；赁佣(受雇为佣工) 租用、', '小学', '1'),
    ('赂', 'lù', '10', '贝', '左右', NULL, '赂 (形声。从贝,各声。从贝”,表示与钱财有关。本义赠送财物) 同本义 赂,遗也。--《说文》 大赂南金。--《诗·鲁颂·泮水》 骊姬赂二王。--《国语·晋语》 因厚赂单于；组词：赂贿(用财物买通别人) 行贿,用钱、物买通别人 六国破灭,非兵不利、战不善,弊在赂秦', '小学', '1'),
    ('赃', 'zāng', '10', '贝', '左右', NULL, '赃 (形声。左形,右声。本义赃物) 同本义 以赃获罪,没其先居之财。--《列子·天瑞》 又如赃仗(赃证);赃派(栽赃诬陷);栽赃(坐赃。把赃物或违禁物暗放在别人处,诬告他犯法)；组词：赃仗(赃证)；赃派(栽赃诬陷)；栽赃(坐赃', '小学', '1'),
    ('资', 'zī', '10', '贝', '上下', NULL, '资 (形声。从贝,次声。从贝,与财富有关。本义钱财) 同本义 资,货也。--《说文》 资,川也。--《广雅》 怀其资--《易·旅》 丧乱蔑资。--《诗·大雅·板》 资用乏绝；组词：投资(把资金投入企业)；内资；外资；集资；薪资(工资)；茶资(茶 资zī 1.钱财,费用~财', '小学', '1'),
    ('赊', 'shē', '11', '贝', '左右', NULL, '赊 (形声。从贝,佘声。本义赊欠) 同本义 买货延期交款 赊,贳买也。--《说文》 段注贳买者,在彼为贳,在我则为赊也。” 赊,不交钱而贾曰赊。--《字汇》 凡赊者祭祀无过旬日；组词：赊贷(出借财物给人,准予借者缓期偿还)；赊头(欠帐的期限)；赊钱(所欠的贷款)；赊券(欠帐的字据) 卖物延期收款 少年来', '小学', '1'),
    ('赋', 'fù', '12', '贝', '左右', NULL, '赋 (形声。从贝,武声。从贝”,表示与财物有关。本义征收) 同本义 赋,敛也。--《说文》 赋,税也。--《广雅》 厥赋惟上上错。--《书·禹贡》。传谓土地所生,以供天子；组词：赋银(征收税银)；赋粟(征收田赋)；赋里(征收商业税)；赋币(征收财物) 缴纳赋税 讼者平,赋者均', '小学', '1'),
    ('赌', 'dǔ', '12', '贝', '左右', NULL, '赌 (形声。从贝,者声。本义用财物作注比输赢) 同本义 钱(以金钱为输赢的赌博);赌运(赌博的运气);赌贩(赌棍);赌经(专记赌术的书籍) 泛指比胜负;争输赢 ;赌气)', '小学', '1'),
    ('赎', 'shú', '12', '贝', '左右', NULL, '赎 (形声。左形,右声。本义用财物换回人或抵押品) 同本义 宋人以兵车百乘,文马百驷,以赎华元于郑。；组词：赎生(购买生物来放生)；赎票(出钱赎回被匪徒绑走的肉票) 用财物脱罪或抵免过失 骞后期当斩,赎为庶人', '小学', '1'),
    ('赏', 'shǎng', '12', '贝', '上下', NULL, '赏 (形声。从贝,尚声。本义赏赐;奖给) 同本义 赏,赐有功也。--《说文》 赏,上报下之功也。--《墨子经》 三年有赏于大邦。--《易·未济》 尧能赏均刑法；组词：赏捞(赏赐捞劳)；赏口(供赏赐为奴仆的人口)；赏田(赏赐的田地)；赏首(第一个受赏者)；赏设(犒赏)；赏赣(赏赐)；赏地', '小学', '1'),
    ('赐', 'cì', '12', '贝', '左右', NULL, '赐 (形声。从贝,易声。从贝”,表示与钱财有关。本义赏赐) 给予;上给予下 赐,予也。--《说文》 上予下曰赐。--《正字通》 长者赐,少者贱者不敢辞；组词：赐光(赏脸,赏光)；赐环(将放逐之臣赦罪召还)；赐第(皇上敕建的府第)；赐田(君主所赐予的田地)；赐官(赐予设置家臣以治', '小学', '1'),
    ('赔', 'péi', '12', '贝', '左右', NULL, '赔 (形声。从贝,咅声。贝”是古代货币,与财产买卖有关。本义补还损失) 同本义 陪嫁 亏蚀;耗损 向人道歉或认错 赔péi 1.补还损失~偿。~退。~礼(道歉)。 2.亏,蚀~钱', '小学', '1'),
    ('赖', 'lài', '13', '贝', '左右', NULL, '赖 (形声。从贝,剌声。本义得益;赢利) 同本义 赖,赢也。--《说文》 赖,取也。--《方言十三》 先王岂有赖焉。--《国语·周语》。注利也。” 相语以利,相示以赖,相陈以知贾；组词：赖利(得利) 依靠；依赖；依恃、凭藉 奸人赖赏而富', '小学', '1'),
    ('赘', 'zhuì', '14', '贝', '上下', NULL, '赘 (会意。从敖贝。敖犹放”,贝与财富有关。本义抵押) 同本义 赘,以物质钱也。--《说文》 赘,得也。--《广雅》。按,以物得钱也。 卖子与人作奴婢名曰赘子；组词：赘子(旧时穷苦人家把孩子卖给富家做奴婢的,叫做赘子”) 聚会 梁王赘其群臣而议其过', '小学', '1'),
    ('赚', 'zuàn', '14', '贝', '左右', NULL, '赚 (形声。从贝,兼声。从贝,与财富有关。本义指买卖得盈利) 同本义 我也许过他二十两银子,只恨他没本事赚我的钱。；组词：赚手(获利)；赚得(获得 赢得；获得 西州客,心边赚得,一味春偏', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('赛', 'sài', '14', '贝', NULL, NULL, '赛 (形声。从贝,塞省声。本义行祭礼以酬神) 同本义 冬赛祷祠。--《史记·封禅书》。索隐赛谓报神福也。” 朝析暮赛依巫口。--白居易《新乐府·黑潭龙》；组词：赛文(古代因年谷丰收为酬神而作的祭文)；赛还(祭祀还愿)；赛愿(祭神还愿)；赛神(祭祀以报答神明)；赛馔(祭神的食品)', '小学', '1'),
    ('赞', 'zàn', '16', '贝', '上下', NULL, '赞 (会意本义进财货以求谒见) 同本义 赞,见也。--《说文》。按,玉帛雉羔雁之属皆贝类。贝者,佐见之具。 进见以见为礼也。--《说文》锴注；组词：赞谒(进见)；赞献(进献祭品)；赞见(进见) 导引 太史赞王,王敬从之', '小学', '1'),
    ('赠', 'zèng', '16', '贝', '左右', NULL, '赠 (形声。从贝,曾声。从贝,表示与财富有关。本义赠送) 同本义 赠,玩好相送也。--《说文》 何以赠之。--《诗·秦风·渭阳》 凡赠币无常。--《仪礼·既夕礼》。注玩好曰赠；组词：赠赆(赠送给远行人的路费)；赠仪(赠送的礼物)；赠策(赠物以表示心意)；赠诗(互相酬答)；赠我药石(比喻感谢别人以 赠z', '小学', '1'),
    ('赡', 'shàn', '17', '贝', '左右', NULL, '赡 (形声。从贝,詹声。本义供给) 同本义 皆以赡给九族,赏赐军士。--《晋书·羊祜传》；组词：赡家(养家)；赡育(赡养抚育)；赡身(养活自身)；赡私(赡养身家)；赡用(供给费用)；赡老(供养老人) 周济；帮助 缉盗', '小学', '1'),
    ('赢', 'yíng', '17', '贝', NULL, NULL, '赢 (会意。从贝,从赼,赢省声。贝,古货币,与财富买卖有关。本义有余) 同本义 赢,贾有余利也。；组词：赢衍(丰盈；盈余)；赢财(余财)；赢畜(多余财物的积蓄)；赢副(多余的东西)；赢绌(盈余和亏损)；赢落(帐外结余)；赢费', '小学', '1'),
    ('赤', 'chì', '7', '赤', '上下', NULL, '赤 (会意。甲骨文,从大(人)从火。人在火上,被烤得红红的。一说大火”为赤。本义火的颜色,即红色)；组词：赤刀(刀口赤色的宝刀)；赤衣(红色衣服)；赤丸(红色弹丸)；赤日(红日；烈日)；赤石(红色的石头)；赤泥(呈红色', '小学', '1'),
    ('赦', 'shè', '11', '赤', '左右', NULL, '赦〈动〉 (形声。从攴,赤声。本义宽免罪过) 同本义 赦,置也。--《说文》。段注赦与捨音义同。非专谓赦罪也◇捨行而赦废。赦专为赦罪矣。” 掌三刺三宥三赦之法；组词：赦书(宽免刑罚的文书)；赦贷(宽免罪过)；赦命(赦免的命令)；赦宥(宽恕；赦免)；赦恕(宽免,饶恕)；赦过(赦免过错)', '小学', '1'),
    ('赫', 'hè', '14', '赤', '左右', NULL, '赫〈形〉 (会意。从二赤。火赤。本义泛指赤色) 红如火烧。亦泛指火红色 赫,火赤貌。--《说文》 赫如渥赭。--《诗·邶风·简兮》 如赫日(红日);赫赤(深红;火红)；组词：赫奕(显耀盛大的样子)；赫剌剌(威武显赫的样子)；赫耀(显赫) 显盛 赫赫楚国,而君临之', '小学', '1'),
    ('走', 'zǒu', '7', '走', '上下', NULL, '走 (会意。金文字形象摆动两臂跑步的人形,下部象人脚∠起来表示人在跑。本义跑) 同本义 走,趋也。', '小学', '1'),
    ('赴', 'fù', '9', '走', '半包围', NULL, '赴〈动〉 (形声。从走,卜声。从走”的字、多与跑”、走”有关。本义奔向,奔赴。多指奔向危险的地方)；组词：赴履(奔赴)；赴质(奔赴目标)；赴助(赴救)；赴急(往救急难)；赴援(赴救) 前往；去；到；至,到达 长子迈将赴饶之德兴', '小学', '1'),
    ('赵', 'zhào', '9', '走', '半包围', NULL, '赵 (形声。从走,肖声。本义快走) 同本义 趙,趋趙也。--《说文》 趙,及也。--《广雅》 天子北征,赵行囗舍。--《穆天子传》。郭璞注赵,犹超腾', '小学', '1'),
    ('赶', 'gǎn', '10', '走', '半包围', NULL, '赶 (形声。从走,旱声。1本义兽类翘起尾巴奔跑。《说文》举尾走也。”2追赶;驱赶) 追赶,从后面追上 心道进退而刑道滔赶。；组词：赶先进；你追我赶；赶逐(追赶)；赶彀(追赶)；赶罗(催逼；逼迫)；赶人不要赶上(比喻不要逼人太甚)；赶势利(趋炎附势,依', '小学', '1'),
    ('起', 'qǐ', '10', '走', '半包围', NULL, '起〈动〉 (形声。从走,己声。本义由躺而坐;由坐而立) 同本义 起,能立也。--《说文》 曩子坐,今子起。--《庄子·齐物论》 载起载行。--《诗·小雅·沔水》 请业则起；组词：起在(起来)；起舞(起身而舞', '小学', '1'),
    ('趁', 'chèn', '12', '走', '半包围', NULL, '趁 (形声。本义追逐) 同本义 急逐趁之,蟆入草间。--《聊斋志异·促织》 又如疾趁(急追);趁逐(追逐;追求);趁赶(追逐) 乘便 满足,遂。用同称” 趁 组成介词结构；组词：疾趁(急追)；趁逐(追逐；追求)；趁赶(追逐) 乘便 满足,遂', '小学', '1'),
    ('超', 'chāo', '12', '走', '半包围', NULL, '超 (形声。从走,召声。本义跃上;跳过,跃过) 同本义 超,跳也。--《说文》 超乘者五百乘。--《吕氏春秋·悔过》。注巨踊上车也。” 超回志度；组词：超乘(跃登战车)；超足(腾跃)；超步(跨登；迈步)；超次(超越等级升迁) 提拔；擢升 故莫敢超等逾官', '小学', '1'),
    ('越', 'yuè', '12', '走', '半包围', NULL, '越 (形声。从走,戉声。本义经过,越过) 同本义 越,度也。--《说文》 越,渡也。--《广雅》 越十七扼。--《吕氏春秋·长攻》 越陌度阡；组词：越位；越度(跨越)；越绝(越过,度过)；越陌度阡(穿过田间小路)；越冬(过冬) 超越,跃过 戒勿越', '小学', '1'),
    ('趋', 'qū', '12', '走', '半包围', NULL, '趋 (形声。从走,刍声。本义快步走) 同本义 趋,走也。--《说文》。按,疾行曰趋,疾趋曰走。” 走而不趋。--《礼记·王藻》 帷薄之外不趋；组词：趋蹑(快速尾随)；趋行(急行；赶路)；趋走(疾走)；趋风(快走如风', '小学', '1'),
    ('趟', 'tàng', '15', '走', '半包围', NULL, '趟〈动〉 从浅水中走过 翻土 踩,踏 大洋马一纵一纵的趟起漫天尘土。--徐光耀《平原烈火》 哪一辈子欠人的罪孽啊,都让我们李家人给趟上了。', '小学', '1'),
    ('趣', 'qù', '15', '走', '半包围', NULL, '趣〈形〉 (形声。从走,取声。本义急,赶快) 同本义 趣,疾也。--《说文》 若不趣降汉,汉今虏若,若非汉敌也。--《史记》 趣 〈动〉 通促”。催促;督促 趣其稼事', '小学', '1'),
    ('足', 'zú', '7', '足', NULL, NULL, '足 (会意。甲骨文字形,上面的方口象膝,下面的止”即脚,合起来指整个脚。本义脚) (同本义。秦汉以前,足”和’趾”都表示脚”;脚”表示小腿。魏晋以后,三者都表示脚,但在书面语中', '小学', '1'),
    ('趴', 'pā', '9', '足', '左右', NULL, '趴〈动〉 胸腹部向下卧倒 身体向前倚靠 趴pā 1.胸腹朝地下卧倒~下。 2.身体向前靠在东西上~在桌上。', '小学', '1'),
    ('趾', 'zhǐ', '11', '足', '左右', NULL, '趾 (形声。从足,止声。古所谓趾,指足,不指脚趾。脚指叫做指,趾是止”的后起字。本义脚)；组词：趾股(腿脚)；趾踵(脚)；趾踵相接(形容人数之多)；趾爪(脚爪) 脚指头 右手攀右趾若啸呼状', '小学', '1'),
    ('跃', 'yuè', '11', '足', '左右', NULL, '跃 (形声。从足,翟声。本义跳跃) 同本义 跃,跳也。--《广雅》 涌趯(跃)邪阴。--《汉书·李寻传》。师古曰趯字与跃同。” 骐骥一跃。--《荀子·劝学》 浮光跃金；组词：跃龙门(比喻科举考试)；跃如(踊跃的样子)；跃治(比喻人好炫耀以求表现)；跃马横戈(骑马奔跃,横握长戈)；跃动(跳动)', '小学', '1'),
    ('跋', 'bá', '12', '足', '左右', NULL, '跋 (形声。从足,犮声。本义草中行走,越山过岭) 同本义 文公躬擐甲胄,跋履山川。--《左传·成公十三年》 跋涉山川,蒙犯霜露。--《左传·襄公二十八年》 大夫跋涉,我心则怃；组词：跋援(犹攀登)；跋履(登山涉水) 扭转 跋马望君非一度,冷猿秋雁不胜悲╠严武《巴岭答杜二见忆》 又如跋马(勒紧马绳,使马', '小学', '1'),
    ('跌', 'diē', '12', '足', '左右', NULL, '跌 (形声。从足,失声。本义失足摔倒) 同本义 失蹑曰跌。--《通俗文》 跌而不振。--《汉书·晁错传》。注足失据也。” 若跌而据。--《淮南子·缪称》；组词：他跌伤了；跌磕(挫折,栽筋斗)；跌翻(跌倒,摔倒)；跌跌滚滚(跌交打滚的样子)；跌跌爬爬(连跌带爬)；跌坐(身体迅速坐下', '小学', '1'),
    ('跑', 'pǎo', '12', '足', '左右', NULL, '跑 急走 跑,趵也。--《广雅·释言》 红缰跑骏马,金镞掣秋鹰。--唐·马戴《边将》 又如长跑(长距离跑步);跑解马(表演马术);跑冰(滑冰;溜冰);跑竹马(民间娱乐活动之一种)；组词：长跑(长距离跑步)；跑解马(表演马术)；跑冰(滑冰；溜冰)；跑竹马(民间娱乐活动之一种)；跑搭(奔走,奔忙)；跑路(奔走', '小学', '1'),
    ('跛', 'bǒ', '12', '足', '左右', NULL, '跛 (形声。从足,皮声。本义瘸,腿或脚有毛病)同本义 跛,行不正也。--《说文》 立毋跛。--《礼记·典礼上》 眇能视,跛能履。--《易·履卦》 此独以跛之故；组词：跛足(脚残废有病', '小学', '1'),
    ('距', 'jù', '11', '足', '左右', NULL, '距 (形声。从足,巨声。本义鸡爪) 同本义 距,鸡距也。--《说文》 后阺为之金距。--《左传》 不鸣不将无距。--《汉书·五行志》。注距,鸡附足骨,斗时所用刺之；组词：苗距；槽距；差距；焦距；行距；株距；距国(介于大国之间,或两面受敌的国家)；距随(古人射箭站立时两脚的间隔距离) 倒刺', '小学', '1'),
    ('跟', 'gēn', '13', '足', '左右', NULL, '跟 (形声。从足,艮声。本义足后为跟) 同本义 跟,足踵也。--《说文》 足后曰跟,在下方着地,一体任之,象木根也。--《释名·释形体》 阽焦原而跟趾；组词：跟蹠(脚后跟)；跟踵(脚后跟)；跟胫(脚跟与小腿)；跟趾(脚后跟) 器官的基底部分', '小学', '1'),
    ('跨', 'kuà', '13', '足', '左右', NULL, '跨〈动〉 (形声。从足,夸声。本义迈步,越过) 同本义 跨,渡也。--《说文》。段注谓大其两股间,以有所越也。” 不跨其国。--《国语·晋语》 康王跨之；组词：跨进大门；跨过小沟；跨蹑(跨踏；跨步)；跨巽(跨到或达到巽”的方位)；跨火(跨过火堆', '小学', '1'),
    ('跪', 'guì', '13', '足', '左右', NULL, '跪〈动〉 (形声。从足,危声。本义屈膝,单膝或双膝着地,臀部抬起,伸直腰股) 同本义 跪,拜也。；组词：授立不跪；长跪,半跪；跪拜；跪射；跪下祈祷；跪香拜佛(为长辈祈福寿的一种拜佛仪式) 指足 门者刖跪', '小学', '1'),
    ('路', 'lù', '13', '足', '左右', NULL, '路〈名〉 (形声。从足,各声。本义道路) 同本义 路,道也。--《说文》 路,途也。--《尔雅》 百夫有洫,洫上有途,千户有浍,浍上有道,万夫有川,川上有路。--《周礼·地官》；组词：路奠(出殡时,亲友在灵柩经过的路上设供桌祭奠)；路赆(友人相赠的路费)；路引(行路的通行凭证)；路歧(路歧人', '小学', '1'),
    ('跳', 'tiào', '13', '足', '左右', NULL, '跳〈动〉 (形声。从足,兆声。本义跃) 同本义 跳,...一曰跃也。--《说文》 特跳此者。--《左传·襄公二十五年》 跳往助之；组词：跳蹋(由生气或着急而顿足)；跳索(杂技中的一种绳技)；跳鳞(跳出水面的鱼)；跳踯(上下跳跃) 越过障碍 如跳墙；跳过篱笆', '小学', '1'),
    ('践', 'jiàn', '12', '足', '左右', NULL, '践 (形声。从足,戋声。本义踩,践踏) 同本义 践,履也。--《说文》 践之者,籍之也。--《书大传》 敦彼行苇,牛羊勿践履。--《诗·大雅·行苇》 大夫、士入君门不践阈；组词：践踹(践踏)；践冰(踏在冰上', '小学', '1'),
    ('跷', 'qiāo', '13', '足', '左右', NULL, '跷 (形声。从足,尧声。本义举足) 同本义 躥,举足行高也。从足,喬声。--《说文》 可躥足而待也。--《汉书·高帝纪》 莫不躥足抗首。--扬雄《长杨赋》；组词：跷蹄辇脚(高举脚,轻落足)；跷着腿坐着；跷足(举足)；跷腿(抬脚举步) 竖起 踮起脚后跟 跷起脚来,把一个一个脸面都看遍', '小学', '1'),
    ('跺', 'duò', '13', '足', '左右', NULL, '跺 顿足,用脚猛力踏地 跺 duò(脚)用力踏地急得直~脚。', '小学', '1'),
    ('踊', 'yǒng', '14', '足', '左右', NULL, '踊 (形声。从足,勇声。从足,表示脚的动作行为。本义往上跳) 同本义 踊,跳也。--《说文》 踊,上也。--《广雅》 曲踊三百。--《左传·僖公二十八年》 三踊于幕庭；组词：踊骇(惊扰跳跃)；踊跳(跳跃)；踊身(纵身) 登,登上 景公为路寝之台,成,而不踊焉', '小学', '1'),
    ('踏', 'tà', '15', '足', '左右', NULL, '踏〈动〉 落下 下垂 踏〈动〉 (形声。从足,沓声。本义足着地;踩 ) 同本义 踏,足著地也。；组词：踏步不前；踏雪(在雪地上行走)；把火踏灭；踏踏(马蹄声,也作蹋蹋)；踏破菜园(吃素的人,破了荤戒)；踏蹑(织布时踩踏织机', '小学', '1'),
    ('踢', 'tī', '15', '足', '左右', NULL, '踢〈动〉 用脚特别是足尖触击(打) 踢,以足蹴物。--《正字通》 这个踢”是近代的新字。；组词：踢弄(百戏技艺中以手足为主的杂技)；踢箭(北方的游戏,即南方的踢毽子)；踢飞脚(两脚相继踢起,高与头齐)；踢天弄井(上天', '小学', '1'),
    ('踩', 'cǎi', '15', '足', '左右', NULL, '踩 踩踏;脚底接触地面或物体 走,行走 踩高跷 踩水 踩 cǎi脚底接触地面或物体左脚~在凳子上。 【踩水】一种游泳形式。人直立水中,两腿交替上抬下踩,身体保持不沉,并能前行。', '小学', '1'),
    ('踪', 'zōng', '15', '足', '左右', NULL, '踪 (形声。从足,从(宗)声。本义脚印,踪迹) 同本义 草合人踪断,尘浓鸟迹深。--李白《谒老君庙》 千山鸟飞绝,万径人踪灭。--柳宗元《江雪》 访其遗踪；组词：踪尘(尘世的事情)；踪绪(踪迹,头绪)；踪响(踪纪声响)；踪辙(踪迹) 事物的痕迹 翠华一去寂无踪,玉楼歌吹,声断己随风', '小学', '1'),
    ('踱', 'duó', '16', '足', '左右', NULL, '踱 慢步行走 鲁智深离了僧房,信步踱出山门外。--《水浒全传》 又如踱来踱去;踱方步;踱走(踱步,走慢步,慢步走) 踱 duó漫步行走。', '小学', '1'),
    ('蹂', 'róu', '16', '足', '左右', NULL, '蹂 (形声。从足,柔声。本义践踏) 同本义 蹂,履也。--《广雅》 蹂,蹂践,蹋也。--《玉篇》 余骑相蹂践争项王。--《史记·项羽本纪》；组词：蹂若(蹂践、蹂蹈、践踏)；蹂蹈(践踏)；蹂踏(犹踩踏)；蹂抑(践踏压制)；蹂促(犹践踏) 欺压、侵凌；侵袭 蹂强翼弱,名', '小学', '1'),
    ('蹄', 'tí', '16', '足', '左右', NULL, '蹄〈名〉 (形声。从足,本义牛、马、猪、羊等有蹄类哺乳动物足趾前部的典型角质覆盖物,以将趾的末端几乎全部包裹住,又指有角质保护物的脚)；组词：牛蹄；马蹄；猪蹄；蹄涔(留有牛马脚迹的小池塘)；蹄洼(留有蹄迹的小水塘)；蹄道(有着兽蹄鸟迹的走道)；蹄蚤(蹄趾与脚爪)', '小学', '1'),
    ('蹈', 'dǎo', '17', '足', '左右', NULL, '蹈 (形声。从足,舀声。本义踩,踏) 同本义(往往有冒险的意味) 蹈,践也。--《说文》 蹈,履也。--《广雅》 足之蹈之。--《孟子》 蹈腾昆仑。--《淮南子·原道》。注蹑也；组词：蹈火(踩火)；蹈藉(践踏)；蹈跃(践踏奔跳)；蹈冰(踏冰) 顿足踏地 发扬蹈历之己蚤', '小学', '1'),
    ('蹋', 'tà', '17', '足', '左右', NULL, '蹋〈动〉 同踏”。践踏;踩 蹋,践也。--《说文》 蹋,履也。--《广雅·释诂一》 字亦作踏” 舞辄数十人相随,蹋地为节。--《后汉书·东夷传》 踢 王傅萨都喇以足蹋人而死', '小学', '1'),
    ('蹦', 'bèng', '18', '足', '左右', NULL, '蹦 双脚并拢跳。泛指跳跃;乱动 意想不到地或突然地出现 蹦 bèng跳这鱼还活~乱跳的呢。', '小学', '1'),
    ('蹬', 'dēng', '19', '足', '左右', NULL, '蹬 踩;踏 蹬,履也。--《广雅》 功蹬王府。--《槀长蔡湛颂》 唿喇一声蹬倒八卦炉,往外就走。--《西游记》；组词：蹬空(踏空)；蹬脱(踢开；甩脱,抛开)；蹬足(以足顿地)；蹬踏(登；蹬上高处) 穿 磴 磴,石级 马镫 梯道 蹬倚绝壁,', '小学', '1'),
    ('蹭', 'cèng', '19', '足', '左右', NULL, '蹭 (形声。从足,曾声。本义摩擦) 同本义 因擦过某物而沾上 磨蹭,行动拖拉;慢慢地走 蹭 cèng 1摩擦~破一块皮。 2因擦过去而沾上~了一身油。 3慢腾腾地行动磨~', '小学', '1'),
    ('蹲', 'dūn', '19', '足', '左右', NULL, '蹲 蹲蹲”,舞的样子 坎坎鼓我,蹲蹲舞我。--《诗·小雅·出车》 蹲 dūn 1两腿弯曲,像坐的样子,但臀部不着地。 2比喻闲居或呆着在家里~着。 【蹲点】较长时间到某个基层单位', '小学', '1'),
    ('躁', 'zào', '20', '足', '左右', NULL, '躁 (形声) 同本义 躁,疾也。--《说文》。字亦作躁。 羽杀则躁。--《考工记·矢人》。按,今字作躁。 躁者不静。--《管子·心术》 巽为躁卦。--《易·说卦》 震为决躁；组词：躁暴(暴躁；急躁)；躁妄(急躁轻率)；躁忿(急躁易怒)；躁扰(急躁好动)；躁静(急躁与宁静)；躁率(急躁轻率) 急疾；迅', '小学', '1'),
    ('躏', 'lìn', '21', '足', '左右', NULL, '躏 (形声。从足,蔺声。本义使力的碾踏) 同本义 躏玄鹤,乱昆鸡。--司马相如《上林赋》 百姓奔走相蹂躏。；组词：躏践(踩踏；践踏)；躏蹂(踩踏)；躏藉(踩踏；践踏) 欺压；伤害 太后...恐百岁后为唐宗室躏藉无死所', '小学', '1'),
    ('身', 'shēn', '7', '身', NULL, NULL, '身〈名〉 (象形。象人之形。本义身躯的总称) 同本义 身,躬也。象人之形。--《说文》。按,身的本义是人的躯干。 必有寝礼,长一身有半。--《论语·乡党》 人自项以下,踵以上', '小学', '1'),
    ('躬', 'gōng', '10', '身', '左右', NULL, '躬 (形声。从身,弓声。从身”的字多与身体有关。本义整个身体) 同本义 躬,身也。--《说文》 信圭矦守之,躬圭伯守之。--《考工记·玉人》。按,琢为人形,信直躳曲；组词：躬体(身体)；躬先士卒(身先士卒)；躬擐(身穿', '小学', '1'),
    ('躯', 'qū', '11', '身', '左右', NULL, '躯 (形声。从身,区声。本义身体) 同本义 躯,体也。--《说文》 籍柔覆温之躯。--明·刘基《卖柑者言》 赖是以食吾躯。--明·刘基《卖柑者言》；组词：躯老(躯劳', '小学', '1'),
    ('躲', 'duǒ', '13', '身', '左右', NULL, '躲 (形声。从身,朵声。1本义身。2避开,隐匿) 藏身 避开;避让 躲 duǒ隐藏;避开~雨、~债。', '小学', '1'),
    ('躺', 'tǎng', '15', '身', '左右', NULL, '躺〈动〉 (形声。从身,尚声。本义平卧) 同本义 这无耻的畜生想必是躺尸了。--清·忧患余生《邻女语》；组词：躺在床上；躺着歇歇；躺尸(詈词', '小学', '1'),
    ('车', 'chē', '4', '车', NULL, NULL, '车 (象形。甲骨文有多种写法。象车形。本义车子,陆地上有轮子的运输工具) 同本义 車,舆论之总名。夏后时奚仲所造。象形。', '小学', '1'),
    ('轧', 'zhá', '5', '车', '左右', NULL, '轧 ga 挤入;拥挤 结交 核查 象声词。如轧拉(形容物体摩擦或受压力后而发出的声音) 轧 ya (形声。从车,本义辗压)；组词：把路面轧一下 排挤,倾轧 轧gá 1.〈方〉 1挤,拥挤不要~', '小学', '1'),
    ('轨', 'guǐ', '6', '车', '左右', NULL, '轨 (形声。从车,九声。本义轨距,车两轮间的距离) 同本义 轨,车辙也。--《说文》 经涂九轨。--《考工记·匠人》。注轨,谓辙广。” 车不得方轨。--《战国策·齐策》；组词：轨距 车轮的痕迹,车辙 轨,迹也', '小学', '1'),
    ('轩', 'xuān', '7', '车', '左右', NULL, '轩 (形声。从车,干声。本义中国古代一种前顶较高而有帷幕的车子,供大夫以上乘坐) 同本义 轩,曲輈藩车。', '小学', '1'),
    ('转', 'zhuǎn', '8', '车', '左右', NULL, '转 (形声。从车,专声。转运要用车,故从车。本义转运) 同本义(通过陆路运输) 转,运也。；组词：转饷(转运粮饷)；转输(转运输送物资)；转海(海运)；转粟(运送谷物)；转漕(转运粮饷)；转毂(转运货物的车子) 回还,', '小学', '1'),
    ('轮', 'lún', '8', '车', '左右', NULL, '轮 (形声。从车,仑声。本义车轮,轮子) 同本义 轮,有辐曰轮,无辐曰辁。--《说文》。按,考工有轮人。 坎为弓轮。--《易·说卦》 輮以为轮。--《荀子·劝学》 金车玉作轮；组词：轮指(弹奏乐器的一种指法一手的几个手指接连动作,犹如车轮的转动)；轮轭(车轮和车轭)；轮崇(车轮的高度) 引申为车子 椎', '小学', '1'),
    ('软', 'ruǎn', '8', '车', '左右', NULL, '软 (形声。从车,欠声。本义柔软) 同本义。质地不硬,与硬”相对。也作輭” 軟,柔也。--《玉篇》 軟,俗輭字。--《广韵》 輭,柔也。--《广韵》 步步金阶上软舆；组词：软壁(可折叠的屏风)；软片(指裱好的书画)；软柔柔(非常柔软)；软设设(软软的)；软性(轻柔的事物', '小学', '1'),
    ('轰', 'hōng', '8', '车', '上下', NULL, '轰 (会意。从三车。本义群车行驶声) 同本义 轰,群车声也。--《说文》 轰轰殷殷。--《史记·苏秦传》；组词：轰隐(成群车队的喧闹声)；轰輵(象声词', '小学', '1'),
    ('轴', 'zhóu', '9', '车', '左右', NULL, '轴 (形声。从车,由声。本义轮轴) 同本义 轴,持轮也。--《说文》 輑谓之轴。--《方言九》 服重任,行远道,正直而固者,轴也。--《列女传·母仪》 迁于袒,用轴；组词：车轴；主轴；轴心(轮轴) 车子 字画下端便于悬挂或卷起的圆杆 把平面或立体分成对称部分的直线 轴zhóu 1.支持轮子或', '小学', '1'),
    ('轻', 'qīng', '9', '车', '左右', NULL, '轻 (形声。本义车名) 轻车 轻,轻车也。--《说文》。段玉裁注轻本车名,故字从车。引申为凡轻重之轻。” 轻车之萃。谓驰敌致师之车也。--《周礼·车仆》 使轻车锐骑冲雍门；组词：轻单( 轻(輕)qīng 1.份量小,跟"重"相对这张桌子较~', '小学', '1'),
    ('载', 'zǎi', '10', '车', '半包围', NULL, '载 年(唐虞时代用于年名) 夏曰岁,商曰祀,周曰年,唐虞曰载。--《尔雅·释天》 朕在位七十载。--《书·尧典》 汉兴,至孝文四十有余载。--《史记·文帝本纪》；组词：载祀(年) 载 记载,写在一定的册页里,有郑重的色彩 夫有勋而不废,有绩而载', '小学', '1'),
    ('轿', 'jiào', '10', '车', '左右', NULL, '轿〈名〉 (形声。从车,乔声。本义轿子) 竹舆。古代过山用的交通工具 舆轿而逾领。--《汉书·严助传》；组词：山轿(过山用的竹制舆车) 轿子 )；轿行(出租轿子的行业机构) 轿(辤)jiào轿子,由人抬着走的一种交通工具抬~', '小学', '1'),
    ('较', 'jiào', '10', '车', '左右', NULL, '较〈名〉 (形声。从车,交声。本义车箱两旁板上的横木。士大夫以上的乘车,较上饰有曲铜钩)；组词：重较(两重横木) 车箱 金薄缪龙,为舆倚较', '小学', '1'),
    ('辅', 'fǔ', '11', '车', '左右', NULL, '辅 (形声。从车,甫声。本义车旁横木。辅所以益辐,使之能重载) 同本义 輔,人颊车也。--《说文》。按,当作木夹车也。 若车之有辅。--《吕氏春秋·权勋》 辅,小木。--《尔雅》；组词：辅材(制作车轮外旁夹毂的直木材料) 助手 夫将者国之辅也', '小学', '1'),
    ('辆', 'liàng', '11', '车', '左右', NULL, '辆 (形声。从车,两声。古代的车一般有两个轮子,故车一乘即称一两,后来写作辆”,总称为车辆”) 用于车,指单个数 指鞋一双 一辆小鞋儿', '小学', '1'),
    ('辈', 'bèi', '12', '车', '上下', NULL, '辈 (形声。从车,非声。本义百辆车) 同本义 辈,若军发车,百辆为辈。--《说文》 也指车列,车队 稠人广众,荐宠下辈。(下车来推崇赞扬他们。)--《史记》 世;辈分 古人不可见；组词：前辈；后辈；长辈；晚辈 某类人 若辈得无苦贫乎?--明·崔铣《记王忠肃公翱三事》 汝辈所惜罗程艺耳', '小学', '1'),
    ('辉', 'huī', '12', '车', '左右', NULL, '辉 (形声。从光。军声。本义光;光辉) 同本义 煇,光也。--《说文》 庭燎有煇。--《诗·小雅·庭燎》 故德煇动于内。--《礼记·乐记》 观国之煇。--《汉书·韦玄成传》；组词：辉辉(光耀的样子)；辉烂(光辉灿烂)；辉风(光辉的风范)；辉容(光辉的仪容) 晨光 朝旦为辉,日中为光', '小学', '1'),
    ('辐', 'fú', '13', '车', '左右', NULL, '辐 (形声。从车,畐声。畐”有腹满”义(参福”字条),而辐”为圆形,与人腹满之形相类,因而畐”在字中亦兼有表义作用。本义辐条。插入轮毂以支撑轮圈的细条)；组词：轮辐；辐集(聚集)；辐聚(聚集) 聚集如辐 辐 fú 1.车轮上一条一条的直条,从轮边连结到轮的中心', '小学', '1'),
    ('辑', 'jí', '13', '车', '左右', NULL, '辑 (形声。本义车箱) 同本义。泛指车子 辑,车和辑也。--《说文》 辑,合材为车,咸相得谓之辑。--《六书故》 推于御也,齐辑乎辔衔之际。--《列子·汤问》 整套书籍；组词：辑辑(群集的样子) 敛,拖着不使脱落 望于山川,遍于群神,辑五瑞', '小学', '1'),
    ('输', 'shū', '13', '车', '左右', NULL, '输 (形声。从车,俞声。本义转运,运送) 同本义 输,委输也。--《说文》 运所有,输所无。--《淮南子·泛南训》 输积聚以贷。--《左传·襄公九年》 春申道缀基毕输；组词：输供(输送供给)；输将(运送)；输场(唐代转运物资的货场)；输发(输送和调发粮草、军队)；输转(转运)；输将(运送,输运', '小学', '1'),
    ('辕', 'yuán', '14', '车', '左右', NULL, '辕 (形声。从车,袁声。本义车辕子,车前驾牲口的直木) 同本义 辕,辀也。--《说文》。按,大车、柏车、羊车皆左右两木,曰辕,其形直。一牛在辕间;田车、兵车、乘车皆居中；组词：辕轭(车前驾牲口的直木和套在牲口脖子上的曲木', '小学', '1'),
    ('辖', 'xiá', '14', '车', '左右', NULL, '辖 (形声。从车,害声。本义大车轴头上穿着的小铁棍,可以管住轮子使不脱落) 同本义 辖,键也。；组词：辖押(管辖看押)；辖下(统辖之下)；省辖市；直辖(直接管辖) 卡,夹 为左右所辖,进退不得', '小学', '1'),
    ('辙', 'zhé', '16', '车', '左中右', NULL, '辙 (形声。从车,徹省声。本义车迹,车轮碾过的痕迹) 同本义 下,视其辙;登,轼而望之。--《左传·庄公十年》 晓驾炭车辗冰辙。--《卖炭翁》 车子 会使辙交驰,北邀当国去相见；组词：辙印(车子行驶的痕迹)；辙迹(车子行驶的痕迹) 道路 欲驾巾车归去,有豺狼当辙', '小学', '1'),
    ('辛', 'xīn', '7', '辛', '上下', NULL, '辛〈名〉 (象形。据甲骨文,像古代刑刀。本义大罪) 同本义 辛,大罪也。--《说文》。段注辛痛泣出,罪人之象。凡辠(罪)、宰、辜、辭皆从辛者由此。” 辛所以煞伤之也', '小学', '1'),
    ('辜', 'gū', '12', '辛', '上下', NULL, '辜 (形声。从辛,古声。辛”,是受刑的意思。本义罪行) 同本义 辜,罪也。--《说文》。段注辜本非常重罪,引申之凡有罪者皆曰辜。” 民之无辜。--《诗·小雅·正月》 无罪无辜；组词：死有余辜；无辜 灾难,祸害 害遍生民,辜及朽骨', '小学', '1'),
    ('辞', 'cí', '13', '辛', '左右', NULL, '辞 (会意。本义诉讼,打官司) 同本义 辞,讼也。--《说文》。按,分争辩讼谓之辞。 善于辞案条教。--《后汉书·周纡传》。注辞案犹今案牍也。” 皇帝请问下民,鳏寡有辞于苗', '小学', '1'),
    ('辟', 'pì', '13', '辛', '左右', NULL, '辟 (会意。小篆字形,从卩,从辛,从口。卩”,音榞??,,甲骨文象人曲膝而跪的样子。辛”,甲骨文象古代酷刑用的一种刀具。本义法律,法度)；组词：复辟 古称官吏 厥辟不辟', '小学', '1'),
    ('辣', 'là', '14', '辛', '左右', NULL, '辣 (形声。从辛,剌省声。本义辛味) 同本义。姜、蒜、辣椒等带刺激性的味道 辢,辛也。--《广雅》 辛甚曰辣。--《通俗文》 江南曰辣,中国曰辛。--《声类》；组词：酸甜苦辣；辣菜根子(辣菜的根很辣,喻非常泼辣)；辣拐子(辣手的家伙', '小学', '1'),
    ('辨', 'biàn', '16', '辛', '左中右', NULL, '辨 (形声。从刀,辡(榓溃?? )声。本义判别,区分,辨别) 同本义 辨,判也。--《说文》 辨,别也。--《小尔雅》 辨方正位。--《周礼·天官》 辨是与非；组词：明辨是非；辨白(分辨清楚)；辨色(辨别物色) 通辩”', '小学', '1'),
    ('辩', 'biàn', '16', '辛', '左中右', NULL, '辩 (形声。从言,辡(榓溃?? )声。本义辩论,申辩) 同本义 辩,治也。--《说文》 辩其狱讼。--《周礼·乡士》 分争辩讼。--《礼记·曲礼》 辩者言之信；组词：辩证；辩日(古代传说辩论太阳离地球远近的故事) 分别,辨别', '小学', '1'),
    ('辫', 'biàn', '17', '辛', '左中右', NULL, '辫 交织,编结。也作编” 辮,交也。--《说文》 织绳曰辮。--《通俗文》 女子头发辫而不垂。--《梁书·西北诸戎传》；组词：辫发(将头发编成辫子；用作满族代称)；辫髻(编发成辫,再盘成髻) 辫 发辫', '小学', '1'),
    ('辰', 'chén', '7', '辰', NULL, NULL, '辰 (象形。金文字形,是蛤蚌壳之类软体动物的形象,蜃”的本字◇经假借而产生了其他用法。本义;蛤蚌之类的软体动物)', '小学', '1'),
    ('辱', 'rǔ', '10', '辰', NULL, NULL, '辱 (会意。甲骨文字形,是辰”下加脚(止)或加手(又,寸)的形象。1本义耕作。辰”是蜃”的本字,古代以蜃为农具进行耕作。这个意义后来写作耨”(遮??))；组词：奇耻大辱；荣辱；羞辱；忍辱负重；蒙受屈膝之辱；辱害(耻辱和损害)；辱残(受耻辱和残害) 辱 使...受辱；侮辱 南辱于楚', '小学', '1'),
    ('边', 'biān', '5', '辶', '半包围', NULL, '边 (形声。从辵,舩声。本义山崖的边缘) 同本义 边,行垂崖也。--《说文》 边,垂也。--《尔雅》 白帝城边足风波,瞿塘五月谁敢过。--唐·李白《荆州歌》；组词：崖边；岸边；水池边；边侧(边沿,旁侧)；边涯(边际；边缘) 边境 其在边邑', '小学', '1'),
    ('辽', 'liáo', '5', '辶', '半包围', NULL, '辽 (形声。从辵,尞声。本义遥远) 同本义 辽,远也。--《说文》 山修远其辽辽兮。--《楚辞·九叹·忧苦》。注辽辽,远貌。” 楚师辽远,粮食将尽,必将速归；组词：辽绝(远隔)；辽险(遥远险要)；辽天(远天)；辽阻(辽远阻隔)；辽荒(荒凉遥远) 开阔 江山辽落,居然有万里之势', '小学', '1'),
    ('达', 'dá', '6', '辶', '半包围', NULL, '达 (形声。从辵,羍声。本义道路畅通) 同本义。泛指畅通 达,行不相遇也。--《说文》 达,通也。--《广雅》 左右达为夹室,所以相隔。--《礼记·内则》 寡人其达王于甬句东；组词：四通八达；达越(疏通瑟底之孔使其声迟重)；达乡(相对而畅达的窗户)', '小学', '1'),
    ('迁', 'qiān', '6', '辶', '半包围', NULL, '迁 (形声。从辵,辵”表移动。形声字声旁有时有表意作用,此即一例。本义向高处迁移) 同本义 迁,登也。；组词：迁莺(指迁升飞翔的黄莺', '小学', '1'),
    ('迂', 'yū', '6', '辶', '半包围', NULL, '迂〈形〉 (形声。从辵,于声。本义曲折,绕远) 同本义 迂,僻也。--《说文》。按,僻远也。 迂乃心。--《书·盘庚》。传僻也。” 子之迂也。--《论语》。皇疏远也；组词：迂直(虽迂曲却是最直接有利的)；迂折(迂回曲折)；迂弘(深远宏大)；迂邈(遥远)；迂路(绕路)；迂深 迂yū 1.曲折,', '小学', '1'),
    ('迄', 'qì', '6', '辶', '半包围', NULL, '迄〈动〉 (形声。从辵,乞声。本义到;至) 同本义 迄,至也。--《说文新附》 以迄于今。--《诗·大雅·生民》 迄于天下。--《国语·周语下》 吴获迄古；组词：迄至(至,到) 迄 〈副〉 竟,毕竟,终究 迄无成功', '小学', '1'),
    ('迅', 'xùn', '6', '辶', '半包围', NULL, '迅〈形〉 迅,疾也。--《说文》。按,疾走也。 狼绝有力迅。--《尔雅》 藨者若鹿迅走。--《周书·王会》 迅雷风烈。--《论语》 年往迅劲矢；组词：迅指(巡指间', '小学', '1'),
    ('过', 'guò', '6', '辶', '半包围', NULL, '过 古国名 处浇于过,处豷于戈。--《左传·襄公四年》 姓,过国之后 过 (形声。从辵,表示与行走有关,唈声。本义走过,经过)；组词：过江；过马路；从这条街上过；从他门前过；路过(途中经过)；过翼(经过的飞鸟)；过宾( 过(過)guò 1.经历,经历某个', '小学', '1'),
    ('迈', 'mài', '6', '辶', '半包围', NULL, '迈 (形声。从辵 夲义远行) 同本义 丙子九月,辞家西迈。--钱谦益《徐霞客传》 我日斯迈,而月斯征。；组词：迈过门槛；迈腿；迈步(举脚向前走；跨出步子)；迈开(向前跨出) 超过,跨越 三王可迈,五帝可越', '小学', '1'),
    ('迎', 'yíng', '7', '辶', '半包围', NULL, '迎 (形声。从辵。本义遇,相逢) 同本义 迎,逢也。--《说文》。段玉裁注夆,悟也;逢,遇也,其理一也。” 以迎岁于东郊。--《淮南子·时则》。注逆春也。” 迎日推策；组词：迎霜(遇霜) 迎接；欢迎 冕而亲迎', '小学', '1'),
    ('运', 'yùn', '7', '辶', '半包围', NULL, '运 (会意。从辵,军声。本义运行;运转;转动) 同本义 運,移徙也。--《说文》 日、月运行。--《易·系辞》 日运为躔,月运为逡。--《方言》。注犹行也。” 是鸟也,海运；组词：运衡(指运转的玉衡星)；运玑(谓运转测天之器', '小学', '1'),
    ('近', 'jìn', '7', '辶', '半包围', NULL, '近 (形声。从辵,表示与行走有关,斤声。本义走近,接近) 同本义 近,附也。--《说文》 为其近于道也。--《礼记·祭义》 小大近丧。--《诗·大雅·荡》 吾入关,秋毫不敢有所近；组词：逼近(靠近；接近)；挨近；近傍(接近；靠近)；近晚(傍晚)；近火(靠近火) 引申追求,希求 为近利市三倍', '小学', '1'),
    ('返', 'fǎn', '7', '辶', '半包围', NULL, '返〈动〉 (形声。从辵,反声。字本作反”。本义回归,返回) 同本义 返,还也。--《说文》 返,归也。--《广雅》 祖伊返。--《书·西伯勘黎》 黄鹤一去不复返,白云千载空悠悠；组词：返命(办完事情后,回来复命)；返书(回信)；返棹(船只返回) 归还 其子长而返其璧', '小学', '1'),
    ('还', 'hái', '7', '辶', '半包围', NULL, '还 huan (形声。从辵(表示与行走有关),瞏声。本义返回) 同本义 还,復也。--《说文》 还,返也。--《尔雅·释言》 还而不入。--《诗·小雅·何人斯》 吾其还也', '小学', '1'),
    ('这', 'zhè', '7', '辶', '半包围', NULL, '这 (形声。从辵,言声。本义迎) 此,指目前的或较近的或刚刚提到的人、物、事或想法 为报江南二三日,这回应见雪中人。--卢仝《送好法师归江南诗》；组词：这向(这些日子)；这厢(这边；这里)；这的(这个；这里)；这壁(这里；这边)；这厮(这个奴才,这个家伙', '小学', '1'),
    ('进', 'jìn', '7', '辶', '半包围', NULL, '进 (会意。甲骨文字形,上面是隹”,象小鸟形,下面是止”(趾)。鸟脚只能前进不能后退,故用以表示前进。本义前进,与退”相对)', '小学', '1'),
    ('远', 'yuǎn', '7', '辶', '半包围', NULL, '远 (形声。从辵,袁声。本义走路走得长) 同本义 远,辽也。--《说文》 远,遐也。--《尔雅》 屏之远方。--《礼记·王制》。注九州之外也。” 柔远人也；组词：远(遠)yuǎn 1.空间或时间的距离长,跟"近"相对~方', '小学', '1'),
    ('违', 'wéi', '7', '辶', '半包围', NULL, '违 (形声。从辵,韦声。本义离开;背离) 同本义 违,离也。--《说文》 违,远也。--《尔雅》 中心有违。--《诗·邶风·谷风》。传离也。” 薄违农父；组词：违别(离别)；违离(离别；分离；背离)；违恋(依依惜别)；违阔(离别；阔别)；违署(离开官署', '小学', '1'),
    ('连', 'lián', '7', '辶', '半包围', NULL, '连 (会意。从辵,从车。本义人拉的车) 同本义 遙,负车也。--《说文》。段注连即古文輦也。 连车组輓。--《周礼·故书巾车》 与其輂连。--《周礼·乡师》 行服连轺辇者；组词：连亲(连姻)；连昏(连婚', '小学', '1'),
    ('迟', 'chí', '7', '辶', '半包围', NULL, '迟 (形声。本义慢慢走) 同本义。泛指慢 迟,徐行也。--《说文》 迟,缓也。--《广雅》 废彻不迟。--《诗·小雅·楚茨》 行道迟迟。--《诗·邶风·谷风》 迟归有待；组词：迟徐(缓慢)；迟滞(缓慢阻滞) 迟钝；反应慢,不灵敏 料事同而迟速不同', '小学', '1'),
    ('迫', 'pò', '8', '辶', '半包围', NULL, '迫 (形声。从辵,白声。本义逼近) 同本义 迫,近也。--《说文》 迫,逼也,近也。--《广韵》 望崦嵫而勿迫。--《离骚》。注附也。” 而侮所迫之国者,可亡也；组词：迫措(犹逼近) 硬逼,逼迫 贾家庄几为巡徼所陵迫死', '小学', '1'),
    ('述', 'shù', '8', '辶', '半包围', NULL, '述 (形声。从辵,术声。本义遵循) 同本义 述,循也。--《说文》 报我不述。--《诗·邶风·日月》 遂述命曰。--《仪礼·少牢礼》 述大禹之戒以作歌。--《书·五子之歌》；组词：述遵(遵循)；述旧(遵行旧规)；述祖(遵循祖训) 陈述,记叙 识礼乐之文者能述', '小学', '1'),
    ('迷', 'mí', '9', '辶', '半包围', NULL, '迷 (形声。从辵,米声。本义迷路;分辨不清) 同本义 迷,惑也。--《说文》 烈风雷雨弗迷。--《书·舜典》 凡夫失其所欲之路,而妄行之,则为迷', '小学', '1'),
    ('迹', 'jì', '9', '辶', '半包围', NULL, '迹 同本义 赵主父令工施钩梯而缘播吾(山名),刻疏人迹其上。--《韩非子·外储说左上》 又如浪迹天涯;人迹(人的足迹);人急至;迹蹈(重复走过的路);迹状(行迹)；组词：浪迹天涯；人迹(人的足迹)；人急至；迹蹈(重复走过的路)；迹状(行迹)；迹响(踪纪声响) 留下的印子 蟆入草间,蹑迹披求', '小学', '1'),
    ('追', 'zhuī', '9', '辶', '半包围', NULL, '追 (本义追赶) 同本义(使追赶对象回来) 追,逐也。--《说文》 以比追胥。--《周礼·小司徒》。注逐寇也。” 公追戎于济西。--《左传·庄公十八年》 驰车充国者,追寇之马也；组词：穷寇勿 追zhuī 1.赶,紧跟~赶', '小学', '1'),
    ('退', 'tuì', '9', '辶', '半包围', NULL, '退〈动〉 (会意。小篆字形。从彳,从日,从攵。彳,小步。攵,足的反写。本义向后走,后退)；组词：退到院子里；他往后退了几步；退缩(后退,回缩)；退生(后退以求生)；退厅(退堂', '小学', '1'),
    ('送', 'sòng', '9', '辶', '半包围', NULL, '送 (会意。小篆字形) 同本义 送,遣也。--《说文》。 送迎无礼。--《荀子·富国》。注致女也。”；组词：送嫁(送亲)；送娘(方言', '小学', '1'),
    ('适', 'shì', '9', '辶', '半包围', NULL, '适 (形声。从辵,啻声。本义往,到) 同本义 適,之也。--《说文》。段曰往自发动言之,适自所到言之。” 十一月,沛公引兵之薛。--《汉书·高帝纪》 辍耕之垄上；组词：无所适从；何适；适秦；适远(到 适(適)shì 1.相合,妥当,切合~合', '小学', '1'),
    ('逃', 'táo', '9', '辶', '半包围', NULL, '逃〈动〉 (形声。从辵,兆声。本义逃走,逃跑) 同本义 逃,亡也。--《说文》 许由逃之。--《庄子·外物》 恒侯体痛,使人索扁鹊,已逃秦矣。--《韩非子·喻老》 处于逃；组词：逃闪(逃跑藏匿)；逃越(逃走)；逃生子(逃妾所生之子)；逃犯(逃跑的犯人)；逃军(军队主将抛下军队独自逃走；逃兵) 逃避', '小学', '1'),
    ('逆', 'nì', '9', '辶', '半包围', NULL, '逆〈动〉 (形声。从辵,屰声。本义迎,迎接,迎着) 同本义 逆,迎也。关东曰逆,关西曰迎。；组词：逆战(迎战)；逆厘(迎福纳吉)；逆劳(迎劳)；逆暑(迎夏', '小学', '1'),
    ('选', 'xuǎn', '9', '辶', '半包围', NULL, '选 (形声。从辵,巽声。本义遣送;放遂) 同本义 选,遣也。--《说文》 其母曰弗去,惧选。”癸卯,针适晋。--《左传·昭公元年》 假借为柬”。挑选,选择 选,一曰择也', '小学', '1'),
    ('逊', 'xùn', '9', '辶', '半包围', NULL, '逊 (形声。从辵,孙声。本义逃遁) 同本义 遜,遁也。--《说文》 吾家耄逊于荒。--《书·微子》 是以耆儒硕老,抱其书而远逊。--汉·扬雄《剧秦美新》；组词：逊郊(天子逃遁于荒野) 辞让；退让 将逊于位', '小学', '1'),
    ('透', 'tòu', '10', '辶', '半包围', NULL, '透〈动〉 (形声。从辵,秀声。本义跳,跳跃) 同本义 透,跳也。--《说文新附》 妃知不免,乃透井死。--《南史·后妃传下》 或群跳而电透。--《文选·王廷寿王孙赋》 事穷奔透；组词：透索(跳索的游戏)；透掷(跳跃)；透水(跳水)；透井(跳井) 穿过,透过 渐渐透出', '小学', '1'),
    ('逐', 'zhú', '10', '辶', '半包围', NULL, '逐 (会意。甲骨文字形,象人(脚)在豕等动物后面追逐的样子。止”小篆改从辵。本义追赶) 同本义 (含有使追赶对象离开或消灭的意思) 逐,追也。；组词：逐逐(追逐；急于得利)；逐驾(追随尊驾；跟随君主左右)；逐 逐zhú 1.赶走,强迫离开驱~', '小学', '1'),
    ('递', 'dì', '10', '辶', '半包围', NULL, '递 (形声。从辵,虒声。本义轮流;交替) 同本义 递,更易也。--《说文》 国之递甚也。--《战国策·齐策六》 二八侍宿射递代些。--《楚辞·招魂》 诈术递用；组词：递嬗(不断地更迭、变化)；递代(互相替换)；递衣(轮流换穿同一件衣服)；递兴(交替兴起)；递迁(更易变化) 传；传送 递', '小学', '1'),
    ('途', 'tú', '10', '辶', '半包围', NULL, '途〈名〉 (形声。从辵,余声。本义道路) 同本义 途,道也。--《广韵》 徐亦训道。字古借涂,后变作途。又作塼。--朱骏声《说文通训定声》 堂途谓之陈。又,路,旅途也', '小学', '1'),
    ('逗', 'dòu', '10', '辶', '半包围', NULL, '逗 (形声。从辵,豆声。本义止住,停留) 同本义 逗,止也。--《说文》 廷尉奏恢逗桡。当斩。--《汉书·韩安国传》 逗留不进。--《汉书·匈奴传》 逗华阴之湍渚；组词：逗延(逗留；停留)；逗宿(留宿)；赶,趁 临,到 透入 撩拨；调戏 招引 透露；显露 逗 dòu 1哄孩子玩', '小学', '1'),
    ('通', 'tōng', '10', '辶', '半包围', NULL, '通〈动〉 (形声。从辵,甬声。本义没有堵塞,可以通过) 同本义 通,达也。--《说文》 往来不穷谓之通。--《易·系辞》 推而行之谓之通。 坎为通。--《易·说卦》 道远难通；组词：通衢大道(四通八达的大道,指交通要道)；通漕(直通水运)；通塞(指境遇的顺利与滞涩)；通水(通水运；能行船的地域)；通畅', '小学', '1'),
    ('逛', 'guàng', '10', '辶', '半包围', NULL, '逛〈动〉 外出散步;闲游;游览 平生最喜游山逛水。--宗璞《西湖漫笔》 又如逛庙(赶庙会);逛厂(指逛游北京琉璃厂一带集市);逛膀子(闲游);逛景(游览景致) 逛guàng闲玩；组词：逛庙(赶庙会)；逛厂(指逛游北京琉璃厂一带集市)；逛膀子(闲游)；逛景(游览景致) 逛guàng闲玩,游览~大街', '小学', '1'),
    ('逝', 'shì', '10', '辶', '半包围', NULL, '逝 (形声。从辵,折声。本义去;往) 同本义 逝,往也。--《说文》 逝,行也。--《广雅》 谷旦于逝。--《诗·陈风·东门之枌》 君子可逝也。--《论语·子罕》；组词：逝者如斯夫', '小学', '1'),
    ('逞', 'chěng', '10', '辶', '半包围', NULL, '逞 (形声。从辵,呈声。本义通,通达) 同本义 逞,通也。--《说文》。傅云龙古语考补正通,达也,是其本义。通有行义,无疾义。” 快意,实现,使称心 今民馁而君逞欲；组词：逞志(逐心如意,以求快意)；逞欲(逐心如意,以求得到欲望的满足)；逞心(快意；称心) 炫耀 放纵,恣肆 逞 chěng', '小学', '1'),
    ('速', 'sù', '10', '辶', '半包围', NULL, '速 (形声。从辵,束声。本义速度快) 同本义 速,疾也。--《说文》 不微至,无以为戚速也。--《周礼·考工记·总目》 字亦作遬” 轻则僩遬。--《荀子·议兵》 则莫能以速中；组词：收效甚速；速速(非常快速)；速捷(快速敏捷)；速战速决(用最快的速度发动战争,以达到预期的目的 速sù 1.快,很快快~', '小学', '1'),
    ('造', 'zào', '10', '辶', '半包围', NULL, '造 (形声。从辵,告声。本义到;往某地去) 同本义 造,就也。--《说文》 咸造勿亵在王庭。--《书·盘庚》 凡四方之宾 客造焉。--《周礼·司门》 造于西阶下；组词：造劫历世(佛教语', '小学', '1'),
    ('逢', 'féng', '10', '辶', '半包围', NULL, '逢〈动〉 (形声。从辵,表示与行走有关。夆声。本义遭逢,遇见) 同本义 逢,遇也。--《说文》 魑魅罔两,莫能逢之。--《左传·宣公三年》 而亲以逢殆；组词：逢辰(遇到好的时刻)；逢会(遇到时机；相会,会合)；逢场(遇到或到达某场合)；逢晤(当面相遇) 迎,迎接 道而得神,是谓', '小学', '1'),
    ('逮', 'dǎi', '11', '辶', '半包围', NULL, '逮 (形声。从辵,隶声。本义赶上;及;到) 同本义 逮,唐逮及也。--《说文》。按,逮者,行相及也。古曰唐逮。 逮于袁娄而与之盟。--《公羊传·成公二年》 群后之逮在下；组词：逮及(达到,到了 逮 dǎi捉~鸟', '小学', '1'),
    ('逸', 'yì', '11', '辶', '半包围', NULL, '逸 (会意。从辵兔。兔子善于奔逃。本义逃跑) 同本义 逸,失也。从辵兔,兔谩訑善逃也。--《说文》 随侯逸。--《左传·桓公八年》。注逸,逃也。” 马逸不能止；组词：逸犯(逃犯)；逸亡(逃亡)；逸窜(逃窜)；逸盗(在逃的盗匪)；逸禽(逃逸之鸟)；逸马(奔逃的马)；逸匪(指在逃的匪徒)', '小学', '1'),
    ('逻', 'luó', '11', '辶', '半包围', NULL, '逻 (形声。从辵,表示与行走有关,罗声。本义巡察,巡逻) 同本义 逻者数十骑。--宋·文天祥《指南录后序》；组词：逻伺(巡罗侦察)；逻弋(巡逻)；逻守(巡逻守卫)；逻役(巡逻的差役)；逻捕(巡察搜捕) 遮拦 蛛蝥结网工遮逻', '小学', '1'),
    ('逼', 'bī', '12', '辶', '半包围', NULL, '逼 (形声。从辵),畐(鉦??)声。本义接近,靠近) 同本义(仅表示空间距离的接近、靠近) 逼,近也。；组词：逼水(迫近水边)；逼曙(天快亮的时候)；逼战(近战) 逼迫,即紧紧催促 又荆州之民附操者,逼兵势耳', '小学', '1'),
    ('逾', 'yú', '12', '辶', '半包围', NULL, '逾 (形声。从辵,俞声。本义越过,经过) 同本义 又如逾迈(走过;时光易逝);逾墙钻穴(指男女偷情;跳墙钻洞);逾墉(越过城墙);逾墙(越过矮墙);逾假不归(即假期已满而未归营)；组词：逾迈(走过；时光易逝)；逾墙钻穴(指男女偷情；跳墙钻洞)；逾墉(越过城墙)；逾墙(越过矮墙)；逾假不归(即假期已满而未归', '小学', '1'),
    ('遂', 'suí', '12', '辶', '半包围', NULL, '遂 (形声。从辵 同本义 遂,亡也。--《说文》 行,往 遂,往也。--《广雅·释诂一》 不能遂。--《易·大壮》 遂贤良。--《礼记·月令》；组词：遂行(通行；顺适地进行) 称心如意；使得到满足 他年如遂隐,五老是知音', '小学', '1'),
    ('遇', 'yù', '12', '辶', '半包围', NULL, '遇 (形声。从辵,禺声。本义相逢,不期而会) 同本义 遇,逢也。--《说文》 遇主于巷。--《易·暌》。崔注遇者,不期而会。” 乃遇汝鸠汝方。--《书·序》 诸侯未及期相见曰遇；组词：遇庭(和父母相见)；遇人不淑(指女子嫁了不好的丈夫)；遇缺补正(指遇到员额出缺时,得补任为官) 遭受 遇人之艰难矣', '小学', '1'),
    ('遍', 'biàn', '12', '辶', '半包围', NULL, '遍 (形声。本义走遍) 同本义 徧,徧也。--《说文》 徧于群神。--《虞书》 凡永嘉山水,游历殆遍。--宋·沈括《梦溪笔谈》 遍衙门告不成；组词：满山遍野；遍窥(周览,尽见)；遍体(浑身,全身) 遍 从头到尾经历一次 遍 biàn 1普遍；全部满山~野', '小学', '1'),
    ('遏', 'è', '12', '辶', '半包围', NULL, '遏 (形声。从辵,曷声。本义抑制;阻止,阻拦) 阻止 遏,止也。--《尔雅·释诂》 君子以遏恶扬善。--《易·大有卦》 夏王率遏众力。--《书·汤誓》 胜殷遏刘；组词：遏捺(按捺,遏止)；遏密(指皇帝死后禁绝演奏作乐)；遏讼(阻止诉讼)；遏塞(阻塞)；遏刘(抑制暴乱,阻止杀伐) 断绝 四', '小学', '1'),
    ('道', 'dào', '12', '辶', '半包围', NULL, '道 (形声。从辵,首声。本义供行走的道路) 同本义 道,所行道也。--《说文》 一达谓之道。--《尔雅》 道坦坦。--《易·履》 百夫有洫,洫上有途,千夫有浍,浍上有道,万夫有川；组词：大道,问道于盲；要道；人行', '小学', '1'),
    ('遗', 'yí', '12', '辶', '半包围', NULL, '遗 wei 给予;馈赠 相遗以水。--《韩非子·五蠹》 欲厚遗之。--《史记·魏公子列传》 置币遗单于。--《汉书·李广苏建传》 裘葛之遗。--唐·魏征《谏太宗十思疏》；组词：遗贼(给予戕害；遭害)；遗赂(赠送财物)；遗劳(馈赠；犒劳)；遗酌(济助)；遗送(赠送)；遗金(赠送金钱) 送交；交付', '小学', '1'),
    ('遣', 'qiǎn', '13', '辶', '半包围', NULL, '遣〈动〉 同本义 遣,纵也。--《说文》 遣之日读诔。--《周礼·太史》。注谓祖庙之庭,大奠将行时也。” 大丧饰遣车。--《周礼·巾车》 书遣于策；组词：遣俘(遣还俘虏)；遣还(犹遣返) 派', '小学', '1'),
    ('遥', 'yáo', '13', '辶', '半包围', NULL, '遥 (形声。从辵 同本义 遥,远也。--《广雅》 遥,远也。梁楚曰遥。--《方言六》 遥遥,远也。--《广雅》 倚沼畦瀛兮遥望博。--《楚辞·招魂》。注遥,远也。” 可登而路遥；组词：遥天(远天)；遥祭(向着远方而祭祀)；遥领(间接治理,由远处控制监督)；遥遥华胄(指远古时候的名门后裔)；遥心(心向远方', '小学', '1'),
    ('遭', 'zāo', '14', '辶', '半包围', NULL, '遭 (形声。从辵,曹声。本义遇见,碰到) 同本义(多指碰到不幸的事) 遭,遇也。--《说文》 遭先生于道。--《礼记·曲礼》。疏逢也。” 未既龀而遭之。--《国语·郑语》。注遇也；组词：遭伤(遇死；被害)；遭变(遇到变故)；遭坏(遇到山崖或墙壁等的崩塌)；遭险(遇到危险) 受到；遭受 轩凡四遭火', '小学', '1'),
    ('遮', 'zhē', '14', '辶', '半包围', NULL, '遮 (形声。从辵,庶声。本义阻挡;拦阻) 同本义(使不通过,使中途停止) 陈王出,遮道而呼涉。；组词：遮影(遮挡；遮蔽)；遮止(阻止,拦阻)；遮迭(遮挡；招架)；遮路(阻塞道路)；遮遏(阻止；阻挡) 掩蔽 千呼万唤始出来,', '小学', '1'),
    ('遵', 'zūn', '15', '辶', '半包围', NULL, '遵 (形声。从辵,尊声。本义顺着,沿着) 同本义 遵,循也。--《说文》 遵大路兮。--《诗·郑风·遵大路》 女执懿筐,遵彼微行。--《诗·豳风·七月》 遵四时以叹逝；组词：遵依(遵照)；遵巡(顺着；沿着)；遵序(依次,顺着次序)；遵时(顺应时势)；遵海(沿着海岸)；遵陆(沿着陆路) 遵', '小学', '1'),
    ('避', 'bì', '16', '辶', '半包围', NULL, '避 (形声。从辵),辟声。本义躲开,回避) 同本义 避,回也。--《说文》 避,去也。--《苍颉篇》 无乃实有所避。--《国语·周语》 自云先世避秦时乱；组词：避风雨；避秦(秦时苛政扰民,人民纷纷逃避而隐居)；避言(言语谨慎,避免说错话)；避宅(到处躲藏,不住在家里) 离去 左右', '小学', '1'),
    ('邀', 'yāo', '16', '辶', '半包围', NULL, '邀 (形声。从辵,敫声。本义迎候) 同本义 邀相见。--唐·白居易《琵琶行(并序)》 邀我至田家。--唐·孟浩然《过故人庄》 北邀当国者；组词：邀接(迎接)；邀迓(迎请)；邀迎(迎合) 逢,遇到 邀殊宠,一枝已傍日边红', '小学', '1'),
    ('邑', 'yì', '7', '邑', '上下', NULL, '邑 (会意。甲骨文字形。上为囗,表疆域,下为跪着的人形,表人口∠起来表城邑。邑”是汉字的一个部首,变体为右耳旁。从邑”的字多和地名、邦郡有关。本义国) 古代称侯国为邑 邑,国也；组词：敝邑(对本国的谦称) 国都,京城 邑外谓之郊', '小学', '1'),
    ('邓', 'dèng', '4', '阝', '左右', NULL, '邓 古国名 邓,曼姓之国。今属南阳。从邑,登声。--《说文》 在今河南省邓县。公元前678年为楚所灭 邓侯吾离来朝。--《春秋·桓公七年》 申吕应邓。--《国语·郑语》 袭楚至邓', '小学', '1'),
    ('邢', 'xíng', '6', '阝', '左右', NULL, '邢 古国名 姓 邢xíng姓。 邢gěng 1.古地名。故地在今山西省河津县境。', '小学', '1'),
    ('那', 'nà', '6', '阝', NULL, NULL, '那〈代〉 (形声。小篆字形,从邑,冄声。邑与地名或行政区域有关◇省作那”。1本义国名。《说文》西夷国。”2指示代词。特指某个人、某个时间、某个地方或某个事物。 不一定是远指之词；组词：那昝(那咱', '小学', '1'),
    ('邦', 'bāng', '6', '阝', '左右', NULL, '邦 (形声。从邑,丰声。古文从之、从田,会意。与封字从之、从土同意。本义古代诸侯的封国、国家)', '小学', '1'),
    ('邪', 'xié', '6', '阝', '左右', NULL, '邪 xie (形声。从邑,牙声。本义琅邪郡。字亦作琊) 赤芾在股,邪幅在下。--《诗·小雅·采菽》 方直不曲谓之正,反正为邪。--《贾子道术》 竹林,前正而后有枉者谓之邪道；组词：邪靡(倾斜披靡的样子)；邪睨(斜视)；邪绝(斜行度越) 不正当,不正派 虽有奇邪而不治者', '小学', '1'),
    ('邮', 'yóu', '7', '阝', '左右', NULL, '邮 (会意。从邑垂。垂,边郵;邑,城邑。邮”,从邑,由声。本义古地名。) 同本义 邮,左冯翊高陵,从邑,由声。；组词：邮吏(驿战管邮递的小官)；邮馆(设在驿站的旅店)；邮驿(古时办理传送公务信件的地方) 指传送文书的人 殷洪乔不为致书邮', '小学', '1'),
    ('邻', 'lín', '7', '阝', '左右', NULL, '邻 (形声。从邑,粦声。从邑”,表示与行政区域有关。本义古代的一种居民组织。五家为邻) 周朝地方基层组织的户口单位 邻,五家为邻。；组词：邻伍(古制一邻有五家,五家为伍,故称邻伍)；邻里 相连接的家户', '小学', '1'),
    ('郁', 'yù', '8', '阝', '左右', NULL, '郁 郁夷 郁,右扶风郁夷也。从邑,有声。--《说文》 古地名『置县。在今陕西省陇县西 物实无中核者谓之郁 物实无中核者谓之郁,无刀斧之斫者谓之朴。--《论衡》；组词：郁朴(本指没有内核的果实或未加工的木料,借喻缺乏教养的人) 郁 〈形〉 文采美盛 周监于二代,郁郁乎文哉!--《论语·八', '小学', '1'),
    ('郊', 'jiāo', '8', '阝', '左右', NULL, '郊〈名〉 (形声。从邑,交声。从邑”,表示与城郭、行政区域有关。本义上古时代国都外百里以内的地区称郊”) 郊区 郊,距国百里为郊。；组词：郊祀(古时帝 郊jiāo城外,市区外东~', '小学', '1'),
    ('郎', 'láng', '8', '阝', '左右', NULL, '郎〈名〉 (形声。从邑,良声。从邑”,表示与行政区域有关。本义古邑名。在今山东金乡县境) 古地名。春秋鲁邑 郎,鲁邑也。', '小学', '1'),
    ('郑', 'zhèng', '8', '阝', '左右', NULL, '郑 (形声。从邑,奠声。从邑,与地名、邦域有关。本义周代诸侯国名,姬姓) 同本义 郑,京兆县,周厉王子友所封。从邑,奠声。宗周之灭,郑徙缯洧之上,今新郑是也。；组词：郑声(郑国音乐)；郑风(《诗》十五国风之一)；郑国渠(古代关中平原的人工灌溉 郑(鄭)zhèng 1.周代诸侯国名', '小学', '1'),
    ('部', 'bù', '10', '阝', '左右', NULL, '部 (形声。从邑,)声。从邑”表示与行政区域有关。本义古汉地名。约在今甘肃省天水、清水、秦安、两当、礼县、徽县一带)；组词：部阵(队伍)；部校(部队；泛称武官)；部将(部下的武官；军中偏将) 中央行政官署', '小学', '1'),
    ('郭', 'guō', '10', '阝', '左右', NULL, '郭 (形声。从邑,从邑”,表示与城郭有关。本义在城的外围加筑的一道城墙) 同本义。内城叫城,外城叫郭 郭,外城也。；组词：郭围(外城边沿)；郭术(城墙和道路)；郭郛(外城) 泛指城市 东家有贤女,窈窕艳城郭', '小学', '1'),
    ('都', 'dōu', '10', '阝', '左右', NULL, '都 dou 全部 表示全部包括在内 渐黄昏,清角吹寒,都在空城。--姜夔《扬州慢》 常愿天下有情人都成眷属。--清·林觉民《与妻书》；组词：你的话并不都对；都子(乞丐)；都把势(总头目) 跟是”字合用,说明理由', '小学', '1'),
    ('鄙', 'bǐ', '13', '阝', '左右', NULL, '鄙 (形声。从邑,啚)声。本义五百家(周代户口单位)) 同本义 鄙,五酂为鄙。--《说文》 五家为邻,五邻为里,四里为酂,五酂为鄙,五鄙为县,五县为遂', '小学', '1'),
    ('酌', 'zhuó', '10', '酉', '左右', NULL, '酌 (形声。从酉,从勺,勺亦声。从酉”与酒有关。本义斟酒) 同本义 酌,盛酒行觞也。--《说文》 尸升,坐取爵酌。--《仪礼·有司彻》。 酒曰清酌。--《礼记·曲礼》 缩酌用茅；组词：酌zhuó 1.斟酒自~', '小学', '1'),
    ('配', 'pèi', '10', '酉', '左右', NULL, '配〈名〉 (形声。从酉,己声。按一说不从己”声,应是妃”省声。本义用不同的酒配制而成的颜色)；组词：元配；继配；配匹(配偶)；配耦(配偶)；配头(方言', '小学', '1'),
    ('酒', 'jiǔ', '10', '酉', '左右', NULL, '酒 (会意。从水,从酉。酉”本义就是酒。酉”亦兼表字音。本义用高粱、大麦、米、葡萄或其他水果发酵制成的饮料)；组词：酒肆(酒店)；酒水(酒；筵席)；酒生(酒保,酒店伙计)；酒务(酒店) 酒席,酒筵 酒jiǔ 1.用粮食(高粱、麦、米等)', '小学', '1'),
    ('酗', 'xù', '11', '酉', '左右', NULL, '酗 (形声。从酉,凶声。酉”与酒有关。本义无节制地喝酒,酒后昏迷乱来) 同本义 下邳周丘,无行酗酒。；组词：酗戕(酒后杀人)；酗讼(因酗酒而争讼)；酗淫(酗酒淫乐) 撒酒疯 弟弼,好酒而酗', '小学', '1'),
    ('酝', 'yùn', '11', '酉', '左右', NULL, '酝 (形声。从酉声。简体)声。简体字云”声。从酉”,与酒有关。本义酿酒) 同本义 酝,酿也。；组词：酝酒(酿酒)；酝户(专事酿酒的人家)；酝造(酿造,制作) 逐渐造成 公盖酝百家之精,兼六朝秀,而一禀之', '小学', '1'),
    ('酣', 'hān', '12', '酉', '左右', NULL, '酣〈形〉 (会意。从酉,从甘,甘亦声。从酉”,表示与酒有关。甘”也具有表意作用。本义酒喝得很畅快)；组词：酣湑(畅饮欢乐)；酣饫(酒醉饭饱)；酣歌(畅饮乐极而歌唱)；酣兴(尽情喝酒的乐趣)；酣叫(畅饮且大声地呼叫)；酣放(嗜酒', '小学', '1'),
    ('酥', 'sū', '12', '酉', '左右', NULL, '酥 (会意。从禾,从酉。酥指食品,因而与禾、酉(代表酒)有关。本义酪类。由牛羊乳制成。又称酥油”)；组词：酥团(用牛羊乳制成的酪类食品,色白光润)；酥酡(古印度以乳酪作成的食品)；酥酪(以牛羊乳所制成的一种食品)；酥蜜(酥酪与', '小学', '1'),
    ('酪', 'lào', '13', '酉', '左右', NULL, '酪〈名〉 (形声。从酉,各声。本义乳酪) 由干酪食品制成的饼,典型地为扁圆形 用果子或果子的仁做的糊状食品 酪lào 1.用牛、羊、马等的乳汁制成的半凝固食品奶~', '小学', '1'),
    ('酬', 'chóu', '13', '酉', '左右', NULL, '酬 (形声。从酉,夀声。本义客人给主人祝酒后,主人再次给客人敬酒作答) 同本义 酬,主人进客也。；组词：酬献(相互劝酒)；酬劝(劝酒) 酬答,报答 主人酬宾', '小学', '1'),
    ('酱', 'jiàng', '13', '酉', '上下', NULL, '酱 (会意。从肉,从酉。酒以和酱也。爿声。古文从酉,爿声。籀文从酉,从皿,爿声。本义用盐醋等调料腌制而成的肉酱) 用麦、面、豆等发酵制成的调味品 酱用百有二十瓮。；组词：黄酱；炸酱；甜酱；豆瓣酱；酱坊；酱豆(盛酱的食器)；酱瓜(即越瓜)；酱清(古代调味品', '小学', '1'),
    ('酵', 'jiào', '14', '酉', '左右', NULL, '酵〈名〉 (形声。从酉,表示与酒有关,孝声。本义酒母) 同本义 酒滓 酵〈动〉 发酵 酵母 酵素 酵子 酵jiào发酵,又称"酵解"', '小学', '1'),
    ('酷', 'kù', '14', '酉', '左右', NULL, '酷〈形〉 (形声。从酉,表示与酒有关,告声。本义酒味浓;香气浓) 同本义 芬芳沤郁,酷烈淑郁。--司马相如《上林赋》 残暴;苛刻 课额日以增,官吏日以酷；组词：酷滥(滥用残酷的刑罚)；酷评(苛刻的评论)；酷惨(残暴,惨酷)；酷偿(残酷报复)；酷能(以严刑酷法为能)；酷吏(滥用刑法', '小学', '1'),
    ('酸', 'suān', '14', '酉', '左右', NULL, '酸〈名〉 (形声。从酉,酉”是汉字部首之一。从酉”,与酒、酪等有关。本义醋) 同本义 像醋一样的气味或味道 杏子还没熟,太酸；组词：酸辛(酸味和辣味)；酸苦(酸味和苦味)；酸醨(味酸而薄的酒) 特指胃酸,胃液 杂剧脚色之一,主要扮演青年文人,因此亦用作', '小学', '1'),
    ('酿', 'niàng', '14', '酉', '左右', NULL, '酿 (形声。从酉,襄声。本义做酒,酿造) 同本义。原专指酿酒,后也指利用发酵作用酿造蜜、醋、酱等 酿,醖也。作酒曰酿。；组词：酝酿(造酒的发酵过程)；酿米(酿酒的米)；酿具(酿酒的器具)；酿秫(用秫黍酿酒)；酿制(酿造)；酿糯(以糯米酿酒) 酝酿', '小学', '1'),
    ('醇', 'chún', '15', '酉', '左右', NULL, '醇 (形声。本义酒味浓厚) 同本义 醇,厚也。--《说文》 买二石醇醪。--《汉书·爰盎传》 春醴惟醇。--张衡《东京赋》 醉醇醲而饫肥鲜者。--刘基《卖柑者言》；组词：醇醨(味道浓厚的美酒叫做醇,味道淡薄的叫做醨)；醇醪(纯厚的美酒)；醇味(美酒味)；醇旨(酒味淳厚甘美) 淳朴；质朴 至', '小学', '1'),
    ('醉', 'zuì', '15', '酉', '左右', NULL, '醉 (会意。从酉,从卒。酉”表示酒,卒”表示终结。酒喝到不能再喝的时候,就醉了。本义醉酒)', '小学', '1'),
    ('醋', 'cù', '15', '酉', '左右', NULL, '醋 (形声。从酉声。从酉”,表示与酒有关。本义用酒或酒糟发酵制成的一种酸味调料) 同本义 酸味 醋 比喻嫉妒 旧时对文人的蔑称 醋 cù 1调味用的酸性液体', '小学', '1'),
    ('醒', 'xǐng', '16', '酉', '左右', NULL, '醒 (形声。从酉,星声。酉与酒有关。本义酒醒) 同本义 醒能述以文。--宋·欧阳修《醉翁亭记》 今宵酒醒何处。--宋·柳永《雨霖铃》；组词：醒酒石(可以醒酒的石头)；醒酒汤(可以醒酒的羹汤)；醒药(醒酒的药)；醒狂(不醉而狂) 醒悟 睡眠状态结束或尚未睡着 既', '小学', '1'),
    ('采', 'cǎi', '8', '采', '上下', NULL, '采 (会意。从爪从木。甲骨文,上象手,下象树木及其果实。表示以手在树上采摘果实和叶子。本义用手指或指尖轻轻摘取来)；组词：采花；采果子；采及葑菲(对别人征求意见时的谦辞) 引申为采集；搜集 古有 采 cǎi 1摘(花、果子)~蘑菇', '小学', '1'),
    ('释', 'shì', '12', '采', NULL, NULL, '释 (形声。从采,瞘声。采,有辨别、分析义。本义脱掉,解下) 同本义 释,解也。从采,取其分别物也。瞘声。；组词：释绂(解下印绶', '小学', '1'),
    ('里', 'lǐ', '7', '里', '上下', NULL, '里 (会意。从衣,里声。本义衣服的里层) 同本义 褃,衣内也。--《说文》。衣外曰表。 襦在褃也。--《谷梁传·宣公九年》注 不罹于褃。--《诗·小雅·小弁》 绿衣黄里；组词：里衣(内衣,汗衫', '小学', '1'),
    ('重', 'zhòng', '9', '里', NULL, NULL, '重 chong (字源见重”) 重复,重叠 四阿重屋。--《考工记·匠人》。注复笮也。” 设重帘。--《周礼·掌次》 余将董道而不豫兮,固将重昏而终身；组词：这两个例子重了；重句(重复的文句)；重字(重复的字)；重卦(重叠八卦)；重席(重叠的垫席)；重轩(双重栏杆) 双,成对', '小学', '1'),
    ('野', 'yě', '11', '里', '左右', NULL, '野 (形声。从里,予声。《尔雅·释言》里,邑也。”本义郊外;野外) 同本义 野,郊外也。--《说文》 邑外谓之郊,郊外谓之野。--《说文》。段注 龙战于野；组词：野外(郊外)；野 野(埜)yě 1.郊外,村外~外', '小学', '1'),
    ('量', 'liàng', '12', '里', '上下', NULL, '量〈动〉 (形声。本义用量器计算容积或长度) 同本义 量,称轻重也。--《说文》。段注称者,铨也『志曰量者,所以量多少也♀权者,所以均物平轻重也。此训量为称轻重者,有多少斯有轻重；组词：比量(不用尺而用手、绳、棍等大概地量一量；比试)；量柴头数米角比喻做事小气吝啬,斤斤计较；量地(丈量土地)；量酒(量酒人', '小学', '1'),
    ('金', 'jīn', '8', '金', '上下', NULL, '金〈名〉 (会意。金文字形。从人(表示覆盖),从土,从二。从土”,表示藏在地下;从二”,表示藏在地下的矿物。本义金属) 金属的通称或金属总名 金,五色金也。黄为之长。久埋不生衣；组词：五金(指金、银、铜、铁、锡,泛指金属)；白金(铂的通称；古代指银子)；金背(镜子)；金钥(门销或金属门 金jīn 1.金', '小学', '1'),
    ('鉴', 'jiàn', '13', '金', NULL, NULL, '鉴 (形声。从金,监声。本义古代用来盛水或冰的青铜大盆) 同本义 鑑,大盆也,一曰鑑诸,可以取明水于月。；组词：鉴诸(古代承露取水的器具)；鉴燧(方诸和阳燧) 中国古代用青铜制成的镜子 鉴(鑑、鑒)jiàn 1.〈古〉用来盛水或冰的', '小学', '1'),
    ('针', 'zhēn', '7', '钅', '左右', NULL, '针 (会意。从金,从十。最初用的竹针,写作箴”,后来有了金属的针,写作鎝”(针)。本义缝衣的用具)；组词：针头线脑(做针线活的零碎物件)；针巧(针线的工夫精巧)；针缕(即针线”', '小学', '1'),
    ('钉', 'dìng', '7', '钅', '左右', NULL, '钉 (形声。从金,丁声。本义鍊饼黄金) 钉子 假借为丁,今俗用为铁钉字。--《说文通训定声》；组词：钉铰(一种金属零件', '小学', '1'),
    ('钓', 'diào', '8', '钅', '左右', NULL, '钩 (形声。从金,勺声。本义以钩饵取鱼) 同本义 钓,钩鱼也。--《说文》 以钓于淇。--《诗·卫风·竹竿》 子钓而不纲。--《论语》 闲来垂钓碧溪上；组词：钓蛤蟆 引申为诱取 而晋献以璧马钓之', '小学', '1'),
    ('钙', 'gài', '9', '钅', '左右', NULL, '钙 一种银白色的相当柔软的碱土族二价金属元素,在空气中很快失去光泽,受热时以明亮的火焰燃烧,主要用于合金和各种冶金过程中,常用作清除剂;自然界中不单独存在；组词：肺结核的病灶经过钙化而痊愈', '小学', '1'),
    ('钝', 'dùn', '9', '钅', '左右', NULL, '钝 (形声。从金,屯声。本义不锋利) 同本义 兵不钝锋。--《文选·檄吴将校部曲》 庶竭驽钝。--诸葛亮《出师表》；组词：钝刀(钝兵', '小学', '1'),
    ('钞', 'chāo', '9', '钅', '左右', NULL, '钞 掠取;抢掠◇作抄” 钞,叉取也。从金,少声。--《说文》。俗字作抄。 遮取谓之抄掠。--《通俗文》 攻钞郡县。--《后汉书·公孙瓒传》；组词：钞掠(劫掠骚扰；劫夺他人财物) 誊写', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('钟', 'zhōng', '9', '钅', '左右', NULL, '钟 (形声。左形,右声。鐘本义古代打击乐器,青铜制) 同本义 钟,乐钟也。--《说文》。杨树达曰钟者,可捶之物。” 钟,铃也。--《广雅·释器》 垂之和钟；组词：钟磬(两种古代乐器)；钟鼎之家(宴享时列鼎、击钟奏乐的古代贵族家庭)；钟石(指乐器中的钟和磬)；钟板(钟和云板)；钟乳(', '小学', '1'),
    ('钠', 'nà', '9', '钅', '左右', NULL, '钠 一种银白色的软的、蜡状而有延展性的金属元素,原子序数11,其化学性质很活泼,用在钠蒸气灯中,尤其在内燃机用的致冷阀中作为一种传热剂 钠nà金属元素之一。符号na。银白色', '小学', '1'),
    ('钢', 'gāng', '9', '钅', '左右', NULL, '钢 (形声。从金,冈声。本义铁和碳的合金。比生铁坚韧,比熟铁质硬) 同本义 表面粗糙有细点纹,置于蜡纸下,以针形钢笔在纸上书写,即现透明的笔迹,用以油印。或指钢质电镌的印刷底版', '小学', '1'),
    ('钥', 'yào', '9', '钅', '左右', NULL, '钥 yao 门直闩。上穿横闩下插地上的直木 户钥,自关而东,陈、楚之间谓之键,自关而西谓之钥。；组词：钥牡(开锁的工具', '小学', '1'),
    ('钦', 'qīn', '9', '钅', '左右', NULL, '钦 (形声。从欠,金声。欠,打呵欠,张口舒气。本义打呵欠的样子) 同本义 钦,欠貌。--《说文》。段玉裁注凡气不足而后欠,钦者,倦而张口之貌也。” 燮生而钦颐折頾,丑状骇人', '小学', '1'),
    ('钧', 'jūn', '9', '钅', '左右', NULL, '钧 (形声。从金,匀声。本义古代重量单位。三十斤为一钧) 同本义 钧,三十斤也。--《说文》 入钧金。--《周礼·大司寇》 钧衡石。--《礼记·月令》 颜高之弓六钧；组词：钧衡(钧和衡都是量物的工具,因借为评量人才之意)；千钧一发；雷霆万钧；钧石(钧和石', '小学', '1'),
    ('钩', 'gōu', '9', '钅', '左右', NULL, '钩 (会意。从金,从句,句亦声。句”,弯曲。也具有表意作用。本义衣带上的钩。引申为 钓鱼或挂物用的钩”) 形状弯曲,用于探取、悬挂器物的用品。可分为钓钩、挂钩、带钩等 鉤,曲也', '小学', '1'),
    ('钮', 'niǔ', '9', '钅', '左右', NULL, '钮 (形声。从金,丑声。本义印鼻,即友子) 同本义 钮,印鼻也。--《说文》 龟纽(钮)之玺。--《淮南子·说林》。注纽系佩服也。” 诸王金玺龟钮。--《晋书·舆服志》；组词：环钮；狮钮；虎钮；瓦钮 器物上面可以提携或系绳带的部分 妙墨新题森锁钮', '小学', '1'),
    ('钱', 'qián', '10', '钅', '左右', NULL, '钱 (形声。从金,戔声。本义农具名,即铁铲。上古时期曾以农具作为交易媒介,其后铸造货币又仿其形为之,因此引申为货币、钱财) 金属货币。特指铜钱 一曰货也。古者货贝而宝龟', '小学', '1'),
    ('钳', 'qián', '10', '钅', '左右', NULL, '钳 (形声。从金,甘声。本义金属夹具) 古刑具。束颈的铁圈 钳,以铁有所劫束也。--《说文》 皆弛解钳。--《后汉书·光武纪》 古之刑在项曰钳,今之链锁；组词：钳铁(古代束颈的刑具)；钳髠(钳和髠', '小学', '1'),
    ('钻', 'zuàn', '10', '钅', '左右', NULL, '钻 (形声。从金,赞(占)声。古时钻”、鑽”是两个字。钻”本是镊子,又作刑具。现在是鑽”的简化字。本义穿孔)；组词：钻一个眼；钻木取火；钻入(穿入)；钻山(在山墙上开门或开洞', '小学', '1'),
    ('钾', 'jiǎ', '10', '钅', '左右', NULL, '钾 碱金属族的一价金属元素,呈银白色,质软,有光泽,熔点低,比钠更活泼,在空气中很快氧化,与水激烈反应,放出氢气而自行着火', '小学', '1'),
    ('铁', 'tiě', '10', '钅', '左右', NULL, '铁〈名〉 (形声。从金,臷声。本义化学元素。符号fe。一种很重的可锻、有延展性和有磁性的、主要是两价和三价的金属元素,纯铁为银白色,但在潮湿空气中容易生锈)；组词：铁冶(冶铁工场)；铁山(产铁的矿山)；铁石(铁与石；铁矿石)；铁锡(铁和锡)；铁砂(含铁的矿砂)；铁炭(铁和炭)；铁皮(', '小学', '1'),
    ('铃', 'líng', '10', '钅', '左右', NULL, '铃 (形声。从金,令声。本义金属制成的响器。又为打击乐器。形似钟而小) 同本义 大祭祀,鸣铃以应鸡人。；组词：铃杵(一种有柄的铃)；铃语(风铃的声音)；铃铎(挂在楼阁寺院檐角的铃)；铃铛寿星(小儿帽子及手镯上的点缀饰品', '小学', '1'),
    ('铅', 'qiān', '10', '钅', '左右', NULL, '铅 青金 铅,青石也。--《说文》 铅松怪石。--《书·禹贡》 或髡钳以鈆杵舂。--《汉书·江都易王非传》 药物秘海岳,采铅青溪滨；组词：铅刀(铅制的刀,不够锋利', '小学', '1'),
    ('铆', 'mǎo', '10', '钅', '左右', NULL, '铆 (卯为铆的本字) 卯,榫 一铆顶一楔。--《中国谚语资料》 铆 敲打或冲压(如金属销、棒或螺栓的)端部或尖端使镦粗成头 我得铆点劲儿干,把耽误人家的工夫给补上', '小学', '1'),
    ('铐', 'kào', '11', '钅', '左右', NULL, '铐 (形声。从金,考声。本义手铐) 同本义 铐 戴上手铐 铐kào 1.束缚手的刑具手~子。 2.戴手铐将罪犯~起来。', '小学', '1'),
    ('铛', 'chēng', '11', '钅', '左右', NULL, '铛 锒铛。锁系囚人的铁索 铛,锒铛也。从金,当声。--《说文》。按,锁曰锒铛。 女子的耳饰 足履革屣,耳悬金铛。--《北史》 铛 钟鼓的声音 铛铛晓漏。--徐陵《与杨仆射书》；组词：铛铛 cheng 温器,似锅,三足 烙饼或做菜用的平底浅锅 鼎铛玉石,金块珠砾,弃掷逦迤', '小学', '1'),
    ('铜', 'tóng', '11', '钅', '左右', NULL, '铜〈名〉 (形声。从金,同声。本义金属名,古称赤金) 同本义 铜,赤金也。--《说文》 章山之铜,所谓丹阳铜也。今世有白铜,盖点化为之,非其本质', '小学', '1'),
    ('铡', 'zhá', '11', '钅', '左右', NULL, '铡 (形声。从金,则声。从金,表示是金属制品。本义铡刀) 同本义 将铜铡来,切了你那颅头。--元·李直夫《虎头牌》 铡 用铡刀切碎、切成小块 铡刀 铡zhá 1.铡刀', '小学', '1'),
    ('铣', 'xǐ', '11', '钅', '左右', NULL, '铣 xi 用一种能旋转的圆形多刃刀具切削金属工件 铣刀 铣工 铣削 铣 xian (形声。从金,先声。本义富有光泽的金属) 富有光泽的金属 金之泽者。', '小学', '1'),
    ('铭', 'míng', '11', '钅', '左右', NULL, '铭 (形声。从金,名声。从金,与钟鼎器物有关。本义在器物上雕刻文字) 同本义 铭者,自名也。自名以称扬其先祖之美而明著之后世者也。；组词：铭功(在金石上刻文字来记下功勋)；铭戒(在金石等物品上,刻下言辞,以为劝诫)；铭勒(镌刻金石,以记述功德) 牢记不忘 铭', '小学', '1'),
    ('铲', 'chǎn', '11', '钅', '左右', NULL, '铲 (形声。从金,产声。本义用以铲削的铁器) 铲子 又如铁铲;煤铲 古兵器。形似铲 铲,长小尺一丈,尾有刃,以便后刺。--明·茅元仪《武备志》 铲 削平;铲除 铲,削平也。；组词：铁铲；煤铲 古兵器', '小学', '1'),
    ('银', 'yín', '11', '钅', '左右', NULL, '银 (形声。从金,艮声。本义一种白色金属,通称银子) 同本义 性的物质,在自然界中以自生式共生状态(如在脆银矿、辉银矿、淡红银矿', '小学', '1'),
    ('铸', 'zhù', '12', '钅', '左右', NULL, '铸 (形声。从金,寿声。甲骨文字形,会意。上面是双手拿鬲”(古炊具),下面是皿”;鬲、皿表熔化金属的锅炉。中间象被熔铸的金属。小篆变为形声字。本义铸造)；组词：铸印(铸造金属印章)；铸冶(销冶金属铸造器物)；铸兵(铸造兵器)；铸作(铸造)；铸金(熔铸金属成物)；铸铜(炼铜) 造就', '小学', '1'),
    ('铺', 'pù', '12', '钅', '左右', NULL, '铺 (形声。从金,甫声。本义衔门环的底座。又称铺首”) 同本义 铺,箸门铺首也。--《说文》 挤玉户以撼金铺兮。--司马相如《长门赋》 金琐银铺；组词：铺手(铺首) 铜器名', '小学', '1'),
    ('链', 'liàn', '12', '钅', '左右', NULL, '链 (形声。从金,连声。本义铅矿) 链条 今人以锒铛之类相连属者为链。--《六书故》 又如铁链;锁链 链 用索环栓住；组词：铁链；锁链 链 用索环栓住、捆绑或联接 链(鍊)liàn 1.用金属环连套构成的长条铁~子', '小学', '1'),
    ('销', 'xiāo', '12', '钅', '左右', NULL, '销 (形声。从金,肖声。本义熔化金属) 同本义 销,铄金也。--《说文》 销车以斗七命。--《淮南子·泛论》 收天下兵,聚之咸阳,销以为钟鑜。--《史记·秦始皇本纪》 销锋镐；组词：销冶(熔炼,熔铸,熔冶)；销炼(熔化冶炼)；销钱(熔化钱币) 溶化；消融 雪霜顿销释,土脉膏且黏', '小学', '1'),
    ('锁', 'suǒ', '12', '钅', '左右', NULL, '锁 (形声) 置于可启闭的器物上,以钥匙或暗码(如字码机构、时间机构、自动释放开关、磁性螺线管等)打开的扣件 柄铁折叠环复,如锁上练,引之长丈许。--明·魏禧《大铁椎传》；组词：锁管(锁簧插入的锁身)；锁孔(锁眼)；锁梃儿(锁的销子)；上锁 一种用铁环钩连而成的刑具 若见鬼把椎锁绳纆,立守其旁', '小学', '1'),
    ('锄', 'chú', '12', '钅', '左右', NULL, '锄〈名〉 (形声。从金,助声。本义锄头。一种长柄农具,其刀身平薄而横装,专用于中耕、除草、疏松植株周围的土壤)；组词：大锄；小锄 锄 〈动〉 用锄头整理田地,除草 大儿锄豆溪东,中儿正织鸡笼', '小学', '1'),
    ('锅', 'guō', '12', '钅', '左右', NULL, '锅 (形声。从金,唈声。本义炊事用具,圆形中凹,多用铁制) 同本义 形状像锅的东西 车鈍。即车轴外面的铁圈 车鈍,燕、齐、海、岱之间谓之锅。', '小学', '1'),
    ('锈', 'xiù', '12', '钅', '左右', NULL, '锈 金属表面所生的氧化物 鏽,铁生衣也。--《集韵》 刀子锈用木贼草擦之,则锈自落。--《物类相感志》；组词：锈彩(古金属的锈斑) 锈病 锈 生锈 令人感激坐流涕,锈涩短刀何足云', '小学', '1'),
    ('锉', 'cuò', '12', '钅', '左右', NULL, '锉 (形声。从金,坐声。本义小釜,瓦锅) 同本义 锉,鍑也。--《说文》 用钢制成的磨铜', '小学', '1'),
    ('锋', 'fēng', '12', '钅', '左右', NULL, '锋 (形声。从金,。本义刀、剑等的尖端或锐利部分) 同本义 底厉锋锷。--《汉书·萧望之传》；组词：锋端(指刀剑等兵器的刃口)；锋镝(刀刃和箭头', '小学', '1'),
    ('锌', 'xīn', '12', '钅', '左右', NULL, '锌〈名〉 一种蓝白色的晶状的二价金属元素,有低至中等的硬度,纯时有延性,主要用作钢铁的保护性涂层 锌白 锌版 锌xīn金属化学元素。符号zn。青白色,质脆。用于电镀、造黄铜等', '小学', '1'),
    ('锐', 'ruì', '12', '钅', '左右', NULL, '锐 (形声。从金,兑声。本义芒) 同本义 锐,芒也。--《说文》。段玉裁注芒者,草聑也。” 精锐的军队或士卒 赵王出轻锐以寇其后,秦数不利。--《战国策》 瑜等率轻锐继其后', '小学', '1'),
    ('错', 'cuò', '13', '钅', '左右', NULL, '错 (形声。从金,昔声。本义用金涂饰,镶嵌) 同本义 错,金涂也。今所谓镀金。俗字作镀。--《说文》 金银要饰谓之错镂。--《通俗文》 鼎错日用而不足贵。--《淮南子·说山》；组词：错臂(用丹青画饰手臂) 互相磨擦 错,磨也', '小学', '1'),
    ('锚', 'máo', '13', '钅', '左右', NULL, '锚 (形声。从金,苗声。本义船停泊时所用的设备。一般为铁制或钢制)同本义 链);锚链孔(艏之两旁各有一小孔,以备起锚时将锚链由此孔收进,锚则紧贴于外之钢板上)', '小学', '1'),
    ('锡', 'xī', '13', '钅', '左右', NULL, '锡 化学名词。一种略带蓝色的白色光泽的低熔点金属元素,在化合物内是二价或四价,不会被空气氧化,主要以二氧化物(锡石)和各种硫化物(例如硫锡石)的形式存在 素符号sn 金锡连丹；组词：锡古子(形如鼓的有盖锡锅) 通緆”', '小学', '1'),
    ('锣', 'luó', '13', '钅', '左右', NULL, '锣 带卷边的青铜圆盘 鸣锣聚众。--《广东军务记》 又 鸣锣会集。 鸣锣传递。 锣(鑼)luó打击乐器。铜制,圆形,像盘,用槌敲打发声敲~打鼓。', '小学', '1'),
    ('锤', 'chuí', '13', '钅', '左右', NULL, '锤 (形声。从金,垂声。本义古代重量单位) 同本义 八铢 锤,八铢也。--《说文》 有千金之璧,而无锱锤之祄诸。--《淮南子·诠言》 十二两 虽割国之锱锤以事人', '小学', '1'),
    ('锥', 'zhuī', '13', '钅', '左右', NULL, '锥 (形声。从金,隹声。本义钻孔的工具) 同本义 锥,锐也。--《说文》 锥,利也。--《释名·释用器》 引锥自刺其股。--《战国策·秦策一》 锥之处囊中；组词：锥刀(用以雕刻的锥形小刀', '小学', '1'),
    ('锦', 'jǐn', '13', '钅', '左右', NULL, '锦〈名〉 (形声。从帛,金声。本义有彩色花纹的丝织品) 同本义 锦,襄邑织文。--《说文》。朱骏声按,染丝织成文章也『襄邑县贡织文。” 皆奉玉锦束请觌。--《仪礼·聘礼》。注玉锦；组词：锦囊(锦制的袋子)；锦衾(锦制的大被)；锦帆(锦制的帆)；锦覆(以织锦遮掩羞丑,喻作美言庇护) 古指锦袍 旧时书信中的敬', '小学', '1'),
    ('锨', 'xiān', '13', '钅', '左右', NULL, '锨 (形声。从金,欣声。本义掘土和铲东西的工具。农具名。似锹而较铲方阔,柄端无短拐) 同本义 锨镢以归监督。--明·魏大中《浚濠工竣疏》；组词：铁锨,木锨 锨(杴)xiān一种掘土或铲东西的工具,铁制或木制', '小学', '1'),
    ('锭', 'dìng', '13', '钅', '左右', NULL, '锭 (形声。从金,定声。本义古代盛熟食无足的蒸器) 同本义 锭,镫也。--《说文》 膏灯 烛台者,插烛之锭也', '小学', '1'),
    ('键', 'jiàn', '13', '钅', '左右', NULL, '键 (形声。从金,建声。本义鼎上贯通两耳的横杠) 同本义 键,铉也。--《说文》。段玉裁注谓鼎扃也。以木横关鼎耳而举之。非是则既炊之鼎不可举也。故谓之关键。” 车辖。安在车轴两端；组词：键闭(门闩；锁 键jiàn 1.车轴上的铁条,用以管住车轮', '小学', '1'),
    ('锯', 'jù', '13', '钅', '左右', NULL, '锯 (形声。从金,居声。本义析解木石等的齿形工具) 同本义 锯,枪唐也。--《说文》 锯者所以治木也。--《列女传·仁智》。据古史考曰,孟庄子作锯,又按鲁语,中刑用刀锯；组词：手锯；电锯；拉锯；锯齿；锯梁(锯子当中支撑锯把的木梁) 锯形物 古刑具 中刑用刀锯', '小学', '1'),
    ('锰', 'měng', '13', '钅', '左右', NULL, '锰 一种灰白色多价金属元素,通常硬而脆,类似铁但无磁性 锰钢 锰měng金属化学元素。符号mn。赤灰色,质坚而脆。锰与铁的合金叫"锰钢",它是特殊钢,供做火车的车轮等', '小学', '1'),
    ('锹', 'qiāo', '14', '钅', '左右', NULL, '锹 掘土器,用于开沟掘土、铲取什物, 锹 用锹挖掘 锹(鍫)qiāo 1.挖土或铲取东西的工具铁~。 2.用锹铲~土。~煤。', '小学', '1'),
    ('锻', 'duàn', '14', '钅', '左右', NULL, '锻 (形声。从金,段声。本义打铁) 同本义 锻,小冶也。--《说文》。按,熔铸金为冶,以金入火焠而椎之为小冶。” 锻练之吏。--《后汉书·韦彪传》；组词：锻菜刀；锻锄头', '小学', '1'),
    ('镀', 'dù', '14', '钅', '左右', NULL, '镀 (形声。从金,度声。本义以金属附着到别的金属或物体表面) 利用化学、机械或电镀的方法使一种金属附着在别的金属或物体的表面上 假金只用真金镀,若是真金不镀金', '小学', '1'),
    ('镇', 'zhèn', '15', '钅', '左右', NULL, '镇 压~尺(用金属、玉石等制成的尺形文具,用来压书和纸。亦称镇纸”,压尺”)。~痛。 以武力维持安定~压(用强力压制,不许进行政治活动)。~反。~服。~慑。~守。 安定~静。~定', '小学', '1'),
    ('镊', 'niè', '15', '钅', '左右', NULL, '镊 镊子 镊,摄取发也。--《释名·释首饰》 愿戢子之手,摄子之镊。--晋·左思《白发赋》 古簪端垂锦 后床帷陈设故旧,钗镊十余枚', '小学', '1'),
    ('镐', 'gǎo', '15', '钅', '左右', NULL, '镐 gao 镐头 镐 hao (形声。从金,高声。本义温器) 同本义 镐,温器也。--《说文》 镐京。古都名。西周国都,在今陕西西安西南 王在在镐。--《诗·小雅·鱼藻》；组词：镐洛(镐京与洛阳的并称) 姓 镐 通皓”', '小学', '1'),
    ('镜', 'jìng', '16', '钅', '左右', NULL, '镜 (形声。从金,竟声。本义照形取影的器具) 同本义 镜,鉴也。--《玉篇》 镜,景也。--《说文》 明镜者可以察形也。--《大戴礼记·保傅》 以镜考己行；组词：镜袱(盖住镜面的布帛帘子)；镜心(镜子的中心)；镜月(镜中之花,水中之月)；镜花(镜中的花影) 其他光学用器 镜jìng', '小学', '1'),
    ('镣', 'liào', '17', '钅', '左右', NULL, '镣 (形声。从金,尞声。本义成色好的银子) 同本义 镣,白金也。--《说文》 白金谓之银,其美者谓之镣。--《尔雅》 大夫镣琫而镣珌。--《诗·瞻彼洛矣》传；组词：镣金(精美的银子)；镣铣(成色好的有光泽的金属) 有孔炉 套在脚腕上使不能快跑的刑具 镣,铁连环之絷足,秆者带以输作,重', '小学', '1'),
    ('镰', 'lián', '18', '钅', '左右', NULL, '镰 (形声。从金,廉声。本义农具名。即镰刀”) 同本义 镰,锲也。--《说文》 刈钩自关而西或谓之镰。--《方言五》；组词：佩镰；两刃镰；开镰收割的季节,村里人都很忙 锋利的棱角 凡箭镞胡合嬴者四镰', '小学', '1'),
    ('镶', 'xiāng', '22', '钅', '左右', NULL, '镶 (形声。从金,襄声。本义瓤子) 铸铜铁器模型的瓤子 镶,作型中肠也。--《说文》 古兵器名 手持白头镶；组词：镶滚(在衣服边缘加一道边；女服加宽边叫镶,加窄边叫滚) 俗称修补其缺处 今市肆有补齿,一云镶齿,如生', '小学', '1'),
    ('长', 'cháng', '4', '长', NULL, NULL, '长 chang (象形。甲骨文字形,象人披长发之形,以具体表抽象,表示长短的长”。本义两点距离大)；组词：狭长(窄而长)；长铗(剑的一种', '小学', '1'),
    ('门', 'mén', '3', '门', NULL, NULL, '门 (象形。甲骨文字形,象门形。门”是汉字的一个部首。本义双扇门,门) 同本义 閠,闻也。从二户相对,象形。按,一扇曰户,两扇曰门。又,在堂室曰户,在宅区域曰门。 五祀；组词：门阑(门帘；门框)；门钉(大门上的圆头装饰物)；门楔(门榄两端靠门框竖立的短木)；门吊儿(门上的搭钩)；门坎(门槛) 房', '小学', '1'),
    ('闪', 'shǎn', '5', '门', '半包围', NULL, '闪 (会意。从人在门中。本义自门内偷看) 同本义,引申为偷看 闪,窥头在门中也。--《说文》。南朝 宋·裴松之注引《魏略·苛吏传》白日常自于墙壁间閨闪。” 故鱼鲔不渧；组词：脑子闪过一个念头；闪尸(忽隐忽现)；闪飒(闪烁)；闪缀(闪闪发光)；闪然(隐没不见)；闪荡(光闪动)；闪放( 闪shǎn', '小学', '1'),
    ('闭', 'bì', '6', '门', '半包围', NULL, '闭 (会意。从门,从才。才”是用来闭门的东西。本义关门,把门合闭起来) 同本义 闭,阖门也。；组词：闭扫(即闭门欲扫', '小学', '1'),
    ('问', 'wèn', '6', '门', '半包围', NULL, '问 (形声。从口,门声。本义问,询问) 同本义 问,讯也。--《说文》 皇帝请问下民。--《书·吕刑》 时聘曰问。--《周礼·大宗伯》 小聘曰问。--《仪礼·聘礼》 问人于他邦', '小学', '1'),
    ('闯', 'chuǎng', '6', '门', '半包围', NULL, '闯 (会意。从马,从门。本义猛冲,突然直入) 同本义 阩,马出门貌。从马在门中。--《说文》 开之则闯然公子阳生也。--《公羊传·哀公六年》。注出头貌。”；组词：闯堂；闯阵；闯亮(江湖隐语,指望风探哨)；闯寡门(去妓院吃茶而不嫖宿)；闯花门阚(嫖)小娘(嫖妓宿娼) 孟浪行事 奔走谋', '小学', '1'),
    ('闰', 'rùn', '7', '门', '半包围', NULL, '闰 (会意。从王在门中”。古代天子每年冬季以明年朔政分赐诸侯,诸侯于月初祭庙受朔政称为告朔”。据《说文》段注,举行告朔之礼时,王通常居于明堂,但逢闰月,则居于路 寝门；组词：闰秋(闰 闰rùn多余的数', '小学', '1'),
    ('闲', 'xián', '7', '门', '半包围', NULL, '闲 (会意。从门中有木。本义栅栏) 同本义 闲,阑也。--《说文》 人闲有家。--《易·家》。注;阑也。” 日闲舆卫。--《易·大畜》。注阂也。” 舍则守王闲；组词：闲厩(古代皇家养牲口的地方)；闲驹(养马之所) 伦理道德的规范、界限 掌十有二闲之政教', '小学', '1'),
    ('间', 'jiān', '7', '门', '半包围', NULL, '间 中间;内 一动一静者,天地之閒也。--《礼记·乐记》 而独閒数百千里。--《汉书·严助传》。注中间也。” 攘臂于其閒。--《庄子·人间世》。司马注犹里也。” 黄河远上白云间；组词：两地之间；上下之间；左右之间；半中间；两个高楼间的小弄；两个电极间的真空 一会儿,顷刻 莫然有间,而子桑户死', '小学', '1'),
    ('闷', 'mèn', '7', '门', '半包围', NULL, '闷 气闷,因气不通畅而引起的不快之感 闭则热而闷。--《素问·风论》 又如闷吐(心闷想吐);闷绝(晕倒。一说窒息而死);闷痒(因身体不舒爽而发痒);闷窒(窒息)；组词：闷吐(心闷想吐)；闷绝(晕倒', '小学', '1'),
    ('闸', 'zhá', '8', '门', '半包围', NULL, '闸 (形声。从门,甲声。本义开闭閠(根据枢转轧轧有声而造字) 水闸 完我岸闸,千夫奏功。--宋·苏轼《祭英烈王祝文》；组词：闸牌子(河道上管水闸的人)；开闸；船闸；涵闸(涵洞和水闸的总称)；闸头(水闸) 制动器的通称 电闸,在电路上用来接通、断', '小学', '1'),
    ('闹', 'nào', '8', '门', '半包围', NULL, '闹 (会意。从市,从閠(斗)。市场上的争吵、喧闹。本义嘈杂,喧扰) 同本义 鸣声相呼和,无理只取闹。--韩愈《食虾蟆》 召闹取怒。--唐·柳宗元《答韦中立论师道书》 渐不喜闹；组词：闹里(闹哄哄的场合中)；人声吵闹；喧闹(喧哗吵闹)；闹耳朵(形容嘈杂)；闹吵(喧闹,大声争吵) 热闹 门巷不教当闹市,诗', '小学', '1'),
    ('闺', 'guī', '9', '门', '半包围', NULL, '闺 (形声。从门,圭声。圭”亦具有表意作用。本义上圆下方的小门;小门) 同本义 闺,特立之户也。上圆下方,有似圭。；组词：闺窦(穿墙小门)；闺閤(宫中小门,内宫深处)；闺牖(宫内的门窗)；闺壸(内宫) 内室 室西连于中闺,先妣尝一至', '小学', '1'),
    ('闻', 'wén', '9', '门', '半包围', NULL, '闻 (形声。从耳,门声。本义听到) 同本义 闻,知声也。--《说文》 闻耳之聪也。--《墨子经上》 心不在焉,视而不见,听而不闻。--《礼记·大学》 闻佳人兮召予；组词：闻声不食(听到动物的叫声就不忍心吃它的肉)；闻所不闻(听到从未听过的事情', '小学', '1'),
    ('闽', 'mǐn', '9', '门', '半包围', NULL, '闽 (形声。从虫,门声。本义古种族名。生活在浙江南部和福建一带,后因称福建为闽) 同本义 閩,东南越也。；组词：闽中(泛指福建省地)；闽江(水名', '小学', '1'),
    ('阀', 'fá', '9', '门', '半包围', NULL, '阀 (形声。从门,伐声。本义阀阅。即仕官人家自序功状而树立在门外左边的柱子) 同本义 功劳 献诚子煦,积阀亦至夏州节度使。；组词：阀阅(有权势的仕宦人家) 依靠权势在某一方面有特殊支配地位的人物或集团 阀门 阀 fá 1.〈古〉有权势有地位的家庭或家', '小学', '1'),
    ('阁', 'gé', '9', '门', '半包围', NULL, '阁 (形声。从门,各声。本义古代放在门上用来防止门自合的长木桩) 门限 閣,所止扉也。门开则旁有两长橜杆辂之,止其自阖也。', '小学', '1'),
    ('阅', 'yuè', '10', '门', '半包围', NULL, '阅 (形声。从门,说省声。象在门里清点东西。本义在门内考察、计算事物) 同本义 阅,具数于门中也。；组词：阅问(逐一询问) 察看；视察,考查 常以秋、岁末之时阅其民', '小学', '1'),
    ('阎', 'yán', '11', '门', '半包围', NULL, '阎 (形声。从门,臽声。本义内巷内的门,亦指里巷) 同本义 閻,里中门也。--《说文》 隐于穷阎漏屋。--《荀子·儒效》。注里门也。” 兴于闾阎。--《汉书·循吏传》注 便旋闾阎；组词：阎闾(里巷内外的门)；阎术(里巷)；阎亲(乡亲) 姓 阎yán里巷的门,又指里巷~里', '小学', '1'),
    ('阐', 'chǎn', '11', '门', '半包围', NULL, '阐 (形声。从门,单声。本义开,打开) 同本义 阐,开也。--《说文》 看山倚前户,待月阐东扉。--唐·白居易诗 开辟;开拓 阐并天下。--《史记·秦始皇本纪》；组词：阐辟(开辟,开拓)；阐拓(开拓) 讲明白 隐则胜阐矣', '小学', '1'),
    ('阔', 'kuò', '12', '门', '半包围', NULL, '阔 (形声。从门,活声。本义阔大,很开阔) 同本义 阔,疏也。--《说文》 阔,稀也。--《汉书·沟洫志》集注 阔,远也。--《尔雅》 缓步阔视。--《列子·黄帝》 于嗟阔兮；组词：阔绝(隔绝,差别很大)；阔略(疏略；粗疏)；阔落(宽疏,不细密)；阔寥(稀少)；阔疏(粗疏)；阔希(稀疏) 宽横的距离大', '小学', '1'),
    ('队', 'duì', '4', '阝', '左右', NULL, '队 (形声。本义从高处掉下来。是坠”的本字) 坠落 队,从高陨也。俗字作坠。--《说文》 殷亩而驰不队。--《考工记·轮人》 退人若将队诸渊。--《礼记·檀弓下》 公(齐襄公)惧；组词：排队；纵队；横队 军队或集体的编制单位 队 duì 1行列排~、整~', '小学', '1'),
    ('阱', 'jǐng', '6', '阝', '左右', NULL, '阱 (形声。从阜,表示与地形地势的高低上下有关,井声。本义陷阱,为捕捉野兽的坑) 同本义 阱,陷也。；组词：猛虎落阱；阱鄂(捕野兽的陷坑和笼子)；阱机(本指捕捉动物的陷阱', '小学', '1'),
    ('防', 'fáng', '6', '阝', '左右', NULL, '防〈名〉 (形声。从阜,方声。本义堤坝) 同本义 防,堤也。--《说文》 以防止水。--《周礼·稻人》 町原防。--《左传·襄公二十五年》 祭防与水庸；组词：防隅(水防山隅)；沟防；堤防 要塞；关防 地名 春秋陈邑,在今河南省淮阳县北 春秋鲁地', '小学', '1'),
    ('阳', 'yáng', '6', '阝', '左右', NULL, '阳 (形声。从阜,? 同本义 阳,高明也。--《说文》 山南为阳,水北为阳。--《谷梁传·僖公二十八年》 山东曰朝阳,山西曰夕阳。--《尔雅》 利刊阳木而火之。--《周礼·柞氏》；组词：衡阳(在衡山之南),洛阳(在洛河之北)；阳陆(山之南)；阳濒(水之北岸)；阳林(生在山南的林木)；阳木(山南之木 阳(陽', '小学', '1'),
    ('阴', 'yīn', '6', '阝', '左右', NULL, '阴 (会意。从阜,从侌,侌亦声。阜,土山,从阜多与地形有关。简化字属会意,表示月夜笼罩山冈,很阴暗。本义山的北面,水的南面)；组词：胸为~,背为阳', '小学', '1'),
    ('阵', 'zhèn', '6', '阝', '左右', NULL, '阵 军队作战时布置的局势~线。~势。严~以待。 战场~地。~亡。冲锋陷~。 量词,指事情或动作经过的段落~发。~痛。下了一~雨。 阵zhèn 1.作战队伍的行列~容。严~以待', '小学', '1'),
    ('阶', 'jiē', '6', '阝', '左右', NULL, '阶〈名〉 (形声。从阜,表示与地形地势的高低上下有关,皆声。本义台阶) 同本义 阶,陛也。字亦作堦。；组词：阶廊(台阶和走廊)；阶檐(台阶与屋檐)；阶陛(宫殿的台阶)；阶除(台阶)；阶墀(宫殿台阶) 梯子 捐阶', '小学', '1'),
    ('阻', 'zǔ', '7', '阝', '左右', NULL, '阻 (形声。从阜声,且声。阜”是土山,与高下险阻有关。本义险要的地方) 同本义 阻,险也。；组词：阻隘(险要之地)；阻阨(据守险要) 妨碍物；障隔 保其岩阻', '小学', '1'),
    ('阿', 'ā', '7', '阝', '左右', NULL, '阿〈助〉 (汉语名词词头,盛行于魏晋以后) 加在亲属称呼前面有亲昵的意味 阿姊闻妹来。--《乐府诗集·木兰诗》 府吏得闻之,堂上启阿母。--《玉台新咏·古诗为焦仲卿妻作》。；组词：阿爷(又作阿耶”', '小学', '1'),
    ('附', 'fù', '7', '阝', '左右', NULL, '附 (形声。从阜,付声。从阜”,表示与地形地势的高低上下有关。本义小土丘。《说文》附娄,小土山也。”) 沾着,附着 如涂涂附。；组词：附缠(附着,纠缠住)；附离(附着) 依傍；依附 附于诸侯,曰附庸', '小学', '1'),
    ('际', 'jì', '7', '阝', '左右', NULL, '际 (形声。从阜,祭声。本义两墙相合之缝) 同本义 际,壁会也。--《说文》。段玉裁注两墙相合之缝也。 泛指合缝的地方;缝隙 凿棺际而安之；组词：岩际；水际；无边无际；边际；天际；九天之际；一望无际；分际；漫无边际 时候；时机 败军之际', '小学', '1'),
    ('陆', 'lù', '7', '阝', '左右', NULL, '陆 liu 数目字六”的大写 陆 lu (会意。从阜,表示与地形地势的高低上下有关,从坴(鑬??),土块很大。坴”亦兼表字音。本义陆地,高而平的地方)；组词：大陆(广大的陆地)；水陆(水面和陆地上)；陆毛(陆地之所产', '小学', '1'),
    ('陈', 'chén', '7', '阝', '左右', NULL, '陈 (形声。从阜,从木,申声。本义地名。古宛丘地,春秋时陈国国都,在今河南省淮阳县。引申为姓氏) 古国名 陈,宛丘,舜后妫(畧??))满之所封。', '小学', '1'),
    ('陋', 'lòu', '8', '阝', '左右', NULL, '陋〈形〉 (形声。本义狭窄,狭小) 同本义 陋,阨陕也。--《说文》 百盖无筑,千聚无社,谓之陋。--《管子·侈靡》 生于辟陋之国。--《淮南子·修务》 渞恒山其若陋兮；组词：陋巷蓬门(穷苦人的住处', '小学', '1'),
    ('陌', 'mò', '8', '阝', '左右', NULL, '陌 (形声。从阜,百声。阜,土山,与地形有关。本义田间小路) 田间东西方向的小路。也泛指田间小路 为田开阡陌封疆,而赋税平。；组词：南陌(南方的田间小路)；陌路(田间的小路)；陌头(路旁) 泛指道路 素骥鸣广陌,慷慨送我行', '小学', '1'),
    ('降', 'jiàng', '8', '阝', '左右', NULL, '降 (会意) 同本义,与陟”相对 降,下也。--《说文》 是降丘宅土。--《书·禹贡》 复降在原。--《诗·大雅·公刘》 维岳降神。--《诗·大雅·崧高》 降西阶一等；组词：降阶(走下台阶)；降格(从上而至', '小学', '1'),
    ('限', 'xiàn', '8', '阝', '左右', NULL, '限 (形声。从阜,艮声。阜,土山,与山势有关。本义阻隔) 同本义 限,阻也。--《说文》 限之以大故。--《楚辞·怀沙》 牵牛织女遥相望,尔独何辜限河梁；组词：限绝(隔绝)；限隔(阻隔；隔绝)；限带(阻隔围绕)；限难(阻难) 限制；限定 是身如浮云,安可限南北', '小学', '1'),
    ('陕', 'shǎn', '8', '阝', '左右', NULL, '陕 古地名。战国陕邑,在今河南省陕县 自陕而东者,周公主之;自陕而西者,召公主之。--《公羊传》 中国陕西省的简称 陕 狭窄 是故溪陕者速涸', '小学', '1'),
    ('陡', 'dǒu', '9', '阝', '左右', NULL, '陡 (形声。从阜,走声。从阜”,表示与地形地势的高低上下有关。本义山势陡峭) 同本义 陡,峻立也。；组词：陡山；山陡路险；陡直(山势峻峭壁立)；陡崖(陡峭的山崖) 陡 顿时；突然 程度深,范围广 曾经消瘦,每遍犹闲,这番最陡', '小学', '1'),
    ('院', 'yuàn', '9', '阝', '左右', NULL, '院〈名〉 (形声。从阜,完声。阜”是土山,与土、建筑有关。本义庭院,院子。房屋围墙以内的空地)；组词：前院；后院；深宫大院 四周有墙垣围绕、自成部分的房屋 院东五里', '小学', '1'),
    ('除', 'chú', '9', '阝', '左右', NULL, '除〈名〉 (形声。从阜,余声。从阜”,表示与地形地势的高低上下有关。本义宫殿的台阶) 同本义 除,殿阶也。', '小学', '1'),
    ('陨', 'yǔn', '9', '阝', '左右', NULL, '陨 (形声。从阜,员声。阜”指土山,与高下”义有关。本义从高处掉下,坠落) 同本义 陨,从高下也。；组词：陨坠(坠落)；陨泗(流泪)；陨涕(落泪)；陨集(下落聚集) 丧失,失去 天诱其衷,成王陨命,穆公是以不 陨yǔn从高处掉', '小学', '1'),
    ('险', 'xiǎn', '9', '阝', '左右', NULL, '险 (形声。从阜,佥声。从阜”,与地势有关。本义地势高低悬殊,难以通过) 同本义 险,阻难也。；组词：险瘠(艰险贫瘠)；险易(艰险与平坦之地)；险戏(艰险) 地势险峻、危险 不登险峰,不识天地的辽阔', '小学', '1'),
    ('陪', 'péi', '10', '阝', '左右', NULL, '陪〈名〉 (形声。从阜,咅声。左耳旁为阜”的变形。阜,土山。本义重叠的土堆) 同本义 陪,重土也。；组词：陪贰(副手,助手)；陪推(以推官出任主考官的副官) 陪 〈动〉 伴随,陪伴 以无陪无卿', '小学', '1'),
    ('陵', 'líng', '10', '阝', '左右', NULL, '陵〈名〉 (形声。从阜,表示与地形地势的高低上下有关。夌声。本义大土山) 同本义 陵,大阜也。--说文》 如山如阜,如冈如陵。；组词：陵谷(山岭和深谷)；陵谷变迁(高山深谷变换位置', '小学', '1'),
    ('陶', 'táo', '10', '阝', '左右', NULL, '陶〈名〉 (形声。从阜,匋声,阜,土山。从阜”,与土有关。本义陶丘) 同本义。本为两重的山丘,后为地名专称。在今山东省定陶县。因陶丘在定陶,故定陶亦省称陶 陶,再成丘也。；组词：陶丘(重叠的山丘) 瓦器,陶器 器用陶匏', '小学', '1'),
    ('陷', 'xiàn', '10', '阝', '左右', NULL, '陷 (会意兼形声。从阜;从臽,臽亦声。据金文,象人掉进陷阱形。本义坠入,掉进) 同本义 陷,高下也。一曰陊也。；组词：陷狱(入狱)；沉陷(地面陷下去) 陷溺,淹没 陷没而死', '小学', '1'),
    ('隅', 'yú', '11', '阝', '左右', NULL, '隅〈名〉 (形声。从阜,禺声。阜”是土山,有土则可用于建筑,因而从阜”的字有的与建筑有关。本义山水弯曲边角处)；组词：山隅；隅椒(山角与山顶)；隅隈(角落和弯曲之处)；隅陬(角落) 角,角落 俟我于城隅', '小学', '1'),
    ('隆', 'lóng', '11', '阝', '左右', NULL, '隆〈形〉 (形声。从生,降省声。本义高) 丰大;高 隆,丰大也。--《说文》 宛中隆。--《尔雅·释山》。注山中央高。” 虽隆薛之城。--《战国策·齐策一》 隆准而龙颜；组词：隆穷(隆起的样子)；隆颓(高低不平的样子)；隆岳(高山)；隆恩(皇帝给予的特大的恩典) 国家逢勃发展；隆盛 陛下都洛阳,', '小学', '1'),
    ('随', 'suí', '11', '阝', '左右', NULL, '雜 (形声。从辵 同本义 雜,从也。--《说文》 雜无故也。--《易·杂卦》 雜山刊木循也。--《书·禹贡》 无纵诡雜。--《诗·大雅·民劳》 凡庭实雜入。--《仪礼·聘礼》；组词：随任(晚辈跟随做官的长辈在任所生活 随(雜)suí 1.跟着,沿着,顺着~着', '小学', '1'),
    ('隐', 'yǐn', '11', '阝', '左右', NULL, '隐 藏匿;隐蔽 隐,蔽也。--《说文》 隐,微也。--《尔雅》 隐五刃。--《国语·齐语》。注隐藏也。” 则事可以隐定。 隐忌雍蔽之人。--《荀子·致仕》。注隐,亦蔽也', '小学', '1'),
    ('隔', 'gé', '12', '阝', '左右', NULL, '隔 (形声。从阜,鬲声。从阜”,表示与地势高低上下有关。本义阻隔、遮断) 同本义 隔,障也。；组词：把一间房隔成两间；隔越(阻隔,隔绝)；隔碍(阻隔', '小学', '1'),
    ('隘', 'ài', '12', '阝', '左右', NULL, '隘 (形声。籀文从阜,益声。阜,土山,从阜”的字多与地势有关。本义狭窄;狭小) 同本义 隘,陋也。；组词：狭隘(宽度小；隘 险要的通道 隘ài 1.险要的地方要~', '小学', '1'),
    ('隙', 'xì', '12', '阝', '左右', NULL, '隙 (会意。从阜亦声。阜,土山,与土有关。本义墙上开裂的裂缝) 同本义。也泛指孔穴、空隙 隙,壁际孔也。；组词：裂隙；罅隙；隙穴(空隙与洞穴)；隙地(空地)；隙积(带有空隙垛体的体积) 空子 辅隙则国 隙、鄐xì 1.裂缝缝~', '小学', '1'),
    ('障', 'zhàng', '13', '阝', '左右', NULL, '障 (形声。从阜,章声。阜,土山。从阜,与高下、险阻有关。本义阻塞,阻隔) 同本义 障,隔也。；组词：障翼(遮挡掩护)；障距(阻隔,壅蔽)；障塞(阻塞不通)；障隔(阻隔) 阻挡；拒绝 令而不行,谓之障', '小学', '1'),
    ('隧', 'suì', '14', '阝', '左右', NULL, '隧 (形声。从阜,遂声。阜指土山,从阜的字有的与建筑有关。本义墓道,古墓中运送棺材到墓室的通道)；组词：隧户(墓道的门)；隧口(墓道的入口处) 地道 君何患焉?若阙地及泉,隧而相见,其谁曰不然?--《左传·隐公元年》 请隧弗', '小学', '1'),
    ('隶', 'lì', '8', '隶', '上下', NULL, '隶 (隶又樆尾会意。本义逮、捕、追及) 同本义 隶,及也,从又从尾省,又持尾者从后及之也。；组词：隶事(以故事相互隶属) 通离”', '小学', '1'),
    ('难', 'nán', '10', '隹', '左右', NULL, '难〈形〉 (形声。从隹声。从隹,与鸟有关。1本义支翅鸟。2假借为困难) 困难;艰难;不容易 非为织作迟,君家妇难为。；组词：难句(难得的佳句)；难老(难于衰老)；难行(难于施行；不容易走)；难治(不容易治理)；难航(不易舟行)；难期(难及,难于', '小学', '1'),
    ('雀', 'què', '11', '隹', '上下', NULL, '雀子 qiao 义同雀”。方言。用于家雀儿”、雀盲眼” qiao 雀盲眼 雀 〈名〉que (会意。从小隹。隹”是短尾鸟的泛称,上加三点表示小。本义麻雀)；组词：雀盲症；雀舌牙茶(嫩芽茶)；雀子(麻雀)；雀爪(像麻雀的爪形,为绘画法中的一种名称)；雀立(跳跃', '小学', '1'),
    ('雁', 'yàn', '12', '隹', NULL, NULL, '雁 (形声。从隹,从人,厂声,隹,短尾鸟。厂,石山之涯岩,也有表意作用。本义鸟名) 鸟类的一属,形状略像鹅,颈和翼较长,足和尾较短,羽毛淡紫褐色,善于游泳和飞行 雁,雁鸟也。；组词：雁塔题名(借指考中进士)；雁杳鱼沉(雁字鱼书', '小学', '1'),
    ('雄', 'xióng', '12', '隹', '左右', NULL, '雄 (形声。从隹,厷声。从隹,与鸟有关。本义公鸟) 同本义 雄,鸟父也。--《说文》 谁知鸟之雌雄。--《诗·小雅·正月》 雄雉于飞。--《诗·邶风·雄雉》 但见悲鸟号古木；组词：雄父(公鸡) 泛指动植物能产生精细胞的 雄狐绥绥', '小学', '1'),
    ('雅', 'yǎ', '12', '隹', '左右', NULL, '雅 (形声。从隹,牙声。从隹,与鸟有关。本义鸟名,乌鸦的一种。《说文》楚乌也。”) 正确;合乎规范 雅者,正也。言王政之所由废兴也。', '小学', '1'),
    ('集', 'jí', '12', '隹', '上下', NULL, '集 同本义 集,群鸟在木上也。--《说文》 集,会也。--《尔雅》 集于苞栩。--《诗·唐风·鸨羽》 黄鸟于飞,集于灌木。--《诗·周南·葛覃》；组词：集隼(栖息的隼鸟)；集凤(凤停于树) 引申为停留 人皆集于苑,己独集于枯', '小学', '1'),
    ('雇', 'gù', '12', '隹', NULL, NULL, '雇 (形声。从隹,表示与鸟类有关。户声。本义鸟名。即九雇,一种候鸟) 出钱让人给自己做事 雇,傭也。；组词：雇唤(雇请)；雇觅(雇佣)；雇募(出钱招募)；雇直(雇用的酬劳)；雇借(雇用)；雇船 受雇 展筑外城一十一里有余,役兵及', '小学', '1'),
    ('雌', 'cí', '14', '隹', '左右', NULL, '雌 (形声。从隹,此声。从隹”,表示与鸟有关。本义母鸟。引申为母的) 母鸟,能产卵的鸟 听凤皇之鸣,以别十二律,其雄鸣为六,雌鸣亦六。', '小学', '1'),
    ('雏', 'chú', '13', '隹', '左右', NULL, '雏〈名〉 (形声。从隹,刍声。本义小鸡) 同本义 雏,鸡子也。--《说文》 乃以雏尝黍。--《礼记·月令》。注新鸡也。” 有人于此,力不能胜一匹雏,则为无力人矣；组词：雏雉(幼雉)；雏禽(幼鸟)；雏莺(幼莺', '小学', '1'),
    ('雕', 'diāo', '16', '隹', '左右', NULL, '雕 (形声。从隹,周声。从隹”,表示与鸟类有关。本义大型猛禽。日间活动的大猛禽(鹰科)力大身大,形态优美,视力敏锐,飞行力强。也叫鹫”)；组词：雕悍(凶悍如雕)；雕鸷(凶猛如雕)；雕鹗(雕和鶚', '小学', '1'),
    ('雨', 'yǔ', '8', '雨', NULL, NULL, '雨 雨,从云层中降向地面的水 雨,濡物者也。--《管子·形势解》 积土成山,风雨兴焉。--《荀子》；组词：雨过天晴(像雨后晴空般的蓝色)；雨打梨花(喻指零乱不堪的狼狈情景)；雨打鸡(喻浑身湿淋淋的状态)；雨毛(细雨)；雨泣(泪', '小学', '1'),
    ('雪', 'xuě', '11', '雨', '上下', NULL, '雪 (会意。从雨,从彗,彗省声。本义空气中的水汽,冷却到摄氏零度以下时,就有部分凝结成冰晶,由空中降下,叫做雪)；组词：雪案萤窗(比喻勤学苦读)；雪里鸿(即雪泥鸿爪)；雪浪纸(一种有波浪形暗纹的宣纸) 雪 借喻 雪xuě 1.从天上落下的白', '小学', '1'),
    ('雳', 'lì', '12', '雨', '上下', NULL, NULL, '小学', '1'),
    ('零', 'líng', '13', '雨', '上下', NULL, '零〈动〉 (形声。从雨,令声。本义下雨。指落细雨) 同本义 零,余雨也。--《说文》 零雨其濛。--《诗·豳风·东山》；组词：零雨(徐徐飘落的雨) 引申为如雨一般地落下；降落 今当远离,临表涕零', '小学', '1'),
    ('雷', 'léi', '13', '雨', '上下', NULL, '雷 (象形。甲骨文,中间象闪电,圆圈和小点表示雷声。整个字形象雷声和闪电相伴而作。小篆变成了会意字,从雨,下象雷声相连之形,表示打雷下雨。本义云层放电时发出的巨响 )', '小学', '1'),
    ('雹', 'báo', '13', '雨', '上下', NULL, '雹 (形声。从雨,包声。本义冰雹) 同本义 阳之专气为雹。--《大戴礼记·曾子天圆》。注阳气在雨,温暖如汤,阴气薄之不相入,转而为雹,盖犹沸汤在闭器而沈于泉,则为冰也；组词：雹霰(冰雹夹杂雪珠而下) 雹 báo 冰雹', '小学', '1'),
    ('雾', 'wù', '13', '雨', '上下', NULL, '雾 接近地面的空气中的水蒸气 透明。如大雾;浓雾;雾合(如云雾般的聚合);雾析(雾气消散);雾岑(云雾缭绕的山峰);雾卷(雾气离散);雾杳(雾气深广的样子)', '小学', '1'),
    ('需', 'xū', '14', '雨', '上下', NULL, '需 (会意。从雨而声。需”指遇雨,停在那里等待。本义等待) 同本义 需,须也。--《易·需》。传需者,待也。” 聂许闻之需役。--《庄子·大宗师》 九江需次今几年,去去渌水依红莲；组词：需次(候补官员依照资历补缺)；需铨(等待铨选录用) 需要 零星需用亦在账房内开销', '小学', '1'),
    ('震', 'zhèn', '15', '雨', '上下', NULL, '震 疾雷(霹雳)使物体振动~夷伯之庙”。~霆。 雷烨烨~电。” 巨大的力等使物体剧烈颤动~撼。~荡。~颤。~响。~动。声~遐迩。 迅速或剧烈地颤动地~。身子不由得一~', '小学', '1'),
    ('霉', 'méi', '15', '雨', '上下', NULL, '霉 (形声。从雨,每声。本义物因生菌而质变) 同本义 器中,使发霉后晒干而成) 霉 真菌', '小学', '1'),
    ('霍', 'huò', '16', '雨', '上下', NULL, '霍 (会意。从雨。俗省作霍”。本义鸟疾飞时发出的声音◇描述门、水等响声)同本义 ? 磨刀霍霍向猪羊。；组词：霍落(象声词)；霍瀋(水流声)；霍嚓(象声词) 霍 引申为疾速 霍然病已', '小学', '1'),
    ('霎', 'shà', '16', '雨', '上下', NULL, '霎〈名〉 (从雨,妾声。本义小雨) 同本义 很短时间;瞬间 小街上霎时间沉寂起来。--《梁生宝买稻种》；组词：霎那间(片刻间)；霎时间(极短时间) 霎,雨声', '小学', '1'),
    ('霜', 'shuāng', '17', '雨', '上下', NULL, '霜 (形声。从雨,相声。本义在气温降到摄氏零度以下时,近地面空气中水汽的白色结晶) 同本义 霜,露所凝也。士气津液从地而生,薄以寒气则结为霜。；组词：霜雪(比喻高洁清白)；霜瓦(覆盖着白霜的瓦片)；霜旦(下霜的早晨)；霜甲(沾着霜的战甲)；霜衣(寒衣)；霜妃(指 霜sh', '小学', '1'),
    ('霞', 'xiá', '17', '雨', '上下', NULL, '霞 (形声。从雨,叚声。本义早晚的彩云) 同本义 霞,赤云气也。--《说文新附》 落霞与孤鹜齐飞,秋水共长天一色。--王勃《滕王阁序》 云霞明灭；组词：霞举飞升(道教指修行得道者可由云霞托拥,飞升天界；亦指腾云驾雾)；云霞(云彩)；霞彩(云霞的彩光) 霞 指像霞一样美丽的', '小学', '1'),
    ('露', 'lù', '21', '雨', '上下', NULL, '露〈动〉 lou 露lòu 1.显现,用于一些口语~脸。~马脚。 2.见luф。 露lù 1.显出,现出显~。暴~。~出。揭~。 2.在屋外,没有遮盖~天。~宿。~井。~矿', '小学', '1'),
    ('霸', 'bà', '21', '雨', '上下', NULL, '霸 (形声。从月。1本义阴历每月之初始见的月光。这个意义又写作魄”。2古代诸侯之长) 假借为伯。指古代诸侯联盟的盟主 霸者,伯也,行方伯之职。；组词：春秋五霸；霸王请客；强留(歇后语) 依仗权势或实力横行一方的人 薛家系金陵一霸', '小学', '1'),
    ('霹', 'pī', '21', '雨', '上下', NULL, NULL, '小学', '1'),
    ('青', 'qīng', '8', '青', '上下', NULL, '青〈形〉 (会意。从生,从丹。金文字形上面是个生”字;下面是丹”字,丹是井字之变。青”是汉字部首之一。本义蓝色)；组词：青磷(磷火', '小学', '1'),
    ('靖', 'jìng', '13', '青', '左右', NULL, '靖 (形声。从立,青声。本义立容安静) 同本义 靖,立竫也。--《说文》 自作不靖。--《书·盘庚》 靖共尔位。--《诗·小雅·小明》 虎靖衡门；组词：靖密(安静致密)；靖冥(宁静幽深)；靖默(沉静缄默)；靖重(安祥凝重) 安定；和平 靖,安也', '小学', '1'),
    ('静', 'jìng', '14', '青', '左右', NULL, '静 (形声。从青,争声。本义彩色分布适当) 安静;宁静 静言思之。--《诗·邶风·柏舟》 宵静女德,以伏蛊慝。--《国语·晋语》 本朝不静。--《吕氏春秋·音律》 静乃明几；组词：静雅(安静)；静鞭(帝王仪仗的一种,鞭形,振之作响,令人肃静', '小学', '1'),
    ('非', 'fēi', '8', '非', NULL, NULL, '非〈动〉 (指事。金文作兆”,像飞”字下面相背展开的双翅形,双翅相背,表示违背。本义违背;不合)；组词：非常异义(违背经文正义的异说)；非度(违反法度)；非道(不合道义)；非德(不合道德；违背道德)；非理(不合常理；违背情理', '小学', '1'),
    ('靠', 'kào', '15', '非', '上下', NULL, '靠〈动〉 (形声。从非,告声。从非”,表示相违背。本义相背) 相依 靠,相违也。--《说文》。段玉裁注今俗谓相依曰靠,古人谓相背曰靠。” 仰仗,依赖 不可只靠一言半句,海上单方；组词：靠傍(依靠,靠山)；靠托(倚仗；依靠)；靠天(不靠人力,依赖天命) 倚靠、依赖或凭靠 保持某种路线或方向等 信得过 接近', '小学', '1'),
    ('靡', 'mí', '19', '非', NULL, NULL, '靡 通湄”。水边,河岸 明月珠子,珃瓅江靡。--《史记·司马相如列传》 靡 浪费 而百姓靡于外。--《战国策·秦策》 国家靡敝。--《礼记·少仪》。疏谓财物糜散凋敝。” 不随俗靡；组词：奢靡；靡货(奢侈品)；靡靡(华丽而堂皇)；靡丽(奢华,美盛) 消失 喧杂杂鸟声多,静悄悄人事靡', '小学', '1'),
    ('面', 'miàn', '9', '面', NULL, NULL, '面 (象形。甲骨文字形,里面是目”字,外面表示面庞。面”,在古代指人的整个面部。脸”是魏晋时期才出现,而且只指两颊的上部,唐宋口语中才开始用同面”本义脸)；组词：面不厮睹(脸不对着看,表示生气)；颜面(脸面；脸部；体 面(靣)miàn 1.脸,头的前部~孔', '小学', '1'),
    ('革', 'gé', '9', '革', NULL, NULL, '革 (象形。金文字形,象被剖剥下来的兽皮。中间的圆形物,是被剥下的兽身皮,余下的部分是兽的头、身和尾。革”是汉字部首之一,从革”的字多与皮革有关。本义去毛的兽 皮)；组词：人造革；革带(皮带)；革笥(用皮作的甲胄)；革船(用皮革缝制的船) 用革制成的甲胄 革gé 1.去毛加工制成的兽皮制~厂', '小学', '1'),
    ('靴', 'xuē', '13', '革', '左右', NULL, '靴 (形声。从革,化声。革,皮革。本义高到踝骨以上的长筒鞋) 同本义 尝有人著靴骑驴,至兆门外。；组词：靴叶子(塞藏在靴筒内可折叠的票夹)；靴桶(靴靿', '小学', '1'),
    ('靶', 'bǎ', '13', '革', '左右', NULL, '靶 靶子 靶场 靶心 靶 bǎ 靶子。练习射击或射箭的目标。借指攻击的对象打~、成了别人的~子。 靶bà 1.辔首垂下部,即辔革。 2.缰绳。 3.器物上便于用手拿的部分', '小学', '1'),
    ('鞋', 'xié', '15', '革', '左右', NULL, '鞋 (形声。从革,圭声。皮革鞋的材料。圭、鞋”古音相近。本义鞋子) 同本义 韕,生革醍也。；组词：鞋扇(鞋面)；鞋脚(小妾第一次拜见长妻时所敬赠的见面礼亲手做的针线活；也指鞋袜)；鞋脚钱(跑腿钱)；雨鞋；皮鞋；布鞋；鞋', '小学', '1'),
    ('鞍', 'ān', '15', '革', '左右', NULL, '鞍 (形声。从革,安声。本义马鞍) 同本义,放在骡马等背上供人骑坐或载物的器具。 鞌,鞁具也。；组词：鞍桥(指马鞍', '小学', '1'),
    ('鞠', 'jū', '17', '革', '左右', NULL, '鞠 (形声。从革,匊声。从革”,表示与皮革有关。本义古时一种用来踢打玩耍的皮球。最早是结毛而成◇来用毛充填皮囊而成,宋代以后才有充气的皮球)；组词：鞠室(蹴鞠之所)；鞠场(毬场)；鞠戏(古代踢球的游戏)；鞠院(古球场,有围墙) 姓 鞠 弯曲,弯身 鞠jū 1.养育,抚', '小学', '1'),
    ('鞭', 'biān', '18', '革', '左右', NULL, '鞭 (形声。从革,便声。本义皮制的马鞭) 同本义 鞭,驱也。--《说文》 其左执鞭弭。--《国语·晋语》 虽鞭之长,不及马腹。--《左传·宣公十五年》 北市买长鞭；组词：鞭影(马鞭的影子◇以比喻警戒策勉)；鞭镫(马鞭与马镫)；鞭弭(马鞭和弓) 竹根 新鞭暗入庭,初长两三茎', '小学', '1'),
    ('韧', 'rèn', '7', '韦', '左右', NULL, '韧 (形声。从韦,刃声。韦,熟牛皮。本义柔软而结实,受外力作用时虽变形而不易折断) 同本义 故凡用兵者,攻坚则韧,乘暇则神。', '小学', '1'),
    ('韩', 'hán', '12', '韦', '左右', NULL, '韩 (形声。从韦,倝声。从韦”,取围绕,周匝之义。本义井垣) 井上的木栏 韩,井垣 也。--《说文》 古国名 中国周朝时的一个诸侯国,在今山西省韩城县 战国七雄之一◇为秦所灭', '小学', '1'),
    ('韭', 'jiǔ', '9', '韭', '上下', NULL, '韭 (象形。小篆,象韭菜长在地上的形状。本义韭菜) 同本义 韭,菜名,一种而久者,故谓之韭。', '小学', '1'),
    ('音', 'yīn', '9', '音', '上下', NULL, '音 (指事。从言含一。甲骨文言、音”互用,金文、小篆在言中加一横,表示所发之音。本义声音)；组词：音颡(喉咙)；音强(指声音的强弱', '小学', '1'),
    ('韵', 'yùn', '13', '音', '左右', NULL, '韵 (形声。从音,员(匀)声。本义和谐悦耳的声音) 同本义 余韵徐歇。--宋· 苏轼《石钟山记》 短笛无声,寒砧不韵。；组词：韵悠悠(声音悠扬) 归本于喉的音', '小学', '1'),
    ('页', 'yè', '6', '页', NULL, NULL, '页 (象形。小篆字形。上面是首”,下面是人”,头”的本字。页”是汉字的一个部首。从页”的字都与头面有关。1本义人头。2引申义书页) 书页 巌,枼也。；组词：页子(书页) 量词 一般指两面印刷的书籍、杂志、资料等印刷品的一张纸的一面', '小学', '1'),
    ('顶', 'dǐng', '8', '页', '左右', NULL, '顶 (形声。从页,丁声。从页”,表示与人头有关。本义人头的最上端) 同本义 顶颠也。--《说文》 过涉灭顶。--《易·大过》 肩高于顶。--《庄子·大宗师》。释文本作项', '小学', '1'),
    ('顷', 'qǐng', '8', '页', '左右', NULL, '顷 (会意。从匕,从页。匕有排列比较义,也有不正之义。页,头∠起来表示头偏。本义头不正)；组词：顷筐(倾斜口的竹筐', '小学', '1'),
    ('项', 'xiàng', '9', '页', '左右', NULL, '项 (形声。从页,工声。从页,与头有关。本义脖子的后部) 同本义 项,头后也。--《说文》 延颈秀项,皓质呈露。--曹植《洛神赋》 项背相望。--《后汉书·左雄传》；组词：项髻(挽发髻于颈后)；项窝(脖子后部的凹处) 泛指人颈 老魔将芭蕉扇插在后项衣领', '小学', '1'),
    ('顺', 'shùn', '9', '页', '左右', NULL, '顺 (会意。从页,从巛。页,头。本义沿着同一方向) 同本义 顺,循也。--《释名》 顺彼长道,屈此群丑。--《诗·鲁颂·泮水》 曹操自江陵将顺江东下。--《资治通鉴》 顺风而呼', '小学', '1'),
    ('须', 'xū', '9', '页', '左右', NULL, '须 (本字作须”◇来写成有魀,现在又简化为须”。象形。从页,从彡,页,头,彡,表毛饰。指人面上的毛。本义胡须)；组词：须眉浊物(指趋炎附势,丧失气节的男人)；虬须(卷曲的胡子)；银须；黄须；长须；软须；须麋(须眉) 野兽的魀', '小学', '1'),
    ('顽', 'wán', '10', '页', '左右', NULL, '顽 (形声。从页,元声。从页。本义难劈开的囫囵木头) 同本义 纤枝无萧洒,顽干空突兀。--唐·元稹《画松》 愚顽之人;顽固派 凶恶的人 岂惜战斗死,为君扫凶顽；组词：顽算(耍弄 顽wán 1.愚蠢无知愚~', '小学', '1'),
    ('顾', 'gù', '10', '页', '左右', NULL, '顾 (形声。从页,头。表示与头有关。雇声。本义回头看) 同本义 顾,环视也。--《说文》 顾见汉骑司马吕马童。--《史记·项羽本纪》 顾瞻周道。--《诗·桧风·匪风》 眷言顾之；组词：顾瞻(回首环视；眷顾；关照)；顾盼生辉(一 顾gù(顧) 1.回头看瞻前~后', '小学', '1'),
    ('顿', 'dùn', '10', '页', '左右', NULL, '顿 (形声。从页,屯声。从页”,表示与头有关。本义叩头,磕头) 同本义 顿,下首也。--《说文》 二曰顿首。--《周礼·大祝》。注拜头叩地也。”；组词：顿颡(屈膝下拜,以额叩地,多在请罪投降时用)；顿筑(以头或物撞地)；顿头(磕头)；顿膝(下跪) 用脚底或用脚使劲往下踩', '小学', '1'),
    ('颁', 'bān', '10', '页', '左右', NULL, '颁 (形声。从页,分声。页”本音念楸??,,意思是头,汉字部首之一。从页”的字多与头有关。)本义脑袋很大的样子) 鬓 颁,一曰鬓也。；组词：颁白(指鬓发花白', '小学', '1'),
    ('颂', 'sòng', '10', '页', '左右', NULL, '颂 (形声。从页,公声。从页”的字一般与头”有关。本义容貌,仪容) 同本义 颂,貌也。--《说文》 鲁徐生善为颂。--《汉书·儒林传》 庶考斯之颂仪。--《杨统碑》', '小学', '1'),
    ('预', 'yù', '10', '页', '左右', NULL, '预 (形声。从页, 予声。本义安乐。经典通用豫”字) 同本义 仙亭日登眺,虎丘时游预。--唐·白居易《和微之诗》 预先,事先。事先有准备。通豫” 预备走舸。(豫备轻快的小船。豫；组词：预虑(事先考虑)；预筮(预卜吉凶)；预借元宵(预先点放灯)；预日(提前一天)；预图(预先考虑)；预置(事前陈设) 预 参', '小学', '1'),
    ('颅', 'lú', '11', '页', '左右', NULL, '颅 (形声。从页,眗声。从页”,表示与头有关。本义头盖骨) 同本义 首身分离,暴骨草泽,头颅僵仆,相望于境。；组词：颅颡(额头) 颅盖 颅骨 颅腔 颅(颾)lú脑盖,也指头~骨', '小学', '1'),
    ('领', 'lǐng', '11', '页', '左右', NULL, '领 (形声。从页,令声。从页”,表示与头有关。本义脖子) 同本义 领,项也。--《说文》 领,项也。--《广雅·释亲》 领如蝤蛴。--《诗·卫风·硕人》 缅然引领南望；组词：领门儿(衣领；领口)；领鬃(鬃毛)；领颚(下巴)；领腰(脖子与腰部)；领圈(项圈) 领子,衣领 若挈裘领', '小学', '1'),
    ('颇', 'pō', '11', '页', '左右', NULL, '颇 (形声。从页,皮声。页,人头。本义头偏) 同本义 颇,头偏也。--《说文》 偏,倾斜,不平正 循绳墨而不颇。--《楚辞·离骚》 天不颇覆,地不偏载；组词：颇覆(偏至一侧,只覆盖一部分', '小学', '1'),
    ('颈', 'jǐng', '11', '页', NULL, NULL, '颈 (形声。从刀,巠声。从页”,表示与头有关。本义颈项) 同本义 颈,头茎也。--《说文》 小人莫不延颈举踵而愿曰。--《荀子·荣辱》 譬之是犹欲寿而歾颈也；组词：颈血(刎颈时流出的血', '小学', '1'),
    ('颊', 'jiá', '12', '页', '左右', NULL, '颊 (形声。从页,表示与头有关,夹声。本义面颊,脸的两侧从眼到下颌部分) 同本义 颊,面旁也。；组词：颊辅(面颊)；颊适(容貌调适,没有迎拒的表情)；颊车(下牙床骨；牙慧,蹈袭陈言)；颊颧(颊权', '小学', '1'),
    ('频', 'pín', '13', '页', '左右', NULL, '频 (会意。从步,从页。页人头。《说文》认为步是涉”的省略。人将要渡河,见水深,皱眉而止。本义皱眉)；组词：频蹙(皱眉蹙额,忧愁不乐的样子) 接近；临近 百姓流亡,频于涂炭', '小学', '1'),
    ('颓', 'tuí', '13', '页', '左右', NULL, '颓 (会意。从页,从秃。页,人头。本义头秃。原作穨”) 同本义。本作跕” 穨,秃貌。从秃,贵声。；组词：颓卒(委靡衰老的士卒)；颓思(颓丧的心意)；颓尔(厌伏不振貌)；颓堕委靡(体力精神衰退不振) 衰老 詈词', '小学', '1'),
    ('颖', 'yǐng', '13', '页', '左右', NULL, '颖 (形声。从禾,顷声。从禾与农作物有关。本义谷穗。亦称颖片”。指禾本科植物小穗基部的二枚苞片)；组词：颖果(干果的一种,种皮和果皮合而为一,里面只有一粒种子) 锥芒 乃颖脱而出,非特其末见而已', '小学', '1'),
    ('颗', 'kē', '14', '页', '左右', NULL, '颗 (形声。从页,果声。从页”,表示与头有关。本义小头) 引申指颗粒状物 颗,小头也。--《说文》 翠叶轻拢豆颗匀。--元好问《未开海棠》；组词：颗盐(俗称粒盐”', '小学', '1'),
    ('题', 'tí', '15', '页', '半包围', NULL, '题〈名〉 (形声。从页,是声。页,头。本义额头) 同本义 题,额也。--《说文》 雕题交趾。--《礼记·王制》 赤眉圆题。--《汉书·司马相如传》 夫加之以衡扼,齐之以月题；组词：题注(以头额撞击)；黑牛白题(黑牛白额) 物品的前端或顶端 又如榱题 题tí 1.〈古〉指额圜(圆)~', '小学', '1'),
    ('颜', 'yán', '15', '页', '左右', NULL, '颜 (形声。从页,彦声。从页,与头有关。本义印堂) 印堂,两眉之间 颜,眉目之间也。--《说文》。段玉裁注各本作眉目之间,浅人妄增字耳,今正。眉与眉之间不名颜。...颜为眉间；组词：颜角(额角)；颜题(古代头巾覆额面部分) 面容,脸色 有女同车,颜如舜华', '小学', '1'),
    ('额', 'é', '15', '页', '左右', NULL, '额 (形声。从页,客声。从页”,表示与头有关。本义额头,脑门) 同本义 頿,颡也。从页,各声。字亦作额。；组词：额颅(额头,前额)；额颅盖(前额)；额花(妇女用来贴在额上的以纸、绢、玉等做成的装饰花)；额黄(六朝至唐时的妇女,喜欢在', '小学', '1'),
    ('颠', 'diān', '16', '页', '左右', NULL, '颠 (形声。从页,真声。本义头顶) 同本义 颠,顶也。--《说文》 班序颠毛。--《国语·齐语》 诲于华颠胡老。--《后汉书·蔡邕传》；组词：颠毛(头发)；颠顶(头顶)；颠童(形容老人头发稀少) 泛指物体的顶部 如颠日(天日,天空的太阳)；颠杪(顶端末梢)；颠委', '小学', '1'),
    ('颤', 'chàn', '19', '页', '左右', NULL, '颤 颤抖,发抖 那手早颤起来,不敢打到第二下。--《范进中举》 又如发颤;颤悠(形容颤抖摇晃);颤悠悠(颤抖摇晃的样子) 物体振动 通惮”。惧怕,惊恐 越国之士,可谓颤矣；组词：发颤；颤悠(形容颤抖摇晃)；颤悠悠(颤抖摇晃的样子) 物体振动 通惮”', '小学', '1'),
    ('风', 'fēng', '4', '风', '半包围', NULL, '风 (形声。从虫,凡声。风动虫生”故字从虫”。本义空气流动的自然现象;尤指空气与地球表面平行的自然运动)', '小学', '1'),
    ('飒', 'sà', '9', '风', '左右', NULL, '飒 (形声。从风,立声。本义风声) 同本义 飒,翔风也。--《说文》 飒飒,风也。--《广雅》 风飒飒兮木萧萧。--《楚辞·九歌》 有风飒然而至。--宋玉《风赋》；组词：飒飖(大风)；飒飒；飒剌剌(形容风的声音) 飒 狂风拉物 梦初回,燕尾翻风,乱飒起湘帘翠', '小学', '1'),
    ('飘', 'piāo', '15', '风', '左右', NULL, '飘 (形声。从风,票声。本义旋风;暴风) 同本义 飘,回风也。...盘旋而起。--《说文》 少阳所至为飘风。--《素问·六元正纪论》 回风为飘。--《尔雅》 其为飘风；组词：飘风(旋风)；飘骤(疾风骤雨', '小学', '1'),
    ('飞', 'fēi', '3', '飞', NULL, NULL, '飞 (象形。小篆字形,下面象展开的双翼,上面象鸟首。本义鸟飞) 同本义 飛,鸟翥也。象张翼之形。；组词：飞凫(飞翔的凫鸟)；飞翰(飞翔的小鸟)；飞鸿(飞翔中的鸿雁) 泛指飞翔 飞龙在天', '小学', '1'),
    ('食', 'shí', '9', '食', '上下', NULL, '食 (会意。从饣皂,饣声。本义饭,饭食) 同本义 食,饣米也。--《说文》。按,六谷之饭曰食。 掌王之食饮。--《周礼·膳夫》。注饭也。” 治其粮与其食。--《周礼·廪人》；组词：食次(酒菜和点心之类；食品) 食sì 1.供养,拿东西给人吃~亲(亲父母)尽孝', '小学', '1'),
    ('餐', 'cān', '16', '飠', '上下', NULL, '餐 (形声。从食)声。本义吃) 同本义 餐,吞也。--《说文》 餐,食也。--《广雅》 相谒而餐。--《方言一》。注昼饭为餐,晚饭为飧。” 彼君子兮,不素餐兮；组词：进餐；会餐；野餐；就餐；聚餐；餐玉(吞食玉屑', '小学', '1'),
    ('饥', 'jī', '5', '饣', '左右', NULL, '饥 (形声。从食,幾声。本义荒年,五谷无收) 同本义 饑,谷不熟为饑。--《说文》 五谷不熟谓之饥。--《墨子·七患》 降丧饥馑。--《诗·小雅·雨无止》 齐尝大饥；组词：饥荒；饥馁(饥饿)；饥时得一口(紧要处得人救济,恩德深厚)；饥氓(逃荒的人)；饥岁(荒年) 饥(饑)jī 1.饿,跟"饱', '小学', '1'),
    ('饭', 'fàn', '7', '饣', '左右', NULL, '饭 (形声。从食,反声。本义吃饭) 同本义 饭,食也。--《说文》 饭飱者三饭也。--《礼记·玉藻》 呼饭饮之。--《汉书·朱买臣传》 饭疏食,饮水；组词：尚能饭否；饭粥(吃粥)；饭蔬(吃蔬菜) 给人喂饭或喂牲口 有一漂母见信饥,饭信', '小学', '1'),
    ('饮', 'yǐn', '7', '饣', '左右', NULL, '饮 (会意。甲骨文字形。右边是人形,左上边是人伸着舌头,左下边是酒坛(酉)。象人伸舌头向酒坛饮酒。小篆演变为飲”,隶书作饮”。本义喝)；组词：豪饮(放量饮酒)；饮水茹藻(喝泠水吃淡味食品', '小学', '1'),
    ('饰', 'shì', '8', '饣', NULL, NULL, '饰 (形声。从巾,从人,食声。人佩巾有装饰作用。本义刷拭) 同本义 饰,刷也。--《说文》。按,字亦作拭。 凡祭祀,饰其牛牲。--《周礼·地官·封人》 装饰;修饰 运而有光者；组词：饰车(有彩漆文饰之车', '小学', '1'),
    ('饱', 'bǎo', '8', '饣', '左右', NULL, '饱 (形声。从食,包声。本义吃足) 同本义。与饥”相对 饱,厌也。--《说文》 饱,满也。--《广雅》 既醉既饱。--《诗·小雅·执竞》 乐岁(丰年)终身饱；组词：酒足饭饱；饱食暖衣(吃得饱,穿得暖', '小学', '1'),
    ('饲', 'sì', '8', '饣', '左右', NULL, '饲 (形声。从食,司声。本义给人吃,喂食。本作食”) 同本义 屈指计归,张颐待饲。--《旧唐书》 饲养,给动物吃东西 饲 粮食 饲,粮也。--《集韵》 指饲料 饲sì喂食~料', '小学', '1');
INSERT IGNORE INTO edu_hanzi
    (hanzi_char, hanzi_pinyin, hanzi_strokes, hanzi_radical, hanzi_structure, hanzi_stroke_order, hanzi_meaning, hanzi_grade_level, hanzi_status)
VALUES
    ('饵', 'ěr', '9', '饣', '左右', NULL, '饵 (形声。从食,耳声。本义糕饼) 同本义 饵,粉饼也。--《说文》 鱼胶饵。--《考工记·弓人》；组词：果饵(果饼) 钓鱼用的鱼食 临川靡芳饵', '小学', '1'),
    ('饶', 'ráo', '9', '饣', '左右', NULL, '饶 (形声。从食,尧声。本义饱) 同本义 饶,饱也。--《说文》。 富裕,丰足 饶,多也。--《小尔雅》 饶,益也『时谣曰今年尚可后年饶。今苏俗买物请益谓之讨饶头；组词：饶裕(富足；富裕)；饶益(富裕)；饶美(丰美)；饶富(富饶,丰足)；饶益(富裕,使人受益)；饶余(富足有余)；饶足(生活', '小学', '1'),
    ('饺', 'jiǎo', '9', '饣', '左右', NULL, '饺〈名〉 (会意。从交,从食,交亦声。本义饺子,一种有馅的半圆形面食) 同本义 饺jiǎo面皮包馅做成半圆形的食品水~。蒸~子。锅贴~儿。', '小学', '1'),
    ('饼', 'bǐng', '9', '饣', '左右', NULL, '饼 (形声。从食,并声。本义古代面食的通称◇指扁圆形的面制食品) 同本义 形状像饼的东西 饼 做饼 饼铛 饼肥 饼干 饼子 用玉米面', '小学', '1'),
    ('饿', 'è', '10', '饣', '左右', NULL, '饿 (形声。从食,我声。本义饥之甚。按在古代,饥”与饿”存在着程度上的差别。饥”指一般的肚子饿;饿”是严重的饥饿)；组词：饿隶(饥饿的人；形容干瘠的样子)；饿损(饿坏)；饿杀鬼(方言', '小学', '1'),
    ('馁', 'něi', '10', '饣', '左右', NULL, '馁 (形声。从食,委声。本义饥饿) 同本义 餳,饥也。--《说文》 餳,饥也。--《广雅》 餳,饿也。--《三苍》 闵其粥糜冻餳之患。--《王纯碑》 今民馁而君逞欲；组词：馁殍(饿殍)；馁疾(饥饿病困)；馁毙(饿死)；馁馑(饿死)；馁士(饥饿之士)；馁腹(饿着肚子) 气馁；泄气,丧气 其为气', '小学', '1'),
    ('馅', 'xiàn', '11', '饣', '左右', NULL, '馅 面食、糕点里包的豆沙、糖、果仁、果肉或切碎的肉、菜等填料 被包裹的人或物 城外土馒头,馅草在城里。--宋·阮阅《诗话总龟》 比喻事情的底细,隐密 馅xiàn包在米粉', '小学', '1'),
    ('馆', 'guǎn', '11', '饣', '左右', NULL, '馆 (形声。从食,官声。馆”,供宿供膳,所以从食”。它的异体字作舘”,说明馆”属于房舍一类。本义高级客舍,宾馆)；组词：馆人(负责管理馆舍招待宾客的人)；馆客(接待宾客, 馆(舘)guǎn 1.接待宾客或旅客居住或食宿的房屋宾~', '小学', '1'),
    ('馋', 'chán', '12', '饣', NULL, NULL, '馋 (形声。从食)声。本义贪嘴,贪食) 同本义 贪图;贪羡 馋 chán 1看见好吃的食物就忍不住想吃;专爱吃好的~猫、~嘴。 2羡慕;贪。 【馋涎欲滴】馋得口水都快滴下来了', '小学', '1'),
    ('馍', 'mó', '13', '饣', '左右', NULL, '馍 饼类食品 馍(饝)mó面制食品的一种,一般也称"馒头"吃~ ~了。', '小学', '1'),
    ('馏', 'liú', '13', '饣', '左右', NULL, '馏 通过加热使物质分离或分解 馏 (形声。从食,留声。本义蒸饭) 把凉了的熟食品再蒸热 又如把凉饭馏一馏;馏馒头 馏liù将凉的熟食蒸热把包子~一~。 馏liú', '小学', '1'),
    ('馒', 'mán', '14', '饣', '左右', NULL, NULL, '小学', '1'),
    ('首', 'shǒu', '9', '首', '上下', NULL, '首 (象形。金文字形,上面是头发和头皮,用以表示头盖;下面是眼睛,用以代表面部。本义头)；组词：昂首；叩首；搔首；首功(以获敌首论功)；首虏(指斩获敌人的首级)；首枕其股(让死者的头枕在自己的腿上', '小学', '1'),
    ('香', 'xiāng', '9', '香', '上下', NULL, '香 (会意字。据小篆,从黍,从甘。黍”表谷物;甘”表香甜美好。本义五谷的香) 同本义 香,芳也。春秋传曰香稷馨香。”；组词：香鼠(一种皮毛名贵的貂)；香醪( 香xiāng 1.气味好闻,味道鲜美,跟"臭"相对~气', '小学', '1'),
    ('马', 'mǎ', '3', '马', NULL, NULL, '马 (象形。早期金文字形,象马眼、马鬃、马尾之形。马”是汉字的一个部首。本义家畜名) 单蹄食草大型哺乳动物 非固定特征(如体型较大,蹄子较大,颈稍呈弓形,头小,耳短) 千里马常有；组词：马伯乐(相马的人)；马首(属马的人)；马牌子(官府养马的伕役,他们身上都挂有腰牌作凭证)；马曹(官署名', '小学', '1'),
    ('驮', 'tuó', '6', '马', '左右', NULL, '驮 驮着货物的牲口或牲口所负载的货物 驮 tuo (形声。从马,大声。本作佗”。《说文》负何也。”本义骡马负载东西)；组词：驮绳(捆缚负载之物所用的绳子)；驮银；驮背', '小学', '1'),
    ('驯', 'xùn', '6', '马', '左右', NULL, '驯 (形声。从马,川声。本义马驯服) 同本义。亦指鸟兽驯服 驯,马训也。--《说文》 养野鸟兽使服谓之训。--《一切经音义》引《说文》 驯,性行调顺也。--《字林》 乃驾驯駮之驷；组词：驯兽(驯服之兽)；驯雉(驯顺的雉)；驯禽(驯养的禽鸟)；驯鹿(驯养的鹿)；驯乌(驯顺的乌鸦)；驯象(驯养的象) 泛指顺服', '小学', '1'),
    ('驰', 'chí', '6', '马', '左右', NULL, '驰 (形声。从马,也声。本义车马疾行) 同本义 驰,大驱也。--《说文》 弗驰弗驱。--《诗·唐风·山有枢》 车驰卒奔。--《左传·宣公十二年》 好驰马试剑；组词：驰车(古代战场上快速奔走的马车、轻车；驾车行走)；驰马(骑马快跑)；驰道(为帝王行驶马车所筑的马路)；驰报(疾驰传报)', '小学', '1'),
    ('驱', 'qū', '7', '马', '左右', NULL, '驱 (形声。从马,区声。本义奔驰;疾行) 同本义 驱,马驰也。--《说文》 驱,奔也。--《广雅·释室》 王用三驱。--《易·比》 驱马悠悠。--《诗·鄘风·载驰》 负而前驱；组词：驱弛；驰驱(骑马快跑)；长驱(迅速地向很远的目的地走)；驱侵(驱车侵袭)；驱劳(奔走辛劳)；驱突(驱驰奔跑)；驱骇(奔走', '小学', '1'),
    ('驳', 'bó', '7', '马', '左右', NULL, '驳 (会意。从马,从爻。甲骨文字形,右边是爻”),表示马的毛色混杂,左边是马”。本义马毛色不纯)；组词：驳骏(毛色斑驳的骏马)；乌驳马', '小学', '1'),
    ('驴', 'lǘ', '7', '马', '左右', NULL, '驴 (形声。从马,眗声。本义驴子。家畜名) 同本义 驴,似马,长耳。--《说文》。段注按,‘驴、骡、駃騠’太史公皆谓为匈奴奇畜,本中国所不用,故字皆不见经传,盖秦人造之耳；组词：驴头(驴马头', '小学', '1'),
    ('驶', 'shǐ', '8', '马', '左右', NULL, '驶 (形声。从马,史声。本义马行疾(快)) 同本义 又如甚驶(骑马跑得很快);驶马(疾驰之马) 疾速 欲缓携手期,流年一何驶!--王维《赠从弟司库员外絿》 又如驶流(湍急的水流)；组词：甚驶(骑马跑得很快)；驶马(疾驰之马) 疾速 欲缓携手期,流年一何驶!--王维《赠从弟司库员外絿》 又如驶流(湍急的水流', '小学', '1'),
    ('驹', 'jū', '8', '马', '左右', NULL, '驹 (形声。从马,句声。本义两岁以下的马) 同本义 驹,马二岁曰驹。--《说文》 老马反为驹。--《诗·角弓》 执驹。--《周礼·校人》 武帝谓之千里驹。--《汉书·刘德传》；组词：驹儿隙(白驹过隙', '小学', '1'),
    ('驻', 'zhù', '8', '马', '左右', NULL, '驻 (形声。从马,主声。本义马立止) 同本义 驻,马立也。--《说文》 驻驾。--《后汉书·灵帝纪》。注停车处也。” 驻,止也。--《苍颉篇》 怅容与而久驻兮；组词：驻马(驻鞍、驻勒', '小学', '1'),
    ('驼', 'tuó', '8', '马', '左右', NULL, '驼 (形声。从马,它声。从马,表示与马相类的动物。本义骆驼) 同本义。也单用作驼” 绒服);驼队(骆驼队) 成块的东西。也作坨” 你没看见,退油丹都使了两驼!', '小学', '1'),
    ('驾', 'jià', '8', '马', '上下', NULL, '驾 (形声。从马,加声。本义以轭加于马上) 同本义 驾,马在轭中。--《说文》 其乱至矣,不可以驾矣。--《吕氏春秋·贵因》 驾言兮焉求。--晋·陶渊明《归去来兮辞》；组词：驾御(驾驭', '小学', '1'),
    ('骂', 'mà', '9', '马', '上下', NULL, '骂 (形声。马声。吅,喧闹声。本义用粗语或恶意的话侮辱人) 同本义 对子骂父。--《世说新语·方正》 群怪聚骂。--唐·柳宗元《答韦中立论师道书》 窃骂侯生；组词：斥骂(责骂', '小学', '1'),
    ('骄', 'jiāo', '9', '马', '左右', NULL, '骄〈名〉 (形声。从马,乔声。本义六尺高的马) 同本义 骄,马高六尺为骄。《诗》曰我马唯骄。”', '小学', '1'),
    ('骆', 'luò', '9', '马', '左右', NULL, '骆 (形声。从马,各声。本义尾和鬣毛黑色的白马) 同本义 骆,马白色黑鬣尾也。--《说文》 白马朱鬣骆。--《广雅》 驾彼四骆。--《诗·小雅·四牡》 又 哔哔骆马。 驾白骆；组词：骆马(身白鬣黑的马) 骆驼 姓 骆 通络”', '小学', '1'),
    ('骇', 'hài', '9', '马', '左右', NULL, '骇 (形声。从马,亥声。本义马受惊) 同本义 骇,惊也。--《说文》 马方骇,鼓而惊之。--《汉书·梅乘传》；组词：骇驷(狂奔的驷马) 惊骇；惊诧；惊动 录事骇之', '小学', '1'),
    ('验', 'yàn', '10', '马', '左右', NULL, '验 (形声。从马。佥声。本义马名) 同本义 验,马名。--《说文》 证据;凭证 何以为验。--《史记·晋世家》 商君之法,舍人无验者坐之。--《史记·商君列传》；组词：验左(佐证；证据) 效验,灵验 自然之验', '小学', '1'),
    ('骏', 'jùn', '10', '马', '左右', NULL, '骏 (形声。本义良马) 同本义 骏,马之良材也。--《说文》 天子八骏。--《穆天子传》 天子赐许男骏马十六。 东市买骏马。--《乐府诗集·木兰诗》 将胡骏马而归；组词：骏骨(骏马的骨头', '小学', '1'),
    ('骑', 'qí', '11', '马', '左右', NULL, '骑 (形声。从马,奇声。本义跨马) 同本义 骑,跨马也。--《说文》 步骑罗些。--《楚辞·招魂》 脱身独骑。--《史记·项羽本纪》 其子好骑。--《淮南子·人间训》 骑大马；组词：骑射(骑马射箭)；骑寇(骑马入侵的贼寇,也是对北方游牧民族的鄙称)；骑猎(骑马打猎)；骑战(骑马打仗) 跨于物上或两边叫', '小学', '1'),
    ('骗', 'piàn', '12', '马', '左右', NULL, '骗 (形声。从马,扁声。本义跃而上马) 跃上马背而骑乘;骑。同騗” 骗,谓跃上马也。--《纂文》；组词：骗马(飞身上马；勾引、调戏妇女)；骗石(上马或登车用的垫脚石) 欺骗；哄劝 骗词(欺骗的话)；骗诈(欺骗讹诈) 超越；跨', '小学', '1'),
    ('骚', 'sāo', '12', '马', '左右', NULL, '骚 (形声。从马,蚤声。本义刷马) 同本义 骚,摩马。--《说文》。段玉裁注人曰搔,马曰骚,其意一也。摩马,如今人之刷马。” 骚动;动乱 骚,扰也。--《说文》。按,谓马扰动也；组词：骚害(骚扰,伤害)；骚骚(急迫的样子)；骚杀(下垂飘动的样子)；骚边(骚扰边境) 通搔”', '小学', '1'),
    ('骡', 'luó', '14', '马', '左右', NULL, '骡 动物名。骡子 驘,驴父马母。--《说文》 同驽驘与乘驵兮。--《楚辞·九叹·忧苦》。注马母騼父生子曰驘。”；组词：骡纲(驮载商旅货物结队而行的骡群)；骡驴(骡和驴,比喻平庸的人；兽名,俗称四不像”) 骡(驘)luó家畜', '小学', '1'),
    ('骤', 'zhòu', '17', '马', '左右', NULL, '骤 (形声。从马,聚声。本义马奔驰) 同本义 骤,马疾步也。--《说文》 车骤徒趋。--《周礼·大司马》 步及骤处兮。--《楚辞·招魂》。注走也。” 车驱而驺(骤)；组词：骤骥(疾驰的骏马) 使马奔驰 遇春骤马追到,便活擒于马上', '小学', '1'),
    ('骨', 'gǔ', '9', '骨', '半包围', NULL, '骨 表示声、形、动作。如骨都都(形容连续不断向外冒);骨骨农农(咕咕哝哝;嘀嘀咕咕);骨辘辘(象声词。滚动声) 骨嘟 只有秋公骨嘟了嘴,坐在一边', '小学', '1'),
    ('髓', 'suǐ', '21', '骨', NULL, NULL, '髓 (形声。从骨,随省声。本义骨中的凝脂) 同本义 比喻精华 植物茎的中心部分,由薄壁的细胞组成 髓suǐ 1. 2.像髓的东西脑~。', '小学', '1'),
    ('高', 'gāo', '10', '高', '上中下', NULL, '高 (象形。甲骨文字形,象楼台重叠之形『字部首之一。从高”的字多与高大或建筑有关。本义离地面远;从下向上距离大)；组词：高平( 高gāo 1.跟"低"相对 1由下至上距离大的,离地面远的~山', '小学', '1'),
    ('鬓', 'bìn', '20', '髟', '上下', NULL, '鬓 (形声。从髟),宾声。髟”,意思是头发长。髟”的字多与毛发有关。本义颊发。两颊两旁近耳的头发)；组词：鬓影(面颊两旁近耳的头发)；鬓发霜侵(鬓发花白) 鬓发 鬓角 鬓脚 鬓 bìn鬓角', '小学', '1'),
    ('鬼', 'guǐ', '9', '鬼', NULL, NULL, '鬼〈名〉 (象形。甲骨文字形,下面是个人”字,上面象一个可怕的脑袋(非田”字),是人们想象中的似人非人的怪物。鬼”是汉字部首之一,从鬼”的字大多与迷信、鬼神有关', '小学', '1'),
    ('魁', 'kuí', '13', '鬼', '半包围', NULL, '魁〈名〉 (形声。从斗,鬼声。斗”,长柄酒勺。本义汤勺,调羹。长柄大头) 同本义 魁,羹抖也。；组词：魁星(即奎宿”,原为二十八宿之一◇被古人附会为主管文运之神)；魁杓(指北斗星)；魁冈(河魁星与天冈星的合称 魁kuí 1', '小学', '1'),
    ('魂', 'hún', '13', '鬼', '左右', NULL, '魂 (形声。从鬼,云声。本义灵魂,古人想象的能离开人体而存在的精神) 同本义 魂,阳气也。；组词：魂识(心灵；魂灵)；魂气(灵魂)；魂骸(死者的灵魂和躯体)；魂质(灵魂和实体) 精神,神志 魂hún迷信说法,所谓"离开', '小学', '1'),
    ('魄', 'pò', '14', '鬼', '左右', NULL, '魄〈名〉 (形声。从鬼,白声。从鬼的字,常与灵魂、鬼怪有关。本义阴神,迷信的人指依附于人的身体而存在的精神)；组词：魂魄(迷信者指附在人体内可以游离出去的精神)；心魄(心灵)；丧魂落魄；魄荡魂飞(魄散魂消、魄散魂飞 魄pò 1.[魂魄]', '小学', '1'),
    ('魏', 'wèi', '17', '鬼', '左右', NULL, '魏 阙宫门的台观 乃县治象之法于象魏。--《周礼·太宰》 魏阙之高。--《淮南子·本经》 是以来仪集羽族于观魏。--汉·班固《典引》；组词：象魏(古代宫门外的阙门)；魏观(即魏阙、魏象) 古国名 西周时分封的诸侯国', '小学', '1'),
    ('魔', 'mó', '20', '鬼', NULL, NULL, '魔 (形声。从鬼,麻声。本义魔罗”的略称。佛教把一切扰乱身心、破坏行善、妨碍修行的心理活动均称为魔”)；组词：病魔；魔道(佛家语', '小学', '1'),
    ('鱼', 'yú', '8', '鱼', '上下', NULL, '鱼 (象形。甲骨文字形,象鱼形。本义一种水生脊椎动物) 完全水生并在水中呼吸的有头冷血脊椎动物,包括圆口类、板鳃类和具有软骨或硬骨骨骼的高等有鳃水生脊椎动物 鱼,水虫也。象形；组词：鱼鲩冠儿(女道士戴的鱼脑骨似的尖形帽子)；鱼鳞册(鱼鳞图册”的简称 鱼(魚)yú脊椎动物的一类,生活在水里', '小学', '1'),
    ('鲁', 'lǔ', '12', '鱼', '上下', NULL, '鲁 (会意。甲骨文从鱼,从口,口”象器形。整个字形象鱼在器皿之中。本义鱼味美,嘉) 同本义 (古鲁字)从曰,不从白,彝器每言鲁休”,纯鲁”,阮氏元云鲁本义盖为嘉,从鲁入口,嘉美也；组词：鲁拙(笨拙)；鲁人(鲁钝的人,愚钝的人) 莽撞,粗野 鲁 中国春秋时国名 鲁lǔ 1.笨,愚钝~钝', '小学', '1'),
    ('鲜', 'xiān', '14', '鱼', '左右', NULL, '鲜 (会意。从鱼,从羊。鱼”表类属,羊”表味美。本义鱼名。出貉国) 假借为鱻。鲜鱼,活鱼 冬宜鲜羽。；组词：鲜眼(像鱼那样的圆眼)；鱼鲜；海鲜；鲜脍(切细的鲜鱼肉)；鲜鳞(活鱼)；鲜羽(活鱼和活鸟) 鲜美的食物 惟君用鲜', '小学', '1'),
    ('鲤', 'lǐ', '15', '鱼', '左右', NULL, '鲤 鲤鱼 鲤,鱣也。从鱼,里声。--《说文》。按,鱣者大鱼,似鱯而短,即今之寻黄鱼,非鲤也。 必河之鲤。--《诗·陈风·衡门》 一种软鳍淡水鱼,素栖于池塘或缓流中', '小学', '1'),
    ('鲫', 'jì', '15', '鱼', '左右', NULL, '鲫 鲫鱼,亦称鲋” 鲫溜 鲫jì鲫鱼,体侧扁,背脊隆起,无触须,头小,背青褐色,腹银白色。生活在淡水中,供食用。变种"金鱼"供观赏。', '小学', '1'),
    ('鲸', 'jīng', '16', '鱼', '左右', NULL, '鲸 (形声。从鱼,京声。本义鲸鱼) 同本义 鳍,鼻孔在头的上部,用肺呼吸。肉可食,脂肪可制油,用于医药和其他工业。如蓝鲸;抹香鲸;长须鲸;鲸文(古代钱币名『时所铸,上面有鱼形', '小学', '1'),
    ('鳄', 'è', '17', '鱼', '左右', NULL, '鳄 鳄鱼 型河口湾鳄。)这些种类都会毫不迟疑地袭击人类。如鳄海(有鳄鱼出没的海滨) 钝吻鳄的俗称 宽吻鳄的俗称 鳄鱼扳手 鳄鱼夹 鳄 è一种凶猛的爬行动物。头部扁平,吻和尾很长', '小学', '1'),
    ('鳍', 'qí', '18', '鱼', '左右', NULL, '鳍 (形声。从鱼,耆声。本义鱼类和某些其他水生动物的类似翅或桨的附肢) 同本义 。如鳍棘(支撑鱼鳍薄膜的棘刺状硬骨。又叫鳍鬣) 鳍qí鱼类及其它水生脊椎动物的运动器官。一般由薄膜', '小学', '1'),
    ('鳖', 'biē', '19', '鱼', '上下', NULL, '鳖 (形声。从鱼,敝声。本义甲鱼,一种爬行动物,俗称团鱼”) 同本义 北各地,多栖于池沼、河沟、稻田中,肉味鲜美,一般认为是补品 江汉之鱼鳖鼋鼍为天下富。', '小学', '1'),
    ('鳞', 'lín', '20', '鱼', '左右', NULL, '鳞 (形声。从鱼,粦声。本义鱼甲) 同本义 鳞,鱼甲也。--《说文》 鳞罗布烈。--扬雄《羽猎赋》 鳞浪层层。--明·袁宏道《满井游记》 鳞爪飞扬；组词：鳞爪(喻残存、零碎或无足轻重之物)；鳞沦(水纹相次连接的样子)；鳞接(密接如鱼鳞)；鳞萃(荟萃如鱼鳞) 鳞片状物 鳞,甲', '小学', '1'),
    ('鸟', 'niǎo', '5', '鸟', NULL, NULL, '鸟 (象形。甲骨文字形,小篆作字形,都象鸟形。本义飞禽总名) 同本义 鸟,长尾禽总名也。象形。；组词：鸟篆(鸟形的篆书)；鸟卜(用鸟预卜年岁的吉凶)；鸟恨(鸟声含恨)；鸟乌(指乌鸦)；鸟迹(鸟的足迹)；鸟耘(群鸟耘田)；鸟', '小学', '1'),
    ('鸠', 'jiū', '7', '鸟', '左右', NULL, '鸠 (形声。从鸟,九声。本义鸟名) 鸠鸽科的鸟的泛称 鸠,鹘鸠也。--《说文》 维鸠居之。--《诗·召南·鹊巢》 维鸠盈之。 维鸠方之。 有雉鸠”(普通单称鸠)、祝鸠”、斑鸠”等', '小学', '1'),
    ('鸡', 'jī', '7', '鸟', '左右', NULL, '鸡 (形声。从鸟,奚声。本义家禽名。雄鸡可以报晓) 鸟纲雉科家禽,品种很多,喙短锐,有冠与肉髯,翅膀短,尤指普通家鸡(gallus gallus) 雞,知时兽也。从隹,奚声；组词：鸡男(雄鸡)；鸡坊(养鸡场)；鸡肤(鸡 鸡(雞、鷄)jī家禽之一', '小学', '1'),
    ('鸣', 'míng', '8', '鸟', '左右', NULL, '鸣 (会意。从口,从鸟。本义鸟叫) 同本义 鸣,鸟声也。--《说文》 鸟兽之音曰鸣。--《管辂别传》 鸣鹤在阴。--《易·中孚》 凤皇鸣矣。--《诗·大雅·卷阿》 鸡既鸣矣；组词：∶鸣管(鸟类的发声装置)；鸣凤(凤鸟鸣叫)；鸣雁(雁鸣叫) 泛指发声 震为鸣', '小学', '1'),
    ('鸥', 'ōu', '9', '鸟', '左右', NULL, '鸥 (形声。从鸟,区声。《说文》水鸮也。”本义水鸮) 水鸟名 惊起一滩鸥鹭。--宋·李清照《如梦令》 鸥鹭灭没。--宋·陆游《过小孤山大孤山》 鸥科(laridae)。此类鸟善飞', '小学', '1'),
    ('鸦', 'yā', '9', '鸟', '左右', NULL, '鸦 鸟名。各种大型的、通常是亮黑色的鸦属(corvus)成员 鸱鸦耆鼠。--《庄子·齐物论》；组词：鸦鹊无声(鸦雀无声)；鸦巢生凤(比喻平庸的家庭,出了优秀的子弟) 比喻黑色 鸦(鵶)yā 1.鸟名', '小学', '1'),
    ('鸭', 'yā', '10', '鸟', '左右', NULL, '鸭 水禽名。俗称鸭子 春江水暖鸭先知。--宋·苏轼《惠崇春江晚景》 属于鸭科的各种游禽,有短的颈和腿,躯体略扁形,喙多半宽而平,跗节前面覆有小盾片,雌雄各有不同羽衣', '小学', '1'),
    ('鸯', 'yāng', '10', '鸟', '上下', NULL, NULL, '小学', '1'),
    ('鸳', 'yuān', '10', '鸟', '上下', NULL, '鸳 (形声。从鸟,夗声。本义鸳鸯”的省称) 同本义 鸳,鸳鸯也。--《说文》 鹊好外反,鸳好内思。--陆佃《埤雅》 鸳鸯于飞。--《诗·小雅·鸳鸯》 鸳鸯,水鸟,凫类也；组词：鸳鸯瓦脊(互相成对的瓦建成的屋脊)；鸳鸯拐(两脚向左或向右踢起)；鸳鸯客(同在一桌饮酒、吃饭的两人) 比喻同事,同僚 芸', '小学', '1'),
    ('鸵', 'tuó', '10', '鸟', '左右', NULL, '鸵 鸵鸟 鸵鸟属(struthio)的一种善跑而不会飞的平胸鸟类,头和颈有茸毛,身上有软羽,大腿几乎赤裸,足有二趾,翼和尾有值钱的大羽,因此而为人饲养 鸵,大鸟,驼蹄,如汉元帝时', '小学', '1'),
    ('鸽', 'gē', '11', '鸟', '左右', NULL, '鸽 (形声。从鸟,合声。本义鸽子) 同本义 鸽,鸠属。从鸟,合声。形同勃姑。--《说文》；组词：野鸽；家鸽；信鸽；鸽绕(指禅通凌虚之境,有如鸽子绕行天空一般)；鸽竿(用鸽子作饵的捕鹰长竿) 鸽派 他们是国会中鸽派代表', '小学', '1'),
    ('鸿', 'hóng', '11', '鸟', '左右', NULL, '鸿 (形声。从鸟,江声。本义大雁) 同本义 鸿,鹄也。--《说文》 鸿渐于干。--《易·渐》 鸿雁于飞。--《诗·小雅·鸿雁》；组词：鸿冥(鸿鸟飞入苍冥)；鸿飞(鸿鸟飞翔)；鸿爪(比喻往事遗留的痕迹)；鸿渐(鸿鸟飞翔由低处逐渐进于高位', '小学', '1'),
    ('鹃', 'juān', '12', '鸟', '左右', NULL, '鹃 (形声。从鸟,胦声。本义鸟名,即杜鹃) 同本义 卵产于别的鸟巢中为它代孵,吃毛虫,是益鸟。如鹃血(传说杜鹃啼声凄苦,日夜不停,甚至口中流血。常比喻悲怨之深);鹃魂(借指冤魂)', '小学', '1'),
    ('鹅', 'é', '12', '鸟', '左右', NULL, '鹅 (形声。从鸟,我声。本义家禽名。头大,喙扁阔,颈长,尾短。羽毛为白色或黑色) 同本义。鸭科中一明确亚科的鸟 如 鹅骄(形容像鹅一般高傲); 鹅顶椅(靠背高的椅子)', '小学', '1'),
    ('鹉', 'wǔ', '13', '鸟', '左右', NULL, NULL, '小学', '1'),
    ('鹊', 'què', '13', '鸟', '左右', NULL, '鹊 (形声。从鸟,昔声。字本从隹,隶变作鸟。见《说文》舃”字注。本义喜鹊) 同本义 维鹊有巢,维鸠居之。；组词：红嘴蓝鹊；鹊音(好消息)；鹊报(喜鹊报喜', '小学', '1'),
    ('鹏', 'péng', '13', '鸟', '左右', NULL, '鹏 (形声。从鸟,朋声。鹏”是传说中最大的一种鸟,由鲲变化而成。本义大鹏) 同本义 朋,神鸟也。朋,古文凤。鹏,亦古文凤。；组词：鹏术(大鹏鸟高飞远举之术) 比喻前程远大 鹏图仍矫翼,熊轼且移轮', '小学', '1'),
    ('鹤', 'hè', '15', '鸟', '左右', NULL, '鹤 (形声。从鸟,隺声。本义鹤科各种类鸟的统称,皆为大型涉禽)同本义 ,羽毛更紧密,部分秃顶,嘴较钝并在近中央处有较大鼻孔,后趾向上抬起 鹤,似鹄长喙。；组词：鹤音(鹤鸣声)；鹤侣(鹤的伴侣)；鹤唳(鹤鸣)；鹤胫(鹤的小腿)；鹤语(鹤的叫声) 鹤 比喻白色 鹤hè鸟儿,要保护,禁', '小学', '1'),
    ('鹦', 'yīng', '16', '鸟', '左右', NULL, '鹦 鸟名,鹦鹉。俗称鹦哥” 雨细花零鹦语切,愁肠千万结。--前蜀·魏承班《谒金门》 又如鹦哥帻(色彩红似鹦哥嘴的头巾);鹦舌(鹦鹉之舌；组词：鹦哥帻(色彩红似鹦哥嘴的头巾)；鹦舌(鹦鹉之舌', '小学', '1'),
    ('鹰', 'yīng', '18', '鸟', NULL, NULL, '鹰 (形声。从鸟。本义鹰属的各种鸟) 同本义 种鸟 鹰翅疾如风,鹰爪利如锥。--唐·白居易《放鹰》；组词：鹰鸷(猛禽)；鹰人(驯鹰的人)；鹰师(训练老鹰的人)；鹰架(用竹木制成、用来提取重物的支架；亦指老鹰栖立的架子)；鹰拿燕', '小学', '1'),
    ('鹿', 'lù', '11', '鹿', NULL, NULL, '鹿〈名〉 (象形。甲骨文字形,象鹿的头角四足之形。本义鹿科动物的总称。种类很多,通常雄鹿有角)；组词：鹿中(刻成鹿形的木器)；鹿伏鹤行(形容小心警惕的样子) 比喻政权,爵位 秦失其鹿,天下共逐之', '小学', '1'),
    ('麦', 'mài', '7', '麦', '上下', NULL, '麦 (形声。甲骨文字形。从攵,来声。麦”是汉字的一个部首。本义麦子) 同本义 造纸原料 麦,芒谷。；组词：麦棱头(麦田的田畦)；麦人(麦心,麦核', '小学', '1'),
    ('麸', 'fū', '11', '麦', '左右', NULL, '麸 小麦皮屑 麸,小麦屑皮也。从麦,夫声。--《说文》 灭诸褊春夏用大麦麸,秋冬用小麦麸,筛粉,和酥傅之。--《本草纲目》 碎屑 麸皮 麸子 麸 fū小麦磨粉', '小学', '1'),
    ('麻', 'má', '11', '麻', NULL, NULL, '麻麻黑 麻麻亮 麻 (会意。从广,从林。广表示房子,林指削制的麻皮∠而表示在家里劈麻,进行剥制。本义麻类植物的总名。古代专指大麻)', '小学', '1'),
    ('黄', 'huáng', '11', '黄', NULL, NULL, '黄〈形〉 (象形。金文象蝗虫形。当是蝗”的本字。本义蝗虫) 黄色 黄,地之色也。--《说文》 黄为土色,位在中央。--《论衡·騰符》 黄中之色也；组词：黄烘烘(形容金黄色)；黄干干(形容很黄)；黄骝(黄红色的骏马)；黄盖(帝王车上所用的 黄huáng 1.像油菜花或向日葵', '小学', '1'),
    ('黍', 'shǔ', '12', '黍', '上下', NULL, '黍 (形声。从禾,雨省声。本义植物名。亦称稷”、糜子”) 古代专指一种子实叫黍子的一年生草本植物 黍,禾属而黏者也。；组词：黍离(喻覆没；衰败', '小学', '1'),
    ('黎', 'lí', '15', '黍', NULL, NULL, '黎〈形〉 (形声。从黍,利省声。本义黍胶。以黍米制成。古代用以粘履) 假借为齐”。众多,数目很多 民靡有黎,具祸以烬。；组词：黎庶(民众；百姓)；黎氓(黎民,人民)；黎甿(黎民,人民)；黎首(黎民·黔首) 颜色黑中带黄 土青曰黎', '小学', '1'),
    ('黑', 'hēi', '12', '黑', NULL, NULL, '黑〈形〉 (会意。小篆字形,上面是古囱”字,即烟囱;下面是炎”(火)字,表示焚烧出烟之盛∠起来表示烟火熏黑之意。本义黑色)；组词：黑气(黑色的水气)；黑章(黑色的花纹)；黑麻(黑色的胡麻)；黑眸(黑色的眸子)；黑斑(黑色的斑点)；黑参参(黑乎乎) 昏', '小学', '1'),
    ('黔', 'qián', '16', '黑', '左右', NULL, '黔〈形〉 (形声。从黑,今声。本义黑色) 同本义 黔,黎也。从黑,今声。秦谓民为黔首,谓黑发也,同谓之黎民。；组词：黔口(黑嘴巴)；黔黑(深黑)；黔丑(污黑丑陋) 黔 〈名〉 指百姓 贵州省的简称 姓 黔 〈动〉 晒黑,染黑,熏黑 乌不', '小学', '1'),
    ('默', 'mò', '16', '黑', '左右', NULL, '默 (形声。从犬,黑声。本义狗突然窜出追人) 闭口不说话 恭默思道。--《书·说命》 默而识之。--《论语》 或默或语。--《易·系辞》 三年默以思道；组词：默然不语(静默而不作声)；默默无言(沉默不语) 幽静 默顺风以偃仰兮', '小学', '1'),
    ('鼎', 'dǐng', '12', '鼎', NULL, NULL, '鼎 (象形。甲骨文字形,上面的部分象鼎的左右耳及鼎腹,下面象鼎足。本义古代烹煮用的器物)；组词：鼎峙(比喻三方并峙,如鼎之三足)；鼎铉(指鼎)；鼎鼐(鼎、鼐均为古代炊具,用来调和五味', '小学', '1'),
    ('鼓', 'gǔ', '13', '鼓', '左右', NULL, '鼓 (会意。甲骨文字形,左边是鼓的本字,右边是支”,表示手持棒槌击鼓。本义鼓,一种打击乐器)', '小学', '1'),
    ('鼠', 'shǔ', '13', '鼠', NULL, NULL, '鼠 (象形。头部象锐利的鼠牙,下象足、脊背、尾巴形。本义老鼠) 同本义 鼠,穴虫之总名也。；组词：鼠窜而狼忙(形容逃窜得匆忙狼狈)；鼠牙雀角(比喻强暴侵凌,引起争讼)；鼠盗蜂起(封建统治阶级对小股农民起义的污蔑)；鼠腹', '小学', '1'),
    ('鼻', 'bí', '14', '鼻', '上下', NULL, '鼻 (会意。从自,从畀),畀”又兼作声符。自”是鼻”的本字,作自己”用后,另造了鼻”字。畀”是给予、付与的意思∠起来表示一呼一吸,自相给予。本义鼻子)；组词：鼻哂(即嗤之以鼻', '小学', '1'),
    ('齐', 'qí', '6', '齐', NULL, NULL, '齐 (象形。甲骨文字形,象禾麦穗头长得平整的样子。小篆字形下面多了两条线,表示地面。本义禾麦吐穗上平整)；组词：齐均(整齐均匀)；齐贝(整齐的贝壳', '小学', '1'),
    ('齿', 'chǐ', '8', '齿', '上下', NULL, '齿 (象形。甲骨文,象嘴里的牙齿,象形字。战国文字在上面加了个声符止”,成为形声字。小篆同。本义牙)；组词：齿吻(齿及唇)；齿颊(牙齿与脸颊) 排列如齿状的物品 齿革羽毛', '小学', '1'),
    ('龄', 'líng', '13', '齿', '左右', NULL, '龄 (形声。从齿,令声。从牙齿来看年龄的长幼,所以从齿”。本义年龄) 同本义 通子垂九龄,但觅梨与栗。--陶渊明《责子》；组词：学龄儿童；高龄；龄齿(年龄) 年限；年数 暂游越万里,少别数千龄', '小学', '1'),
    ('龙', 'lóng', '5', '龙', NULL, NULL, '龙 (象形。甲骨文,象龙形。本义古代传说中一种有鳞有须能兴云作雨的神异动物) 同本义 龍,鳞虫之长。能幽能明,能细能巨,能短能长。春分而登天,秋分而潜渊。；组词：龙工(像龙一样熟悉水性之功', '小学', '1'),
    ('龟', 'guī', '7', '龟', '上下', NULL, '龟 (象形。甲骨文字形,头象它(蛇)头,左象足,右象甲壳,下面象尾。本义乌龟) 即金龟,亦称乌龟 黑色,雌体呈棕色,腹面略带黄色,均有暗褐色斑纹,四肢较扁平,有爪,指、趾间具全蹼；组词：龟文(龟背所现的纹理)；龟王(指龟类中的王者)；龟龙(古人以龟、龙、麟、凤合称四灵)；龟蛇(龟和蛇) 龟甲 龟(龜)jū', '小学', '1');
