-- ===========================================
-- 汉字库初始化数据（现代汉语常用字表一级 3500 字）
--
-- 由 tools/gen-hanzi-seed.py 生成，**不要手工编辑**：改数据请改脚本后重跑，
-- 否则脚本头里的来源与计数会和内容对不上。
--
-- 数据来源（公开数据集，文本逐字取自源，未人工转写）：
--   字表  现代汉语常用字表一级 3500 字  https://raw.githubusercontent.com/elephantnose/characters/master/3500%E5%B8%B8%E7%94%A8%E6%B1%89%E5%AD%97.txt
--   字段  chinese-xinhua 单字字典 word.json（拼音/笔画数/部首/中文释义）
--   结构  makemeahanzi IDS 部件分解（部首补缺 + 间架结构推导）
--
-- 口径：
--   * 幂等：INSERT IGNORE + uk_edu_hanzi_char，重复执行不产生重复行，
--     也不会覆盖已有数据（如 V1.10 里带笔顺的 12 个字）。
--   * 拼音已把源数据里的 U+0261（ɡ）修正为 g，否则会得到「dīnɡ」。
--   * 释义取本义段（90 字内，在「同本义/又如/古籍」处断句）+「又如」组词，
--     避开大段古籍引文（hanzi_meaning 是 VARCHAR(500)，不会写超）。
--   * 笔顺（hanzi_stroke_order）留空：公开数据集只给 SVG 笔顺轨迹、没有笔画名，
--     由老师按教材口径在「基础数据维护」页补。
--   * 结构只取可靠映射：含「？」或首字符为 ⿸/⿻ 的分解一律留空
--     （那两类会把独体字判成包围结构），详见脚本 IDS_STRUCTURE 注释。
--   * 学段固定「小学」（与 V1.10 种子、GradeLevels 的中文名口径一致）。
--
-- 规模：3496 行；缺字 4（啰囱屎铝）；释义不可用留空 21（俘品圾拭檬湘澈玛瞭窖芍蚯蜈蜘蝌豌雳霹馒鸯鹉）；
--       其余字段填充率见生成器输出。
-- 采集侧：本文件末尾同时种一条「汉字采集·常用字3500」采集任务，默认停用。
-- ===========================================



















-- ------------------------------------------------------------
-- 采集任务
-- ------------------------------------------------------------
-- 采集任务种子：默认停用（与成语/古诗同口径）。进「采集管理」设置 cron 后启用，
-- 或直接点「立即执行」从公开单字字典续采剩余汉字。
SELECT '汉字采集·常用字3500', 'HANZI', '{"charListUrl": "https://raw.githubusercontent.com/elephantnose/characters/master/3500%E5%B8%B8%E7%94%A8%E6%B1%89%E5%AD%97.txt", "gradeLevel": "小学", "idsUrl": "https://raw.githubusercontent.com/skishore/makemeahanzi/master/dictionary.txt", "limit": 500, "meaningMaxChars": 90, "url": "https://raw.githubusercontent.com/pwxcoo/chinese-xinhua/master/data/word.json"}', '语文', '小学', NULL, 3, 0, '汉字采集：公开单字字典（拼音/笔画/部首/中文释义）+ makemeahanzi IDS（结构），按 hanzi_char 去重，单次 500 字。默认停用：请在页面设置 cron 后启用，再点「立即执行」取数。'
WHERE NOT EXISTS (SELECT 1 FROM edu_collect_task WHERE collect_task_name = '汉字采集·常用字3500');
